INSERT INTO content_unit (slug, bucket, title, kind, sort_order) VALUES ('surah-al-fateha', 'Sessions', 'Surah Al-Fateha', 'book', 0) ON CONFLICT(slug) DO UPDATE SET bucket = excluded.bucket, title = excluded.title;
