INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'blurb', NULL, 'Surah Al-Fateha', 0, NULL, 'This book is a series of spoken sessions, delivered aloud to an audience and afterward set down as prose. It takes the opening chapter of the Quran, Surah Al-Fateha, and reads it slowly, almost phrase by phrase, drawing out of each word far more than a first hearing would suggest is there.', '', NULL, NULL, NULL, NULL, 'surah al fateha', 'this book is a series of spoken sessions delivered aloud to an audience and afterward set down as prose it takes the opening chapter of the quran surah al fateha and reads it slowly almost phrase by phrase drawing out of each word far more than a first hearing would suggest is there', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'introduction to the book', 'Introduction to the Book', 0, NULL, 'This book is a series of spoken sessions, delivered aloud to an audience and afterward set down as prose. It takes the opening chapter of the Quran, Surah Al-Fateha, and reads it slowly, almost phrase by phrase, drawing out of each word far more than a first hearing would suggest is there.', '', NULL, NULL, NULL, NULL, 'surah al fateha introduction to the book', 'this book is a series of spoken sessions delivered aloud to an audience and afterward set down as prose it takes the opening chapter of the quran surah al fateha and reads it slowly almost phrase by phrase drawing out of each word far more than a first hearing would suggest is there', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'introduction to the book', 'Introduction to the Book', 1, NULL, 'The series belongs to a larger conversation about knowing one''s master. It begins where the speaker says understanding must begin: not with theology but with friendship, and from friendship with love, because the name Allah reaches back to a root the sessions approach through the Quranic idea of love. From there the talks move outward — the linguistic meaning of Allah, of Rabb, of REHMA, and the striking image of the womb as the source of mercy. They ask what worship truly is, what it means that Allah is the Lord of all the worlds, and how being differs from attribute. They turn to the Day of Judgment, to the motives that move a person toward piety, and at last to the two petitions the surah teaches us to make: guidance to the straight path, and the steadfastness to remain upon it.', '', NULL, NULL, NULL, NULL, 'surah al fateha introduction to the book', 'the series belongs to a larger conversation about knowing ones master it begins where the speaker says understanding must begin not with theology but with friendship and from friendship with love because the name allah reaches back to a root the sessions approach through the quranic idea of love from there the talks move outward the linguistic meaning of allah of rabb of rehma and the striking image of the womb as the source of mercy they ask what worship truly is what it means that allah is the lord of all the worlds and how being differs from attribute they turn to the day of judgment to the motives that move a person toward piety and at last to the two petitions the surah teaches us to make guidance to the straight path and the steadfastness to remain upon it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'introduction to the book', 'Introduction to the Book', 2, NULL, 'The speaker is the author of these sessions; he gave them, and they carry his voice throughout. What the reader receives is a patient, close reading meant to make a familiar prayer new again.', '', NULL, NULL, NULL, NULL, 'surah al fateha introduction to the book', 'the speaker is the author of these sessions he gave them and they carry his voice throughout what the reader receives is a patient close reading meant to make a familiar prayer new again', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 0, NULL, 'The self has already received close attention, as has the theme of the Quran. What opens now is a new group of topics, gathered under the heading "Know Thy Master." Within this group, the focus falls on Allah — His various attributes, His relationship with us, and what He expects of us. The ground to be covered includes His proof of existence, His mercy, and the matter of fate and destiny.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the self has already received close attention as has the theme of the quran what opens now is a new group of topics gathered under the heading know thy master within this group the focus falls on allah his various attributes his relationship with us and what he expects of us the ground to be covered includes his proof of existence his mercy and the matter of fate and destiny', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 1, NULL, 'Any serious discussion of Allah begins with the word الہ, because the name Allah grows from the root الہ. To grasp the depth of that root, however, requires first understanding the Quranic concept of love: وِلع. The Islamic conception of love differs sharply from what Bollywood and Hollywood offer under that name. Understanding الہ therefore demands a clear account of love — and understanding love, in turn, demands starting with friendship. Love always begins there. No genuine love for a person takes root until friendship with that person has first been established. Real friendship, when it deepens, flowers into pure love.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'any serious discussion of allah begins with the word اله because the name allah grows from the root اله to grasp the depth of that root however requires first understanding the quranic concept of love ولع the islamic conception of love differs sharply from what bollywood and hollywood offer under that name understanding اله therefore demands a clear account of love and understanding love in turn demands starting with friendship love always begins there no genuine love for a person takes root until friendship with that person has first been established real friendship when it deepens flowers into pure love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 2, NULL, 'Lust needs no friendship. This is why one-night stands and casual, meaningless sex spread through society — they are rooted in lust, in the base animal instinct of قُوَّۃُ الشَّھْوَانِیَّۃِ studied earlier. Animals do not need to become friends before they mate. Love, however, always begins in the sentiments of friendship. The Arabs say that whenever the plant of love grows, it grows in the soil of friendship. Before turning to the term الہ, then, the various shades of love must first be laid out — and before that, the different types of friendship the Quran speaks of must be understood.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'lust needs no friendship this is why one night stands and casual meaningless sex spread through society they are rooted in lust in the base animal instinct of قوه الشهوانيه studied earlier animals do not need to become friends before they mate love however always begins in the sentiments of friendship the arabs say that whenever the plant of love grows it grows in the soil of friendship before turning to the term اله then the various shades of love must first be laid out and before that the different types of friendship the quran speaks of must be understood', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 3, NULL, 'In the present age, genuine friendship has grown extraordinarily difficult to form. The world has moved toward virtual connections — the kind sustained by social media platforms and electronic devices. Human beings have grown so enslaved to their phones that a simple fifteen-minute conversation between two people, uninterrupted by the pull of a screen, has become nearly impossible. The more tightly connected people have become to their devices, the more disconnected they have become from one another. Real, unhurried conversation between human beings has all but vanished. Instead of owning these devices, people are owned by them. The device has become the master; its user, the obedient slave. The moment it sounds, everything else is dropped and attention snaps to the screen in total submission — سمعنا و اطعنا — I hear and I obey.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'in the present age genuine friendship has grown extraordinarily difficult to form the world has moved toward virtual connections the kind sustained by social media platforms and electronic devices human beings have grown so enslaved to their phones that a simple fifteen minute conversation between two people uninterrupted by the pull of a screen has become nearly impossible the more tightly connected people have become to their devices the more disconnected they have become from one another real unhurried conversation between human beings has all but vanished instead of owning these devices people are owned by them the device has become the master its user the obedient slave the moment it sounds everything else is dropped and attention snaps to the screen in total submission سمعنا و اطعنا i hear and i obey', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 4, NULL, 'The parallel is almost comic. People with asthma reach for an inhaler every few minutes because they cannot breathe. Phones have made us the same way. The frantic search for a signal — the inability to simply sit without one — has become its own kind of respiratory crisis. Not long ago, I was telling my daughter about the کعبۃ and about going for عمرۃ. I asked her what she would like to know about Mecca. The first thing she asked was whether they have Wi-Fi there. As sad as it is, that is what life has been reduced to.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the parallel is almost comic people with asthma reach for an inhaler every few minutes because they cannot breathe phones have made us the same way the frantic search for a signal the inability to simply sit without one has become its own kind of respiratory crisis not long ago i was telling my daughter about the كعبه and about going for عمره i asked her what she would like to know about mecca the first thing she asked was whether they have wi fi there as sad as it is that is what life has been reduced to', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 5, NULL, 'The Quranic concept of friendship, then, deserves serious attention — and the angle from which it is approached makes all the difference. There are two ways to enter this subject:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the quranic concept of friendship then deserves serious attention and the angle from which it is approached makes all the difference there are two ways to enter this subject', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 6, NULL, 'The first is to ask what kind of friends one should look for. The second is to ask what kind of friend one should be to others.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the first is to ask what kind of friends one should look for the second is to ask what kind of friend one should be to others', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 7, NULL, 'The first approach is the selfish one, and the Quran does not endorse it. The correct approach is the second: not what kind of friends to have, but what kind of friend to be. The distinction matters enormously. When a person becomes the right kind of friend to others, Allah places the right kind of people in that person''s path.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the first approach is the selfish one and the quran does not endorse it the correct approach is the second not what kind of friends to have but what kind of friend to be the distinction matters enormously when a person becomes the right kind of friend to others allah places the right kind of people in that persons path', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 8, NULL, 'The Quran uses at least ten distinct words for friendship, each carrying its own shade of meaning and appearing in contexts that illuminate something specific about the relationship. Moving through some of these terms reveals what Allah is teaching about the different kinds of bonds between people.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the quran uses at least ten distinct words for friendship each carrying its own shade of meaning and appearing in contexts that illuminate something specific about the relationship moving through some of these terms reveals what allah is teaching about the different kinds of bonds between people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 10, NULL, 'The first term is ولی. It derives from مُوَالات, which conveys the idea of protection. A ولی is someone who manages another''s affairs and always has that person''s back. When trouble strikes — of any kind — the ولی is there to guard and shield. He does not merely help after the fact; he handles the situation entirely. A ولی therefore denotes not friendship in a general sense but something stronger: a dependable ally who can be counted on both to pull someone out of a crisis and to keep that person from falling into one in the first place. One of the names of Allah is الولی.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the first term is ولي it derives from موالات which conveys the idea of protection a ولي is someone who manages anothers affairs and always has that persons back when trouble strikes of any kind the ولي is there to guard and shield he does not merely help after the fact he handles the situation entirely a ولي therefore denotes not friendship in a general sense but something stronger a dependable ally who can be counted on both to pull someone out of a crisis and to keep that person from falling into one in the first place one of the names of allah is الولي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 11, NULL, 'Al-Baqarah: 257ٱللَّهُ وَلِىُّ ٱلَّذِينَ آمَنُوا۟ يُخْرِجُهُم مِّنَ ٱلظُّلُمَتِ إِلَى ٱلنُّورِ ۖ وَٱلَّذِينَ كَفَرُوٓا۟ أَوْلِيَآؤُهُمُ ٱلطَّغُوتُ يُخْرِجُونَهُم مِّنَ ٱلنُّورِ إِلَى ٱلظُّلُمَتِ ۗ أُو۟لَٓئِكَ أَصْحَبُ ٱلنَّارِ ۖ هُمْ فِيهَا خَلِدُونَAllah is the Wali of those who believe. He brings them out from darkness into light. But as for those who disbelieve, their Auliya are Taghut , they bring them out from light into darkness. Those are the dwellers of the Fire, and they will abide therein forever.', '', NULL, 'Al-Baqarah: 257', NULL, NULL, 'surah al fateha quranic friendship', 'al baqarah 257الله ولي الذين امنوا يخرجهم من الظلمت الي النور والذين كفروا اولياوهم الطغوت يخرجونهم من النور الي الظلمت اوليك اصحب النار هم فيها خلدونallah is the wali of those who believe he brings them out from darkness into light but as for those who disbelieve their auliya are taghut they bring them out from light into darkness those are the dwellers of the fire and they will abide therein forever', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 12, NULL, 'Al-Baqarah: 257أللَّهُ وَلِىُّ ٱلَّذِينَ آمَنُوا۟', '', 'أللَّهُ وَلِىُّ ٱلَّذِينَ آمَنُوا۟', 'Al-Baqarah: 257', 2, 257, 'surah al fateha quranic friendship', 'al baqarah 257الله ولي الذين امنوا', 'الله ولي الذين امنوا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 13, NULL, 'Allah is the ولی of those who believe. He is a protective friend to those who believe.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'allah is the ولي of those who believe he is a protective friend to those who believe', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 14, NULL, 'A related form of this same root is the word مولا. It describes that same caring, concerned friend who also holds the ability to protect — specifically when he takes on a position of authority. The idea is this: when someone is entirely convinced that another person truly cares for them, truly has their best interests at heart, and they simply submit to that person''s authority and heed what he says, that person will protect them from trouble, or help them out of it when they are already in it. The one who stands in that position of authority over their affairs is called مولا.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'a related form of this same root is the word مولا it describes that same caring concerned friend who also holds the ability to protect specifically when he takes on a position of authority the idea is this when someone is entirely convinced that another person truly cares for them truly has their best interests at heart and they simply submit to that persons authority and heed what he says that person will protect them from trouble or help them out of it when they are already in it the one who stands in that position of authority over their affairs is called مولا', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 15, NULL, 'This is precisely why the phrase مَوْلَانَا عَلِیٌّ carries such weight. The word مولا is used there not only to affirm his authority over our affairs, but, more fundamentally, to establish that he is our caring and concerned friend — the one who is there to protect us, whose teachings exist to protect us and keep us from harm. He is someone who always has our back; his teachings always have our best interests at heart. By placing the word مولا before his name, the testimony affirms his ولایۃ — his genuine, sincere love, care, and concern for us — precisely in order to protect us.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'this is precisely why the phrase مولانا علي carries such weight the word مولا is used there not only to affirm his authority over our affairs but more fundamentally to establish that he is our caring and concerned friend the one who is there to protect us whose teachings exist to protect us and keep us from harm he is someone who always has our back his teachings always have our best interests at heart by placing the word مولا before his name the testimony affirms his ولايه his genuine sincere love care and concern for us precisely in order to protect us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 16, NULL, 'There is a striking adjective the Quran applies to this word ولی in one verse. That word is حمیم. Allah says:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'there is a striking adjective the quran applies to this word ولي in one verse that word is حميم allah says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 17, NULL, 'Fussilat: 34وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ۚ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَوَةٌۭ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌۭ', '', 'وَلَا تَسْتَوِى ٱلْحَسَنَةُ وَلَا ٱلسَّيِّئَةُ ۚ ٱدْفَعْ بِٱلَّتِى هِىَ أَحْسَنُ فَإِذَا ٱلَّذِى بَيْنَكَ وَبَيْنَهُۥ عَدَوَةٌۭ كَأَنَّهُۥ وَلِىٌّ حَمِيمٌۭ', 'Fussilat: 34', 41, 34, 'surah al fateha quranic friendship', 'fussilat 34ولا تستوي الحسنه ولا السييه ادفع بالتي هي احسن فاذا الذي بينك وبينه عدوه كانه ولي حميم', 'ولا تستوي الحسنه ولا السييه ادفع بالتي هي احسن فاذا الذي بينك وبينه عدوه كانه ولي حميم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 18, NULL, 'The good deed and the evil deed cannot be equal. Repel with one which is better, then verily! he, between whom and you there was enmity, as though he was a close friend.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the good deed and the evil deed cannot be equal repel with one which is better then verily he between whom and you there was enmity as though he was a close friend', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 19, NULL, 'Even where there is open hostility between two people — where one speaks with the most aggressive language imaginable while the other remains kind and respectful — Allah''s instruction is to respond as a protective friend would: to continue behaving as though genuinely looking out for that person, to answer in the gentlest way possible. Then Allah adds the adjective حمیم.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'even where there is open hostility between two people where one speaks with the most aggressive language imaginable while the other remains kind and respectful allahs instruction is to respond as a protective friend would to continue behaving as though genuinely looking out for that person to answer in the gentlest way possible then allah adds the adjective حميم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 20, NULL, 'The word حمیم comes from حُمَّۃ, which means fever — a word Arabic uses for intense heat. In this verse, that heat describes the intimacy of friendship. حمیم is the closeness in which there is a warmth between two people, a felt nearness. The heat here is not romantic; it is the inner warmth that rises when someone''s company moves a person deeply. A حمیم is a friend whose presence leaves one feeling all warm and fuzzy inside. And the Quran places this standard precisely where it is hardest to meet: toward someone who is being aggressive, someone acting with the coarsest hostility imaginable. If that is how a believer must conduct himself toward an enemy, the standard toward a fellow believer is higher still. SubhanAllah — the Quran sets a breathtaking measure for what it means to live as a believer. And yet Islam is called a violent religion.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the word حميم comes from حمه which means fever a word arabic uses for intense heat in this verse that heat describes the intimacy of friendship حميم is the closeness in which there is a warmth between two people a felt nearness the heat here is not romantic it is the inner warmth that rises when someones company moves a person deeply a حميم is a friend whose presence leaves one feeling all warm and fuzzy inside and the quran places this standard precisely where it is hardest to meet toward someone who is being aggressive someone acting with the coarsest hostility imaginable if that is how a believer must conduct himself toward an enemy the standard toward a fellow believer is higher still subhanallah the quran sets a breathtaking measure for what it means to live as a believer and yet islam is called a violent religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 21, NULL, 'That, then, is the first kind of friend a believer is called to be toward another — ولی حمیم.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'that then is the first kind of friend a believer is called to be toward another ولي حميم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 23, NULL, 'The second kind of friend is a صدیق. The word صدیق comes from صدق, which carries two meanings: sincerity and truthfulness. A صدیق, then, is a friend of the most genuine and truthful kind. To be a صدیق to someone means the friendship rests on nothing but a sincere desire to be with that person. It is not friendship pursued because the association raises one''s standing at school or at work, or because others will think more highly of the company one keeps, or because the friend is wealthy and some advantage might follow, or because the friend is learned and proximity to learning lends an air of scholarship. A صدیق carries no hidden agenda. The friendship has no strings attached. It is grounded in who the person is — not in what they own, not in the status they hold, not in anything artificial or superficial. Strip all of that away, and what remains — a bond that endures for its own sake alone — is صدقۃ. That friend will be there, no matter what.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the second kind of friend is a صديق the word صديق comes from صدق which carries two meanings sincerity and truthfulness a صديق then is a friend of the most genuine and truthful kind to be a صديق to someone means the friendship rests on nothing but a sincere desire to be with that person it is not friendship pursued because the association raises ones standing at school or at work or because others will think more highly of the company one keeps or because the friend is wealthy and some advantage might follow or because the friend is learned and proximity to learning lends an air of scholarship a صديق carries no hidden agenda the friendship has no strings attached it is grounded in who the person is not in what they own not in the status they hold not in anything artificial or superficial strip all of that away and what remains a bond that endures for its own sake alone is صدقه that friend will be there no matter what', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 24, NULL, 'Being a صدیق is not easy. Having a صدیق is even more difficult. Casual acquaintances — people to chat with, to gossip with — are easy to find. But a صدیق is something rarer and harder, because this is the kind of friend who never gives up, no matter how many times one fails.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'being a صديق is not easy having a صديق is even more difficult casual acquaintances people to chat with to gossip with are easy to find but a صديق is something rarer and harder because this is the kind of friend who never gives up no matter how many times one fails', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 25, NULL, 'That is the first nuance: sincerity. The second is truthfulness. The Arabs have a saying:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'that is the first nuance sincerity the second is truthfulness the arabs have a saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 26, NULL, 'Sayingالصَّدِیقُکَ مَن صَدَقَت', '', 'الصَّدِیقُکَ مَن صَدَقَت', 'Saying', NULL, NULL, 'surah al fateha quranic friendship', 'sayingالصديقك من صدقت', 'الصديقك من صدقت');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 27, NULL, 'A friend is someone who is true — genuinely honest — not merely someone who is friendly. When things are going wrong, a true friend speaks plainly: "Listen! I care about you. I don''t want you to do this, because I believe it will hurt you. Stop." A صدیق is not there simply to look good or to supply the warm, comfortable feeling one craves. He tells the harsh truth — the truth one does not want to hear. That is precisely why the word grows from the root صدق, meaning truthfulness.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'a friend is someone who is true genuinely honest not merely someone who is friendly when things are going wrong a true friend speaks plainly listen i care about you i dont want you to do this because i believe it will hurt you stop a صديق is not there simply to look good or to supply the warm comfortable feeling one craves he tells the harsh truth the truth one does not want to hear that is precisely why the word grows from the root صدق meaning truthfulness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 28, NULL, 'A صدیق to someone, then, is a person who will be genuinely honest with his friend whatever the cost. A صدیق does not simply agree, knowing full well that the path his friend has chosen leads to ruin. He is not paralyzed by the fear that speaking plainly will shatter the friendship. I don''t want to say anything because he might get really upset — that is not a صدیق. It is precisely that silence, that comfortable evasion, that costs people their friendships. Honesty is offered, and it is not wanted. But the صدیق does not surrender to that. He does not give up on his friend, however painful the truth becomes.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'a صديق to someone then is a person who will be genuinely honest with his friend whatever the cost a صديق does not simply agree knowing full well that the path his friend has chosen leads to ruin he is not paralyzed by the fear that speaking plainly will shatter the friendship i dont want to say anything because he might get really upset that is not a صديق it is precisely that silence that comfortable evasion that costs people their friendships honesty is offered and it is not wanted but the صديق does not surrender to that he does not give up on his friend however painful the truth becomes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 29, NULL, 'There is a striking dimension to this word when it appears in the Quran. Allah describes certain people who, on the Day of Judgment, find themselves on the wrong side — people heading toward the Fire. He records what they say, in verses 26:99–101:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'there is a striking dimension to this word when it appears in the quran allah describes certain people who on the day of judgment find themselves on the wrong side people heading toward the fire he records what they say in verses 26 99 101', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 30, NULL, 'Ash-Shu''ara: 99وَمَآ أَضَلَّنَآ إِلَّا ٱلْمُجْرِمُونَ', '', 'وَمَآ أَضَلَّنَآ إِلَّا ٱلْمُجْرِمُونَ', 'Ash-Shu''ara: 99', 26, 99, 'surah al fateha quranic friendship', 'ash shuara 99وما اضلنا الا المجرمون', 'وما اضلنا الا المجرمون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 31, NULL, 'Their claim is that the fault is not theirs. They did not end up in this state through their own choices alone — these criminals, these evil people, misled them. The blame, they insist, belongs elsewhere. And Allah then records more of what they say:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'their claim is that the fault is not theirs they did not end up in this state through their own choices alone these criminals these evil people misled them the blame they insist belongs elsewhere and allah then records more of what they say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 32, NULL, 'Ash-Shu''ara: 100فَمَا لَنَا مِن شَفِعِينَ', '', 'فَمَا لَنَا مِن شَفِعِينَ', 'Ash-Shu''ara: 100', 26, 100, 'surah al fateha quranic friendship', 'ash shuara 100فما لنا من شفعين', 'فما لنا من شفعين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 33, NULL, 'There is nobody on our side to plead for us. شافعی is one who cares for a person and, when trouble comes, steps forward and says: he is good, he is fine, he is with me. The way a teacher might walk into the principal''s office and say: this is a good student — do not worry about him, I will answer for him. That is شفاعۃ. These people are saying that on this day, no one has come to speak for them. No one is standing in their corner. And then they say:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'there is nobody on our side to plead for us شافعي is one who cares for a person and when trouble comes steps forward and says he is good he is fine he is with me the way a teacher might walk into the principals office and say this is a good student do not worry about him i will answer for him that is شفاعه these people are saying that on this day no one has come to speak for them no one is standing in their corner and then they say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 34, NULL, 'Ash-Shu''ara: 101وَلَا صَدِيقٍ حَمِيمٍۢ', '', 'وَلَا صَدِيقٍ حَمِيمٍۢ', 'Ash-Shu''ara: 101', 26, 101, 'surah al fateha quranic friendship', 'ash shuara 101ولا صديق حميم', 'ولا صديق حميم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 35, NULL, 'This is the only place in the Quran where صدیق is used in quite this direct way. They are saying that today they have no true, sincere, close friends — no one near to them who loves them. SubhanAllah. And in recording that complaint, Allah reminds us that the opposite is equally true. If those on the wrong side of Judgment Day are lamenting the absence of close friends, then those on the right side — the people of paradise — will indeed have a close friend standing with them. Who is that ultimate صَدِيقٍ حَمِيمٍۢ available to the believers? The شفاعۃ of Rasul Allah ﷺ, inshaAllah. May Allah qualify all of us for that.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'this is the only place in the quran where صديق is used in quite this direct way they are saying that today they have no true sincere close friends no one near to them who loves them subhanallah and in recording that complaint allah reminds us that the opposite is equally true if those on the wrong side of judgment day are lamenting the absence of close friends then those on the right side the people of paradise will indeed have a close friend standing with them who is that ultimate صديق حميم available to the believers the شفاعه of rasul allah ﷺ inshaallah may allah qualify all of us for that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 36, NULL, 'What those disbelievers — those destined for the Fire — lament on that day is the absence of a صَدِيقٍ. In the world, whenever someone offered them sincere and honest counsel, they turned it away. They mocked. They ridiculed. They broke off those very friendships. And now, at the hour of judgment, they wish they had kept those صَدِيقٍ close. A صَدِيقٍ is worth holding — however harsh and painful their truth may be — because they prove to be the truest of friends in the آخرۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'what those disbelievers those destined for the fire lament on that day is the absence of a صديق in the world whenever someone offered them sincere and honest counsel they turned it away they mocked they ridiculed they broke off those very friendships and now at the hour of judgment they wish they had kept those صديق close a صديق is worth holding however harsh and painful their truth may be because they prove to be the truest of friends in the اخره', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 38, NULL, 'صاحب is among the most comprehensive words the Quran uses for a friend. It can describe the most casual of acquaintances — someone seated beside a traveler on a train or a bus for a few hours. At that minimal level of contact, the word already applies.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'صاحب is among the most comprehensive words the quran uses for a friend it can describe the most casual of acquaintances someone seated beside a traveler on a train or a bus for a few hours at that minimal level of contact the word already applies', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 39, NULL, 'Yet a lifetime companion is equally a صاحب. What the term holds in common across all its uses is a single quality: a صاحب always means well. They want something good for the one they accompany. When trouble comes, they help to whatever degree they can. And the better they know a person, the greater their capacity to help — and the deeper their concern. This is why one of the names Allah gives to Rasul Allah ﷺ in the Quran is صاحب:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'yet a lifetime companion is equally a صاحب what the term holds in common across all its uses is a single quality a صاحب always means well they want something good for the one they accompany when trouble comes they help to whatever degree they can and the better they know a person the greater their capacity to help and the deeper their concern this is why one of the names allah gives to rasul allah ﷺ in the quran is صاحب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 40, NULL, 'At-Takwir: 22وَمَا صَاحِبُكُم بِمَجْنُونٍۢAnd your companion is not a madman;', '', NULL, 'At-Takwir: 22', NULL, NULL, 'surah al fateha quranic friendship', 'at takwir 22وما صاحبكم بمجنونand your companion is not a madman', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 41, NULL, 'The people of Mecca were calling him insane. And what does Allah say in response? Not: my Messenger is not insane. Not: my Prophet is not insane. Not: the one I love most is not insane. Not: the greatest man ever to walk this earth is not insane. He says: YOUR companion — the one who genuinely cares for you — is not insane. That is the بلاغۃ of the Quran: a precision of eloquence that the ancient Arabs felt immediately, and that could entirely transform a person''s way of thinking.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the people of mecca were calling him insane and what does allah say in response not my messenger is not insane not my prophet is not insane not the one i love most is not insane not the greatest man ever to walk this earth is not insane he says your companion the one who genuinely cares for you is not insane that is the بلاغه of the quran a precision of eloquence that the ancient arabs felt immediately and that could entirely transform a persons way of thinking', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 42, NULL, 'What صحبۃ calls for is to be أصحاب to one another. And صحبۃ is something that is also gradually disappearing at a societal level. It operates at the level of the individual, but it also works at the level of society. The companions during the time of the Prophet ﷺ celebrated ordinariness; they did not construct artificial standards of living. Today, that spirit of صحبۃ has largely vanished. A person who buys an expensive phone and makes sure to display it at every opportunity — "Oh, you still have an iPhone 6? Poor guy! It''s okay, don''t worry — I''ll still hang out with you, but only when we''re alone" — has entirely lost the sense of what a صاحب is. A صاحب is always concerned about a companion''s feelings. They do not go out of their way to show off in order to make a companion feel inferior.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'what صحبه calls for is to be اصحاب to one another and صحبه is something that is also gradually disappearing at a societal level it operates at the level of the individual but it also works at the level of society the companions during the time of the prophet ﷺ celebrated ordinariness they did not construct artificial standards of living today that spirit of صحبه has largely vanished a person who buys an expensive phone and makes sure to display it at every opportunity oh you still have an iphone 6 poor guy its okay dont worry ill still hang out with you but only when were alone has entirely lost the sense of what a صاحب is a صاحب is always concerned about a companions feelings they do not go out of their way to show off in order to make a companion feel inferior', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 43, NULL, 'The performance of false modesty — "Oh, this old thing? It''s Gucci. It was on sale for eight hundred" — offered to someone who could never afford it, reveals an absence of that concern. صاحب is a delicate term in that respect.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the performance of false modesty oh this old thing its gucci it was on sale for eight hundred offered to someone who could never afford it reveals an absence of that concern صاحب is a delicate term in that respect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 45, NULL, 'The next word the Quran uses for a friend is ولیجۃ. It appears only once in the Quran. ولیجۃ comes from the verb وَلَجَ، یَلِجُو, which in Arabic means to penetrate deeply. Allah says:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the next word the quran uses for a friend is وليجه it appears only once in the quran وليجه comes from the verb ولج يلجو which in arabic means to penetrate deeply allah says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 46, NULL, 'Saba: 2يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا', '', 'يَعْلَمُ مَا يَلِجُ فِى ٱلْأَرْضِ وَمَا يَخْرُجُ مِنْهَا', 'Saba: 2', 34, 2, 'surah al fateha quranic friendship', 'saba 2يعلم ما يلج في الارض وما يخرج منها', 'يعلم ما يلج في الارض وما يخرج منها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 47, NULL, 'Allah knows what goes into the earth and what comes out of it.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'allah knows what goes into the earth and what comes out of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 48, NULL, 'ولیجۃ, then, is a friend who is deeply immersed in one''s affairs — someone who knows everything happening in a person''s life and is actively present in it, day to day. The trust extended to a ولیجۃ is total. This is not merely someone to confide in; it is someone genuinely involved in the workings of one''s life.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'وليجه then is a friend who is deeply immersed in ones affairs someone who knows everything happening in a persons life and is actively present in it day to day the trust extended to a وليجه is total this is not merely someone to confide in it is someone genuinely involved in the workings of ones life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 49, NULL, 'This is not an ordinary friendship built on pleasantries and occasional contact. It is close, rare, and exceptionally demanding of trust. A ولیجۃ is the friend trusted with a bank account, with children, with all one''s gold and jewelry, without a second thought — trusted in any affair of life. The signed blank check handed over before a long journey, I''m traveling for a couple of months; please write out these checks for my bills, with no anxiety whatsoever: that is the trust of a ولیجۃ. Such friendship is extremely rare today.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'this is not an ordinary friendship built on pleasantries and occasional contact it is close rare and exceptionally demanding of trust a وليجه is the friend trusted with a bank account with children with all ones gold and jewelry without a second thought trusted in any affair of life the signed blank check handed over before a long journey im traveling for a couple of months please write out these checks for my bills with no anxiety whatsoever that is the trust of a وليجه such friendship is extremely rare today', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 50, NULL, 'What makes the Quranic use of this word remarkable is that Allah limits the ولیجۃ relationship to three specific entities. He says:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'what makes the quranic use of this word remarkable is that allah limits the وليجه relationship to three specific entities he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 51, NULL, 'At-Tawbah: 16أَمْ حَسِبْتُمْ أَن تُتْرَكُوا۟ وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَهَدُوا۟ مِنكُمْ وَلَمْ يَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلْمُؤْمِنِينَ وَلِيجَةًۭ ۚ وَٱللَّهُ خَبِيرٌۢ بِمَا تَعْمَلُونَDo you think that you shall be left alone while Allah has not yet tested those among you who have striven hard and fought and have not taken Walijah besides Allah and His Messenger, and the believers. Allah is Well-Acquainted with what you do.', '', NULL, 'At-Tawbah: 16', NULL, NULL, 'surah al fateha quranic friendship', 'at tawbah 16ام حسبتم ان تتركوا ولما يعلم الله الذين جهدوا منكم ولم يتخذوا من دون الله ولا رسوله ولا المومنين وليجه والله خبير بما تعملونdo you think that you shall be left alone while allah has not yet tested those among you who have striven hard and fought and have not taken walijah besides allah and his messenger and the believers allah is well acquainted with what you do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 52, NULL, 'Do you think that you shall be left alone', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'do you think that you shall be left alone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 53, NULL, 'Ali ''Imran: 142وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَهَدُوا۟ مِنكُمْ', '', 'وَلَمَّا يَعْلَمِ ٱللَّهُ ٱلَّذِينَ جَهَدُوا۟ مِنكُمْ', 'Ali ''Imran: 142', 3, 142, 'surah al fateha quranic friendship', 'ali imran 142ولما يعلم الله الذين جهدوا منكم', 'ولما يعلم الله الذين جهدوا منكم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 54, NULL, 'while Allah has not yet tested those among you who have striven hard and fought', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'while allah has not yet tested those among you who have striven hard and fought', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 55, NULL, 'At-Tawbah: 16وَلَمْ يَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلْمُؤْمِنِينَ وَلِيجَةًۭ ۚ', '', 'وَلَمْ يَتَّخِذُوا۟ مِن دُونِ ٱللَّهِ وَلَا رَسُولِهِۦ وَلَا ٱلْمُؤْمِنِينَ وَلِيجَةًۭ ۚ', 'At-Tawbah: 16', 9, 16, 'surah al fateha quranic friendship', 'at tawbah 16ولم يتخذوا من دون الله ولا رسوله ولا المومنين وليجه', 'ولم يتخذوا من دون الله ولا رسوله ولا المومنين وليجه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 56, NULL, 'and have not taken ولیجۃ besides Allah and His Messenger, and the believers', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'and have not taken وليجه besides allah and his messenger and the believers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 57, NULL, 'In this verse, Allah calls Himself a ولیج to us. Life brings trials, and through those trials He tests how deeply His love and His commands have penetrated the most personal corners of a person''s life. What is His role in family decisions? What is His role in financial decisions, in business decisions, in choices of career and education? Is He a ولیج — genuinely intimate in those innermost concerns?', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'in this verse allah calls himself a وليج to us life brings trials and through those trials he tests how deeply his love and his commands have penetrated the most personal corners of a persons life what is his role in family decisions what is his role in financial decisions in business decisions in choices of career and education is he a وليج genuinely intimate in those innermost concerns', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 58, NULL, 'The verse places the Messenger ﷺ alongside Allah. The question, then, is how much a person consults the Prophet''s legacy in the most personal matters of life. When trouble comes, how much does one turn to his life and سیرۃ, to his example? When difficulties arise — with people, with Islam — how much does one seek the counsel of Rasul Allah ﷺ? How deeply is he involved in the most intimate matters?', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the verse places the messenger ﷺ alongside allah the question then is how much a person consults the prophets legacy in the most personal matters of life when trouble comes how much does one turn to his life and سيره to his example when difficulties arise with people with islam how much does one seek the counsel of rasul allah ﷺ how deeply is he involved in the most intimate matters', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 59, NULL, 'When the سنۃ of the Messenger comes up today, what tends to be celebrated and emphasized are its most outward forms — the سنۃ of prayer, of keeping a beard, of being the first to say سلام, the mannerisms and etiquette passed down from our beloved Messenger ﷺ. In many respects, these remain public forms. The most intimate decisions are another matter entirely: whether to enter a particular financial transaction, what clothes to buy, whether to go along with friends to a certain gathering, whether to go along at all. The question is whether the Messenger has been brought into those decisions — the ones touching the most private affairs. How far does the سنۃ reach in such matters? Even in the ways one speaks, in one''s أخلاق, in the way one carries oneself — does the Prophet''s example give guidance?', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'when the سنه of the messenger comes up today what tends to be celebrated and emphasized are its most outward forms the سنه of prayer of keeping a beard of being the first to say سلام the mannerisms and etiquette passed down from our beloved messenger ﷺ in many respects these remain public forms the most intimate decisions are another matter entirely whether to enter a particular financial transaction what clothes to buy whether to go along with friends to a certain gathering whether to go along at all the question is whether the messenger has been brought into those decisions the ones touching the most private affairs how far does the سنه reach in such matters even in the ways one speaks in ones اخلاق in the way one carries oneself does the prophets example give guidance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 60, NULL, 'The way people speak to one another today is deeply disordered. There is no سنۃ in it. There is no respect for elders. There is no humility in mutual conversation. The Quran tells us that speech should be respectful and kind — that of a ولی حمیم, a protective and warm friend — even toward enemies. And yet even among believers, the moment any disagreement arises, the instinct is to bludgeon with evidence, to demean, to mock. Even in something as simple as a conversation, there is a profound departure from the سنۃ of Rasul Allah ﷺ.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the way people speak to one another today is deeply disordered there is no سنه in it there is no respect for elders there is no humility in mutual conversation the quran tells us that speech should be respectful and kind that of a ولي حميم a protective and warm friend even toward enemies and yet even among believers the moment any disagreement arises the instinct is to bludgeon with evidence to demean to mock even in something as simple as a conversation there is a profound departure from the سنه of rasul allah ﷺ', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 61, NULL, 'The verse then includes the believers — ٱلْمُؤْمِنِينَ — within this same relationship of ولیجۃ. When Allah is truly intimate in one''s life, and when the teachings of the Prophet are truly intimate in one''s personal affairs, Allah gives the gift of the finest kind of believers — those who can be trusted to the very depths of one''s personal life. What a gift that is, especially now, when trust has all but disappeared. People cannot be trusted in the workplace; even those called closest friends carry doubt. That kind of trust is gone from life. And Allah (Azza Wa Jal) gives, in this verse, the secret to finding it again: when He is admitted into the intimate life, and when the Messenger ﷺ is admitted alongside Him, the gift that follows is true believers worthy of exactly that trust. SubhanAllah!', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the verse then includes the believers المومنين within this same relationship of وليجه when allah is truly intimate in ones life and when the teachings of the prophet are truly intimate in ones personal affairs allah gives the gift of the finest kind of believers those who can be trusted to the very depths of ones personal life what a gift that is especially now when trust has all but disappeared people cannot be trusted in the workplace even those called closest friends carry doubt that kind of trust is gone from life and allah azza wa jal gives in this verse the secret to finding it again when he is admitted into the intimate life and when the messenger ﷺ is admitted alongside him the gift that follows is true believers worthy of exactly that trust subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 63, NULL, 'Another kind of friendship is بِطانۃ, which comes from the root بطن — the Arabic word for stomach. A بِطانۃ is a friend who guards secrets. Where the ولیجۃ is immersed in all of one''s personal matters, the بِطانۃ protects what is entrusted to them. A secret shared with a بِطانۃ goes with them to their grave.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'another kind of friendship is بطانه which comes from the root بطن the arabic word for stomach a بطانه is a friend who guards secrets where the وليجه is immersed in all of ones personal matters the بطانه protects what is entrusted to them a secret shared with a بطانه goes with them to their grave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 64, NULL, 'The contrast is painfully familiar. A secret is shared — "please don''t tell anyone" — and the friend puts the call on speaker and begins texting it along. "Hey, listen up! Don''t tell anyone, but —" That is not a بِطانۃ. There are people with what one might call a very light stomach — they simply cannot hold a secret.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the contrast is painfully familiar a secret is shared please dont tell anyone and the friend puts the call on speaker and begins texting it along hey listen up dont tell anyone but that is not a بطانه there are people with what one might call a very light stomach they simply cannot hold a secret', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 65, NULL, 'The verse in which this word appears in the Quran is:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the verse in which this word appears in the quran is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 66, NULL, 'Ali ''Imran: 118يَٓأَيُّهَا ٱلَّذِينَ آمَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةًۭ مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًۭا وَدُّوا۟ مَا عَنِتُّمْ قَدْ بَدَتِ ٱلْبَغْضَآءُ مِنْ أَفْوَهِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْآيَتِ ۖ إِن كُنتُمْ تَعْقِلُونَO you who believe!', '', 'يَٓأَيُّهَا ٱلَّذِينَ آمَنُوا۟ لَا تَتَّخِذُوا۟ بِطَانَةًۭ مِّن دُونِكُمْ لَا يَأْلُونَكُمْ خَبَالًۭا وَدُّوا۟ مَا عَنِتُّمْ قَدْ بَدَتِ ٱلْبَغْضَآءُ مِنْ أَفْوَهِهِمْ وَمَا تُخْفِى صُدُورُهُمْ أَكْبَرُ ۚ قَدْ بَيَّنَّا لَكُمُ ٱلْآيَتِ ۖ إِن كُنتُمْ تَعْقِلُونَ', 'Ali ''Imran: 118', 3, 118, 'surah al fateha quranic friendship', 'ali imran 118يايها الذين امنوا لا تتخذوا بطانه من دونكم لا يالونكم خبالا ودوا ما عنتم قد بدت البغضاء من افوههم وما تخفي صدورهم اكبر قد بينا لكم الايت ان كنتم تعقلونo you who believe', 'يايها الذين امنوا لا تتخذوا بطانه من دونكم لا يالونكم خبالا ودوا ما عنتم قد بدت البغضاء من افوههم وما تخفي صدورهم اكبر قد بينا لكم الايت ان كنتم تعقلون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 67, NULL, 'Do not take as Bitanah those outside your religion, for they will not fail to do their best to corrupt you. They desire to harm you severely. Hatred has already appeared from their mouths, but what their breasts conceal is far worse. Indeed, We have made plain to you the signs if you understand.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'do not take as bitanah those outside your religion for they will not fail to do their best to corrupt you they desire to harm you severely hatred has already appeared from their mouths but what their breasts conceal is far worse indeed we have made plain to you the signs if you understand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 68, NULL, 'This verse belongs to the context of the Battle of Uhud, in سُورَۃُ آلِ عِمْرَانَ. The Battle of Uhud was a difficult military situation for the Muslims. Medina was home to different communities — Christians and Jews among them — and some were cooperating with the enemy. In that context, the Quranic instruction was clear: do not share secrets with those outside the faith who carry this propensity, because in a state of war the chain of disclosure is unpredictable. Many would leave no stone unturned and actively seek to cause harm. The verse is not a blanket judgment on all Christians and Jews — it addresses those who carry that specific intent.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'this verse belongs to the context of the battle of uhud in سوره ال عمران the battle of uhud was a difficult military situation for the muslims medina was home to different communities christians and jews among them and some were cooperating with the enemy in that context the quranic instruction was clear do not share secrets with those outside the faith who carry this propensity because in a state of war the chain of disclosure is unpredictable many would leave no stone unturned and actively seek to cause harm the verse is not a blanket judgment on all christians and jews it addresses those who carry that specific intent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 69, NULL, 'The context is a state of war, where a casual word can cost lives. A passing remark — that I had seen the Prophet that day, that he would be at a certain place at a certain time — may be innocent in intent, yet for someone plotting against the Messenger, that information is gold. The one confided in may mean no harm, but the one they speak to next might. The disclosure travels down the chain. The instruction, therefore, is to keep intimate secrets within the innermost circle. That is the context of this word.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the context is a state of war where a casual word can cost lives a passing remark that i had seen the prophet that day that he would be at a certain place at a certain time may be innocent in intent yet for someone plotting against the messenger that information is gold the one confided in may mean no harm but the one they speak to next might the disclosure travels down the chain the instruction therefore is to keep intimate secrets within the innermost circle that is the context of this word', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 70, NULL, 'Beyond that context, the verse illuminates another shade of friendship — the بطانۃ, the one who knows the deepest and darkest secrets.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'beyond that context the verse illuminates another shade of friendship the بطانه the one who knows the deepest and darkest secrets', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 72, NULL, 'The next word the Quran uses for a friend is خلیل. خلیل comes from the root word خلۃ. Another word from the same root is خلال, which means flossing — what passes in between one thing and another. When thread is drawn between teeth, that action is خلال in Arabic.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the next word the quran uses for a friend is خليل خليل comes from the root word خله another word from the same root is خلال which means flossing what passes in between one thing and another when thread is drawn between teeth that action is خلال in arabic', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 73, NULL, 'A خلیل, then, is someone whose friendship has penetrated deep within the heart. The love for them runs so deep that one thinks of them constantly, feels their absence constantly, and wishes to be with them at any given moment. That is a خلیل. It is, again, a very rare kind of friendship — and it is precisely this kind of friendship that Allah سُبْحَانَهُ وَتَعَالَى had with Ibrahim عَلَیْہِ السَّلَامُ:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'a خليل then is someone whose friendship has penetrated deep within the heart the love for them runs so deep that one thinks of them constantly feels their absence constantly and wishes to be with them at any given moment that is a خليل it is again a very rare kind of friendship and it is precisely this kind of friendship that allah سبحانه وتعالي had with ibrahim عليه السلام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 74, NULL, 'An-Nisa: 125وَٱتَّخَذَ ٱللَّهُ إِبْرَهِيمَ خَلِيلًۭا', '', 'وَٱتَّخَذَ ٱللَّهُ إِبْرَهِيمَ خَلِيلًۭا', 'An-Nisa: 125', 4, 125, 'surah al fateha quranic friendship', 'an nisa 125واتخذ الله ابرهيم خليلا', 'واتخذ الله ابرهيم خليلا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 75, NULL, 'Allah took اِبْرَاھِیْمُ عَلَیْہِ السَّلَامُ as a خلیل.', '', 'اِبْرَاھِیْمُ عَلَیْہِ السَّلَامُ خلیل', NULL, NULL, NULL, 'surah al fateha quranic friendship', 'allah took ابراهيم عليه السلام as a خليل', 'ابراهيم عليه السلام خليل');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 76, NULL, 'Allah سُبْحَانَهُ وَتَعَالَى uses the word خلیل in remarkable ways throughout the Quran.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'allah سبحانه وتعالي uses the word خليل in remarkable ways throughout the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 77, NULL, 'Al-Baqarah: 254يَٓأَيُّهَا ٱلَّذِينَ آمَنُوٓا۟ أَنفِقُوا۟ مِمَّا رَزَقْنَكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌۭ لَّا بَيْعٌۭ فِيهِ وَلَا خُلَّةٌۭ وَلَا شَفَعَةٌۭ ۗ وَٱلْكَفِرُونَ هُمُ ٱلظَّلِمُونَ', '', 'يَٓأَيُّهَا ٱلَّذِينَ آمَنُوٓا۟ أَنفِقُوا۟ مِمَّا رَزَقْنَكُم مِّن قَبْلِ أَن يَأْتِىَ يَوْمٌۭ لَّا بَيْعٌۭ فِيهِ وَلَا خُلَّةٌۭ وَلَا شَفَعَةٌۭ ۗ وَٱلْكَفِرُونَ هُمُ ٱلظَّلِمُونَ', 'Al-Baqarah: 254', 2, 254, 'surah al fateha quranic friendship', 'al baqarah 254يايها الذين امنوا انفقوا مما رزقنكم من قبل ان ياتي يوم لا بيع فيه ولا خله ولا شفعه والكفرون هم الظلمون', 'يايها الذين امنوا انفقوا مما رزقنكم من قبل ان ياتي يوم لا بيع فيه ولا خله ولا شفعه والكفرون هم الظلمون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 78, NULL, 'O Believers! Spend from that which we have provided for you, before a Day comes when there will be no bargaining, nor friendship, nor intercession. And it is the disbelievers who are the Zalimun.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'o believers spend from that which we have provided for you before a day comes when there will be no bargaining nor friendship nor intercession and it is the disbelievers who are the zalimun', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 79, NULL, 'He also says:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'he also says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 80, NULL, 'Az-Zukhruf: 67ٱلْأَخِلَّآءُ يَوْمَئِذٍۭ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا ٱلْمُتَّقِينَ', '', 'ٱلْأَخِلَّآءُ يَوْمَئِذٍۭ بَعْضُهُمْ لِبَعْضٍ عَدُوٌّ إِلَّا ٱلْمُتَّقِينَ', 'Az-Zukhruf: 67', 43, 67, 'surah al fateha quranic friendship', 'az zukhruf 67الاخلاء يوميذ بعضهم لبعض عدو الا المتقين', 'الاخلاء يوميذ بعضهم لبعض عدو الا المتقين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 81, NULL, 'The closest of friends — those who shared deep love and intimacy in this world — will become each other''s enemies on the Day of Judgment. أخلاء is the plural of خلیل. Allah declares that no matter how close two people were in this life, that bond turns to enmity when the Day arrives. The sole exception is المتقین, the pious. And grammatically, this is the strongest form of exception the language permits: the only ones spared are those who were careful, in this world, about the kind of friends they kept. Every other friendship — however fierce and devoted it felt — dissolves on that Day.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the closest of friends those who shared deep love and intimacy in this world will become each others enemies on the day of judgment اخلاء is the plural of خليل allah declares that no matter how close two people were in this life that bond turns to enmity when the day arrives the sole exception is المتقين the pious and grammatically this is the strongest form of exception the language permits the only ones spared are those who were careful in this world about the kind of friends they kept every other friendship however fierce and devoted it felt dissolves on that day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 82, NULL, 'The lesson is clear: friendship must be chosen on the basis of a person''s consciousness of Allah, سُبْحَانَهُ وَتَعَالَى, and on the seriousness with which they carry their religious responsibility. The wrong person must never become one''s خلیل.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the lesson is clear friendship must be chosen on the basis of a persons consciousness of allah سبحانه وتعالي and on the seriousness with which they carry their religious responsibility the wrong person must never become ones خليل', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 83, NULL, 'Because when the Day of Judgment arrives, the wrongdoer says:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'because when the day of judgment arrives the wrongdoer says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 84, NULL, 'Sayingوَيَوْمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَلَيْتَنِى ٱتَّخَذْتُ مَعَ ٱلرَّسُولِ سَبِيلًۭا ‎۲۷‏يَوَيْلَتَىٰ لَيْتَنِى لَمْ أَتَّخِذْ فُلَانًا خَلِيلًۭا', '', 'وَيَوْمَ يَعَضُّ ٱلظَّالِمُ عَلَىٰ يَدَيْهِ يَقُولُ يَلَيْتَنِى ٱتَّخَذْتُ مَعَ ٱلرَّسُولِ سَبِيلًۭا ‎ ۲۷‏ يَوَيْلَتَىٰ لَيْتَنِى لَمْ أَتَّخِذْ فُلَانًا خَلِيلًۭا', 'Saying', NULL, NULL, 'surah al fateha quranic friendship', 'sayingويوم يعض الظالم علي يديه يقول يليتني اتخذت مع الرسول سبيلا ۲۷ يويلتي ليتني لم اتخذ فلانا خليلا', 'ويوم يعض الظالم علي يديه يقول يليتني اتخذت مع الرسول سبيلا ۲۷ يويلتي ليتني لم اتخذ فلانا خليلا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 85, NULL, 'And the Day when the ظالم will chew up his own hands, He will say: "If only I took on a path alongside the messenger ﷺ." "Ah! Woe to me! Would that I had never taken so-and-so as a friend!"', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'and the day when the ظالم will chew up his own hands he will say if only i took on a path alongside the messenger ﷺ ah woe to me would that i had never taken so and so as a friend', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 86, NULL, 'The word سبیل means a path — a beautifully precise linguistic image for an entire way of life. The wrongdoer is not lamenting a single decision but a whole direction of living: had he chosen the lifestyle of the messenger ﷺ, he would not stand in ruin on that Day. The verse carries extraordinary force, and the one that follows it sharpens it further.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the word سبيل means a path a beautifully precise linguistic image for an entire way of life the wrongdoer is not lamenting a single decision but a whole direction of living had he chosen the lifestyle of the messenger ﷺ he would not stand in ruin on that day the verse carries extraordinary force and the one that follows it sharpens it further', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 87, NULL, 'No other verse in the Quran concentrates despair quite like this one. It binds two words of regret together:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'no other verse in the quran concentrates despair quite like this one it binds two words of regret together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 88, NULL, 'Sayingيَوَيْلَتَىٰ لَيْتَنِى', '', 'يَوَيْلَتَىٰ لَيْتَنِى', 'Saying', 25, 28, 'surah al fateha quranic friendship', 'sayingيويلتي ليتني', 'يويلتي ليتني');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 89, NULL, 'حسرۃ is already an exaggerated form of lament. Then لیتنی is layered on top of it — an expression even more intense, carrying the weight of حسرۃ. The word حسرۃ means deep regret. This verse stands among the آیات most saturated with sorrow in the entire Book. And what does all that sorrow come down to? A man wishing he had never taken a certain person as a friend.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'حسره is already an exaggerated form of lament then ليتني is layered on top of it an expression even more intense carrying the weight of حسره the word حسره means deep regret this verse stands among the ايات most saturated with sorrow in the entire book and what does all that sorrow come down to a man wishing he had never taken a certain person as a friend', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 90, NULL, 'Al-Furqan: 28لَمْ أَتَّخِذْ فُلَانًا خَلِيلًۭا', '', 'لَمْ أَتَّخِذْ فُلَانًا خَلِيلًۭا', 'Al-Furqan: 28', 25, 28, 'surah al fateha quranic friendship', 'al furqan 28لم اتخذ فلانا خليلا', 'لم اتخذ فلانا خليلا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 91, NULL, 'There is something striking in the phrasing. The verse does not say "I wish I had chosen better friends" — it says I wish I had not taken this person as my friend. خلیل is someone held with profound love. A person loved that deeply would at the very least be known by name. Yet on the Day of Judgment, regret floods the heart and hatred fills it so completely that the name is gone. The verse therefore reads فُلَانًا خَلِيلًۭا — "so-and-so," an unnamed, anonymous figure. That is the depth of this person''s regret on the Day of Judgment.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'there is something striking in the phrasing the verse does not say i wish i had chosen better friends it says i wish i had not taken this person as my friend خليل is someone held with profound love a person loved that deeply would at the very least be known by name yet on the day of judgment regret floods the heart and hatred fills it so completely that the name is gone the verse therefore reads فلانا خليلا so and so an unnamed anonymous figure that is the depth of this persons regret on the day of judgment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 93, NULL, 'The word رفیق in Arabic comes from رفقۃ or رفق, and it means comfort. مِرفِقَۃ is the pillow placed behind an aching back. Those small cushions on a couch are also called مِرفَاق, because a person leans on them and they take the pressure away, allowing the body to relax.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the word رفيق in arabic comes from رفقه or رفق and it means comfort مرفقه is the pillow placed behind an aching back those small cushions on a couch are also called مرفاق because a person leans on them and they take the pressure away allowing the body to relax', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 94, NULL, 'A رفیق, then, is the friend one turns to in stress, in serious trouble, in difficult times — for comfort. The image is of a pillow one can lean on at any moment. And there is something telling in that image: a person reclining on a pillow is always at ease, never sitting formally. A رفیق is a friend with whom no performance is required. There is no need for stiff formality, no need to measure every word. This is someone in whose company a person can simply be themselves — completely, without pretense. That is a رفیق.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'a رفيق then is the friend one turns to in stress in serious trouble in difficult times for comfort the image is of a pillow one can lean on at any moment and there is something telling in that image a person reclining on a pillow is always at ease never sitting formally a رفيق is a friend with whom no performance is required there is no need for stiff formality no need to measure every word this is someone in whose company a person can simply be themselves completely without pretense that is a رفيق', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 95, NULL, 'Now Allah says:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'now allah says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 96, NULL, 'An-Nisa: 69وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُو۟لَٓئِكَ مَعَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّۦنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّلِحِينَ ۚ وَحَسُنَ أُو۟لَٓئِكَ رَفِيقًۭا', '', 'وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُو۟لَٓئِكَ مَعَ ٱلَّذِينَ أَنْعَمَ ٱللَّهُ عَلَيْهِم مِّنَ ٱلنَّبِيِّۦنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّلِحِينَ ۚ وَحَسُنَ أُو۟لَٓئِكَ رَفِيقًۭا', 'An-Nisa: 69', 4, 69, 'surah al fateha quranic friendship', 'an nisa 69ومن يطع الله والرسول فاوليك مع الذين انعم الله عليهم من النبين والصديقين والشهداء والصلحين وحسن اوليك رفيقا', 'ومن يطع الله والرسول فاوليك مع الذين انعم الله عليهم من النبين والصديقين والشهداء والصلحين وحسن اوليك رفيقا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 97, NULL, 'Those who obey God and obey the Prophet will receive special favors from Allah. They will be counted among the elect: they will find themselves in the company of prophets, of those who did righteous deeds, and of those who gave their lives for the sake of Allah. The verse closes:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'those who obey god and obey the prophet will receive special favors from allah they will be counted among the elect they will find themselves in the company of prophets of those who did righteous deeds and of those who gave their lives for the sake of allah the verse closes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 98, NULL, 'An-Nisa: 69وَحَسُنَ أُو۟لَٓئِكَ رَفِيقًۭا', '', 'وَحَسُنَ أُو۟لَٓئِكَ رَفِيقًۭا', 'An-Nisa: 69', 4, 69, 'surah al fateha quranic friendship', 'an nisa 69وحسن اوليك رفيقا', 'وحسن اوليك رفيقا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 99, NULL, 'What an awesome company of comforting friends. To be in the presence of Rasul Allah ﷺ and feel no anxiety — to be at ease in the company of Maulana Ali (AS), in the company of the Imams. SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'what an awesome company of comforting friends to be in the presence of rasul allah ﷺ and feel no anxiety to be at ease in the company of maulana ali as in the company of the imams subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 100, NULL, 'رفیق, then, is another kind of friend — one whose presence brings comfort, in whose company there is no unease. It is a quality worth striving to offer others.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'رفيق then is another kind of friend one whose presence brings comfort in whose company there is no unease it is a quality worth striving to offer others', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 102, NULL, 'The next kind of friend is a قرین, and it is a remarkable category. The word قرن is used in Arabic for the rope that holds two camels together. When two camels stand side by side and a single rope binds them, that rope is called قرن. A قرین, then, is someone who is always at one''s side — joined at the hip, as the expression goes. When one moves, the other is pulled along. They move as one.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the next kind of friend is a قرين and it is a remarkable category the word قرن is used in arabic for the rope that holds two camels together when two camels stand side by side and a single rope binds them that rope is called قرن a قرين then is someone who is always at ones side joined at the hip as the expression goes when one moves the other is pulled along they move as one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 103, NULL, 'The قرین is the friend who is a constant presence: always nearby, always at the other end of the line, always the first to receive a message, always there. When one is happy, the other becomes happy; when one grieves, the other feels that grief. That inseparability is قرین.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the قرين is the friend who is a constant presence always nearby always at the other end of the line always the first to receive a message always there when one is happy the other becomes happy when one grieves the other feels that grief that inseparability is قرين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 104, NULL, 'A قرین is also someone with whom one shares a great deal — because a rope cannot bind two camels of wildly different height or speed. There must be some equivalence between them; the pairing only holds when they are well matched. So a قرین is someone who shares one''s mind and one''s heart. They think as one thinks; they feel as one feels. That deep correspondence, that mirroring of thought and feeling, is the relationship of قرین.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'a قرين is also someone with whom one shares a great deal because a rope cannot bind two camels of wildly different height or speed there must be some equivalence between them the pairing only holds when they are well matched so a قرين is someone who shares ones mind and ones heart they think as one thinks they feel as one feels that deep correspondence that mirroring of thought and feeling is the relationship of قرين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 105, NULL, 'قرین can also mean people of the same community — all bound together by the rope of قَرِینُ عَہْدٍ شَرِیفٍ, all belonging to the same creed. That shared belonging makes them a قرین as well. The Quran presents this word in a striking and sobering way. In سُورَۃُ صِفَاتِ, some of those who make it to جنۃ begin to inquire about others — family members, people from their community — who are not there with them.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'قرين can also mean people of the same community all bound together by the rope of قرين عهد شريف all belonging to the same creed that shared belonging makes them a قرين as well the quran presents this word in a striking and sobering way in سوره صفات some of those who make it to جنه begin to inquire about others family members people from their community who are not there with them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 106, NULL, 'Sayingفَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَسَآءَلُونَ ‎۵۰‏قَالَ قَآئِلٌۭ مِّنْهُمْ إِنِّى كَانَ لِى قَرِينٌۭ ‎۵۱‏يَقُولُ أَءِنَّكَ لَمِنَ ٱلْمُصَدِّقِينَ ‎۵۲‏أَءِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَمًا أَءِنَّا لَمَدِينُونَ ‎۵۳‏قَالَ هَلْ أَنتُم مُّطَّلِعُونَ ‎۵۴‏فَٱطَّلَعَ فَرَآهُ فِى سَوَآءِ ٱلْجَحِيمِThen they will turn to one another, and question each otherA speaker of them will say: "Indeed, I had a companion, Who used to mock me!', '', 'فَأَقْبَلَ بَعْضُهُمْ عَلَىٰ بَعْضٍۢ يَتَسَآءَلُونَ ‎ ۵۰‏ قَالَ قَآئِلٌۭ مِّنْهُمْ إِنِّى كَانَ لِى قَرِينٌۭ ‎ ۵۱‏ يَقُولُ أَءِنَّكَ لَمِنَ ٱلْمُصَدِّقِينَ ‎ ۵۲‏ أَءِذَا مِتْنَا وَكُنَّا تُرَابًۭا وَعِظَمًا أَءِنَّا لَمَدِينُونَ ‎ ۵۳‏ قَالَ هَلْ أَنتُم مُّطَّلِعُونَ ‎ ۵۴‏ فَٱطَّلَعَ فَرَآهُ فِى سَوَآءِ ٱلْجَحِيمِ', 'Saying', NULL, NULL, 'surah al fateha quranic friendship', 'sayingفاقبل بعضهم علي بعض يتساءلون ۵۰ قال قايل منهم اني كان لي قرين ۵۱ يقول اءنك لمن المصدقين ۵۲ اءذا متنا وكنا ترابا وعظما اءنا لمدينون ۵۳ قال هل انتم مطلعون ۵۴ فاطلع فراه في سواء الجحيمthen they will turn to one another and question each othera speaker of them will say indeed i had a companion who used to mock me', 'فاقبل بعضهم علي بعض يتساءلون ۵۰ قال قايل منهم اني كان لي قرين ۵۱ يقول اءنك لمن المصدقين ۵۲ اءذا متنا وكنا ترابا وعظما اءنا لمدينون ۵۳ قال هل انتم مطلعون ۵۴ فاطلع فراه في سواء الجحيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 107, NULL, 'who used to mock me and say: "Are you among those who believe? Are you among those fools who call themselves Muslims? Are you among those idiots who say that when we die and become dust and bones, we shall indeed receive reward or punishment?!" In response he will answer: "Look down." So he will look down and see that person in the midst of the Hellfire.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'who used to mock me and say are you among those who believe are you among those fools who call themselves muslims are you among those idiots who say that when we die and become dust and bones we shall indeed receive reward or punishment in response he will answer look down so he will look down and see that person in the midst of the hellfire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 108, NULL, 'May Allah protect us from being among them. The choice of قرین is therefore one of the most consequential a person can make. A قرین can elevate a person to the doorsteps of Paradise, or he can be the very means of his ruin in the Hellfire.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'may allah protect us from being among them the choice of قرين is therefore one of the most consequential a person can make a قرين can elevate a person to the doorsteps of paradise or he can be the very means of his ruin in the hellfire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 109, NULL, 'Az-Zukhruf: 36وَمَن يَعْشُ عَن ذِكْرِ ٱلرَّحْمَنِ نُقَيِّضْ لَهُۥ شَيْطَنًۭا فَهُوَ لَهُۥ قَرِينٌۭAnd whosoever turns away from the remembrance of the intensely merciful, We shall appoint for him a شیطان to be a قرین to him.', '', NULL, 'Az-Zukhruf: 36', NULL, NULL, 'surah al fateha quranic friendship', 'az zukhruf 36ومن يعش عن ذكر الرحمن نقيض له شيطنا فهو له قرينand whosoever turns away from the remembrance of the intensely merciful we shall appoint for him a شيطان to be a قرين to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 110, NULL, 'This is Allah speaking in سُورَۃُ الزُّخْرُفِ. These are not idle words. The prospect of having شیطان as a قرین is a grave one. May Allah protect us all from that.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'this is allah speaking in سوره الزخرف these are not idle words the prospect of having شيطان as a قرين is a grave one may allah protect us all from that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 112, NULL, 'The Quran describes good friends, but it also describes bad ones. The word for this evil friend is خزول. خزل in Arabic is close in meaning to خضع, which means deception. خزول is a friend who only acts like a friend — until the moment of truth arrives and the true colors show. This person was present through the easy times, right there at every turn, always around, a genuine قرین. But when things grew difficult, he vanished. The one who depended on him found no one there. That is خزول, and it is what is called صِیغَۃُ مُبَالَغَہِ — not ordinary deception, but deception of the most extreme kind. This is the profoundly disappointing friend who abandons at the worst possible moment. He earns trust so completely, so patiently, that a blank check is handed over without hesitation — and by morning he is gone with everything. That level of betrayal is خزول. It takes years of sustained, consistent effort to خزول-ofy someone to that degree.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the quran describes good friends but it also describes bad ones the word for this evil friend is خزول خزل in arabic is close in meaning to خضع which means deception خزول is a friend who only acts like a friend until the moment of truth arrives and the true colors show this person was present through the easy times right there at every turn always around a genuine قرين but when things grew difficult he vanished the one who depended on him found no one there that is خزول and it is what is called صيغه مبالغه not ordinary deception but deception of the most extreme kind this is the profoundly disappointing friend who abandons at the worst possible moment he earns trust so completely so patiently that a blank check is handed over without hesitation and by morning he is gone with everything that level of betrayal is خزول it takes years of sustained consistent effort to خزول ofy someone to that degree', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 113, NULL, 'This is precisely how the Quran characterizes شیطان. His ultimate deception is to keep us from the remembrance of Allah — that is his entire game. He works to distract and divert attention toward دنیا.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'this is precisely how the quran characterizes شيطان his ultimate deception is to keep us from the remembrance of allah that is his entire game he works to distract and divert attention toward دنيا', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 114, NULL, 'Sayingلَّقَدْ أَضَلَّنِى عَنِ ٱلذِّكْرِ بَعْدَ إِذْ جَآءَنِى ۗ وَكَانَ ٱلشَّيْطَنُ لِلْإِنسَنِ خَذُولًۭا', '', 'لَّقَدْ أَضَلَّنِى عَنِ ٱلذِّكْرِ بَعْدَ إِذْ جَآءَنِى ۗ وَكَانَ ٱلشَّيْطَنُ لِلْإِنسَنِ خَذُولًۭا', 'Saying', 25, 29, 'surah al fateha quranic friendship', 'sayingلقد اضلني عن الذكر بعد اذ جاءني وكان الشيطن للانسن خذولا', 'لقد اضلني عن الذكر بعد اذ جاءني وكان الشيطن للانسن خذولا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 115, NULL, 'شیطان is a خزول to human beings. Allah says this because شیطان acts like a friend throughout this life. He draws a person into things while convincing them that those things serve their own good, their own enjoyment. He makes a person watch films and delight in filth. He makes them buy, travel, speak, and build the wrong kinds of friendships — all of it — and all the while that person believes life is good, that they are living it fully. Every last bit of it is خزل. Because when Judgment Day arrives, شیطان is nowhere to be found. He steps forward and says:', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'شيطان is a خزول to human beings allah says this because شيطان acts like a friend throughout this life he draws a person into things while convincing them that those things serve their own good their own enjoyment he makes a person watch films and delight in filth he makes them buy travel speak and build the wrong kinds of friendships all of it and all the while that person believes life is good that they are living it fully every last bit of it is خزل because when judgment day arrives شيطان is nowhere to be found he steps forward and says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 116, NULL, 'Ibrahim: 22وَمَا كَانَ لِىَ عَلَيْكُم مِّن سُلْطَنٍ', '', 'وَمَا كَانَ لِىَ عَلَيْكُم مِّن سُلْطَنٍ', 'Ibrahim: 22', 14, 22, 'surah al fateha quranic friendship', 'ibrahim 22وما كان لي عليكم من سلطن', 'وما كان لي عليكم من سلطن');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 117, NULL, 'Ibrahim: 22إِلَّآ أَن دَعَوْتُكُمْ فَٱسْتَجَبْتُمْ لِى', '', 'إِلَّآ أَن دَعَوْتُكُمْ فَٱسْتَجَبْتُمْ لِى', 'Ibrahim: 22', 14, 22, 'surah al fateha quranic friendship', 'ibrahim 22الا ان دعوتكم فاستجبتم لي', 'الا ان دعوتكم فاستجبتم لي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 118, NULL, 'I simply suggested that you do these things! I didn''t hold a gun to your head! You were the one who actually chose to do all these things!', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'i simply suggested that you do these things i didnt hold a gun to your head you were the one who actually chose to do all these things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'quranic friendship', 'Quranic Friendship', 119, NULL, 'Ibrahim: 22فَلَا تَلُومُونِى وَلُومُوٓا۟ أَنفُسَكُم', '', 'فَلَا تَلُومُونِى وَلُومُوٓا۟ أَنفُسَكُم', 'Ibrahim: 22', 14, 22, 'surah al fateha quranic friendship', 'ibrahim 22فلا تلوموني ولوموا انفسكم', 'فلا تلوموني ولوموا انفسكم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 120, NULL, 'So now don''t blame me! Blame yourself for the situation you''re in; and let''s just enjoy the barbecue together.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'so now dont blame me blame yourself for the situation youre in and lets just enjoy the barbecue together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 121, NULL, 'That is خذول — and that is precisely what will happen on Judgment Day.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'that is خذول and that is precisely what will happen on judgment day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 122, NULL, 'This is خزول. The question it forces is whether any of us are that kind of person — the kind of friend who deserts and abandons in the moment of need. The phone was dead. The call was missed. The message went unseen.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'this is خزول the question it forces is whether any of us are that kind of person the kind of friend who deserts and abandons in the moment of need the phone was dead the call was missed the message went unseen', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 123, NULL, 'The recognition was there — but the moment passed without action. That is شیطان.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'the recognition was there but the moment passed without action that is شيطان', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'quranic friendship', 'Quranic Friendship', 124, NULL, 'Reliability is among the most important qualities a friend can possess, and its absence is one of the surest ways to lose a friendship. A person may have genuine and rare friendships — and lose them not through malice but through sheer irresponsibility, through failing to hold up their end. That neglect is precisely the character of شیطان.', '', NULL, NULL, NULL, NULL, 'surah al fateha quranic friendship', 'reliability is among the most important qualities a friend can possess and its absence is one of the surest ways to lose a friendship a person may have genuine and rare friendships and lose them not through malice but through sheer irresponsibility through failing to hold up their end that neglect is precisely the character of شيطان', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 0, NULL, 'The Arabs have what they call مَرَاتِبُ الْحُبِّ, the stages of love. Unlike friendship, where we learned that the perfect friend must possess all the relevant qualities, love is described as having ten stages, or ten levels. People generally understand these stages in a worldly sense, which is perfectly acceptable, but the true purpose of understanding them is to learn how to love Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the arabs have what they call مراتب الحب the stages of love unlike friendship where we learned that the perfect friend must possess all the relevant qualities love is described as having ten stages or ten levels people generally understand these stages in a worldly sense which is perfectly acceptable but the true purpose of understanding them is to learn how to love allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 2, NULL, 'The first level is what they call علاقۃ, and it is:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the first level is what they call علاقه and it is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 3, NULL, 'Sayingتَعَلُّقِ القَلب بِی المحبُوب', '', 'تَعَلُّقِ القَلب بِی المحبُوب', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingتعلق القلب بي المحبوب', 'تعلق القلب بي المحبوب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 4, NULL, 'The connection of the heart to the beloved. This is the point at which the heart becomes connected or attached to the beloved. In our terms, we might call it attachment or a “crush.” We say, “I have a crush on that person,” or, “I am attached to this person or that person.” That is علاقۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the connection of the heart to the beloved this is the point at which the heart becomes connected or attached to the beloved in our terms we might call it attachment or a crush we say i have a crush on that person or i am attached to this person or that person that is علاقه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 5, NULL, 'This kind of attachment may develop into something deeper, or it may be very temporary. At this stage, it is simply a connection or attraction, without anything more.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this kind of attachment may develop into something deeper or it may be very temporary at this stage it is simply a connection or attraction without anything more', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 7, NULL, 'The second level is called ارادۃ, which is willful love. This is where you actually begin to seek the beloved—تُرِیدُہُ. You make an effort to find the beloved. At this stage, the lover is called مُرید because he sets out with a goal and a purpose: to find the beloved.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the second level is called اراده which is willful love this is where you actually begin to seek the beloved تريده you make an effort to find the beloved at this stage the lover is called مريد because he sets out with a goal and a purpose to find the beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 8, NULL, 'The first level was simply a connection of the heart. At this stage, there is an active pursuit of what the heart desires. It is considered the beginning of the path. Thus, ارادۃ is the stage at which you begin to desire the company of the beloved.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the first level was simply a connection of the heart at this stage there is an active pursuit of what the heart desires it is considered the beginning of the path thus اراده is the stage at which you begin to desire the company of the beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 10, NULL, 'The third level is سبابۃ. This سبابۃ comes from the Arabic expression سَبَّ الماءُ. The Arabs use this term to describe a waterfall. In English, we can think of this stage as “falling in love.” It is the point at which you begin to lose control. That is the اِنسِباب.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the third level is سبابه this سبابه comes from the arabic expression سب الماء the arabs use this term to describe a waterfall in english we can think of this stage as falling in love it is the point at which you begin to lose control that is the انسباب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 11, NULL, 'So سبابۃ is the stage at which you begin to lose control, and you realize that you are falling in love with this person.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'so سبابه is the stage at which you begin to lose control and you realize that you are falling in love with this person', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 13, NULL, 'Then comes غَرام, which carries the sense of مُلازمۃ. The punishment of the Hellfire is described as:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'then comes غرام which carries the sense of ملازمه the punishment of the hellfire is described as', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the stages of love', 'The Stages Of Love', 14, NULL, 'Al-Furqan: 65وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ ۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا', '', 'وَٱلَّذِينَ يَقُولُونَ رَبَّنَا ٱصْرِفْ عَنَّا عَذَابَ جَهَنَّمَ ۖ إِنَّ عَذَابَهَا كَانَ غَرَامًا', 'Al-Furqan: 65', 25, 65, 'surah al fateha the stages of love', 'al furqan 65والذين يقولون ربنا اصرف عنا عذاب جهنم ان عذابها كان غراما', 'والذين يقولون ربنا اصرف عنا عذاب جهنم ان عذابها كان غراما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 15, NULL, 'Indeed, the punishment of the Hellfire is unceasing. It does not stop. The idea here is لا یَنْفَکّ—something that does not let go, something never-ending.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'indeed the punishment of the hellfire is unceasing it does not stop the idea here is لا ينفك something that does not let go something never ending', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 16, NULL, 'This غَرام is the state the Arabs refer to as مُغْرَم بہ. It means that the lover simply wants to be with the beloved. There is a very strong desire to remain with the beloved at all times, and distance becomes painful at this stage.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this غرام is the state the arabs refer to as مغرم به it means that the lover simply wants to be with the beloved there is a very strong desire to remain with the beloved at all times and distance becomes painful at this stage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 17, NULL, 'One sign of people at this stage is that they constantly look at pictures of their beloved, or repeatedly return to read their letters, emails, or text messages. Doing so gives them a sense of closeness to the beloved and reduces the pain of separation.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'one sign of people at this stage is that they constantly look at pictures of their beloved or repeatedly return to read their letters emails or text messages doing so gives them a sense of closeness to the beloved and reduces the pain of separation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 19, NULL, 'The fifth stage is وُد, and the lover at this stage is called الوِداد. The word وُد means pure love. It is صَفوَۃُ المَحَبَّۃ—the purity of love. It is a love purified of the inclinations of the self.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the fifth stage is ود and the lover at this stage is called الوداد the word ود means pure love it is صفوه المحبه the purity of love it is a love purified of the inclinations of the self', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 20, NULL, 'In the previous stages, there was still some نفس involved. There were still selfish reasons for loving the beloved: wanting to see them, desiring them, thinking about them. At those earlier stages, it is really more about you than about the beloved. But when you enter the stage of وُد, love begins to become pure. It begins to become selfless.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'in the previous stages there was still some نفس involved there were still selfish reasons for loving the beloved wanting to see them desiring them thinking about them at those earlier stages it is really more about you than about the beloved but when you enter the stage of ود love begins to become pure it begins to become selfless', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 21, NULL, 'This is why the Messenger of Allah ﷺ said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is why the messenger of allah ﷺ said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 22, NULL, 'Sayingتَزَوِّج الوَلُود الوَدُود', '', 'تَزَوِّج الوَلُود الوَدُود', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingتزوج الولود الودود', 'تزوج الولود الودود');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 23, NULL, 'Marry a fertile woman who is ودود. Marry a woman who possesses this kind of pure love, a woman whose love is not selfish. And, obviously, in Arabic there is always مفحوم المُخالَفۃ, which means that the converse is also true: a woman should likewise look for a husband who possesses this quality.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'marry a fertile woman who is ودود marry a woman who possesses this kind of pure love a woman whose love is not selfish and obviously in arabic there is always مفحوم المخالفه which means that the converse is also true a woman should likewise look for a husband who possesses this quality', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 24, NULL, 'So الوُد is pure love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'so الود is pure love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 25, NULL, 'Interestingly, this is also one of the names of Allah. He is الودود:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'interestingly this is also one of the names of allah he is الودود', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the stages of love', 'The Stages Of Love', 26, NULL, 'Hud: 90وَٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ ۚ إِنَّ رَبِّى رَحِيمٌۭ وَدُودٌۭ', '', 'وَٱسْتَغْفِرُوا۟ رَبَّكُمْ ثُمَّ تُوبُوٓا۟ إِلَيْهِ ۚ إِنَّ رَبِّى رَحِيمٌۭ وَدُودٌۭ', 'Hud: 90', 11, 90, 'surah al fateha the stages of love', 'hud 90واستغفروا ربكم ثم توبوا اليه ان ربي رحيم ودود', 'واستغفروا ربكم ثم توبوا اليه ان ربي رحيم ودود');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 27, NULL, 'Ask forgiveness of your master and turn to Him in repentance. Indeed, my master is Most Merciful, Most Loving.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'ask forgiveness of your master and turn to him in repentance indeed my master is most merciful most loving', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 28, NULL, 'He is selfless in His love. Thus, الودود has two meanings:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'he is selfless in his love thus الودود has two meanings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 29, NULL, 'Sayingالوَادُّ فی عِبادِہِ والمَودُود', '', 'الوَادُّ فی عِبادِہِ والمَودُود', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingالواد في عباده والمودود', 'الواد في عباده والمودود');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 30, NULL, 'Allah is the One who loves His servants, and He is the One whom His servants love. It is a relationship of pure love in both directions. Allah has a pure, selfless love for His creation, and creation has a pure, selfless love for its master. That is الوُد.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'allah is the one who loves his servants and he is the one whom his servants love it is a relationship of pure love in both directions allah has a pure selfless love for his creation and creation has a pure selfless love for its master that is الود', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 31, NULL, 'This is also how Allah describes the true purpose of a man and a woman coming together:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is also how allah describes the true purpose of a man and a woman coming together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 32, NULL, 'Ar-Rum: 21وَمِنْ آيَتِهِۦٓ أَنْ خَلَقَ لَكُم مِّنْ أَنفُسِكُمْ أَزْوَجًۭا لِّتَسْكُنُوٓا۟ إِلَيْهَا وَجَعَلَ بَيْنَكُم مَّوَدَّةًۭ وَرَحْمَةً ۚAnd among His Signs is that He created for you wives from among yourselves, that you may find سکون, repose, in them, and He has placed between you pure love and mercy. Verily, in that are indeed signs for a people who reflect.', '', NULL, 'Ar-Rum: 21', NULL, NULL, 'surah al fateha the stages of love', 'ar rum 21ومن ايته ان خلق لكم من انفسكم ازوجا لتسكنوا اليها وجعل بينكم موده ورحمه and among his signs is that he created for you wives from among yourselves that you may find سكون repose in them and he has placed between you pure love and mercy verily in that are indeed signs for a people who reflect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 33, NULL, 'Allah says that He placed مودۃ between a man and a woman, which is pure love. This is the kind of love in which a husband will not divorce his wife when she becomes sick, when she is no longer beautiful, or when she becomes fat. If you have مودۃ for your wife, then even if she becomes fat, you will still love her. Seriously. If she becomes sick, you will still love her, because she will still love you even if you become fat or ugly. She will still love you.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'allah says that he placed موده between a man and a woman which is pure love this is the kind of love in which a husband will not divorce his wife when she becomes sick when she is no longer beautiful or when she becomes fat if you have موده for your wife then even if she becomes fat you will still love her seriously if she becomes sick you will still love her because she will still love you even if you become fat or ugly she will still love you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 34, NULL, 'A woman''s love is quite remarkable; it does not change in the same way a man''s love can change.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'a womans love is quite remarkable it does not change in the same way a mans love can change', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 35, NULL, 'Shakespeare said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'shakespeare said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 36, NULL, 'Love is not love which alters when it alteration finds; or bends with the remover to remove', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'love is not love which alters when it alteration finds or bends with the remover to remove', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 37, NULL, 'O no! it is an ever-fixed mark that looks on tempests and is never shaken', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'o no it is an ever fixed mark that looks on tempests and is never shaken', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 38, NULL, 'That is real love. That is الوُد. What he means is that love is not truly love if it changes merely because circumstances change. Your wife may be beautiful today, and you love her. But if one day she is no longer beautiful, that should not change your love. If it does, then that is not love. That is lust.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'that is real love that is الود what he means is that love is not truly love if it changes merely because circumstances change your wife may be beautiful today and you love her but if one day she is no longer beautiful that should not change your love if it does then that is not love that is lust', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 39, NULL, 'I know of a woman who was in an accident and suffered burns on one side of her face. Her husband simply divorced her because she was no longer beautiful. He divorced her and sent her back to her parents. That is not love. That is sick. Yet that is the state of some people.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'i know of a woman who was in an accident and suffered burns on one side of her face her husband simply divorced her because she was no longer beautiful he divorced her and sent her back to her parents that is not love that is sick yet that is the state of some people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 40, NULL, 'That is not real love. This is why, if you observe carefully, women often have a much deeper capacity for this kind of love than most men do. If the same accident had happened to the husband and his face had been burned, she might have spent the rest of her life with him, caring for him and loving him in the same way. That is real love, and women have a much greater capacity to love in this way.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'that is not real love this is why if you observe carefully women often have a much deeper capacity for this kind of love than most men do if the same accident had happened to the husband and his face had been burned she might have spent the rest of her life with him caring for him and loving him in the same way that is real love and women have a much greater capacity to love in this way', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 41, NULL, 'This is why Rasul Allah ﷺ said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is why rasul allah ﷺ said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 42, NULL, 'Sayingحُبِّبَ الییَّ النِّساء', '', 'حُبِّبَ الییَّ النِّساء', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingحبب اليي النساء', 'حبب اليي النساء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 43, NULL, 'I was made to love women.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'i was made to love women', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 44, NULL, 'That statement has nothing to do with lust.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'that statement has nothing to do with lust', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 45, NULL, 'Sayingوَالتِّیْب وَالمِسوَاک', '', 'وَالتِّیْب وَالمِسوَاک', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingوالتيب والمسواك', 'والتيب والمسواك');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 46, NULL, 'And I was made to love perfume and to love flossing.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'and i was made to love perfume and to love flossing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 47, NULL, 'What is the connection between women, perfume, and floss? Perfume simply gives. Perfume dissipates its own existence for others—for us. When you put on perfume, it diffuses and gives up its own existence in order to make you smell pleasant.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'what is the connection between women perfume and floss perfume simply gives perfume dissipates its own existence for others for us when you put on perfume it diffuses and gives up its own existence in order to make you smell pleasant', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 48, NULL, 'Floss enters a filthy mouth and cleans it at the expense of its own existence. It sacrifices itself to clean our mouths. What does the floss gain from that experience? Nothing. What does perfume gain from being applied? Nothing.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'floss enters a filthy mouth and cleans it at the expense of its own existence it sacrifices itself to clean our mouths what does the floss gain from that experience nothing what does perfume gain from being applied nothing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 49, NULL, 'That is the quality in women that the Prophet loved: the capacity for sacrifice that comes so naturally to a woman and that men often find so difficult. That is why love is what we learn from our mothers. That is why Rasul Allah ﷺ said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'that is the quality in women that the prophet loved the capacity for sacrifice that comes so naturally to a woman and that men often find so difficult that is why love is what we learn from our mothers that is why rasul allah ﷺ said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 50, NULL, 'Sayingالَجنَّۃُ تَحتَ الاَقدَامِ الاُمَّھَات', '', 'الَجنَّۃُ تَحتَ الاَقدَامِ الاُمَّھَات', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingالجنه تحت الاقدام الامهات', 'الجنه تحت الاقدام الامهات');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 51, NULL, 'Paradise is UNDER the feet of mothers. UNDER the feet of mothers.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'paradise is under the feet of mothers under the feet of mothers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 52, NULL, 'That is where we learn love best. That is where we see it most fully embodied.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'that is where we learn love best that is where we see it most fully embodied', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 53, NULL, 'That is why, in a HADEES, Rasul Allah ﷺ said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'that is why in a hadees rasul allah ﷺ said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 54, NULL, 'Sayingُشَقَقْتُ الرَّحَم مِن أِسمِیَ الرَّحمٰن ۔ فمََنْ قَطَعَہُ فَقَد قَطَعْتُہ', '', 'ُشَقَقْتُ الرَّحَم مِن أِسمِیَ الرَّحمٰن ۔ فمََنْ قَطَعَہُ فَقَد قَطَعْتُہ', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingشققت الرحم من اسمي الرحمن فمن قطعه فقد قطعته', 'شققت الرحم من اسمي الرحمن فمن قطعه فقد قطعته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 55, NULL, 'I have derived the womb—شققت literally means “to split.” He says, “I have split the womb from My name الرحمن, the Merciful.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'i have derived the womb شققت literally means to split he says i have split the womb from my name الرحمن the merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 56, NULL, 'That is unique to women. Men do not have wombs. Allah gave that only to women. It is that space at the center of a woman that becomes the source of all mercy in the world. It was our first abode. All of us were once in that abode of رحمہ.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'that is unique to women men do not have wombs allah gave that only to women it is that space at the center of a woman that becomes the source of all mercy in the world it was our first abode all of us were once in that abode of رحمه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 57, NULL, 'And the mercy of the womb is extraordinary: it grows in order to accommodate what is inside it. That is what mercy is. It is an emotion that grows according to the need of the servant. It expands to meet the needs of others. That is mercy. That is love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'and the mercy of the womb is extraordinary it grows in order to accommodate what is inside it that is what mercy is it is an emotion that grows according to the need of the servant it expands to meet the needs of others that is mercy that is love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 58, NULL, 'That is why our Prophet is رَحْمَۃً لِی الْعَالَمِینَ:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'that is why our prophet is رحمه لي العالمين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the stages of love', 'The Stages Of Love', 59, NULL, 'Al-Anbiya: 107وَمَآ أَرْسَلْنَكَ إِلَّا رَحْمَةًۭ لِّلْعَلَمِينَ', '', 'وَمَآ أَرْسَلْنَكَ إِلَّا رَحْمَةًۭ لِّلْعَلَمِينَ', 'Al-Anbiya: 107', 21, 107, 'surah al fateha the stages of love', 'al anbiya 107وما ارسلنك الا رحمه للعلمين', 'وما ارسلنك الا رحمه للعلمين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 60, NULL, 'We have not sent you but as a mercy to all of humanity—because he expanded himself to meet the needs of others.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'we have not sent you but as a mercy to all of humanity because he expanded himself to meet the needs of others', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 61, NULL, 'That is وُد: pure love. It is not a utilitarian kind of love, a love tainted by one''s own selfish needs. It is not the kind of love that asks, “What am I going to get out of this? What is in it for me?”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'that is ود pure love it is not a utilitarian kind of love a love tainted by ones own selfish needs it is not the kind of love that asks what am i going to get out of this what is in it for me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 62, NULL, 'It is a love that transcends all of that. It is the kind of love that remains when beauty is present and remains when beauty is gone. If service is no longer possible because of a stroke or some other incapacity, the love remains. That is real love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'it is a love that transcends all of that it is the kind of love that remains when beauty is present and remains when beauty is gone if service is no longer possible because of a stroke or some other incapacity the love remains that is real love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 63, NULL, 'It is not love when the beloved matters only because they are useful to me. That is not love. That is something else.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'it is not love when the beloved matters only because they are useful to me that is not love that is something else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 64, NULL, 'And we have become a society largely devoid of this kind of love. Everything in our lives is about us: What is in it for me? Why should I help you?', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'and we have become a society largely devoid of this kind of love everything in our lives is about us what is in it for me why should i help you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 65, NULL, 'After the battle of سفین was over, a water carrier narrated that he went across the battlefield searching for dying soldiers. In those days, there would be a man whose duty was to carry a مشکیزۃ, a water container, in order to quench the thirst of dying soldiers. They say that at the moment of death a person becomes extremely thirsty, and water helps ease the transition.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'after the battle of سفين was over a water carrier narrated that he went across the battlefield searching for dying soldiers in those days there would be a man whose duty was to carry a مشكيزه a water container in order to quench the thirst of dying soldiers they say that at the moment of death a person becomes extremely thirsty and water helps ease the transition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 66, NULL, 'The man narrated that he was carrying water across the battlefield of سفین, searching for thirsty soldiers, when he came upon a man whose lower body had been severed. Only his torso remained on the scorching ground, and he was crying out for water.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the man narrated that he was carrying water across the battlefield of سفين searching for thirsty soldiers when he came upon a man whose lower body had been severed only his torso remained on the scorching ground and he was crying out for water', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 67, NULL, 'The water carrier approached him and brought the cup close to his lips. At that moment, they heard another man calling for water. The dying man closed his lips and refused to drink so that his brother could be given water first.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the water carrier approached him and brought the cup close to his lips at that moment they heard another man calling for water the dying man closed his lips and refused to drink so that his brother could be given water first', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 68, NULL, 'The water carrier rushed to the second man. As he brought the cup close to his lips, they heard a third man calling for water. The second man likewise closed his lips and refused to drink.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the water carrier rushed to the second man as he brought the cup close to his lips they heard a third man calling for water the second man likewise closed his lips and refused to drink', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 69, NULL, 'The water carrier hurried to the third man, but by the time he reached him, the man had died. He then returned to the second man, but he too had died. Finally, he returned to the first man, and by then he also had died of thirst.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the water carrier hurried to the third man but by the time he reached him the man had died he then returned to the second man but he too had died finally he returned to the first man and by then he also had died of thirst', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 70, NULL, 'That was love. That was وُد—the love these people had for one another. Where is our love? How do we compare?', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'that was love that was ود the love these people had for one another where is our love how do we compare', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 72, NULL, 'The next stage is called شغف. What they call شَغَافُ الْقَلْبِ is the pericardium. This is the stage at which the heart is surrounded by love. Love encompasses the heart.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the next stage is called شغف what they call شغاف القلب is the pericardium this is the stage at which the heart is surrounded by love love encompasses the heart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 73, NULL, 'This is the state of obsession. Wherever you are, whatever you see, it reminds you of the beloved.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is the state of obsession wherever you are whatever you see it reminds you of the beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 74, NULL, 'Sayingجِدَھرْ دِیکھْتَا ہُوں تُو ہِی تُو ہَےْ', '', 'جِدَھرْ دِیکھْتَا ہُوں تُو ہِی تُو ہَےْ', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingجدهر ديكهتا هون تو هي تو هي', 'جدهر ديكهتا هون تو هي تو هي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 75, NULL, 'You see the beloved everywhere: in the sunrise, the sunset, the rose, the birds, the music. Everything reminds you of the beloved.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'you see the beloved everywhere in the sunrise the sunset the rose the birds the music everything reminds you of the beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 77, NULL, 'Then comes the stage of العشق, which is a very dangerous state of love. People who enter this state of love for another person, or for God, can end up losing their sanity. It is an extremely dangerous phase. This is the stage in which the lover takes pleasure in pain and suffering for the sake of the beloved. It is a state of insane love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'then comes the stage of العشق which is a very dangerous state of love people who enter this state of love for another person or for god can end up losing their sanity it is an extremely dangerous phase this is the stage in which the lover takes pleasure in pain and suffering for the sake of the beloved it is a state of insane love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 78, NULL, 'The word عشق actually comes from the name of a vine, عَشَقَ. When this vine surrounds a tree, it draws the life out of the tree and eventually kills it. The image is of the tree destroying itself in order to nourish and sustain the vine. It kills itself so that its beloved can live.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the word عشق actually comes from the name of a vine عشق when this vine surrounds a tree it draws the life out of the tree and eventually kills it the image is of the tree destroying itself in order to nourish and sustain the vine it kills itself so that its beloved can live', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 79, NULL, 'So عشق is the kind of love in which there is total constriction. The lover begins to suffer for love of the beloved and actually takes pleasure in that suffering.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'so عشق is the kind of love in which there is total constriction the lover begins to suffer for love of the beloved and actually takes pleasure in that suffering', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 80, NULL, 'The Arabs say:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the arabs say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 81, NULL, 'Sayingدَعَا الْعِشْقُ الْاِتِّصَالَ', '', 'دَعَا الْعِشْقُ الْاِتِّصَالَ', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingدعا العشق الاتصال', 'دعا العشق الاتصال');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 82, NULL, 'The only cure for this intense level of love is finally meeting the beloved.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the only cure for this intense level of love is finally meeting the beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 83, NULL, 'During the time of فرعون, there was a woman who had become Muslim but had not disclosed her Islam to anyone. فرعون eventually discovered this and summoned her to his court. She was arrested and brought before him with her two daughters. The older daughter was ten years old, and the younger was only a few months old.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'during the time of فرعون there was a woman who had become muslim but had not disclosed her islam to anyone فرعون eventually discovered this and summoned her to his court she was arrested and brought before him with her two daughters the older daughter was ten years old and the younger was only a few months old', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 84, NULL, 'فرعون said to the woman, “I have heard that you now believe in the God of Moses. I give you two choices. The first is that you reject the God of موسی and accept me as your god. If you do so, I will grant you a palace in which you and your daughters will live as royalty. You will enjoy every comfort you can imagine for the rest of your lives.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'فرعون said to the woman i have heard that you now believe in the god of moses i give you two choices the first is that you reject the god of موسي and accept me as your god if you do so i will grant you a palace in which you and your daughters will live as royalty you will enjoy every comfort you can imagine for the rest of your lives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 85, NULL, '“The second choice is that you reject my offer. If you do, I will burn both of your daughters alive before your eyes, and then I will burn you alive as well.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the second choice is that you reject my offer if you do i will burn both of your daughters alive before your eyes and then i will burn you alive as well', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 86, NULL, 'She rejected his offer.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'she rejected his offer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 87, NULL, 'So فرعون ordered his men to fill a large cauldron with oil and heat it until it began to boil. فرعون asked her again, “Do you accept my offer?”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'so فرعون ordered his men to fill a large cauldron with oil and heat it until it began to boil فرعون asked her again do you accept my offer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 88, NULL, 'She said, “I am already in love with Moosa''s God. How can I betray Him for you?”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'she said i am already in love with moosas god how can i betray him for you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 89, NULL, 'This is عشق.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is عشق', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 90, NULL, 'At فرعون''s command, his soldiers dragged her ten-year-old daughter forward and threw her into the boiling oil. There are mothers in the group. Only a mother can understand what befalls a mother''s heart when she sees her child burned to death before her eyes.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'at فرعونs command his soldiers dragged her ten year old daughter forward and threw her into the boiling oil there are mothers in the group only a mother can understand what befalls a mothers heart when she sees her child burned to death before her eyes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 91, NULL, 'فرعون asked her again, “Do you accept my offer?”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'فرعون asked her again do you accept my offer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 92, NULL, 'Again, she refused.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'again she refused', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 93, NULL, 'So they took her infant daughter, only a few months old, and threw her into the boiling oil as well. Still, she did not say a word.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'so they took her infant daughter only a few months old and threw her into the boiling oil as well still she did not say a word', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 94, NULL, 'At that moment, it is said that the veils of the sky were removed before her eyes, and she saw her two daughters in Paradise saying to her, “Mother, be patient just a little while longer. We are soon going to be reunited in Heaven.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'at that moment it is said that the veils of the sky were removed before her eyes and she saw her two daughters in paradise saying to her mother be patient just a little while longer we are soon going to be reunited in heaven', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 95, NULL, 'Then came the woman''s turn. She said to فرعون, “I have one final request: after you kill me, bury my bones together with the bones of my daughters.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'then came the womans turn she said to فرعون i have one final request after you kill me bury my bones together with the bones of my daughters', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 96, NULL, 'فرعون said, “Your wish will be granted.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'فرعون said your wish will be granted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 97, NULL, 'Then they threw the woman into the burning oil as well, and she was reunited with her children. Her final wish was fulfilled, and their bones were buried together.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'then they threw the woman into the burning oil as well and she was reunited with her children her final wish was fulfilled and their bones were buried together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 98, NULL, 'Two thousand years later, Rasul Allah ﷺ is being taken on معراج. When براق flew over بَیْتُ الْمُقَدَّسِ, the Prophet smelled the fragrance of Paradise. He asked جبرئیل, “Where is this fragrance coming from?”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'two thousand years later rasul allah ﷺ is being taken on معراج when براق flew over بيت المقدس the prophet smelled the fragrance of paradise he asked جبرييل where is this fragrance coming from', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 99, NULL, 'جبرئیل narrated this entire incident to the Prophet and said that, from the day the bones of that woman and her daughters were buried, this fragrance had been rising from their graves. Only the angels enjoy this fragrance; we do not possess the sense by which such a fragrance can be perceived. But this was our Prophet ﷺ, who sensed that fragrance and asked about it.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'جبرييل narrated this entire incident to the prophet and said that from the day the bones of that woman and her daughters were buried this fragrance had been rising from their graves only the angels enjoy this fragrance we do not possess the sense by which such a fragrance can be perceived but this was our prophet ﷺ who sensed that fragrance and asked about it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 100, NULL, 'This is عشق. This is the story of عشق: how this woman loved Allah and how Allah loved her in return. Two thousand years later, the Messenger ﷺ was sensing the fragrance of Paradise rising from their graves. SubhanAllah!', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is عشق this is the story of عشق how this woman loved allah and how allah loved her in return two thousand years later the messenger ﷺ was sensing the fragrance of paradise rising from their graves subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 101, NULL, 'The story of کربلا is the story of عشق. Every محرم, we hear that tale of عشق. Karbala is the tale of this extraordinary, consuming love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the story of كربلا is the story of عشق every محرم we hear that tale of عشق karbala is the tale of this extraordinary consuming love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 102, NULL, 'You may have heard of the woman in Imam Hussain''s camp whose son went into battle and returned to her covered in blood and wounds. He came back to the camp, called out to his mother, and asked, “Are you pleased with me, Mother?”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'you may have heard of the woman in imam hussains camp whose son went into battle and returned to her covered in blood and wounds he came back to the camp called out to his mother and asked are you pleased with me mother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 103, NULL, 'What mother could bear to see her son covered in wounds and bleeding from head to toe? Yet his mother told him, “Not yet, my son. I will not be pleased with you until you sacrifice yourself for Imam Hussain.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'what mother could bear to see her son covered in wounds and bleeding from head to toe yet his mother told him not yet my son i will not be pleased with you until you sacrifice yourself for imam hussain', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 104, NULL, 'This is عشق.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is عشق', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 105, NULL, 'He returned to the battle and fought until he was martyred. They cut off his head and threw it toward the camp. His mother came out, took his head, placed it in her lap, and began kissing his forehead. Then she screamed and died.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'he returned to the battle and fought until he was martyred they cut off his head and threw it toward the camp his mother came out took his head placed it in her lap and began kissing his forehead then she screamed and died', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 106, NULL, 'This is عشق.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is عشق', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 108, NULL, 'The next phase is called تَتَیَُم. The word تیم is used for a slave, though not at the level of an عبد. It describes a high degree of love accompanied by a kind of servitude. This is the stage at which you enter the service of the beloved.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the next phase is called تتيم the word تيم is used for a slave though not at the level of an عبد it describes a high degree of love accompanied by a kind of servitude this is the stage at which you enter the service of the beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 109, NULL, 'Love has now reached the point of asking, “What can I do for you? How can I serve you?” At this stage, the lover finds pleasure in serving the beloved.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'love has now reached the point of asking what can i do for you how can i serve you at this stage the lover finds pleasure in serving the beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 111, NULL, 'The next stage is تعبد, where the lover becomes a complete slave to the beloved. At this stage, servitude is joined by complete obedience. It is the point at which, when the beloved says, “Jump,” the lover asks, “How high?” There is unquestioning obedience to the beloved.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the next stage is تعبد where the lover becomes a complete slave to the beloved at this stage servitude is joined by complete obedience it is the point at which when the beloved says jump the lover asks how high there is unquestioning obedience to the beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 112, NULL, 'This is why the poet says:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is why the poet says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 113, NULL, 'Sayingتُعصِی اِلٰہَ وَ تُظْھِرُ حُبُّہُ', '', 'تُعصِی اِلٰہَ وَ تُظْھِرُ حُبُّہُ', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingتعصي اله و تظهر حبه', 'تعصي اله و تظهر حبه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 114, NULL, 'Sayingھَذا الامْرُکَ فِی قِیَاسِ بَدِیعُ', '', 'ھَذا الامْرُکَ فِی قِیَاسِ بَدِیعُ', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingهذا الامرك في قياس بديع', 'هذا الامرك في قياس بديع');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 115, NULL, 'You claim to love your God, and yet you disobey Him? Such a love makes no sense to me.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'you claim to love your god and yet you disobey him such a love makes no sense to me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 116, NULL, 'So عبد is the stage of complete obedience in love. And this is an honorific title of the Messenger of Allah ﷺ:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'so عبد is the stage of complete obedience in love and this is an honorific title of the messenger of allah ﷺ', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the stages of love', 'The Stages Of Love', 117, NULL, 'Al-Isra: 1سُبْحَنَ ٱلَّذِىٓ أَسْرَىٰ بِعَبْدِهِ لَيْلًۭا', '', 'سُبْحَنَ ٱلَّذِىٓ أَسْرَىٰ بِعَبْدِهِ لَيْلًۭا', 'Al-Isra: 1', 17, 1, 'surah al fateha the stages of love', 'al isra 1سبحن الذي اسري بعبده ليلا', 'سبحن الذي اسري بعبده ليلا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 118, NULL, 'Glorious is the One who took His slave on a journey by night.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'glorious is the one who took his slave on a journey by night', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 119, NULL, 'Not “messenger,” not “prophet,” but عبد—His slave. This title of the Prophet is even greater than the title of رسول. This is عبودیۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'not messenger not prophet but عبد his slave this title of the prophet is even greater than the title of رسول this is عبوديه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 120, NULL, 'تعبد is adoration. That is why the عابد is the one who adores. “Adore” is a Latin word connected with love. Thus, عبودیۃ is the realm of adoration, where there is complete stillness before the beloved and unconditional obedience to the beloved.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'تعبد is adoration that is why the عابد is the one who adores adore is a latin word connected with love thus عبوديه is the realm of adoration where there is complete stillness before the beloved and unconditional obedience to the beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 122, NULL, 'The next stage of love is called خُلۃ, and it is the level of the خلیل. The Prophet said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the next stage of love is called خله and it is the level of the خليل the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 123, NULL, 'Sayingان اللہ أِتَّخَذَنِی خَلِیلاً کَمَا التَّخَذَ ابراھیمَ خلیلا', '', 'ان اللہ أِتَّخَذَنِی خَلِیلاً کَمَا التَّخَذَ ابراھیمَ خلیلا', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingان الله اتخذني خليلا كما التخذ ابراهيم خليلا', 'ان الله اتخذني خليلا كما التخذ ابراهيم خليلا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 124, NULL, 'Allah took me as a خلیل just as He took Ibrahim as a خلیل.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'allah took me as a خليل just as he took ibrahim as a خليل', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 125, NULL, 'This is the highest level of love, where love:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is the highest level of love where love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 126, NULL, 'Sayingتَتَخَلَّلُو خَلَایَ الجَسَد', '', 'تَتَخَلَّلُو خَلَایَ الجَسَد', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingتتخللو خلاي الجسد', 'تتخللو خلاي الجسد');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 127, NULL, 'The love completely permeates every cell of the body.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the love completely permeates every cell of the body', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 128, NULL, 'تخلیل means to penetrate deeply. For example, in the احکام of غُسُل, when you do تخلیل الشَّعَر, you must reach every hair follicle. That is خُلَّۃ. It is a very high degree of love, where love has permeated the entire soul.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'تخليل means to penetrate deeply for example in the احكام of غسل when you do تخليل الشعر you must reach every hair follicle that is خله it is a very high degree of love where love has permeated the entire soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 130, NULL, 'The final stage of love is called محبۃ, and there is really no single word in the English language that can encompass the depth of this love. The word محبۃ comes from the root word حُب, which means seed. It is a never-ending, eternal kind of love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the final stage of love is called محبه and there is really no single word in the english language that can encompass the depth of this love the word محبه comes from the root word حب which means seed it is a never ending eternal kind of love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 131, NULL, 'What happens when you sow a seed? You reap a harvest. You receive an exponential return. And what happens after the harvest? It grows again. You harvest again, and it grows again. That is حُب. That is an enduring love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'what happens when you sow a seed you reap a harvest you receive an exponential return and what happens after the harvest it grows again you harvest again and it grows again that is حب that is an enduring love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 132, NULL, 'And this is the مقام of the Prophet. He is حَبِیبُ اللَّہِ—the one whom Allah loves.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'and this is the مقام of the prophet he is حبيب الله the one whom allah loves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 133, NULL, 'Adam is سَفِیرُ اللَّہِ, the one Allah sent; نوح is نجی اللہ, the one Allah saved; ابراھیم is خَلِیلُ اللَّہِ, the one Allah befriended; موسی is کَلِیمُ اللّٰہِ, the one with whom Allah conversed; عیسی is روح اللہ, the one into whom Allah breathed His spirit; but Rasul Allah ﷺ is حَبِیبُ اللَّہِ. He is the one Allah loved.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'adam is سفير الله the one allah sent نوح is نجي الله the one allah saved ابراهيم is خليل الله the one allah befriended موسي is كليم الله the one with whom allah conversed عيسي is روح الله the one into whom allah breathed his spirit but rasul allah ﷺ is حبيب الله he is the one allah loved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 134, NULL, 'And this is an astonishing thing if you reflect on it: the Creator is in love with His created being. What does that say about the character of our Prophet ﷺ, that the Creator loves him in this way? The entire creation is concerned with pleasing Allah, while Allah is concerned with pleasing Rasul Allah ﷺ:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'and this is an astonishing thing if you reflect on it the creator is in love with his created being what does that say about the character of our prophet ﷺ that the creator loves him in this way the entire creation is concerned with pleasing allah while allah is concerned with pleasing rasul allah ﷺ', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the stages of love', 'The Stages Of Love', 135, NULL, 'Ad-Duha: 5وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ', '', 'وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ', 'Ad-Duha: 5', 93, 5, 'surah al fateha the stages of love', 'ad duha 5ولسوف يعطيك ربك فترضي', 'ولسوف يعطيك ربك فترضي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 136, NULL, 'And indeed your master will give you so much that “you” will be well pleased.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'and indeed your master will give you so much that you will be well pleased', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 137, NULL, 'Allah promises His Messenger that He will give him and continue giving him until HE is well pleased. That is the kind of love Allah has for the Messenger, and that is the kind of love the Messenger has for Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'allah promises his messenger that he will give him and continue giving him until he is well pleased that is the kind of love allah has for the messenger and that is the kind of love the messenger has for allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 138, NULL, 'This is why to love the Messenger of Allah is to love Allah, and to love Allah is to love the Messenger of Allah:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is why to love the messenger of allah is to love allah and to love allah is to love the messenger of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 139, NULL, 'Ali ''Imran: 31قُلْ إِن كُنتُمْ تُحِبُّونَ ٱللَّهَ فَٱتَّبِعُونِى يُحْبِبْكُمُ ٱللَّهُSay: “If you love Allah, then follow me; Allah will love you.”', '', NULL, 'Ali ''Imran: 31', NULL, NULL, 'surah al fateha the stages of love', 'ali imran 31قل ان كنتم تحبون الله فاتبعوني يحببكم اللهsay if you love allah then follow me allah will love you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 140, NULL, 'May Allah grant us the مقام of محبۃ, increase us in محبۃ, and make us people of محبۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'may allah grant us the مقام of محبه increase us in محبه and make us people of محبه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 141, NULL, 'The Prophet said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 142, NULL, 'Sayingوللہ لا تَدْخُلَ الجَنَّۃ حتی تؤمنُ۔ ولا تُؤمن حتی تَحابُّ', '', 'وللہ لا تَدْخُلَ الجَنَّۃ حتی تؤمنُ۔ ولا تُؤمن حتی تَحابُّ', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingولله لا تدخل الجنه حتي تومن ولا تومن حتي تحاب', 'ولله لا تدخل الجنه حتي تومن ولا تومن حتي تحاب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 143, NULL, 'You will not enter Paradise until you believe, and you will not believe until you love one another—until you spend on one another and care for one another.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'you will not enter paradise until you believe and you will not believe until you love one another until you spend on one another and care for one another', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the stages of love', 'The Stages Of Love', 144, NULL, 'Ali ''Imran: 92لَن تَنَالُوا۟ ٱلْبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَ', '', 'لَن تَنَالُوا۟ ٱلْبِرَّ حَتَّىٰ تُنفِقُوا۟ مِمَّا تُحِبُّونَ', 'Ali ''Imran: 92', 3, 92, 'surah al fateha the stages of love', 'ali imran 92لن تنالوا البر حتي تنفقوا مما تحبون', 'لن تنالوا البر حتي تنفقوا مما تحبون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 145, NULL, 'You will not attain any good until you spend from that which you love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'you will not attain any good until you spend from that which you love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 146, NULL, 'How much do we spend in the way of Allah? Those who truly believe love Allah more than they love their دنیا:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'how much do we spend in the way of allah those who truly believe love allah more than they love their دنيا', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 147, NULL, 'Sayingوالذین امنو أشدو حب لی اللہ', '', 'والذین امنو أشدو حب لی اللہ', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingوالذين امنو اشدو حب لي الله', 'والذين امنو اشدو حب لي الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 148, NULL, 'Those who believe love Allah more than they love their دنیا.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'those who believe love allah more than they love their دنيا', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 149, NULL, 'And we should think about what people are doing for their دنیا. It is remarkable. We have to ask ourselves whether we are doing even one-tenth for our آخرۃ of what they are doing for their دنیا. Just one-tenth.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'and we should think about what people are doing for their دنيا it is remarkable we have to ask ourselves whether we are doing even one tenth for our اخره of what they are doing for their دنيا just one tenth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 150, NULL, 'They work twelve hours a day, seven days a week, amassing all these goods. People learn the most unusual things simply because they are interested in them. Yet we do not learn Arabic in order to understand our Creator''s Book.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'they work twelve hours a day seven days a week amassing all these goods people learn the most unusual things simply because they are interested in them yet we do not learn arabic in order to understand our creators book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 151, NULL, 'There is an advertisement for learning Italian. It shows a farm boy who is in love with an Italian celebrity. She will be in his town for one evening, so he has one opportunity, one chance to meet her. It is a television advertisement.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'there is an advertisement for learning italian it shows a farm boy who is in love with an italian celebrity she will be in his town for one evening so he has one opportunity one chance to meet her it is a television advertisement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 152, NULL, 'The point is that the advertisers know they are speaking to people who understand that, when you are in love, you will do anything for the beloved. So this boy gets Italian-learning software and tries to learn Italian in a single night just so that he can speak to that celebrity.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the point is that the advertisers know they are speaking to people who understand that when you are in love you will do anything for the beloved so this boy gets italian learning software and tries to learn italian in a single night just so that he can speak to that celebrity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 153, NULL, 'This is what love does. This is what lovers do for the Beloved.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is what love does this is what lovers do for the beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 154, NULL, 'We are loveless people. We want to talk about love, but we do not want to do anything. We do not want to make any effort in the name of love. We do not learn Arabic. We do not take the time to understand the language of our Beloved. We do not want to make the effort to understand the language in which He speaks to His creation.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'we are loveless people we want to talk about love but we do not want to do anything we do not want to make any effort in the name of love we do not learn arabic we do not take the time to understand the language of our beloved we do not want to make the effort to understand the language in which he speaks to his creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 155, NULL, 'We are lazy people. We claim love, but none of it is true. We are false lovers.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'we are lazy people we claim love but none of it is true we are false lovers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 156, NULL, 'But there are lovers. There are true lovers.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'but there are lovers there are true lovers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 157, NULL, 'So if we are not in love, if we cannot be true lovers, then at the very least we should stand in awe of these lovers, such as Rasul Allah ﷺ and Maulana Ali. At least we should wish to love them.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'so if we are not in love if we cannot be true lovers then at the very least we should stand in awe of these lovers such as rasul allah ﷺ and maulana ali at least we should wish to love them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 158, NULL, 'The Arabs say that sometimes the ear falls in love before the eyes do. Sometimes you hear about someone and fall in love with them.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the arabs say that sometimes the ear falls in love before the eyes do sometimes you hear about someone and fall in love with them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 159, NULL, 'I hope that, at some point, we all experience true love. Allah made this عشق, this love in the world, a sign showing us what divine love is. It is a حجۃ against us. Romeo and Juliet are a حجۃ against us. LAILA and MAJNOON are a حجۃ against us.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'i hope that at some point we all experience true love allah made this عشق this love in the world a sign showing us what divine love is it is a حجه against us romeo and juliet are a حجه against us laila and majnoon are a حجه against us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 160, NULL, 'If this is the love of one created being for another created being, then what kind of love should a creature have for his Creator? If these are the depths to which you will go out of love for another human being, then what should be the depth of your efforts for your Creator?', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'if this is the love of one created being for another created being then what kind of love should a creature have for his creator if these are the depths to which you will go out of love for another human being then what should be the depth of your efforts for your creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 161, NULL, 'This pure love is a beautiful thing. People long to be in love. Some want it so badly that they keep falling in love again and again simply for the experience of love. These are foolish people—عُشَّاق—because, as I said, عشق is a disease.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this pure love is a beautiful thing people long to be in love some want it so badly that they keep falling in love again and again simply for the experience of love these are foolish people عشاق because as i said عشق is a disease', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 162, NULL, 'But the cure for love is meeting the beloved. You may long to meet someone so intensely that you will go to the ends of the earth to find that person.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'but the cure for love is meeting the beloved you may long to meet someone so intensely that you will go to the ends of the earth to find that person', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 163, NULL, 'سَلْمَانُ الْفَارِسِیُّ—look at his love. Look at what he did.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'سلمان الفارسي look at his love look at what he did', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 164, NULL, 'He was a man who was unjustly sold into slavery. He was a slave. He traveled far and wide simply to find the Messenger. Whenever he heard of a righteous man, he would go to him and ask about the Prophet. His journey to the Prophet ﷺ is extraordinary.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'he was a man who was unjustly sold into slavery he was a slave he traveled far and wide simply to find the messenger whenever he heard of a righteous man he would go to him and ask about the prophet his journey to the prophet ﷺ is extraordinary', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 165, NULL, 'Because of his sincerity, Allah gave him the signs by which he would recognize the Prophet. The first time he met the Prophet, he brought him dates and said, “This is صدقۃ.” Then he watched as the Prophet did not eat from them, because he had been told that the Prophet would not eat from charity.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'because of his sincerity allah gave him the signs by which he would recognize the prophet the first time he met the prophet he brought him dates and said this is صدقه then he watched as the prophet did not eat from them because he had been told that the prophet would not eat from charity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 166, NULL, 'The next time he came, he brought dates and said, “This is ھدیۃ; it is a gift.” Then the Prophet ate from them. Salman knew. “Ah! Just as I was told.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the next time he came he brought dates and said this is هديه it is a gift then the prophet ate from them salman knew ah just as i was told', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 167, NULL, 'Then Salman became Muslim.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'then salman became muslim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 168, NULL, 'Sayingسَلْمَانُ مِنَّا اَھْلَ الْبَیْتِ', '', 'سَلْمَانُ مِنَّا اَھْلَ الْبَیْتِ', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingسلمان منا اهل البيت', 'سلمان منا اهل البيت');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 169, NULL, 'Look where love takes you. Salman is from my family. He is part of our family.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'look where love takes you salman is from my family he is part of our family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 170, NULL, 'He was an extraordinary man of love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'he was an extraordinary man of love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 171, NULL, 'اَبُو اَیُّوبَ الْاَنْصَارِیُّ—when the Prophet came to Medina, he let go of the reins of his camel because everyone wanted the Prophet to stay with them. The Prophet was an extremely diplomatic person. He did not want to upset or offend anyone. So he said, “I will leave the reins of my camel, and wherever she stops, I will stay with that person.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'ابو ايوب الانصاري when the prophet came to medina he let go of the reins of his camel because everyone wanted the prophet to stay with them the prophet was an extremely diplomatic person he did not want to upset or offend anyone so he said i will leave the reins of my camel and wherever she stops i will stay with that person', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 172, NULL, 'The camel stopped in front of the house of Hz Abu Ayyub Al-Ansari. He rushed forward and took the Prophet''s luggage. The Prophet said, “A man is with his luggage.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the camel stopped in front of the house of hz abu ayyub al ansari he rushed forward and took the prophets luggage the prophet said a man is with his luggage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 173, NULL, 'So Abu Ayyub brought the Prophet into his house and placed him on the lower floor because he wanted to honor him. It was easier to stay on the ground floor than upstairs: there were no stairs to climb, and one could go outside more easily. He wanted to give the Prophet the greatest possible ease, so he housed him downstairs while he and his wife stayed on the floor above.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'so abu ayyub brought the prophet into his house and placed him on the lower floor because he wanted to honor him it was easier to stay on the ground floor than upstairs there were no stairs to climb and one could go outside more easily he wanted to give the prophet the greatest possible ease so he housed him downstairs while he and his wife stayed on the floor above', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 174, NULL, 'But then Abu Ayyub became deeply uneasy. He could hardly walk on the floor above, thinking, “I do not want to place my foot where the Prophet may have rested his head below.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'but then abu ayyub became deeply uneasy he could hardly walk on the floor above thinking i do not want to place my foot where the prophet may have rested his head below', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 175, NULL, 'This is ادب. We no longer have this kind of ادب.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is ادب we no longer have this kind of ادب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 176, NULL, 'So he went and begged the Prophet: “Please, یَا رَسُولَ اللّٰہِ! We cannot stay above you.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'so he went and begged the prophet please يا رسول الله we cannot stay above you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 177, NULL, 'And so the Prophet changed places with him.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'and so the prophet changed places with him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 178, NULL, 'His wife would take food upstairs to the Prophet, and after he had eaten, she would bring the food back. Abu Ayyub would ask her, “Show me where the Messenger''s fingers touched the food,” and then he would eat from that spot.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'his wife would take food upstairs to the prophet and after he had eaten she would bring the food back abu ayyub would ask her show me where the messengers fingers touched the food and then he would eat from that spot', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 179, NULL, 'This is تَـتَـبُّـعُ الْآثَارِ—following the traces. It came from love. These people had so much love for him.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is تتبع الاثار following the traces it came from love these people had so much love for him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 180, NULL, 'Look at میمونۃ, the Prophet''s wife. Thirty years after she married the Prophet, as she was nearing death, do you know where she wanted to go? To the place where she had spent her first night with the Prophet ﷺ. That is where she is buried.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'look at ميمونه the prophets wife thirty years after she married the prophet as she was nearing death do you know where she wanted to go to the place where she had spent her first night with the prophet ﷺ that is where she is buried', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 181, NULL, 'Look at the love. Look at that love. This is what these people had.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'look at the love look at that love this is what these people had', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 182, NULL, 'Today, we want to remove love from Islam and turn the religion into something else. But this religion is nothing if it is not about love:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'today we want to remove love from islam and turn the religion into something else but this religion is nothing if it is not about love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 183, NULL, 'Sayingلَا یُؤْمِنُ اَحَدُکُمْ حَتَّی یُحِبَّ اَخِی', '', 'لَا یُؤْمِنُ اَحَدُکُمْ حَتَّی یُحِبَّ اَخِی', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingلا يومن احدكم حتي يحب اخي', 'لا يومن احدكم حتي يحب اخي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 184, NULL, 'No one is a believer until he loves his brother.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'no one is a believer until he loves his brother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 185, NULL, 'He did not use another word there. He said: until you love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'he did not use another word there he said until you love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 186, NULL, 'Sayingقُلْ اِنْ کُنْتُمْ تُحِبُّونَ اللَّہَ فَتَّبِعُونِی', '', 'قُلْ اِنْ کُنْتُمْ تُحِبُّونَ اللَّہَ فَتَّبِعُونِی', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingقل ان كنتم تحبون الله فتبعوني', 'قل ان كنتم تحبون الله فتبعوني');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 187, NULL, 'Say: If you love Allah, then follow me, and God will love you.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'say if you love allah then follow me and god will love you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 188, NULL, 'Because:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'because', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 189, NULL, 'Sayingعَلَامَۃُ الْحُبِّ اتِّبَاعُ الْحَبِیبِ', '', 'عَلَامَۃُ الْحُبِّ اتِّبَاعُ الْحَبِیبِ', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingعلامه الحب اتباع الحبيب', 'علامه الحب اتباع الحبيب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 190, NULL, 'The sign of love is that you follow the Beloved. You do what the Beloved says.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the sign of love is that you follow the beloved you do what the beloved says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 191, NULL, 'Look at the love of عُوَیْسُ الْقَرَنِیُّ. Look at that man''s love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'look at the love of عويس القرني look at that mans love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 192, NULL, 'When he heard that the Prophet''s tooth had been broken in the battle of احد, he became overwhelmed. What had his Messenger felt? How much pain had his Messenger experienced when they struck him?', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'when he heard that the prophets tooth had been broken in the battle of احد he became overwhelmed what had his messenger felt how much pain had his messenger experienced when they struck him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 193, NULL, 'To experience that pain himself, he pulled out one of his own teeth. But that was not enough. What if it had not been that tooth, but another? So he pulled out another. What if it had been this one? He pulled out another. What if it had been that one? He continued until he had pulled out all of his teeth.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'to experience that pain himself he pulled out one of his own teeth but that was not enough what if it had not been that tooth but another so he pulled out another what if it had been this one he pulled out another what if it had been that one he continued until he had pulled out all of his teeth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 194, NULL, 'That is love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'that is love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 195, NULL, 'These were people of extraordinary intensity. They had عشق. How are we ever going to compare with their love?', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'these were people of extraordinary intensity they had عشق how are we ever going to compare with their love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 196, NULL, 'This is why I say that, if we cannot love Allah, we should try to love those who loved Allah. And if we cannot love them, then we should love those who loved those who loved Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is why i say that if we cannot love allah we should try to love those who loved allah and if we cannot love them then we should love those who loved those who loved allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 197, NULL, 'Love is struggle. When you love, you struggle and you sacrifice. That is the nature of love: you sacrifice for the one you love. If you are not sacrificing, there is no love. It is not real love when everything is only me, me, me.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'love is struggle when you love you struggle and you sacrifice that is the nature of love you sacrifice for the one you love if you are not sacrificing there is no love it is not real love when everything is only me me me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 198, NULL, 'People have gone to extraordinary lengths in love:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'people have gone to extraordinary lengths in love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 199, NULL, 'Sayingأَمُرُّ بِدِّیارِ دِیَارِ لَیلَۃ أُقَبْلُ لم جِدَارُ وَلا الجِدَارَۃ', '', 'أَمُرُّ بِدِّیارِ دِیَارِ لَیلَۃ أُقَبْلُ لم جِدَارُ وَلا الجِدَارَۃ', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingامر بديار ديار ليله اقبل لم جدار ولا الجداره', 'امر بديار ديار ليله اقبل لم جدار ولا الجداره');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 200, NULL, 'Sayingمَا حُبُّ الدِّیَارِ شَغَفْنَا قَلبِی؛ وَلاکِنْ حُبُّ مَنْ سَکَنَ الدِّیَارَۃ', '', 'مَا حُبُّ الدِّیَارِ شَغَفْنَا قَلبِی؛ وَلاکِنْ حُبُّ مَنْ سَکَنَ الدِّیَارَۃ', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingما حب الديار شغفنا قلبي ولاكن حب من سكن الدياره', 'ما حب الديار شغفنا قلبي ولاكن حب من سكن الدياره');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 201, NULL, 'The poet says, did you not ask about that place? About that neighborhood that no longer exists? Did you not ask about the place where لیلۃ used to live?', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'the poet says did you not ask about that place about that neighborhood that no longer exists did you not ask about the place where ليله used to live', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 202, NULL, 'He says: Indeed, I asked. But how can dead stones answer me? Where did everyone go?', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'he says indeed i asked but how can dead stones answer me where did everyone go', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 203, NULL, 'Then he says: I pass by the stones, the dwelling places of my beloved, and I kiss this wall and I kiss that wall.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'then he says i pass by the stones the dwelling places of my beloved and i kiss this wall and i kiss that wall', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 204, NULL, 'And then he says:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'and then he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 205, NULL, 'Sayingمَا حُبُّ الدِّیَارِ شَغَفْنَا قَلبِی', '', 'مَا حُبُّ الدِّیَارِ شَغَفْنَا قَلبِی', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingما حب الديار شغفنا قلبي', 'ما حب الديار شغفنا قلبي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 206, NULL, 'It is not love of the walls that has enraptured my heart, but love of the one who used to live within those walls.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'it is not love of the walls that has enraptured my heart but love of the one who used to live within those walls', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 207, NULL, 'This is why we go and visit these places. It is not the places themselves. It is the Beloved. He was there. That is why we go there: because he walked there.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'this is why we go and visit these places it is not the places themselves it is the beloved he was there that is why we go there because he walked there', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 208, NULL, 'Our religion is a religion of love. Everything we do in our religion must be done out of love, not merely out of fear.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'our religion is a religion of love everything we do in our religion must be done out of love not merely out of fear', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 209, NULL, 'Allah is worthy of fear, but even the fear of Allah should be rooted in love. It is like the fear a child feels at the thought of upsetting or disappointing a parent. That fear is really rooted in pure love. The child loves the parents so deeply that he or she is afraid to upset them.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'allah is worthy of fear but even the fear of allah should be rooted in love it is like the fear a child feels at the thought of upsetting or disappointing a parent that fear is really rooted in pure love the child loves the parents so deeply that he or she is afraid to upset them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 210, NULL, 'That should be our fear of Allah. It should be rooted in love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'that should be our fear of allah it should be rooted in love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 211, NULL, 'Allah is—اللَّہُ اَکْبَرُ—greater than anything that can be said in His praise:', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'allah is الله اكبر greater than anything that can be said in his praise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 212, NULL, 'Sayingلا نُحْصِی الثَّنَاء عَلیکَ۔ اَنتَ کَمَا اَثْنَیتُ عَلی نَفسِکَ', '', 'لا نُحْصِی الثَّنَاء عَلیکَ۔ اَنتَ کَمَا اَثْنَیتُ عَلی نَفسِکَ', 'Saying', NULL, NULL, 'surah al fateha the stages of love', 'sayingلا نحصي الثناء عليك انت كما اثنيت علي نفسك', 'لا نحصي الثناء عليك انت كما اثنيت علي نفسك');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 213, NULL, 'We cannot praise You as You have praised Yourself. You are as You have praised Yourself.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'we cannot praise you as you have praised yourself you are as you have praised yourself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 214, NULL, 'Anything I say about Allah will be deficient.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'anything i say about allah will be deficient', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 215, NULL, 'So we all need to think about our lives. This is our time, and what we do with this time will determine what happens when we leave it. We are all going to depart from this world.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'so we all need to think about our lives this is our time and what we do with this time will determine what happens when we leave it we are all going to depart from this world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 216, NULL, 'It is therefore essential that we ask ourselves: How are we spending our time? What are we doing with it? Are we doing useful and worthwhile things? Beneficial things? Are we drawing closer to Allah? Are we coming to know our Prophet better?', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'it is therefore essential that we ask ourselves how are we spending our time what are we doing with it are we doing useful and worthwhile things beneficial things are we drawing closer to allah are we coming to know our prophet better', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 217, NULL, 'Because he is worth knowing. He is worth studying. The stories about him are worth knowing. His HADDES, his family, his etiquette, and his character are worth knowing. It is worth knowing about his family members—who they were and what they went through.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'because he is worth knowing he is worth studying the stories about him are worth knowing his haddes his family his etiquette and his character are worth knowing it is worth knowing about his family members who they were and what they went through', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the stages of love', 'The Stages Of Love', 218, NULL, 'May Allah guide us all. May He open our hearts and place us all on the path of love.', '', NULL, NULL, NULL, NULL, 'surah al fateha the stages of love', 'may allah guide us all may he open our hearts and place us all on the path of love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 0, NULL, 'I now turn to the Surah. The first آیۃ of سُورَۃُ الْفَاتِحَۃِ is', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'i now turn to the surah the first ايه of سوره الفاتحه is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 1, NULL, 'بِسْمِ اللَّہِ الرَّحْمَنِ الرَّحِیمِ', '', 'بِسْمِ اللَّہِ الرَّحْمَنِ الرَّحِیمِ', NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'بسم الله الرحمن الرحيم', 'بسم الله الرحمن الرحيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 3, NULL, 'I begin with the word اللہ. The word Allah comes from the root word الہ, a term I generally use to mean God. In reality, however, الہ is a very general term, comparable to words such as "book" or "car." There are many kinds of books and cars; neither term is specific. In the same way, there can be many kinds of الہ. English has two kinds of articles: the indefinite article "a," as in "a book" or "a car," and the definite article "the," as in "the book" or "the car."', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'i begin with the word الله the word allah comes from the root word اله a term i generally use to mean god in reality however اله is a very general term comparable to words such as book or car there are many kinds of books and cars neither term is specific in the same way there can be many kinds of اله english has two kinds of articles the indefinite article a as in a book or a car and the definite article the as in the book or the car', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 5, NULL, 'The distinction between "a book" and "the book" is important. "A book" is generic and could refer to any book. But when I say "the book," I am no longer referring to just any book; I have a particular book in mind. The same principle applies to the word الہ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the distinction between a book and the book is important a book is generic and could refer to any book but when i say the book i am no longer referring to just any book i have a particular book in mind the same principle applies to the word اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 7, NULL, 'The word الہ is a generic, indefinite term that may apply to many things. There can be many kinds of الہ, just as there can be many kinds of books. But when the Arabic definite article ال, meaning "the," is attached to it, the combination ال + الہ produces the word اللہ. In other words, اللہ is the specific, definite form of the generic word الہ. At its root, Allah is ال + الہ. By the rules of Arabic grammar, the الف of اللہ is dropped, and the ال merges with the ل and the ہ to become Allah. To understand the linguistic meaning of the word Allah, then, the first step is to understand the meaning of الہ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the word اله is a generic indefinite term that may apply to many things there can be many kinds of اله just as there can be many kinds of books but when the arabic definite article ال meaning the is attached to it the combination ال اله produces the word الله in other words الله is the specific definite form of the generic word اله at its root allah is ال اله by the rules of arabic grammar the الف of الله is dropped and the ال merges with the ل and the ه to become allah to understand the linguistic meaning of the word allah then the first step is to understand the meaning of اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 9, NULL, 'The word الہ is a compound word that carries a range of meanings. A composite word may be compared to a jigsaw puzzle: each piece carries a distinct meaning, and all the pieces together form the complete picture. If الہ carries four meanings — A, B, C, and D — then a full understanding of the word comes from all four taken together. Its meaning is not A alone, nor B alone, nor C or D in isolation. It is A + B + C + D. This is what I mean by a composite word, and the concept is worth keeping firmly in mind because many of the words examined in these pages are composite words of this kind.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the word اله is a compound word that carries a range of meanings a composite word may be compared to a jigsaw puzzle each piece carries a distinct meaning and all the pieces together form the complete picture if اله carries four meanings a b c and d then a full understanding of the word comes from all four taken together its meaning is not a alone nor b alone nor c or d in isolation it is a b c d this is what i mean by a composite word and the concept is worth keeping firmly in mind because many of the words examined in these pages are composite words of this kind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 11, NULL, 'The word الہ carries several distinct meanings, each of which contributes to the whole.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the word اله carries several distinct meanings each of which contributes to the whole', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 13, NULL, 'The primary root is الہ, drawn from اَلَہَ یَعلُہُ. At its core, the verb اَلَہَ means to worship. The first meaning of اَلَہَ, therefore, is: the one who is the object of all worship and obedience.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the primary root is اله drawn from اله يعله at its core the verb اله means to worship the first meaning of اله therefore is the one who is the object of all worship and obedience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 14, NULL, 'Worship itself is an extreme form of gratitude — the highest degree of thankfulness, in which the one who has given becomes so precious and indispensable that the heart is brought to its knees. It is a state of complete surrender when a person''s will yields entirely to the will of the beloved. When that happens, the beloved becomes one''s الہ. This is the first meaning of اَلَہَ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'worship itself is an extreme form of gratitude the highest degree of thankfulness in which the one who has given becomes so precious and indispensable that the heart is brought to its knees it is a state of complete surrender when a persons will yields entirely to the will of the beloved when that happens the beloved becomes ones اله this is the first meaning of اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 15, NULL, 'The principle extends into ordinary life. A person who is so consumed by a career that it is placed above every other person and every competing claim has made that career an الہ. Whatever commands and rules the heart, whatever a person effectively bows before — whether video games, sport, television, children, or wealth — fits this definition. Such things become, in a meaningful sense, an الہ. Likewise, when love for another person becomes so total that it governs every thought, action, and decision, that beloved has become an الہ. For الہ is precisely this: the one worshipped, the one obeyed and submitted to without question.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the principle extends into ordinary life a person who is so consumed by a career that it is placed above every other person and every competing claim has made that career an اله whatever commands and rules the heart whatever a person effectively bows before whether video games sport television children or wealth fits this definition such things become in a meaningful sense an اله likewise when love for another person becomes so total that it governs every thought action and decision that beloved has become an اله for اله is precisely this the one worshipped the one obeyed and submitted to without question', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 17, NULL, 'The word أَلَہَ is also used for a child desperate for its mother''s milk, crying out for it with everything it has — that, too, is اَلِہَ. There is a particular hunger in a baby''s face at such a moment, and a particular intensity in the way it reaches for its mother. That is أَلَہَ: the one to whom a person turns desperately and inevitably, with passion and need, in moments of happiness and grief alike, without restraint or control. That, too, is an أَلَہَ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the word اله is also used for a child desperate for its mothers milk crying out for it with everything it has that too is اله there is a particular hunger in a babys face at such a moment and a particular intensity in the way it reaches for its mother that is اله the one to whom a person turns desperately and inevitably with passion and need in moments of happiness and grief alike without restraint or control that too is an اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 18, NULL, 'Some people are enslaved to sugar; others to cigarettes, drugs, parties, or films. Whatever a person turns to desperately and uncontrollably the moment happiness or depression strikes, whatever becomes the source of relief and comfort, is by this definition their الہ. Peace is sought in its arms. Obedience to it no longer feels like a choice but a compulsion. When the craving commands a person to smoke, the person obeys. When the desire for ice cream becomes irresistible, the person obeys. Watching one more episode or spending hours every day playing video games may cease to be merely casual habits and become acts of total loyalty and devotion, driven by the conviction that happiness and satisfaction are impossible without them. The person turns to these things with the same desperation with which a baby, burning with thirst, turns to its mother.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'some people are enslaved to sugar others to cigarettes drugs parties or films whatever a person turns to desperately and uncontrollably the moment happiness or depression strikes whatever becomes the source of relief and comfort is by this definition their اله peace is sought in its arms obedience to it no longer feels like a choice but a compulsion when the craving commands a person to smoke the person obeys when the desire for ice cream becomes irresistible the person obeys watching one more episode or spending hours every day playing video games may cease to be merely casual habits and become acts of total loyalty and devotion driven by the conviction that happiness and satisfaction are impossible without them the person turns to these things with the same desperation with which a baby burning with thirst turns to its mother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 19, NULL, 'This applies to every one of us. We all have such الہ in our lives. That does not make us horrible people; it makes us human. By learning these meanings, we begin to recognize these masters for what they are. That recognition is the first step toward change.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'this applies to every one of us we all have such اله in our lives that does not make us horrible people it makes us human by learning these meanings we begin to recognize these masters for what they are that recognition is the first step toward change', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 21, NULL, 'The next word is وَلَہَ. It describes someone with whom one is passionately in love — someone one cannot stop thinking about, someone who occupies the mind completely. The derivative وَلَہَ is used when a person is driven to madness by the loss of a beloved. A mother who loses her child is called مُوَلَّا: a mother enduring the excruciating pain and grief of her child''s loss. She is called مُوَلَّا. It is this kind of passionate, consuming love. In Urdu, the expression is وَالِھَانَہَ مُحَبَّتْ — mad love, crazy love — and that, too, comes from وَلَہَ. When someone in one''s life has that kind of hold on the heart — when one thinks of that person constantly, when separation drives one to the edge of reason, when one cannot stop calling or texting, when one repeatedly returns to old photographs and messages, missing that person with every part of oneself — that is the state of وَلَہَ, and by definition that person is one''s الہ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the next word is وله it describes someone with whom one is passionately in love someone one cannot stop thinking about someone who occupies the mind completely the derivative وله is used when a person is driven to madness by the loss of a beloved a mother who loses her child is called مولا a mother enduring the excruciating pain and grief of her childs loss she is called مولا it is this kind of passionate consuming love in urdu the expression is والهانه محبت mad love crazy love and that too comes from وله when someone in ones life has that kind of hold on the heart when one thinks of that person constantly when separation drives one to the edge of reason when one cannot stop calling or texting when one repeatedly returns to old photographs and messages missing that person with every part of oneself that is the state of وله and by definition that person is ones اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 23, NULL, 'The next meaning, أَلِہَ, applies literally — not linguistically — to something on which a person leans, something that bears their full weight. When exhaustion sets in and one leans against something, that supporting thing is literally called أَلِہَ. Thus, if the weight of life rests on finances, property, houses, cars, a job, social standing, friends, neighbors, or children — anything on which one psychologically leans — then each of those things is an الہ. Whatever holds all one''s eggs in a single basket, so to speak, becomes one''s الہ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the next meaning اله applies literally not linguistically to something on which a person leans something that bears their full weight when exhaustion sets in and one leans against something that supporting thing is literally called اله thus if the weight of life rests on finances property houses cars a job social standing friends neighbors or children anything on which one psychologically leans then each of those things is an اله whatever holds all ones eggs in a single basket so to speak becomes ones اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 25, NULL, 'Another derivative of الہ comes from وَلِہَ, which means to become astounded, astonished, or mesmerized. People make role models of actors, musicians, and hip-hop artists. This is especially true of young people who want to be like them, live like them, think like them, dress like them, talk like them, and walk like them. When someone shaves his head to look like Amir Khan in the film Gajni, he has made Amir Khan his الہ. By definition, الہ is the one by whom a person is completely and utterly captivated — the one to imitate, the one to become. It may be a person, an object, a profession, or anything else. Whatever mesmerizes and grips a person so completely that it takes control of their decisions becomes their الہ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'another derivative of اله comes from وله which means to become astounded astonished or mesmerized people make role models of actors musicians and hip hop artists this is especially true of young people who want to be like them live like them think like them dress like them talk like them and walk like them when someone shaves his head to look like amir khan in the film gajni he has made amir khan his اله by definition اله is the one by whom a person is completely and utterly captivated the one to imitate the one to become it may be a person an object a profession or anything else whatever mesmerizes and grips a person so completely that it takes control of their decisions becomes their اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 26, NULL, 'These, then, are the various meanings gathered into the word الہ. Returning to the question: who or what is an الہ?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'these then are the various meanings gathered into the word اله returning to the question who or what is an اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 27, NULL, 'The one worshipped and obeyed is one''s الہ. The one to whom complete devotion and loyalty are given is one''s الہ. The one to whom a person turns in utter desperation, seeking comfort, is one''s الہ. The one a person loves passionately, the one who becomes an obsession, is one''s الہ. The one on whom a person leans for support — physically, mentally, emotionally, or psychologically — is one''s الہ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the one worshipped and obeyed is ones اله the one to whom complete devotion and loyalty are given is ones اله the one to whom a person turns in utter desperation seeking comfort is ones اله the one a person loves passionately the one who becomes an obsession is ones اله the one on whom a person leans for support physically mentally emotionally or psychologically is ones اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 28, NULL, 'This, then, is what the word الہ means. And because الہ is a composite word, it carries the sum of all these meanings at once. The one a person passionately loves is also the one to whom that person is completely devoted; the one on whom they lean; the one to whom they turn desperately for comfort and support. Separation or distance from that person drives them to the edge of sanity. They submit to and obey everything that person says — they worship that person, in the fullest sense described here. All these meanings converge to form a single, complete picture. That is how a composite word works.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'this then is what the word اله means and because اله is a composite word it carries the sum of all these meanings at once the one a person passionately loves is also the one to whom that person is completely devoted the one on whom they lean the one to whom they turn desperately for comfort and support separation or distance from that person drives them to the edge of sanity they submit to and obey everything that person says they worship that person in the fullest sense described here all these meanings converge to form a single complete picture that is how a composite word works', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 29, NULL, 'Given these meanings of الہ, it becomes clear that every person carries numerous الہ in their life, embodying these definitions in countless forms:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'given these meanings of اله it becomes clear that every person carries numerous اله in their life embodying these definitions in countless forms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 30, NULL, 'Some الہ take the form of people — family, friends, children, parents, actors, musicians. Some الہ take the form of objects — houses, cars, one''s own body, jewelry, food, video games, movies. Some الہ take the form of pursuits and compulsions — jobs, careers, recreation, drugs, sex.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'some اله take the form of people family friends children parents actors musicians some اله take the form of objects houses cars ones own body jewelry food video games movies some اله take the form of pursuits and compulsions jobs careers recreation drugs sex', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 31, NULL, 'Every person carries hundreds, if not thousands, of entities in their life that meet the definition of الہ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'every person carries hundreds if not thousands of entities in their life that meet the definition of اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 33, NULL, 'What follows is where the discussion becomes uncomfortable. Every person and thing in our lives that meets the definition of الہ gives physical form to one of the meanings of that word. By definition, الہ is the one to whom we are loyal and devoted; الہ is the one to whom we turn for comfort. So if smoking, movies, or video games are what someone turns to for comfort, those activities become a physical manifestation of that definition of الہ. The definition is conceptual; its manifestation is physical. A person physically does something to please that الہ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'what follows is where the discussion becomes uncomfortable every person and thing in our lives that meets the definition of اله gives physical form to one of the meanings of that word by definition اله is the one to whom we are loyal and devoted اله is the one to whom we turn for comfort so if smoking movies or video games are what someone turns to for comfort those activities become a physical manifestation of that definition of اله the definition is conceptual its manifestation is physical a person physically does something to please that اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 34, NULL, 'Consider another definition: الہ is the one who astounds and astonishes. If Shahrukh Khan, Sylvester Stallone, Adele, Beyonce, or Lady Gaga are the ones who astound, astonish, and impress a person to the point that they want to be like them, then the definition of وَلِھَا has been given a form. That definition has been personified in Shahrukh Khan, Stallone, or whoever else it may be.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'consider another definition اله is the one who astounds and astonishes if shahrukh khan sylvester stallone adele beyonce or lady gaga are the ones who astound astonish and impress a person to the point that they want to be like them then the definition of ولها has been given a form that definition has been personified in shahrukh khan stallone or whoever else it may be', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 36, NULL, 'An idol, by dictionary definition, is an image or representation of a god used as an object of worship — the personification or objectification of someone or something. Idols are human creations. And who personifies and objectifies the definitions of الہ? We do. We decide to turn to smoking, movies, drugs, and alcohol for comfort. We decide to give our complete loyalty and devotion to our jobs, careers, Facebook, and Instagram. We choose to fall passionately in love with wealth, power, and fame. No one makes those choices for us. We make them ourselves. In this sense, we become the creators of our own الہ, just as idols are human-made creations. The similarity is exact.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'an idol by dictionary definition is an image or representation of a god used as an object of worship the personification or objectification of someone or something idols are human creations and who personifies and objectifies the definitions of اله we do we decide to turn to smoking movies drugs and alcohol for comfort we decide to give our complete loyalty and devotion to our jobs careers facebook and instagram we choose to fall passionately in love with wealth power and fame no one makes those choices for us we make them ourselves in this sense we become the creators of our own اله just as idols are human made creations the similarity is exact', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 37, NULL, 'A common assumption is that being Muslim places a person entirely outside the world of idol worship. The frightening reality, according to this understanding, is otherwise. We are surrounded by thousands of الہ — self-created idols — and we worship them daily. Every person, object, concept, and idea that we personify or objectify becomes, through that act, an idol fashioned by our own hands. In that sense, we are all idol-worshippers. It is a painful reality, but it is true. The concept of شرک is not so alien after all. This is precisely why Rasul Allah ﷺ said:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'a common assumption is that being muslim places a person entirely outside the world of idol worship the frightening reality according to this understanding is otherwise we are surrounded by thousands of اله self created idols and we worship them daily every person object concept and idea that we personify or objectify becomes through that act an idol fashioned by our own hands in that sense we are all idol worshippers it is a painful reality but it is true the concept of شرك is not so alien after all this is precisely why rasul allah ﷺ said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 38, NULL, 'Sayingالشِّرکُ فِی أُمَّتِی أَخفٰی مِن سَیرِ النَّمَلِ فِی لَیلَۃِ الظُّلمَۃِ عَلی سَخْرَۃِ السَّوْدَاShirk is more hidden in my nation than the movement of a black ant in a dark night on a black stone.', '', NULL, 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of allah', 'sayingالشرك في امتي اخفي من سير النمل في ليله الظلمه علي سخره السوداshirk is more hidden in my nation than the movement of a black ant in a dark night on a black stone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 39, NULL, 'That is how unaware we may be of our own idol worship.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'that is how unaware we may be of our own idol worship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 40, NULL, 'At the center of all my idols stands one figure: myself. And what drove me to fashion these الہ? My desires. Every idol I have ever built is a product of my passions and caprice; each exists because I wanted it to exist. Allah says:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'at the center of all my idols stands one figure myself and what drove me to fashion these اله my desires every idol i have ever built is a product of my passions and caprice each exists because i wanted it to exist allah says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 41, NULL, 'Al-Furqan: 43أَرَءَيْتَ مَنِ ٱتَّخَذَ إِلَهَهُۥ هَوَىٰهُHave you seen the one who takes his own desire as his god?', '', NULL, 'Al-Furqan: 43', NULL, NULL, 'surah al fateha linguistic meaning of allah', 'al furqan 43ارءيت من اتخذ الهه هواهhave you seen the one who takes his own desire as his god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 42, NULL, 'Allah is asking the messenger ﷺ whether he sees this person — the one who has taken his car, house, job, wealth, fame, and the pleasures and sensations of his body as his الہ; the one who has taken smoking, drugs, alcohol, sex, movies, and video games as his الہ; the one who has taken Shahrukh Khan, Salman Khan, Amir Khan, Adele, and Stallone as his الہ. Allah asks Rasul Allah ﷺ,', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'allah is asking the messenger ﷺ whether he sees this person the one who has taken his car house job wealth fame and the pleasures and sensations of his body as his اله the one who has taken smoking drugs alcohol sex movies and video games as his اله the one who has taken shahrukh khan salman khan amir khan adele and stallone as his اله allah asks rasul allah ﷺ', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 43, NULL, 'Al-Furqan: 43أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلًا', '', 'أَفَأَنتَ تَكُونُ عَلَيْهِ وَكِيلًا', 'Al-Furqan: 43', 25, 43, 'surah al fateha linguistic meaning of allah', 'al furqan 43افانت تكون عليه وكيلا', 'افانت تكون عليه وكيلا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 44, NULL, 'Do you really want to be responsible for this person on the day of judgment?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'do you really want to be responsible for this person on the day of judgment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 45, NULL, 'Worship of the self is the worst form of شرک there is. When gratitude curdles into self-gratification, it becomes the worst kind of شرک. Idolatry has nothing over self-idolatry. We are therefore the ones who continually commit شرک by taking our desires and making them our الہ. Human beings exist in a constant state of self-worship, and it is precisely this condition that prevents us from truly worshipping Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'worship of the self is the worst form of شرك there is when gratitude curdles into self gratification it becomes the worst kind of شرك idolatry has nothing over self idolatry we are therefore the ones who continually commit شرك by taking our desires and making them our اله human beings exist in a constant state of self worship and it is precisely this condition that prevents us from truly worshipping allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 46, NULL, 'This is the default condition of mankind. Islam addresses it at the root: through the negation and destruction of these self-created idols, the understanding of Allah emerges. Allah is لَا اِلَہَ اِلَّا — He is everything other than what is taken as الہ. When every idol born of the desires of the self is broken and destroyed, when the Kaaba of the heart stands empty of them, what is found there is Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'this is the default condition of mankind islam addresses it at the root through the negation and destruction of these self created idols the understanding of allah emerges allah is لا اله الا he is everything other than what is taken as اله when every idol born of the desires of the self is broken and destroyed when the kaaba of the heart stands empty of them what is found there is allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 47, NULL, 'The first act of Rasul Allah ﷺ after the conquest of Mecca was to cleanse the Kaaba of all its idols. Three hundred and sixty-five idols stood in it, around it, and upon it. He destroyed every one without exception. That same exercise must be undertaken in every life. Just as Rasul Allah ﷺ conquered Mecca, the نفس must be conquered. Just as he cleared the Kaaba of its idols one by one, the Kaaba of the heart must gradually be cleared of these idols — one by one. And the greatest and most powerful idol standing in the Kaaba of the heart is the نفس itself: the passions.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the first act of rasul allah ﷺ after the conquest of mecca was to cleanse the kaaba of all its idols three hundred and sixty five idols stood in it around it and upon it he destroyed every one without exception that same exercise must be undertaken in every life just as rasul allah ﷺ conquered mecca the نفس must be conquered just as he cleared the kaaba of its idols one by one the kaaba of the heart must gradually be cleared of these idols one by one and the greatest and most powerful idol standing in the kaaba of the heart is the نفس itself the passions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 48, NULL, 'This is why the creedal formula strikes at the very root of the problem: لَا اِلَٰہَ اِلَّا اللَّہُ. There is no الہ except Allah. No person, thing, concept, principle, or ideology is worthy of being given form — except the one who is free of all form, and that is Allah. Through the negation of self-made idols and the elimination of self-created الہ, the الہ emerges. When the definite article joins الہ, what results is the ultimate الہ, Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'this is why the creedal formula strikes at the very root of the problem لا اله الا الله there is no اله except allah no person thing concept principle or ideology is worthy of being given form except the one who is free of all form and that is allah through the negation of self made idols and the elimination of self created اله the اله emerges when the definite article joins اله what results is the ultimate اله allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 49, NULL, 'The creedal formula لَا اِلَٰہَ اِلَّا اللَّہُ is the act of negating the multiplicity of self-created الہ in order to affirm the one true الہ, Allah. It is the practice of making الہ into ال الہ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the creedal formula لا اله الا الله is the act of negating the multiplicity of self created اله in order to affirm the one true اله allah it is the practice of making اله into ال اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 50, NULL, 'It is the practice of directing every definition of the word الہ toward the one ultimate being — of making Him ال + اللہ, of making Him Allah. It is the work of isolating each definition of الہ and making it specific to Allah alone.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'it is the practice of directing every definition of the word اله toward the one ultimate being of making him ال الله of making him allah it is the work of isolating each definition of اله and making it specific to allah alone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 51, NULL, 'Allah is now the only one I worship and obey. If any other الہ conflicts with His commands, I disobey that الہ in order to obey the ال + الہ, which is Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'allah is now the only one i worship and obey if any other اله conflicts with his commands i disobey that اله in order to obey the ال اله which is allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 52, NULL, 'This does not mean that life cannot be enjoyed. The difference is that Allah now stands at the front and center of my worship and obedience. So long as nothing conflicts with that worship and obedience, I can enjoy life to the fullest.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'this does not mean that life cannot be enjoyed the difference is that allah now stands at the front and center of my worship and obedience so long as nothing conflicts with that worship and obedience i can enjoy life to the fullest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 53, NULL, 'لَا اِلَٰہَ اِلَّا اللَّہُ now means لَا یُعْلَی اِلَّا اللَّہُ: Allah is the only one to whom I am completely devoted and loyal, above everyone else in my life — even my parents, even my children. I serve only Allah and no one else.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'لا اله الا الله now means لا يعلي الا الله allah is the only one to whom i am completely devoted and loyal above everyone else in my life even my parents even my children i serve only allah and no one else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 54, NULL, 'Yet I am glad to serve my parents because Allah has commanded it. I am glad to spend time with my friends, to enjoy life, and to do whatever I wish, so long as my ultimate loyalty and devotion remain with Allah. Whenever anything or anyone challenges that loyalty, I choose Allah over them. That is how I make Him ال + الہ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'yet i am glad to serve my parents because allah has commanded it i am glad to spend time with my friends to enjoy life and to do whatever i wish so long as my ultimate loyalty and devotion remain with allah whenever anything or anyone challenges that loyalty i choose allah over them that is how i make him ال اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 55, NULL, 'لَا اِلَٰہَ اِلَّا اللَّہُ now means لا أَلَہَ الا اللہ: Allah is the only one to whom I turn in utter desperation for every need and every comfort.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'لا اله الا الله now means لا اله الا الله allah is the only one to whom i turn in utter desperation for every need and every comfort', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 56, NULL, 'This does not mean that I cannot seek help from family and friends. Nor does it mean that, when I am hungry and without work, I sit idle because Allah is the appointed provider. Not at all. I turn to whomever I need, for whatever I need. The difference is that I know these people are simply means — أَسْبَاب — through which Allah provides. My ultimate petition, therefore, is always addressed to Him: Ya Allah! I need this. I turn to you for the fulfillment of my needs. Provide me with the means and resources that will fulfill them in a way that pleases you. For it is you, and only you, who are the source of my provision — no one else.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'this does not mean that i cannot seek help from family and friends nor does it mean that when i am hungry and without work i sit idle because allah is the appointed provider not at all i turn to whomever i need for whatever i need the difference is that i know these people are simply means اسباب through which allah provides my ultimate petition therefore is always addressed to him ya allah i need this i turn to you for the fulfillment of my needs provide me with the means and resources that will fulfill them in a way that pleases you for it is you and only you who are the source of my provision no one else', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 57, NULL, 'لَا اِلَٰہَ اِلَّا اللَّہُ now means لا وَلَہَ الا اللہ: Allah is the one I love passionately, the one in whom I am completely absorbed. From the moment I wake until the moment I return to sleep, He is the one I think about.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'لا اله الا الله now means لا وله الا الله allah is the one i love passionately the one in whom i am completely absorbed from the moment i wake until the moment i return to sleep he is the one i think about', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 58, NULL, 'This does not mean that I spend the entire day on the prayer rug or every hour in تسبیح. I may do whatever I wish in life. But everything becomes a sign pointing toward Allah, a reminder of Him. That is what love does: the flower, the rainbow, the sunset, the frog in the pond — all recall the beloved. Love is an obsession. It is a constant connection with the beloved.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'this does not mean that i spend the entire day on the prayer rug or every hour in تسبيح i may do whatever i wish in life but everything becomes a sign pointing toward allah a reminder of him that is what love does the flower the rainbow the sunset the frog in the pond all recall the beloved love is an obsession it is a constant connection with the beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 59, NULL, 'The story of Hazrat أیوب illuminates this. In a hadith of Rasul Allah ﷺ, Allah spoke to His angels about the patience and gratitude of Hazrat أیوب AS. ابلیس then addressed Allah directly, arguing that the only reason أیوب was grateful was because of the abundance he had been given — his wealth and his children. Strip those away, he said, and the gratitude would disappear. So Allah began to take them away. First the wealth went. Then, before his eyes, the house collapsed and killed all his sons. The word that rose instinctively to أیوب''s lips at that sight was AlHamdulillah. And if that were not enough, a terrible disease then descended upon him: his body became infected with worms that consumed his flesh. Allah put Hazrat أیوب through these extreme trials to test his faith and love, and he bore them with extraordinary grace. When the trial was complete, Allah directed him to bathe in a spring prepared for him. He bathed, and the disease was completely cured. Years later, someone asked him: How is your health now, أیوب? He sighed and replied that the days of his illness had been more beloved to him than these days of health. The man was astonished and asked how that could be. أیوب replied that during his illness, Allah had asked him each day: How are you today, أیوب? Now that he was cured, Allah no longer asked, and he missed the love and care that had been showered upon him during those days of trial. This is وَلِھَا. This is مُوَلَّا — extreme, passionate love, in which the absence of the beloved drives a person to the very edge of self.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the story of hazrat ايوب illuminates this in a hadith of rasul allah ﷺ allah spoke to his angels about the patience and gratitude of hazrat ايوب as ابليس then addressed allah directly arguing that the only reason ايوب was grateful was because of the abundance he had been given his wealth and his children strip those away he said and the gratitude would disappear so allah began to take them away first the wealth went then before his eyes the house collapsed and killed all his sons the word that rose instinctively to ايوبs lips at that sight was alhamdulillah and if that were not enough a terrible disease then descended upon him his body became infected with worms that consumed his flesh allah put hazrat ايوب through these extreme trials to test his faith and love and he bore them with extraordinary grace when the trial was complete allah directed him to bathe in a spring prepared for him he bathed and the disease was completely cured years later someone asked him how is your health now ايوب he sighed and replied that the days of his illness had been more beloved to him than these days of health the man was astonished and asked how that could be ايوب replied that during his illness allah had asked him each day how are you today ايوب now that he was cured allah no longer asked and he missed the love and care that had been showered upon him during those days of trial this is ولها this is مولا extreme passionate love in which the absence of the beloved drives a person to the very edge of self', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 60, NULL, 'لَا اِلَٰہَ اِلَّا اللَّہُ now means لا أَلِہَ الا اللہ: Allah is the only one on whom I ultimately lean for support — emotionally, psychologically, financially, physically, in every form.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'لا اله الا الله now means لا اله الا الله allah is the only one on whom i ultimately lean for support emotionally psychologically financially physically in every form', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 61, NULL, 'This does not mean that I will not see a doctor when I am ill, ask my employer for a raise when I deserve one, or turn to family and friends for help when I need it. I will continue to do all of that. But my ultimate support comes from Allah. He is the one who cures my illness, not the doctor. He is the one who ordains the raise, not my employer. He is the one who fulfills my need, not my friends and family.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'this does not mean that i will not see a doctor when i am ill ask my employer for a raise when i deserve one or turn to family and friends for help when i need it i will continue to do all of that but my ultimate support comes from allah he is the one who cures my illness not the doctor he is the one who ordains the raise not my employer he is the one who fulfills my need not my friends and family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 62, NULL, 'The liberation this brings is immense. So many of my complaints about people and life would simply disappear. There is no longer any need to blame someone for a disappointment, because that person was never meant to be the one on whom I ultimately depended in the first place. Disappointment requires expectation. When all my ultimate expectations are from Allah, no one in this world can truly disappoint me. If I receive what I wanted, Allah was the one who gave it. If I do not receive it, it was not meant for me — and who can say that receiving it would not, in the long run, have proved harmful?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the liberation this brings is immense so many of my complaints about people and life would simply disappear there is no longer any need to blame someone for a disappointment because that person was never meant to be the one on whom i ultimately depended in the first place disappointment requires expectation when all my ultimate expectations are from allah no one in this world can truly disappoint me if i receive what i wanted allah was the one who gave it if i do not receive it it was not meant for me and who can say that receiving it would not in the long run have proved harmful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 63, NULL, 'لَا اِلَٰہَ اِلَّا اللَّہُ now means لا وَلِہَ الا اللہ: Allah is the only one who ultimately astounds and impresses me.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'لا اله الا الله now means لا وله الا الله allah is the only one who ultimately astounds and impresses me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 64, NULL, 'This does not mean that I should appreciate no one, praise no one, or find no one impressive. It means that I see Allah behind every cause for praise. If my child does well in school — MashaAllah! Praise to Allah, who made my child capable. If I am mesmerized by the sunrise or sunset — SubhanAllah! Praise to Allah for creating this beauty, and for granting me the eyes, the time, and the willingness to appreciate it. I take the praise inspired by the beauty of the sunset and attribute it to its Creator.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'this does not mean that i should appreciate no one praise no one or find no one impressive it means that i see allah behind every cause for praise if my child does well in school mashaallah praise to allah who made my child capable if i am mesmerized by the sunrise or sunset subhanallah praise to allah for creating this beauty and for granting me the eyes the time and the willingness to appreciate it i take the praise inspired by the beauty of the sunset and attribute it to its creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 65, NULL, 'Through this practice, the true concept of توحید comes into view. توحید is not the idea that Allah is the supreme deity within a hierarchy of deities. It is the recognition that there is no other deity at all. لا الہ — the complete elimination of every other deity. الا اللہ — except the one and only, Allah. It is the transference of الھیۃ from its generic form to the one specific being who has no form. This is the challenge and the goal of لَا اِلَٰہَ اِلَّا اللَّہُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'through this practice the true concept of توحيد comes into view توحيد is not the idea that allah is the supreme deity within a hierarchy of deities it is the recognition that there is no other deity at all لا اله the complete elimination of every other deity الا الله except the one and only allah it is the transference of الهيه from its generic form to the one specific being who has no form this is the challenge and the goal of لا اله الا الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 66, NULL, 'The vehicle that carries a person along this path is Salaat. Within its very nature, Salaat contains the act of breaking idols. The moment the time for prayer arrives, whatever one is doing must stop, whoever one is attending to must be left, and the face must turn toward Allah. Salaat is لَا اِلَٰہَ اِلَّا اللَّہُ enacted.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'the vehicle that carries a person along this path is salaat within its very nature salaat contains the act of breaking idols the moment the time for prayer arrives whatever one is doing must stop whoever one is attending to must be left and the face must turn toward allah salaat is لا اله الا الله enacted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 67, NULL, 'That is the journey of لَا اِلَٰہَ اِلَّا اللَّہُ. It is a difficult journey, and every journey requires provisions to sustain the traveler. The provision for this journey is knowledge of Allah. The greater that knowledge, the greater one''s amazement at His glory. The greater the amazement, the more passionate the love. The more passionate the love, the deeper the absorption. The deeper the absorption, the more complete the worship and submission to His commands. The more complete the worship, the more fully one turns to Him for refuge. The more one finds shelter under His protection, the more one leans on Him for support — for love engenders love. The more one comes to understand how deeply He loves, the more one loves in return. And the more that love grows, the more intensely His blessings and mercy are experienced.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'that is the journey of لا اله الا الله it is a difficult journey and every journey requires provisions to sustain the traveler the provision for this journey is knowledge of allah the greater that knowledge the greater ones amazement at his glory the greater the amazement the more passionate the love the more passionate the love the deeper the absorption the deeper the absorption the more complete the worship and submission to his commands the more complete the worship the more fully one turns to him for refuge the more one finds shelter under his protection the more one leans on him for support for love engenders love the more one comes to understand how deeply he loves the more one loves in return and the more that love grows the more intensely his blessings and mercy are experienced', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 68, NULL, 'Ibrahim: 7وَإِذْ تَأَذَّنَ رَبُّكُمْ لَىِٕن شَكَرْتُمْ لَأَزِيدَنَّكُمْ ۖ وَلَىِٕن كَفَرْتُمْ إِنَّ عَذَابِى لَشَدِيدٌۭAnd when your master proclaimed: "If you are grateful, I will give you more, but if you are ungrateful, indeed! My Punishment is indeed severe."', '', NULL, 'Ibrahim: 7', NULL, NULL, 'surah al fateha linguistic meaning of allah', 'ibrahim 7واذ تاذن ربكم لين شكرتم لازيدنكم ولين كفرتم ان عذابي لشديدand when your master proclaimed if you are grateful i will give you more but if you are ungrateful indeed my punishment is indeed severe', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of allah', 'Linguistic Meaning Of Allah', 69, NULL, 'Salaat is the act of breaking idols. It begins with Wudu — the purification of the very parts of the body used in the service of those idols.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of allah', 'salaat is the act of breaking idols it begins with wudu the purification of the very parts of the body used in the service of those idols', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 0, NULL, 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ الْحَمْدُ لِلَّهِ صَانِعِ الْخَلْقِ عَلَى أَكْمَلِ نِظَامٍ وَأَحْسَنِ قِوَامٍ الْوَادِي عَلَى أَشْرَفِ أَجْدَرِ الْمَقَامِ وَأَرْفَقِ مَسَامٍ وَالصَّلَاةُ وَالسَّلَامُ عَلَى الْمُؤَيَّدِ أَبْلَغِ الْكَلَامِ مُحَمَّدٍ الْمَبْعُوثِ صَلَّى اللَّهُ عَلَيْهِ وَعَلَى آلِهِ وَسَلَّمَ لِهِدَايَتِكَ فَاتِحِ الْأَنَامِ إِلَى سُبُلِ السَّلَامِ وَإِلَى مَا دَلَّ يَالِي وَلَا يَمِّ وَالْحَمْدُ لِلَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُنْ لَهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُنْ لَهُ وَلِيٌّ مِنَ الذُّلِّ وَكَبِّرْهُ تَكْبِيرًا وَالْحَمْدُ لِلَّهِ الَّذِي أَنْزَلَ عَلَى عَبْدِهِ الْكِتَابَ وَلَمْ يَجْعَلْ لَهُ عِوَجًا الْحَمْدُ لِلَّهِ الَّذِي نَحْمَدُهُ وَنَسْتَعِينُهُ وَنَسْتَغْفِرُهُ وَنُؤْمِنُ بِهِ وَنَتَوَكَّلُ عَلَيْهِ وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ وَمَنْ يُضْلِلْهُ فَلَا هَادِيَ لَهُ وَنَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَنَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ أَرْسَلَهُ اللَّهُ تَعَالَى بِالْهُدَى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَكَفَى بِاللَّهِ شَهِيدًا وَنَشْهَدُ أَنَّ مَوْلَانَا عَلِيَّ بْنَ أَبِي طَالِبٍ وَصِيُّهُ وَوَزِيرُهُ فَصَلَّى اللَّهُ عَلَيْهِمْ وَعَلَى آلِهِمْ وَسَلَّمَ عَلَيْهِمْ تَسْلِيمًا كَثِيرًا كَثِيرًا اللَّهُمَّ لَا عِلْمَ لَنَا إِلَّا مَا عَلَّمْتَنَا إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ اللَّهُمَّ عَلِّمْنَا بِمَا يَنْفَعُنَا وَانْفَعْنَا بِمَا عَلَّمْتَنَا اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ عَيْنٍ لَا تَدْمَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ Faamma baadi akkullu سُبْحَانَهُ وَتَعَالَى في كِتابِهِ الكَريمِ baada akkulla أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي اللَّهُمَّ ثَبِّتْنَا عِنْدَ الْمَوْتِ بِلَا إِلَٰهَ إِلَّا اللَّهُ وَاللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ آمِينَ يَا رَبَّ الْعَالَمِينَ', '', 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ الْحَمْدُ لِلَّهِ صَانِعِ الْخَلْقِ عَلَى أَكْمَلِ نِظَامٍ وَأَحْسَنِ قِوَامٍ الْوَادِي عَلَى أَشْرَفِ أَجْدَرِ الْمَقَامِ وَأَرْفَقِ مَسَامٍ وَالصَّلَاةُ وَالسَّلَامُ عَلَى الْمُؤَيَّدِ أَبْلَغِ الْكَلَامِ مُحَمَّدٍ الْمَبْعُوثِ صَلَّى اللَّهُ عَلَيْهِ وَعَلَى آلِهِ وَسَلَّمَ لِهِدَايَتِكَ فَاتِحِ الْأَنَامِ إِلَى سُبُلِ السَّلَامِ وَإِلَى مَا دَلَّ يَالِي وَلَا يَمِّ وَالْحَمْدُ لِلَّهِ الَّذِي لَمْ يَتَّخِذْ وَلَدًا وَلَمْ يَكُنْ لَهُ شَرِيكٌ فِي الْمُلْكِ وَلَمْ يَكُنْ لَهُ وَلِيٌّ مِنَ الذُّلِّ وَكَبِّرْهُ تَكْبِيرًا وَالْحَمْدُ لِلَّهِ الَّذِي أَنْزَلَ عَلَى عَبْدِهِ الْكِتَابَ وَلَمْ يَجْعَلْ لَهُ عِوَجًا الْحَمْدُ لِلَّهِ الَّذِي نَحْمَدُهُ وَنَسْتَعِينُهُ وَنَسْتَغْفِرُهُ وَنُؤْمِنُ بِهِ وَنَتَوَكَّلُ عَلَيْهِ وَنَعُوذُ بِاللَّهِ مِنْ شُرُورِ أَنْفُسِنَا وَمِنْ سَيِّئَاتِ أَعْمَالِنَا مَنْ يَهْدِهِ اللَّهُ فَلَا مُضِلَّ لَهُ وَمَنْ يُضْلِلْهُ فَلَا هَادِيَ لَهُ وَنَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَنَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ أَرْسَلَهُ اللَّهُ تَعَالَى بِالْهُدَى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ وَكَفَى بِاللَّهِ شَهِيدًا وَنَشْهَدُ أَنَّ مَوْلَانَا عَلِيَّ بْنَ أَبِي طَالِبٍ وَصِيُّهُ وَوَزِيرُهُ فَصَلَّى اللَّهُ عَلَيْهِمْ وَعَلَى آلِهِمْ وَسَلَّمَ عَلَيْهِمْ تَسْلِيمًا كَثِيرًا كَثِيرًا اللَّهُمَّ لَا عِلْمَ لَنَا إِلَّا مَا عَلَّمْتَنَا إِنَّكَ أَنْتَ الْعَلِيمُ الْحَكِيمُ اللَّهُمَّ عَلِّمْنَا بِمَا يَنْفَعُنَا وَانْفَعْنَا بِمَا عَلَّمْتَنَا اللَّهُمَّ إِنَّا نَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَمِنْ قَلْبٍ لَا يَخْشَعُ وَمِنْ عَيْنٍ لَا تَدْمَعُ وَمِنْ نَفْسٍ لَا تَشْبَعُ سُبْحَانَهُ وَتَعَالَى في كِتابِهِ الكَريمِ أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي اللَّهُمَّ ثَبِّتْنَا عِنْدَ الْمَوْتِ بِلَا إِلَٰهَ إِلَّا اللَّهُ وَاللَّهُمَّ اجْعَلْنَا مِنَ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ آمِينَ يَا رَبَّ الْعَالَمِينَ', NULL, NULL, NULL, 'surah al fateha what is worship', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم الحمد لله صانع الخلق علي اكمل نظام واحسن قوام الوادي علي اشرف اجدر المقام وارفق مسام والصلاه والسلام علي المويد ابلغ الكلام محمد المبعوث صلي الله عليه وعلي اله وسلم لهدايتك فاتح الانام الي سبل السلام والي ما دل يالي ولا يم والحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا والحمد لله الذي انزل علي عبده الكتاب ولم يجعل له عوجا الحمد لله الذي نحمده ونستعينه ونستغفره ونومن به ونتوكل عليه ونعوذ بالله من شرور انفسنا ومن سييات اعمالنا من يهده الله فلا مضل له ومن يضلله فلا هادي له ونشهد ان لا اله الا الله وحده لا شريك له ونشهد ان محمدا عبد الله ورسوله ارسله الله تعالي بالهدي ودين الحق ليظهره علي الدين كله وكفي بالله شهيدا ونشهد ان مولانا علي بن ابي طالب وصيه ووزيره فصلي الله عليهم وعلي الهم وسلم عليهم تسليما كثيرا كثيرا اللهم لا علم لنا الا ما علمتنا انك انت العليم الحكيم اللهم علمنا بما ينفعنا وانفعنا بما علمتنا اللهم انا نعوذ بك من علم لا ينفع ومن قلب لا يخشع ومن عين لا تدمع ومن نفس لا تشبع faamma baadi akkullu سبحانه وتعالي في كتابه الكريم baada akkulla اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي اللهم ثبتنا عند الموت بلا اله الا الله واللهم اجعلنا من الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر امين يا رب العالمين', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم الحمد لله صانع الخلق علي اكمل نظام واحسن قوام الوادي علي اشرف اجدر المقام وارفق مسام والصلاه والسلام علي المويد ابلغ الكلام محمد المبعوث صلي الله عليه وعلي اله وسلم لهدايتك فاتح الانام الي سبل السلام والي ما دل يالي ولا يم والحمد لله الذي لم يتخذ ولدا ولم يكن له شريك في الملك ولم يكن له ولي من الذل وكبره تكبيرا والحمد لله الذي انزل علي عبده الكتاب ولم يجعل له عوجا الحمد لله الذي نحمده ونستعينه ونستغفره ونومن به ونتوكل عليه ونعوذ بالله من شرور انفسنا ومن سييات اعمالنا من يهده الله فلا مضل له ومن يضلله فلا هادي له ونشهد ان لا اله الا الله وحده لا شريك له ونشهد ان محمدا عبد الله ورسوله ارسله الله تعالي بالهدي ودين الحق ليظهره علي الدين كله وكفي بالله شهيدا ونشهد ان مولانا علي بن ابي طالب وصيه ووزيره فصلي الله عليهم وعلي الهم وسلم عليهم تسليما كثيرا كثيرا اللهم لا علم لنا الا ما علمتنا انك انت العليم الحكيم اللهم علمنا بما ينفعنا وانفعنا بما علمتنا اللهم انا نعوذ بك من علم لا ينفع ومن قلب لا يخشع ومن عين لا تدمع ومن نفس لا تشبع سبحانه وتعالي في كتابه الكريم اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي اللهم ثبتنا عند الموت بلا اله الا الله واللهم اجعلنا من الذين امنوا وعملوا الصالحات وتواصوا بالحق وتواصوا بالصبر امين يا رب العالمين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 1, NULL, 'السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ. In the last session, I tالْفَاتِحَةked about the word إِلَهْ and its various flavors and meanings. We learned that when the definite article the or الْفَاتِحَة in Arabic, when it gets applied to إِلَهْ, it becomes الْإِلٰه. And both of those words then fuse together to form اللَّه. So, الْفَاتِحَةl the various meanings of إِلَهْ then become exclusive for the one that we cالْفَاتِحَةl اللَّه. That''s what the Al does. So now, if I take the meaning of إِلَهْ as a powerful entity that demands submission, then اللَّه becomes the one, the only one for me.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'السلام عليكم ورحمه الله وبركاته in the last session i tالفاتحهked about the word اله and its various flavors and meanings we learned that when the definite article the or الفاتحه in arabic when it gets applied to اله it becomes الاله and both of those words then fuse together to form الله so الفاتحهl the various meanings of اله then become exclusive for the one that we cالفاتحهl الله thats what the al does so now if i take the meaning of اله as a powerful entity that demands submission then الله becomes the one the only one for me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 2, NULL, 'Right? He becomes الْإِلَٰه for me. The only one I deem worthy of my submission. He becomes the only one I must be completely loyالْفَاتِحَة to. Because there is no one more powerful than Him. And it is He who created the heavens and the earth in reالْفَاتِحَةity. And the day He says be, it becomes. His word is the ultimate truth and He has الْفَاتِحَةl dominion on the day the trumpet will be blown. He is the knower of the unseen as well as the seen. And He is wise and He knows everything. And then the same formula applies to the rest of the meanings of إِلَٰه. If we take the meaning of إِلَٰه as seeking protection and refuge, then اللَّه is the only one I exclusively turn to for protection and refuge in desperate times.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'right he becomes الاله for me the only one i deem worthy of my submission he becomes the only one i must be completely loyالفاتحه to because there is no one more powerful than him and it is he who created the heavens and the earth in reالفاتحهity and the day he says be it becomes his word is the ultimate truth and he has الفاتحهl dominion on the day the trumpet will be blown he is the knower of the unseen as well as the seen and he is wise and he knows everything and then the same formula applies to the rest of the meanings of اله if we take the meaning of اله as seeking protection and refuge then الله is the only one i exclusively turn to for protection and refuge in desperate times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 3, NULL, 'If I take إِلَهْ in the meaning of love, then اللَّه becomes the only one I choose to be passionately in love with. He is the only entity, the only deity that I choose to be completely obsessed about. For الْفَاتِحَةl the infinite favors that He bestows upon me, knowing well that I am an extremely ungrateful and unworthy creature, He does not hold back in bestowing His favors upon me. ‏وَآتَىٰكُم مِّن كُلِّ مَا سَأَلْتُمُوهُ ۚ وَإِن تَعُدُّوا۟ نِعْمَتَ ٱللَّهِ لَا تُحْصُوهَآ ۗ إِنَّ ٱلْإِنسَنَ لَظَلُومٌۭ كَفَّارٌۭ ‎. And He gave you of الْفَاتِحَةl that you asked for. And if you try to count the blessings of اللَّه, you will never be able to count them. Indeed, no doubt about it, man is an extreme wrongdoer, a disbeliever, an ungrateful being.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'if i take اله in the meaning of love then الله becomes the only one i choose to be passionately in love with he is the only entity the only deity that i choose to be completely obsessed about for الفاتحهl the infinite favors that he bestows upon me knowing well that i am an extremely ungrateful and unworthy creature he does not hold back in bestowing his favors upon me واتاكم من كل ما سالتموه وان تعدوا نعمت الله لا تحصوها ان الانسن لظلوم كفار and he gave you of الفاتحهl that you asked for and if you try to count the blessings of الله you will never be able to count them indeed no doubt about it man is an extreme wrongdoer a disbeliever an ungrateful being', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 4, NULL, 'Now, if I take the meaning of إِلَهْ in the sense of وَاللَّهَ, of astonishment, then اللَّه becomes the only one whose glory and whose magnificence astonishes me. I reالْفَاتِحَةize that even when I set out to understand Him, when I venture to recognize Him, I do so with the reالْفَاتِحَةization that His loftiness will exhaust my limited capabilities of comprehension and understanding. I will be dumbfounded every single time I attempt to approach Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'now if i take the meaning of اله in the sense of والله of astonishment then الله becomes the only one whose glory and whose magnificence astonishes me i reالفاتحهize that even when i set out to understand him when i venture to recognize him i do so with the reالفاتحهization that his loftiness will exhaust my limited capabilities of comprehension and understanding i will be dumbfounded every single time i attempt to approach him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 5, NULL, 'Because there is just nothing that is comparable to Him. And there are no words that can express His glory. If the sea were to become ink, in order to write the words of my master, indeed the sea would be exhausted before the words of my master would be finished. Even if he brought something similar to the oceans to assist, the words of my master cannot be captured. The praise of my master cannot be captured. So that''s وَالْحَمْدُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'because there is just nothing that is comparable to him and there are no words that can express his glory if the sea were to become ink in order to write the words of my master indeed the sea would be exhausted before the words of my master would be finished even if he brought something similar to the oceans to assist the words of my master cannot be captured the praise of my master cannot be captured so thats والحمد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 6, NULL, 'Finالْفَاتِحَةly, if I take إِلَهْ in the meaning of the one that I lean on for support, then اللَّه becomes the only one that I choose to lean on. He becomes the only one I choose to put my entire weight of الْفَاتِحَةl my spirituالْفَاتِحَة burden on for support. Because His support is the only support that matters. إِن يَنصُرْكُمُ ٱللَّهُ فَلَا غَالِبَ لَكُمْ. If اللَّه helps you, no one can overcome you. And if He forsakes you, then who is there after Him that can help you? And in اللَّه, let الْفَاتِحَةone the believers put their trust.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'finالفاتحهly if i take اله in the meaning of the one that i lean on for support then الله becomes the only one that i choose to lean on he becomes the only one i choose to put my entire weight of الفاتحهl my spirituالفاتحه burden on for support because his support is the only support that matters ان ينصركم الله فلا غالب لكم if الله helps you no one can overcome you and if he forsakes you then who is there after him that can help you and in الله let الفاتحهone the believers put their trust', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 7, NULL, 'So, in other words, there are الْفَاتِحَةl these different meanings, these various rivers of knowledge that flow out of the word إِلَهْ, and they الْفَاتِحَةl then become exclusive. They الْفَاتِحَةl converge into one entity when it reaches the الْإِلَٰه or اللَّه. But the reالْفَاتِحَة question is, what do we get out of the union of الْفَاتِحَةl these meanings of إِلَهْ? So if اللَّه is the only powerful entity deserving submission, if اللَّه is the only one capable of providing refuge and protection, if اللَّه is the only one worthy of passionate love and obsession for my thoughts, and if اللَّه is the only one who astonishes me, astounds me, if اللَّه is the only one I choose to lean and depend on, then the union of الْفَاتِحَةl these meanings of إِلَهْ with its exclusivity of اللَّه, making Him اللَّه, what does the union of these meanings produce for me? What does الْفَاتِحَةl of this mean to me? What does this make اللَّه to me? They make اللَّه worthy of my worship. They make Him worthy of my عِبَادَة.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'so in other words there are الفاتحهl these different meanings these various rivers of knowledge that flow out of the word اله and they الفاتحهl then become exclusive they الفاتحهl converge into one entity when it reaches the الاله or الله but the reالفاتحه question is what do we get out of the union of الفاتحهl these meanings of اله so if الله is the only powerful entity deserving submission if الله is the only one capable of providing refuge and protection if الله is the only one worthy of passionate love and obsession for my thoughts and if الله is the only one who astonishes me astounds me if الله is the only one i choose to lean and depend on then the union of الفاتحهl these meanings of اله with its exclusivity of الله making him الله what does the union of these meanings produce for me what does الفاتحهl of this mean to me what does this make الله to me they make الله worthy of my worship they make him worthy of my عباده', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 8, NULL, 'This is why He created me. And I did not create jinn or the humans except that they should worship me. And this is why He says that. Because the sum of الْفَاتِحَةl these meanings of إِلَهْ, they make Him worthy of my worship. This is why every single day, in every single نَمَاز, I say, ‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‎. It is only you that we worship, and it is only you that we seek help from. This concept of الْإِلٰه, what it leads us to is the idea of worship, the idea of عِبَادَة. And the one we worship is cالْفَاتِحَةled مَعْبُود. We are the عَبْدُ and اللَّه is our مَعْبُود.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'this is why he created me and i did not create jinn or the humans except that they should worship me and this is why he says that because the sum of الفاتحهl these meanings of اله they make him worthy of my worship this is why every single day in every single نماز i say اياك نعبد واياك نستعين it is only you that we worship and it is only you that we seek help from this concept of الاله what it leads us to is the idea of worship the idea of عباده and the one we worship is cالفاتحهled معبود we are the عبد and الله is our معبود', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 9, NULL, 'Now, what is worship? The word عِبَادَة is commonly translated as worship, right? But linguisticالْفَاتِحَةly speaking,', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'now what is worship the word عباده is commonly translated as worship right but linguisticالفاتحهly speaking', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 10, NULL, 'the word عِبَادَة actuالْفَاتِحَةly means a combination of two things. It means to worship and it الْفَاتِحَةso means to obey, both at the same time. They''re not interchangeable like many other words in the English language. No. Both meanings of worship and obedience are embedded inside this one word of عِبَادَة in the Arabic language, in classicالْفَاتِحَة Arabic. Together, they both mean عِبَادَة. You cannot take one meaning out of this word. It is worship and it is obedience.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'the word عباده actuالفاتحهly means a combination of two things it means to worship and it الفاتحهso means to obey both at the same time theyre not interchangeable like many other words in the english language no both meanings of worship and obedience are embedded inside this one word of عباده in the arabic language in classicالفاتحه arabic together they both mean عباده you cannot take one meaning out of this word it is worship and it is obedience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 11, NULL, 'But generالْفَاتِحَةly, when we think of the word worship, what comes to our mind? The five prayers, fasting, paying زَكَاة, performing الحَجّ, right? These are الْفَاتِحَةl different forms and the rituالْفَاتِحَةs of worship.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'but generالفاتحهly when we think of the word worship what comes to our mind the five prayers fasting paying زكاه performing الحج right these are الفاتحهl different forms and the rituالفاتحهs of worship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 12, NULL, 'So it is worship. But these are the rituالْفَاتِحَةs of worship. But what happens is that we think that''s it, and we stop at الْفَاتِحَةl of those activities. And that''s the point that I want to highlight today. The problem with this translation of the word عِبَادَة exclusively in the meaning of worship is that it does not necessarily include the concept of obedience. Especiالْفَاتِحَةly an obedience that stems out of love. That is criticالْفَاتِحَة to understand. That is extremely important to understand. Worship is a love-based obedience. Because the word obedience, it can have a very negative connotation to it, right? Because people can be forced into obedience. Children are often bullied into obedience by the use of either threats or violence.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'so it is worship but these are the rituالفاتحهs of worship but what happens is that we think thats it and we stop at الفاتحهl of those activities and thats the point that i want to highlight today the problem with this translation of the word عباده exclusively in the meaning of worship is that it does not necessarily include the concept of obedience especiالفاتحهly an obedience that stems out of love that is criticالفاتحه to understand that is extremely important to understand worship is a love based obedience because the word obedience it can have a very negative connotation to it right because people can be forced into obedience children are often bullied into obedience by the use of either threats or violence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 13, NULL, 'So it is possible for obedience to have a very negative emotion attached to it. But this is not the kind of obedience that we''re tالْفَاتِحَةking about here when we say عِبَادَة. عِبَادَة is an obedience that comes naturالْفَاتِحَةly from the appreciation of الْفَاتِحَةl these various meanings of إِلَهْ that we learned. When we choose to love اللَّه passionately, when we choose to become obsessed about Him, when we are completely devoted and loyالْفَاتِحَة to Him, when we completely trust Him and lean upon Him, When we''re totالْفَاتِحَةly impressed and amazed by His loftiness, His greatness, His magnificence, when we know that we can الْفَاتِحَةways unconditionالْفَاتِحَةly turn to Him for protection and refuge, then the naturالْفَاتِحَة outcome of the sum of الْفَاتِحَةl of these love-based emotions is obedience. So remember that عِبَادَة is an obedience that stems out of love. It is a lover''s obedience to make the beloved happy. And this is why اللَّه created us. And this is why He gave us this ability to love. He did not create us and desire disobedience from us. He الْفَاتِحَةlows disobedience. His magnificence enables this capability of disobedience within His creation because disobedience is a product of free will.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'so it is possible for obedience to have a very negative emotion attached to it but this is not the kind of obedience that were tالفاتحهking about here when we say عباده عباده is an obedience that comes naturالفاتحهly from the appreciation of الفاتحهl these various meanings of اله that we learned when we choose to love الله passionately when we choose to become obsessed about him when we are completely devoted and loyالفاتحه to him when we completely trust him and lean upon him when were totالفاتحهly impressed and amazed by his loftiness his greatness his magnificence when we know that we can الفاتحهways unconditionالفاتحهly turn to him for protection and refuge then the naturالفاتحه outcome of the sum of الفاتحهl of these love based emotions is obedience so remember that عباده is an obedience that stems out of love it is a lovers obedience to make the beloved happy and this is why الله created us and this is why he gave us this ability to love he did not create us and desire disobedience from us he الفاتحهlows disobedience his magnificence enables this capability of disobedience within his creation because disobedience is a product of free will', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 14, NULL, 'which is cالْفَاتِحَةled خِذْلَان. But اللَّه is not content with it, because disobedience is completely contrary to the concept of love. You know, there''s a poet by the name of محمُودٌ الوَرَّاقُ, and in one of his poems he says, You disobey اللَّه and then you feign the love of God? This is an impossible and unknown kind of logic. Had your love been sincere, you would have been obedient. Because a lover is الْفَاتِحَةways obedient to the one he loves. So, it is the nature of love that we want to obey the one that we love. In another one of his poems, he says, . You know, a woman once asked someone about the state of this person who loves her with this burning passion. عَاشِق is the one who is burning up with passion. Right?', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'which is cالفاتحهled خذلان but الله is not content with it because disobedience is completely contrary to the concept of love you know theres a poet by the name of محمود الوراق and in one of his poems he says you disobey الله and then you feign the love of god this is an impossible and unknown kind of logic had your love been sincere you would have been obedient because a lover is الفاتحهways obedient to the one he loves so it is the nature of love that we want to obey the one that we love in another one of his poems he says you know a woman once asked someone about the state of this person who loves her with this burning passion عاشق is the one who is burning up with passion right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 15, NULL, 'They say, دَوَاءُ الْعِشْقِ الِاتِّصَالُ. The only cure for عِشْق is to be connected with the beloved, to be in the embrace of the beloved. So, she''s tالْفَاتِحَةking about this man, she''s asking about this man who loves her, and she''s inquiring about his love for her. And this is something that lovers do, right? They want to know, they inquire from others about how much their beloved loves them. So, she asks this man, لِلَّهِ صِفْهُ، وَلَا تَنْقُصْ وَلَا تَزِدِ. For اللهِ sake, describe him to me and don''t stint in your description and don''t exaggerate. In other words, you know, I want to know the truth. I want to hear the truth. So, this man, he says, لَوْ كَانَ رَحْلِيلُ الْمَوْتِ بِالدُّمَاءِ. If your lover thought that he would die from thirst, وَقُتِيَ قِيفَانَ وُرُودَ الْمَاءِ لَمْ يَرِدِ. And if you said don''t touch that water, he wouldn''t touch it.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'they say دواء العشق الاتصال the only cure for عشق is to be connected with the beloved to be in the embrace of the beloved so shes tالفاتحهking about this man shes asking about this man who loves her and shes inquiring about his love for her and this is something that lovers do right they want to know they inquire from others about how much their beloved loves them so she asks this man لله صفه ولا تنقص ولا تزد for الله sake describe him to me and dont stint in your description and dont exaggerate in other words you know i want to know the truth i want to hear the truth so this man he says لو كان رحليل الموت بالدماء if your lover thought that he would die from thirst وقتي قيفان ورود الماء لم يرد and if you said dont touch that water he wouldnt touch it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 16, NULL, 'So her lover knows that he is going to die of thirst, but if the woman said don''t touch that water, he wouldn''t touch it. He''d rather die than disobey. So the point of that, what he''s emphasizing there is that the nature of love is obedience. So the more you love اللَّه, the more you will want to obey Him. So عِبَادَة to اللَّه has these two concepts embedded within it: worship and obedience. Both of which stem out of this passionate love for Him and not from some kind of forced compulsion or coercion. And to put this in practicالْفَاتِحَة terms, to give you an example, let''s say, you know, we are about to pray in 15 minutes, right? Let''s say it''s فَجْر time. And so we have to pray. We have to do our عِبَادَة. We have to go through the rituالْفَاتِحَة of prayer.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'so her lover knows that he is going to die of thirst but if the woman said dont touch that water he wouldnt touch it hed rather die than disobey so the point of that what hes emphasizing there is that the nature of love is obedience so the more you love الله the more you will want to obey him so عباده to الله has these two concepts embedded within it worship and obedience both of which stem out of this passionate love for him and not from some kind of forced compulsion or coercion and to put this in practicالفاتحه terms to give you an example lets say you know we are about to pray in 15 minutes right lets say its فجر time and so we have to pray we have to do our عباده we have to go through the rituالفاتحه of prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 17, NULL, 'Now, what kind of عِبَادَة is prayer, صَلَاةٌ? Is it worship or is it obedience? It''s worship, right? But then from فَجْر الْفَاتِحَةl the way up till ظُهْر, we will not be worshipping him through this rituالْفَاتِحَة of prayer, but if we are sincere in our love for him, we will be doing what? We will be obeying him. We will be in a state of obedience with him. Because it is the dream and the desire of every lover to make their beloved happy. And so the beauty of this word عِبَادَة is that it covers the entire spectrum of love, putting us in a constant state of worship. You see, when we are performing the rituالْفَاتِحَة acts of صَلَاةٌ, we are in a state of عِبَادَة. But then when we are in between two prayers, by being in a state of obedience, we are still in the state of عِبَادَة. You see, this is why', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'now what kind of عباده is prayer صلاه is it worship or is it obedience its worship right but then from فجر الفاتحهl the way up till ظهر we will not be worshipping him through this rituالفاتحه of prayer but if we are sincere in our love for him we will be doing what we will be obeying him we will be in a state of obedience with him because it is the dream and the desire of every lover to make their beloved happy and so the beauty of this word عباده is that it covers the entire spectrum of love putting us in a constant state of worship you see when we are performing the rituالفاتحه acts of صلاه we are in a state of عباده but then when we are in between two prayers by being in a state of obedience we are still in the state of عباده you see this is why', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 18, NULL, 'The concept of عِبَادَة is so comprehensive in Islam. We are constantly in a state of worship, if not through the formالْفَاتِحَة rituالْفَاتِحَةs, then through obedience. So what this means is that if you go in the morning and earn a حَلَالٌ income through your job, that is an act of obedience, that is an act of عِبَادَة. When you go to school and you sincerely accomplish the purpose of education, you''re in a state of عِبَادَة, you''re worshiping. When you love and respect your elders, when you are kind to your siblings, when you''re generous to the needy, when you''re courageous in the face of temptations, no matter what you do, as long as you''re in a state of obedience and servitude to اللَّه, anything and everything that you do becomes an act of عِبَادَة. It becomes worship. It turns into worship.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'the concept of عباده is so comprehensive in islam we are constantly in a state of worship if not through the formالفاتحه rituالفاتحهs then through obedience so what this means is that if you go in the morning and earn a حلال income through your job that is an act of obedience that is an act of عباده when you go to school and you sincerely accomplish the purpose of education youre in a state of عباده youre worshiping when you love and respect your elders when you are kind to your siblings when youre generous to the needy when youre courageous in the face of temptations no matter what you do as long as youre in a state of obedience and servitude to الله anything and everything that you do becomes an act of عباده it becomes worship it turns into worship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 19, NULL, 'Going to the toilet becomes عِبَادَة. Imagine that. When you go to the toilet to relieve yourself, if you obey the commands of اللَّه to cover your head and feet and seek His protection and recite الْفَاتِحَةl those دُعَاءٌ, you''re in a state of عِبَادَة. So you can see that this concept of worship, of عِبَادَة, is reالْفَاتِحَةly incredible in Islam. And may اللَّه give us الْفَاتِحَةl the strength and تَوْفِيق to become His obedient slaves and to fulfill the purpose of our creation.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'going to the toilet becomes عباده imagine that when you go to the toilet to relieve yourself if you obey the commands of الله to cover your head and feet and seek his protection and recite الفاتحهl those دعاء youre in a state of عباده so you can see that this concept of worship of عباده is reالفاتحهly incredible in islam and may الله give us الفاتحهl the strength and توفيق to become his obedient slaves and to fulfill the purpose of our creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 20, NULL, 'جِلَاءً...', '', 'جِلَاءً', NULL, NULL, NULL, 'surah al fateha what is worship', 'جلاء', 'جلاء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'what is worship?', 'What is Worship?', 21, NULL, 'وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتَمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ، وَعَلَى أَخِيهِ وَوَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ، وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِمَا الطَّيِّبِينَ الطَّاهِرِينَ، وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ، الْفَاتِحَة', '', 'وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتَمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ، وَعَلَى أَخِيهِ وَوَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ، وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِمَا الطَّيِّبِينَ الطَّاهِرِينَ، وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ، الْفَاتِحَة', NULL, NULL, NULL, 'surah al fateha what is worship', 'واخر دعوانا ان الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد خاتم النبيين وسيد المرسلين وعلي اخيه ووصيه علي بن ابي طالب اشرف الوصيين وعلي الايمه من ذريتهما الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه', 'واخر دعوانا ان الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد خاتم النبيين وسيد المرسلين وعلي اخيه ووصيه علي بن ابي طالب اشرف الوصيين وعلي الايمه من ذريتهما الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 0, NULL, 'I have studied composite words such as الہ and رب. The word الہ combines several meanings derived from:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'i have studied composite words such as اله and رب the word اله combines several meanings derived from', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 1, NULL, 'اَلَہَ یَعلُہُ, signifying the one worthy of worship. أَلَہَ, which describes a child yearning for its mother''s milk, representing the one we desperately turn to for our needs. وَلَہَ, indicating the one we passionately love. أَلِہَ, meaning the one we rely on or place our trust in. وَلِہَ, which expresses being astounded by someone''s glory and magnificence.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'اله يعله signifying the one worthy of worship اله which describes a child yearning for its mothers milk representing the one we desperately turn to for our needs وله indicating the one we passionately love اله meaning the one we rely on or place our trust in وله which expresses being astounded by someones glory and magnificence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 2, NULL, 'I combine all these meanings to understand الہ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'i combine all these meanings to understand اله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 3, NULL, 'I then discussed our creedal formula of لَا اِلٰہَ اِلَّا اللَّہُ. This formula aims to eliminate the multiplicity of generic objects of worship, represented by الہ, and to identify the one specific object of worship, الہ. This involves applying the definite article "the" to الہ, which then becomes ال, الہ, or اللہ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'i then discussed our creedal formula of لا اله الا الله this formula aims to eliminate the multiplicity of generic objects of worship represented by اله and to identify the one specific object of worship اله this involves applying the definite article the to اله which then becomes ال اله or الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 4, NULL, 'Next, I examined the word رب, which is also a composite word, combining', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'next i examined the word رب which is also a composite word combining', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 5, NULL, 'Sayingأَلْمَالِكُ وَالسَّيِّدُ وَالْمُرَبِّي وَالْمُرْشِدُ وَالْمُنْعِمُ وَالْقَيِّمُ', '', 'أَلْمَالِكُ وَالسَّيِّدُ وَالْمُرَبِّي وَالْمُرْشِدُ وَالْمُنْعِمُ وَالْقَيِّمُ', 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'sayingالمالك والسيد والمربي والمرشد والمنعم والقيم', 'المالك والسيد والمربي والمرشد والمنعم والقيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 6, NULL, 'المَالِکُ: The absolute owner. السَّیِّد: The one with complete authority. المُرَبِّی: The one who nourishes. المُرْشَدُ: The one who guides and puts to purpose. المُنعِمُ: The benevolent benefactor; the one who showers with undeserved gifts. القَیِّمُ: The maintainer.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'المالك the absolute owner السيد the one with complete authority المربي the one who nourishes المرشد the one who guides and puts to purpose المنعم the benevolent benefactor the one who showers with undeserved gifts القيم the maintainer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 7, NULL, 'Combining the meanings of all these words leads to an understanding of the word رب, which I translate as master.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'combining the meanings of all these words leads to an understanding of the word رب which i translate as master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 8, NULL, 'I then looked at the concept of عبد, which, from a Quranic perspective, means a "free slave." To understand this relationship, I examined the master-slave relationship of this world. I then compared it to the master-slave relationship that Allah has with us, concluding that even though Allah is our master, he is unlike any other master we have encountered in this world.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'i then looked at the concept of عبد which from a quranic perspective means a free slave to understand this relationship i examined the master slave relationship of this world i then compared it to the master slave relationship that allah has with us concluding that even though allah is our master he is unlike any other master we have encountered in this world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 10, NULL, 'I now examine the word رحمۃ. This is the primary attribute of Allah, and it is an attribute most dear to him. This quality is so fundamental to him that he has made it obligatory upon himself. Allah has imposed certain obligations on Muslims, such as prayers, fasting, zakah, and Hajj. He has made many actions compulsory for Muslims. However, he has made one action compulsory upon himself: the action of his mercy, his رحمۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'i now examine the word رحمه this is the primary attribute of allah and it is an attribute most dear to him this quality is so fundamental to him that he has made it obligatory upon himself allah has imposed certain obligations on muslims such as prayers fasting zakah and hajj he has made many actions compulsory for muslims however he has made one action compulsory upon himself the action of his mercy his رحمه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 11, NULL, 'In a hadith, Rasul Allah ﷺ says:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'in a hadith rasul allah ﷺ says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 12, NULL, 'Prophetic traditionإنَّ الله لَمَّا قَضٰى الخَلق،كَتَبَ فَوقَ عَرْشُه اِنَّ رَحمَتِی تَغلِبُ غَضَبِیIndeed, after Allah established all his creation, he wrote on his throne, "Indeed my mercy shall overcome my wrath"', '', NULL, 'Prophetic tradition', NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'prophetic traditionان الله لما قضي الخلق كتب فوق عرشه ان رحمتي تغلب غضبيindeed after allah established all his creation he wrote on his throne indeed my mercy shall overcome my wrath', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 13, NULL, 'Indeed, when Allah established all of creation, he wrote a statement on his throne. This statement was:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'indeed when allah established all of creation he wrote a statement on his throne this statement was', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 14, NULL, 'Prophetic traditionاِنَّ رَحمَتِی تَغلِبُ غَضَبِیIndeed, my رحمۃ—my mercy for my creation—will always overcome my wrath.', '', NULL, 'Prophetic tradition', NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'prophetic traditionان رحمتي تغلب غضبيindeed my رحمه my mercy for my creation will always overcome my wrath', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 15, NULL, 'In other words, in my dealings with creation, my mercy will always supersede my anger. This is a rule that our Almighty Creator imposed upon himself in his dealings with us. SubhanAllah! This statement is not literal; there is no actual physical throne. Rather, it is a graphic representation of an emotion, depicting Allah''s love for his creation.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'in other words in my dealings with creation my mercy will always supersede my anger this is a rule that our almighty creator imposed upon himself in his dealings with us subhanallah this statement is not literal there is no actual physical throne rather it is a graphic representation of an emotion depicting allahs love for his creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 16, NULL, 'I now turn to the word رحمۃ. It is a very powerful word. I will first examine the general definition of the word رحمۃ. A more graphic representation of the word will follow, to help visualize this concept properly, InshaAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'i now turn to the word رحمه it is a very powerful word i will first examine the general definition of the word رحمه a more graphic representation of the word will follow to help visualize this concept properly inshaallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 17, NULL, 'The word رحمۃ is generally translated in English as "mercy." This translation, however, distorts the word''s true meaning. I do not claim it is incorrect, but rather that it is a weak rendering. The reason is that the word "mercy" is generally used when someone is spared from punishment. When one hears the words, "the soldiers showed mercy," it implies they possessed the power to inflict something terrible but chose to spare everyone. The criminal begged the judge for mercy, meaning he asked to be spared from punishment. Thus, the general understanding of "mercy" involves an impending negative or painful event, from which someone then decides to withhold the action. This is what it means to show mercy. Therefore, a subconscious association with punishment exists when the word mercy is used, coupled with the idea of escaping that punishment. When I consider mercy, the underlying assumption is often punishment.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'the word رحمه is generally translated in english as mercy this translation however distorts the words true meaning i do not claim it is incorrect but rather that it is a weak rendering the reason is that the word mercy is generally used when someone is spared from punishment when one hears the words the soldiers showed mercy it implies they possessed the power to inflict something terrible but chose to spare everyone the criminal begged the judge for mercy meaning he asked to be spared from punishment thus the general understanding of mercy involves an impending negative or painful event from which someone then decides to withhold the action this is what it means to show mercy therefore a subconscious association with punishment exists when the word mercy is used coupled with the idea of escaping that punishment when i consider mercy the underlying assumption is often punishment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 18, NULL, 'When I consistently use the word "mercy" for Allah, carrying that subconscious taint of escaping punishment, and repeat it frequently, it subtly creates the impression that Allah intended to inflict something harmful upon us, but then He decided against it. This implies He showed us mercy by not punishing us. This fosters a subtle, subconscious image of Allah as a tyrant in some sense— نَعُوذُ بِاللّٰہِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'when i consistently use the word mercy for allah carrying that subconscious taint of escaping punishment and repeat it frequently it subtly creates the impression that allah intended to inflict something harmful upon us but then he decided against it this implies he showed us mercy by not punishing us this fosters a subtle subconscious image of allah as a tyrant in some sense نعوذ بالله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 19, NULL, 'In reality, this is not the true intent of the word رحمۃ. The word رحمۃ has absolutely nothing to do with punishment. It contains no concept of punishment. I will now examine the linguistic meaning of the word رحمۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'in reality this is not the true intent of the word رحمه the word رحمه has absolutely nothing to do with punishment it contains no concept of punishment i will now examine the linguistic meaning of the word رحمه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 20, NULL, 'Definition of rehma', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'definition of rehma', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 21, NULL, 'In classical Arabic, رحمۃ has four meanings:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'in classical arabic رحمه has four meanings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 22, NULL, 'Unconditional love Care Genuine concern Mercy', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'unconditional love care genuine concern mercy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 23, NULL, 'Mercy is the final piece of this puzzle, not the initial one. Unconditional love comes first, followed by care, then concern, and finally mercy. This is رحمۃ. These four words are self-explanatory. Unconditional love is affection without conditions. Allah loves His creation unconditionally, like a mother who loves all her children equally, regardless of their obedience or disobedience. It does not matter to her regarding her love for them. Allah loves us in the same way, and this is fitting. We are all His creation, after all. He created us with His own hands.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'mercy is the final piece of this puzzle not the initial one unconditional love comes first followed by care then concern and finally mercy this is رحمه these four words are self explanatory unconditional love is affection without conditions allah loves his creation unconditionally like a mother who loves all her children equally regardless of their obedience or disobedience it does not matter to her regarding her love for them allah loves us in the same way and this is fitting we are all his creation after all he created us with his own hands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 24, NULL, 'Allah is caring. He looks after us, provides for us, and fulfills all our needs.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'allah is caring he looks after us provides for us and fulfills all our needs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 25, NULL, 'He is genuinely and sincerely concerned for our salvation, happiness, and well-being.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'he is genuinely and sincerely concerned for our salvation happiness and well being', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 26, NULL, 'Finally, Allah is merciful, in that He shows compassion toward our weakness. He graciously forgives our sins and transgressions, and He accepts our weak and feeble acts of worship, even though they may lack the sincerity and honor He deserves.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'finally allah is merciful in that he shows compassion toward our weakness he graciously forgives our sins and transgressions and he accepts our weak and feeble acts of worship even though they may lack the sincerity and honor he deserves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 27, NULL, 'So رحمۃ combines these four words: unconditional love, extreme care, genuine concern, and mercy. Linguistically speaking, the word رحمۃ means to show love, care, concern, and mercy for the purpose of benefiting someone. The ancient Arab would say:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'so رحمه combines these four words unconditional love extreme care genuine concern and mercy linguistically speaking the word رحمه means to show love care concern and mercy for the purpose of benefiting someone the ancient arab would say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 28, NULL, 'Sayingالرحمۃُ، رِقَّۃٌ تَقتَدِ الأحسانُ أِلی المَرحوم', '', 'الرحمۃُ، رِقَّۃٌ تَقتَدِ الأحسانُ أِلی المَرحوم', 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'sayingالرحمه رقه تقتد الاحسان الي المرحوم', 'الرحمه رقه تقتد الاحسان الي المرحوم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 29, NULL, 'رحمۃ signifies a form of love or tenderness specifically intended to benefit the beloved. In other words, رحمۃ is precisely targeted toward someone''s welfare and must manifest as a beneficial action; otherwise, it is not رحمۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'رحمه signifies a form of love or tenderness specifically intended to benefit the beloved in other words رحمه is precisely targeted toward someones welfare and must manifest as a beneficial action otherwise it is not رحمه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 31, NULL, '2 Manifestations', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', '2 manifestations', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 32, NULL, 'I find two common manifestations of this word رحمۃ in the Quran: الرحمن and الرحیم. Both originate from the word رحمۃ. I will first examine how these words are commonly translated. English translations of بِسْمِ اللَّہِ الرَّحْمَٰنِ الرَّحِیمِ often render the phrase as:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'i find two common manifestations of this word رحمه in the quran الرحمن and الرحيم both originate from the word رحمه i will first examine how these words are commonly translated english translations of بسم الله الرحمن الرحيم often render the phrase as', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 33, NULL, '"In the name of Allah – the most gracious, the most merciful." "In the name of Allah – the most beneficent, the most merciful." "The most merciful, the most kind." "The merciful, the beneficent." "The beneficent, the beneficent."', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'in the name of allah the most gracious the most merciful in the name of allah the most beneficent the most merciful the most merciful the most kind the merciful the beneficent the beneficent the beneficent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 34, NULL, 'The difficulty with these translations lies in how challenging these words are to process and visualize in English. The word "beneficent," for instance, rarely appears in everyday English conversation. One would not typically use it to express gratitude for assistance, saying, "You are so beneficent." The fundamental purpose of translation is to enhance understanding of the text. However, employing words in translation that are unfamiliar or unrelatable to the reader undermines this very purpose.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'the difficulty with these translations lies in how challenging these words are to process and visualize in english the word beneficent for instance rarely appears in everyday english conversation one would not typically use it to express gratitude for assistance saying you are so beneficent the fundamental purpose of translation is to enhance understanding of the text however employing words in translation that are unfamiliar or unrelatable to the reader undermines this very purpose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 35, NULL, 'I will first clarify the meaning of these two words. As I said, both الرحمن and الرحیم are manifestations of the word رحمۃ. The word رحمۃ signifies a combination of four elements, all intended to benefit someone:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'i will first clarify the meaning of these two words as i said both الرحمن and الرحيم are manifestations of the word رحمه the word رحمه signifies a combination of four elements all intended to benefit someone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 36, NULL, 'Unconditional love Care Genuine concern Mercy', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'unconditional love care genuine concern mercy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 37, NULL, 'When Allah is called الرحمن and الرحیم, I acknowledge these four qualities of Allah. This means that Allah has intense love for us; He cares for us; He is genuinely concerned for us; and He shows us mercy. This is the implicit acknowledgment in any word that derives from رحمۃ. Allah states this point repeatedly in the Quran:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'when allah is called الرحمن and الرحيم i acknowledge these four qualities of allah this means that allah has intense love for us he cares for us he is genuinely concerned for us and he shows us mercy this is the implicit acknowledgment in any word that derives from رحمه allah states this point repeatedly in the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 38, NULL, 'Al-Qasas: 73وَمِن رَّحْمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ', '', 'وَمِن رَّحْمَتِهِۦ جَعَلَ لَكُمُ ٱلَّيْلَ وَٱلنَّهَارَ', 'Al-Qasas: 73', 28, 73, 'surah al fateha linguistic meaning of rehma', 'al qasas 73ومن رحمته جعل لكم اليل والنهار', 'ومن رحمته جعل لكم اليل والنهار');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 39, NULL, 'Out of His love, He created the night and the day:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'out of his love he created the night and the day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 40, NULL, 'Al-Kahf: 16مِّن رَّحْمَتِهِۦ وَيُهَيِّئْ لَكُم مِّنْ أَمْرِكُم مِّرْفَقًۭا', '', 'مِّن رَّحْمَتِهِۦ وَيُهَيِّئْ لَكُم مِّنْ أَمْرِكُم مِّرْفَقًۭا', 'Al-Kahf: 16', 18, 16, 'surah al fateha linguistic meaning of rehma', 'al kahf 16من رحمته ويهيي لكم من امركم مرفقا', 'من رحمته ويهيي لكم من امركم مرفقا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 41, NULL, 'Out of His love, He will make our tasks easy for us.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'out of his love he will make our tasks easy for us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 42, NULL, 'وَمِنْ آيَتِهِۦٓ أَن يُرْسِلَ ٱلرِّيَاحَ مُبَشِّرَتٍۢ وَلِيُذِيقَكُم مِّن رَّحْمَتِهِ Out of His love, He sends the winds that deliver good tidings, so that one recognizes His love. مَّا يَفْتَحِ ٱللَّهُ لِلنَّاسِ مِن رَّحْمَةٍۢ فَلَا مُمْسِكَ لَهَاۖ When Allah opens the doors of His love for someone, nothing can close them.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'ومن ايته ان يرسل الرياح مبشرت وليذيقكم من رحمته out of his love he sends the winds that deliver good tidings so that one recognizes his love ما يفتح الله للناس من رحمه فلا ممسك لها when allah opens the doors of his love for someone nothing can close them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 43, NULL, 'The purpose of all such verses is to explain one thing. I discussed Allah as our Master. When one considers the word "master" in the worldly sense, or the word "authority," the last thing that comes to mind in a master-slave relationship is unconditional love. But Allah immediately reminds us, at the beginning of every recitation: بِسْمِ اللَّہِ الرَّحْمَٰنِ الرَّحِیمِ. He reminds us that He is a different kind of Master. He reminds us that one will never, ever find a master in this world as powerful as Allah, yet one who possesses the kind of رحمۃ that He does. SubhanAllah!', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'the purpose of all such verses is to explain one thing i discussed allah as our master when one considers the word master in the worldly sense or the word authority the last thing that comes to mind in a master slave relationship is unconditional love but allah immediately reminds us at the beginning of every recitation بسم الله الرحمن الرحيم he reminds us that he is a different kind of master he reminds us that one will never ever find a master in this world as powerful as allah yet one who possesses the kind of رحمه that he does subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 44, NULL, 'No other master in this world will show unconditional love to their slaves. They might take care of their slaves once in a while, but they will never truly love them. Masters will always show love to their own kin, never to their slave. But this Master—our Master, Allah—the very first emotion He exhibits toward us is unconditional love. No other master will care for us the way Allah cares for us. No other master will be genuinely concerned about us, the way Allah is concerned for us. No other master will show us mercy when one disobeys them and fails to complete the task to their standards. But Allah always has mercy on us.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'no other master in this world will show unconditional love to their slaves they might take care of their slaves once in a while but they will never truly love them masters will always show love to their own kin never to their slave but this master our master allah the very first emotion he exhibits toward us is unconditional love no other master will care for us the way allah cares for us no other master will be genuinely concerned about us the way allah is concerned for us no other master will show us mercy when one disobeys them and fails to complete the task to their standards but allah always has mercy on us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 46, NULL, 'I will now explain the linguistic meanings of the words الرحمن and الرحیم. This understanding, God willing, will be profound and will deepen one''s appreciation of Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'i will now explain the linguistic meanings of the words الرحمن and الرحيم this understanding god willing will be profound and will deepen ones appreciation of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 47, NULL, 'The word رحمن follows a specific phonetic pattern that conveys intensification, ferocity, severity, and extreme force. Any Arabic word following this phonetic pattern, آن, shares these characteristics. Examples include:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'the word رحمن follows a specific phonetic pattern that conveys intensification ferocity severity and extreme force any arabic word following this phonetic pattern ان shares these characteristics examples include', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 48, NULL, 'غضبان (extremely angry; intensely angry) جوعان (extremely hungry; ferociously hungry) عطشان (extremely thirsty)', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'غضبان extremely angry intensely angry جوعان extremely hungry ferociously hungry عطشان extremely thirsty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 49, NULL, 'Following this same pattern, the word رحمن means "extremely merciful" or "intensely merciful."', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'following this same pattern the word رحمن means extremely merciful or intensely merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 50, NULL, 'Rehman', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'rehman', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 51, NULL, 'Any word that follows this phonetic pattern possesses three characteristics:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'any word that follows this phonetic pattern possesses three characteristics', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 52, NULL, 'It is extreme. It is immediate. It is temporary.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'it is extreme it is immediate it is temporary', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 53, NULL, 'All words matching this pattern consistently possess these three characteristics: they are extreme, immediate, and temporary.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'all words matching this pattern consistently possess these three characteristics they are extreme immediate and temporary', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 54, NULL, 'The word رحمن signifies Allah''s love, care, concern, and mercy. This is not merely love as humans understand it; rather, it is an extreme and intense form of love, care, concern, and mercy that transcends human imagination or any worldly example. Thus, the first characteristic of الرحمن is that any love, care, concern, and mercy one anticipates from Allah will surpass all human imagination and expectation. No example of such love can be found in this world.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'the word رحمن signifies allahs love care concern and mercy this is not merely love as humans understand it rather it is an extreme and intense form of love care concern and mercy that transcends human imagination or any worldly example thus the first characteristic of الرحمن is that any love care concern and mercy one anticipates from allah will surpass all human imagination and expectation no example of such love can be found in this world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 55, NULL, 'The second meaning of الرحمن is that it is something happening immediately. One does not have to wait for it; it is occurring right now. I consider this point by observing a distinction in English between someone who is patient and someone who is being patient. The latter demonstrates patience in the present moment. For example, if I state that a woman is patient, I cannot determine if she is currently losing patience with her children. She might be yelling at them, or she might be throwing them against the wall; I do not know that. When I say a woman is patient, I mean she is generally a patient person. This does not necessarily mean she is acting patiently at this very second. However, when I say, "she is being patient," I refer to her present state: right now.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'the second meaning of الرحمن is that it is something happening immediately one does not have to wait for it it is occurring right now i consider this point by observing a distinction in english between someone who is patient and someone who is being patient the latter demonstrates patience in the present moment for example if i state that a woman is patient i cannot determine if she is currently losing patience with her children she might be yelling at them or she might be throwing them against the wall i do not know that when i say a woman is patient i mean she is generally a patient person this does not necessarily mean she is acting patiently at this very second however when i say she is being patient i refer to her present state right now', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 56, NULL, 'The love and care of الرحمن does not manifest generally or at some distant point in time. Rather, that extreme and intense form of love is happening right now. In other words, through الرحمن, the Quran teaches that one does not have to wait for Allah to show one love at some future point in time. One does not have to wait for Him to care for one, or be concerned for one at a later point in time when some event occurs, or when one is in the middle of a calamity. No, this is not so. All of that is happening right now. He loves one right now. He cares for one right now. He is genuinely concerned for one right now, and He is being merciful to one right now.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'the love and care of الرحمن does not manifest generally or at some distant point in time rather that extreme and intense form of love is happening right now in other words through الرحمن the quran teaches that one does not have to wait for allah to show one love at some future point in time one does not have to wait for him to care for one or be concerned for one at a later point in time when some event occurs or when one is in the middle of a calamity no this is not so all of that is happening right now he loves one right now he cares for one right now he is genuinely concerned for one right now and he is being merciful to one right now', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 57, NULL, 'All of that is happening, in its extreme form, right now. The first characteristic of الرحمن is its extreme nature, and the second is its immediacy. The third is its temporary quality. The love of الرحمن is extreme, intense, and immediate, but it is temporary; it is not permanent. This third aspect, its temporary nature, may be difficult to accept initially, and it can feel counterintuitive. I will explain the reasoning shortly.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'all of that is happening in its extreme form right now the first characteristic of الرحمن is its extreme nature and the second is its immediacy the third is its temporary quality the love of الرحمن is extreme intense and immediate but it is temporary it is not permanent this third aspect its temporary nature may be difficult to accept initially and it can feel counterintuitive i will explain the reasoning shortly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 58, NULL, 'Thus, الرحمن carries three essential qualities:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'thus الرحمن carries three essential qualities', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 59, NULL, 'Extreme Immediate Temporary', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'extreme immediate temporary', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 60, NULL, 'All words following this phonetic pattern share these three characteristics.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'all words following this phonetic pattern share these three characteristics', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 61, NULL, 'As an example, I offer غضبان. This term signifies extreme anger, present at that very moment. However, this extreme anger must be temporary. An individual cannot physically sustain such intense rage indefinitely; it would be physically impossible, potentially leading to collapse or even death. Even a figure of immense rage eventually calms.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'as an example i offer غضبان this term signifies extreme anger present at that very moment however this extreme anger must be temporary an individual cannot physically sustain such intense rage indefinitely it would be physically impossible potentially leading to collapse or even death even a figure of immense rage eventually calms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 62, NULL, 'Similarly, جوعان denotes extreme hunger, present at that moment, yet temporary. This is because one either eats, and the hunger subsides, or one starves, and the hunger ceases with life itself. In neither scenario does the hunger persist permanently.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'similarly جوعان denotes extreme hunger present at that moment yet temporary this is because one either eats and the hunger subsides or one starves and the hunger ceases with life itself in neither scenario does the hunger persist permanently', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 63, NULL, 'Likewise, عتشان signifies extreme thirst, present at that moment, yet temporary. One either drinks, alleviating the thirst, or succumbs to it. The thirst does not endure indefinitely.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'likewise عتشان signifies extreme thirst present at that moment yet temporary one either drinks alleviating the thirst or succumbs to it the thirst does not endure indefinitely', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 64, NULL, 'Allah''s intense mercy is temporary because we would not be able to handle the intensity and severity of His love for a long period. I offer an example that illustrates this point clearly. I recall moments with a mother in a very cuddly and huggy mood. She wraps her arms around me and squeezes until I cannot breathe, saying, "أو میرا بیٹا! أو میری بیٹی - Mua Mua Mua." My face is left dripping wet after this display. This is a manifestation of intense love, a burst of affection a mother showers. This intense love is a beautiful thing when one feels:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'allahs intense mercy is temporary because we would not be able to handle the intensity and severity of his love for a long period i offer an example that illustrates this point clearly i recall moments with a mother in a very cuddly and huggy mood she wraps her arms around me and squeezes until i cannot breathe saying او ميرا بيتا او ميري بيتي mua mua mua my face is left dripping wet after this display this is a manifestation of intense love a burst of affection a mother showers this intense love is a beautiful thing when one feels', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 65, NULL, 'down, depressed, or in need of serious TLC.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'down depressed or in need of serious tlc', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 66, NULL, 'One would appreciate such intense love. However, if this were to happen every time one walked by the mother, with her saying, "أو میرا بیٹا! أو میری بیٹی - Mua Mua Mua," every single time, one would not be able to tolerate it. One would feel annoyed and irritated. The natural reaction would be to exclaim, "Mom!!! Leave me alone! Stop marinating my face with your saliva every time I walk by!"', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'one would appreciate such intense love however if this were to happen every time one walked by the mother with her saying او ميرا بيتا او ميري بيتي mua mua mua every single time one would not be able to tolerate it one would feel annoyed and irritated the natural reaction would be to exclaim mom leave me alone stop marinating my face with your saliva every time i walk by', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 67, NULL, 'Allah''s intense love is extreme and immediate, but it is temporary. If His love were constant, its intensity and severity would prevent us from functioning. We would literally go insane; we would lose our minds.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'allahs intense love is extreme and immediate but it is temporary if his love were constant its intensity and severity would prevent us from functioning we would literally go insane we would lose our minds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 68, NULL, 'Story of Eisa and the Rabi.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'story of eisa and the rabi', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 70, NULL, 'Raheem', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'raheem', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 71, NULL, 'The next word I consider is الرحیم. Allah''s love, care, concern, and mercy also manifest through the word رحیم. The word رحیم, and all others following its phonetic pattern—کَرِیمٌ، سَلِیمٌ، حَکِیمٌ، جَمِیلٌ، جَلِیلٌ—possess two distinct qualities:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'the next word i consider is الرحيم allahs love care concern and mercy also manifest through the word رحيم the word رحيم and all others following its phonetic pattern كريم سليم حكيم جميل جليل possess two distinct qualities', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 72, NULL, 'First, it is permanent, not temporary. Second, it is not necessarily immediate; its manifestation is long-term. For instance, if I describe my aunt as loving, I refer to a lasting quality. This does not imply she is actively demonstrating that love at this precise moment. She might not be showering me with affection right now, yet I remain certain her love is always present.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'first it is permanent not temporary second it is not necessarily immediate its manifestation is long term for instance if i describe my aunt as loving i refer to a lasting quality this does not imply she is actively demonstrating that love at this precise moment she might not be showering me with affection right now yet i remain certain her love is always present', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 74, NULL, 'Throughout the Quran, I observe that الرحمن is consistently mentioned before الرحیم. This consistent pairing prompts an inquiry into why these two words are always used together.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'throughout the quran i observe that الرحمن is consistently mentioned before الرحيم this consistent pairing prompts an inquiry into why these two words are always used together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 75, NULL, 'If Allah had used only الرحمن, His love, care, concern, and mercy would have been extreme and immediate, yet not permanent. Conversely, if Allah had used only الرحیم, His love and mercy would have been permanent, but not extreme. How, then, can I describe Allah''s love, care, concern, and mercy as simultaneously extreme, beyond expectations, immediate, permanent, and long-term? The only way to express these combined qualities is through الرحمن and الرحیم. SubhanAllah! No better terms exist to describe the qualities of Allah''s love and care than الرحمن and الرحیم.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'if allah had used only الرحمن his love care concern and mercy would have been extreme and immediate yet not permanent conversely if allah had used only الرحيم his love and mercy would have been permanent but not extreme how then can i describe allahs love care concern and mercy as simultaneously extreme beyond expectations immediate permanent and long term the only way to express these combined qualities is through الرحمن and الرحيم subhanallah no better terms exist to describe the qualities of allahs love and care than الرحمن and الرحيم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 76, NULL, 'I offer an example to illustrate this point. You are at work. Today is pay day. Your boss is not there at the office; and you have a flight booked to Timbuktu for 6:00 p.m. This means you need to leave the office exactly at 5:00 o''clock or you will not make it to the airport. It is already 4:45 p.m., and you still have not received your paycheck. For some reason, you desperately need your paycheck, because that money is for your trip. You were counting on this paycheck for the expenses of your trip. So now you are getting desperate. It is 4:50 p.m. now, and your boss is still not there. You are getting extremely anxious. Your co-worker says to you: "Don''t worry. Our boss is reliable. He''ll be here. You''ll get your paycheck. Don''t worry! Relax!!" Now it is 4:55 p.m., and you are totally freaking out. Your co-worker is still telling you: "Don''t worry! He''s reliable! He''ll be here." What might be said to the co-worker at that moment? A rude response is to be avoided; such an utterance would be highly impolite.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'i offer an example to illustrate this point you are at work today is pay day your boss is not there at the office and you have a flight booked to timbuktu for 6 00 p m this means you need to leave the office exactly at 5 00 oclock or you will not make it to the airport it is already 4 45 p m and you still have not received your paycheck for some reason you desperately need your paycheck because that money is for your trip you were counting on this paycheck for the expenses of your trip so now you are getting desperate it is 4 50 p m now and your boss is still not there you are getting extremely anxious your co worker says to you dont worry our boss is reliable hell be here youll get your paycheck dont worry relax now it is 4 55 p m and you are totally freaking out your co worker is still telling you dont worry hes reliable hell be here what might be said to the co worker at that moment a rude response is to be avoided such an utterance would be highly impolite', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 77, NULL, 'You''ll say, "I know he is reliable, but I need him to be reliable right now, this very minute! I need his quality of reliability immediately." When I am in serious trouble, my need for Allah''s help is immediate. Therefore, I need the name of Allah that provides immediate assistance. That name is الرحمن.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'youll say i know he is reliable but i need him to be reliable right now this very minute i need his quality of reliability immediately when i am in serious trouble my need for allahs help is immediate therefore i need the name of allah that provides immediate assistance that name is الرحمن', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 78, NULL, 'However, I also need the other name, الرحیم, because it addresses my future. When Allah says الرحیم, it signifies permanence, which guarantees the future. Thus, الرحمن guarantees His love, care, concern, and mercy for the present, while الرحیم guarantees these same qualities for the future. In other words, the attributes of الرحمن and الرحیم encompass both short-term and long-term aspects of His love.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'however i also need the other name الرحيم because it addresses my future when allah says الرحيم it signifies permanence which guarantees the future thus الرحمن guarantees his love care concern and mercy for the present while الرحيم guarantees these same qualities for the future in other words the attributes of الرحمن and الرحيم encompass both short term and long term aspects of his love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 79, NULL, 'I offer another example. Teenagers may find this example particularly relatable. I return home, intensely hungry. I had missed breakfast, and too much work at the office prevented me from having lunch. Thus, I arrive home starving. I sit at the dining table, and my wife asks, "So what do you want me to cook for next week?" I respond, "Woman! Who cares about next week? Give me something to eat right now!" When one is extremely hungry, the sole thought is of the immediate present. Once I have finished eating my dinner tonight and I go, "BURP. Aaaah. AlHamdulillah!" only then do I become interested in what we are eating next week.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'i offer another example teenagers may find this example particularly relatable i return home intensely hungry i had missed breakfast and too much work at the office prevented me from having lunch thus i arrive home starving i sit at the dining table and my wife asks so what do you want me to cook for next week i respond woman who cares about next week give me something to eat right now when one is extremely hungry the sole thought is of the immediate present once i have finished eating my dinner tonight and i go burp aaaah alhamdulillah only then do i become interested in what we are eating next week', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 80, NULL, 'Only after paying this month''s bills does one begin to worry about next month''s. Similarly, only after paying this semester''s fees does one start to consider next semester''s. Thus, we consider the future only when our immediate concerns have been addressed. Allah says I am الرحمن. I am taking care of your immediate needs right now. But when your immediate concerns are taken care of, I will also be الرحیم to take care of all your future concerns.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'only after paying this months bills does one begin to worry about next months similarly only after paying this semesters fees does one start to consider next semesters thus we consider the future only when our immediate concerns have been addressed allah says i am الرحمن i am taking care of your immediate needs right now but when your immediate concerns are taken care of i will also be الرحيم to take care of all your future concerns', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 81, NULL, 'Someone once asked أَبْنُ عَبَّاسٍ رَضِیَ اللہُ عَنْہُ about the difference between الرحمن and الرحیم. He said, "Allah is الرحمن in this life, and He is الرحیم in the afterlife." This is because Allah''s love and care will cease for disbelievers on the Day of Judgment. Until that day, however, He is الرحمن for both believers and disbelievers. He is الرحمن for all of us—every human being. In other words, the الرحمن does not only love and care for me or for you. He loves and cares for every single being He ever created: plants, animals, and humans. This includes people of every religion, color, or race, whether Muslim or non-Muslim. He even loves and cares for those who hate Him and deny His existence. His doors of رحمنیۃ are always open to everyone. He constantly hopes they will choose to return to Him. His invitation never expires, because الرحمن is a universal quality.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'someone once asked ابن عباس رضي الله عنه about the difference between الرحمن and الرحيم he said allah is الرحمن in this life and he is الرحيم in the afterlife this is because allahs love and care will cease for disbelievers on the day of judgment until that day however he is الرحمن for both believers and disbelievers he is الرحمن for all of us every human being in other words the الرحمن does not only love and care for me or for you he loves and cares for every single being he ever created plants animals and humans this includes people of every religion color or race whether muslim or non muslim he even loves and cares for those who hate him and deny his existence his doors of رحمنيه are always open to everyone he constantly hopes they will choose to return to him his invitation never expires because الرحمن is a universal quality', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 82, NULL, 'Sayingرَحْمَتِی وَسِعَتْ عَلَیٰ کُلِّ شَیْءٍ', '', 'رَحْمَتِی وَسِعَتْ عَلَیٰ کُلِّ شَیْءٍ', 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'sayingرحمتي وسعت علي كل شيء', 'رحمتي وسعت علي كل شيء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 83, NULL, 'My mercy extends to all. Rain descends from the sky for all human beings to drink, and from it, they all draw their sustenance.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'my mercy extends to all rain descends from the sky for all human beings to drink and from it they all draw their sustenance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 84, NULL, 'The good drink, and the wretched drink. The sinner drinks, and the pious drinks. The friend of Allah drinks, and the enemy of Allah drinks. The scholar drinks, and the ignorant drinks.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'the good drink and the wretched drink the sinner drinks and the pious drinks the friend of allah drinks and the enemy of allah drinks the scholar drinks and the ignorant drinks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 85, NULL, 'Everybody drinks! This is the universal mercy of this world.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'everybody drinks this is the universal mercy of this world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 86, NULL, 'Sayingمَا مِنْ يَوْمٍ إِلَّا وَالْبَحْرُ يَسْتَأْذِنُ رَبَّهُ فِي أَنْ يُغْرِقَ ابْنَ آدَمَ، وَالْأَرْضُ تَسْتَأْذِنُ فِي أَنْ تَبْتَلِعَهُ، وَالْمَلَائِكَةُ تَسْتَأْذِنُ فِي أَنْ تُعَاجِلَهُ وَتُهْلِكَهُ.', '', 'مَا مِنْ يَوْمٍ إِلَّا وَالْبَحْرُ يَسْتَأْذِنُ رَبَّهُ فِي أَنْ يُغْرِقَ ابْنَ آدَمَ، وَالْأَرْضُ تَسْتَأْذِنُ فِي أَنْ تَبْتَلِعَهُ، وَالْمَلَائِكَةُ تَسْتَأْذِنُ فِي أَنْ تُعَاجِلَهُ وَتُهْلِكَهُ.', 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'sayingما من يوم الا والبحر يستاذن ربه في ان يغرق ابن ادم والارض تستاذن في ان تبتلعه والملايكه تستاذن في ان تعاجله وتهلكه', 'ما من يوم الا والبحر يستاذن ربه في ان يغرق ابن ادم والارض تستاذن في ان تبتلعه والملايكه تستاذن في ان تعاجله وتهلكه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 87, NULL, 'Not a single day passes without the ocean asking its Master, "Ya Allah! Give me permission to drown these disbelievers! They enjoy your blessings and rebel against you?! Let me teach them a lesson!"', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'not a single day passes without the ocean asking its master ya allah give me permission to drown these disbelievers they enjoy your blessings and rebel against you let me teach them a lesson', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 88, NULL, 'والارضُ یَستَئذِنُ فی أَن تَبتَلِعَہُ The earth begs its Master, "Oh Ya Allah! Allow me to swallow them alive where they stand. They walk on your earth, eat its produce that you grow for them, and yet do not prostrate before you in abject humiliation?! Let me remove them from the face of this earth!"', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'والارض يستيذن في ان تبتلعه the earth begs its master oh ya allah allow me to swallow them alive where they stand they walk on your earth eat its produce that you grow for them and yet do not prostrate before you in abject humiliation let me remove them from the face of this earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 89, NULL, 'والملائکۃ یَستَئذِنُ فی ان تُعاَجِلَہُ وَ تُھلِکُہ The angels say, "..... Ya Allah, give us permission! We will destroy them! We will annihilate them!"', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'والملايكه يستيذن في ان تعاجله و تهلكه the angels say ya allah give us permission we will destroy them we will annihilate them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 90, NULL, 'The ocean, the earth, and the angels—these are all creations of Allah, just as I am. They observe my sins and rebellion, growing furious. But what does the Creator say, the One against whom I rebel?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'the ocean the earth and the angels these are all creations of allah just as i am they observe my sins and rebellion growing furious but what does the creator say the one against whom i rebel', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 91, NULL, 'Sayingدَعُوا عَبْدِي فَأَنَا أَعْلَمُ بِعَبْدِي مِنْكُمْ. إِنْ كَانَ عَبْدَكُمْ فَشَأْنُكُمْ بِهِ. وَإِنْ كَانَ عَبْدِي فَمِنِّي وَإِلَيَّ عَبْدِي.', '', 'دَعُوا عَبْدِي فَأَنَا أَعْلَمُ بِعَبْدِي مِنْكُمْ. إِنْ كَانَ عَبْدَكُمْ فَشَأْنُكُمْ بِهِ. وَإِنْ كَانَ عَبْدِي فَمِنِّي وَإِلَيَّ عَبْدِي.', 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'sayingدعوا عبدي فانا اعلم بعبدي منكم ان كان عبدكم فشانكم به وان كان عبدي فمني والي عبدي', 'دعوا عبدي فانا اعلم بعبدي منكم ان كان عبدكم فشانكم به وان كان عبدي فمني والي عبدي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 92, NULL, 'Let them be! Leave them alone! I love my creation way more than that. If they are your creation, do whatever you please with them! But if they are my creation, then hand them over to me, and you step out of the way. I will deal with my creation!', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'let them be leave them alone i love my creation way more than that if they are your creation do whatever you please with them but if they are my creation then hand them over to me and you step out of the way i will deal with my creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 93, NULL, 'Sayingیَسْأَلُ الْمَلَائِکَۃَ: فلماذا عقدُہُ؟', '', 'یَسْأَلُ الْمَلَائِکَۃَ: فلماذا عقدُہُ؟', 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'sayingيسال الملايكه فلماذا عقده', 'يسال الملايكه فلماذا عقده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 94, NULL, 'The angels ask: What are you waiting for?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'the angels ask what are you waiting for', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 95, NULL, 'یَسْتَجِیبُ اللَّہُ: إنني أتطَّلِع إلى التوبتَہُ I am waiting for their repentance. أِنْ اَتَانِی نَھَارًا قَبِلْتُہُ أِنْ اَتَانِی لَیْلًا قَبِلْتُہُ If he approaches me during the day time, I will accept him; if he approaches me during the night time I will accept him. مَن تَقَرَّبَ أِلَیَّ تَلَقَّیتُہُ مِن بَعِید If anyone takes one single step toward me, I approach him by running toward him.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'يستجيب الله انني اتطلع الي التوبته i am waiting for their repentance ان اتاني نهارا قبلته ان اتاني ليلا قبلته if he approaches me during the day time i will accept him if he approaches me during the night time i will accept him من تقرب الي تلقيته من بعيد if anyone takes one single step toward me i approach him by running toward him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 96, NULL, 'وَمَنْ أَعْرَضَ عَنِّي نَادَيْتُهُ مِنْ قَرِيبٍ. أَوَلَكَ رَبٌّ غَيْرِي؟And if anyone walks away from me, I go after him to bring him closer and ask him: Do you have another master who is more loving than me?الْحَسَنَةُ عِنْدِي بِعَشْرِ أَمْثَالِهَا وَأَزِيدُDo you not know that I take one good deed from you and reward you ten times for it, even more?وَوَصِيَّةٌ عِنْدِي بِمِثْلِهَا وَأَعْفُو وَأَغْفِرُBut I count your sin as a single sin, and when you repent, I even forgive that and reward you for your repentance.فَأَيْنَ تَذْهَبُونَThen where are you going?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'ومن اعرض عني ناديته من قريب اولك رب غيري and if anyone walks away from me i go after him to bring him closer and ask him do you have another master who is more loving than me الحسنه عندي بعشر امثالها وازيدdo you not know that i take one good deed from you and reward you ten times for it even more ووصيه عندي بمثلها واعفو واغفرbut i count your sin as a single sin and when you repent i even forgive that and reward you for your repentance فاين تذهبونthen where are you going', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rehma', 'Linguistic Meaning Of REHMA', 97, NULL, 'I find that this HADEES truly portrays the رحمنیۃ and the رحیمیۃ of our Creator. Love is an emotion that cannot be quantified in words; it can only be judged through action.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rehma', 'i find that this hadees truly portrays the رحمنيه and the رحيميه of our creator love is an emotion that cannot be quantified in words it can only be judged through action', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 1, NULL, 'REHM', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'rehm', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 2, NULL, 'The word رحمۃ derives from رَحَم. In Arabic, رَحَم refers to a mother''s womb when she carries a child. The رَحَم is the place where a baby resides inside the mother for nine months before birth. I considered why Allah chose a word for mercy that derives from a mother''s womb. The mother''s womb describes the relationship between Allah and His creation, which makes this connection beautiful.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'the word رحمه derives from رحم in arabic رحم refers to a mothers womb when she carries a child the رحم is the place where a baby resides inside the mother for nine months before birth i considered why allah chose a word for mercy that derives from a mothers womb the mothers womb describes the relationship between allah and his creation which makes this connection beautiful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 3, NULL, 'Both parents love their children. However, I observe that in the Quran, when Allah compares His love for His creation, He never uses the example of a father. He always uses the example of a mother. Therefore, to truly understand the meaning of the word رحمۃ and the nature of Allah''s relationship with us, I must first understand the bond between a mother and her child during pregnancy.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'both parents love their children however i observe that in the quran when allah compares his love for his creation he never uses the example of a father he always uses the example of a mother therefore to truly understand the meaning of the word رحمه and the nature of allahs relationship with us i must first understand the bond between a mother and her child during pregnancy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 4, NULL, 'A famous Hadith describes Allah speaking directly to the womb. Here, the womb represents the archetypal womb, as the mother''s womb is the means by which all of humanity comes into existence. All of us originate from our mothers'' wombs. Allah spoke to the womb, saying:', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'a famous hadith describes allah speaking directly to the womb here the womb represents the archetypal womb as the mothers womb is the means by which all of humanity comes into existence all of us originate from our mothers wombs allah spoke to the womb saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 5, NULL, 'Sayingاِنِّی سَمَّیتُکَ بِاسْمی', '', 'اِنِّی سَمَّیتُکَ بِاسْمی', 'Saying', NULL, NULL, 'surah al fateha womb the source of mercy', 'sayingاني سميتك باسمي', 'اني سميتك باسمي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 6, NULL, 'I named you from My names.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i named you from my names', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 7, NULL, 'I am الرحمن and I am الرحیم, and from these I derive the name for My unconditional love, My constant care, My genuine concern, and My infinite mercy. I name My رحمۃ based on your womb, your رَحَم. I make you a symbol of My رحمۃ and My unconditional love, because every human being who will exist through time will come through you. You will remind them of My love for them. Your رحم is the very first thing they will experience before they come into this world, and My رحمۃ is what they will experience once they are born into this world until the day they return to Me. That is the conversation the رحمن had with the womb, the رَحَم. SubhanAllah!', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i am الرحمن and i am الرحيم and from these i derive the name for my unconditional love my constant care my genuine concern and my infinite mercy i name my رحمه based on your womb your رحم i make you a symbol of my رحمه and my unconditional love because every human being who will exist through time will come through you you will remind them of my love for them your رحم is the very first thing they will experience before they come into this world and my رحمه is what they will experience once they are born into this world until the day they return to me that is the conversation the رحمن had with the womb the رحم subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 8, NULL, 'What is it about a mother''s womb that is important for understanding? Several points are important. The first question is: when a child is inside its mother''s womb, is it being punished? Is there any association with punishment for the baby while it is inside its mother''s womb? Absolutely not. The mother''s relationship with the baby is one of pure love. This serves as a reminder of the very nature of Allah''s relationship with His creation. It is based on pure love and has nothing to do with punishment. The moment a woman discovers she is pregnant, she falls in love with the baby. She has not even seen the baby yet. She has not even met the baby yet, but she still falls completely and unconditionally in love with her baby.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'what is it about a mothers womb that is important for understanding several points are important the first question is when a child is inside its mothers womb is it being punished is there any association with punishment for the baby while it is inside its mothers womb absolutely not the mothers relationship with the baby is one of pure love this serves as a reminder of the very nature of allahs relationship with his creation it is based on pure love and has nothing to do with punishment the moment a woman discovers she is pregnant she falls in love with the baby she has not even seen the baby yet she has not even met the baby yet but she still falls completely and unconditionally in love with her baby', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 9, NULL, 'I consider whether the womb exists before conception, or if the body creates and discards it with each pregnancy. The womb exists within every woman, whether she carries a baby or not; it is always present. Similarly, Allah''s رحمۃ—his unconditional love, care, concern, and mercy—is always present. His رحمۃ does not depend on our existence, nor on the existence of humanity or creation. Instead, his رحمۃ is perpetually present and will endure even after we, all of humanity, and this universe cease to exist, just as the womb remains after a child is born.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i consider whether the womb exists before conception or if the body creates and discards it with each pregnancy the womb exists within every woman whether she carries a baby or not it is always present similarly allahs رحمه his unconditional love care concern and mercy is always present his رحمه does not depend on our existence nor on the existence of humanity or creation instead his رحمه is perpetually present and will endure even after we all of humanity and this universe cease to exist just as the womb remains after a child is born', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 10, NULL, 'A child inside its mother''s womb does not know it is being cared for, nor does it know of the mother''s existence. It remains unaware. Care is provided in ways it cannot imagine. The fetus in the womb cannot even imagine the womb''s role in sustaining its life, let alone comprehend or appreciate that care.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'a child inside its mothers womb does not know it is being cared for nor does it know of the mothers existence it remains unaware care is provided in ways it cannot imagine the fetus in the womb cannot even imagine the wombs role in sustaining its life let alone comprehend or appreciate that care', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 11, NULL, 'Similarly, Allah cares for us in ways we cannot imagine or realize. His care is so subtle that His presence, let alone His رحمۃ, remains invisible to us. This subtlety is why one of His names is لطیف. The word لطیف means something extremely subtle. It is present and constantly working for us, yet we do not even feel its presence. This is لطیف.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'similarly allah cares for us in ways we cannot imagine or realize his care is so subtle that his presence let alone his رحمه remains invisible to us this subtlety is why one of his names is لطيف the word لطيف means something extremely subtle it is present and constantly working for us yet we do not even feel its presence this is لطيف', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 12, NULL, 'It is remarkable that in the Quran, every mention of the attribute لطیف is accompanied by another attribute. That attribute is خبیر, the All-Knowing.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'it is remarkable that in the quran every mention of the attribute لطيف is accompanied by another attribute that attribute is خبير the all knowing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 13, NULL, 'Al-An''am: 103لَّا تُدْرِكُهُ ٱلْأَبْصَرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَرَ ۖ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', '', 'لَّا تُدْرِكُهُ ٱلْأَبْصَرُ وَهُوَ يُدْرِكُ ٱلْأَبْصَرَ ۖ وَهُوَ ٱللَّطِيفُ ٱلْخَبِيرُ', 'Al-An''am: 103', 6, 103, 'surah al fateha womb the source of mercy', 'al anam 103لا تدركه الابصر وهو يدرك الابصر وهو اللطيف الخبير', 'لا تدركه الابصر وهو يدرك الابصر وهو اللطيف الخبير');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 14, NULL, 'Our eyes cannot see Him, but He is aware of what our eyes perceive. He is extremely subtle, yet ALL-KNOWING simultaneously. Thus, the child does not even know that its mother is caring for it.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'our eyes cannot see him but he is aware of what our eyes perceive he is extremely subtle yet all knowing simultaneously thus the child does not even know that its mother is caring for it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 15, NULL, 'I next consider the womb, and the idea of protection immediately comes to mind. The mother constantly protects the baby. This protection manifests in many ways:', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i next consider the womb and the idea of protection immediately comes to mind the mother constantly protects the baby this protection manifests in many ways', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 16, NULL, 'She watches for sharp table corners when she walks. She tries to stay safe. She sleeps on her side. She monitors what she eats. She constantly caresses the baby.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'she watches for sharp table corners when she walks she tries to stay safe she sleeps on her side she monitors what she eats she constantly caresses the baby', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 17, NULL, 'Her love and care for the baby drive this extreme protectiveness.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'her love and care for the baby drive this extreme protectiveness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 18, NULL, 'Allah provides this same constant protection for His creation. People do not simply arrive at school without incident. I consider the multitude of things that can go wrong between leaving home and arriving at school. Indeed, countless potential dangers exist. Yet Allah protects and keeps His creation safe. Every day, people leave their homes, and not all of them return that night. Those who die in car crashes or accidents do not know they will not return home that night. When their appointed time arrives, their life ends. Until that time, Allah''s constant protection, His رحمۃ, shields them from accidents and other harms. Thus, just as the womb constantly protects its creation, Allah constantly protects His own creation. The mother''s womb serves as a reminder of this truth.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'allah provides this same constant protection for his creation people do not simply arrive at school without incident i consider the multitude of things that can go wrong between leaving home and arriving at school indeed countless potential dangers exist yet allah protects and keeps his creation safe every day people leave their homes and not all of them return that night those who die in car crashes or accidents do not know they will not return home that night when their appointed time arrives their life ends until that time allahs constant protection his رحمه shields them from accidents and other harms thus just as the womb constantly protects its creation allah constantly protects his own creation the mothers womb serves as a reminder of this truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 19, NULL, 'A mother endures many difficulties for her baby. She deals with constant morning sickness. Some have to take these horribly painful tests. Some have to take extremely nauseating medicines for the health and growth of the baby. They undergo constant blood work, experiencing one painful procedure after another. A mother endures so much pain, all for the sake of her child. The child, however, remains completely unaware of this. The child takes the mother completely for granted, just as we take the رحمۃ of Allah سُبْحَانَهُ وَتَعَالَى for granted. Moreover, the child technically does nothing for the mother, yet the mother does everything for the child. The baby consumes her food. The mother eats, but within minutes the baby takes everything, leaving her hungry again shortly after a large meal. Consequently, the husband may find himself running for ice cream in the middle of the night. The baby takes everything from her and gives nothing back to its mother. In fact, when the baby does thank her, it does so by kicking her from the inside. It might:', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'a mother endures many difficulties for her baby she deals with constant morning sickness some have to take these horribly painful tests some have to take extremely nauseating medicines for the health and growth of the baby they undergo constant blood work experiencing one painful procedure after another a mother endures so much pain all for the sake of her child the child however remains completely unaware of this the child takes the mother completely for granted just as we take the رحمه of allah سبحانه وتعالي for granted moreover the child technically does nothing for the mother yet the mother does everything for the child the baby consumes her food the mother eats but within minutes the baby takes everything leaving her hungry again shortly after a large meal consequently the husband may find himself running for ice cream in the middle of the night the baby takes everything from her and gives nothing back to its mother in fact when the baby does thank her it does so by kicking her from the inside it might', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 20, NULL, 'Stretch from time to time. Perform an insanity workout whenever it feels like it. Bench press with her ribs.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'stretch from time to time perform an insanity workout whenever it feels like it bench press with her ribs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 21, NULL, 'The mother silently and happily endures these actions. This is incredible. The mother remains in a constant state of discomfort because of this baby, yet she happily endures it. We do absolutely nothing for Allah, but Allah still does everything for us. We do nothing for Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'the mother silently and happily endures these actions this is incredible the mother remains in a constant state of discomfort because of this baby yet she happily endures it we do absolutely nothing for allah but allah still does everything for us we do nothing for allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 22, NULL, 'I can do nothing for Allah, even if I wished. I cannot add anything to his kingdom, nor can I take anything away. My good deeds do not increase his kingdom, and my sins do not diminish it. I cannot make him wealthier or poorer than he already is. I cannot praise him more than he is already praised. I cannot do anything for him. The fact remains clear: I can offer Allah absolutely nothing. Yet, he constantly acts for me, often without my even realizing his presence, and in many cases, without my acknowledging it.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i can do nothing for allah even if i wished i cannot add anything to his kingdom nor can i take anything away my good deeds do not increase his kingdom and my sins do not diminish it i cannot make him wealthier or poorer than he already is i cannot praise him more than he is already praised i cannot do anything for him the fact remains clear i can offer allah absolutely nothing yet he constantly acts for me often without my even realizing his presence and in many cases without my acknowledging it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 23, NULL, 'Ar-Rahman: 29كُلَّ يَوْمٍ هُوَ فِى شَأْنٍۢ', '', 'كُلَّ يَوْمٍ هُوَ فِى شَأْنٍۢ', 'Ar-Rahman: 29', 55, 29, 'surah al fateha womb the source of mercy', 'ar rahman 29كل يوم هو في شان', 'كل يوم هو في شان');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 24, NULL, 'Every moment he is engaged in work to keep this universe and everything within it functional. SubhanAllah!', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'every moment he is engaged in work to keep this universe and everything within it functional subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 25, NULL, 'The womb reminds me that all the needs of the child are met by its mother. The child is completely surrounded and enveloped by its mother''s love and care. Its food, its drinks, and even the disposal of its waste are all managed by the mother''s body. Everything the child needs is fully provided.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'the womb reminds me that all the needs of the child are met by its mother the child is completely surrounded and enveloped by its mothers love and care its food its drinks and even the disposal of its waste are all managed by the mothers body everything the child needs is fully provided', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 26, NULL, 'Rent is paid. Housing and lodging are free. It does not pay for utilities. All meals are included.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'rent is paid housing and lodging are free it does not pay for utilities all meals are included', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 27, NULL, 'The baby is completely wrapped in its mother''s love and care.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'the baby is completely wrapped in its mothers love and care', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 28, NULL, 'Similarly, I am completely wrapped in the unconditional love, care, concern, and mercy of Allah سُبْحَانَهُ وَتَعَالَى. He provides my sustenance and gives me the luxuries of a good life. He makes the outside world functional for me, and He keeps the inside world functional. My heart beats, my organs work, and my breath comes in and out. I can walk. I can speak. He makes all this happen for me. He gave me parents, teachers, knowledge, and a family. He surrounded me with all the comforts of my life.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'similarly i am completely wrapped in the unconditional love care concern and mercy of allah سبحانه وتعالي he provides my sustenance and gives me the luxuries of a good life he makes the outside world functional for me and he keeps the inside world functional my heart beats my organs work and my breath comes in and out i can walk i can speak he makes all this happen for me he gave me parents teachers knowledge and a family he surrounded me with all the comforts of my life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 29, NULL, 'I often complain about paying bills, mortgage, and utility expenses. Yet, I consider: how much do I pay for my sight? How much do I pay Allah for my ability to hear, to speak, or to breathe? Setting aside all else, how much do I pay for each breath I take? How much would I pay for my breath if I could not breathe and Allah asked me to pay for the next one?', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i often complain about paying bills mortgage and utility expenses yet i consider how much do i pay for my sight how much do i pay allah for my ability to hear to speak or to breathe setting aside all else how much do i pay for each breath i take how much would i pay for my breath if i could not breathe and allah asked me to pay for the next one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 30, NULL, 'I consider the price I would pay for my next breath. I reflect on the worth of my hands. My life is immensely blessed with His uncountable bounties. I am blessed with the riches and provisions He created for us, all of which I take completely for granted. Yet, He accepts this, and He continues to serve me.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i consider the price i would pay for my next breath i reflect on the worth of my hands my life is immensely blessed with his uncountable bounties i am blessed with the riches and provisions he created for us all of which i take completely for granted yet he accepts this and he continues to serve me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 31, NULL, 'I have discussed the benefits of the child. I now turn to the mother''s motivation. The baby does not pay the mother; it gives nothing back to her. What, then, motivates this mother to carry on? Despite all the discomfort this child causes her, what could possibly be her driving force?', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i have discussed the benefits of the child i now turn to the mothers motivation the baby does not pay the mother it gives nothing back to her what then motivates this mother to carry on despite all the discomfort this child causes her what could possibly be her driving force', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 32, NULL, 'The mother''s sole motivation for her baby is an extreme form of unconditional love. This point bears consideration. As the child grows within the mother''s womb, it increasingly presents physical challenges for her. With each passing day, as the embryo increases in size, it becomes more demanding on the mother''s body. Yet, her love for the baby intensifies. Her affection grows constantly, which is remarkable. Then, at birth, the baby''s arrival nearly takes her life. As if nine months of torture were not enough, the baby inflicts the incredibly intense pain of childbirth. I have been in the delivery room twice and have witnessed that pain. Nazneen was in labor for eight hours when Erum was born. I know that many mothers experience far worse, but I have personally never seen anyone endure such profound pain. Yet, when Erum finally emerged, I recall the doctor attempting to hand her to me. She was covered in the substances of birth, and I reacted with an exclamation of disgust: "What is this?! Can you please clean this thing first?"', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'the mothers sole motivation for her baby is an extreme form of unconditional love this point bears consideration as the child grows within the mothers womb it increasingly presents physical challenges for her with each passing day as the embryo increases in size it becomes more demanding on the mothers body yet her love for the baby intensifies her affection grows constantly which is remarkable then at birth the babys arrival nearly takes her life as if nine months of torture were not enough the baby inflicts the incredibly intense pain of childbirth i have been in the delivery room twice and have witnessed that pain nazneen was in labor for eight hours when erum was born i know that many mothers experience far worse but i have personally never seen anyone endure such profound pain yet when erum finally emerged i recall the doctor attempting to hand her to me she was covered in the substances of birth and i reacted with an exclamation of disgust what is this can you please clean this thing first', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 33, NULL, 'I remember when she brought Erum to Nazneen; with incredible love, she touched her cheeks and said, "Hi baby!" Then she passed out. That was an insane moment in my life. I still do not comprehend it, and I probably never will. I had thought she would hate this baby who caused her so much pain! I had expected her to yell at her, to scream at her, to curse her out, saying, "You almost killed me! I hate you!" But that is not what happened. Instead, the first time they brought Erum to her, she gave her a big hug and kissed her. I had never seen anyone in such profound pain and simultaneously so happy! SubhanAllah!', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i remember when she brought erum to nazneen with incredible love she touched her cheeks and said hi baby then she passed out that was an insane moment in my life i still do not comprehend it and i probably never will i had thought she would hate this baby who caused her so much pain i had expected her to yell at her to scream at her to curse her out saying you almost killed me i hate you but that is not what happened instead the first time they brought erum to her she gave her a big hug and kissed her i had never seen anyone in such profound pain and simultaneously so happy subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 34, NULL, 'Anyone else who causes such immense pain, who makes one bleed in that manner, would certainly not receive a hug. We made our mothers bleed, almost to death. Yet, as soon as we emerged from her womb, she showered us with her love. Her love for us actually increased; she fell more deeply in love with us than ever before, mere seconds after we had nearly killed her.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'anyone else who causes such immense pain who makes one bleed in that manner would certainly not receive a hug we made our mothers bleed almost to death yet as soon as we emerged from her womb she showered us with her love her love for us actually increased she fell more deeply in love with us than ever before mere seconds after we had nearly killed her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 35, NULL, 'What kind of relationship is this? It is a completely illogical relationship, one that defies all understanding. It transcends all logic because this dynamic does not occur in any other relationship. No other relationship functions in this way, where one never gives—never, ever gives—and only takes, yet still receives more love in return. One continues to demand more, and she continues to give more.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'what kind of relationship is this it is a completely illogical relationship one that defies all understanding it transcends all logic because this dynamic does not occur in any other relationship no other relationship functions in this way where one never gives never ever gives and only takes yet still receives more love in return one continues to demand more and she continues to give more', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 36, NULL, 'And a mother bleeds profusely to give life. After childbirth or surgery to bring forth life, she must immediately feed the newborn. Feeding can also be a very painful experience. Anyone else in this world who undergoes surgery or such intense pain says, "I need six weeks off. I need two months off. I need a break. I need a vacation." Does a mother receive a two-month break after giving birth? No. A broken leg, for instance, grants six months of recovery. Having nearly died in childbirth, she is immediately on duty. From the moment of birth, the mother works full-time.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'and a mother bleeds profusely to give life after childbirth or surgery to bring forth life she must immediately feed the newborn feeding can also be a very painful experience anyone else in this world who undergoes surgery or such intense pain says i need six weeks off i need two months off i need a break i need a vacation does a mother receive a two month break after giving birth no a broken leg for instance grants six months of recovery having nearly died in childbirth she is immediately on duty from the moment of birth the mother works full time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 37, NULL, 'What does the infant offer in return?', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'what does the infant offer in return', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 38, NULL, 'She provides milk, love, and care. She is constantly concerned about it and protects it. She bathes it, oils it, and changes diapers every few minutes.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'she provides milk love and care she is constantly concerned about it and protects it she bathes it oils it and changes diapers every few minutes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 39, NULL, 'This continues through countless sleepless nights, month after month, year after year. Does the infant express thanks, show gratitude, or sing praises for the mother? No. Yet the mother continues to love and care for her infant repeatedly. She does. The only reward the infant offers is through:', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'this continues through countless sleepless nights month after month year after year does the infant express thanks show gratitude or sing praises for the mother no yet the mother continues to love and care for her infant repeatedly she does the only reward the infant offers is through', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 40, NULL, 'Urinating on her Defecating on her Vomiting on her', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'urinating on her defecating on her vomiting on her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 41, NULL, 'Even then, does the mother cast it aside? No. She finds it endearing: "Aww, so cute," as she cleans it, "Oh, it''s okay, my little baby."', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'even then does the mother cast it aside no she finds it endearing aww so cute as she cleans it oh its okay my little baby', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 42, NULL, '"Don''t worry, I will change you. All better now!" I consider this an incredibly beautiful relationship. Yet, at the same time, I also find it an extremely insane relationship.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'dont worry i will change you all better now i consider this an incredibly beautiful relationship yet at the same time i also find it an extremely insane relationship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 43, NULL, 'This is what Allah does for us. His actions on a much larger scale also defy understanding. Allah''s love for us simply defies logic; it is beyond all rational thought. I cannot confine His love to what common sense dictates, for common sense suggests we do not deserve such love from Him. When I honestly judge our actions and consider our ingratitude toward Allah, I find no reason for Him to continue caring for us.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'this is what allah does for us his actions on a much larger scale also defy understanding allahs love for us simply defies logic it is beyond all rational thought i cannot confine his love to what common sense dictates for common sense suggests we do not deserve such love from him when i honestly judge our actions and consider our ingratitude toward allah i find no reason for him to continue caring for us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 44, NULL, 'We do not even dedicate two hours a day to remember Him five times. That is all it takes. Yet, we readily spend time on trivial activities:', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'we do not even dedicate two hours a day to remember him five times that is all it takes yet we readily spend time on trivial activities', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 45, NULL, 'watching a three-hour Indian movie, watching a five-hour soccer match, watching an all-day cricket match, rewinding and replaying it.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'watching a three hour indian movie watching a five hour soccer match watching an all day cricket match rewinding and replaying it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 46, NULL, 'We find time for all these trivialities, but not two hours for our Creator. Not even thirty minutes to perform the فرائض. We do not even manage that much, simply to express gratitude. We constantly disobey Him despite everything He does for us. We do all that He forbids. Some do not even acknowledge His existence, questioning if Allah exists or caring if He does.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'we find time for all these trivialities but not two hours for our creator not even thirty minutes to perform the فرايض we do not even manage that much simply to express gratitude we constantly disobey him despite everything he does for us we do all that he forbids some do not even acknowledge his existence questioning if allah exists or caring if he does', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 47, NULL, 'Yet, He continues to give, to feed, to provide, and to forgive us. This is truly incredible. Despite my constant ingratitude, my constant disloyalty, and my constant defiance of His every command, I still wake each morning. I still breathe oxygen.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'yet he continues to give to feed to provide and to forgive us this is truly incredible despite my constant ingratitude my constant disloyalty and my constant defiance of his every command i still wake each morning i still breathe oxygen', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 48, NULL, 'I am still going about my day, eating and drinking the delicious foods He provides for me. I am still enjoying life, even attending parties. He takes none of that away from me. This does not make sense. It simply does not make sense.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i am still going about my day eating and drinking the delicious foods he provides for me i am still enjoying life even attending parties he takes none of that away from me this does not make sense it simply does not make sense', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 49, NULL, 'I observe our actions concerning food. How much of it do I see wasted? This food represents His greatest blessings for humankind, the very means of our sustenance. I see how we disrespect this sustenance.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i observe our actions concerning food how much of it do i see wasted this food represents his greatest blessings for humankind the very means of our sustenance i see how we disrespect this sustenance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 50, NULL, 'I reflect on the etiquette of eating. The Prophet ﷺ said: "Sit before your food like a slave sits before his master. Cover your head before you eat out of respect. Do not place your plate on the floor; elevate it from the ground to honor it. When you are done eating, find and eat the crumbs and grains that are left behind." Such is the profound respect and honor I believe we should show for food in our lives.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i reflect on the etiquette of eating the prophet ﷺ said sit before your food like a slave sits before his master cover your head before you eat out of respect do not place your plate on the floor elevate it from the ground to honor it when you are done eating find and eat the crumbs and grains that are left behind such is the profound respect and honor i believe we should show for food in our lives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 51, NULL, 'I ask myself why this is so.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i ask myself why this is so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 52, NULL, 'Without it, I cannot even imagine the state to which our lives would be reduced. I consider the immense effort required behind the scenes to bring that food to our plates.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'without it i cannot even imagine the state to which our lives would be reduced i consider the immense effort required behind the scenes to bring that food to our plates', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 53, NULL, 'I reflect on the time, the effort, the protection, the management, and the planning involved in taking a seed and cultivating it into a plant. Similarly, I consider the process of raising an animal: nurturing it, feeding it, and protecting it until it reaches the proper age. Then it passes into the hands of the one who performs ذبیحۃ to make it halal for us. After that, it reaches the supermarket and the meat shop for purchase. Finally, the provision of tools allows for its cooking until it reaches our plates. This entire process represents years of Allah''s labor, now presented before us on our plates.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i reflect on the time the effort the protection the management and the planning involved in taking a seed and cultivating it into a plant similarly i consider the process of raising an animal nurturing it feeding it and protecting it until it reaches the proper age then it passes into the hands of the one who performs ذبيحه to make it halal for us after that it reaches the supermarket and the meat shop for purchase finally the provision of tools allows for its cooking until it reaches our plates this entire process represents years of allahs labor now presented before us on our plates', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 54, NULL, 'Yet, I wonder if we truly care. Often, we take only a few bites before discarding it. The reasons given are often trivial: it was not warm enough, not fresh enough, or lacked sufficient salt. Sometimes, it is simply attributed to children''s preferences.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'yet i wonder if we truly care often we take only a few bites before discarding it the reasons given are often trivial it was not warm enough not fresh enough or lacked sufficient salt sometimes it is simply attributed to childrens preferences', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 55, NULL, 'I consider the profound sense of futility that arises from months of labor on a project, only for it to be discarded. Such an experience naturally leads to a reluctance to undertake similar efforts again.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'i consider the profound sense of futility that arises from months of labor on a project only for it to be discarded such an experience naturally leads to a reluctance to undertake similar efforts again', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 56, NULL, 'Rasul Allah ﷺ established these etiquettes in شریعۃ so that they might serve as a constant reminder. Humanity is انسان, a forgetful creature in perpetual need of such reminders. The subject of this remembrance is Allah''s mercy, his رحمۃ. Indeed, all of شریعۃ functions as a reminder of this mercy. When a decent human being is presented with and reminded of another person''s love, care, concern, and mercy, a natural response of praise and gratitude emerges. This holds true for any individual of sound character.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'rasul allah ﷺ established these etiquettes in شريعه so that they might serve as a constant reminder humanity is انسان a forgetful creature in perpetual need of such reminders the subject of this remembrance is allahs mercy his رحمه indeed all of شريعه functions as a reminder of this mercy when a decent human being is presented with and reminded of another persons love care concern and mercy a natural response of praise and gratitude emerges this holds true for any individual of sound character', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 57, NULL, 'Unfortunately, we are often ungrateful. We continuously disrespect and disregard Allah''s continuous provision, even as he constantly provides for us, giving us food, clothes, and shelter, each better than the last. This is like a mother who keeps feeding her baby regardless of its actions. A baby does not consider the months of intense effort that went into its growth, from a drop of liquid to a fully developed child, and then to an adult. Yet, a mother never stops loving her child. This is a boundless love. There is no logical reason for Allah to love us in this way, but he does. He continues to do so. This is because he has رحمۃ for us. This defines the relationship he has with us:', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'unfortunately we are often ungrateful we continuously disrespect and disregard allahs continuous provision even as he constantly provides for us giving us food clothes and shelter each better than the last this is like a mother who keeps feeding her baby regardless of its actions a baby does not consider the months of intense effort that went into its growth from a drop of liquid to a fully developed child and then to an adult yet a mother never stops loving her child this is a boundless love there is no logical reason for allah to love us in this way but he does he continues to do so this is because he has رحمه for us this defines the relationship he has with us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 58, NULL, 'unconditional love constant care genuine concern constant mercy', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'unconditional love constant care genuine concern constant mercy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 59, NULL, 'As a baby grows, the womb expands to accommodate it. Similarly, Allah''s love, his mercy, his forgiveness, and his compassion constantly grow to accommodate us. This is the love our Creator has for us.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'as a baby grows the womb expands to accommodate it similarly allahs love his mercy his forgiveness and his compassion constantly grow to accommodate us this is the love our creator has for us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 60, NULL, 'Sayingاِنِّی سَمَّیتُکَ بِاسْمی"Oh Womb! I have named you from my names. I have named you رَحَم to remind you that I am الرحمن and الرحیم. I have made you a symbol of my love, so that every human being recognizes my unconditional love for them — through you and by your example."', '', NULL, 'Saying', NULL, NULL, 'surah al fateha womb the source of mercy', 'sayingاني سميتك باسمي oh womb i have named you from my names i have named you رحم to remind you that i am الرحمن and الرحيم i have made you a symbol of my love so that every human being recognizes my unconditional love for them through you and by your example', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'womb - the source of mercy', 'Womb - The Source Of Mercy', 61, NULL, 'Just as we can never fully understand a mother''s love for her child, we can never fully grasp or appreciate Allah''s love and care for his creation. Yet, to offer some understanding of this relationship, he gave us mothers. When one seeks to taste a single drop of that endless ocean of love Allah holds for his creation, the image of a mother comes to mind.', '', NULL, NULL, NULL, NULL, 'surah al fateha womb the source of mercy', 'just as we can never fully understand a mothers love for her child we can never fully grasp or appreciate allahs love and care for his creation yet to offer some understanding of this relationship he gave us mothers when one seeks to taste a single drop of that endless ocean of love allah holds for his creation the image of a mother comes to mind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 0, NULL, 'I have explained the رحمۃ of Allah سُبْحَانَهُ وَتَعَالَى, and I have tried to make clear what رحمۃ means and what it represents.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i have explained the رحمه of allah سبحانه وتعالي and i have tried to make clear what رحمه means and what it represents', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 1, NULL, 'In sum, رحمۃ joins together unconditional love, constant care, genuine concern, unlimited mercy, and compassion. The two common derivatives of رحمۃ are الرحمن and الرحیم.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'in sum رحمه joins together unconditional love constant care genuine concern unlimited mercy and compassion the two common derivatives of رحمه are الرحمن and الرحيم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 2, NULL, 'The attribute الرحمن points to the intensity of his رحمۃ: its urgency, its promptness, and also its interim or temporary quality. The attribute الرحیم points to the long-term and permanent qualities of his رحمۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'the attribute الرحمن points to the intensity of his رحمه its urgency its promptness and also its interim or temporary quality the attribute الرحيم points to the long term and permanent qualities of his رحمه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 3, NULL, 'I then turned to the root of رحمۃ itself. It comes from رحم, which literally means the womb of a mother. The womb gives magnificent examples that depict and demonstrate the رحمۃ of Allah سُبْحَانَهُ وَتَعَالَى.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i then turned to the root of رحمه itself it comes from رحم which literally means the womb of a mother the womb gives magnificent examples that depict and demonstrate the رحمه of allah سبحانه وتعالي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 4, NULL, 'I know how the womb takes a shapeless drop of liquid and, by its رحمۃ, transforms it into a living child. I drew the analogy that the رحمۃ of Allah سُبْحَانَهُ وَتَعَالَى shapes and transforms our spiritual existence.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i know how the womb takes a shapeless drop of liquid and by its رحمه transforms it into a living child i drew the analogy that the رحمه of allah سبحانه وتعالي shapes and transforms our spiritual existence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 5, NULL, 'His رحمۃ takes human beings in their raw and ignorant state, with no real goal and no true purpose beyond the limits of this دنیا. It then transforms them into extraordinary personalities, people whose names I do not even mention without adding رَحْمَۃُ اللہِ عَلَیْہِ after them.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'his رحمه takes human beings in their raw and ignorant state with no real goal and no true purpose beyond the limits of this دنيا it then transforms them into extraordinary personalities people whose names i do not even mention without adding رحمه الله عليه after them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 6, NULL, 'This is why Rasul Allah ﷺ is called رَحْمَۃً لِی الْعَالَمِینَ. He is called رحمۃ for this world because he took on the role of a mother''s womb, shaping and nurturing the spiritual existence of humanity. That was not only for the people of his own time, but for all humanity until the end of time.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'this is why rasul allah ﷺ is called رحمه لي العالمين he is called رحمه for this world because he took on the role of a mothers womb shaping and nurturing the spiritual existence of humanity that was not only for the people of his own time but for all humanity until the end of time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 7, NULL, 'I also looked at how a mother suffers in order to give comfort to her child. She protects it, nurtures it, feeds it, and bears hardship, pain, and suffering so that a shapeless mass becomes a living, breathing child. From this I drew the parallel that Allah سُبْحَانَهُ وَتَعَالَى, through his various intermediaries, his Imams, his prophets, and his messengers, shapes our spiritual existence. Just as a pregnant mother suffers, history shows that these people endured many hardships in order to deliver the message of Allah to their nations.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i also looked at how a mother suffers in order to give comfort to her child she protects it nurtures it feeds it and bears hardship pain and suffering so that a shapeless mass becomes a living breathing child from this i drew the parallel that allah سبحانه وتعالي through his various intermediaries his imams his prophets and his messengers shapes our spiritual existence just as a pregnant mother suffers history shows that these people endured many hardships in order to deliver the message of allah to their nations', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 9, NULL, 'I also find one of the most wondrous qualities of the womb, the رحم, in the way it expands to meet the needs of the fetus. It gives a beautiful reminder that Allah''s رحمۃ expands as well: not only to meet the needs of his creation, but also to forgive their shortcomings, sins, and transgressions.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i also find one of the most wondrous qualities of the womb the رحم in the way it expands to meet the needs of the fetus it gives a beautiful reminder that allahs رحمه expands as well not only to meet the needs of his creation but also to forgive their shortcomings sins and transgressions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 10, NULL, 'His vast forgiveness is one of the manifestations of his infinite compassion toward his creation. Allah knows that we are people of very weak character. We are often enslaved by worldly desires. Yet he also knows that we are trying, in whatever ways we can, to move toward him: centimeter by centimeter, inch by inch. So he makes up for that weakness and strengthens what is lacking in us through his forgiveness.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'his vast forgiveness is one of the manifestations of his infinite compassion toward his creation allah knows that we are people of very weak character we are often enslaved by worldly desires yet he also knows that we are trying in whatever ways we can to move toward him centimeter by centimeter inch by inch so he makes up for that weakness and strengthens what is lacking in us through his forgiveness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 11, NULL, 'There is a verse in the Quran in which Allah says:', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'there is a verse in the quran in which allah says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 12, NULL, 'Az-Zumar: 53قُلْ يَعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُSay, "O My servants who have transgressed against themselves [by sinning], do not despair of the mercy of Allah . Indeed, Allah forgives all sins. Indeed, it is He who is the Forgiving, the Merciful."', '', NULL, 'Az-Zumar: 53', NULL, NULL, 'surah al fateha manifestations of rehma', 'az zumar 53قل يعبادي الذين اسرفوا علي انفسهم لا تقنطوا من رحمه الله ان الله يغفر الذنوب جميعا انه هو الغفور الرحيمsay o my servants who have transgressed against themselves by sinning do not despair of the mercy of allah indeed allah forgives all sins indeed it is he who is the forgiving the merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 13, NULL, 'He says:', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 14, NULL, 'O My slaves who have transgressed against themselves through their sins. Which slaves does He mean? The disbelievers? The polytheists? The idol worshipers? No. He means us: Muslims, believers. يَعِبَادِىَ. In Arabic, this form of address carries deep nearness, deep love, and deep intimacy. A casual call would have been یَا أَیُّھَا الْعِبَادُ, meaning “O slaves,” without that intimacy or love. But يَعِبَادِىَ expresses intense nearness: O My beloved slaves, O My revered slaves, O My cherished slave. The difference is clear. And what kind of slaves are they? Faithful slaves? Trustworthy slaves? Obedient slaves? No.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'o my slaves who have transgressed against themselves through their sins which slaves does he mean the disbelievers the polytheists the idol worshipers no he means us muslims believers يعبادي in arabic this form of address carries deep nearness deep love and deep intimacy a casual call would have been يا ايها العباد meaning o slaves without that intimacy or love but يعبادي expresses intense nearness o my beloved slaves o my revered slaves o my cherished slave the difference is clear and what kind of slaves are they faithful slaves trustworthy slaves obedient slaves no', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'manifestations of rehma', 'Manifestations of REHMA', 15, NULL, 'Az-Zumar: 53ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ', '', 'ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ', 'Az-Zumar: 53', 39, 53, 'surah al fateha manifestations of rehma', 'az zumar 53الذين اسرفوا علي انفسهم', 'الذين اسرفوا علي انفسهم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 16, NULL, 'I mean the ones who have crossed every limit and boundary in wronging themselves. They have severely harmed their own souls by living in sin, hopelessness, and disobedience to Allah; by choosing a way of life that damages and obstructs their spiritual growth.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i mean the ones who have crossed every limit and boundary in wronging themselves they have severely harmed their own souls by living in sin hopelessness and disobedience to allah by choosing a way of life that damages and obstructs their spiritual growth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 17, NULL, 'These are the slaves He is addressing. Yet the scholars point out something beautiful in this verse: before this description comes the word يَعِبَادِىَ. Allah still calls them My slaves. No matter who they are, and no matter what they have done, they still belong to Him as His slaves.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'these are the slaves he is addressing yet the scholars point out something beautiful in this verse before this description comes the word يعبادي allah still calls them my slaves no matter who they are and no matter what they have done they still belong to him as his slaves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 18, NULL, 'There is no abandonment from Allah سُبْحَانَهُ وَتَعَالَى. Just as the womb does not abandon its fetus if it is deformed, Allah constantly preserves the relationship of رحمۃ with us, even if we become the worst of the worst. We may be the most sinful people on the face of the earth, constantly walking on very thin ice, yet Allah still keeps that relationship and connection alive through the word يَعِبَادِىَ: My slaves. SubhanAllah. AllahuAkbar.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'there is no abandonment from allah سبحانه وتعالي just as the womb does not abandon its fetus if it is deformed allah constantly preserves the relationship of رحمه with us even if we become the worst of the worst we may be the most sinful people on the face of the earth constantly walking on very thin ice yet allah still keeps that relationship and connection alive through the word يعبادي my slaves subhanallah allahuakbar', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'manifestations of rehma', 'Manifestations of REHMA', 19, NULL, 'Az-Zumar: 53ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ', '', 'ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ', 'Az-Zumar: 53', 39, 53, 'surah al fateha manifestations of rehma', 'az zumar 53الذين اسرفوا علي انفسهم', 'الذين اسرفوا علي انفسهم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 20, NULL, 'The ones who have done severe harm to their souls and to themselves.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'the ones who have done severe harm to their souls and to themselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 21, NULL, 'I now come to Allah''s advice to them:', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i now come to allahs advice to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'manifestations of rehma', 'Manifestations of REHMA', 22, NULL, 'Az-Zumar: 53لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ', '', 'لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ', 'Az-Zumar: 53', 39, 53, 'surah al fateha manifestations of rehma', 'az zumar 53لا تقنطوا من رحمه الله', 'لا تقنطوا من رحمه الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 23, NULL, 'Never lose hope in the mercy of Allah. Never, not even by the smallest measure. I will not enter the technical details here, but the word لا indicates absolute and unconditional force, without the slightest doubt. The same force appears in لَا اِلَہَ اِلَّا اللَّہُ, which also begins with لا, because that statement carries absolute finality: there is no god at all except Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'never lose hope in the mercy of allah never not even by the smallest measure i will not enter the technical details here but the word لا indicates absolute and unconditional force without the slightest doubt the same force appears in لا اله الا الله which also begins with لا because that statement carries absolute finality there is no god at all except allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 24, NULL, 'So Allah is saying, with complete certainty and under no circumstance, “I am making it حرام; I am making it impermissible. I am forbidding you to lose hope in my mercy. Ever.”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'so allah is saying with complete certainty and under no circumstance i am making it حرام i am making it impermissible i am forbidding you to lose hope in my mercy ever', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 25, NULL, 'Why? Allah never tells us something without also giving us a reason to believe it. So why should I not lose hope in the mercy of Allah?', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'why allah never tells us something without also giving us a reason to believe it so why should i not lose hope in the mercy of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'manifestations of rehma', 'Manifestations of REHMA', 26, NULL, 'Az-Zumar: 53إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا', '', 'إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا', 'Az-Zumar: 53', 39, 53, 'surah al fateha manifestations of rehma', 'az zumar 53ان الله يغفر الذنوب جميعا', 'ان الله يغفر الذنوب جميعا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 27, NULL, 'Because Allah is able to forgive every sin and every transgression. How can that be? I may have spent an entire lifetime in His disobedience. How can He forgive so many sins?', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'because allah is able to forgive every sin and every transgression how can that be i may have spent an entire lifetime in his disobedience how can he forgive so many sins', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'manifestations of rehma', 'Manifestations of REHMA', 28, NULL, 'Yusuf: 98إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '', 'إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'Yusuf: 98', 12, 98, 'surah al fateha manifestations of rehma', 'yusuf 98انه هو الغفور الرحيم', 'انه هو الغفور الرحيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 29, NULL, 'Because, indeed, without the slightest doubt, He and only He is الغفور: the One who forgives constantly.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'because indeed without the slightest doubt he and only he is الغفور the one who forgives constantly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 30, NULL, 'The word غفور follows the same linguistic pattern as رحیم. He is not merely forgiving; He is constantly forgiving and constantly merciful. Nothing lies beyond His power. Nothing is outside His reach. Allah can forgive all sins, and He will forgive them. This word, غفور, is remarkable because it reaches the very essence of His forgiveness.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'the word غفور follows the same linguistic pattern as رحيم he is not merely forgiving he is constantly forgiving and constantly merciful nothing lies beyond his power nothing is outside his reach allah can forgive all sins and he will forgive them this word غفور is remarkable because it reaches the very essence of his forgiveness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 32, NULL, 'In the Quran, when Allah speaks of His ability to forgive, He uses three different attributes for Himself. All three come from the same root: غَفَرَ.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'in the quran when allah speaks of his ability to forgive he uses three different attributes for himself all three come from the same root غفر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 33, NULL, 'The word غَفَرَ literally means to cover something. The Arabic word for helmet is مِغفَر. When a helmet is worn, the head is no longer visible. In that sense, مغفرۃ means to forgive: to cover sins so completely that they are hidden from sight, as though they never existed.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'the word غفر literally means to cover something the arabic word for helmet is مغفر when a helmet is worn the head is no longer visible in that sense مغفره means to forgive to cover sins so completely that they are hidden from sight as though they never existed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 34, NULL, 'GHAFARA', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'ghafara', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 35, NULL, 'So Allah calls Himself غَافِرِ الذَّنْبِ in the Quran.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'so allah calls himself غافر الذنب in the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 36, NULL, 'Sayingتَنزِيلُ ٱلْكِتَبِ مِنَ ٱللَّهِ ٱلْعَزِيزِ ٱلْعَلِيمِ ‎۲‏غَافِرِ ٱلذَّنۢبِ وَقَابِلِ ٱلتَّوْبِ شَدِيدِ ٱلْعِقَابِ ذِى ٱلطَّوْلِۖ لَآ إِلَهَ إِلَّا هُوَۖ إِلَيْهِ ٱلْمَصِيرُ( 2 ) The revelation of the Book is from Allah the All-Mighty, the All-Knower. ( 3 ) The forgiver of sin, acceptor of repentance, severe in punishment, owner of abundance. There is no deity except Him; to Him is the destination.', '', NULL, 'Saying', NULL, NULL, 'surah al fateha manifestations of rehma', 'sayingتنزيل الكتب من الله العزيز العليم ۲ غافر الذنب وقابل التوب شديد العقاب ذي الطول لا اله الا هو اليه المصير 2 the revelation of the book is from allah the all mighty the all knower 3 the forgiver of sin acceptor of repentance severe in punishment owner of abundance there is no deity except him to him is the destination', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 37, NULL, 'In language, غافر means the One who forgives at once. He does not hesitate. He does not pause to think before forgiving. That is غافر.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'in language غافر means the one who forgives at once he does not hesitate he does not pause to think before forgiving that is غافر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 38, NULL, 'Then He calls Himself غفَّار.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'then he calls himself غفار', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 39, NULL, 'Nuh: 10فَقُلْتُ ٱسْتَغْفِرُوا۟ رَبَّكُمْ إِنَّهُۥ كَانَ غَفَّارًۭاAnd said, Ask forgiveness of your Lord. Indeed, He is ever a Perpetual Forgiver.', '', NULL, 'Nuh: 10', NULL, NULL, 'surah al fateha manifestations of rehma', 'nuh 10فقلت استغفروا ربكم انه كان غفاراand said ask forgiveness of your lord indeed he is ever a perpetual forgiver', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 40, NULL, 'I understand غفَّار as the One who forgives abundantly. His forgiveness has no limit. He continues to forgive no matter how much sin exists.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i understand غفار as the one who forgives abundantly his forgiveness has no limit he continues to forgive no matter how much sin exists', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 41, NULL, 'Human beings have boundaries. A person may say, “I can forgive anything except betrayal,” or, “I cannot forgive lies,” or, “I cannot forgive rudeness.” Everyone carries some idea of what feels unforgivable. But Allah is غفَّار: He has no limit in what He can forgive. He can forgive everything when repentance is true.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'human beings have boundaries a person may say i can forgive anything except betrayal or i cannot forgive lies or i cannot forgive rudeness everyone carries some idea of what feels unforgivable but allah is غفار he has no limit in what he can forgive he can forgive everything when repentance is true', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 42, NULL, 'The third variation is غفور. As I have said, it follows the same phonetic pattern as رحیم, and it means constantly or permanently forgiving. This is the form used in the verse under discussion:', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'the third variation is غفور as i have said it follows the same phonetic pattern as رحيم and it means constantly or permanently forgiving this is the form used in the verse under discussion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'manifestations of rehma', 'Manifestations of REHMA', 43, NULL, 'Yusuf: 98إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', '', 'إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ', 'Yusuf: 98', 12, 98, 'surah al fateha manifestations of rehma', 'yusuf 98انه هو الغفور الرحيم', 'انه هو الغفور الرحيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 44, NULL, 'And indeed, He is constantly forgiving and constantly merciful.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'and indeed he is constantly forgiving and constantly merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 45, NULL, 'Unflinching loyalty, infinite hope, a permanent relationship that never ends, and forgiveness that is intense, immediate, and abundant are among the essential manifestations of His رحمۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'unflinching loyalty infinite hope a permanent relationship that never ends and forgiveness that is intense immediate and abundant are among the essential manifestations of his رحمه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 47, NULL, 'Another manifestation of the expansion of His رحمۃ, like the expansion of the womb, appears in His infinite rewards for small acts. On certain holy nights, Allah offers an astonishing amount of reward. (Thum Vasheq - 20 Hajj). I want to present one perspective on why Allah offers such rewards, so that the intention behind them becomes clearer.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'another manifestation of the expansion of his رحمه like the expansion of the womb appears in his infinite rewards for small acts on certain holy nights allah offers an astonishing amount of reward thum vasheq 20 hajj i want to present one perspective on why allah offers such rewards so that the intention behind them becomes clearer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 48, NULL, 'I see the holy month of Ramadan drawing near. In this month, it is the سنۃ of Rasul Allah ﷺ to perform اعتکاف. This means withdrawing into the مسجد for a set time, devoted only to the remembrance of Allah سُبْحَانَهُ وَتَعَالَى in silence. In India and Pakistan, people spend at least three days and nights in اعتکاف. They pray, recite Quran, do تسبیح, reflect on their lives, and more. Allah loves this. Rasul Allah ﷺ described the reward of اعتکاف in a HADEES. He said:', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i see the holy month of ramadan drawing near in this month it is the سنه of rasul allah ﷺ to perform اعتكاف this means withdrawing into the مسجد for a set time devoted only to the remembrance of allah سبحانه وتعالي in silence in india and pakistan people spend at least three days and nights in اعتكاف they pray recite quran do تسبيح reflect on their lives and more allah loves this rasul allah ﷺ described the reward of اعتكاف in a hadees he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 49, NULL, 'Sayingمَنِ اعْتَكَفَ يَوْماً ابْتِغَاءَ وَجْهِ اللهِ بَاعَدَ اللهُ بَيْنَهُ وَبَيْنَ النَّارِ ثَلَاثَةَ خَنَادِقَ كُلُّ خَنْدَقٍ كَمَا بَيْنَ الْخَافِقَيْنِ', '', 'مَنِ اعْتَكَفَ يَوْماً ابْتِغَاءَ وَجْهِ اللهِ بَاعَدَ اللهُ بَيْنَهُ وَبَيْنَ النَّارِ ثَلَاثَةَ خَنَادِقَ كُلُّ خَنْدَقٍ كَمَا بَيْنَ الْخَافِقَيْنِ', 'Saying', NULL, NULL, 'surah al fateha manifestations of rehma', 'sayingمن اعتكف يوما ابتغاء وجه الله باعد الله بينه وبين النار ثلاثه خنادق كل خندق كما بين الخافقين', 'من اعتكف يوما ابتغاء وجه الله باعد الله بينه وبين النار ثلاثه خنادق كل خندق كما بين الخافقين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 50, NULL, 'Whoever remains in اعتکاف for one day, only one day, Allah سُبْحَانَهُ وَتَعَالَى distances him from the Fire by three trenches. Each trench stretches as far as the distance between East and West. SubhanAllah. This is the reward for spending a single day in the مسجد, in the state of ذکر. It shows how beloved this act of اعتکاف is to Allah سُبْحَانَهُ وَتَعَالَى.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'whoever remains in اعتكاف for one day only one day allah سبحانه وتعالي distances him from the fire by three trenches each trench stretches as far as the distance between east and west subhanallah this is the reward for spending a single day in the مسجد in the state of ذكر it shows how beloved this act of اعتكاف is to allah سبحانه وتعالي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 51, NULL, 'I recall that one day in the month of Ramadan, اِبْنُ عَبَّاسٍ رَضِیَ اللَّہُ تَعَالَیٰ عَنْہُ, the cousin of the Prophet ﷺ, entered a مسجد intending to spend the day in اعتکاف, seeking the immense reward Allah has promised.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i recall that one day in the month of ramadan ابن عباس رضي الله تعالي عنه the cousin of the prophet ﷺ entered a مسجد intending to spend the day in اعتكاف seeking the immense reward allah has promised', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 52, NULL, 'Soon after he began his اعتکاف, he saw a Muslim brother in the مسجد who looked deeply sad. He went up to him and asked what had made him so sorrowful.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'soon after he began his اعتكاف he saw a muslim brother in the مسجد who looked deeply sad he went up to him and asked what had made him so sorrowful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 53, NULL, 'The man says, “O cousin of the Prophet ﷺ, I owe a debt to someone, and I need to pay it. But I cannot pay it because I have no money. The weight of that debt, that obligation, is crushing my soul.”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'the man says o cousin of the prophet ﷺ i owe a debt to someone and i need to pay it but i cannot pay it because i have no money the weight of that debt that obligation is crushing my soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 54, NULL, 'ابن عباس says to his man: “Would you like me to go to your lender and speak to him on your behalf? Perhaps I can persuade him to forgive your debt, reduce it, or give you more time. Would you like me to do that?”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'ابن عباس says to his man would you like me to go to your lender and speak to him on your behalf perhaps i can persuade him to forgive your debt reduce it or give you more time would you like me to do that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 55, NULL, 'The man replies, “Of course, یَا ابْنَ عَبَّاسٍ, I would be delighted if you did that.”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'the man replies of course يا ابن عباس i would be delighted if you did that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 56, NULL, 'So ابن عباس immediately stood up, walked out of the مسجد, and began putting on his slippers.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'so ابن عباس immediately stood up walked out of the مسجد and began putting on his slippers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 57, NULL, 'Suddenly, the man remembered: “Oh my God, ابن عباس was here for his اعتکاف. Now he is breaking his اعتکاف for me. What have I done? He came to the مسجد for an act of worship, and I became the reason he had to break his اعتکاف. That is the last thing I wanted.”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'suddenly the man remembered oh my god ابن عباس was here for his اعتكاف now he is breaking his اعتكاف for me what have i done he came to the مسجد for an act of worship and i became the reason he had to break his اعتكاف that is the last thing i wanted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 58, NULL, 'He rushes toward him and says, “یَا ابْنَ عَبَّاسٍ, do you not realize what you have done? Do you not remember why you were here? You have broken your اعتکاف!”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'he rushes toward him and says يا ابن عباس do you not realize what you have done do you not remember why you were here you have broken your اعتكاف', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 59, NULL, 'So ابن عباس looks at the man, and the HADEES says that tears begin to roll down his face. He says: “I remember my Prophet ﷺ telling me that if one of you strives to fulfill the need of his Muslim brother, Allah سُبْحَانَهُ وَتَعَالَى rewards him with the blessing of ten years of اعتکاف.”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'so ابن عباس looks at the man and the hadees says that tears begin to roll down his face he says i remember my prophet ﷺ telling me that if one of you strives to fulfill the need of his muslim brother allah سبحانه وتعالي rewards him with the blessing of ten years of اعتكاف', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 60, NULL, 'SubhanAllah. Not one day. Not one month. Not one year. Ten years of اعتکاف.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'subhanallah not one day not one month not one year ten years of اعتكاف', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 61, NULL, 'The reward for a single day of اعتکاف is distance from the Hellfire by three trenches, and each trench stretches the distance between east and west. That is the reward for one day of اعتکاف. Even one day is difficult enough; a full week of اعتکاف is beyond most people. When did I last complete a week of اعتکاف? Yet striving to meet the need of a Muslim brother brings the reward of ten years of اعتکاف. SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'the reward for a single day of اعتكاف is distance from the hellfire by three trenches and each trench stretches the distance between east and west that is the reward for one day of اعتكاف even one day is difficult enough a full week of اعتكاف is beyond most people when did i last complete a week of اعتكاف yet striving to meet the need of a muslim brother brings the reward of ten years of اعتكاف subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 62, NULL, 'After hearing this HADEES, my first thought is natural: I must not miss any chance to help anyone. This is a great opening to gain nearness to Allah. That is true. At times, the quickest path to Allah''s blessings runs through His creation: through other people, and through doing good to them.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'after hearing this hadees my first thought is natural i must not miss any chance to help anyone this is a great opening to gain nearness to allah that is true at times the quickest path to allahs blessings runs through his creation through other people and through doing good to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 63, NULL, 'That is why, when people hear this HADEES, they often rush to help others. They keep their ears open for any chance to serve someone. That is a beautiful response.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'that is why when people hear this hadees they often rush to help others they keep their ears open for any chance to serve someone that is a beautiful response', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 64, NULL, 'But I want to point to something higher and deeper in this HADEES. I want to turn the focus toward the intention behind the سُبْحَانَهُ وَتَعَالَى of Allah رحمۃ. This HADEES is astonishing, and an example will show why.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'but i want to point to something higher and deeper in this hadees i want to turn the focus toward the intention behind the سبحانه وتعالي of allah رحمه this hadees is astonishing and an example will show why', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 65, NULL, 'Suppose I enter a room and see someone there who is very sad. Suppose it is my niece Mariam. I discover that, for some reason, Mariam looks deeply unhappy that day. So I say, “I will give ten million dollars to anyone who makes her smile.”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'suppose i enter a room and see someone there who is very sad suppose it is my niece mariam i discover that for some reason mariam looks deeply unhappy that day so i say i will give ten million dollars to anyone who makes her smile', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 66, NULL, 'What will happen? Ten million dollars. Everyone in the room will try to make her smile. They will gather around her and offer their best jokes, all hoping to make her smile.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'what will happen ten million dollars everyone in the room will try to make her smile they will gather around her and offer their best jokes all hoping to make her smile', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 67, NULL, 'I know most people will look at that gesture and say, “Oh, you are so rich. You must have so much money that you are willing to give ten million dollars just to make her smile.” But a few will reach the heart of the gesture and say, “You must love her so much. You must love her so much that one smile from her is worth ten million dollars to you. She must mean the world to you.”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i know most people will look at that gesture and say oh you are so rich you must have so much money that you are willing to give ten million dollars just to make her smile but a few will reach the heart of the gesture and say you must love her so much you must love her so much that one smile from her is worth ten million dollars to you she must mean the world to you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 68, NULL, 'That is the difference. The reality is that I love her so much that I am willing to pay ten million dollars to the person who makes her smile.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'that is the difference the reality is that i love her so much that i am willing to pay ten million dollars to the person who makes her smile', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 69, NULL, 'So when Allah says that He will give the reward of ten years of اعتکاف to the one who fulfills Asif''s need, the common reading of that HADEES becomes a motivation to act for that reward. Yet most people miss what it reveals: how much Allah loves me. Ya Allah, You love me so much that You would give that much reward to anyone who fulfills my need and removes my constriction for me. SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'so when allah says that he will give the reward of ten years of اعتكاف to the one who fulfills asifs need the common reading of that hadees becomes a motivation to act for that reward yet most people miss what it reveals how much allah loves me ya allah you love me so much that you would give that much reward to anyone who fulfills my need and removes my constriction for me subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 70, NULL, 'So this HADEES can also be heard another way: “O one who feels low. O one who feels depressed. O one who feels burdened and constricted by troubles. It is you I am looking at. It is you for whom I am opening doors, because I want to see you happy. For your happiness, I will reward anyone with this amount of ثواب if they strive to bring you ease.”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'so this hadees can also be heard another way o one who feels low o one who feels depressed o one who feels burdened and constricted by troubles it is you i am looking at it is you for whom i am opening doors because i want to see you happy for your happiness i will reward anyone with this amount of ثواب if they strive to bring you ease', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 71, NULL, 'This is the رحمۃ He has for us. AllahuAkbar.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'this is the رحمه he has for us allahuakbar', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 72, NULL, 'My perspective changes completely when I see another person in need. I begin to see that this is a person Allah loves. He loves him so much that He is willing to reward me with immense generosity and immense blessings for helping him. Then I ask myself what place I may gain in His sight if I bring ease to someone He loves.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'my perspective changes completely when i see another person in need i begin to see that this is a person allah loves he loves him so much that he is willing to reward me with immense generosity and immense blessings for helping him then i ask myself what place i may gain in his sight if i bring ease to someone he loves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 73, NULL, 'When someone does something deeply kind for a person I love, that person becomes dearer to me. He comes closer to my heart. In the same way, once I understand this view, it is nearness to Allah سُبْحَانَهُ وَتَعَالَى that moves me to help another person, more than the reward itself.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'when someone does something deeply kind for a person i love that person becomes dearer to me he comes closer to my heart in the same way once i understand this view it is nearness to allah سبحانه وتعالي that moves me to help another person more than the reward itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 74, NULL, 'I have to appreciate why such immense rewards are attached to such simple acts. They come from the love He has for us. Because of that love, He showers His blessings upon even the smallest acts of kindness. He may grant the reward of ten or twenty Hajj for a few hours of worship. I may act for the reward, or I may act out of gratitude for that divine love.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i have to appreciate why such immense rewards are attached to such simple acts they come from the love he has for us because of that love he showers his blessings upon even the smallest acts of kindness he may grant the reward of ten or twenty hajj for a few hours of worship i may act for the reward or i may act out of gratitude for that divine love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 76, NULL, 'I will give another example. There is a HADEES in which Rasul Allah ﷺ tells us that when I visit a sick person, I should ask him to pray for me and for my forgiveness.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i will give another example there is a hadees in which rasul allah ﷺ tells us that when i visit a sick person i should ask him to pray for me and for my forgiveness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 77, NULL, 'At first, that sounds reversed. I would expect myself to be the one praying for the sick person, asking Allah to grant him health. He appears to be the one in need of my prayers. Yet the HADEES says that I should ask him to pray for me and for my forgiveness.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'at first that sounds reversed i would expect myself to be the one praying for the sick person asking allah to grant him health he appears to be the one in need of my prayers yet the hadees says that i should ask him to pray for me and for my forgiveness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 78, NULL, 'What does that mean? I can make it clearer with an example.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'what does that mean i can make it clearer with an example', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 79, NULL, 'My daughter may fall very ill, God forbid. May Allah protect our children from trials. I give this only as an example to make the point clearer. She becomes very sick and is admitted to the emergency room. The doctors come to me and say that she is in severe pain and cannot breathe properly.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'my daughter may fall very ill god forbid may allah protect our children from trials i give this only as an example to make the point clearer she becomes very sick and is admitted to the emergency room the doctors come to me and say that she is in severe pain and cannot breathe properly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 80, NULL, 'As a father, I cannot even imagine the state I would be in if that ever happened. Nothing is more painful for a parent than seeing his own child suffer, whether the suffering is physical, mental, or spiritual. Then the doctor tells me that she cannot breathe and must be put on a ventilator.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'as a father i cannot even imagine the state i would be in if that ever happened nothing is more painful for a parent than seeing his own child suffer whether the suffering is physical mental or spiritual then the doctor tells me that she cannot breathe and must be put on a ventilator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 81, NULL, 'At that moment, there would be no other place in the world where I would want to be. I would not leave my daughter''s side even for a second. I would sit beside her because I love her so much. I would remain at her bedside, constantly praying for her.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'at that moment there would be no other place in the world where i would want to be i would not leave my daughters side even for a second i would sit beside her because i love her so much i would remain at her bedside constantly praying for her', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 82, NULL, 'Then Allah answers my prayers. She wakes up. She says, “Babu! I want ice cream.”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'then allah answers my prayers she wakes up she says babu i want ice cream', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 83, NULL, 'I would be ready at once. “You want ice cream? Of course. What flavor do you want?” If I could not find it there, I would drive wherever I had to drive to get that ice cream for her. That is what I would do.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i would be ready at once you want ice cream of course what flavor do you want if i could not find it there i would drive wherever i had to drive to get that ice cream for her that is what i would do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 84, NULL, 'At that point, I would feel intensely close to her. “What else do you want, sweetheart? Is there anything else I can do for you? Is there anything else I can get for you?”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'at that point i would feel intensely close to her what else do you want sweetheart is there anything else i can do for you is there anything else i can get for you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 85, NULL, 'It so happened that, just before she fell ill, we had a terrible fight. She had disobeyed me and spoken to me very rudely. I was still angry with her when all of this happened.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'it so happened that just before she fell ill we had a terrible fight she had disobeyed me and spoken to me very rudely i was still angry with her when all of this happened', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 86, NULL, 'Then she wakes up and remembers what she did. She says, “Babu, I''m sorry for what I did and said. Please forgive me!”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'then she wakes up and remembers what she did she says babu im sorry for what i did and said please forgive me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 87, NULL, 'I know what I would say: “Forgive you? Sweetheart, there''s nothing to forgive. I''m not upset with you at all anymore. Don''t even think about it.”', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i know what i would say forgive you sweetheart theres nothing to forgive im not upset with you at all anymore dont even think about it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 88, NULL, 'That is how parents are with their children. There is nothing strange in it.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'that is how parents are with their children there is nothing strange in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 89, NULL, 'If this is how deeply I love my child, then Allah''s love for his creation is beyond what I can imagine. According to a HADEES, Allah holds the love of seventy mothers for every single one of his creation. In such an affliction, I felt intensely close to my daughter. When a creation of Allah سُبْحَانَهُ وَتَعَالَى is going through trials and afflictions, Allah is nearer to him than I can grasp.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'if this is how deeply i love my child then allahs love for his creation is beyond what i can imagine according to a hadees allah holds the love of seventy mothers for every single one of his creation in such an affliction i felt intensely close to my daughter when a creation of allah سبحانه وتعالي is going through trials and afflictions allah is nearer to him than i can grasp', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 90, NULL, 'I was ready to respond to anything my daughter asked for in that moment, though my ability is extremely limited. But when a human being, a creation of Allah سُبْحَانَهُ وَتَعَالَى, is in pain and asks for something, whether for himself or for someone else, Allah does not refuse him in that moment.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i was ready to respond to anything my daughter asked for in that moment though my ability is extremely limited but when a human being a creation of allah سبحانه وتعالي is in pain and asks for something whether for himself or for someone else allah does not refuse him in that moment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 91, NULL, 'When I am afflicted, Allah is closest to me in that very moment, closer than any human being could ever be. When I turn to Allah for forgiveness with true repentance, there is nothing He would not forgive, whatever sin I may have committed and however terribly I may have behaved. Allah would forgive instantly.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'when i am afflicted allah is closest to me in that very moment closer than any human being could ever be when i turn to allah for forgiveness with true repentance there is nothing he would not forgive whatever sin i may have committed and however terribly i may have behaved allah would forgive instantly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 92, NULL, 'I do not hesitate for a second to forgive my child. The mercy of Allah is far greater. He is the One who makes Himself known through love. He holds the love of seventy mothers for His creation, so He does not refuse forgiveness.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i do not hesitate for a second to forgive my child the mercy of allah is far greater he is the one who makes himself known through love he holds the love of seventy mothers for his creation so he does not refuse forgiveness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 93, NULL, 'If I were angry with my son, and my daughter woke up and said to me, “Babu! Please forgive my brother,” would I refuse? “Oh my God, you are in such a difficult state. You are in so much pain. You are suffering so much right now, and even in this state you are concerned about your brother? You want me to forgive him? Your request will surely be granted. Of course I forgive him. I will give you anything you want right now. All you have to do is ask.” SubhanAllah', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'if i were angry with my son and my daughter woke up and said to me babu please forgive my brother would i refuse oh my god you are in such a difficult state you are in so much pain you are suffering so much right now and even in this state you are concerned about your brother you want me to forgive him your request will surely be granted of course i forgive him i will give you anything you want right now all you have to do is ask subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 94, NULL, 'I can now appreciate the beauty of that HADEES. In the very middle of my affliction, I raise my hands and ask Allah سُبْحَانَهُ وَتَعَالَى to fulfill another person''s need. I may ask for my own forgiveness, or for the forgiveness of someone else. At that moment, there is no way Allah turns down my request, because my trial has brought me extremely close to Him. He is right by my bedside, holding my hand. That is how His رحمۃ manifests.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'i can now appreciate the beauty of that hadees in the very middle of my affliction i raise my hands and ask allah سبحانه وتعالي to fulfill another persons need i may ask for my own forgiveness or for the forgiveness of someone else at that moment there is no way allah turns down my request because my trial has brought me extremely close to him he is right by my bedside holding my hand that is how his رحمه manifests', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 95, NULL, 'This is why trials become such a perfect opening for me to ask Allah for what I need. A trial can become one of the best experiences a person ever has: an experience of awareness, nearness, and closeness to the love of Allah سُبْحَانَهُ وَتَعَالَى.', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'this is why trials become such a perfect opening for me to ask allah for what i need a trial can become one of the best experiences a person ever has an experience of awareness nearness and closeness to the love of allah سبحانه وتعالي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'manifestations of rehma', 'Manifestations of REHMA', 96, NULL, 'If Allah is so loving, why does He afflict people in the first place?', '', NULL, NULL, NULL, NULL, 'surah al fateha manifestations of rehma', 'if allah is so loving why does he afflict people in the first place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'manifestations of rehma', 'Manifestations of REHMA', 97, NULL, 'Ash-Shura: 30وَمَآ أَصَبَكُم مِّن مُّصِيبَةٍۢ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا۟ عَن كَثِيرٍۢ', '', 'وَمَآ أَصَبَكُم مِّن مُّصِيبَةٍۢ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا۟ عَن كَثِيرٍۢ', 'Ash-Shura: 30', 42, 30, 'surah al fateha manifestations of rehma', 'ash shura 30وما اصبكم من مصيبه فبما كسبت ايديكم ويعفوا عن كثير', 'وما اصبكم من مصيبه فبما كسبت ايديكم ويعفوا عن كثير');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 0, NULL, 'I begin, InshaAllah, with the linguistic meaning of the word رب. Before that meaning, there is a striking sign from the جمال: the beauty of the Quran. It belongs to the symmetrical beauty of the Quran, especially the symmetry in its use of the words Allah and RAB.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i begin inshaallah with the linguistic meaning of the word رب before that meaning there is a striking sign from the جمال the beauty of the quran it belongs to the symmetrical beauty of the quran especially the symmetry in its use of the words allah and rab', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 2, NULL, 'Sayingبِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎۱‏ٱلْحَمْدُ لِلَّهِرَبِّ ٱلْعَلَمِينَ ‎۲‏ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎۳‏مَلِكِ يَوْمِ ٱلدِّينِ ‎۴‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‎۵‏ٱهْدِنَا ٱلصِّرَطَ ٱلْمُسْتَقِيمَ ‎۶‏صِرَطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ( 1 ) In the Name of Allah, the Most Beneficent, the Most Merciful.', '', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ ۱‏ ٱلْحَمْدُ لِلَّهِرَبِّ ٱلْعَلَمِينَ ‎ ۲‏ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ ۳‏ مَلِكِ يَوْمِ ٱلدِّينِ ‎ ۴‏ إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‎ ۵‏ ٱهْدِنَا ٱلصِّرَطَ ٱلْمُسْتَقِيمَ ‎ ۶‏ صِرَطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ ٱلْمَغْضُوبِ عَلَيْهِمْ وَلَا ٱلضَّآلِّينَ', 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'sayingبسم الله الرحمن الرحيم ۱ الحمد للهرب العلمين ۲ الرحمن الرحيم ۳ ملك يوم الدين ۴ اياك نعبد واياك نستعين ۵ اهدنا الصرط المستقيم ۶ صرط الذين انعمت عليهم غير المغضوب عليهم ولا الضالين 1 in the name of allah the most beneficent the most merciful', 'بسم الله الرحمن الرحيم ۱ الحمد للهرب العلمين ۲ الرحمن الرحيم ۳ ملك يوم الدين ۴ اياك نعبد واياك نستعين ۵ اهدنا الصرط المستقيم ۶ صرط الذين انعمت عليهم غير المغضوب عليهم ولا الضالين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 3, NULL, '( 2 ) All praises and thanks belong to Allah, the Lord of the Alamin. ( 3 ) The Most Beneficent, the Most Merciful. ( 4 ) The Only Owner of the Day of Recompense. ( 5 ) You we worship, and You we ask for help. ( 6 ) Guide us to the Straight Way. ( 7 ) The Way of those on whom You have bestowed Your Grace, not of those who earned Your Anger, nor of those who went astray.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', '2 all praises and thanks belong to allah the lord of the alamin 3 the most beneficent the most merciful 4 the only owner of the day of recompense 5 you we worship and you we ask for help 6 guide us to the straight way 7 the way of those on whom you have bestowed your grace not of those who earned your anger nor of those who went astray', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 4, NULL, 'In the first Surah of the Quran, سُورَۃُ الْفَاتِحَۃِ, I find that Allah is mentioned twice, and that RAB is mentioned once after those two mentions. The فاتحۃ begins with بِسْمِ اللَّہِ الرَّحْمَنِ الرَّحِیمِ. Allah is therefore mentioned in the first verse. Then comes اَلْحَمْدُ لِلَّہِ, another mention of Allah, followed by رب العلمین.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'in the first surah of the quran سوره الفاتحه i find that allah is mentioned twice and that rab is mentioned once after those two mentions the فاتحه begins with بسم الله الرحمن الرحيم allah is therefore mentioned in the first verse then comes الحمد لله another mention of allah followed by رب العلمين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 5, NULL, 'So the name Allah appears twice before the word RAB appears once. After that, in the remaining verses, neither Allah nor RAB is mentioned again. This is what stands at the beginning of the Quran.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'so the name allah appears twice before the word rab appears once after that in the remaining verses neither allah nor rab is mentioned again this is what stands at the beginning of the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 6, NULL, 'At the end of the Quran, in سُورَۃُ النَّاسِ, the pattern appears from the other direction when I work backward.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'at the end of the quran in سوره الناس the pattern appears from the other direction when i work backward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 7, NULL, 'An-Nas: 1قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِSay: "I seek refuge with the Lord of mankind,', '', NULL, 'An-Nas: 1', NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'an nas 1قل اعوذ برب الناسsay i seek refuge with the lord of mankind', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 8, NULL, 'In سُورَۃُ النَّاسِ, the word mentioned is not Allah but RAB: قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'in سوره الناس the word mentioned is not allah but rab قل اعوذ برب الناس', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 9, NULL, 'Al-Falaq: 1قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِSay: "I seek refuge with the Lord of the daybreak,', '', NULL, 'Al-Falaq: 1', NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'al falaq 1قل اعوذ برب الفلقsay i seek refuge with the lord of the daybreak', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 10, NULL, 'When I go to the سورۃ before it, سُورَۃُ الْفَلَقِ, the word mentioned is not Allah but RAB: قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ. RAB appears again.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'when i go to the سوره before it سوره الفلق the word mentioned is not allah but rab قل اعوذ برب الفلق rab appears again', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 11, NULL, 'Al-Ikhlas: 1قُلْ هُوَ ٱللَّهُ أَحَدٌSay :"He is Allah, the unique!', '', NULL, 'Al-Ikhlas: 1', NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'al ikhlas 1قل هو الله احدsay he is allah the unique', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 12, NULL, 'When I go to the سورۃ before that, سُورَۃُ الْاِخْلَاصِ, the word mentioned is Allah, not RAB: قُلْ ھُوَ اللَّہُ اَحَدٌ. SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'when i go to the سوره before that سوره الاخلاص the word mentioned is allah not rab قل هو الله احد subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 13, NULL, 'In the beginning, سُورَۃُ الْفَاتِحَۃِ, Allah is mentioned twice, and then RAB is mentioned. From the end, the pattern reverses: RAB is mentioned twice, and then Allah is mentioned. SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'in the beginning سوره الفاتحه allah is mentioned twice and then rab is mentioned from the end the pattern reverses rab is mentioned twice and then allah is mentioned subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 14, NULL, 'The last two Surahs use the word RAB, with no mention of the name Allah. In سُورَۃُ اِخْلَاصِ, only the name Allah appears, with no mention of RAB. The result is a perfect symmetry: one Surah at the beginning, and several Surahs at the end.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the last two surahs use the word rab with no mention of the name allah in سوره اخلاص only the name allah appears with no mention of rab the result is a perfect symmetry one surah at the beginning and several surahs at the end', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 16, NULL, 'The root of the word رب is actually رَبَبٌ. In Arabic, the two با are combined. A شدۃ is then placed over the با, producing ربّ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the root of the word رب is actually ربب in arabic the two با are combined a شده is then placed over the با producing رب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 17, NULL, 'In most English translations, رب is rendered as “lord.” But the word “lord” does not carry the meaning clearly. For many English readers, it may only call to mind a title, or even a phrase such as “the Lord of the Rings.” That is why Arab linguists do not regard “lord” as a strong translation of رب. It fails to reveal the true meaning and power of the word.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'in most english translations رب is rendered as lord but the word lord does not carry the meaning clearly for many english readers it may only call to mind a title or even a phrase such as the lord of the rings that is why arab linguists do not regard lord as a strong translation of رب it fails to reveal the true meaning and power of the word', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 18, NULL, 'RABB', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'rabb', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 19, NULL, 'I approach the word رب first through its language. The word رب is a composite word, like الہ, which has already been examined. I have shown that الہ is not used only for Allah. It can apply to many other realities in human life.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i approach the word رب first through its language the word رب is a composite word like اله which has already been examined i have shown that اله is not used only for allah it can apply to many other realities in human life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 20, NULL, 'In the same way, رب is not used only for Allah. The word carries several meanings in the language. It is used for Allah, but it may also be used for human beings and for other created relations, such as parents, teachers, and guardians. The first point, then, is that رب is not specific to Allah. In Classical Arabic, رب can be used for Allah, for human beings, and for other things.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'in the same way رب is not used only for allah the word carries several meanings in the language it is used for allah but it may also be used for human beings and for other created relations such as parents teachers and guardians the first point then is that رب is not specific to allah in classical arabic رب can be used for allah for human beings and for other things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 21, NULL, 'The classical definition of رب is:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the classical definition of رب is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 22, NULL, 'Sayingالرَبُّ ھُوَ المَالِکُ وَ السَّیِّد وَ المُرَبِّی وَ المُرْشَدُ وَ المُنعِمُ وَ القَیِّمُ', '', 'الرَبُّ ھُوَ المَالِکُ وَ السَّیِّد وَ المُرَبِّی وَ المُرْشَدُ وَ المُنعِمُ وَ القَیِّمُ', 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'sayingالرب هو المالك و السيد و المربي و المرشد و المنعم و القيم', 'الرب هو المالك و السيد و المربي و المرشد و المنعم و القيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 23, NULL, 'I understand a true رب as one who gathers six meanings. I may also say that Allah, as رب, is all six at once: He is مالک, He is سید, He is مربی, He is مرشد, He is منعم, and He is قیم. The word RAB therefore does not carry one meaning only. It joins all six meanings together.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i understand a true رب as one who gathers six meanings i may also say that allah as رب is all six at once he is مالك he is سيد he is مربي he is مرشد he is منعم and he is قيم the word rab therefore does not carry one meaning only it joins all six meanings together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 25, NULL, 'MALIK', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'malik', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 26, NULL, 'I begin with the first meaning: مالک, owner. Whoever owns something, or has authority of ownership over someone, is called رب. The thing owned is called مِلک. This is not the English word “milk,” the milk produced by cows. In Arabic, مِلک or ملکیۃ means property, and the owner of that property is called مالک.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i begin with the first meaning مالك owner whoever owns something or has authority of ownership over someone is called رب the thing owned is called ملك this is not the english word milk the milk produced by cows in arabic ملك or ملكيه means property and the owner of that property is called مالك', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 27, NULL, 'I also find this meaning in ordinary life. Human beings own phones, iPads, computers, cars, and houses. In that limited sense, such ownership makes them مالک. Since “owner” is one of the meanings of رب, that ownership also makes a human being a رب in that sense.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i also find this meaning in ordinary life human beings own phones ipads computers cars and houses in that limited sense such ownership makes them مالك since owner is one of the meanings of رب that ownership also makes a human being a رب in that sense', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 28, NULL, 'I see this limited kind of ownership in teachers over their students, and in parents over their young children. Children may protest, “It is my life, Mom. You cannot tell me what to do. You do not own me.” Those feelings are common today, and, to be fair, many of us felt the same way while growing up. Still, parents do have a form of ownership over their children until those children become adults.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i see this limited kind of ownership in teachers over their students and in parents over their young children children may protest it is my life mom you cannot tell me what to do you do not own me those feelings are common today and to be fair many of us felt the same way while growing up still parents do have a form of ownership over their children until those children become adults', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 29, NULL, 'But this is not ultimate or absolute ownership. Parents give birth to their children, but they do not create them. Allah created the child, and Allah created the parent. Therefore, ultimate and absolute ownership belongs only to Allah. So, although parents and teachers may be رب in one sense of the word, Allah is the absolute owner and the absolute رب of His creation. He is مالک. And if He is مالک, then I am His property. I am His مِلکِیَّۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'but this is not ultimate or absolute ownership parents give birth to their children but they do not create them allah created the child and allah created the parent therefore ultimate and absolute ownership belongs only to allah so although parents and teachers may be رب in one sense of the word allah is the absolute owner and the absolute رب of his creation he is مالك and if he is مالك then i am his property i am his ملكيه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 31, NULL, 'SAYYED', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'sayyed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 32, NULL, 'The second meaning of the word Rabb can be seen in the word سید, which complements the earlier meaning of مالک. The word مالک means owner, while سید means someone who has authority. سید is the one in charge. The difference is simple: مالک is someone who has ownership, and سید is someone who has authority.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the second meaning of the word rabb can be seen in the word سيد which complements the earlier meaning of مالك the word مالك means owner while سيد means someone who has authority سيد is the one in charge the difference is simple مالك is someone who has ownership and سيد is someone who has authority', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 33, NULL, 'I may own something without having complete authority over it. That is possible. I may own a car, for example, but I still have to register it. I still have to get it inspected every year. I still have to drive within the speed limit. I still have to drive it on the road. I cannot simply drive on the sidewalk because I feel like it, unless I am in Pakistan. So, even though I own my car, I do not necessarily have complete authority over it.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i may own something without having complete authority over it that is possible i may own a car for example but i still have to register it i still have to get it inspected every year i still have to drive within the speed limit i still have to drive it on the road i cannot simply drive on the sidewalk because i feel like it unless i am in pakistan so even though i own my car i do not necessarily have complete authority over it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 34, NULL, 'The reverse is also true. I may have complete authority over something without having complete ownership of it. Take the computer in my office. I can do whatever I want with the software installed on it. I can install new programs. I can uninstall programs I do not like. Nobody will stop me or question me about that. But I do not own the computer. My company owns it.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the reverse is also true i may have complete authority over something without having complete ownership of it take the computer in my office i can do whatever i want with the software installed on it i can install new programs i can uninstall programs i do not like nobody will stop me or question me about that but i do not own the computer my company owns it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 35, NULL, 'So I may own something without having complete authority over it. And I may have complete authority over something without necessarily owning it.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'so i may own something without having complete authority over it and i may have complete authority over something without necessarily owning it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 36, NULL, 'Allah, as رب, has absolute ownership, and He has absolute authority. He has both at once. He may do whatever He wills with His property, whenever He wills. If He wills to burn it, He may burn it. If He wills to tear it apart, He may tear it apart. If He wills to drown it, toss it away, or discard it, He may do so by His will.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'allah as رب has absolute ownership and he has absolute authority he has both at once he may do whatever he wills with his property whenever he wills if he wills to burn it he may burn it if he wills to tear it apart he may tear it apart if he wills to drown it toss it away or discard it he may do so by his will', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 37, NULL, 'No one has the right to question Him about it, because He has complete ownership and complete authority over us and over everything else in the universe. Even complaint and grief do not bind Him. He is not obliged to heed them. They make no difference to Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'no one has the right to question him about it because he has complete ownership and complete authority over us and over everything else in the universe even complaint and grief do not bind him he is not obliged to heed them they make no difference to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 38, NULL, 'When parents ground their children, the matter becomes easier to see. If I take my daughter''s phone away, she may cry and complain as much as she wants, but she is not getting it back. In that setting, I am her مالک, and she and her phone are my ملکیۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'when parents ground their children the matter becomes easier to see if i take my daughters phone away she may cry and complain as much as she wants but she is not getting it back in that setting i am her مالك and she and her phone are my ملكيه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 39, NULL, 'If our crying and grumbling do not move our parents, though their capacity as رب is limited, then they certainly do not compel the One who is the absolute and ultimate رب. We are creation. He is our Creator.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'if our crying and grumbling do not move our parents though their capacity as رب is limited then they certainly do not compel the one who is the absolute and ultimate رب we are creation he is our creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 40, NULL, 'I constantly seem to forget that he is not the one on trial. We are. We have reversed the matter completely.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i constantly seem to forget that he is not the one on trial we are we have reversed the matter completely', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 41, NULL, 'Today, mankind has placed Allah in the witness stand and taken the judge''s seat. We question his every act without shame. People ask why, if he is so powerful, he does not remove evil from the world. They ask how, if he is so loving and merciful, he could allow pain to touch them. They say that they prayed, yet the job or promotion did not come. They insist that they are good people, that they paid their taxes honestly, that they paid their زکواۃ, and that they brush their teeth twice every day. Then they ask why he did this to them.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'today mankind has placed allah in the witness stand and taken the judges seat we question his every act without shame people ask why if he is so powerful he does not remove evil from the world they ask how if he is so loving and merciful he could allow pain to touch them they say that they prayed yet the job or promotion did not come they insist that they are good people that they paid their taxes honestly that they paid their زكواه and that they brush their teeth twice every day then they ask why he did this to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 42, NULL, 'This is the reversal. The reality is that he is the judge. He is the مالک. He is the سید. We are his property and his subjects. He has every right to question us. We have no right at all to question him.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'this is the reversal the reality is that he is the judge he is the مالك he is the سيد we are his property and his subjects he has every right to question us we have no right at all to question him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 43, NULL, 'For this reason, I find it astonishing that Allah still allowed us to understand something of the wisdom in his design through the Quran and through his messengers. I see this as an immense act of mercy and generosity from him, because he is not obligated to do anything for us. He is not there to serve us. Yet he does so anyway, because that is what a true رب does.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'for this reason i find it astonishing that allah still allowed us to understand something of the wisdom in his design through the quran and through his messengers i see this as an immense act of mercy and generosity from him because he is not obligated to do anything for us he is not there to serve us yet he does so anyway because that is what a true رب does', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 45, NULL, 'I come to the third meaning of the word: مُرَبَّی. This is a powerful word. مُرَبَّی means one who ensures growth: someone who cares for a thing, nurtures it, and enables it to develop.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i come to the third meaning of the word مربي this is a powerful word مربي means one who ensures growth someone who cares for a thing nurtures it and enables it to develop', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 46, NULL, 'In other words, a مُرَبَّی is responsible for the growth and development of whatever has been placed under his care. Ownership and authority alone do not guarantee this care. I may own something and have control over it, yet neglect it. A neglected backyard makes the point plainly. People own cars but never service them. We possess our bodies, yet we often mistreat them. Ownership is present, and a measure of authority is present, but care is missing.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'in other words a مربي is responsible for the growth and development of whatever has been placed under his care ownership and authority alone do not guarantee this care i may own something and have control over it yet neglect it a neglected backyard makes the point plainly people own cars but never service them we possess our bodies yet we often mistreat them ownership is present and a measure of authority is present but care is missing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 47, NULL, 'So ownership and authority over something do not necessarily mean that it will be properly looked after. A رب is the one who owns, has complete authority over what he owns, and also takes complete care of it. He ensures its proper growth. He nurtures it. This act of caring for what belongs to him and nurturing it is called تربیۃ. I find this phenomenon throughout the world.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'so ownership and authority over something do not necessarily mean that it will be properly looked after a رب is the one who owns has complete authority over what he owns and also takes complete care of it he ensures its proper growth he nurtures it this act of caring for what belongs to him and nurturing it is called تربيه i find this phenomenon throughout the world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 48, NULL, 'TARBIYAH', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'tarbiyah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 49, NULL, 'The poet says:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the poet says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 50, NULL, 'Sayingمِن دُرَّۃٍ بَیضَآءَ صَافِیَۃً || مِمَّا تَرَبَّبَ حَائِرَ البَحرٍ', '', 'مِن دُرَّۃٍ بَیضَآءَ صَافِیَۃً || مِمَّا تَرَبَّبَ حَائِرَ البَحرٍ', 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'sayingمن دره بيضاء صافيه مما تربب حاير البحر', 'من دره بيضاء صافيه مما تربب حاير البحر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 51, NULL, 'I see the depth of the ocean nurturing the clear white pearl. The poet calls the ocean a رب because it helps develop the pearl inside its shell. A tree is also called a رب because it nurtures the fruit it bears.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i see the depth of the ocean nurturing the clear white pearl the poet calls the ocean a رب because it helps develop the pearl inside its shell a tree is also called a رب because it nurtures the fruit it bears', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 52, NULL, 'So I find many forms of تربیۃ throughout the world. The concept of تربیۃ is tied to setting limits and drawing boundaries. That is what تربیۃ means.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'so i find many forms of تربيه throughout the world the concept of تربيه is tied to setting limits and drawing boundaries that is what تربيه means', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 53, NULL, 'The تربیۃ of a plant means caring for it through ordered limits:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the تربيه of a plant means caring for it through ordered limits', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 54, NULL, 'watering it at the right time making sure it receives enough sunlight protecting it from too much sunlight protecting it from insects and bugs', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'watering it at the right time making sure it receives enough sunlight protecting it from too much sunlight protecting it from insects and bugs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 55, NULL, 'In other words, تربیۃ is a set of dos and do nots that continues until the plant matures into a tree and begins to bear fruit. If the plant is simply left to grow on its own, that is not تربیۃ, because no boundaries have been set.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'in other words تربيه is a set of dos and do nots that continues until the plant matures into a tree and begins to bear fruit if the plant is simply left to grow on its own that is not تربيه because no boundaries have been set', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 56, NULL, 'In the same way, the تربیۃ of children means caring for their physical needs, their diet, and their clothing. It also means caring for their minds by educating them and protecting them. In essence, it is the close watching of their growth from birth until they mature into healthy, sound, decent human beings: physically, psychologically, and socially. This is تَرْبِیَۃُ الْاَوْلَادِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'in the same way the تربيه of children means caring for their physical needs their diet and their clothing it also means caring for their minds by educating them and protecting them in essence it is the close watching of their growth from birth until they mature into healthy sound decent human beings physically psychologically and socially this is تربيه الاولاد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 57, NULL, 'I do not understand تربیۃ as a quick or easy process. It is long, demanding, and full of labor. In fact, it is among the hardest forms of work: never-ending, thankless, and full-time.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i do not understand تربيه as a quick or easy process it is long demanding and full of labor in fact it is among the hardest forms of work never ending thankless and full time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 58, NULL, 'This is why, when I recite التحیات in every prayer, I say: اَللّٰھُمَّ مَغْفَرٌلِی - Oh Allah forgive me و لوالدی and my parents. وَالرَّحْمُھُمَا کَمَا رَبَّیَانِی صَغِیرَۃً and have mercy on them just as they had mercy on me during the period of my تربیۃ when I was young.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'this is why when i recite التحيات in every prayer i say اللهم مغفرلي oh allah forgive me و لوالدي and my parents والرحمهما كما ربياني صغيره and have mercy on them just as they had mercy on me during the period of my تربيه when i was young', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 59, NULL, 'In this statement, I find the primary ingredient of ربوبیۃ: mercy (رحمۃ). Mercy is the main component of ربوبیۃ. Without mercy, there can be no ربوبیۃ. Mercy is made of love, care, and concern. That is what ربوبیۃ contains.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'in this statement i find the primary ingredient of ربوبيه mercy رحمه mercy is the main component of ربوبيه without mercy there can be no ربوبيه mercy is made of love care and concern that is what ربوبيه contains', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 60, NULL, 'The image of ربوبیۃ appears in the care some people give to plants. They spray each leaf with water, then clean it gently with a soft cloth. That kind of love, care, and gentleness shows what ربوبیۃ is.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the image of ربوبيه appears in the care some people give to plants they spray each leaf with water then clean it gently with a soft cloth that kind of love care and gentleness shows what ربوبيه is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 61, NULL, 'It is not harshness. It is not beating. It is not psychological, emotional, or physical abuse. It is not forcing submission through guilt. It is love, patience, and kindness. That is the Islamic way of ربوبیۃ. Contrary to what appears in movies and in society today, the Islamic way of ربوبیۃ has always been رحمۃ. The proof is in the life of Rasul Allah ﷺ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'it is not harshness it is not beating it is not psychological emotional or physical abuse it is not forcing submission through guilt it is love patience and kindness that is the islamic way of ربوبيه contrary to what appears in movies and in society today the islamic way of ربوبيه has always been رحمه the proof is in the life of rasul allah ﷺ', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 62, NULL, 'Our prophet ﷺ took the most vicious people, the most barbaric people, and transformed them without a single slap, taunt, sarcastic remark, or insult. He made them رَضِیَ اللَّہُ عَنْہُ, the greatest title a human being can receive: رَضِیَ اللَّہُ عَنْہُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'our prophet ﷺ took the most vicious people the most barbaric people and transformed them without a single slap taunt sarcastic remark or insult he made them رضي الله عنه the greatest title a human being can receive رضي الله عنه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 63, NULL, 'I do not mention the names of these صحابۃ without saying رَضِیَ اللَّہُ عَنْہُ. Our prophet did that. How? Through love, gentleness, kindness, forgiveness, and patience; through his أخلاق. That is ربوبیۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i do not mention the names of these صحابه without saying رضي الله عنه our prophet did that how through love gentleness kindness forgiveness and patience through his اخلاق that is ربوبيه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 64, NULL, 'What did he ask of us in return? After giving twenty-three years of his life to our تربیۃ, in his last sermon, after حِجَّۃُ الْوَدَاعِ, he said:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'what did he ask of us in return after giving twenty three years of his life to our تربيه in his last sermon after حجه الوداع he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 65, NULL, 'Sayingیا أُمَّتَی لا تُسَوِّدَ وَجْھِی یوم القیامۃ', '', 'یا أُمَّتَی لا تُسَوِّدَ وَجْھِی یوم القیامۃ', 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'sayingيا امتي لا تسود وجهي يوم القيامه', 'يا امتي لا تسود وجهي يوم القيامه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 66, NULL, 'My people! Do not embarrass me before Allah on the Day of Judgment! When the result falls short, exceptions do not decide the matter. If most students in a class fail, the principal questions the teacher: What is happening? Why have so many students failed in this class?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'my people do not embarrass me before allah on the day of judgment when the result falls short exceptions do not decide the matter if most students in a class fail the principal questions the teacher what is happening why have so many students failed in this class', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 67, NULL, 'Our Prophet ﷺ, after twenty-three years of service and تربیۃ, asked only one thing in return: یا أُمَّتَی لا تُسَوِّدَ وَجْھِی یوم القیامۃ. Do not embarrass me before Allah on the Day of Judgment. May Allah make us among those who make our Prophet proud.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'our prophet ﷺ after twenty three years of service and تربيه asked only one thing in return يا امتي لا تسود وجهي يوم القيامه do not embarrass me before allah on the day of judgment may allah make us among those who make our prophet proud', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 69, NULL, 'MURSHAD', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'murshad', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 70, NULL, 'The fourth meaning of the word رب is مُرشَد. He is the one who sets things in the right direction, sets them on the right path, and puts them to proper use. This is مُرشَد.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the fourth meaning of the word رب is مرشد he is the one who sets things in the right direction sets them on the right path and puts them to proper use this is مرشد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 71, NULL, 'The word مُرشَد comes from رُشد, which in classical Arabic means to ripen, the final stage of fruit. For this reason, رُشد also means rationality, reason, or maturity, because these are the final stages of the intellect.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the word مرشد comes from رشد which in classical arabic means to ripen the final stage of fruit for this reason رشد also means rationality reason or maturity because these are the final stages of the intellect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 72, NULL, 'So مُرشَد is the one who takes something in its raw form and works on it until it ripens and matures. Then He puts it to its proper use and sets it in the right direction.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'so مرشد is the one who takes something in its raw form and works on it until it ripens and matures then he puts it to its proper use and sets it in the right direction', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 73, NULL, 'A teacher may train a student in computer science and then also find that student a job, so the training can be applied. In that case, the teacher has acted as a مُرشَد. A مُرشَدis not someone who brings a person to maturity and then leaves that person unused. He sets the person on the path. He guides that person forward from the point of maturity. He provides the opportunity to practice what has been learned, so that the trained person and others can benefit from that learning. That is مُرشَد.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'a teacher may train a student in computer science and then also find that student a job so the training can be applied in that case the teacher has acted as a مرشد a مرشدis not someone who brings a person to maturity and then leaves that person unused he sets the person on the path he guides that person forward from the point of maturity he provides the opportunity to practice what has been learned so that the trained person and others can benefit from that learning that is مرشد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 74, NULL, 'I learn from this that Allah, as رب, does not only own us, hold complete authority over us, and nurture us with love and care. He also creates opportunities for us to put our training to use. He trains us by placing people in our path who help us grow and develop. He finds the perfect friend for us, someone who helps us grow and mature. Then He guides us to put that training to use by becoming good friends ourselves to other people. That is مُرشَد.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i learn from this that allah as رب does not only own us hold complete authority over us and nurture us with love and care he also creates opportunities for us to put our training to use he trains us by placing people in our path who help us grow and develop he finds the perfect friend for us someone who helps us grow and mature then he guides us to put that training to use by becoming good friends ourselves to other people that is مرشد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 75, NULL, 'Even parents and teachers cannot always do this. They may complete the تربیۃ of their children, but they cannot always put them to proper use. Children have to find their own path. But Allah, as رب, goes further. He sets us on the right path after our training has been completed. SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'even parents and teachers cannot always do this they may complete the تربيه of their children but they cannot always put them to proper use children have to find their own path but allah as رب goes further he sets us on the right path after our training has been completed subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 77, NULL, 'MUNIM', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'munim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 78, NULL, 'I take the next meaning of رب from the word مُنعِم. The word مُنعِم is used for the one who bestows gifts, the one who gives blessings. It comes from the root نِعَم or نعمۃ, which means gifts or blessings.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i take the next meaning of رب from the word منعم the word منعم is used for the one who bestows gifts the one who gives blessings it comes from the root نعم or نعمه which means gifts or blessings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 79, NULL, 'Slavery is no longer part of ordinary life, but the old example still makes the meaning clear. It is one thing to own a slave. It is another thing to care for him, nurture him, train him, put him to proper use, and then, beyond all of that, bestow gifts on him as well.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'slavery is no longer part of ordinary life but the old example still makes the meaning clear it is one thing to own a slave it is another thing to care for him nurture him train him put him to proper use and then beyond all of that bestow gifts on him as well', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 80, NULL, 'The word نعمۃ points to gifts and benefits given beyond what a person deserves. A gift is not something earned. By definition, it is more than what is due. It expresses the love and mercy of the giver. If something is deserved, then it is salary, payment, or earnings. It is not a gift.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the word نعمه points to gifts and benefits given beyond what a person deserves a gift is not something earned by definition it is more than what is due it expresses the love and mercy of the giver if something is deserved then it is salary payment or earnings it is not a gift', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 81, NULL, 'Interestingly, the Arabic word نَعَم, which means yes, also comes from the same root as blessing. The connection is beautiful. The natural human response to receiving blessings is نَعَم: yes, surely. This is what I love about this language. Every word is so perfectly connected to its root.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'interestingly the arabic word نعم which means yes also comes from the same root as blessing the connection is beautiful the natural human response to receiving blessings is نعم yes surely this is what i love about this language every word is so perfectly connected to its root', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 82, NULL, 'I may own a slave, or an animal, such as a goat. If I own a goat, I take care of it. But I do not buy it gifts. I do not buy it jewelry. There is no need. It is a goat. It is part of my property.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i may own a slave or an animal such as a goat if i own a goat i take care of it but i do not buy it gifts i do not buy it jewelry there is no need it is a goat it is part of my property', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 83, NULL, 'In earlier times, slaves were treated no differently from goats or other animals. They were barely cared for, much less given gifts.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'in earlier times slaves were treated no differently from goats or other animals they were barely cared for much less given gifts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 84, NULL, 'Who is Allah? He is مالک and سید. He is our absolute owner, with complete authority over us. That makes us His ملکیۃ: His property.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'who is allah he is مالك and سيد he is our absolute owner with complete authority over us that makes us his ملكيه his property', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 85, NULL, 'But Allah as رب is an owner unlike any other. He takes good care of His property. He has complete authority and control over it. He brings it to full growth. He looks after it, protects it, sustains it, and sets it on the right path. Then, beyond all of that, He gives it many generous gifts it did not deserve.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'but allah as رب is an owner unlike any other he takes good care of his property he has complete authority and control over it he brings it to full growth he looks after it protects it sustains it and sets it on the right path then beyond all of that he gives it many generous gifts it did not deserve', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 86, NULL, 'I have to take this seriously: Allah, as our master, owes us nothing. So whatever He gives us, in any form, is a gift. He is not obligated to give it at all.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i have to take this seriously allah as our master owes us nothing so whatever he gives us in any form is a gift he is not obligated to give it at all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 87, NULL, 'I did nothing to deserve my eyes. I did not pay for my hand. No price can be placed on the eyes, even one eye. No price can be placed on the hands, or on the ability to walk. These gifts are beyond price.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i did nothing to deserve my eyes i did not pay for my hand no price can be placed on the eyes even one eye no price can be placed on the hands or on the ability to walk these gifts are beyond price', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 88, NULL, 'Allah gave us all these precious gifts, yet He says He will question us about them on the Day of Judgment.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'allah gave us all these precious gifts yet he says he will question us about them on the day of judgment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 89, NULL, 'At-Takathur: 8ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ', '', 'ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ', 'At-Takathur: 8', 102, 8, 'surah al fateha linguistic meaning of rabb', 'at takathur 8ثم لتسلن يوميذ عن النعيم', 'ثم لتسلن يوميذ عن النعيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 90, NULL, 'On that Day, we will be asked about the greatest of all gifts: ایمان. The word نعیم is the superlative form of نعم, and it means the greatest gift of all.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'on that day we will be asked about the greatest of all gifts ايمان the word نعيم is the superlative form of نعم and it means the greatest gift of all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 91, NULL, 'What is that gift? It is the gift for which all the other gifts were given to us: ایمان. That is the ultimate gift: ایمان.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'what is that gift it is the gift for which all the other gifts were given to us ايمان that is the ultimate gift ايمان', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 92, NULL, 'On the Day of Judgment, He will ask us about our ایمان, the greatest blessing of all. Without it, what would be the purpose of giving us these gifts and making us different from animals? We were given them so that we could see the creations, reflect on them, recognize Him, and try to draw closer to Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'on the day of judgment he will ask us about our ايمان the greatest blessing of all without it what would be the purpose of giving us these gifts and making us different from animals we were given them so that we could see the creations reflect on them recognize him and try to draw closer to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 93, NULL, 'I now understand that Allah as رب is the One who:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i now understand that allah as رب is the one who', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 94, NULL, 'owns us; holds ultimate authority over us; trains us and nurtures us with love, kindness, and patience until we reach maturity; places us on His chosen path; then showers us with many undeserved gifts.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'owns us holds ultimate authority over us trains us and nurtures us with love kindness and patience until we reach maturity places us on his chosen path then showers us with many undeserved gifts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 96, NULL, 'QAYYIM', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'qayyim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 97, NULL, 'The final meaning of رب comes from قَیِّم: the one who ensures that things hold together and do not fall apart. It means the one whose attention and care remain fixed on what He sustains. Important things collapse when care is withdrawn. The matter is easy to see in ordinary life. People who garden know that some plants are extremely delicate; if they are neglected for even one day, they die. Some people keep fish as pets; if the fish are not fed for a single day, they end up belly-up. That night, there is NEMO KABAAB for dinner. A house left unattended for one day quickly shows what neglect does.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the final meaning of رب comes from قيم the one who ensures that things hold together and do not fall apart it means the one whose attention and care remain fixed on what he sustains important things collapse when care is withdrawn the matter is easy to see in ordinary life people who garden know that some plants are extremely delicate if they are neglected for even one day they die some people keep fish as pets if the fish are not fed for a single day they end up belly up that night there is nemo kabaab for dinner a house left unattended for one day quickly shows what neglect does', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 98, NULL, 'So قَیِّم means the Sustainer, the Maintainer, the One whose focus and attention are constantly upon things. That meaning is also embedded in رب. That is why Allah says in the Quran:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'so قيم means the sustainer the maintainer the one whose focus and attention are constantly upon things that meaning is also embedded in رب that is why allah says in the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 99, NULL, 'Sayingاللَّہُ لَا اِلَٰہَ ھُوَ الْحَیُّ الْقَیُّومُ', '', 'اللَّہُ لَا اِلَٰہَ ھُوَ الْحَیُّ الْقَیُّومُ', 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'sayingالله لا اله هو الحي القيوم', 'الله لا اله هو الحي القيوم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 100, NULL, 'Allah is the only الہ: الحی, the Giver of life, and القیوم, the One who then maintains that life through His constant attention to all things. The word قیوم is the superlative form of قَیِّم: the One who constantly sustains, constantly maintains, and never takes a break.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'allah is the only اله الحي the giver of life and القيوم the one who then maintains that life through his constant attention to all things the word قيوم is the superlative form of قيم the one who constantly sustains constantly maintains and never takes a break', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 101, NULL, 'In other words, I am not alive because I keep myself alive. My next breath does not come because I eat well, exercise, follow a good diet, or live in a healthy place. None of that is the reason I am alive. I am alive because Allah allows me to live. He sustains me; my own efforts do not.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'in other words i am not alive because i keep myself alive my next breath does not come because i eat well exercise follow a good diet or live in a healthy place none of that is the reason i am alive i am alive because allah allows me to live he sustains me my own efforts do not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 102, NULL, 'There are many ways my existence could end in a second: crossing a road, a small earthquake, a snowstorm.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'there are many ways my existence could end in a second crossing a road a small earthquake a snowstorm', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 103, NULL, 'The Indian actress Sri Devi died. She was a perfectly healthy woman, yet she drowned in a bathtub. She likely had plans for the next day, just as I do. She surely had short-term goals and long-term goals. All of them disappeared in a second. I exist because the قَیِّم allows me to exist. I am completely and constantly dependent on Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the indian actress sri devi died she was a perfectly healthy woman yet she drowned in a bathtub she likely had plans for the next day just as i do she surely had short term goals and long term goals all of them disappeared in a second i exist because the قيم allows me to exist i am completely and constantly dependent on allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 104, NULL, 'I see another matter in this ayah: two attributes of Allah are mentioned, الحی and القیوم. He gives life, and He constantly maintains what He gives life to.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i see another matter in this ayah two attributes of allah are mentioned الحي and القيوم he gives life and he constantly maintains what he gives life to', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 105, NULL, 'These two attributes belong together because the One who gives life also knows how to sustain it. He knows how long it should be sustained. He knows the stages and steps through which it must pass. He knows how and when it will end, and what will happen after it ends. The entire plan for every individual creation, not only for human beings but for all creation, has already been fully set by the قیوم.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'these two attributes belong together because the one who gives life also knows how to sustain it he knows how long it should be sustained he knows the stages and steps through which it must pass he knows how and when it will end and what will happen after it ends the entire plan for every individual creation not only for human beings but for all creation has already been fully set by the قيوم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 106, NULL, 'That is part of the meaning of قَیِّم: to have a plan. Nothing can be begun or maintained without a plan. A person who starts a business does not choose the business by playing rock paper scissors. The whole plan must be considered first:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'that is part of the meaning of قيم to have a plan nothing can be begun or maintained without a plan a person who starts a business does not choose the business by playing rock paper scissors the whole plan must be considered first', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 107, NULL, 'the initial investment how the business will stay afloat how it will grow costs and expenses budget allocations', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the initial investment how the business will stay afloat how it will grow costs and expenses budget allocations', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 108, NULL, 'The whole matter is planned before the business even begins. It is impossible that Allah created us without a plan.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the whole matter is planned before the business even begins it is impossible that allah created us without a plan', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 110, NULL, 'I now come to the complete definition of the word Rabb.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i now come to the complete definition of the word rabb', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 111, NULL, 'Sayingالرب ھو المالک والسَّیِّد و المُرَبِّی والمُرشِد وَالمُنعِم والقَیِّم', '', 'الرب ھو المالک والسَّیِّد و المُرَبِّی والمُرشِد وَالمُنعِم والقَیِّم', 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'sayingالرب هو المالك والسيد و المربي والمرشد والمنعم والقيم', 'الرب هو المالك والسيد و المربي والمرشد والمنعم والقيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 112, NULL, 'RAB', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'rab', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 113, NULL, 'رب is the One who is مالک, the One with absolute ownership. At the same time, He is سید, with complete and unconditional authority.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'رب is the one who is مالك the one with absolute ownership at the same time he is سيد with complete and unconditional authority', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 114, NULL, 'At the same time, He is مربی. He causes growth, takes care of us, nurtures us, and protects us with love, care, concern, and mercy.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'at the same time he is مربي he causes growth takes care of us nurtures us and protects us with love care concern and mercy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 115, NULL, 'At the same time, He is مرشد. He brings us to physical and spiritual maturity, then sets us on His straight path and puts us to proper use.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'at the same time he is مرشد he brings us to physical and spiritual maturity then sets us on his straight path and puts us to proper use', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 116, NULL, 'At the same time, He is منعم. He showers us with gifts and blessings that are undeserved and beyond number.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'at the same time he is منعم he showers us with gifts and blessings that are undeserved and beyond number', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 117, NULL, 'At the same time, He is قیم. He sustains us for the full span of our duration.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'at the same time he is قيم he sustains us for the full span of our duration', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 118, NULL, 'Allah, as our رب, gathers all these meanings together, all at once. He is not one of these things at one stage of life and another at a different stage. He is all of them, at the same time. His ownership includes His authority. His authority includes His nurturing. His nurturing includes His guidance and direction. His guidance includes His blessings. His blessings include His sustenance, provision, and maintenance. All of this is present together. SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'allah as our رب gathers all these meanings together all at once he is not one of these things at one stage of life and another at a different stage he is all of them at the same time his ownership includes his authority his authority includes his nurturing his nurturing includes his guidance and direction his guidance includes his blessings his blessings include his sustenance provision and maintenance all of this is present together subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 119, NULL, 'I now tie this understanding of رب to a point already discussed: the man of pure essence, someone from the اُولُو الْاَلْبَابِ, who reflects deeply on the creation of the heavens and the earth, and on the alternation of night and day.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i now tie this understanding of رب to a point already discussed the man of pure essence someone from the اولو الالباب who reflects deeply on the creation of the heavens and the earth and on the alternation of night and day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 120, NULL, 'Sayingإِنَّ فِى خَلْقِ ٱلسَّمَوَتِ وَٱلْأَرْضِ وَٱخْتِلَفِ ٱلَّيْلِ وَٱلنَّهَارِ لَآيَتٍۢ لِّأُو۟لِى ٱلْأَلْبَبِ ‎۱۹۰‏ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَمًۭا وَقُعُودًۭا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَوَتِ وَٱلْأَرْضِ', '', 'إِنَّ فِى خَلْقِ ٱلسَّمَوَتِ وَٱلْأَرْضِ وَٱخْتِلَفِ ٱلَّيْلِ وَٱلنَّهَارِ لَآيَتٍۢ لِّأُو۟لِى ٱلْأَلْبَبِ ‎ ۱۹۰‏ ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَمًۭا وَقُعُودًۭا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَوَتِ وَٱلْأَرْضِ', 'Saying', NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'sayingان في خلق السموت والارض واختلف اليل والنهار لايت لاولي الالبب ۱۹۰ الذين يذكرون الله قيما وقعودا وعلي جنوبهم ويتفكرون في خلق السموت والارض', 'ان في خلق السموت والارض واختلف اليل والنهار لايت لاولي الالبب ۱۹۰ الذين يذكرون الله قيما وقعودا وعلي جنوبهم ويتفكرون في خلق السموت والارض');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 121, NULL, 'I find him saying:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i find him saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 122, NULL, 'Ali ''Imran: 191رَبَّنَا مَا خَلَقْتَ هَذَا بَطِلًۭا سُبْحَنَكَ فَقِنَا عَذَابَ ٱلنَّارِ', '', 'رَبَّنَا مَا خَلَقْتَ هَذَا بَطِلًۭا سُبْحَنَكَ فَقِنَا عَذَابَ ٱلنَّارِ', 'Ali ''Imran: 191', 3, 191, 'surah al fateha linguistic meaning of rabb', 'ali imran 191ربنا ما خلقت هذا بطلا سبحنك فقنا عذاب النار', 'ربنا ما خلقت هذا بطلا سبحنك فقنا عذاب النار');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 123, NULL, 'Once he recognized that the heavens, the earth, and he himself must have a creator, the word he used for that creator was Rabb. His reflection on the creation of the heavens and the earth led him to that name. In what he saw, the creator was the absolute owner, with complete authority. He was nurturing and developing His creation with love, care, and mercy. He was setting everything toward its purpose. He was pouring out countless gifts and blessings upon every created thing. He was sustaining, maintaining, and providing for them continuously through time.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'once he recognized that the heavens the earth and he himself must have a creator the word he used for that creator was rabb his reflection on the creation of the heavens and the earth led him to that name in what he saw the creator was the absolute owner with complete authority he was nurturing and developing his creation with love care and mercy he was setting everything toward its purpose he was pouring out countless gifts and blessings upon every created thing he was sustaining maintaining and providing for them continuously through time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 124, NULL, 'That is why he said:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'that is why he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 125, NULL, 'Ali ''Imran: 191رَبَّنَا مَا خَلَقْتَ هَذَا بَطِلًۭا', '', 'رَبَّنَا مَا خَلَقْتَ هَذَا بَطِلًۭا', 'Ali ''Imran: 191', 3, 191, 'surah al fateha linguistic meaning of rabb', 'ali imran 191ربنا ما خلقت هذا بطلا', 'ربنا ما خلقت هذا بطلا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 126, NULL, 'Our رب, you did not create all of this without a purpose.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'our رب you did not create all of this without a purpose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 127, NULL, 'This was a beautiful and fitting conclusion, because Allah confirmed it in His revelation. The very first ayah revealed to Rasul Allah ﷺ was:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'this was a beautiful and fitting conclusion because allah confirmed it in his revelation the very first ayah revealed to rasul allah ﷺ was', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 128, NULL, 'Al-''Alaq: 1ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ', '', 'ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ', 'Al-''Alaq: 1', 96, 1, 'surah al fateha linguistic meaning of rabb', 'al alaq 1اقرا باسم ربك الذي خلق', 'اقرا باسم ربك الذي خلق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 129, NULL, 'I notice that the first revelation says: Recite with the name of your رب who created you. It does not say ٱقْرَأْ بِٱسْمِ اللہِ ٱلَّذِى خَلَقَ‎. In this verse, Allah introduces himself to his Messenger for the very first time.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i notice that the first revelation says recite with the name of your رب who created you it does not say اقرا باسم الله الذي خلق in this verse allah introduces himself to his messenger for the very first time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 130, NULL, 'When a person introduces himself, he normally gives his name, not one of his qualities. If I met someone for the first time, and I said: السَّلَامُ عَلَیْکُمْ I am a teacher; or السَّلَامُ عَلَیْکُمْ I can do 200 push-ups, the reaction would be: وَعَلَیْکُمُ السَّلَامُ, You''re also a weirdo! That is not how introductions usually work. A person begins with his name.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'when a person introduces himself he normally gives his name not one of his qualities if i met someone for the first time and i said السلام عليكم i am a teacher or السلام عليكم i can do 200 push ups the reaction would be وعليكم السلام youre also a weirdo that is not how introductions usually work a person begins with his name', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 131, NULL, 'For that reason, I would have expected Allah to say ٱقْرَأْ بِٱسْمِ اللہِ ٱلَّذِى خَلَقَ: Read with the name of Allah who created you. Instead, he says: Read in the name of your رب who created you. Allah chose to introduce himself as رب. That choice tells me something important.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'for that reason i would have expected allah to say اقرا باسم الله الذي خلق read with the name of allah who created you instead he says read in the name of your رب who created you allah chose to introduce himself as رب that choice tells me something important', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 132, NULL, 'When I introduce myself as a teacher, I am saying how I want to be known. I am presenting myself through that role. In effect, I am saying that being a teacher matters to me more than my other qualities, even more than my name.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'when i introduce myself as a teacher i am saying how i want to be known i am presenting myself through that role in effect i am saying that being a teacher matters to me more than my other qualities even more than my name', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 133, NULL, 'Allah is glorious beyond comprehension. He is magnificent beyond comprehension. He is powerful beyond comprehension. Yet what He says to Rasul Allah ﷺ, and to us by extension, is that the most important relationship between Him and us is Rabb. That is how He wants me to think of Him: not as جلیل, not as عظیم, not as قوی, not as کبیر, not as متکبر, but as رب.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'allah is glorious beyond comprehension he is magnificent beyond comprehension he is powerful beyond comprehension yet what he says to rasul allah ﷺ and to us by extension is that the most important relationship between him and us is rabb that is how he wants me to think of him not as جليل not as عظيم not as قوي not as كبير not as متكبر but as رب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 134, NULL, 'The weight of that choice needs to settle in the heart. When a king introduces himself, he does not usually choose a humble description. He does not say, “I''m your neighbor!” or “I''m your dad''s friend!” or “I''m your caretaker.” He says, “I AM YOUR KING. KNEEL. BOW DOWN BEFORE ME!”', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'the weight of that choice needs to settle in the heart when a king introduces himself he does not usually choose a humble description he does not say im your neighbor or im your dads friend or im your caretaker he says i am your king kneel bow down before me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 135, NULL, 'If Allah had chosen such a form of introduction in the Quran, it would have suited His majesty. It would have been entirely fitting. Yet the word He chose instead was رب. This shows how important the word is to Him. After the meanings of this word become clear, the loving relationship He wishes to have with His creation also becomes clearer.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'if allah had chosen such a form of introduction in the quran it would have suited his majesty it would have been entirely fitting yet the word he chose instead was رب this shows how important the word is to him after the meanings of this word become clear the loving relationship he wishes to have with his creation also becomes clearer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 136, NULL, 'This matters deeply for the theme of revelation. In the sequence of revelation, the very first verse says:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'this matters deeply for the theme of revelation in the sequence of revelation the very first verse says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 137, NULL, 'Al-''Alaq: 1ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ', '', 'ٱقْرَأْ بِٱسْمِ رَبِّكَ ٱلَّذِى خَلَقَ', 'Al-''Alaq: 1', 96, 1, 'surah al fateha linguistic meaning of rabb', 'al alaq 1اقرا باسم ربك الذي خلق', 'اقرا باسم ربك الذي خلق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 138, NULL, 'But the very last revealed verse says to the messenger ﷺ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'but the very last revealed verse says to the messenger ﷺ', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 139, NULL, 'Al-Ma''idah: 3ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ ٱلْإِسْلَمَ دِينًۭا', '', 'ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ وَأَتْمَمْتُ عَلَيْكُمْ نِعْمَتِى وَرَضِيتُ لَكُمُ ٱلْإِسْلَمَ دِينًۭا', 'Al-Ma''idah: 3', 5, 3, 'surah al fateha linguistic meaning of rabb', 'al maidah 3اليوم اكملت لكم دينكم واتممت عليكم نعمتي ورضيت لكم الاسلم دينا', 'اليوم اكملت لكم دينكم واتممت عليكم نعمتي ورضيت لكم الاسلم دينا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 140, NULL, 'On this day I have perfected your religion for you, and I have completed my blessings on you, and I have selected Islam as the way of life for you.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'on this day i have perfected your religion for you and i have completed my blessings on you and i have selected islam as the way of life for you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 141, NULL, 'Al-Ma''idah: 3فَمَنِ ٱضْطُرَّ فِى مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍۢ لِّإِثْمٍ', '', 'فَمَنِ ٱضْطُرَّ فِى مَخْمَصَةٍ غَيْرَ مُتَجَانِفٍۢ لِّإِثْمٍ', 'Al-Ma''idah: 3', 5, 3, 'surah al fateha linguistic meaning of rabb', 'al maidah 3فمن اضطر في مخمصه غير متجانف لاثم', 'فمن اضطر في مخمصه غير متجانف لاثم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 142, NULL, 'I then come to the final part of the ayah:', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i then come to the final part of the ayah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 143, NULL, 'Al-Baqarah: 192فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', '', 'فَإِنَّ ٱللَّهَ غَفُورٌۭ رَّحِيمٌۭ', 'Al-Baqarah: 192', 2, 192, 'surah al fateha linguistic meaning of rabb', 'al baqarah 192فان الله غفور رحيم', 'فان الله غفور رحيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic meaning of rabb', 'Linguistic Meaning Of Rabb', 144, NULL, 'I have no doubt that Allah is All-Forgiving and All-Merciful. The revelation begins with رب and ends with the name Allah. This exactly matches the pattern of بِسْمِ اللَّہِ الرَّحْمَنِ الرَّحِیمِ. In that statement comes the name Allah, followed by His two attributes of mercy: الرَّحْمَنِ الرَّحِیمِ. The revelation then ends with غَفُورٌۭ رَّحِيمٌۭ: the constantly forgiving and the constantly loving. It begins with His intense and constant love and mercy, and it ends with His constant forgiveness and constant mercy. SubhanAllah!', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic meaning of rabb', 'i have no doubt that allah is all forgiving and all merciful the revelation begins with رب and ends with the name allah this exactly matches the pattern of بسم الله الرحمن الرحيم in that statement comes the name allah followed by his two attributes of mercy الرحمن الرحيم the revelation then ends with غفور رحيم the constantly forgiving and the constantly loving it begins with his intense and constant love and mercy and it ends with his constant forgiveness and constant mercy subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 1, NULL, 'I have examined the linguistic meaning of the word رب. I learned that a رب brings together six attributes:', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i have examined the linguistic meaning of the word رب i learned that a رب brings together six attributes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 2, NULL, 'Sayingالمالک والسَّیِّد و المُرَبِّی والمُرشَد وَالمُنعِم والقَیِّم', '', 'المالک والسَّیِّد و المُرَبِّی والمُرشَد وَالمُنعِم والقَیِّم', 'Saying', NULL, NULL, 'surah al fateha master slave relationship', 'sayingالمالك والسيد و المربي والمرشد والمنعم والقيم', 'المالك والسيد و المربي والمرشد والمنعم والقيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 3, NULL, 'A رب is, first, مالک: the one who possesses absolute ownership. At the same time, He is سید, meaning that He has complete authority over us.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'a رب is first مالك the one who possesses absolute ownership at the same time he is سيد meaning that he has complete authority over us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 4, NULL, 'Within that complete ownership and unrestricted authority, He is also مربی: the one who causes growth. He cares for His creation, nurtures them, and protects them. He is مرشد, which means that He not only nurtures His creation until maturity, but also gives each created thing its purpose. He sets every creation on the path of its destiny and supports it along that path.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'within that complete ownership and unrestricted authority he is also مربي the one who causes growth he cares for his creation nurtures them and protects them he is مرشد which means that he not only nurtures his creation until maturity but also gives each created thing its purpose he sets every creation on the path of its destiny and supports it along that path', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 5, NULL, 'In doing so, He is also منعم: He showers His creation with countless gifts and blessings that they have not earned. Finally, He is قیم: the one who sustains and maintains them for the whole span of their existence.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'in doing so he is also منعم he showers his creation with countless gifts and blessings that they have not earned finally he is قيم the one who sustains and maintains them for the whole span of their existence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 6, NULL, 'All these meanings come together in the word رب. I also learned that the primary ingredient in Allah''s ربوبیۃ is love. All six meanings rest on that one fundamental emotion of رحمۃ: intense, constant love and care.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'all these meanings come together in the word رب i also learned that the primary ingredient in allahs ربوبيه is love all six meanings rest on that one fundamental emotion of رحمه intense constant love and care', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 7, NULL, 'Sayingالرَّحْمَٰنُ عَلَّمَ الْقُرْآنَ', '', 'الرَّحْمَٰنُ عَلَّمَ الْقُرْآنَ', 'Saying', NULL, NULL, 'surah al fateha master slave relationship', 'sayingالرحمن علم القران', 'الرحمن علم القران');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 8, NULL, 'The Loving, the Intensely Merciful, taught the Quran. It is not اَلْجَبَّارُ, عَلَّمَ, or اَلْقُرْآنَ. Thus رحمۃ is the most essential element of Allah''s ربوبیۃ. This is why, when a person of sound essence reflected on the creation of the heavens and the earth, the word he used to call upon his Creator was رب.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'the loving the intensely merciful taught the quran it is not الجبار علم or القران thus رحمه is the most essential element of allahs ربوبيه this is why when a person of sound essence reflected on the creation of the heavens and the earth the word he used to call upon his creator was رب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'master slave relationship', 'Master Slave Relationship', 9, NULL, 'Ali ''Imran: 191رَبَّنَا مَا خَلَقْتَ هَذَا بَطِلًۭا', '', 'رَبَّنَا مَا خَلَقْتَ هَذَا بَطِلًۭا', 'Ali ''Imran: 191', 3, 191, 'surah al fateha master slave relationship', 'ali imran 191ربنا ما خلقت هذا بطلا', 'ربنا ما خلقت هذا بطلا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'master slave relationship', 'Master Slave Relationship', 10, NULL, 'Ali ''Imran: 192رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ', '', 'رَبَّنَآ إِنَّكَ مَن تُدْخِلِ ٱلنَّارَ فَقَدْ أَخْزَيْتَهُۥ', 'Ali ''Imran: 192', 3, 192, 'surah al fateha master slave relationship', 'ali imran 192ربنا انك من تدخل النار فقد اخزيته', 'ربنا انك من تدخل النار فقد اخزيته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'master slave relationship', 'Master Slave Relationship', 11, NULL, 'Ali ''Imran: 193رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًۭا يُنَادِى لِلْإِيمَنِ أَنْ آمِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا', '', 'رَّبَّنَآ إِنَّنَا سَمِعْنَا مُنَادِيًۭا يُنَادِى لِلْإِيمَنِ أَنْ آمِنُوا۟ بِرَبِّكُمْ فَـَٔامَنَّا', 'Ali ''Imran: 193', 3, 193, 'surah al fateha master slave relationship', 'ali imran 193ربنا اننا سمعنا مناديا ينادي للايمن ان امنوا بربكم فامنا', 'ربنا اننا سمعنا مناديا ينادي للايمن ان امنوا بربكم فامنا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 12, NULL, 'He used the word رب because he saw the whole creation reflecting the many attributes of its Creator, ربوبیۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'he used the word رب because he saw the whole creation reflecting the many attributes of its creator ربوبيه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 13, NULL, 'I may meet a highly skilled electrician and watch him at work. From his knowledge and skill alone, I can conclude that he studied at a good electrical engineering school, or that a highly skilled teacher trained him in this work. I have not seen that teacher. I may not even know the name of the school he attended. Yet I can still reach that conclusion by observing his work. The reason is simple: in this respect, the electrician is the product of his teacher. Through his skill and knowledge, he displays the training, discipline, and qualities his teacher gave him.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i may meet a highly skilled electrician and watch him at work from his knowledge and skill alone i can conclude that he studied at a good electrical engineering school or that a highly skilled teacher trained him in this work i have not seen that teacher i may not even know the name of the school he attended yet i can still reach that conclusion by observing his work the reason is simple in this respect the electrician is the product of his teacher through his skill and knowledge he displays the training discipline and qualities his teacher gave him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 14, NULL, 'All creation does the same. It continually displays the ربوبیۃ of its Creator. This principle is true at the smallest level, and it is certainly true at the largest level. The universe, because it is created, continually reflects the attributes of its Creator.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'all creation does the same it continually displays the ربوبيه of its creator this principle is true at the smallest level and it is certainly true at the largest level the universe because it is created continually reflects the attributes of its creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'master slave relationship', 'Master Slave Relationship', 15, NULL, 'Al-Isra: 44تُسَبِّحُ لَهُ ٱلسَّمَوَتُ ٱلسَّبْعُ وَٱلْأَرْضُ وَمَن فِيهِنَّ ۚ وَإِن مِّن شَىْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِۦ وَلَكِن لَّا تَفْقَهُونَ تَسْبِيحَهُمْ', '', 'تُسَبِّحُ لَهُ ٱلسَّمَوَتُ ٱلسَّبْعُ وَٱلْأَرْضُ وَمَن فِيهِنَّ ۚ وَإِن مِّن شَىْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِۦ وَلَكِن لَّا تَفْقَهُونَ تَسْبِيحَهُمْ', 'Al-Isra: 44', 17, 44, 'surah al fateha master slave relationship', 'al isra 44تسبح له السموت السبع والارض ومن فيهن وان من شيء الا يسبح بحمده ولكن لا تفقهون تسبيحهم', 'تسبح له السموت السبع والارض ومن فيهن وان من شيء الا يسبح بحمده ولكن لا تفقهون تسبيحهم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 16, NULL, 'The seven heavens, the earth, and everything within them constantly glorify Him. There is not a single thing that does not sing His praise. But you do not understand their glorification.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'the seven heavens the earth and everything within them constantly glorify him there is not a single thing that does not sing his praise but you do not understand their glorification', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 17, NULL, 'In other words, the signs and آیات of who Allah is have been placed into the very fabric of His design. The more I reflect on creation, the more clearly I can appreciate the beauty of that design.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'in other words the signs and ايات of who allah is have been placed into the very fabric of his design the more i reflect on creation the more clearly i can appreciate the beauty of that design', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 18, NULL, 'I said that رب is commonly translated into English as “Lord.” Linguists, however, agree that the closest single-word replacement for رب is “master.” A master does not only have ownership, authority, and control over something or someone. A master also possesses complete knowledge and skill. Those qualities are essential for nurturing, guidance, and maintenance. For that reason, master comes much closer to the meaning of رب than “lord.”', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i said that رب is commonly translated into english as lord linguists however agree that the closest single word replacement for رب is master a master does not only have ownership authority and control over something or someone a master also possesses complete knowledge and skill those qualities are essential for nurturing guidance and maintenance for that reason master comes much closer to the meaning of رب than lord', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 20, NULL, 'I now understand the meaning of رب, and the next point is that رب implies a relationship. Some words carry a relationship within them. They need a counterpart.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i now understand the meaning of رب and the next point is that رب implies a relationship some words carry a relationship within them they need a counterpart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 21, NULL, 'When I say “teacher,” the word already points to students. I cannot be a teacher if I have no students to teach. When I say “parent,” the word points to children. When I say “employer,” it points to employees. Certain titles require a relationship by their very meaning.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'when i say teacher the word already points to students i cannot be a teacher if i have no students to teach when i say parent the word points to children when i say employer it points to employees certain titles require a relationship by their very meaning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 22, NULL, 'Other words do not work that way. When I say “intelligent,” the word does not necessarily place a person in a direct relationship with anyone else. It is a general attribute. The same is true of “tall.” It describes a quality, not a personal bond.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'other words do not work that way when i say intelligent the word does not necessarily place a person in a direct relationship with anyone else it is a general attribute the same is true of tall it describes a quality not a personal bond', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 23, NULL, 'In the same way, Allah has certain names that do not imply a personal relationship. Allah is الأعلی. He is lofty. This is a powerful attribute, but it describes His state in relation to creation in a general way. It does not, by itself, establish a personal relationship.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'in the same way allah has certain names that do not imply a personal relationship allah is الاعلي he is lofty this is a powerful attribute but it describes his state in relation to creation in a general way it does not by itself establish a personal relationship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 24, NULL, 'Other names of Allah do establish such a relationship. خالق, the Creator, is one example. If He is Creator, then there must be مخلوق, creation. There cannot be a creator without creation. He can be powerful by Himself. He can be الأعلی on His own, but not خالق without creation.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'other names of allah do establish such a relationship خالق the creator is one example if he is creator then there must be مخلوق creation there cannot be a creator without creation he can be powerful by himself he can be الاعلي on his own but not خالق without creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 25, NULL, 'غفور is another example. Allah is extremely forgiving, which means there must be someone to forgive. Some attributes of Allah are general in nature, while others imply a very personal relationship.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'غفور is another example allah is extremely forgiving which means there must be someone to forgive some attributes of allah are general in nature while others imply a very personal relationship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 26, NULL, 'I therefore understand that when Allah begins His revelation with the word رب, and when He says اِقْرَأْ بِسْمِ رَبِّکَ الَّذِی خَلَقَ, He is introducing Himself as رب to Rasul Allah ﷺ, and through him, to us.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i therefore understand that when allah begins his revelation with the word رب and when he says اقرا بسم ربك الذي خلق he is introducing himself as رب to rasul allah ﷺ and through him to us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 27, NULL, 'In doing so, what He is essentially saying is this: “When you think of Me, set all My other attributes aside for a moment, and think of Me first and foremost as your رب. Even if you forget every other relationship I have with you, never let go of this one. At every waking moment of your life, remain mindful that I am your رب. My ربوبیۃ will take precedence in all My dealings and interactions with you, and the primary ingredient of My ربوبیۃ is رحمۃ: love, care, and concern.”', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'in doing so what he is essentially saying is this when you think of me set all my other attributes aside for a moment and think of me first and foremost as your رب even if you forget every other relationship i have with you never let go of this one at every waking moment of your life remain mindful that i am your رب my ربوبيه will take precedence in all my dealings and interactions with you and the primary ingredient of my ربوبيه is رحمه love care and concern', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 28, NULL, 'I find that the statement does not simply say رب. It says ربک, “your” رب. Allah is the master of all creation. He is مالک and سید, the One who has absolute ownership and complete authority over everything. He could have said: اِقْرَأْ بِسْمِ رَبِّ الَّذِی خَلَقَ, “Read in the name of the master who created.”', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i find that the statement does not simply say رب it says ربك your رب allah is the master of all creation he is مالك and سيد the one who has absolute ownership and complete authority over everything he could have said اقرا بسم رب الذي خلق read in the name of the master who created', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 29, NULL, 'But He does not leave it there. He makes it personal: اِقْرَأْ بِسْمِ رَبِّکَ الَّذِی خَلَقَ, “Read in the name of your master who created you.” It is as though He is saying, “I am only your master and nobody else''s.” He makes His relationship that intimate with each one of us. SubhanAllah!', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'but he does not leave it there he makes it personal اقرا بسم ربك الذي خلق read in the name of your master who created you it is as though he is saying i am only your master and nobody elses he makes his relationship that intimate with each one of us subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 30, NULL, 'The relationship of رب requires a counterpart. If Allah is رب, if Allah is master, then I must ask what that makes me. What completes the relationship with a master is a slave. If Allah is master, that makes us all His slaves; and the Arabic word for slave is عبد. So when I accept Allah as my رب, by accepting that relationship itself, I am also accepting the fact that I am His slave.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'the relationship of رب requires a counterpart if allah is رب if allah is master then i must ask what that makes me what completes the relationship with a master is a slave if allah is master that makes us all his slaves and the arabic word for slave is عبد so when i accept allah as my رب by accepting that relationship itself i am also accepting the fact that i am his slave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 31, NULL, 'I can accept this, once I think it through. I have already established that he is مالک: he owns us. I accept that Allah has complete authority over us because he is سید. I know that we live under his training and nurturing because he is مربی. I know that we need his guidance if we are to fulfill our destiny because he is مرشد. I know that we constantly receive countless gifts we never earned because he is منعم. I know, too, that he is our final sustainer and provider. We exist only because he allows us to exist, because he is قیم.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i can accept this once i think it through i have already established that he is مالك he owns us i accept that allah has complete authority over us because he is سيد i know that we live under his training and nurturing because he is مربي i know that we need his guidance if we are to fulfill our destiny because he is مرشد i know that we constantly receive countless gifts we never earned because he is منعم i know too that he is our final sustainer and provider we exist only because he allows us to exist because he is قيم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 32, NULL, 'So it is not impossible, or even strange, to accept that we are slaves of this gracious master. The simple truth is that our acceptance does not change the fact. Whether we accept it or not, we are still his property and his slaves. My children could say to me, “We don''t accept you as our father!” The answer would still be, “Well, tough luck. I am still your father.”', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'so it is not impossible or even strange to accept that we are slaves of this gracious master the simple truth is that our acceptance does not change the fact whether we accept it or not we are still his property and his slaves my children could say to me we dont accept you as our father the answer would still be well tough luck i am still your father', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 33, NULL, 'So I want to make the ground clear: we are slaves of this master whether we like it or not, and whether we want it or not. That is the relationship.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'so i want to make the ground clear we are slaves of this master whether we like it or not and whether we want it or not that is the relationship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 35, NULL, 'Having said that, I want to show how beautiful this relationship with our master is. Until I appreciate the beauty of this relationship with him, I cannot gain the benefits of his ربوبیۃ. This matters because that is how relationships work.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'having said that i want to show how beautiful this relationship with our master is until i appreciate the beauty of this relationship with him i cannot gain the benefits of his ربوبيه this matters because that is how relationships work', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 36, NULL, 'I cannot receive benefit from a teacher until I acknowledge him and accept him as my teacher. I benefit only when I accept that relationship and submit to it.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i cannot receive benefit from a teacher until i acknowledge him and accept him as my teacher i benefit only when i accept that relationship and submit to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 37, NULL, 'I can see the same truth in the relationship between a doctor and a patient. A doctor cannot help a patient until the patient accepts the doctor''s prescribed treatment and submits to it. If a patient has diabetes and the doctor tells him to stop eating candy, yet every time he sees candy, he says, “Oh, I know the doctor asked me not to eat it, but what does he know anyway? It is only a little bit. It is not as if I am eating the whole bag. He is never going to find out anyway. Besides, everyone else is eating candy, so why cannot I have it?” then the patient has not truly accepted the doctor-patient relationship.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i can see the same truth in the relationship between a doctor and a patient a doctor cannot help a patient until the patient accepts the doctors prescribed treatment and submits to it if a patient has diabetes and the doctor tells him to stop eating candy yet every time he sees candy he says oh i know the doctor asked me not to eat it but what does he know anyway it is only a little bit it is not as if i am eating the whole bag he is never going to find out anyway besides everyone else is eating candy so why cannot i have it then the patient has not truly accepted the doctor patient relationship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 38, NULL, 'It does not matter if he calls him Dr. So-and-so. It does not matter how many visits he makes or how many appointments he keeps. He will not benefit, because despite what he says, he has not truly accepted himself as a patient. Only when he fully accepts that relationship and submits to the doctor''s treatment can he receive the benefit the doctor wants him to have.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'it does not matter if he calls him dr so and so it does not matter how many visits he makes or how many appointments he keeps he will not benefit because despite what he says he has not truly accepted himself as a patient only when he fully accepts that relationship and submits to the doctors treatment can he receive the benefit the doctor wants him to have', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 39, NULL, 'The relationship works in both directions. What is striking is that the doctor, despite his vast knowledge and skill, is completely helpless here. The doctor has the knowledge to benefit the patient. The doctor truly cares about the patient. He wants to benefit him. Yet with all his knowledge, will, and desire to help, he cannot do anything, because the patient has not completed the relationship.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'the relationship works in both directions what is striking is that the doctor despite his vast knowledge and skill is completely helpless here the doctor has the knowledge to benefit the patient the doctor truly cares about the patient he wants to benefit him yet with all his knowledge will and desire to help he cannot do anything because the patient has not completed the relationship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 40, NULL, 'I am not really speaking about doctors and patients. I am speaking about myself. I claim that Allah is my رب. I know His infinite رحمۃ. I know that He wants what is best for me. I know the treatment He has prescribed for my soul. I know the duties and the prohibitions.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i am not really speaking about doctors and patients i am speaking about myself i claim that allah is my رب i know his infinite رحمه i know that he wants what is best for me i know the treatment he has prescribed for my soul i know the duties and the prohibitions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 41, NULL, 'I may even pray and fulfill my religious obligations. Yet in daily life, I may still do the very things that go against His prescribed treatment. How, then, can my رب help me and benefit me? This is striking: despite the infinite powers of my رب, I leave the relationship incomplete, and so I fail to receive the benefit He wants for me.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i may even pray and fulfill my religious obligations yet in daily life i may still do the very things that go against his prescribed treatment how then can my رب help me and benefit me this is striking despite the infinite powers of my رب i leave the relationship incomplete and so i fail to receive the benefit he wants for me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 42, NULL, 'If I truly want to gain the benefits my رب offers, I must ask what is required of me.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'if i truly want to gain the benefits my رب offers i must ask what is required of me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 43, NULL, 'I have to complete the relationship. I complete it by submitting myself as His عبد. His relationship with me is that of ربوبیۃ. I complete that relationship through my عبودیۃ and my عبادۃ: my submission, my servitude, and my worship.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i have to complete the relationship i complete it by submitting myself as his عبد his relationship with me is that of ربوبيه i complete that relationship through my عبوديه and my عباده my submission my servitude and my worship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 45, NULL, 'The words عبادۃ and عبودیۃ must be understood clearly. The word عبادۃ is generally translated as worship, and worship is an action. عبودیۃ is the inward state that makes me want to worship. عبادۃ are the different forms of worship. عبودیۃ is the feeling of servitude that drives those acts of worship.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'the words عباده and عبوديه must be understood clearly the word عباده is generally translated as worship and worship is an action عبوديه is the inward state that makes me want to worship عباده are the different forms of worship عبوديه is the feeling of servitude that drives those acts of worship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 46, NULL, 'IBADAH', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'ibadah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 47, NULL, 'What is striking is that, in Arabic, عبادۃ carries two meanings at once. It means عُبُودِیَّۃُ وَ الطَّاعَۃُ: worship and obedience together.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'what is striking is that in arabic عباده carries two meanings at once it means عبوديه و الطاعه worship and obedience together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 48, NULL, 'Worship is usually understood as prayer, fasting, ZAKAT, and similar acts. These are all forms of worship, but I often stop there and treat them as the whole meaning. That is the problem with translating عبادۃ simply as worship. Worship by itself does not necessarily include the idea of obedience.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'worship is usually understood as prayer fasting zakat and similar acts these are all forms of worship but i often stop there and treat them as the whole meaning that is the problem with translating عباده simply as worship worship by itself does not necessarily include the idea of obedience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 49, NULL, 'I understand عبادۃ to include obedience, but not obedience produced by force. It is obedience that rises from love. The word obedience can carry a harsh meaning, because a person may be forced to obey. Children may be bullied into obedience through force or worse. In history, slaves were beaten and tortured into obedience like animals. That is why the word can carry a painful emotional weight.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i understand عباده to include obedience but not obedience produced by force it is obedience that rises from love the word obedience can carry a harsh meaning because a person may be forced to obey children may be bullied into obedience through force or worse in history slaves were beaten and tortured into obedience like animals that is why the word can carry a painful emotional weight', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 50, NULL, 'But that is not the obedience meant here. Forced obedience is not عبادۃ. The Arabic word for that kind of compulsion is رِقَّۃ, which corresponds to غلامی in Urdu. رقۃ means forced obedience; عبودیۃ means willing obedience.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'but that is not the obedience meant here forced obedience is not عباده the arabic word for that kind of compulsion is رقه which corresponds to غلامي in urdu رقه means forced obedience عبوديه means willing obedience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 51, NULL, 'Worship is the outward form of that obedience. The seven forms of worship — وِلَایَۃٌ، طَھَارَۃٌ ، صَلَوَاۃٌ، زَکَوَاۃٌ، حَجٌّ، جِھَادٌ — are all forms in which obedience appears. I perform them because Allah has commanded them. Every act of worship, then, is carried out in obedience to his command.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'worship is the outward form of that obedience the seven forms of worship ولايه طهاره صلواه زكواه حج جهاد are all forms in which obedience appears i perform them because allah has commanded them every act of worship then is carried out in obedience to his command', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 52, NULL, 'When I obey willingly and happily, I am in a state of عبودیۃ, and that is the desired state. If I do the same act with resentment, without being truly pleased to do it, I am in a state of رقۃ, which is not the desired state.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'when i obey willingly and happily i am in a state of عبوديه and that is the desired state if i do the same act with resentment without being truly pleased to do it i am in a state of رقه which is not the desired state', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 53, NULL, 'The outward worship may be the same. I may perform صلواۃ in both cases. But if I pray unwillingly, it is no longer عبادۃ; it is رقۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'the outward worship may be the same i may perform صلواه in both cases but if i pray unwillingly it is no longer عباده it is رقه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 54, NULL, 'I arrive, then, at this: عبادۃ is nothing other than willing obedience to the Beloved, born from passionate and unconditional love. This is why, when اِمَامُ جَعْفَرٍ الصَّادِقِ was asked, یا أمام! ھَلِ الدِّینُ؟ - O Imam, what is the essence of religion? he said, اِلَّا الطَّاعَۃُ - nothing but obedience. Then the man asked: ھَلِ الطَّاعَۃُ؟ What is obedience? He replied الا الحُب - nothing but love. So the essence of every form of worship is willing obedience, and the essence of willing obedience is love.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i arrive then at this عباده is nothing other than willing obedience to the beloved born from passionate and unconditional love this is why when امام جعفر الصادق was asked يا امام هل الدين o imam what is the essence of religion he said الا الطاعه nothing but obedience then the man asked هل الطاعه what is obedience he replied الا الحب nothing but love so the essence of every form of worship is willing obedience and the essence of willing obedience is love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 55, NULL, 'I learned that Allah is ال الہ - He is “The الہ.” He is the One who takes precedence over every form of الہ in my life. But His relationship with me is more direct than that: He is my رب. The word Allah tells me who He is, and what He is meant to signify in my life in the broadest sense. The word رب describes His personal relationship with me. In other words, He is the One to be worshiped because He is اللہ, and He is also the One to be obeyed willingly because He is رب.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i learned that allah is ال اله he is the اله he is the one who takes precedence over every form of اله in my life but his relationship with me is more direct than that he is my رب the word allah tells me who he is and what he is meant to signify in my life in the broadest sense the word رب describes his personal relationship with me in other words he is the one to be worshiped because he is الله and he is also the one to be obeyed willingly because he is رب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 56, NULL, 'I can put this in practical terms. These two names matter because they shape ordinary life between the prayers. Suppose prayer is fifteen minutes away. Suppose فجر begins in fifteen minutes, and the عبادۃ still has to be made. What kind of عبادۃ is صلوۃ? It is worship. But from فجر until ظھر, a person may not be engaged in worship in the narrow sense. Even then, he is still meant to be obeying Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i can put this in practical terms these two names matter because they shape ordinary life between the prayers suppose prayer is fifteen minutes away suppose فجر begins in fifteen minutes and the عباده still has to be made what kind of عباده is صلوه it is worship but from فجر until ظهر a person may not be engaged in worship in the narrow sense even then he is still meant to be obeying him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 57, NULL, 'If I truly recognize Him as الہ, and if I truly accept His relationship with me as رب, then between two prayers I may not always be performing an act of worship, but I must still remain in obedience to Him. This is why the concept of عبادۃ is so comprehensive in Islam. Every form of obedience is counted as عبادۃ in Islam.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'if i truly recognize him as اله and if i truly accept his relationship with me as رب then between two prayers i may not always be performing an act of worship but i must still remain in obedience to him this is why the concept of عباده is so comprehensive in islam every form of obedience is counted as عباده in islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 58, NULL, 'For that reason, when I explain the word عبادۃ, I prefer “obedience” over “worship.” Unconditional, willing obedience is worship.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'for that reason when i explain the word عباده i prefer obedience over worship unconditional willing obedience is worship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 59, NULL, 'A person earns a حلال income at work; that is an act of عبادۃ. A student goes to school and sincerely fulfills the purpose of learning; that is عبادۃ. A person obeys, loves, and respects his parents and teachers; that is عبادۃ. He is kind to his siblings, generous to the needy, and respectful to his elders; that is عبادۃ. He washes his hands before eating, covers his head before going to the toilet, smiles at someone, or makes وضو before sleeping; all of these are acts of عبادۃ when they are done in willing obedience and sincere love for the Beloved.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'a person earns a حلال income at work that is an act of عباده a student goes to school and sincerely fulfills the purpose of learning that is عباده a person obeys loves and respects his parents and teachers that is عباده he is kind to his siblings generous to the needy and respectful to his elders that is عباده he washes his hands before eating covers his head before going to the toilet smiles at someone or makes وضو before sleeping all of these are acts of عباده when they are done in willing obedience and sincere love for the beloved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 60, NULL, 'So the word عبادۃ in Islam is very comprehensive. It is not restricted to the formal acts of worship.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'so the word عباده in islam is very comprehensive it is not restricted to the formal acts of worship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 62, NULL, 'I now turn from عبودیۃ to عبد, which means a slave. Many Muslims feel uneasy with the word slave because it brings a harsh image to mind. That image comes from the way masters have often treated slaves throughout history. I want to use those very examples as a contrast between the kinds of masters the world has known and the kind of master our رب is.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i now turn from عبوديه to عبد which means a slave many muslims feel uneasy with the word slave because it brings a harsh image to mind that image comes from the way masters have often treated slaves throughout history i want to use those very examples as a contrast between the kinds of masters the world has known and the kind of master our رب is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 64, NULL, 'I begin with the word slave. What is the defining mark of a slave? A slave is someone whose free will has been taken away. He has no choice in the decisions his master makes. He must obey the master''s will without question. He has no independent existence except to serve the master''s desires.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i begin with the word slave what is the defining mark of a slave a slave is someone whose free will has been taken away he has no choice in the decisions his master makes he must obey the masters will without question he has no independent existence except to serve the masters desires', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 65, NULL, 'In worldly slavery, the master denies the slave''s freedom and forbids him to choose for himself. That is the deepest humiliation. To take away the freedom of choice from an intelligent human being is to say, “I do not think you are capable of making the right choices.” It is to say, “You are no different from an animal to me. Just as I choose for my cattle and my dog, I will choose for you.” Denying a human being the freedom to choose is the height of humiliation and disgrace.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'in worldly slavery the master denies the slaves freedom and forbids him to choose for himself that is the deepest humiliation to take away the freedom of choice from an intelligent human being is to say i do not think you are capable of making the right choices it is to say you are no different from an animal to me just as i choose for my cattle and my dog i will choose for you denying a human being the freedom to choose is the height of humiliation and disgrace', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 66, NULL, 'When I speak of our Master, I ask what the most precious gift is that He gave us. What is the final gift that sets us apart from every other creation in this world? It is free will.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'when i speak of our master i ask what the most precious gift is that he gave us what is the final gift that sets us apart from every other creation in this world it is free will', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 67, NULL, 'Did He need to give it to us? No. He is مالک. He is my owner. He owns every created thing in this universe. That alone makes every creation His property and His slave. Being His property, or being His slave, therefore has nothing to do with being Muslim or not. Everything belongs to Him. Everything is His slave.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'did he need to give it to us no he is مالك he is my owner he owns every created thing in this universe that alone makes every creation his property and his slave being his property or being his slave therefore has nothing to do with being muslim or not everything belongs to him everything is his slave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 68, NULL, 'The sun is His property. The moon is His property. The galaxies are His property. This whole universe, and everything within it, including me, belongs to Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'the sun is his property the moon is his property the galaxies are his property this whole universe and everything within it including me belongs to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 69, NULL, 'Does the sun have free will? Does the moon have free will? Do night and day have free will? No. They are all in complete submission to the will of their Creator.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'does the sun have free will does the moon have free will do night and day have free will no they are all in complete submission to the will of their creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 70, NULL, 'Sayingوَکُلٌّ فِی فَلَکٍ یَسْبَحُونَ.', '', 'وَکُلٌّ فِی فَلَکٍ یَسْبَحُونَ.', 'Saying', NULL, NULL, 'surah al fateha master slave relationship', 'sayingوكل في فلك يسبحون', 'وكل في فلك يسبحون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 71, NULL, 'They are all floating in their orbits. They have been bound by gravity. They have no choice except to float where they have been placed. Allah bound them and took away their freedom of choice.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'they are all floating in their orbits they have been bound by gravity they have no choice except to float where they have been placed allah bound them and took away their freedom of choice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 72, NULL, 'Could He have done that to us? Could Allah have bound us? Could He have forced us into submission? The One who compelled and enslaved the sun, the moon, the solar systems, and the galaxies could certainly have forced us into submission.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'could he have done that to us could allah have bound us could he have forced us into submission the one who compelled and enslaved the sun the moon the solar systems and the galaxies could certainly have forced us into submission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 73, NULL, 'But did He? No. He gave us intellect and freedom of choice, something He did not give to any other creation. SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'but did he no he gave us intellect and freedom of choice something he did not give to any other creation subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 74, NULL, 'I see from the outset that Allah is truly my master. He is my رب, but His ربوبیۃ is unlike the mastery of any other master I know. Every worldly master first tries to take away freedom of choice. Teachers, parents, employers, courts, doctors: any worldly رب comes with some form of control, some restriction on the will.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i see from the outset that allah is truly my master he is my رب but his ربوبيه is unlike the mastery of any other master i know every worldly master first tries to take away freedom of choice teachers parents employers courts doctors any worldly رب comes with some form of control some restriction on the will', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 75, NULL, 'Allah alone is the رب who has granted complete freedom of choice. If denying freedom of choice is the deepest humiliation, then granting full freedom of choice is the highest honor. SubhanAllah. Allah honored us above every other creation by giving us the freedom to choose.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'allah alone is the رب who has granted complete freedom of choice if denying freedom of choice is the deepest humiliation then granting full freedom of choice is the highest honor subhanallah allah honored us above every other creation by giving us the freedom to choose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 76, NULL, 'Al-Kahf: 29وَقُلِ ٱلْحَقُّ مِن رَّبِّكُمْ ۖ فَمَن شَآءَ فَلْيُؤْمِن وَمَن شَآءَ فَلْيَكْفُرْAnd say: "The truth has been revealed by your master."', '', NULL, 'Al-Kahf: 29', NULL, NULL, 'surah al fateha master slave relationship', 'al kahf 29وقل الحق من ربكم فمن شاء فليومن ومن شاء فليكفرand say the truth has been revealed by your master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 77, NULL, 'Then whosoever wills, let him believe, and whosoever wills, let him disbelieve', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'then whosoever wills let him believe and whosoever wills let him disbelieve', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 79, NULL, 'What gifts do masters give their slaves? Nothing of worth. They barely feed them, barely clothe them, and barely pay them. When they do provide food and clothing, they give only the minimum, just enough to keep them alive. Yet for the little they give, they expect a great deal in return. Every master I know gives the minimum and demands the maximum from his slaves.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'what gifts do masters give their slaves nothing of worth they barely feed them barely clothe them and barely pay them when they do provide food and clothing they give only the minimum just enough to keep them alive yet for the little they give they expect a great deal in return every master i know gives the minimum and demands the maximum from his slaves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 80, NULL, 'I have spoken about what Allah has given us: the many undeserved gifts that the منعم has showered upon his creation. These are precious gifts, far beyond the ordinary logic of exchange. Any company that gave its employees so much would bleed red.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i have spoken about what allah has given us the many undeserved gifts that the منعم has showered upon his creation these are precious gifts far beyond the ordinary logic of exchange any company that gave its employees so much would bleed red', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 81, NULL, 'Measured against the quantity and quality of the gifts our رب has bestowed upon us, what does he ask in return? The bare minimum. The very least. SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'measured against the quantity and quality of the gifts our رب has bestowed upon us what does he ask in return the bare minimum the very least subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 82, NULL, 'Among all created beings, our master has given us the most. The rest of creation remains constantly in عبودیۃ to him. They work around the clock, in constant obedience to Allah, without a moment''s break, in order to serve us.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'among all created beings our master has given us the most the rest of creation remains constantly in عبوديه to him they work around the clock in constant obedience to allah without a moments break in order to serve us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 83, NULL, 'Yet although he has given us the most, he asks the least from us in return:', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'yet although he has given us the most he asks the least from us in return', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 84, NULL, 'one hour of صلواۃ each day; one month of fasting out of twelve, and even that only from sunrise to sunset; 2.5% of our wealth in زکواۃ, from wealth he gave us in the first place.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'one hour of صلواه each day one month of fasting out of twelve and even that only from sunrise to sunset 2 5 of our wealth in زكواه from wealth he gave us in the first place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 85, NULL, 'It is incredible.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'it is incredible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 86, NULL, 'And even then, I find mercy at every turn. If صلواۃ is missed, there is no problem; قضاء is there. If water cannot be found, there is no problem; تیمم is there. If illness or travel makes fasting difficult, the fasts are completed later. If a saved amount has not remained untouched for a full year, there is no problem; زکواۃ is not due. If there is no money for حج, or if the journey is unsafe, there is no problem; the obligation of حج is lifted from one''s shoulders.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'and even then i find mercy at every turn if صلواه is missed there is no problem قضاء is there if water cannot be found there is no problem تيمم is there if illness or travel makes fasting difficult the fasts are completed later if a saved amount has not remained untouched for a full year there is no problem زكواه is not due if there is no money for حج or if the journey is unsafe there is no problem the obligation of حج is lifted from ones shoulders', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 87, NULL, 'This is astonishing. How easy has he made it for us? What kind of master does this? I know of no other master in this world who makes matters so easy for a slave. I know of no other master who gives so much and asks for so little in return. Such a master is unheard of.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'this is astonishing how easy has he made it for us what kind of master does this i know of no other master in this world who makes matters so easy for a slave i know of no other master who gives so much and asks for so little in return such a master is unheard of', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 89, NULL, 'And if that generosity were not enough, he also sent revelation and messengers to explain his reasons to us. Does a master ever explain his reasons to his slaves? Can any slave demand, “Explain the purpose of this command to me”? Can a slave negotiate with his master? Can a slave say, “I will obey only if, and only when, the command is explained to me”? No. Yet this master explained matters to us in the Quran. Our master also showed us, through the living example of Rasul Allah ﷺ, how to carry out our obligations in practice. He did this to make the relationship easier to accept, and to make عبودیۃ easy for us.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'and if that generosity were not enough he also sent revelation and messengers to explain his reasons to us does a master ever explain his reasons to his slaves can any slave demand explain the purpose of this command to me can a slave negotiate with his master can a slave say i will obey only if and only when the command is explained to me no yet this master explained matters to us in the quran our master also showed us through the living example of rasul allah ﷺ how to carry out our obligations in practice he did this to make the relationship easier to accept and to make عبوديه easy for us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'master slave relationship', 'Master Slave Relationship', 90, NULL, 'Al-Baqarah: 185يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ', '', 'يُرِيدُ ٱللَّهُ بِكُمُ ٱلْيُسْرَ وَلَا يُرِيدُ بِكُمُ ٱلْعُسْرَ', 'Al-Baqarah: 185', 2, 185, 'surah al fateha master slave relationship', 'al baqarah 185يريد الله بكم اليسر ولا يريد بكم العسر', 'يريد الله بكم اليسر ولا يريد بكم العسر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 91, NULL, 'Allah desires ease for you. He does not desire hardship for you.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'allah desires ease for you he does not desire hardship for you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 93, NULL, 'I ask another question. Who are the acts of worship meant to benefit: Him or us? In every ordinary master-slave relationship, slavery is arranged for the master''s benefit, not the slave''s.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i ask another question who are the acts of worship meant to benefit him or us in every ordinary master slave relationship slavery is arranged for the masters benefit not the slaves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 94, NULL, 'But this Master designed the universe for us. He gave us the most and asked the least in return. He even explained the reasons behind His commands. So the question becomes: everything He has asked us to do, whom does it benefit? It benefits us, and only us. SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'but this master designed the universe for us he gave us the most and asked the least in return he even explained the reasons behind his commands so the question becomes everything he has asked us to do whom does it benefit it benefits us and only us subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 95, NULL, 'Every slave in the world is bought and put to work for the master''s gain. Every command given to a slave serves the master''s interest. What kind of Master is this, whose every command is for the benefit of His slaves? Not a single command is for His own benefit. If that is not love, if that is not care, if that is not mercy, if that is not ease, if that is not رحمۃ, then what is it? AllahuAkbar.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'every slave in the world is bought and put to work for the masters gain every command given to a slave serves the masters interest what kind of master is this whose every command is for the benefit of his slaves not a single command is for his own benefit if that is not love if that is not care if that is not mercy if that is not ease if that is not رحمه then what is it allahuakbar', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 96, NULL, 'He is constantly serving us. And what He asks from us in return is also only for our benefit, not His.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'he is constantly serving us and what he asks from us in return is also only for our benefit not his', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 98, NULL, 'I ask another question. Is a slave''s work judged according to the slave''s abilities, or according to the master''s expectations? In ordinary slavery, a slave''s work is judged by the master''s standards and demands.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i ask another question is a slaves work judged according to the slaves abilities or according to the masters expectations in ordinary slavery a slaves work is judged by the masters standards and demands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 99, NULL, 'How does Allah judge our actions? He judges them according to each person''s knowledge and ability. Nowhere in the Quran does Allah demand perfection. The only thing He asks for in the Quran is effort.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'how does allah judge our actions he judges them according to each persons knowledge and ability nowhere in the quran does allah demand perfection the only thing he asks for in the quran is effort', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 101, NULL, 'I know of no master in this world who rushes to meet the needs of his slaves. I have never seen even a story in which a slave cries out to his master in need, and the master drops everything and hurries to help him. Yet what does our RAB do?', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i know of no master in this world who rushes to meet the needs of his slaves i have never seen even a story in which a slave cries out to his master in need and the master drops everything and hurries to help him yet what does our rab do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 102, NULL, 'Al-Baqarah: 186وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِAnd when My slaves ask you concerning Me, Indeed I near him in that very moment. I immediately respond to the invocations of the supplicant when he calls upon Me.', '', NULL, 'Al-Baqarah: 186', NULL, NULL, 'surah al fateha master slave relationship', 'al baqarah 186واذا سالك عبادي عني فاني قريب اجيب دعوه الداع اذا دعانand when my slaves ask you concerning me indeed i near him in that very moment i immediately respond to the invocations of the supplicant when he calls upon me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 103, NULL, 'No master ever does that. History shows the ordinary pattern: slaves are hurried forward to meet the needs of their masters, never the other way around. What kind of merciful master, then, is this, who hastens to fulfill the needs of His slaves?', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'no master ever does that history shows the ordinary pattern slaves are hurried forward to meet the needs of their masters never the other way around what kind of merciful master then is this who hastens to fulfill the needs of his slaves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 104, NULL, 'I reflect more deeply on the ربوبیۃ of this master, and I see more clearly how astonishing his رحمۃ and mercy are. He is intensely loving, deeply caring, and overwhelmingly merciful. He is unlike any master I know, and unlike any master I will ever come to know in this world. No master does for his slave what our رب does for us.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i reflect more deeply on the ربوبيه of this master and i see more clearly how astonishing his رحمه and mercy are he is intensely loving deeply caring and overwhelmingly merciful he is unlike any master i know and unlike any master i will ever come to know in this world no master does for his slave what our رب does for us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 105, NULL, 'Yet his subtle love and mercy can make me forget my place before him. I forget that I am his property. I forget that he is مالک. He is the owner. If he is the owner, then by definition I am owned property. He can do whatever he wills with me. He can break me, tear me apart, burn me, drown me. Nothing prevents him from doing any of it. And if he chooses to do so, nothing remains in my power, or in the power of all of us together, or in the power of everything in the universe combined, to protect me from his wrath.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'yet his subtle love and mercy can make me forget my place before him i forget that i am his property i forget that he is مالك he is the owner if he is the owner then by definition i am owned property he can do whatever he wills with me he can break me tear me apart burn me drown me nothing prevents him from doing any of it and if he chooses to do so nothing remains in my power or in the power of all of us together or in the power of everything in the universe combined to protect me from his wrath', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'master slave relationship', 'Master Slave Relationship', 106, NULL, 'Sayingإِن يُرِدْنِ ٱلرَّحْمَنُ بِضُرٍّۢ . لَّا تُغْنِ عَنِّى شَفَعَتُهُمْ شَيْـًۭٔا وَلَا يُنقِذُونِ', '', 'إِن يُرِدْنِ ٱلرَّحْمَنُ بِضُرٍّۢ . لَّا تُغْنِ عَنِّى شَفَعَتُهُمْ شَيْـًۭٔا وَلَا يُنقِذُونِ', 'Saying', 36, 23, 'surah al fateha master slave relationship', 'sayingان يردن الرحمن بضر لا تغن عني شفعتهم شيا ولا ينقذون', 'ان يردن الرحمن بضر لا تغن عني شفعتهم شيا ولا ينقذون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 107, NULL, 'If the Rehman decides to harm me, absolutely nothing in existence will be able to help me. That truth stands plainly.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'if the rehman decides to harm me absolutely nothing in existence will be able to help me that truth stands plainly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'master slave relationship', 'Master Slave Relationship', 108, NULL, 'Ya-Sin: 23إِن يُرِدْنِ ٱلرَّحْمَنُ بِضُرٍّۢ', '', 'إِن يُرِدْنِ ٱلرَّحْمَنُ بِضُرٍّۢ', 'Ya-Sin: 23', 36, 23, 'surah al fateha master slave relationship', 'ya sin 23ان يردن الرحمن بضر', 'ان يردن الرحمن بضر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 109, NULL, 'If the REHMAN decides to harm me. SubhanAllah. Not', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'if the rehman decides to harm me subhanallah not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 110, NULL, 'Sayingإِن يُرِدْنِ الجبار. إِن يُرِدْنِ القھار. إِن يُرِدْنِ ذوالنتقام', '', 'إِن يُرِدْنِ الجبار. إِن يُرِدْنِ القھار. إِن يُرِدْنِ ذوالنتقام', 'Saying', NULL, NULL, 'surah al fateha master slave relationship', 'sayingان يردن الجبار ان يردن القهار ان يردن ذوالنتقام', 'ان يردن الجبار ان يردن القهار ان يردن ذوالنتقام');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 111, NULL, 'not the conqueror, not the powerful, not the avenger. If the Rehman decides to harm me: no, no, no.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'not the conqueror not the powerful not the avenger if the rehman decides to harm me no no no', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'master slave relationship', 'Master Slave Relationship', 112, NULL, 'Ya-Sin: 23إِن يُرِدْنِ ٱلرَّحْمَنُ', '', 'إِن يُرِدْنِ ٱلرَّحْمَنُ', 'Ya-Sin: 23', 36, 23, 'surah al fateha master slave relationship', 'ya sin 23ان يردن الرحمن', 'ان يردن الرحمن');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 113, NULL, 'If the REHMAN decides to harm me, then even in His ضُر, even in His harm, He is merciful. Hidden within it is a benefit. SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'if the rehman decides to harm me then even in his ضر even in his harm he is merciful hidden within it is a benefit subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 114, NULL, 'And yet I constantly disobey Allah. I constantly fall short in my عبودیۃ, in my obedience and servitude to Him. Still, He allows me to exist.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'and yet i constantly disobey allah i constantly fall short in my عبوديه in my obedience and servitude to him still he allows me to exist', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 115, NULL, 'My phone was causing problems. It was acting up and freezing on me. Every now and then I had to restart it. I went to the store and bought a new phone. I got rid of the old one. Why? Because it acted up on me occasionally, not all the time, only a few times. So I replaced it.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'my phone was causing problems it was acting up and freezing on me every now and then i had to restart it i went to the store and bought a new phone i got rid of the old one why because it acted up on me occasionally not all the time only a few times so i replaced it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 116, NULL, 'That is what is done with property when it no longer does its job. It is discarded. I belong to Allah. We all belong to Allah. And we are not doing our jobs, not merely occasionally, not merely sometimes, but in some cases constantly, all the time. What, then, should my Owner do with me? What should my Owner do with property as useless as myself? Discard it. But does He do that? AllahuAkbar.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'that is what is done with property when it no longer does its job it is discarded i belong to allah we all belong to allah and we are not doing our jobs not merely occasionally not merely sometimes but in some cases constantly all the time what then should my owner do with me what should my owner do with property as useless as myself discard it but does he do that allahuakbar', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 117, NULL, 'So even when words such as رب and عبد (master and slave) are used, He is unlike any master imaginable in this world. This Master loves us intensely and constantly. When I realize that, my natural response is to love Him back. That is another unique relationship between a master and a slave.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'so even when words such as رب and عبد master and slave are used he is unlike any master imaginable in this world this master loves us intensely and constantly when i realize that my natural response is to love him back that is another unique relationship between a master and a slave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 119, NULL, 'I know no master in this world whom a slave naturally loves. History shows the opposite: slaves have hated their masters, and at the first chance they have wanted to run away from them.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i know no master in this world whom a slave naturally loves history shows the opposite slaves have hated their masters and at the first chance they have wanted to run away from them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 120, NULL, 'But I wholeheartedly love my Master. The only direction I want to run is toward Him, not away from Him. I do that by submitting myself to His love and mercy, through willing obedience. This is not the forced obedience known in the world. It is obedience freely given.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'but i wholeheartedly love my master the only direction i want to run is toward him not away from him i do that by submitting myself to his love and mercy through willing obedience this is not the forced obedience known in the world it is obedience freely given', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 121, NULL, 'This obedience rises from the highest stages of love already described. It appears as a desire for service and servitude, like the service of a passionate lover, an عاشق, for his معشوق - for his beloved. That is عبودیۃ. That is worship. In that lies my greatest challenge.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'this obedience rises from the highest stages of love already described it appears as a desire for service and servitude like the service of a passionate lover an عاشق for his معشوق for his beloved that is عبوديه that is worship in that lies my greatest challenge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 122, NULL, 'I face the greatest challenge, the greatest difficulty, and the hardest trial of every waking moment when I accept Allah as رب. This is the constant challenge I face, and every person in the world faces. It is not the acceptance of the Creator as Allah. That part does not trouble people. Even the جَاھِلِی عَرَبٍ accepted Him as Allah. The real problem, and the real test, is accepting Him as رب: as Master.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i face the greatest challenge the greatest difficulty and the hardest trial of every waking moment when i accept allah as رب this is the constant challenge i face and every person in the world faces it is not the acceptance of the creator as allah that part does not trouble people even the جاهلي عرب accepted him as allah the real problem and the real test is accepting him as رب as master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 123, NULL, 'That acceptance carries its own demand. If I accept Him as رب, then I must become a slave. I must accept the relationship He has placed upon me. I must give up the false freedom of my passions and desires and wear the collar of His عبودیۃ, becoming His slave. That is where the struggle lies.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'that acceptance carries its own demand if i accept him as رب then i must become a slave i must accept the relationship he has placed upon me i must give up the false freedom of my passions and desires and wear the collar of his عبوديه becoming his slave that is where the struggle lies', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 124, NULL, 'I live in an age of absolute and unrestricted self-indulgence. The spirit of the age says: I am in charge. I am in control. I am the master of my own destiny. I am powerful. I am wealthy. I do not have to listen to anyone. No one is the boss of me. I can do whatever I want, whenever I want. I am the king of my domain. This is my life. If I want to do it, I will do it. If I do not want to do it, I will not.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i live in an age of absolute and unrestricted self indulgence the spirit of the age says i am in charge i am in control i am the master of my own destiny i am powerful i am wealthy i do not have to listen to anyone no one is the boss of me i can do whatever i want whenever i want i am the king of my domain this is my life if i want to do it i will do it if i do not want to do it i will not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 125, NULL, 'In other words, I make myself my own رب. I make myself my own master.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'in other words i make myself my own رب i make myself my own master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 126, NULL, 'And I hear Allah saying: “No! I am your master. I gave you this life. I gave you this authority. I gave you the gift of parents. I gave you the gift of children. I honored you with intellect and free will. I gave you rank and power. I gave you health and strength. I gave you all these things so you would recognize Me and draw nearer to Me, because I am your master, and I am a master unlike any other master you will ever know. Submit to Me, and I will show you what true happiness is.”', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'and i hear allah saying no i am your master i gave you this life i gave you this authority i gave you the gift of parents i gave you the gift of children i honored you with intellect and free will i gave you rank and power i gave you health and strength i gave you all these things so you would recognize me and draw nearer to me because i am your master and i am a master unlike any other master you will ever know submit to me and i will show you what true happiness is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 127, NULL, 'My greatest challenge in this life is to accept my عبودیۃ willingly and gladly, and to submit to my master with sincere obedience and true worship. I can overcome that challenge only by recognizing and appreciating the love and mercy of my master. The relationship of ربوبیۃ becomes complete only when I submit willingly and obey this magnificent master, because love gives birth to love.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'my greatest challenge in this life is to accept my عبوديه willingly and gladly and to submit to my master with sincere obedience and true worship i can overcome that challenge only by recognizing and appreciating the love and mercy of my master the relationship of ربوبيه becomes complete only when i submit willingly and obey this magnificent master because love gives birth to love', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 128, NULL, 'If this incredible رب does so much for disobedient and ungrateful slaves, what would He do for me if I truly became willingly obedient to Him?', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'if this incredible رب does so much for disobedient and ungrateful slaves what would he do for me if i truly became willingly obedient to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 129, NULL, 'Ibrahim: 7وَإِذْ تَأَذَّنَ رَبُّكُمْ لَىِٕن شَكَرْتُمْ لَأَزِيدَنَّكُمْ ۖ وَلَىِٕن كَفَرْتُمْ إِنَّ عَذَابِى لَشَدِيدٌۭAnd when your master said: “If you become grateful, I will give you more, but if you are ungrateful, then indeed my punishment is severe.”', '', NULL, 'Ibrahim: 7', NULL, NULL, 'surah al fateha master slave relationship', 'ibrahim 7واذ تاذن ربكم لين شكرتم لازيدنكم ولين كفرتم ان عذابي لشديدand when your master said if you become grateful i will give you more but if you are ungrateful then indeed my punishment is severe', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 131, NULL, 'What is freedom? حریۃ. In Arabic, freedom is very different from the way modern English usually defines it. In pre-Islamic Arab culture, the حر stood in contrast to the slave. A free person was someone who was not a عبد. Such a person possessed both حر and عبد.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'what is freedom حريه in arabic freedom is very different from the way modern english usually defines it in pre islamic arab culture the حر stood in contrast to the slave a free person was someone who was not a عبد such a person possessed both حر and عبد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 132, NULL, 'One of the remarkable things about Islam is that it makes a person عبد اللہ. If I am عبد اللہ, the slave of Allah, then what is my relationship to everything else? I become free. My عبدیۃ, my obedience and servitude, belongs only to Allah. It does not belong to anything or anyone else. That is what sets me completely free. So the حر, the Arabs say:', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'one of the remarkable things about islam is that it makes a person عبد الله if i am عبد الله the slave of allah then what is my relationship to everything else i become free my عبديه my obedience and servitude belongs only to allah it does not belong to anything or anyone else that is what sets me completely free so the حر the arabs say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 133, NULL, 'Sayingالحُرُّ عَبْدٌ مَا طَمَع', '', 'الحُرُّ عَبْدٌ مَا طَمَع', 'Saying', NULL, NULL, 'surah al fateha master slave relationship', 'sayingالحر عبد ما طمع', 'الحر عبد ما طمع');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 134, NULL, 'The free man remains a slave as long as he is covetous, as long as he is greedy, and as long as he still wants.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'the free man remains a slave as long as he is covetous as long as he is greedy and as long as he still wants', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 135, NULL, 'Sayingوالعَبْدُ حُرُّ مَا طَمَع', '', 'والعَبْدُ حُرُّ مَا طَمَع', 'Saying', NULL, NULL, 'surah al fateha master slave relationship', 'sayingوالعبد حر ما طمع', 'والعبد حر ما طمع');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 136, NULL, 'And the slave is a free man if he is content.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'and the slave is a free man if he is content', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 137, NULL, 'This reaches the essence of the Arab understanding of freedom before Islam. Real freedom was moral freedom. It was freedom from want, not freedom to do whatever I wished. In my culture, freedom has been defined almost entirely as freedom “to”: freedom to do whatever I want, freedom to say whatever I want, freedom to have whatever I want. For the Arabs, it was freedom “from”: freedom from desires, freedom from wants, and freedom from needs. That is how they understood freedom.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'this reaches the essence of the arab understanding of freedom before islam real freedom was moral freedom it was freedom from want not freedom to do whatever i wished in my culture freedom has been defined almost entirely as freedom to freedom to do whatever i want freedom to say whatever i want freedom to have whatever i want for the arabs it was freedom from freedom from desires freedom from wants and freedom from needs that is how they understood freedom', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 138, NULL, 'I understand Islamic freedom through this powerful pattern: I enslave myself to the One and become free from everything else, or I turn away from the One and become a slave to everything. Even enslavement to Allah is, in essence, the acceptance of His ربوبیۃ, because I am already a slave. I am His property whether I accept that truth or deny it. Freedom, then, begins when I recognize that relationship, draw nearer to Him, and through that nearness reach complete freedom and happiness.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'i understand islamic freedom through this powerful pattern i enslave myself to the one and become free from everything else or i turn away from the one and become a slave to everything even enslavement to allah is in essence the acceptance of his ربوبيه because i am already a slave i am his property whether i accept that truth or deny it freedom then begins when i recognize that relationship draw nearer to him and through that nearness reach complete freedom and happiness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 140, NULL, 'The question of suffering depends on perspective. Did they truly suffer? The signs of suffering are fear, regret, depression, and excuses to escape.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'the question of suffering depends on perspective did they truly suffer the signs of suffering are fear regret depression and excuses to escape', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 141, NULL, 'The black slave John gives the example. He could have played the racist card, but he did not.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'the black slave john gives the example he could have played the racist card but he did not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 142, NULL, 'Karbala was the clearest example of عبودیۃ. It was a battle to defend the honor of the beloved. Yazeed had challenged the ربوبیۃ and الہیۃ of Imam Hussain''s beloved, and Imam Hussain and his companions stood firm to defend that honor. They also set an example of true love for me. They showed that this is how love acts: it pays any price for the beloved. It sacrifices food, drink, children, family, and life itself, but it never deserts the beloved. Love that flees at the first sign of trouble is no love at all. For the true lover, what good is life without the beloved''s grace?', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'karbala was the clearest example of عبوديه it was a battle to defend the honor of the beloved yazeed had challenged the ربوبيه and الهيه of imam hussains beloved and imam hussain and his companions stood firm to defend that honor they also set an example of true love for me they showed that this is how love acts it pays any price for the beloved it sacrifices food drink children family and life itself but it never deserts the beloved love that flees at the first sign of trouble is no love at all for the true lover what good is life without the beloveds grace', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 143, NULL, 'Sayingفَلَيـتَكَ تَحلُو وَالحَيـاةُ مَـرِيرَةٌ . وَلَيـتَكَ تَرضـى وَالأنـامُ غِضَـابُ', '', 'فَلَيـتَكَ تَحلُو وَالحَيـاةُ مَـرِيرَةٌ . وَلَيـتَكَ تَرضـى وَالأنـامُ غِضَـابُ', 'Saying', NULL, NULL, 'surah al fateha master slave relationship', 'sayingفليتك تحلو والحياه مريره وليتك ترضي والانام غضاب', 'فليتك تحلو والحياه مريره وليتك ترضي والانام غضاب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 144, NULL, 'Sayingوَلَيـتَ الَّذِي بَيـنِي وَ بَينَـكَ عَامِرٌ . وَبَـينِي وَبَيـنَ العــالَمِينَ خَـرَابُ', '', 'وَلَيـتَ الَّذِي بَيـنِي وَ بَينَـكَ عَامِرٌ . وَبَـينِي وَبَيـنَ العــالَمِينَ خَـرَابُ', 'Saying', NULL, NULL, 'surah al fateha master slave relationship', 'sayingوليت الذي بيني و بينك عامر وبيني وبين العالمين خراب', 'وليت الذي بيني و بينك عامر وبيني وبين العالمين خراب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 145, NULL, 'Sayingفَيالَيـتَ شُـربِي مِن وِدَادِكَ صَافِياً . وَشُـربِي مِن مَـاء الفُراتِ سَـرَابُ', '', 'فَيالَيـتَ شُـربِي مِن وِدَادِكَ صَافِياً . وَشُـربِي مِن مَـاء الفُراتِ سَـرَابُ', 'Saying', NULL, NULL, 'surah al fateha master slave relationship', 'sayingفياليت شربي من ودادك صافيا وشربي من ماء الفرات سراب', 'فياليت شربي من ودادك صافيا وشربي من ماء الفرات سراب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 146, NULL, 'Sayingإذا نِلتُ مِنكَ الوُدَّ فَالكُلُّ هَيِّـنٌ . وَكُـلَّ الَّذي فَوقَ الـتُّرابِ تُـرابُ', '', 'إذا نِلتُ مِنكَ الوُدَّ فَالكُلُّ هَيِّـنٌ . وَكُـلَّ الَّذي فَوقَ الـتُّرابِ تُـرابُ', 'Saying', NULL, NULL, 'surah al fateha master slave relationship', 'sayingاذا نلت منك الود فالكل هين وكل الذي فوق التراب تراب', 'اذا نلت منك الود فالكل هين وكل الذي فوق التراب تراب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 147, NULL, 'If I can only taste the sweetness of Your pleasure, it does not matter if life itself turns bitter for me.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'if i can only taste the sweetness of your pleasure it does not matter if life itself turns bitter for me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 148, NULL, 'If You are pleased with me, what do I care for the anger and wrath of the whole world?', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'if you are pleased with me what do i care for the anger and wrath of the whole world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 149, NULL, 'May what lies between us remain beautiful, even if everything between me and the world turns ugly.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'may what lies between us remain beautiful even if everything between me and the world turns ugly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 150, NULL, 'One sip from the wine of Your pure love makes the sweet water of the Euphrates seem like a mirage to me.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'one sip from the wine of your pure love makes the sweet water of the euphrates seem like a mirage to me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'master slave relationship', 'Master Slave Relationship', 151, NULL, 'All I need is Your love. If I have that, I have everything. Without it, even the greatest treasure is dust to me.', '', NULL, NULL, NULL, NULL, 'surah al fateha master slave relationship', 'all i need is your love if i have that i have everything without it even the greatest treasure is dust to me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 0, NULL, 'I begin with REHMA.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i begin with rehma', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 1, NULL, 'The classical definition of رب is:', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the classical definition of رب is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 2, NULL, 'Sayingالرَبُّ ھُوَ المَالِکُ وَ السَّیِّد وَ المُرَبِّی وَ المُرْشَدُ وَ المُنعِمُ وَ القَیِّمُ', '', 'الرَبُّ ھُوَ المَالِکُ وَ السَّیِّد وَ المُرَبِّی وَ المُرْشَدُ وَ المُنعِمُ وَ القَیِّمُ', 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingالرب هو المالك و السيد و المربي و المرشد و المنعم و القيم', 'الرب هو المالك و السيد و المربي و المرشد و المنعم و القيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 3, NULL, 'A رب joins six meanings in one. He has complete ownership and absolute authority. He nurtures, guides, and assigns each thing its purpose. He pours out undeserved gifts and blessings. He also sustains, maintains, and provides.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'a رب joins six meanings in one he has complete ownership and absolute authority he nurtures guides and assigns each thing its purpose he pours out undeserved gifts and blessings he also sustains maintains and provides', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 4, NULL, 'After learning what رب means, I must ask what he is رب of. In سُورَۃُ الْفَاتِحَۃِ, he tells us:', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'after learning what رب means i must ask what he is رب of in سوره الفاتحه he tells us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 5, NULL, 'Al-Fatihah: 2ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ', '', 'ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ', 'Al-Fatihah: 2', 1, 2, 'surah al fateha understanding rab al alameen', 'al fatihah 2الحمد لله رب العلمين', 'الحمد لله رب العلمين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 6, NULL, 'I give all praise and gratitude to Allah, who is رَبِّ ٱلْعَلَمِينَ. I begin with the word ٱلْعَلَمِينَ, and then I turn to what رَبِّ ٱلْعَلَمِينَ means in practice.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i give all praise and gratitude to allah who is رب العلمين i begin with the word العلمين and then i turn to what رب العلمين means in practice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 8, NULL, 'Most English translations render الْعَالَمِینَ as “worlds.” They give the meaning as: all praise and gratitude belong to Allah, the master of the worlds, or the master of the universe. That English word gives only a weak and incomplete sense of the Arabic.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'most english translations render العالمين as worlds they give the meaning as all praise and gratitude belong to allah the master of the worlds or the master of the universe that english word gives only a weak and incomplete sense of the arabic', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 9, NULL, 'The word الْعَالَمِینَ is the plural of العالَم. To understand it, I first look at its counterpart, عالِم.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the word العالمين is the plural of العالم to understand it i first look at its counterpart عالم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 10, NULL, 'ALAM', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'alam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 11, NULL, 'The two words عالَم and عالِم have exactly the same spelling. The only difference between عالَم and عالِم is the فتحۃ and the کسرۃ. Apart from that, the spelling is identical.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the two words عالم and عالم have exactly the same spelling the only difference between عالم and عالم is the فتحه and the كسره apart from that the spelling is identical', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 12, NULL, 'In Arabic, when two words share a spelling, they also share a deep connection in meaning. Here, they also share the same root: علم. The word علم means knowledge. So عالِم is the one who knows, and عالَم is what becomes known to him.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'in arabic when two words share a spelling they also share a deep connection in meaning here they also share the same root علم the word علم means knowledge so عالم is the one who knows and عالم is what becomes known to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 13, NULL, 'The distinction is clear:', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the distinction is clear', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 14, NULL, 'عالِم is the one who knows; he is the cause. عالَم is what can be known; it is the effect.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'عالم is the one who knows he is the cause عالم is what can be known it is the effect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 15, NULL, 'The device through which عالِم comes to know عالَم is the intellect, which in Arabic is العقل.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the device through which عالم comes to know عالم is the intellect which in arabic is العقل', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 16, NULL, 'I, as a human being, can know many things. Yet all the knowledge I gain over a lifetime, and all the knowledge human beings gather over centuries, still does not reach everything. I know some things, and I remain ignorant of others. Allah is unlike this. He knows everything that can be known. The word for the One who knows everything about all that exists to be known is علیم.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i as a human being can know many things yet all the knowledge i gain over a lifetime and all the knowledge human beings gather over centuries still does not reach everything i know some things and i remain ignorant of others allah is unlike this he knows everything that can be known the word for the one who knows everything about all that exists to be known is عليم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 17, NULL, 'ALEEM', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'aleem', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 18, NULL, 'It is the superlative form of عالِم. An عالِم is one who has knowledge, even if only some knowledge. But علیم is the One whose knowledge is absolute and complete, embracing everything.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'it is the superlative form of عالم an عالم is one who has knowledge even if only some knowledge but عليم is the one whose knowledge is absolute and complete embracing everything', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 19, NULL, 'So three words now stand from the same root, علم:', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'so three words now stand from the same root علم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 20, NULL, 'عالَم: that which can be known; that which waits to be known, discovered, researched, and understood. عالِم: the one who studies, researches, discovers, and through that process learns about the عالَم. علیم: the One who knows everything there is to know.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'عالم that which can be known that which waits to be known discovered researched and understood عالم the one who studies researches discovers and through that process learns about the عالم عليم the one who knows everything there is to know', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 21, NULL, 'Because I am limited in my ability to learn and understand, the علیم created the عالَم. It is there for study, reflection, and knowledge. Through it, awareness grows, and recognition becomes possible. Recognition of whom? The علیم.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'because i am limited in my ability to learn and understand the عليم created the عالم it is there for study reflection and knowledge through it awareness grows and recognition becomes possible recognition of whom the عليم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 22, NULL, 'COMBO', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'combo', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 23, NULL, 'Allah is infinite. Infinite means without limit. اِمَامُ جَعْفَرٍ الصَّادِقِ عَلَیْہِ السَّلَامُ explained Allah as:', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'allah is infinite infinite means without limit امام جعفر الصادق عليه السلام explained allah as', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 24, NULL, 'Sayingاَللّٰہُ اَکْبَرُ مِنْ اَنْ یُحَدَّ وَ یُحْسَرَ', '', 'اَللّٰہُ اَکْبَرُ مِنْ اَنْ یُحَدَّ وَ یُحْسَرَ', 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingالله اكبر من ان يحد و يحسر', 'الله اكبر من ان يحد و يحسر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 25, NULL, 'I understand Allah''s greatness in this sense: Allah has no boundary, and Allah cannot be confined within human comprehension. In other words, Allah cannot be “defined.”', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i understand allahs greatness in this sense allah has no boundary and allah cannot be confined within human comprehension in other words allah cannot be defined', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 26, NULL, 'Yet my human understanding works through definition. A definition gives finiteness to something. It limits a reality for me so that I can place it within a frame and understand it. This is what the intellect, or عقل, does. It sets a boundary. It confines. It defines.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'yet my human understanding works through definition a definition gives finiteness to something it limits a reality for me so that i can place it within a frame and understand it this is what the intellect or عقل does it sets a boundary it confines it defines', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 27, NULL, 'This is the problem Allah سُبْحَانَهُ وَتَعَالَى solved for me: how can I understand and recognize an infinite Creator through finiteness? The answer is the creation of this عالَم. My ways of learning are limited. I must define something before I can understand it. So how can I, a creature of finiteness and definition, understand a Creator who is infinite and cannot be defined? I understand through the intermediary of a عالَم, which acts like an interpreter.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'this is the problem allah سبحانه وتعالي solved for me how can i understand and recognize an infinite creator through finiteness the answer is the creation of this عالم my ways of learning are limited i must define something before i can understand it so how can i a creature of finiteness and definition understand a creator who is infinite and cannot be defined i understand through the intermediary of a عالم which acts like an interpreter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 28, NULL, 'If a group speaks only English, and I know only Urdu, then I need a middleman to understand what is being said. I need someone who understands both languages, someone who can receive the message in English and translate it into Urdu for me.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'if a group speaks only english and i know only urdu then i need a middleman to understand what is being said i need someone who understands both languages someone who can receive the message in english and translate it into urdu for me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 29, NULL, 'The same idea applies to this عالم. In its creation, it is physical. In its design, it reflects the attributes of its Creator. It “defines” the attributes of the Creator''s glory and magnificence, so that I can gain some understanding of my Creator.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the same idea applies to this عالم in its creation it is physical in its design it reflects the attributes of its creator it defines the attributes of the creators glory and magnificence so that i can gain some understanding of my creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 31, NULL, 'In other words, this universe becomes the medium through which I recognize Allah سُبْحَانَهُ وَتَعَالَى, for every sculpture proves the presence of a sculptor. The poet says:', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'in other words this universe becomes the medium through which i recognize allah سبحانه وتعالي for every sculpture proves the presence of a sculptor the poet says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 32, NULL, 'Verseوُجُودُہُ لَہُ دَلِیلُ قَاطِعٌ', '', 'وُجُودُہُ لَہُ دَلِیلُ قَاطِعٌ', 'Verse', NULL, NULL, 'surah al fateha understanding rab al alameen', 'verseوجوده له دليل قاطع', 'وجوده له دليل قاطع');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 33, NULL, 'Sayingحَاجَتُ کُلِّ مُحدَثٍ لِصَانعٌ', '', 'حَاجَتُ کُلِّ مُحدَثٍ لِصَانعٌ', 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingحاجت كل محدث لصانع', 'حاجت كل محدث لصانع');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 34, NULL, 'The strongest proof that Allah exists is that every sculpture requires a sculptor.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the strongest proof that allah exists is that every sculpture requires a sculptor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 35, NULL, 'Sayingوَلِکُلِّ عالَمُ لِحَاجَّتاً الی العَالِمٌ', '', 'وَلِکُلِّ عالَمُ لِحَاجَّتاً الی العَالِمٌ', 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingولكل عالم لحاجتا الي العالم', 'ولكل عالم لحاجتا الي العالم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 36, NULL, 'In the same way, everything that can be known requires the existence of one who knows it, because nothing exists as a mere passive object. Therefore, I come to know that Allah سُبْحَانَهُ وَتَعَالَى exists through the آثار, through His signs and the effects He has left in creation. This is like the Greek philosopher who asked the Bedouin:', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'in the same way everything that can be known requires the existence of one who knows it because nothing exists as a mere passive object therefore i come to know that allah سبحانه وتعالي exists through the اثار through his signs and the effects he has left in creation this is like the greek philosopher who asked the bedouin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 37, NULL, 'Sayingبِمَ عَرَفتَ رَبُّك؟“How did you come to know of your master?”', '', NULL, 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingبم عرفت ربك how did you come to know of your master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 38, NULL, 'he said.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 39, NULL, 'Sayingإن البِعرَةُ تَدُلُّ علی البَعِیر. والرَّوثَةُ تَدُلُّ علی الحمیر. و آثارُ القدمُ تَدُلُّ علی المَسِیرHe said: The camel''s dung shows me that a camel passed here. The donkey''s dung tells me that a donkey was here. Footsteps in the sand tell me that people walked through this place.فسمآءُ ذاتُ اَبرَاج. وَالْاَرْضَ ذَاتَ الْفِجَاجِ. واَبحَرُ ذَاتَ الامواجSo when I look at the sky, with its perfect constellations; when I see the earth, with its valleys and paths laid out with order; and when I look at the oceans, with all their waves.اَلَا تَدُلُّ عَلَی لَطِیفِ الْخَبِیرِ؟', '', NULL, 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingان البعره تدل علي البعير والروثه تدل علي الحمير و اثار القدم تدل علي المسيرhe said the camels dung shows me that a camel passed here the donkeys dung tells me that a donkey was here footsteps in the sand tell me that people walked through this place فسماء ذات ابراج والارض ذات الفجاج وابحر ذات الامواجso when i look at the sky with its perfect constellations when i see the earth with its valleys and paths laid out with order and when i look at the oceans with all their waves الا تدل علي لطيف الخبير', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 40, NULL, 'Do all these not point to the presence of the لطیف and the خبیر? SubhanAllah. To him, it was that simple. I make such matters far more complicated than they are. The truth is that Allah''s existence is the clearest and most evident truth for a sound and healthy فطرۃ. When that primordial essence of فطرۃ remains intact, the question of a creator''s existence does not even arise. That is why, when the atheist says, “I wish there was a proof of the existence of Allah,” the believer replies, “I see nothing but the proofs of His existence.”', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'do all these not point to the presence of the لطيف and the خبير subhanallah to him it was that simple i make such matters far more complicated than they are the truth is that allahs existence is the clearest and most evident truth for a sound and healthy فطره when that primordial essence of فطره remains intact the question of a creators existence does not even arise that is why when the atheist says i wish there was a proof of the existence of allah the believer replies i see nothing but the proofs of his existence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 41, NULL, 'That is the linguistic meaning of the word عالَم. It is anything and everything that the عالِم can know, so that he may recognize the علیم. For that reason, “world” is not the best translation of عالمین. It narrows the word''s range. If the word meant only “world,” then it would refer only to that, and to nothing beyond the world or the universe. Its plural would then have been العوالم, not الْعَالَمِینَ.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'that is the linguistic meaning of the word عالم it is anything and everything that the عالم can know so that he may recognize the عليم for that reason world is not the best translation of عالمين it narrows the words range if the word meant only world then it would refer only to that and to nothing beyond the world or the universe its plural would then have been العوالم not العالمين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 42, NULL, 'The word الْعَالَمِینَ covers a far wider range than the physical world alone. The statement رَبُّ الْعَالَمِینَ does not mean only that Allah is the master of worlds, or the master of the universe. It means that He is the master of everything that can be known. Everything in creation reflects the علیم. It exists in a passive state, waiting for the عالم to learn about it through reflection, so that he may recognize his Creator.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the word العالمين covers a far wider range than the physical world alone the statement رب العالمين does not mean only that allah is the master of worlds or the master of the universe it means that he is the master of everything that can be known everything in creation reflects the عليم it exists in a passive state waiting for the عالم to learn about it through reflection so that he may recognize his creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 43, NULL, 'I therefore understand رَبُّ الْعَالَمِینَ in a much wider sense than “master of this world” or “master of this universe.” He is the master of every species, every distinct group within creation, every category, every concept, every idea, every postulate, every form of physical matter, every form of chemical matter, and every spiritual entity. Everything that exists, whether physical or metaphysical, falls within the meaning of عالَم. All of it exists for one reason alone: so that its Creator may be recognized and understood.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i therefore understand رب العالمين in a much wider sense than master of this world or master of this universe he is the master of every species every distinct group within creation every category every concept every idea every postulate every form of physical matter every form of chemical matter and every spiritual entity everything that exists whether physical or metaphysical falls within the meaning of عالم all of it exists for one reason alone so that its creator may be recognized and understood', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 45, NULL, 'I find many explanations of the term رَبُّ الْعَالَمِینَ. Here I draw out one interpretation, centered on a quality that is greatly lacking in society: humility. Allah points out that He created different cultures, different creations, different civilizations, and people of different languages. He says in the Quran:', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i find many explanations of the term رب العالمين here i draw out one interpretation centered on a quality that is greatly lacking in society humility allah points out that he created different cultures different creations different civilizations and people of different languages he says in the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 46, NULL, 'Al-Baqarah: 47يَبَنِىٓ إِسْرَٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَلَمِينَ', '', 'يَبَنِىٓ إِسْرَٓءِيلَ ٱذْكُرُوا۟ نِعْمَتِىَ ٱلَّتِىٓ أَنْعَمْتُ عَلَيْكُمْ وَأَنِّى فَضَّلْتُكُمْ عَلَى ٱلْعَلَمِينَ', 'Al-Baqarah: 47', 2, 47, 'surah al fateha understanding rab al alameen', 'al baqarah 47يبني اسرءيل اذكروا نعمتي التي انعمت عليكم واني فضلتكم علي العلمين', 'يبني اسرءيل اذكروا نعمتي التي انعمت عليكم واني فضلتكم علي العلمين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 47, NULL, 'I gave you preference over every other nation. The word used here for nations is عالمین.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i gave you preference over every other nation the word used here for nations is عالمين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 48, NULL, 'I understand from this that Allah is the Creator and Master of all nations, and that His creation must therefore be treated with care. Race and religion do not remove that duty. No one may forget that Allah is رَبُّ الْعَالَمِینَ.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i understand from this that allah is the creator and master of all nations and that his creation must therefore be treated with care race and religion do not remove that duty no one may forget that allah is رب العالمين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 49, NULL, 'This matters because harm done to His creation is never small. A heart may be broken by words. A person may be tortured through a temporary authority that Allah Himself granted. In such moments, the warning remains: I am رَبُّ الْعَالَمِینَ.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'this matters because harm done to his creation is never small a heart may be broken by words a person may be tortured through a temporary authority that allah himself granted in such moments the warning remains i am رب العالمين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 50, NULL, 'Nor does this apply only to human beings. It includes animals, plants, and the earth itself. Before any cruelty is shown to any part of His creation, I must remember: He is their رب too.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'nor does this apply only to human beings it includes animals plants and the earth itself before any cruelty is shown to any part of his creation i must remember he is their رب too', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 51, NULL, 'When a slave is wronged, the offense ultimately reaches the master. In earlier times, wars could begin because someone from one tribe unjustly harmed or killed the slave of another. The master treated that act as a personal insult, because the slave was under his ownership and responsibility. Even if the slave had done wrong and deserved correction, the complaint still belonged before his master.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'when a slave is wronged the offense ultimately reaches the master in earlier times wars could begin because someone from one tribe unjustly harmed or killed the slave of another the master treated that act as a personal insult because the slave was under his ownership and responsibility even if the slave had done wrong and deserved correction the complaint still belonged before his master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 52, NULL, 'So Allah says, “I am رَبُّ الْعَالَمِینَ, so be careful in how you deal with My creation. It does not matter what group, religion, caste, belief system, or country they belong to. It does not matter what relationship they have with you on this earth.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'so allah says i am رب العالمين so be careful in how you deal with my creation it does not matter what group religion caste belief system or country they belong to it does not matter what relationship they have with you on this earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 53, NULL, '“Before he is your son, he is My slave. Before she is your daughter, she is My slave. Before he is your father, and before she is your mother, they are My slaves. Before she is your daughter-in-law, she is My slave. Before he is your son-in-law, he is My slave. Before he is your employee, your servant, or your student, do not forget: he is My slave.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'before he is your son he is my slave before she is your daughter she is my slave before he is your father and before she is your mother they are my slaves before she is your daughter in law she is my slave before he is your son in law he is my slave before he is your employee your servant or your student do not forget he is my slave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 54, NULL, '“I am present, and I am watching. If you treat them unjustly, if you hurt them, if you insult or degrade them, if you misuse your authority over them, you will answer to Me, because I am رَبُّ الْعَالَمِینَ.”', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i am present and i am watching if you treat them unjustly if you hurt them if you insult or degrade them if you misuse your authority over them you will answer to me because i am رب العالمين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 55, NULL, 'SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 56, NULL, 'In one of the sermons of نَہْجُ الْبَلَاغَۃِ, Maulana Ali explains what the title رب العلمین does: it brings all of us to the same level before the Creator. It marks all creation as His slaves.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'in one of the sermons of نهج البلاغه maulana ali explains what the title رب العلمين does it brings all of us to the same level before the creator it marks all creation as his slaves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 57, NULL, 'No nation and no group is better than another because of race or color. If one person is better than another, then by whose standard is that superiority measured? Who alone can judge it? The Master.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'no nation and no group is better than another because of race or color if one person is better than another then by whose standard is that superiority measured who alone can judge it the master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 58, NULL, 'This has become a serious disease in our community. Because we are Muslims, or because we are Sulemanis, we begin to think that we are better than the rest of the world. Yes, we are certainly superior in our knowledge of realities, AlHamdulillah. There is no doubt about that. But that knowledge gives us no right to treat other communities or other religions with spite. It gives us no license to look down on others.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'this has become a serious disease in our community because we are muslims or because we are sulemanis we begin to think that we are better than the rest of the world yes we are certainly superior in our knowledge of realities alhamdulillah there is no doubt about that but that knowledge gives us no right to treat other communities or other religions with spite it gives us no license to look down on others', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 59, NULL, 'In the world today, we suffer from the disease of superiority, from the feeling that we carry some special claim over others, whether we admit it or not. It may come through religion, race, wealth, social status, or any other reason. I must not forget that we all have the same رب.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'in the world today we suffer from the disease of superiority from the feeling that we carry some special claim over others whether we admit it or not it may come through religion race wealth social status or any other reason i must not forget that we all have the same رب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 60, NULL, 'Rank can exist only in the eyes of the Master, and only according to the slave''s servitude. It does not exist in the eyes of the slave.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'rank can exist only in the eyes of the master and only according to the slaves servitude it does not exist in the eyes of the slave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 61, NULL, 'Al-Hujurat: 13إِنَّ أَكْرَمَكُمْ عِندَ اللَّهِ أَتْقَاكُمْ', '', 'إِنَّ أَكْرَمَكُمْ عِندَ اللَّهِ أَتْقَاكُمْ', 'Al-Hujurat: 13', 49, 13, 'surah al fateha understanding rab al alameen', 'al hujurat 13ان اكرمكم عند الله اتقاكم', 'ان اكرمكم عند الله اتقاكم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 62, NULL, 'I stand before the same rule: the most honorable in the eyes of Allah is the one with the most piety. Nothing else gives that honor. Even the highest-ranking person is Allah''s slave, and even the lowest-ranking person is Allah''s slave.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i stand before the same rule the most honorable in the eyes of allah is the one with the most piety nothing else gives that honor even the highest ranking person is allahs slave and even the lowest ranking person is allahs slave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 63, NULL, 'This is what we recite in every أذان, five times a day:', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'this is what we recite in every اذان five times a day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 64, NULL, 'Sayingاشھد ان محمد عبدہ و رسولہ', '', 'اشھد ان محمد عبدہ و رسولہ', 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingاشهد ان محمد عبده و رسوله', 'اشهد ان محمد عبده و رسوله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 65, NULL, 'I testify that Muhammad ﷺ is his slave and his messenger. AllahuAkbar. The highest-ranking person who ever walked this earth is the one we testify to in every prayer as the slave of Allah. Then no one has the right to claim superiority over another. If Allah has blessed a person with gifts, and the greatest gift is ایمان, faith itself, then that gift should make him more humble, not arrogant.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i testify that muhammad ﷺ is his slave and his messenger allahuakbar the highest ranking person who ever walked this earth is the one we testify to in every prayer as the slave of allah then no one has the right to claim superiority over another if allah has blessed a person with gifts and the greatest gift is ايمان faith itself then that gift should make him more humble not arrogant', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 66, NULL, 'The Quran gives the story of one who became arrogant because of his title and rank: the story of ابلیس.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the quran gives the story of one who became arrogant because of his title and rank the story of ابليس', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 67, NULL, 'Sayingأَنَا۠ خَيْرٌۭ مِّنْهُ . خَلَقْتَنِى مِن نَّارٍۢ وَخَلَقْتَهُۥ مِن طِينٍۢ', '', 'أَنَا۠ خَيْرٌۭ مِّنْهُ . خَلَقْتَنِى مِن نَّارٍۢ وَخَلَقْتَهُۥ مِن طِينٍۢ', 'Saying', 7, 12, 'surah al fateha understanding rab al alameen', 'sayingانا خير منه خلقتني من نار وخلقته من طين', 'انا خير منه خلقتني من نار وخلقته من طين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 68, NULL, 'I am better than him. I was created from fire; he was created from clay. ابلیس was an angel, from the عالَم of angels. Adam was a human being, from the عالَم of انسان. Both were slaves of Allah. And ابلیس stood before Allah; He stood before the رَبُّ الْعَالَمِینَ and said:', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i am better than him i was created from fire he was created from clay ابليس was an angel from the عالم of angels adam was a human being from the عالم of انسان both were slaves of allah and ابليس stood before allah he stood before the رب العالمين and said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 69, NULL, 'I am better than him.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i am better than him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 70, NULL, 'This story teaches a clear lesson. What did his Master do with that arrogance? Did it bring him nearer to Allah, or did it cast him out from the Divine Presence? The act for which ابلیس was punished cannot be treated lightly when it appears in me. That would not befit Allah''s justice: to punish ابلیس for arrogance and remove him from His Presence, then reward the same arrogance in me by bringing me nearer to Him. Impossible.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'this story teaches a clear lesson what did his master do with that arrogance did it bring him nearer to allah or did it cast him out from the divine presence the act for which ابليس was punished cannot be treated lightly when it appears in me that would not befit allahs justice to punish ابليس for arrogance and remove him from his presence then reward the same arrogance in me by bringing me nearer to him impossible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 71, NULL, 'The matter must be understood plainly. When I judge another slave and decide that one slave is superior to another, what position have I taken for myself? I have placed myself in the position of my رب.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the matter must be understood plainly when i judge another slave and decide that one slave is superior to another what position have i taken for myself i have placed myself in the position of my رب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 72, NULL, 'The Quran also tells of someone who did that. Someone said, اَنَا رَبُّکُمُ الْاَعْلَی. I am your greatest رب. فرعون said that. His end is known.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the quran also tells of someone who did that someone said انا ربكم الاعلي i am your greatest رب فرعون said that his end is known', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 73, NULL, 'The reality is that فرعون knew he was human. He knew he was not a رب. He knew his own weakness. Yet he still claimed a station he did not deserve. He even hated the fact that he needed to go to the toilet, because that was not fitting, in his mind, for a رب.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the reality is that فرعون knew he was human he knew he was not a رب he knew his own weakness yet he still claimed a station he did not deserve he even hated the fact that he needed to go to the toilet because that was not fitting in his mind for a رب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 74, NULL, 'So he gathered all his physicians and asked them how he could escape this problem. They told him to eat bananas. He ate bananas for forty days, and then he ended up with a much bigger problem.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'so he gathered all his physicians and asked them how he could escape this problem they told him to eat bananas he ate bananas for forty days and then he ended up with a much bigger problem', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 75, NULL, 'I keep repeating and stressing this because it is no longer only a Fironic problem. It has become a global problem. Everyone wants to become الہ; everyone wants to become معبود. At some level, we have all become people who want to be worshiped. Yet we forget how Allah defines us in the Quran:', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i keep repeating and stressing this because it is no longer only a fironic problem it has become a global problem everyone wants to become اله everyone wants to become معبود at some level we have all become people who want to be worshiped yet we forget how allah defines us in the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 76, NULL, 'Al-Mu''minun: 12وَلَقَدْ خَلَقْنَا ٱلْإِنسَنَ مِن سُلَلَةٍۢ مِّن طِينٍۢ', '', 'وَلَقَدْ خَلَقْنَا ٱلْإِنسَنَ مِن سُلَلَةٍۢ مِّن طِينٍۢ', 'Al-Mu''minun: 12', 23, 12, 'surah al fateha understanding rab al alameen', 'al muminun 12ولقد خلقنا الانسن من سلله من طين', 'ولقد خلقنا الانسن من سلله من طين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 77, NULL, 'Human beings come from a chain of dirt, from mud and water mixed together.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'human beings come from a chain of dirt from mud and water mixed together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 78, NULL, 'As-Sajdah: 8ثُمَّ جَعَلَ نَسْلَهُۥ مِن سُلَلَةٍۢ مِّن مَّآءٍۢ مَّهِينٍۢI understand Allah telling these people: “We created your progeny from a lowly fluid. Who do you think you are? Get down off your high horse. Be a رجل.”', '', NULL, 'As-Sajdah: 8', NULL, NULL, 'surah al fateha understanding rab al alameen', 'as sajdah 8ثم جعل نسله من سلله من ماء مهينi understand allah telling these people we created your progeny from a lowly fluid who do you think you are get down off your high horse be a رجل', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 79, NULL, 'A رجل is the one who has ِرَجَلَ. As it is said: ِرَجَلَ عن فَرِسِہ. He is the one who comes down from his high horse and plants his feet on the ground. He does not see himself as raised above the earth. He returns to the level from which he came: dust. That is الرجل.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'a رجل is the one who has رجل as it is said رجل عن فرسه he is the one who comes down from his high horse and plants his feet on the ground he does not see himself as raised above the earth he returns to the level from which he came dust that is الرجل', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 80, NULL, 'Yet I see that all of us, at some level, are playing games. We are trying to be الہ. Allah سُبْحَانَهُ وَتَعَالَى says no: “Be a رجل. Be بنی آدم. Be آدمی.” That is what it truly means to accept Allah as رَبُّ الْعَالَمِینَ. Humility, not arrogance, is the mark of a believer.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'yet i see that all of us at some level are playing games we are trying to be اله allah سبحانه وتعالي says no be a رجل be بني ادم be ادمي that is what it truly means to accept allah as رب العالمين humility not arrogance is the mark of a believer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 81, NULL, 'The acceptance of our عبودیۃ, our slavery and servitude to Allah سُبْحَانَهُ وَتَعَالَى, is a heavy burden that I, as a believer, carry on my back. When a burden rests on the back of a person climbing a mountain, he bends forward; he does not walk upright. The burden makes him bend. It makes him humble. This is why humility is the essence of spiritual progress. Maulana Ali says', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the acceptance of our عبوديه our slavery and servitude to allah سبحانه وتعالي is a heavy burden that i as a believer carry on my back when a burden rests on the back of a person climbing a mountain he bends forward he does not walk upright the burden makes him bend it makes him humble this is why humility is the essence of spiritual progress maulana ali says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 82, NULL, 'Sayingمَنْ تَوَاضَعَ لِی اللَّہُ، رَفَعَ اللَّہُ لَہُ', '', 'مَنْ تَوَاضَعَ لِی اللَّہُ، رَفَعَ اللَّہُ لَہُ', 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingمن تواضع لي الله رفع الله له', 'من تواضع لي الله رفع الله له');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 83, NULL, 'Whoever humbles himself for Allah, Allah raises him and lifts him in rank. For this reason, the highest-ranking person ever to walk the face of the earth was my beloved Prophet مُحَمَّدٌ مُصْطَفَی ﷺ. The greatest man this world will ever know was also the humblest in character. Indeed, humility was his distinguishing mark. The earlier prophecies that foretold his coming identified him by the greatness of his humility. SubhanAllah. The greatest mark of his prophethood was his humility.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'whoever humbles himself for allah allah raises him and lifts him in rank for this reason the highest ranking person ever to walk the face of the earth was my beloved prophet محمد مصطفي ﷺ the greatest man this world will ever know was also the humblest in character indeed humility was his distinguishing mark the earlier prophecies that foretold his coming identified him by the greatness of his humility subhanallah the greatest mark of his prophethood was his humility', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 84, NULL, 'Sayingیُریدُ أَنَّ یَبعَثُ أُمِیِّ مِنَ الأُمِّیِّن۔وأجعل السكينةَ لباسُهُ ، والبِرَّ شَعارُهُ ، والتقوى ضَميرَهُ ، والحِكمَةَ مَنطِقَهُ ، والصِّدقَ والوفاءَ طَبِيعَتُهُ ، والعَفوَ وَالمَعرُوفَ خُلقُهُ ، والَحقَّ شَريعَتَهُ ، والعَدلَ سيرَتَهُ ، والهَدِىُ إمامُهُ ، والإسلامَ مِلَّتُهُ ، وأحمد أِسمُهُ .', '', 'یُریدُ أَنَّ یَبعَثُ أُمِیِّ مِنَ الأُمِّیِّن۔وأجعل السكينةَ لباسُهُ ، والبِرَّ شَعارُهُ ، والتقوى ضَميرَهُ ، والحِكمَةَ مَنطِقَهُ ، والصِّدقَ والوفاءَ طَبِيعَتُهُ ، والعَفوَ وَالمَعرُوفَ خُلقُهُ ، والَحقَّ شَريعَتَهُ ، والعَدلَ سيرَتَهُ ، والهَدِىُ إمامُهُ ، والإسلامَ مِلَّتُهُ ، وأحمد أِسمُهُ .', 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingيريد ان يبعث امي من الامين واجعل السكينه لباسه والبر شعاره والتقوي ضميره والحكمه منطقه والصدق والوفاء طبيعته والعفو والمعروف خلقه والحق شريعته والعدل سيرته والهدي امامه والاسلام ملته واحمد اسمه', 'يريد ان يبعث امي من الامين واجعل السكينه لباسه والبر شعاره والتقوي ضميره والحكمه منطقه والصدق والوفاء طبيعته والعفو والمعروف خلقه والحق شريعته والعدل سيرته والهدي امامه والاسلام ملته واحمد اسمه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 85, NULL, 'Sayingأَهدِي بِهِ بَعدَ الضَّلالَة ، وأعلَمُ بِهِ مِنَ الجَهالة ، وأَرفَعُ به بعد الخَمالَة ، وأعرِفُ به بعد النَّكِرَة ، وأكثَرُ بِهِ بعدَ القِلَّة ، وأغنِي به بعد العَيلَة ، وأَجمِعُ به بعد الفُرقَة', '', 'أَهدِي بِهِ بَعدَ الضَّلالَة ، وأعلَمُ بِهِ مِنَ الجَهالة ، وأَرفَعُ به بعد الخَمالَة ، وأعرِفُ به بعد النَّكِرَة ، وأكثَرُ بِهِ بعدَ القِلَّة ، وأغنِي به بعد العَيلَة ، وأَجمِعُ به بعد الفُرقَة', 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingاهدي به بعد الضلاله واعلم به من الجهاله وارفع به بعد الخماله واعرف به بعد النكره واكثر به بعد القله واغني به بعد العيله واجمع به بعد الفرقه', 'اهدي به بعد الضلاله واعلم به من الجهاله وارفع به بعد الخماله واعرف به بعد النكره واكثر به بعد القله واغني به بعد العيله واجمع به بعد الفرقه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 86, NULL, 'I recognize here the prediction, in the Bible, of the arrival of Rasul Allah ﷺ. Allah mentions these beautiful signs of his coming:', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i recognize here the prediction in the bible of the arrival of rasul allah ﷺ allah mentions these beautiful signs of his coming', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 87, NULL, 'I am going to send you a man from your own nation. His garment will be a peaceful temperament; his behavior will be kind; his conscience will be pious; his reasoning will be wise. Honesty and truth will be his nature; forgiveness will fill his dealings; justice will mark his actions; Ahmed will be his name.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i am going to send you a man from your own nation his garment will be a peaceful temperament his behavior will be kind his conscience will be pious his reasoning will be wise honesty and truth will be his nature forgiveness will fill his dealings justice will mark his actions ahmed will be his name', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 88, NULL, 'Sayingأَهدِي بِهِ بَعدَ الضَّلالَة ، وأعلَمُ بِهِ مِنَ الجَهالة ، وأَرفَعُ به بعد الخَمالَة ، وأعرِفُ به بعد النَّكِرَة ، وأكثَرُ بِهِ بعدَ القِلَّة ، وأغنِي به بعد العَيلَة', '', 'أَهدِي بِهِ بَعدَ الضَّلالَة ، وأعلَمُ بِهِ مِنَ الجَهالة ، وأَرفَعُ به بعد الخَمالَة ، وأعرِفُ به بعد النَّكِرَة ، وأكثَرُ بِهِ بعدَ القِلَّة ، وأغنِي به بعد العَيلَة', 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingاهدي به بعد الضلاله واعلم به من الجهاله وارفع به بعد الخماله واعرف به بعد النكره واكثر به بعد القله واغني به بعد العيله', 'اهدي به بعد الضلاله واعلم به من الجهاله وارفع به بعد الخماله واعرف به بعد النكره واكثر به بعد القله واغني به بعد العيله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 89, NULL, 'I will guide a nation through him and bring them out of error. I will give them knowledge through him and bring them out of ignorance. I will raise him after he had been belittled, make him known after he had been unknown, increase him after scarcity, and enrich him after poverty. Allah continues to mention these qualities of His beloved. Then, after all these beautiful traits and astonishing signs, He mentions the greatest sign of all.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i will guide a nation through him and bring them out of error i will give them knowledge through him and bring them out of ignorance i will raise him after he had been belittled make him known after he had been unknown increase him after scarcity and enrich him after poverty allah continues to mention these qualities of his beloved then after all these beautiful traits and astonishing signs he mentions the greatest sign of all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 90, NULL, 'Sayingلَو یَمشِی عَلی القَصَبِ الیَابِس۔۔۔ لَم یُسمَع مِن تَحتِ قَدَمَیہِ مِن سَکِینَتِہِ', '', 'لَو یَمشِی عَلی القَصَبِ الیَابِس۔۔۔ لَم یُسمَع مِن تَحتِ قَدَمَیہِ مِن سَکِینَتِہِ', 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingلو يمشي علي القصب اليابس لم يسمع من تحت قدميه من سكينته', 'لو يمشي علي القصب اليابس لم يسمع من تحت قدميه من سكينته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 91, NULL, 'He will be deeply humble. He will walk among people with such humility that, when he steps on dry leaves, the crackle beneath his feet will not be heard. SubhanAllah. This is the Prophet I follow. This is the example I follow.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'he will be deeply humble he will walk among people with such humility that when he steps on dry leaves the crackle beneath his feet will not be heard subhanallah this is the prophet i follow this is the example i follow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 92, NULL, 'The honor this slave of Allah received from his Master came through one quality: humility. That is what separates the true believer from the hypocrite.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the honor this slave of allah received from his master came through one quality humility that is what separates the true believer from the hypocrite', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 93, NULL, 'For this reason, I see atheism as a blatant form of arrogance. The atheist rejects the most obvious and most basic fact of his own existence: he was created. Even he cannot truly say that he was not created. If I say that my father created me, and his father created him before him, that is what they call دور; that is تسلسل. The chain keeps going backward. Where does it stop? It stops at Adam. Then who created Adam? That is where the matter ends.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'for this reason i see atheism as a blatant form of arrogance the atheist rejects the most obvious and most basic fact of his own existence he was created even he cannot truly say that he was not created if i say that my father created me and his father created him before him that is what they call دور that is تسلسل the chain keeps going backward where does it stop it stops at adam then who created adam that is where the matter ends', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 94, NULL, 'Sayingوکُلُّکُم مِن آدَم. وَ آدَم مِن تُرَاب', '', 'وکُلُّکُم مِن آدَم. وَ آدَم مِن تُرَاب', 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingوكلكم من ادم و ادم من تراب', 'وكلكم من ادم و ادم من تراب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 95, NULL, 'All of you are from Adam, and Adam is from dust. Arrogance does not befit dirt, because dirt is constantly trampled underfoot.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'all of you are from adam and adam is from dust arrogance does not befit dirt because dirt is constantly trampled underfoot', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 96, NULL, 'Maulana Ali saw a man acting arrogantly, and he said to him, “Who do you think you are? Your beginning is a vile, dirty fluid. Your end is a disgusting, decaying, foul-smelling corpse. Between those two stages, you walk through life carrying two loathsome things inside your body: your urine and your feces. Your creation comes from the union of two ugly body parts. What right do you have to act arrogantly before Allah and his creation?”', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'maulana ali saw a man acting arrogantly and he said to him who do you think you are your beginning is a vile dirty fluid your end is a disgusting decaying foul smelling corpse between those two stages you walk through life carrying two loathsome things inside your body your urine and your feces your creation comes from the union of two ugly body parts what right do you have to act arrogantly before allah and his creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 97, NULL, 'This is the first matter: I must know my station in this world, and I must know who I am. I am Marboob. I am created. I will die. I will be raised up. This understanding, that I am Marboob, is the station of the slave. It is the knowledge that I am not Mabood. I am not the creator.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'this is the first matter i must know my station in this world and i must know who i am i am marboob i am created i will die i will be raised up this understanding that i am marboob is the station of the slave it is the knowledge that i am not mabood i am not the creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 98, NULL, 'Wallahi, I give myself sincere advice: humility belongs in every walk of life. Arrogance must not take root. It is the greatest challenge of our time. Arrogance is the أذان; it is the call of our age. It has become the trademark of worldly success: in schools, in colleges, at work, in families, and in communities. The whole claim is, “I am better than you.” Arrogance does not befit an obedient slave.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'wallahi i give myself sincere advice humility belongs in every walk of life arrogance must not take root it is the greatest challenge of our time arrogance is the اذان it is the call of our age it has become the trademark of worldly success in schools in colleges at work in families and in communities the whole claim is i am better than you arrogance does not befit an obedient slave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 99, NULL, 'May Allah grant us all humility, guide us, and enable us to walk in the footsteps of our beloved prophet ﷺ.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'may allah grant us all humility guide us and enable us to walk in the footsteps of our beloved prophet ﷺ', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 100, NULL, 'If I grasp even this much, if I truly understand the meaning of Rabb Alalameen, the world becomes a beautiful place.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'if i grasp even this much if i truly understand the meaning of rabb alalameen the world becomes a beautiful place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 101, NULL, 'If I understand that Allah is the Rabb Alalameen, then I understand that He is the One who guides everyone. He is the King. He is the Owner. He is the One who cares, the One who guides, and the One who gives gifts. Then everything in my life is between me and Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'if i understand that allah is the rabb alalameen then i understand that he is the one who guides everyone he is the king he is the owner he is the one who cares the one who guides and the one who gives gifts then everything in my life is between me and him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 102, NULL, 'He will take care of me. I do not need to worry about anything. I do not need to judge another slave. I do not need to hurt another slave. I do not need to show my authority or power over another slave, even if I am hurt, even if I am wronged, especially if I have been wronged.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'he will take care of me i do not need to worry about anything i do not need to judge another slave i do not need to hurt another slave i do not need to show my authority or power over another slave even if i am hurt even if i am wronged especially if i have been wronged', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 103, NULL, 'My Master will take care of me. My Master will come to my rescue. He will come to my defense on the Day of Judgment, and He will make that wrong right. He will stand behind me and support me. I do not need to worry about anything.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'my master will take care of me my master will come to my rescue he will come to my defense on the day of judgment and he will make that wrong right he will stand behind me and support me i do not need to worry about anything', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 104, NULL, 'Whether I believe it or not, whether I want it or not, that Day is coming: the Day when the Rabb will gather everyone and exact justice.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'whether i believe it or not whether i want it or not that day is coming the day when the rabb will gather everyone and exact justice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 105, NULL, 'Ali ''Imran: 9رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍۢ لَّا رَيْبَ فِيهِ ۚ', '', 'رَبَّنَآ إِنَّكَ جَامِعُ ٱلنَّاسِ لِيَوْمٍۢ لَّا رَيْبَ فِيهِ ۚ', 'Ali ''Imran: 9', 3, 9, 'surah al fateha understanding rab al alameen', 'ali imran 9ربنا انك جامع الناس ليوم لا ريب فيه', 'ربنا انك جامع الناس ليوم لا ريب فيه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 106, NULL, 'Oh our Master. Indeed, You will gather all of us on a Day about which there is absolutely no doubt, because You have promised us that.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'oh our master indeed you will gather all of us on a day about which there is absolutely no doubt because you have promised us that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 107, NULL, 'Ali ''Imran: 9إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', '', 'إِنَّ ٱللَّهَ لَا يُخْلِفُ ٱلْمِيعَادَ', 'Ali ''Imran: 9', 3, 9, 'surah al fateha understanding rab al alameen', 'ali imran 9ان الله لا يخلف الميعاد', 'ان الله لا يخلف الميعاد');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 108, NULL, 'There is no doubt. Allah never goes against His promise. I remind myself of this every time I recite the Fateha. There is a reason I pray fifty-one rakaats in one day, and all fifty-one times I recite Fateha: so that every time I say Rabb Alalameen, I remind myself of this hierarchy.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'there is no doubt allah never goes against his promise i remind myself of this every time i recite the fateha there is a reason i pray fifty one rakaats in one day and all fifty one times i recite fateha so that every time i say rabb alalameen i remind myself of this hierarchy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 109, NULL, 'I understand who He is, and who I am in this relationship.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i understand who he is and who i am in this relationship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 110, NULL, 'Sayingوآخر الدعوانا عن الحمد للہ رَبُّ الْعَالَمِینَ', '', 'وآخر الدعوانا عن الحمد للہ رَبُّ الْعَالَمِینَ', 'Saying', NULL, NULL, 'surah al fateha understanding rab al alameen', 'sayingواخر الدعوانا عن الحمد لله رب العالمين', 'واخر الدعوانا عن الحمد لله رب العالمين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 111, NULL, 'A man gave Rasul Allah a bottle of wine as a gift.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'a man gave rasul allah a bottle of wine as a gift', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 112, NULL, 'I think of the man who traveled a long distance to meet Rasul Allah (Salawaat). When he reached him, he brought the Messenger a bottle of wine as a gift. He said, “Ya RasulAllah, I got this special wine as a gift for you.”', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i think of the man who traveled a long distance to meet rasul allah salawaat when he reached him he brought the messenger a bottle of wine as a gift he said ya rasulallah i got this special wine as a gift for you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 113, NULL, 'I know how such a scene often unfolds. A very secularized person arrives at a Muslim home with a bottle of wine as a housewarming gift, and the reaction becomes outrage: “La hawla wala quwwata. How dare you? Do you not know I am a Muslim? Do you not know this is haraam? Get the hell out of my house. Never show me your face again.”', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'i know how such a scene often unfolds a very secularized person arrives at a muslim home with a bottle of wine as a housewarming gift and the reaction becomes outrage la hawla wala quwwata how dare you do you not know i am a muslim do you not know this is haraam get the hell out of my house never show me your face again', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 114, NULL, 'But this man brought the bottle to Rasul Allah, the most pious man I can imagine. He smiled. He smiled and said, “Brother, did you not hear Allah''s command that alcohol has been prohibited?”', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'but this man brought the bottle to rasul allah the most pious man i can imagine he smiled he smiled and said brother did you not hear allahs command that alcohol has been prohibited', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 115, NULL, 'He said, “No, Rasul Allah. I never heard that!”', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'he said no rasul allah i never heard that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 116, NULL, 'He immediately gave the bottle to his slave and whispered something in his ear. Rasul Allah says, “What did you just say to him?”', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'he immediately gave the bottle to his slave and whispered something in his ear rasul allah says what did you just say to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 117, NULL, 'The man said, “I told him to sell the bottle in the market.”', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'the man said i told him to sell the bottle in the market', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 118, NULL, 'Rasul Allah smiled again and said, “The One who has prohibited the consumption of intoxicants has also forbidden its trade.”', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'rasul allah smiled again and said the one who has prohibited the consumption of intoxicants has also forbidden its trade', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 119, NULL, 'So the man told the slave to pour it out.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'so the man told the slave to pour it out', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 120, NULL, 'This is the character of Rasul Allah. This is his humility. This is the Tarbiyyah, his rububiyyah. SubhanAllah. He did not say, “Do you not know who I am? How dare you bring this filth into my presence?” He never did that.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'this is the character of rasul allah this is his humility this is the tarbiyyah his rububiyyah subhanallah he did not say do you not know who i am how dare you bring this filth into my presence he never did that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'understanding rab al-alameen', 'Understanding RAB Al-ALAMEEN', 121, NULL, 'Hearts are never conquered with harshness. Hearts have always been conquered only with love and kindness. I need to study and learn what kind of Rabb, what kind of parent, and what kind of teacher our Prophet ﷺ was. SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha understanding rab al alameen', 'hearts are never conquered with harshness hearts have always been conquered only with love and kindness i need to study and learn what kind of rabb what kind of parent and what kind of teacher our prophet ﷺ was subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 0, NULL, 'I examined the term عالَم. It means anything and everything that the عالِم can know, so that he may recognize the علیم.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i examined the term عالم it means anything and everything that the عالم can know so that he may recognize the عليم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 1, NULL, 'Knowledge needs an object before it can be gained. To learn human physiology, I need the human body. To learn mathematics, I need numbers. To study physics, I need physical things to exist. As human beings, I cannot know a subject unless there is an object for that knowledge. This عالَم, then, is the object through which I gain knowledge of the علیم.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'knowledge needs an object before it can be gained to learn human physiology i need the human body to learn mathematics i need numbers to study physics i need physical things to exist as human beings i cannot know a subject unless there is an object for that knowledge this عالم then is the object through which i gain knowledge of the عليم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 2, NULL, 'I also examined the statement رَبُّ الْعَالَمِینَ. It shows that Allah is not only the master of this universe, but the master of everything the human intellect can know. Everything in creation therefore reflects the علیم. Whether it is physical, metaphysical, conceptual, or imaginable, whatever it may be, it reflects the علیم. The fact that he created this infinite universe for us reflects not only his glory and magnificence, but also his generosity and the vastness of his رحمۃ.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i also examined the statement رب العالمين it shows that allah is not only the master of this universe but the master of everything the human intellect can know everything in creation therefore reflects the عليم whether it is physical metaphysical conceptual or imaginable whatever it may be it reflects the عليم the fact that he created this infinite universe for us reflects not only his glory and magnificence but also his generosity and the vastness of his رحمه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 4, NULL, 'To place this in perspective, two fundamental questions stand around the understanding of God. The first is: Who is God? The second is: What does he want from us? These are the two essential questions mankind has grappled with from the beginning of time: Who is God, and what does he want from us?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'to place this in perspective two fundamental questions stand around the understanding of god the first is who is god the second is what does he want from us these are the two essential questions mankind has grappled with from the beginning of time who is god and what does he want from us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 5, NULL, 'I take the first question, “Who is God?” to include further questions: What is He capable of? What are His attributes? What is His personality? What are His traits?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i take the first question who is god to include further questions what is he capable of what are his attributes what is his personality what are his traits', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 6, NULL, 'I take the second question, “What does He want from us?” to include questions such as: Why did He create this universe? What is our purpose on this earth? What does He expect from us?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i take the second question what does he want from us to include questions such as why did he create this universe what is our purpose on this earth what does he expect from us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 7, NULL, 'Allah answers both questions through a very simple and straightforward formula in a verse of the Quran. He says:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'allah answers both questions through a very simple and straightforward formula in a verse of the quran he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 8, NULL, 'Question', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'question', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 9, NULL, 'In this verse, He mentions two broad categories: the horizons and the soul. The horizons are everything outside us: the physical universe. The soul is everything within us: our spiritual universe.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'in this verse he mentions two broad categories the horizons and the soul the horizons are everything outside us the physical universe the soul is everything within us our spiritual universe', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 10, NULL, 'So how does Allah answer the question, “Who am I?”', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'so how does allah answer the question who am i', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 11, NULL, 'Answers', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'answers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 12, NULL, 'He answers it through the horizons: the physical universe and everything within it.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'he answers it through the horizons the physical universe and everything within it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 13, NULL, 'How does He answer the question, “What do I want from you?” He answers it through the نفس: through our own creation and existence, and through the creation of our spirit and soul.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'how does he answer the question what do i want from you he answers it through the نفس through our own creation and existence and through the creation of our spirit and soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 14, NULL, 'This is what I call the genius of Allah''s design. I find it astonishing that He answers such a complex and seemingly impossible question with such a simple formula. In my personal view, this is my absolute proof of the existence of God and of the Quran as the message of Allah, because this kind of perfection in design cannot exist at the human level.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'this is what i call the genius of allahs design i find it astonishing that he answers such a complex and seemingly impossible question with such a simple formula in my personal view this is my absolute proof of the existence of god and of the quran as the message of allah because this kind of perfection in design cannot exist at the human level', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 15, NULL, 'This is also Allah''s solution to the problem that theology faces in modern times: the question of God''s existence. The problem today is that I try to invent and apply human formulas to prove that Allah exists. Yet Allah has already given His own formula in the Quran. It is simple, and it leads to the conclusion because it is the only formula that can work.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'this is also allahs solution to the problem that theology faces in modern times the question of gods existence the problem today is that i try to invent and apply human formulas to prove that allah exists yet allah has already given his own formula in the quran it is simple and it leads to the conclusion because it is the only formula that can work', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 16, NULL, 'If I try to use my own formulas, they fail, because this universe is His kingdom and His design. His rules govern it. The world gives many examples of this. An iPhone works according to Apple''s specifications; used outside those specifications, it does not work as intended. In the same way, Allah''s formula for recognizing Him is the آفاق and the أنفس.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'if i try to use my own formulas they fail because this universe is his kingdom and his design his rules govern it the world gives many examples of this an iphone works according to apples specifications used outside those specifications it does not work as intended in the same way allahs formula for recognizing him is the افاق and the انفس', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 17, NULL, 'Each part of the formula has to be understood in its place.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'each part of the formula has to be understood in its place', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 19, NULL, 'The first part of the formula is the آفاق, the horizons. This part answers several questions:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the first part of the formula is the افاق the horizons this part answers several questions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 20, NULL, 'Who is Allah? What is He capable of? Why is He worthy of my worship, my willing slavery, and my servitude? What makes Him so glorious, magnificent, and overwhelming in my sight that I would even consider Him my Master?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'who is allah what is he capable of why is he worthy of my worship my willing slavery and my servitude what makes him so glorious magnificent and overwhelming in my sight that i would even consider him my master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 21, NULL, 'Allah answers these questions through the signs in the آفاق, His signs in the horizons, meaning His signs in this universe. This subject belongs to the conclusions of reflection. There, I examined the prerequisite for understanding this formula. That prerequisite is this:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'allah answers these questions through the signs in the افاق his signs in the horizons meaning his signs in this universe this subject belongs to the conclusions of reflection there i examined the prerequisite for understanding this formula that prerequisite is this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 22, NULL, 'I must have a sound intellect and a pure heart. The Quran calls this لُب, the core. It also describes such people as اُولُو الْاَلْبَابِ: people whose hearts are pure and whose intellects are sound. Only the two together allow me to see reality as it truly is. The second requirement in the Quran, and in this formula, is an uncontaminated and pure فطرۃ. It grows from a pure heart and a sound intellect.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i must have a sound intellect and a pure heart the quran calls this لب the core it also describes such people as اولو الالباب people whose hearts are pure and whose intellects are sound only the two together allow me to see reality as it truly is the second requirement in the quran and in this formula is an uncontaminated and pure فطره it grows from a pure heart and a sound intellect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 23, NULL, 'The instrument by which I study the universe and learn from it is the intellect, العقل. Its work is to define things and set their limits. The intellect is the container, and knowledge is the content placed inside it. What, then, is knowledge (عِلْم)? In simple terms, knowledge is understanding and recognizing the true reality of things.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the instrument by which i study the universe and learn from it is the intellect العقل its work is to define things and set their limits the intellect is the container and knowledge is the content placed inside it what then is knowledge علم in simple terms knowledge is understanding and recognizing the true reality of things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 24, NULL, 'Concept and judgment', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'concept and judgment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 25, NULL, 'That understanding begins with a concept, called تصور in Arabic. First, the reality is formed in the mind. Then comes حکم: a ruling or judgment about the truth of that reality. The Arabs say:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'that understanding begins with a concept called تصور in arabic first the reality is formed in the mind then comes حكم a ruling or judgment about the truth of that reality the arabs say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 26, NULL, 'Sayingالحُکمُ علی شَیء فرحٌ عَن تَصَوُّرِہِ', '', 'الحُکمُ علی شَیء فرحٌ عَن تَصَوُّرِہِ', 'Saying', NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'sayingالحكم علي شيء فرح عن تصوره', 'الحكم علي شيء فرح عن تصوره');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 27, NULL, 'Before I can judge a thing, I must define it and understand it in every dimension that can be grasped. Once I have formed a clear concept of that reality, I can judge whether it is true or false, good or bad, and so on.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'before i can judge a thing i must define it and understand it in every dimension that can be grasped once i have formed a clear concept of that reality i can judge whether it is true or false good or bad and so on', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 28, NULL, 'Propositions', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'propositions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 29, NULL, 'I ask first how I, as a human being, form a concept of things. Scholars say that propositions are of three kinds.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i ask first how i as a human being form a concept of things scholars say that propositions are of three kinds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 30, NULL, 'A proposition is a statement or assertion that expresses a judgment or an opinion. For example, I may state, "fire burns," or "fire is bright." That statement is then tested against observation, and from that observation I judge whether it is true or false. This is how a proposition works.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'a proposition is a statement or assertion that expresses a judgment or an opinion for example i may state fire burns or fire is bright that statement is then tested against observation and from that observation i judge whether it is true or false this is how a proposition works', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 31, NULL, 'Scholars divide propositions into three kinds:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'scholars divide propositions into three kinds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 32, NULL, 'Empirical propositions Rational propositions Philosophical or revelatory propositions', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'empirical propositions rational propositions philosophical or revelatory propositions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 34, NULL, 'The first kind is empirical propositions. These rest on observation or experience through the five senses: sight, hearing, smell, taste, and touch. They are also called sensory propositions. They belong to the realm that can be witnessed, which the Quran calls عَالَمُ الشَّھَادَۃِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the first kind is empirical propositions these rest on observation or experience through the five senses sight hearing smell taste and touch they are also called sensory propositions they belong to the realm that can be witnessed which the quran calls عالم الشهاده', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 35, NULL, 'So when I say that fire is hot, that it is bright, or that combustion takes place when it combines with oxygen, I am making empirical or sensory propositions. Their truth can be observed through the five senses.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'so when i say that fire is hot that it is bright or that combustion takes place when it combines with oxygen i am making empirical or sensory propositions their truth can be observed through the five senses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 37, NULL, 'The second kind is the rational proposition. It is a logical proposition, such as: 3 + 2 equals 5; therefore, 5 - 3 must equal 2. This kind of proposition works through inference.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the second kind is the rational proposition it is a logical proposition such as 3 2 equals 5 therefore 5 3 must equal 2 this kind of proposition works through inference', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 38, NULL, 'If I see smoke rising in the distance, I can infer that there is a fire there, even though I cannot see the fire itself. That inference rests on earlier empirical knowledge: when something burns, it gives off smoke. From that known fact, I can reason that a fire must be present.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'if i see smoke rising in the distance i can infer that there is a fire there even though i cannot see the fire itself that inference rests on earlier empirical knowledge when something burns it gives off smoke from that known fact i can reason that a fire must be present', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 39, NULL, 'Yet if smoke is the only evidence I consider, my inference may be wrong. The smoke might be coming from a large group of people having a cigar party. To preserve the rational proposition that there is a fire, I need more empirical evidence. If I walk toward the smoke and see the area becoming brighter and feel the air becoming warmer, then the likelihood of my rational proposition increases. I now have more sensory data, in the form of light and heat, supporting the claim that there is a fire.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'yet if smoke is the only evidence i consider my inference may be wrong the smoke might be coming from a large group of people having a cigar party to preserve the rational proposition that there is a fire i need more empirical evidence if i walk toward the smoke and see the area becoming brighter and feel the air becoming warmer then the likelihood of my rational proposition increases i now have more sensory data in the form of light and heat supporting the claim that there is a fire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 40, NULL, 'In other words, the more empirical evidence I have, the stronger the rational proposition becomes.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'in other words the more empirical evidence i have the stronger the rational proposition becomes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 41, NULL, 'That is how Sherlock Holmes works. He uses empirical data to deduce rational propositions.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'that is how sherlock holmes works he uses empirical data to deduce rational propositions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 43, NULL, 'I now turn to the third type of proposition: the philosophical or revelatory proposition. These are the Quranic propositions that speak about عَالَمُ الْغَیْبِ, the Unseen Realm. They speak of the existence of a Creator, angels, divine books, messengers, the Day of Judgment, heaven, and hell.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i now turn to the third type of proposition the philosophical or revelatory proposition these are the quranic propositions that speak about عالم الغيب the unseen realm they speak of the existence of a creator angels divine books messengers the day of judgment heaven and hell', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 44, NULL, 'This is, in broad terms, what the Quran does. It gives philosophical or revelatory propositions. It sets before me the reality of the afterlife, the Day of Judgment, heaven, and hell. These are the realities in which I place my faith. My ایمان rests on these revelatory propositions.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'this is in broad terms what the quran does it gives philosophical or revelatory propositions it sets before me the reality of the afterlife the day of judgment heaven and hell these are the realities in which i place my faith my ايمان rests on these revelatory propositions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 45, NULL, 'The question is how I arrive there. How can I believe in propositions that are wholly unseen and metaphysical? The clearest way to disclose the hidden realm to intelligent human beings is to fashion the physical universe on the same principles as the spiritual universe. Then everything in the physical universe points back to the workings of the spiritual universe.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the question is how i arrive there how can i believe in propositions that are wholly unseen and metaphysical the clearest way to disclose the hidden realm to intelligent human beings is to fashion the physical universe on the same principles as the spiritual universe then everything in the physical universe points back to the workings of the spiritual universe', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 46, NULL, 'An object that points toward a destination is called a sign. So Allah says:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'an object that points toward a destination is called a sign so allah says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 47, NULL, 'Fussilat: 53سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ', '', 'سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ', 'Fussilat: 53', 41, 53, 'surah al fateha the divine formula for recognizing allah', 'fussilat 53سنريهم ايتنا في الافاق وفي انفسهم', 'سنريهم ايتنا في الافاق وفي انفسهم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 48, NULL, 'He will show them His signs, His evidence. Where? فِى ٱلأٓفَاقِ, in the horizons. What appears in the horizons is empirical evidence. Everything outside me exists as observable data. The physical things around me are things I can see, hear, touch, taste, and smell. وَفِىٓ أَنفُسِهِمْ And within their own selves. As rational human beings, I can deduce and infer rational propositions from empirical data. Therefore:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'he will show them his signs his evidence where في الافاق in the horizons what appears in the horizons is empirical evidence everything outside me exists as observable data the physical things around me are things i can see hear touch taste and smell وفي انفسهم and within their own selves as rational human beings i can deduce and infer rational propositions from empirical data therefore', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 49, NULL, 'Sayingسَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ -', '', 'سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ -', 'Saying', 41, 53, 'surah al fateha the divine formula for recognizing allah', 'sayingسنريهم ايتنا في الافاق وفي انفسهم', 'سنريهم ايتنا في الافاق وفي انفسهم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 50, NULL, 'He will show them the evidence of the unseen realm through the empirical and rational data of this universe. How much evidence?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'he will show them the evidence of the unseen realm through the empirical and rational data of this universe how much evidence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 51, NULL, 'Fussilat: 53حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ', '', 'حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ', 'Fussilat: 53', 41, 53, 'surah al fateha the divine formula for recognizing allah', 'fussilat 53حتي يتبين لهم انه الحق', 'حتي يتبين لهم انه الحق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 52, NULL, 'Unlimited evidence, until it becomes absolutely clear to them that these revelatory propositions are true.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'unlimited evidence until it becomes absolutely clear to them that these revelatory propositions are true', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 53, NULL, 'For example, the Quran tells me that Allah is the creator of this universe. The fact that the universe is a created thing is supported by rational and empirical observation. I know that there was a time in the past when this universe did not exist. I also know that a time will come in the future when it will return to non-existence. Existence and non-existence are both attributes of creation. Therefore, by reason, this universe is a creation.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'for example the quran tells me that allah is the creator of this universe the fact that the universe is a created thing is supported by rational and empirical observation i know that there was a time in the past when this universe did not exist i also know that a time will come in the future when it will return to non existence existence and non existence are both attributes of creation therefore by reason this universe is a creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 54, NULL, 'Empirical data also confirm that every creation requires a creator. If this universe is a creation, it must have a creator. So when the Quran proposes:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'empirical data also confirm that every creation requires a creator if this universe is a creation it must have a creator so when the quran proposes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 55, NULL, 'Sayingاللہ الذی خلق السماوت و الارض', '', 'اللہ الذی خلق السماوت و الارض', 'Saying', NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'sayingالله الذي خلق السماوت و الارض', 'الله الذي خلق السماوت و الارض');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 56, NULL, 'Allah is the one who created the heavens and the earth. That revelatory proposition is then backed and supported by rational and empirical evidence in the horizons, evidence that the human mind can understand and process.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'allah is the one who created the heavens and the earth that revelatory proposition is then backed and supported by rational and empirical evidence in the horizons evidence that the human mind can understand and process', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 57, NULL, 'Once I can believe this particular proposition rationally, it becomes easier to believe Allah when He says that He also created a spiritual universe. Logically, the One who has the power to create this physical universe must also have the power to create the spiritual universe.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'once i can believe this particular proposition rationally it becomes easier to believe allah when he says that he also created a spiritual universe logically the one who has the power to create this physical universe must also have the power to create the spiritual universe', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 58, NULL, 'When I understand this phenomenon, I can appreciate the motive of the Quran. This is why, throughout the Quran, Allah asks me to reflect on the creations of the heavens and the earth. He never asks me to reflect on Allah Himself, because that would be impossible without the empirical and rational data of this physical world. That is why He says:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'when i understand this phenomenon i can appreciate the motive of the quran this is why throughout the quran allah asks me to reflect on the creations of the heavens and the earth he never asks me to reflect on allah himself because that would be impossible without the empirical and rational data of this physical world that is why he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 59, NULL, 'Ali ''Imran: 190إِنَّ فِى خَلْقِ ٱلسَّمَوَتِ وَٱلْأَرْضِ وَٱخْتِلَفِ ٱلَّيْلِ وَٱلنَّهَارِ لَآيَتٍۢ لِّأُو۟لِى ٱلْأَلْبَبِ', '', 'إِنَّ فِى خَلْقِ ٱلسَّمَوَتِ وَٱلْأَرْضِ وَٱخْتِلَفِ ٱلَّيْلِ وَٱلنَّهَارِ لَآيَتٍۢ لِّأُو۟لِى ٱلْأَلْبَبِ', 'Ali ''Imran: 190', 3, 190, 'surah al fateha the divine formula for recognizing allah', 'ali imran 190ان في خلق السموت والارض واختلف اليل والنهار لايت لاولي الالبب', 'ان في خلق السموت والارض واختلف اليل والنهار لايت لاولي الالبب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 60, NULL, 'Without doubt, in the creation of the heavens and the earth, and in the alternation of night and day, there are signs for people of intellect.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'without doubt in the creation of the heavens and the earth and in the alternation of night and day there are signs for people of intellect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 61, NULL, 'The word لُب carries a subtle meaning here. It points to the pith or seed, something hidden beneath the earth. In the same way, my intellect becomes the means by which I understand what is unseen through what is seen. From the plant before me, I can infer the hidden seed and the hidden roots. I do not need to uproot the plant and dig into the soil before I can reach the rational conclusion that roots must exist.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the word لب carries a subtle meaning here it points to the pith or seed something hidden beneath the earth in the same way my intellect becomes the means by which i understand what is unseen through what is seen from the plant before me i can infer the hidden seed and the hidden roots i do not need to uproot the plant and dig into the soil before i can reach the rational conclusion that roots must exist', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 62, NULL, 'This is why Allah calls me to reflect on His creations: so that I may gather the empirical and rational evidence He has placed before my intellect. That evidence makes it easier to accept the truth disclosed by revelation.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'this is why allah calls me to reflect on his creations so that i may gather the empirical and rational evidence he has placed before my intellect that evidence makes it easier to accept the truth disclosed by revelation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 63, NULL, 'This is why Maulana Ali taught:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'this is why maulana ali taught', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 64, NULL, 'Sayingلَا تَفَکَّرْ فِی اللہِ ..... وَلَاکِنْ تَفَکَّرْ فِی خَلْقِ اللَّہِ', '', 'لَا تَفَکَّرْ فِی اللہِ ..... وَلَاکِنْ تَفَکَّرْ فِی خَلْقِ اللَّہِ', 'Saying', NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'sayingلا تفكر في الله ولاكن تفكر في خلق الله', 'لا تفكر في الله ولاكن تفكر في خلق الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 65, NULL, 'Do not reflect upon Allah; instead, reflect upon the “creations” of Allah. In witnessing this universe lies the evidence for what exists beyond it. The more I reflect on this physical creation, the more it answers my questions about the spiritual creation, and especially about its creator.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'do not reflect upon allah instead reflect upon the creations of allah in witnessing this universe lies the evidence for what exists beyond it the more i reflect on this physical creation the more it answers my questions about the spiritual creation and especially about its creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 66, NULL, 'So the Quran proposes:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'so the quran proposes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 67, NULL, 'An-Naml: 9أَنَا اللَّـهُ الْعَزِيزُ الْحَكِيمُ', '', 'أَنَا اللَّـهُ الْعَزِيزُ الْحَكِيمُ', 'An-Naml: 9', 27, 9, 'surah al fateha the divine formula for recognizing allah', 'an naml 9انا الله العزيز الحكيم', 'انا الله العزيز الحكيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 68, NULL, 'Indeed I am Allah: the One whose power is complete and whose wisdom is perfect. The universe offers empirical and rational evidence for this claim. Its study shows that it could only have been created by One of immense power and immense wisdom, because every created thing exists with purpose. Human creation, therefore, must also have a purpose.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'indeed i am allah the one whose power is complete and whose wisdom is perfect the universe offers empirical and rational evidence for this claim its study shows that it could only have been created by one of immense power and immense wisdom because every created thing exists with purpose human creation therefore must also have a purpose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 69, NULL, 'The Quran proposes:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the quran proposes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 70, NULL, 'Sayingٱلرَّحْمَنُ ‎۱‏عَلَّمَ ٱلْقُرْآنَ ‎۲‏خَلَقَ ٱلْإِنسَنَ ‎۳‏عَلَّمَهُ ٱلْبَيَانَ', '', 'ٱلرَّحْمَنُ ‎ ۱‏ عَلَّمَ ٱلْقُرْآنَ ‎ ۲‏ خَلَقَ ٱلْإِنسَنَ ‎ ۳‏ عَلَّمَهُ ٱلْبَيَانَ', 'Saying', NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'sayingالرحمن ۱ علم القران ۲ خلق الانسن ۳ علمه البيان', 'الرحمن ۱ علم القران ۲ خلق الانسن ۳ علمه البيان');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 71, NULL, 'The Intensely Merciful taught the Quran, created man, and taught him speech. A careful study of these three acts shows what they disclose:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the intensely merciful taught the quran created man and taught him speech a careful study of these three acts shows what they disclose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 72, NULL, 'the teaching of the Quran, the creation of mankind, the granting of speech.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the teaching of the quran the creation of mankind the granting of speech', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 73, NULL, 'Together, they clearly prove that this could only be the act of a ٱلرَّحْمَنُ. The Quran proposes:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'together they clearly prove that this could only be the act of a الرحمن the quran proposes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 74, NULL, 'Al-Baqarah: 255اللَّهُ لا إِلَهَ إِلا هُوَ الْحَيُّ الْقَيُّومُ', '', 'اللَّهُ لا إِلَهَ إِلا هُوَ الْحَيُّ الْقَيُّومُ', 'Al-Baqarah: 255', 2, 255, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 255الله لا اله الا هو الحي القيوم', 'الله لا اله الا هو الحي القيوم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 75, NULL, 'Allah is the One besides whom there is no deity worthy of worship. He is the Eternally Living and the ultimate maintainer of all things. Empirical and rational evidence shows that life is necessary for maintenance. All life on this earth is temporary; every created being will inevitably die. Whoever dies cannot remain the maintainer, sustainer, or provider for those who depend on him. Therefore, only the Ever-Living can be the ultimate maintainer and sustainer. This supports the next revelatory proposition:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'allah is the one besides whom there is no deity worthy of worship he is the eternally living and the ultimate maintainer of all things empirical and rational evidence shows that life is necessary for maintenance all life on this earth is temporary every created being will inevitably die whoever dies cannot remain the maintainer sustainer or provider for those who depend on him therefore only the ever living can be the ultimate maintainer and sustainer this supports the next revelatory proposition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 76, NULL, 'Al-Baqarah: 255لا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ', '', 'لا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ', 'Al-Baqarah: 255', 2, 255, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 255لا تاخذه سنه ولا نوم', 'لا تاخذه سنه ولا نوم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 77, NULL, 'He is never overcome by drowsiness, and He never sleeps. I know that drowsiness weakens mental ability and focus, while sleep removes them altogether for a time. A person who is drowsy, unconscious, or asleep cannot be all-mighty, nor can he be the ultimate maintainer and sustainer. Constant maintenance requires complete attention and vigilance.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'he is never overcome by drowsiness and he never sleeps i know that drowsiness weakens mental ability and focus while sleep removes them altogether for a time a person who is drowsy unconscious or asleep cannot be all mighty nor can he be the ultimate maintainer and sustainer constant maintenance requires complete attention and vigilance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 78, NULL, 'The remaining propositions unfold from this:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the remaining propositions unfold from this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 79, NULL, 'Al-Baqarah: 255لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ', '', 'لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الأَرْضِ', 'Al-Baqarah: 255', 2, 255, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 255له ما في السماوات وما في الارض', 'له ما في السماوات وما في الارض');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 80, NULL, 'Everything in the heavens and the earth belongs to Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'everything in the heavens and the earth belongs to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 81, NULL, 'Al-Baqarah: 255مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلا بِإِذْنِهِ', '', 'مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلا بِإِذْنِهِ', 'Al-Baqarah: 255', 2, 255, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 255من ذا الذي يشفع عنده الا باذنه', 'من ذا الذي يشفع عنده الا باذنه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 82, NULL, 'Who can intercede on anyone''s behalf without His permission?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'who can intercede on anyones behalf without his permission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 83, NULL, 'Al-Baqarah: 255يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلا بِمَا شَاءَ', '', 'يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلا بِمَا شَاءَ', 'Al-Baqarah: 255', 2, 255, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 255يعلم ما بين ايديهم وما خلفهم ولا يحيطون بشيء من علمه الا بما شاء', 'يعلم ما بين ايديهم وما خلفهم ولا يحيطون بشيء من علمه الا بما شاء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 84, NULL, 'He knows fully what lies ahead and what has already come to pass. No one shares in that knowledge except those whom He chooses to grant a share of it.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'he knows fully what lies ahead and what has already come to pass no one shares in that knowledge except those whom he chooses to grant a share of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 85, NULL, 'Sayingوَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالأَرْضَ وَلا يَئُودُهُ حِفْظُهُمَا', '', 'وَسِعَ كُرْسِيُّهُ السَّمَاوَاتِ وَالأَرْضَ وَلا يَئُودُهُ حِفْظُهُمَا', 'Saying', NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'sayingوسع كرسيه السماوات والارض ولا ييوده حفظهما', 'وسع كرسيه السماوات والارض ولا ييوده حفظهما');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 86, NULL, 'His throne extends over the heavens and the earth. He maintains control over the universe, and that maintenance neither tires Him nor wearies Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'his throne extends over the heavens and the earth he maintains control over the universe and that maintenance neither tires him nor wearies him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 87, NULL, 'Al-Baqarah: 255وَهُوَ الْعَلِيُّ الْعَظِيمُ', '', 'وَهُوَ الْعَلِيُّ الْعَظِيمُ', 'Al-Baqarah: 255', 2, 255, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 255وهو العلي العظيم', 'وهو العلي العظيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 88, NULL, 'I recognize Him as the All-Mighty and the All-Exalted.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i recognize him as the all mighty and the all exalted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 89, NULL, 'When I study these revealed statements alongside the evidence that the universe itself gives through observation and reason, the first statement becomes easy to affirm: اللَّهُ لا إِلَهَ إِلا هُوَ Allah alone is the deity worthy of my worship. No created thing in this universe, living or lifeless, bears that exalted description. If I am to choose any being for worship, reason itself points me to Allah alone.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'when i study these revealed statements alongside the evidence that the universe itself gives through observation and reason the first statement becomes easy to affirm الله لا اله الا هو allah alone is the deity worthy of my worship no created thing in this universe living or lifeless bears that exalted description if i am to choose any being for worship reason itself points me to allah alone', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 90, NULL, 'This is the first part of the formula: the design of the horizons, the آفاق. The horizons give observable and rational evidence for the revealed propositions of the Quran. Through them, I am given a path toward knowing my Creator and recognizing the magnificent powers He possesses, because the effects of His divine attributes appear throughout His creation. This is the story of the Martian and the iPad from the discussion on Conclusions of Reflection.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'this is the first part of the formula the design of the horizons the افاق the horizons give observable and rational evidence for the revealed propositions of the quran through them i am given a path toward knowing my creator and recognizing the magnificent powers he possesses because the effects of his divine attributes appear throughout his creation this is the story of the martian and the ipad from the discussion on conclusions of reflection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 92, NULL, 'The second part of the formula is the أنفس, the soul or the self. The soul answers a different question: what Allah wants from us. That becomes clear when I return to the moment when Allah سُبْحَانَهُ وَتَعَالَى decided to create the first soul, Adam AS. How did He describe His intention to the angels? He said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the second part of the formula is the انفس the soul or the self the soul answers a different question what allah wants from us that becomes clear when i return to the moment when allah سبحانه وتعالي decided to create the first soul adam as how did he describe his intention to the angels he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 93, NULL, 'Al-Baqarah: 30وَإِذْ قَالَ رَبُّكَ لِلْمَلَٓئِكَةِ إِنِّى جَاعِلٌۭ فِى ٱلْأَرْضِ خَلِيفَةًۭ ۖ قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَAnd when your Lord said to the angels: "Verily, I am going to place generations after generations on earth." They said: "Will You place therein those who will make mischief therein and shed blood, - while we glorify You with praises and thanks and sanctify You." He said: "I know that which you do not know."', '', NULL, 'Al-Baqarah: 30', NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 30واذ قال ربك للمليكه اني جاعل في الارض خليفه قالوا اتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك قال اني اعلم ما لا تعلمونand when your lord said to the angels verily i am going to place generations after generations on earth they said will you place therein those who will make mischief therein and shed blood while we glorify you with praises and thanks and sanctify you he said i know that which you do not know', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 94, NULL, 'I begin with His words to the angels: “I am going to create my caliph, my خلیفۃ, on this earth.” I understand this word, خلیفۃ, through its root. The word خلیفۃ comes from خَلَفَ, which means “back” or “behind.” Its opposite is سَلَفَ, which means “the front” or “what lies ahead.” So خلف means the one who comes behind, the one who follows, or the one who succeeds another. In this sense, خلیفۃ means “representative.” Allah said to the angels, “I am planning to create my representative on earth.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i begin with his words to the angels i am going to create my caliph my خليفه on this earth i understand this word خليفه through its root the word خليفه comes from خلف which means back or behind its opposite is سلف which means the front or what lies ahead so خلف means the one who comes behind the one who follows or the one who succeeds another in this sense خليفه means representative allah said to the angels i am planning to create my representative on earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 95, NULL, 'Caliph', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'caliph', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 96, NULL, 'A representative is someone chosen or appointed to act or speak on behalf of another. If I were to choose someone to represent me accurately, I would look for someone who shared my traits, or at least carried traits close enough to mine to make true representation possible. Without that likeness, the person could not represent me or convey my thoughts faithfully.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'a representative is someone chosen or appointed to act or speak on behalf of another if i were to choose someone to represent me accurately i would look for someone who shared my traits or at least carried traits close enough to mine to make true representation possible without that likeness the person could not represent me or convey my thoughts faithfully', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 97, NULL, 'For this reason, in the story of Adam''s creation, Allah did not only create Adam AS. He also taught him all His traits.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'for this reason in the story of adams creation allah did not only create adam as he also taught him all his traits', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 98, NULL, 'Al-Baqarah: 31وَعَلَّمَ آدَمَ ٱلْأَسْمَآءَ كُلَّهَا ثُمَّ عَرَضَهُمْ عَلَى ٱلْمَلَٓئِكَةِ فَقَالَ أَنۢبِـُٔونِى بِأَسْمَآءِ هَٓؤُلَآءِ إِن كُنتُمْ صَدِقِينَAnd He taught Adam all the names , then He showed them to the angels and said, "Tell Me the names of these if you are truthful."', '', NULL, 'Al-Baqarah: 31', NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 31وعلم ادم الاسماء كلها ثم عرضهم علي المليكه فقال انبوني باسماء هولاء ان كنتم صدقينand he taught adam all the names then he showed them to the angels and said tell me the names of these if you are truthful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 99, NULL, 'He taught Adam all the names. He taught Adam all the divine traits. In other words, He trained Adam AS in the divine traits that Allah Himself possessed. Then He presented Adam AS to the angels and challenged them through those traits. What did the angels say?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'he taught adam all the names he taught adam all the divine traits in other words he trained adam as in the divine traits that allah himself possessed then he presented adam as to the angels and challenged them through those traits what did the angels say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 100, NULL, 'Al-Baqarah: 32قَالُوا۟ سُبْحَنَكَ لَا عِلْمَ لَنَآ إِلَّا مَا عَلَّمْتَنَآ ۖ إِنَّكَ أَنتَ ٱلْعَلِيمُ ٱلْحَكِيمُThe angels said: "May You be glorified. We know nothing except what You have taught us. We have not received the training Adam AS received. Therefore, we admit that we cannot be Your true representatives on earth."', '', NULL, 'Al-Baqarah: 32', NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 32قالوا سبحنك لا علم لنا الا ما علمتنا انك انت العليم الحكيمthe angels said may you be glorified we know nothing except what you have taught us we have not received the training adam as received therefore we admit that we cannot be your true representatives on earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 101, NULL, 'That had been their original argument.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'that had been their original argument', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 102, NULL, 'Al-Baqarah: 30وَإِذْ قَالَ رَبُّكَ لِلْمَلَٓئِكَةِ إِنِّى جَاعِلٌۭ فِى ٱلْأَرْضِ خَلِيفَةًۭ ۖ قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ', '', 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٓئِكَةِ إِنِّى جَاعِلٌۭ فِى ٱلْأَرْضِ خَلِيفَةًۭ ۖ قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ وَنَحْنُ نُسَبِّحُ بِحَمْدِكَ وَنُقَدِّسُ لَكَ ۖ قَالَ إِنِّىٓ أَعْلَمُ مَا لَا تَعْلَمُونَ', 'Al-Baqarah: 30', 2, 30, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 30واذ قال ربك للمليكه اني جاعل في الارض خليفه قالوا اتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك قال اني اعلم ما لا تعلمون', 'واذ قال ربك للمليكه اني جاعل في الارض خليفه قالوا اتجعل فيها من يفسد فيها ويسفك الدماء ونحن نسبح بحمدك ونقدس لك قال اني اعلم ما لا تعلمون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 103, NULL, 'I understand the angels'' question as an objection to Adam''s fitness for this trust: will this representative spill blood and wreak havoc, while they themselves are constantly praising and glorifying Allah? They saw themselves as able to represent Him on earth. They could be His true خلیفۃ, and so the need for Adam was not yet clear to them.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i understand the angels question as an objection to adams fitness for this trust will this representative spill blood and wreak havoc while they themselves are constantly praising and glorifying allah they saw themselves as able to represent him on earth they could be his true خليفه and so the need for adam was not yet clear to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 104, NULL, 'But when Allah created Adam and trained him to reflect the divine attributes in his character, they all accepted what had been shown to them. In that sense, they validated and confirmed that Adam, and through him mankind, alone possesses the true capacity to represent Allah سُبْحَانَهُ وَتَعَالَى on the earth.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'but when allah created adam and trained him to reflect the divine attributes in his character they all accepted what had been shown to them in that sense they validated and confirmed that adam and through him mankind alone possesses the true capacity to represent allah سبحانه وتعالي on the earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 105, NULL, 'This is the meaning of Allah creating man in his own image. We possess the attributes that our creator and master possesses. I know that Allah sees. He sees our actions and our deeds:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'this is the meaning of allah creating man in his own image we possess the attributes that our creator and master possesses i know that allah sees he sees our actions and our deeds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 106, NULL, 'Al-Baqarah: 265وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۭ', '', 'وَٱللَّهُ بِمَا تَعْمَلُونَ بَصِيرٌۭ', 'Al-Baqarah: 265', 2, 265, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 265والله بما تعملون بصير', 'والله بما تعملون بصير');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 107, NULL, 'I know that Allah hears:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i know that allah hears', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 108, NULL, 'Al-Baqarah: 137وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', '', 'وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ', 'Al-Baqarah: 137', 2, 137, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 137وهو السميع العليم', 'وهو السميع العليم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 109, NULL, 'For this reason, he gave us the ability to hear, so that we could represent his qualities accurately on this earth. More than that, he gave us hearing so that we could understand what it means when he says that he watches our actions and hears our cries and supplications.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'for this reason he gave us the ability to hear so that we could represent his qualities accurately on this earth more than that he gave us hearing so that we could understand what it means when he says that he watches our actions and hears our cries and supplications', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 110, NULL, 'I know that Allah acts, because we have the ability to act:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i know that allah acts because we have the ability to act', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 111, NULL, 'Ar-Rahman: 29كُلَّ يَوْمٍ هُوَ فِى شَأْنٍۢ', '', 'كُلَّ يَوْمٍ هُوَ فِى شَأْنٍۢ', 'Ar-Rahman: 29', 55, 29, 'surah al fateha the divine formula for recognizing allah', 'ar rahman 29كل يوم هو في شان', 'كل يوم هو في شان');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 112, NULL, 'Every single day, he is busy in work. I know that Allah has the ability to love, because the Quran says that he loves everything good, clean, and pure:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'every single day he is busy in work i know that allah has the ability to love because the quran says that he loves everything good clean and pure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 113, NULL, 'Al-Baqarah: 222إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ', '', 'إِنَّ ٱللَّهَ يُحِبُّ ٱلتَّوَّبِينَ وَيُحِبُّ ٱلْمُتَطَهِّرِينَ', 'Al-Baqarah: 222', 2, 222, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 222ان الله يحب التوبين ويحب المتطهرين', 'ان الله يحب التوبين ويحب المتطهرين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 114, NULL, 'For this reason, he gave us the ability to love. That is why it belongs to our فطرۃ, our natural predisposition, to love what is clean and pure: because that is what our creator loves.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'for this reason he gave us the ability to love that is why it belongs to our فطره our natural predisposition to love what is clean and pure because that is what our creator loves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 115, NULL, 'Similarly, I also know that Allah has the ability to hate and dislike.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'similarly i also know that allah has the ability to hate and dislike', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 116, NULL, 'Al-Baqarah: 205وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ', '', 'وَٱللَّهُ لَا يُحِبُّ ٱلْفَسَادَ', 'Al-Baqarah: 205', 2, 205, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 205والله لا يحب الفساد', 'والله لا يحب الفساد');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 117, NULL, 'I know that Allah hates and dislikes corruption. لَا وَٱللَّهُ يُحِبُّ. For that reason, he placed in our innate nature a dislike for filth and foulness. We recoil from what is dirty because corruption is hateful to him.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i know that allah hates and dislikes corruption لا والله يحب for that reason he placed in our innate nature a dislike for filth and foulness we recoil from what is dirty because corruption is hateful to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 118, NULL, 'This is because we have been created in God''s image. We have been created with the same divine attributes that Allah possesses, in a created and limited way, so that we may serve as his true representatives, his true خلیفۃ, on this earth. Through these qualities, I come to know and understand my creator.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'this is because we have been created in gods image we have been created with the same divine attributes that allah possesses in a created and limited way so that we may serve as his true representatives his true خليفه on this earth through these qualities i come to know and understand my creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 119, NULL, 'The way is simple: I look into my own self.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the way is simple i look into my own self', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 120, NULL, 'Adh-Dhariyat: 21وَفِىٓ أَنفُسِكُمْ ۚ أَفَلَا تُبْصِرُونَ', '', 'وَفِىٓ أَنفُسِكُمْ ۚ أَفَلَا تُبْصِرُونَ', 'Adh-Dhariyat: 21', 51, 21, 'surah al fateha the divine formula for recognizing allah', 'adh dhariyat 21وفي انفسكم افلا تبصرون', 'وفي انفسكم افلا تبصرون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 121, NULL, 'The verse calls the human being back to reflection on the self. What I seek for myself points toward what Allah wants from me. SubhanAllah. I want justice; Allah wants justice. I want to be loved; Allah wants me to love him. I like to be praised; Allah likes to be praised. I appreciate gratitude; Allah likes his creation to be grateful to him. I feel anger when people violate what belongs to me or ignore my rules; Allah is angered when his possessions and his rules are violated. I want others to give me due priority in their lives; Allah wants me to make him the priority in mine.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the verse calls the human being back to reflection on the self what i seek for myself points toward what allah wants from me subhanallah i want justice allah wants justice i want to be loved allah wants me to love him i like to be praised allah likes to be praised i appreciate gratitude allah likes his creation to be grateful to him i feel anger when people violate what belongs to me or ignore my rules allah is angered when his possessions and his rules are violated i want others to give me due priority in their lives allah wants me to make him the priority in mine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 122, NULL, 'I can read the whole Quran from cover to cover and find no demand Allah makes of me that I would not, in some form, expect from someone else. If I want to know what Allah wants from me, I need only reflect on my own self. What do I want for myself from others? That reveals the matter.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i can read the whole quran from cover to cover and find no demand allah makes of me that i would not in some form expect from someone else if i want to know what allah wants from me i need only reflect on my own self what do i want for myself from others that reveals the matter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 123, NULL, 'I want kind treatment, and Allah wants kind treatment. I want to be treated as though I matter, and Allah wants me to treat Him as though He matters. I want credit for what I make, and Allah wants credit for what He made: for creating me, and for creating this universe for me. SubhanAllah!', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i want kind treatment and allah wants kind treatment i want to be treated as though i matter and allah wants me to treat him as though he matters i want credit for what i make and allah wants credit for what he made for creating me and for creating this universe for me subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 124, NULL, 'The question of who created the universe returns first to the self. I was created in His image. I was created with abilities that reflect, in a creaturely way, abilities Allah possesses. He is خالق. He is the Creator, and He gave me the ability to create and construct. He made me خالق. Even a needle cannot exist in my world unless someone makes it. How, then, can a human being created in His image think that this universe came into existence without a creator?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the question of who created the universe returns first to the self i was created in his image i was created with abilities that reflect in a creaturely way abilities allah possesses he is خالق he is the creator and he gave me the ability to create and construct he made me خالق even a needle cannot exist in my world unless someone makes it how then can a human being created in his image think that this universe came into existence without a creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 125, NULL, 'I hear complaints about the state of this world. I hear the question of why I do not do something about it. I already did: I created the human being. I created the human being in My own image. I gave the human being My powers.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i hear complaints about the state of this world i hear the question of why i do not do something about it i already did i created the human being i created the human being in my own image i gave the human being my powers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 126, NULL, 'The answer, then, turns back upon the one who complains. Poverty and misery are not only matters to lament. I gave wealth so that it could be spent to make life better and easier for others. Injustice is not only a subject to speak about. I gave courage so that injustices could be corrected. Blind people are not only to be seen; a person can become their sight. Weak people are not only to be pitied; a person can become their strength.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the answer then turns back upon the one who complains poverty and misery are not only matters to lament i gave wealth so that it could be spent to make life better and easier for others injustice is not only a subject to speak about i gave courage so that injustices could be corrected blind people are not only to be seen a person can become their sight weak people are not only to be pitied a person can become their strength', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 127, NULL, 'I gave everything needed to repair the conditions of this world. Yet human beings often do not want to leave their comfort zones. They want only to complain and to have others solve their problems for them. That is not how it will work, because I created them as gods. I created them as الہ. Each and every one of them has been created with the capabilities of an الہ, so that they can recognize and identify the ال الہ, and so that they can understand what their اللہ wants from them. SubhanAllah.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i gave everything needed to repair the conditions of this world yet human beings often do not want to leave their comfort zones they want only to complain and to have others solve their problems for them that is not how it will work because i created them as gods i created them as اله each and every one of them has been created with the capabilities of an اله so that they can recognize and identify the ال اله and so that they can understand what their الله wants from them subhanallah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 128, NULL, 'If the question is what I want from the human being, the answer lies within the self. By studying one''s own capabilities and desires, a person comes to know what I want.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'if the question is what i want from the human being the answer lies within the self by studying ones own capabilities and desires a person comes to know what i want', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 129, NULL, 'Sayingمَنْ عَرَفَ نَفْسَہُ فَقَدْ عَرَفَ رَبَّہُ', '', 'مَنْ عَرَفَ نَفْسَہُ فَقَدْ عَرَفَ رَبَّہُ', 'Saying', NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'sayingمن عرف نفسه فقد عرف ربه', 'من عرف نفسه فقد عرف ربه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 130, NULL, 'The one who comes to know his own self comes to know his master, because the slave has been created in the image of his master.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the one who comes to know his own self comes to know his master because the slave has been created in the image of his master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 132, NULL, 'This opens a wide field of reflection. The matter is too large for me to cover within these sessions, and each soul must reflect on it and seek the answers that belong to its own condition. One example, however, belongs here: the question of rights, حقوق.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'this opens a wide field of reflection the matter is too large for me to cover within these sessions and each soul must reflect on it and seek the answers that belong to its own condition one example however belongs here the question of rights حقوق', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 133, NULL, 'Human beings have rights. They are entitled to basic rights. From what has already been established, I must also recognize that Allah has rights. Just as there are human rights, there are divine rights. Human rights rest on divine rights; divine rights do not rest on human rights. If human rights carry weight, then divine rights carry far greater weight.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'human beings have rights they are entitled to basic rights from what has already been established i must also recognize that allah has rights just as there are human rights there are divine rights human rights rest on divine rights divine rights do not rest on human rights if human rights carry weight then divine rights carry far greater weight', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 134, NULL, 'Among human rights is the right to be treated with honor. After all that a parent does for her child, and after all that a mother endures to bring her child into this world, she gains a right of gratitude over that child. After the hard work a sincere and dedicated teacher gives to her students, she gains a right of gratitude over them: a right to respect, dignity, and honor.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'among human rights is the right to be treated with honor after all that a parent does for her child and after all that a mother endures to bring her child into this world she gains a right of gratitude over that child after the hard work a sincere and dedicated teacher gives to her students she gains a right of gratitude over them a right to respect dignity and honor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 135, NULL, 'If created beings can understand and value the rights that human beings hold over one another, then what is the right of the One who created them all from nothing?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'if created beings can understand and value the rights that human beings hold over one another then what is the right of the one who created them all from nothing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 136, NULL, 'Sayingوَاللَّـهُ أَخْرَجَكُم مِّن بُطُونِ أُمَّهَاتِكُمْ لَا تَعْلَمُونَ شَيْئًا', '', 'وَاللَّـهُ أَخْرَجَكُم مِّن بُطُونِ أُمَّهَاتِكُمْ لَا تَعْلَمُونَ شَيْئًا', 'Saying', NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'sayingوالله اخرجكم من بطون امهاتكم لا تعلمون شييا', 'والله اخرجكم من بطون امهاتكم لا تعلمون شييا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 137, NULL, 'What is the right of Allah, who brought the human being out from the wombs of mothers in a state of complete ignorance?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'what is the right of allah who brought the human being out from the wombs of mothers in a state of complete ignorance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 138, NULL, 'Sayingوَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَۙ', '', 'وَجَعَلَ لَكُمُ السَّمْعَ وَالْأَبْصَارَ وَالْأَفْئِدَةَۙ', 'Saying', NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'sayingوجعل لكم السمع والابصار والافيده', 'وجعل لكم السمع والابصار والافيده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 139, NULL, 'What, then, is the right of Allah, who gave the human being hearing, sight, and a beating heart?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'what then is the right of allah who gave the human being hearing sight and a beating heart', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 140, NULL, 'Al-Baqarah: 52لَعَلَّكُمْ تَشْكُرُونَ', '', 'لَعَلَّكُمْ تَشْكُرُونَ', 'Al-Baqarah: 52', 2, 52, 'surah al fateha the divine formula for recognizing allah', 'al baqarah 52لعلكم تشكرون', 'لعلكم تشكرون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 141, NULL, 'So that gratitude might arise.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'so that gratitude might arise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 142, NULL, 'When one human being provides for another, the least expected in return is gratitude. A fair exchange would be the same generosity, or something close to it. If that is not given, gratitude remains the minimum due. What, then, of Allah?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'when one human being provides for another the least expected in return is gratitude a fair exchange would be the same generosity or something close to it if that is not given gratitude remains the minimum due what then of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 143, NULL, 'Sayingلَا نَسْأَلُكَ رِزْقًاۖ نَّحْنُ نَرْزُقُكَۗوَ', '', 'لَا نَسْأَلُكَ رِزْقًاۖ نَّحْنُ نَرْزُقُكَۗوَ', 'Saying', NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'sayingلا نسالك رزقا نحن نرزقكو', 'لا نسالك رزقا نحن نرزقكو');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 144, NULL, 'We do not ask you for provision; indeed, it is We who provide for you. What, then, is the right of gratitude owed to the One who takes nothing and gives everything?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'we do not ask you for provision indeed it is we who provide for you what then is the right of gratitude owed to the one who takes nothing and gives everything', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 145, NULL, 'An-Nahl: 53وَمَا بِكُم مِّن نِّعْمَةٍ فَمِنَ اللَّـهِۖثُمَّ', '', 'وَمَا بِكُم مِّن نِّعْمَةٍ فَمِنَ اللَّـهِۖثُمَّ', 'An-Nahl: 53', 16, 53, 'surah al fateha the divine formula for recognizing allah', 'an nahl 53وما بكم من نعمه فمن اللهثم', 'وما بكم من نعمه فمن اللهثم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 146, NULL, 'Every good thing in a person''s possession has been given by Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'every good thing in a persons possession has been given by allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 147, NULL, 'When human beings make something for a purpose, or invent something for a purpose, they claim the right to require that it be used properly. They expect it to serve the purpose for which it was made. If it is misused, they feel entitled to be upset. They feel entitled to demand justice, and even to bring the offender to court.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'when human beings make something for a purpose or invent something for a purpose they claim the right to require that it be used properly they expect it to serve the purpose for which it was made if it is misused they feel entitled to be upset they feel entitled to demand justice and even to bring the offender to court', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 148, NULL, 'What, then, of the purpose for which Allah created?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'what then of the purpose for which allah created', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 149, NULL, 'Adh-Dhariyat: 56وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ', '', 'وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ', 'Adh-Dhariyat: 56', 51, 56, 'surah al fateha the divine formula for recognizing allah', 'adh dhariyat 56وما خلقت الجن والانس الا ليعبدون', 'وما خلقت الجن والانس الا ليعبدون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 150, NULL, 'I have not created jinn and mankind except to worship Me. How, then, am I fulfilling Allah''s right? Does He not have the right to be displeased and angry when I fail to fulfill those rights?', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i have not created jinn and mankind except to worship me how then am i fulfilling allahs right does he not have the right to be displeased and angry when i fail to fulfill those rights', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 151, NULL, 'I must think deeply about the divine formula that Allah سُبْحَانَهُ وَتَعَالَى has given through this verse:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i must think deeply about the divine formula that allah سبحانه وتعالي has given through this verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 152, NULL, 'Fussilat: 53سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ', '', 'سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ', 'Fussilat: 53', 41, 53, 'surah al fateha the divine formula for recognizing allah', 'fussilat 53سنريهم ايتنا في الافاق وفي انفسهم', 'سنريهم ايتنا في الافاق وفي انفسهم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 153, NULL, 'He will show His signs in the horizons and within the self, so that the human being may come to recognize who Allah is and what He wants from him. May Allah bless us all with the wisdom to fulfill His rights and obligations, and enable us to treat Him with the honor and dignity He deserves.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'he will show his signs in the horizons and within the self so that the human being may come to recognize who allah is and what he wants from him may allah bless us all with the wisdom to fulfill his rights and obligations and enable us to treat him with the honor and dignity he deserves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 154, NULL, 'If anyone in this world treated me the way I treat Allah, I would be deeply offended. I have been created in the image of the One who possesses the ultimate rights. That is all I truly am: an image, a reflection of a distorted version of the divine attributes. I am not real in myself. I am an illusion, like a reflection in a mirror, present for a moment and gone the next. But Allah is real. His rights are real. His obligations are real.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'if anyone in this world treated me the way i treat allah i would be deeply offended i have been created in the image of the one who possesses the ultimate rights that is all i truly am an image a reflection of a distorted version of the divine attributes i am not real in myself i am an illusion like a reflection in a mirror present for a moment and gone the next but allah is real his rights are real his obligations are real', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 155, NULL, 'I will end with a beautiful story I heard recently.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i will end with a beautiful story i heard recently', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 156, NULL, 'A man once heard about a saint known for deep learning. He decided to travel to him and ask for advice. After a long journey, he finally reached the saint, greeted him, and said: I have heard that you are a great scholar and a ولی, a friend of Allah. Please give me some advice!', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'a man once heard about a saint known for deep learning he decided to travel to him and ask for advice after a long journey he finally reached the saint greeted him and said i have heard that you are a great scholar and a ولي a friend of allah please give me some advice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 157, NULL, 'The saint said to him: My advice is this: “If you do not consider Allah your superior, then at least consider Him your equal.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the saint said to him my advice is this if you do not consider allah your superior then at least consider him your equal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 158, NULL, 'When the man heard this advice, he said to himself, “What kind of foolish advice is this? Who would be so foolish as not to consider Allah his equal? Is this what I traveled all this way for? I have wasted my whole journey visiting this so-called saint.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'when the man heard this advice he said to himself what kind of foolish advice is this who would be so foolish as not to consider allah his equal is this what i traveled all this way for i have wasted my whole journey visiting this so called saint', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 159, NULL, 'He was thinking all this, and the saint was reading his thoughts.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'he was thinking all this and the saint was reading his thoughts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 160, NULL, 'The saint said to him: You must be tired after your long journey. Spend the night in this inn, and leave in the morning.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the saint said to him you must be tired after your long journey spend the night in this inn and leave in the morning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 161, NULL, 'The man agreed and spent the night there.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the man agreed and spent the night there', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 162, NULL, 'The next morning, after he woke and offered his morning prayer, a servant came to his door carrying a large tray. On one side of the tray was a fresh breakfast for the man:', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the next morning after he woke and offered his morning prayer a servant came to his door carrying a large tray on one side of the tray was a fresh breakfast for the man', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 163, NULL, '4 eggs 4 pieces of buttered toast 2 pieces of chicken 2 glasses of orange juice', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', '4 eggs 4 pieces of buttered toast 2 pieces of chicken 2 glasses of orange juice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 164, NULL, 'On the other side was yesterday''s food: some stale bread and lentils.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'on the other side was yesterdays food some stale bread and lentils', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 165, NULL, 'Just as the man was about to eat, a beggar came to the door and called out to him. He said, “In the name of your creator I ask you for help.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'just as the man was about to eat a beggar came to the door and called out to him he said in the name of your creator i ask you for help', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 166, NULL, '“I have not eaten for two days! For the love of your master, please give me something to eat.” So the man gave the stale bread and lentils to the beggar, and he ate all the fresh food himself.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i have not eaten for two days for the love of your master please give me something to eat so the man gave the stale bread and lentils to the beggar and he ate all the fresh food himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 167, NULL, 'After breakfast, he prepared to leave and decided to visit the saint so he could bid him farewell. He found the saint and said his goodbyes. Just as he was about to go, the saint says to him: “My son! Remember my advice! If you do not consider Allah your superior, then at least consider Him your equal.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'after breakfast he prepared to leave and decided to visit the saint so he could bid him farewell he found the saint and said his goodbyes just as he was about to go the saint says to him my son remember my advice if you do not consider allah your superior then at least consider him your equal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 168, NULL, 'The man lost his temper and yelled at the saint: “What kind of foolish advice is this? Who in this world would be so senseless as not to consider Allah his superior? Even a child knows something so simple, and you are giving me such absurd advice?”', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the man lost his temper and yelled at the saint what kind of foolish advice is this who in this world would be so senseless as not to consider allah his superior even a child knows something so simple and you are giving me such absurd advice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 169, NULL, 'The saint became furious at the man. He says: “Listen! This morning, when you sat down for breakfast, there was fresh food and stale food on your plate. A beggar came to you and asked you for food in the name of your Creator. He asked you for food for the love of your Master.', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'the saint became furious at the man he says listen this morning when you sat down for breakfast there was fresh food and stale food on your plate a beggar came to you and asked you for food in the name of your creator he asked you for food for the love of your master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 170, NULL, '“Had you considered Allah superior to yourself, you would have eaten the stale bread and lentils and given the fresh food to the beggar. Had you considered Allah your equal, you would have shared your fresh food with him. You would have eaten two eggs and given two eggs to him. You would have eaten two pieces of toast and given two pieces to him. You would have enjoyed one glass of orange juice and let the beggar enjoy the other. O wretched creation! Forget superior; you did not even consider Allah your equal.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'had you considered allah superior to yourself you would have eaten the stale bread and lentils and given the fresh food to the beggar had you considered allah your equal you would have shared your fresh food with him you would have eaten two eggs and given two eggs to him you would have eaten two pieces of toast and given two pieces to him you would have enjoyed one glass of orange juice and let the beggar enjoy the other o wretched creation forget superior you did not even consider allah your equal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the divine formula for recognizing allah', 'The Divine Formula For Recognizing Allah', 171, NULL, 'I end with the same advice to myself: “If we do not consider Allah our superior, then, in view of His rights over us and all His favors upon us, let us at least consider Him our equal.”', '', NULL, NULL, NULL, NULL, 'surah al fateha the divine formula for recognizing allah', 'i end with the same advice to myself if we do not consider allah our superior then in view of his rights over us and all his favors upon us let us at least consider him our equal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 0, NULL, 'I have considered the Quranic formula that gives me an understanding of who our Creator is and what his intentions are. That formula is declared in the verse:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i have considered the quranic formula that gives me an understanding of who our creator is and what his intentions are that formula is declared in the verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 1, NULL, 'Formula', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'formula', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 2, NULL, 'Fussilat: 53سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ ۗ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', '', 'سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ ۗ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', 'Fussilat: 53', 41, 53, 'surah al fateha the horizons and the soul', 'fussilat 53سنريهم ايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق اولم يكف بربك انه علي كل شيء شهيد', 'سنريهم ايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق اولم يكف بربك انه علي كل شيء شهيد');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 3, NULL, 'We will show them Our Signs in the universe, and in their own selves, until it becomes absolutely clear to them that this is the truth.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'we will show them our signs in the universe and in their own selves until it becomes absolutely clear to them that this is the truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 4, NULL, 'The signs in the horizons disclose the nature and power of Allah. The signs within our souls disclose the intentions of Allah, because Allah created us all in his own image, and he demands for himself only what we demand from others as rights.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the signs in the horizons disclose the nature and power of allah the signs within our souls disclose the intentions of allah because allah created us all in his own image and he demands for himself only what we demand from others as rights', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 5, NULL, 'In these analogies between the ظاہر and the باطن — the horizons and the soul — I find insight into the inner workings of دین. Rasul Allah ﷺ said in a HADEES:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'in these analogies between the ظاهر and the باطن the horizons and the soul i find insight into the inner workings of دين rasul allah ﷺ said in a hadees', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 6, NULL, 'Sayingاِنَّا اللہ اَسَّسَ دِینَہُ عَلیَ مِثاَلِ خَلقِہِ لِیَستَدِلَّ بِالدِّینِ عَلَی الدُّنیَا ؛ وَ الدُّنیَا عَلَی الدِّین', '', 'اِنَّا اللہ اَسَّسَ دِینَہُ عَلیَ مِثاَلِ خَلقِہِ لِیَستَدِلَّ بِالدِّینِ عَلَی الدُّنیَا ؛ وَ الدُّنیَا عَلَی الدِّین', 'Saying', NULL, NULL, 'surah al fateha the horizons and the soul', 'sayingانا الله اسس دينه علي مثال خلقه ليستدل بالدين علي الدنيا و الدنيا علي الدين', 'انا الله اسس دينه علي مثال خلقه ليستدل بالدين علي الدنيا و الدنيا علي الدين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 7, NULL, 'I understand from this that Allah founded his religion on the pattern of creation. He made the world a proof for his religion, and he made his religion a proof for the world. The physical world and the spiritual world therefore rest on the same principles and patterns. Through the physical world, the human intellect can grasp signs that lead it toward the spiritual world. The horizons and the soul, or the self, are therefore keys by which I learn about Allah سُبْحَانَهُ وَتَعَالَى.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i understand from this that allah founded his religion on the pattern of creation he made the world a proof for his religion and he made his religion a proof for the world the physical world and the spiritual world therefore rest on the same principles and patterns through the physical world the human intellect can grasp signs that lead it toward the spiritual world the horizons and the soul or the self are therefore keys by which i learn about allah سبحانه وتعالي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 9, NULL, 'He scattered the knowledge of who he is across the horizons. Light gives a simple image of this meaning. Light is called white light, and in itself it appears colorless.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'he scattered the knowledge of who he is across the horizons light gives a simple image of this meaning light is called white light and in itself it appears colorless', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 10, NULL, 'White Light', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'white light', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 11, NULL, 'When that light passes through a prism, something hidden becomes visible. A prism is a medium of glass. When white light strikes it, the light refracts; it bends. Because of that bending, a whole spectrum of colors appears, from violet to red and everything in between.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'when that light passes through a prism something hidden becomes visible a prism is a medium of glass when white light strikes it the light refracts it bends because of that bending a whole spectrum of colors appears from violet to red and everything in between', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 12, NULL, 'In the same way, the light of Allah سُبْحَانَهُ وَتَعَالَى strikes creation. The Quran tells us that Allah is the light of the heavens and the earth:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'in the same way the light of allah سبحانه وتعالي strikes creation the quran tells us that allah is the light of the heavens and the earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 13, NULL, 'Sayingاللہ نور السموت والارض', '', 'اللہ نور السموت والارض', 'Saying', NULL, NULL, 'surah al fateha the horizons and the soul', 'sayingالله نور السموت والارض', 'الله نور السموت والارض');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 14, NULL, 'Divine Light', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'divine light', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 15, NULL, 'I understand that when the pure light of Allah''s essence touches creation, and when it enters the physical realm, it refracts into the full spectrum of the divine attributes. This is why the universe contains so many different manifestations of Allah سُبْحَانَهُ وَتَعَالَى''s essence.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i understand that when the pure light of allahs essence touches creation and when it enters the physical realm it refracts into the full spectrum of the divine attributes this is why the universe contains so many different manifestations of allah سبحانه وتعاليs essence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 16, NULL, 'This عالم is the prism through which Allah''s various attributes become visible in creation. Through it, I come to know Him in many ways:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'this عالم is the prism through which allahs various attributes become visible in creation through it i come to know him in many ways', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 17, NULL, 'In one instance, creation shows that Allah is کریم, the generous. In another, the universe shows that He is جبار (the compeller). In another, the عالم reveals that He is قھار (the subduer). In another, He appears as عزیز (the powerful). In another, He is مُزِل (the humiliator). In another, He is معز (the bestower of honor).', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'in one instance creation shows that allah is كريم the generous in another the universe shows that he is جبار the compeller in another the عالم reveals that he is قهار the subduer in another he appears as عزيز the powerful in another he is مزل the humiliator in another he is معز the bestower of honor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 18, NULL, 'So the عالم serves as a colossal theater for the divine manifestations of Allah''s attributes, and through those manifestations I come to know Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'so the عالم serves as a colossal theater for the divine manifestations of allahs attributes and through those manifestations i come to know him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 19, NULL, 'I understand the arrangement in this way: the human intellect learns by defining and limiting things, just as the body works by breaking down food. For the intellect to digest knowledge, it must take in the whole, divide it into parts, and understand each part on its own. Only then can it gather those parts again and understand the whole.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i understand the arrangement in this way the human intellect learns by defining and limiting things just as the body works by breaking down food for the intellect to digest knowledge it must take in the whole divide it into parts and understand each part on its own only then can it gather those parts again and understand the whole', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 20, NULL, 'The عالم presents these parts through the divine attributes. I reflect on each attribute individually, then bring them together to form a fuller understanding of my creator. This is an essential theme of Quran. It calls me to reflect on the heavens and the earth, the horizons and the souls, because through that reflection I recognize my creator and His abilities. Then it turns my attention inward, toward the soul, the نفس, so that I may understand the purpose of my own creation.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the عالم presents these parts through the divine attributes i reflect on each attribute individually then bring them together to form a fuller understanding of my creator this is an essential theme of quran it calls me to reflect on the heavens and the earth the horizons and the souls because through that reflection i recognize my creator and his abilities then it turns my attention inward toward the soul the نفس so that i may understand the purpose of my own creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 21, NULL, 'What, then, is the purpose of human creation?', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'what then is the purpose of human creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 23, NULL, 'Scholars state that human beings were created for three reasons. This distinction is beautiful because it allows for purposeful existence not only for Muslims, but also for people of other beliefs, and even for people without belief.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'scholars state that human beings were created for three reasons this distinction is beautiful because it allows for purposeful existence not only for muslims but also for people of other beliefs and even for people without belief', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 24, NULL, 'The purposes of creation are these:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the purposes of creation are these', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 25, NULL, 'The first, he says, is عمارۃ. Allah سُبْحَانَهُ وَتَعَالَى said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the first he says is عماره allah سبحانه وتعالي said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 26, NULL, 'Hud: 61هُوَ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَٱسْتَعْمَرَكُمْ فِيهَا', '', 'هُوَ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَٱسْتَعْمَرَكُمْ فِيهَا', 'Hud: 61', 11, 61, 'surah al fateha the horizons and the soul', 'hud 61هو انشاكم من الارض واستعمركم فيها', 'هو انشاكم من الارض واستعمركم فيها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 27, NULL, 'We brought you forth from the earth to cultivate it.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'we brought you forth from the earth to cultivate it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 28, NULL, 'The second reason, he says, is عبادۃ:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the second reason he says is عباده', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 29, NULL, 'Adh-Dhariyat: 56وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ', '', 'وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ', 'Adh-Dhariyat: 56', 51, 56, 'surah al fateha the horizons and the soul', 'adh dhariyat 56وما خلقت الجن والانس الا ليعبدون', 'وما خلقت الجن والانس الا ليعبدون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 30, NULL, 'We only created the jinn, beings of the unseen realm, and human beings, beings of the visible realm, for عبادۃ, for willing worship. ابن عباس said in a narration that the purpose behind the creation of human beings was also لیعرفون: to know God. To know God is to love God. In the stages of love, عبودیۃ is one of the levels of محبۃ, of love. It is one of the higher levels of love. Therefore, He created the jinn and human beings to love Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'we only created the jinn beings of the unseen realm and human beings beings of the visible realm for عباده for willing worship ابن عباس said in a narration that the purpose behind the creation of human beings was also ليعرفون to know god to know god is to love god in the stages of love عبوديه is one of the levels of محبه of love it is one of the higher levels of love therefore he created the jinn and human beings to love him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 31, NULL, 'The third and final reason for the creation of human beings is خلافۃ:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the third and final reason for the creation of human beings is خلافه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 32, NULL, 'Al-A''raf: 129وَيَسْتَخْلِفَكُمْ فِى ٱلْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ', '', 'وَيَسْتَخْلِفَكُمْ فِى ٱلْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ', 'Al-A''raf: 129', 7, 129, 'surah al fateha the horizons and the soul', 'al araf 129ويستخلفكم في الارض فينظر كيف تعملون', 'ويستخلفكم في الارض فينظر كيف تعملون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 33, NULL, 'We made you خلفاء because the خلیفۃ, the caliph, is the one who stands in someone else''s place. He is the one who is left behind: ُخَلَفَہ. He remains in order to stand in the place of another. In other words, a خلیفۃ is a steward. Allah created us as His stewards on this earth.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'we made you خلفاء because the خليفه the caliph is the one who stands in someone elses place he is the one who is left behind خلفه he remains in order to stand in the place of another in other words a خليفه is a steward allah created us as his stewards on this earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 34, NULL, 'Why? فَيَنظُرَ كَيْفَ تَعْمَلُونَ, so that He can witness what we do with all the outward and inward gifts He has blessed us with.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'why فينظر كيف تعملون so that he can witness what we do with all the outward and inward gifts he has blessed us with', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 35, NULL, 'There are two types of خلافۃ. We have been made a caliph over ourselves, and then over others. For the خلافۃ of the self, Allah said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'there are two types of خلافه we have been made a caliph over ourselves and then over others for the خلافه of the self allah said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 36, NULL, 'Al-Baqarah: 30وَإِذْ قَالَ رَبُّكَ لِلْمَلَٓئِكَةِ إِنِّى جَاعِلٌۭ فِى ٱلْأَرْضِ خَلِيفَةًۭ', '', 'وَإِذْ قَالَ رَبُّكَ لِلْمَلَٓئِكَةِ إِنِّى جَاعِلٌۭ فِى ٱلْأَرْضِ خَلِيفَةًۭ', 'Al-Baqarah: 30', 2, 30, 'surah al fateha the horizons and the soul', 'al baqarah 30واذ قال ربك للمليكه اني جاعل في الارض خليفه', 'واذ قال ربك للمليكه اني جاعل في الارض خليفه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 37, NULL, 'Allah said to the angels, I have decided to create a caliph on the earth. In سُورَۃُ الصَّوَادِ He said to داود علیہ السلام . He said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'allah said to the angels i have decided to create a caliph on the earth in سوره الصواد he said to داود عليه السلام he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 38, NULL, 'Sad: 26يَدَاوُۥدُ إِنَّا جَعَلْنَكَ خَلِيفَةًۭ فِى ٱلْأَرْضِ فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ وَلَا تَتَّبِعِ ٱلْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمْ عَذَابٌۭ شَدِيدٌۢ بِمَا نَسُوا۟ يَوْمَ ٱلْحِسَابِ', '', 'يَدَاوُۥدُ إِنَّا جَعَلْنَكَ خَلِيفَةًۭ فِى ٱلْأَرْضِ فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ وَلَا تَتَّبِعِ ٱلْهَوَىٰ فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ ۚ إِنَّ ٱلَّذِينَ يَضِلُّونَ عَن سَبِيلِ ٱللَّهِ لَهُمْ عَذَابٌۭ شَدِيدٌۢ بِمَا نَسُوا۟ يَوْمَ ٱلْحِسَابِ', 'Sad: 26', 38, 26, 'surah al fateha the horizons and the soul', 'sad 26يداود انا جعلنك خليفه في الارض فاحكم بين الناس بالحق ولا تتبع الهوي فيضلك عن سبيل الله ان الذين يضلون عن سبيل الله لهم عذاب شديد بما نسوا يوم الحساب', 'يداود انا جعلنك خليفه في الارض فاحكم بين الناس بالحق ولا تتبع الهوي فيضلك عن سبيل الله ان الذين يضلون عن سبيل الله لهم عذاب شديد بما نسوا يوم الحساب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 39, NULL, 'Oh داؤد! We have made you a caliph in the earth. This is the second kind of خلافۃ mentioned in the Quran.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'oh داود we have made you a caliph in the earth this is the second kind of خلافه mentioned in the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 40, NULL, 'There are two kinds of خلافۃ:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'there are two kinds of خلافه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 41, NULL, 'ruling oneself; ruling others.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'ruling oneself ruling others', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 42, NULL, 'But the condition for ruling others is that one must first rule oneself. A person must first take control and mastery of his own نفس.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'but the condition for ruling others is that one must first rule oneself a person must first take control and mastery of his own نفس', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 43, NULL, 'Here, داؤد is told that he has been placed in the earth to rule over others. He was made ruler over بَنِی اِسْرَائِیلَ, so that:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'here داود is told that he has been placed in the earth to rule over others he was made ruler over بني اسراييل so that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 44, NULL, 'Sayingفَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ;', '', 'فَٱحْكُم بَيْنَ ٱلنَّاسِ بِٱلْحَقِّ;', 'Saying', 38, 26, 'surah al fateha the horizons and the soul', 'sayingفاحكم بين الناس بالحق', 'فاحكم بين الناس بالحق');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 45, NULL, 'he may judge among them with the truth. Then He says:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'he may judge among them with the truth then he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 46, NULL, 'Sayingوَلَا تَتَّبِعِ ٱلْهَوَىٰ;', '', 'وَلَا تَتَّبِعِ ٱلْهَوَىٰ;', 'Saying', 38, 26, 'surah al fateha the horizons and the soul', 'sayingولا تتبع الهوي', 'ولا تتبع الهوي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 47, NULL, 'do not follow your caprice. In other words, one must rule oneself before ruling others. If that does not happen,', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'do not follow your caprice in other words one must rule oneself before ruling others if that does not happen', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 48, NULL, 'Sayingفَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ,', '', 'فَيُضِلَّكَ عَن سَبِيلِ ٱللَّهِ,', 'Saying', 38, 26, 'surah al fateha the horizons and the soul', 'sayingفيضلك عن سبيل الله', 'فيضلك عن سبيل الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 49, NULL, 'the ف here is for causation. If a person follows caprice, whims, and appetites, they lead him away from the path of Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the ف here is for causation if a person follows caprice whims and appetites they lead him away from the path of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 50, NULL, 'So what are we as caliphs of Allah? How are we doing as Allah''s representatives on earth? Allah says:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'so what are we as caliphs of allah how are we doing as allahs representatives on earth allah says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 51, NULL, 'Fussilat: 53سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ ۗ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', '', 'سَنُرِيهِمْ آيَتِنَا فِى ٱلأٓفَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ ۗ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍۢ شَهِيدٌ', 'Fussilat: 53', 41, 53, 'surah al fateha the horizons and the soul', 'fussilat 53سنريهم ايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق اولم يكف بربك انه علي كل شيء شهيد', 'سنريهم ايتنا في الافاق وفي انفسهم حتي يتبين لهم انه الحق اولم يكف بربك انه علي كل شيء شهيد');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 52, NULL, 'We will show them Our Signs in the horizons and within our own souls. Allah makes the truth of who we are known through the signs around us and within us. Among those signs are the conditions visible in the horizons today, which reveal how we are doing as caliphs of Allah, just as a physician reads the symptoms of an ill patient. Allah says in سُورَۃُ الرُّومِ', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'we will show them our signs in the horizons and within our own souls allah makes the truth of who we are known through the signs around us and within us among those signs are the conditions visible in the horizons today which reveal how we are doing as caliphs of allah just as a physician reads the symptoms of an ill patient allah says in سوره الروم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 53, NULL, 'Ar-Rum: 41ظَهَرَ ٱلْفَسَادُ فِى ٱلْبَرِّ وَٱلْبَحْرِ بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ لِيُذِيقَهُم بَعْضَ ٱلَّذِى عَمِلُوا۟ لَعَلَّهُمْ يَرْجِعُونَ', '', 'ظَهَرَ ٱلْفَسَادُ فِى ٱلْبَرِّ وَٱلْبَحْرِ بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ لِيُذِيقَهُم بَعْضَ ٱلَّذِى عَمِلُوا۟ لَعَلَّهُمْ يَرْجِعُونَ', 'Ar-Rum: 41', 30, 41, 'surah al fateha the horizons and the soul', 'ar rum 41ظهر الفساد في البر والبحر بما كسبت ايدي الناس ليذيقهم بعض الذي عملوا لعلهم يرجعون', 'ظهر الفساد في البر والبحر بما كسبت ايدي الناس ليذيقهم بعض الذي عملوا لعلهم يرجعون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 54, NULL, 'Mischief, corruption, and pollution have appeared on land and sea because of what human hands have earned. لِيُذِيقَهُم, the لام again gives the reason.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'mischief corruption and pollution have appeared on land and sea because of what human hands have earned ليذيقهم the لام again gives the reason', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 55, NULL, 'لِيُذِيقَهُم بَعْضَ ٱلَّذِى عَمِلُوا۟ لَعَلَّهُمْ يَرْجِعُونَ: so that Allah may give them a taste of some of what they have done, so that they may turn back. Allah allows our harmful actions to bring harmful consequences so that we may return to Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'ليذيقهم بعض الذي عملوا لعلهم يرجعون so that allah may give them a taste of some of what they have done so that they may turn back allah allows our harmful actions to bring harmful consequences so that we may return to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 56, NULL, 'I follow the scholars who say that ‏ظَهَرَ ٱلْفَسَادُ is actually النقص فِى ٱلْبَرِّ وَٱلْبَحْرِ. It means that the blessings of the earth become fewer. The earth loses what once made it abundant.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i follow the scholars who say that ظهر الفساد is actually النقص في البر والبحر it means that the blessings of the earth become fewer the earth loses what once made it abundant', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 57, NULL, 'It also means القحط: droughts, famines, and the harms that strike agriculture. The fruits of the land diminish. Lands that once grew crops stop producing. The benefits of the oceans also decrease: fish, whales, and the other creatures that live in the sea.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'it also means القحط droughts famines and the harms that strike agriculture the fruits of the land diminish lands that once grew crops stop producing the benefits of the oceans also decrease fish whales and the other creatures that live in the sea', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 58, NULL, 'All of this happens because of what we earn through our sinfulness. The human being was created in the best of forms, in the very image of his creator, and with all his divine attributes. Yet when he turns away from his divinity and from his original state, he becomes capable of extreme corruption.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'all of this happens because of what we earn through our sinfulness the human being was created in the best of forms in the very image of his creator and with all his divine attributes yet when he turns away from his divinity and from his original state he becomes capable of extreme corruption', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 59, NULL, 'This was the very concern the angels expressed when Allah mentioned the creation of Adam to them. They said', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'this was the very concern the angels expressed when allah mentioned the creation of adam to them they said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 60, NULL, 'Al-Baqarah: 30قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ', '', 'قَالُوٓا۟ أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ', 'Al-Baqarah: 30', 2, 30, 'surah al fateha the horizons and the soul', 'al baqarah 30قالوا اتجعل فيها من يفسد فيها ويسفك الدماء', 'قالوا اتجعل فيها من يفسد فيها ويسفك الدماء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 61, NULL, 'Are you seriously considering creating a species therein who will create فساد and spill blood?', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'are you seriously considering creating a species therein who will create فساد and spill blood', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 62, NULL, 'The word فساد carries many meanings in English: rottenness, corruption, decay, decomposition, putridity, depravity, wickedness, viciousness, iniquity, immorality, weakness, perversion, wrongness, and incorrectness. All these meanings are gathered inside فساد.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the word فساد carries many meanings in english rottenness corruption decay decomposition putridity depravity wickedness viciousness iniquity immorality weakness perversion wrongness and incorrectness all these meanings are gathered inside فساد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 63, NULL, 'The English word pollution is defined as an undesirable condition of the natural environment, contaminated by harmful substances as a result of human activity.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the english word pollution is defined as an undesirable condition of the natural environment contaminated by harmful substances as a result of human activity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 64, NULL, 'بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ: this is the result. Even in our own language, pollution names one of the dominant problems of the planet.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'بما كسبت ايدي الناس this is the result even in our own language pollution names one of the dominant problems of the planet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 65, NULL, 'I am speaking of human responsibility for the present condition of the earth. The hardships that now surround us, including famine, extreme weather, earthquakes, and floods, are nothing other than بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ: what our own hands have earned. Many countries have fallen into severe crisis because forests have been set on fire. Climate change raises temperatures, and higher temperatures bring more fires.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i am speaking of human responsibility for the present condition of the earth the hardships that now surround us including famine extreme weather earthquakes and floods are nothing other than بما كسبت ايدي الناس what our own hands have earned many countries have fallen into severe crisis because forests have been set on fire climate change raises temperatures and higher temperatures bring more fires', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 66, NULL, 'Another form of this فساد is in the air itself. In India, it has been estimated that half a million people die from air pollution. Fifteen thousand people died from terrorism, and the United States government moved heaven and earth to wage a war on terrorism. Yet half a million people suffer and die from air pollution. Where is the war against that?', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'another form of this فساد is in the air itself in india it has been estimated that half a million people die from air pollution fifteen thousand people died from terrorism and the united states government moved heaven and earth to wage a war on terrorism yet half a million people suffer and die from air pollution where is the war against that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 67, NULL, 'Noise pollution is another part of the same corruption. In Pakistan and India, the levels are plain in the constant honking, yelling, and screaming, and in the noise of rickshaws and taxis with broken silencers. All of that is human-made فساد.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'noise pollution is another part of the same corruption in pakistan and india the levels are plain in the constant honking yelling and screaming and in the noise of rickshaws and taxis with broken silencers all of that is human made فساد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 68, NULL, 'I know today that the world is moving quickly toward desertification. The reason is the loss of what is called topsoil. Desertification means that land once covered with growth becomes desert. This has already happened across large stretches of fertile land, and it continues to spread.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i know today that the world is moving quickly toward desertification the reason is the loss of what is called topsoil desertification means that land once covered with growth becomes desert this has already happened across large stretches of fertile land and it continues to spread', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 69, NULL, 'I was reading a book that said there was a time when all of North Africa was so fertile that, before بنو حِلاؤ entered Africa, a squirrel could run from سنجاب, from Egypt all the way to Morocco, without its feet ever touching the ground. The land was that fertile. But when the بنو حلاؤ came, they were like locusts. They devoured the resources completely. Desertification is therefore another example of بِمَا كَسَبَتْ أَيْدِى ٱلنَّاسِ: what our own hands have earned.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i was reading a book that said there was a time when all of north africa was so fertile that before بنو حلاو entered africa a squirrel could run from سنجاب from egypt all the way to morocco without its feet ever touching the ground the land was that fertile but when the بنو حلاو came they were like locusts they devoured the resources completely desertification is therefore another example of بما كسبت ايدي الناس what our own hands have earned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 70, NULL, 'Another aspect of فساد appears in the words of Allah:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'another aspect of فساد appears in the words of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 71, NULL, 'Ar-Rahman: 10وَٱلْأَرْضَ وَضَعَهَا لِلْأَنَامِ', '', 'وَٱلْأَرْضَ وَضَعَهَا لِلْأَنَامِ', 'Ar-Rahman: 10', 55, 10, 'surah al fateha the horizons and the soul', 'ar rahman 10والارض وضعها للانام', 'والارض وضعها للانام');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 72, NULL, 'The earth has been laid out for the انام. The word انام comes from نوم, which means sleep. أنام are creatures that sleep. This verse, then, concerns all sentient beings. It is not only about human beings; it includes the animal kingdom. Allah سُبْحَانَهُ وَتَعَالَى', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the earth has been laid out for the انام the word انام comes from نوم which means sleep انام are creatures that sleep this verse then concerns all sentient beings it is not only about human beings it includes the animal kingdom allah سبحانه وتعالي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 73, NULL, 'Al-An''am: 38وَمَا مِن دَآبَّةٍۢ فِى ٱلْأَرْضِ وَلَا طَٓئِرٍۢ يَطِيرُ بِجَنَاحَيْهِ إِلَّآ أُمَمٌ أَمْثَالُكُم ۚ مَّا فَرَّطْنَا فِى ٱلْكِتَبِ مِن شَىْءٍۢ ۚ ثُمَّ إِلَىٰ رَبِّهِمْ يُحْشَرُونَThere is not a moving creature on earth, nor a bird that flies with its two wings, but are communities like you. We have neglected nothing in the Book, then unto their Lord they shall be gathered.', '', NULL, 'Al-An''am: 38', NULL, NULL, 'surah al fateha the horizons and the soul', 'al anam 38وما من دابه في الارض ولا طير يطير بجناحيه الا امم امثالكم ما فرطنا في الكتب من شيء ثم الي ربهم يحشرونthere is not a moving creature on earth nor a bird that flies with its two wings but are communities like you we have neglected nothing in the book then unto their lord they shall be gathered', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 74, NULL, 'I understand the verse to mean that no creature walks upon the earth, and no bird flies with its two wings, except that they belong to communities like human communities. Allah سُبْحَانَهُ وَتَعَالَى tells me that the kingdoms of animals are communities like ours. Then He says that He has left nothing out of this Book:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i understand the verse to mean that no creature walks upon the earth and no bird flies with its two wings except that they belong to communities like human communities allah سبحانه وتعالي tells me that the kingdoms of animals are communities like ours then he says that he has left nothing out of this book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 75, NULL, 'Al-An''am: 38مَّا فَرَّطْنَا فِى ٱلْكِتَبِ مِن شَىْءٍۢ', '', 'مَّا فَرَّطْنَا فِى ٱلْكِتَبِ مِن شَىْءٍۢ', 'Al-An''am: 38', 6, 38, 'surah al fateha the horizons and the soul', 'al anam 38ما فرطنا في الكتب من شيء', 'ما فرطنا في الكتب من شيء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 76, NULL, 'Even animals are acknowledged in the Quran. I know that some animals mate for life. I know that animals make immense journeys, pilgrimages, and migrations to distant places, much as human beings do.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'even animals are acknowledged in the quran i know that some animals mate for life i know that animals make immense journeys pilgrimages and migrations to distant places much as human beings do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 77, NULL, 'Today, because of the sins of mankind, dogs are put on Prozac. In the United States, dogs are given Prozac, an antidepressant, because they are depressed in the homes of depressed and miserable people. Dogs are not naturally depressed animals. But so many houses in the United States are sick that the dogs and cats themselves become sick, because they are sentient beings. They are emotional beings. They feel and experience emotions as human beings do.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'today because of the sins of mankind dogs are put on prozac in the united states dogs are given prozac an antidepressant because they are depressed in the homes of depressed and miserable people dogs are not naturally depressed animals but so many houses in the united states are sick that the dogs and cats themselves become sick because they are sentient beings they are emotional beings they feel and experience emotions as human beings do', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 78, NULL, 'I see the problem in the endangered species brought about by human hands. Among the world''s critically endangered species are some of the most beautiful and majestic animals. These are the very animals after which the ancient Arabs named their children: lions and tigers, أسد and فھد . They named their men after مُفْتَرِسَات, after animals that attack their prey. They named their women after the prey itself, such as ماھا and غزالۃ. So فھد goes after ماھا, and she does not stand a chance.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i see the problem in the endangered species brought about by human hands among the worlds critically endangered species are some of the most beautiful and majestic animals these are the very animals after which the ancient arabs named their children lions and tigers اسد and فهد they named their men after مفترسات after animals that attack their prey they named their women after the prey itself such as ماها and غزاله so فهد goes after ماها and she does not stand a chance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 79, NULL, 'What strikes me is that the species endangered today are not the cockroaches. They are not the rats. They are not the snakes. These creatures are flourishing. The animals and species now endangered are the ones that represent divine qualities within the human being, qualities that are disappearing. The eagle, the peregrine, the lion, the tiger, and the elephant all stand for great human qualities that are vanishing.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'what strikes me is that the species endangered today are not the cockroaches they are not the rats they are not the snakes these creatures are flourishing the animals and species now endangered are the ones that represent divine qualities within the human being qualities that are disappearing the eagle the peregrine the lion the tiger and the elephant all stand for great human qualities that are vanishing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 80, NULL, 'Adh-Dhariyat: 21وَفِىٓ أَنفُسِكُمْ ۚ أَفَلَا تُبْصِرُونَ', '', 'وَفِىٓ أَنفُسِكُمْ ۚ أَفَلَا تُبْصِرُونَ', 'Adh-Dhariyat: 21', 51, 21, 'surah al fateha the horizons and the soul', 'adh dhariyat 21وفي انفسكم افلا تبصرون', 'وفي انفسكم افلا تبصرون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 81, NULL, 'Within the souls themselves, the call is to reflect. I see plenty of cockroaches in human disguise. I see plenty of rats and snakes in human disguise. But I no longer find the courage of lions or the majesty of eagles in human form. These qualities have become extinct among human beings.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'within the souls themselves the call is to reflect i see plenty of cockroaches in human disguise i see plenty of rats and snakes in human disguise but i no longer find the courage of lions or the majesty of eagles in human form these qualities have become extinct among human beings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 82, NULL, 'I can go on and on about this, and I am sure much more could be added. But this is what we are doing as the caliphs and stewards of Allah سُبْحَانَهُ وَتَعَالَى. We are destroying the very earth that sustains us and gives us our livelihood. Then we complain that we have problems and ask why Allah does not solve them all.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i can go on and on about this and i am sure much more could be added but this is what we are doing as the caliphs and stewards of allah سبحانه وتعالي we are destroying the very earth that sustains us and gives us our livelihood then we complain that we have problems and ask why allah does not solve them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 83, NULL, 'Why should he? He is not our janitor. He is not our servant. He is not our errand boy. He created us in his image so that we could create جنۃ on earth, just as he created جنۃ in heaven. Adam was not created in جنۃ for amusement. He was created in جنۃ so that he could see and experience the beauty of that place. Then, when he came to the earth, he could cultivate the land and create that same جنۃ on earth.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'why should he he is not our janitor he is not our servant he is not our errand boy he created us in his image so that we could create جنه on earth just as he created جنه in heaven adam was not created in جنه for amusement he was created in جنه so that he could see and experience the beauty of that place then when he came to the earth he could cultivate the land and create that same جنه on earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 84, NULL, 'Hud: 61وَ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَٱسْتَعْمَرَكُمْ فِيهَا', '', 'وَ أَنشَأَكُم مِّنَ ٱلْأَرْضِ وَٱسْتَعْمَرَكُمْ فِيهَا', 'Hud: 61', 11, 61, 'surah al fateha the horizons and the soul', 'hud 61و انشاكم من الارض واستعمركم فيها', 'و انشاكم من الارض واستعمركم فيها');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 85, NULL, 'He brought you forth from the earth to cultivate it.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'he brought you forth from the earth to cultivate it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 86, NULL, 'That cultivation meant creating the same جنۃ on earth. What did we do instead? Why did this happen? How did things become so bad and slip so far out of hand? It happened because of our corruption: because of our فساد, our departure from the divine attributes and majestic qualities with which Allah سُبْحَانَهُ وَتَعَالَى created us. This is why he created the عالمین for us: so that we could study the signs on the horizons, the heavens and the earth, and learn from his divine attributes the ideal condition of the نفس, the ideal condition of the soul.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'that cultivation meant creating the same جنه on earth what did we do instead why did this happen how did things become so bad and slip so far out of hand it happened because of our corruption because of our فساد our departure from the divine attributes and majestic qualities with which allah سبحانه وتعالي created us this is why he created the عالمين for us so that we could study the signs on the horizons the heavens and the earth and learn from his divine attributes the ideal condition of the نفس the ideal condition of the soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 87, NULL, 'But we, as human beings, as خَلِیفَۃُ اللَّہِ, have failed terribly. We have shown that the angels had real grounds for concern. They knew clearly what they were saying when they said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'but we as human beings as خليفه الله have failed terribly we have shown that the angels had real grounds for concern they knew clearly what they were saying when they said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 88, NULL, 'Al-Baqarah: 30أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ', '', 'أَتَجْعَلُ فِيهَا مَن يُفْسِدُ فِيهَا وَيَسْفِكُ ٱلدِّمَآءَ', 'Al-Baqarah: 30', 2, 30, 'surah al fateha the horizons and the soul', 'al baqarah 30اتجعل فيها من يفسد فيها ويسفك الدماء', 'اتجعل فيها من يفسد فيها ويسفك الدماء');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 89, NULL, 'Do you wish to create someone who will sow corruption on earth and spill blood? They knew clearly what they were saying.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'do you wish to create someone who will sow corruption on earth and spill blood they knew clearly what they were saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 90, NULL, 'So what have we turned away from? We have turned away from the divine attributes, from the character of Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'so what have we turned away from we have turned away from the divine attributes from the character of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 92, NULL, 'Character', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'character', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 93, NULL, 'I begin with the word أخلاق, which comes from خُلق. This matters because we are called خَلق.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i begin with the word اخلاق which comes from خلق this matters because we are called خلق', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 94, NULL, 'The word خَلق means creation. It is tied to the body, and the body is tied to the horizons. The word خُلق means character, and character belongs to the soul. Both words are made from the same letters, in the same order. In the science of Arabic, that shared form shows a close relationship in meaning.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the word خلق means creation it is tied to the body and the body is tied to the horizons the word خلق means character and character belongs to the soul both words are made from the same letters in the same order in the science of arabic that shared form shows a close relationship in meaning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 95, NULL, 'خَلق belongs to the body, which is nourished by the physical world. خُلق is character, which takes its nourishment from the spiritual world. خَلق represents the body''s existence; خُلق represents the soul''s existence.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'خلق belongs to the body which is nourished by the physical world خلق is character which takes its nourishment from the spiritual world خلق represents the bodys existence خلق represents the souls existence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 96, NULL, 'Both words begin with the letter خ (kha), a sound of friction in Arabic. It is a sound of effort. The body requires effort to develop, and character requires effort as well. Character demands great effort.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'both words begin with the letter خ kha a sound of friction in arabic it is a sound of effort the body requires effort to develop and character requires effort as well character demands great effort', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 97, NULL, 'So if خَلق is the essence of the body, then خُلق, character, is the essence of the soul. When we die, the body returns to the earth with whatever it gained from the physical world. The soul returns to the spiritual world with the character it developed in this world. That is our true earning. That is our real acquisition: خُلق, character.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'so if خلق is the essence of the body then خلق character is the essence of the soul when we die the body returns to the earth with whatever it gained from the physical world the soul returns to the spiritual world with the character it developed in this world that is our true earning that is our real acquisition خلق character', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 98, NULL, 'A soul that returns to its Master without developed خُلق is an impoverished soul. It has failed the purpose of its خلقۃ; it has failed the purpose of its creation. When the body is weak, it cannot benefit from what this physical world offers.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'a soul that returns to its master without developed خلق is an impoverished soul it has failed the purpose of its خلقه it has failed the purpose of its creation when the body is weak it cannot benefit from what this physical world offers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 99, NULL, 'I know that this world offers many temporary pleasures. Yet if the body is extremely weak, and a person cannot even rise from bed, those pleasures cannot be enjoyed. In the same way, a soul that is empty and bankrupt of أخلاق cannot benefit from the pleasures of the afterlife.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i know that this world offers many temporary pleasures yet if the body is extremely weak and a person cannot even rise from bed those pleasures cannot be enjoyed in the same way a soul that is empty and bankrupt of اخلاق cannot benefit from the pleasures of the afterlife', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 100, NULL, 'How is character developed? Through revelation. The Quran, stated simply, explains the divine attributes of Allah. It shows what His attributes are and why they belong to Him. He is عظیم because he created this vast universe. He is قوی, all-powerful, because he did not merely create the universe; he created it with one single command: کُن, “Be,” and فیکون, it was.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'how is character developed through revelation the quran stated simply explains the divine attributes of allah it shows what his attributes are and why they belong to him he is عظيم because he created this vast universe he is قوي all powerful because he did not merely create the universe he created it with one single command كن be and فيكون it was', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 101, NULL, 'In essence, the Quran describes Allah''s attributes and explains why he is ال الہ. Our hearts witness these divine attributes in the light of revelation, and that witnessing creates Belief. The more the heart understands revelation, the more belief grows. That belief then nourishes and develops character.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'in essence the quran describes allahs attributes and explains why he is ال اله our hearts witness these divine attributes in the light of revelation and that witnessing creates belief the more the heart understands revelation the more belief grows that belief then nourishes and develops character', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 102, NULL, 'Character, then, is nothing other than absorbing these divine attributes into the heart through revelation, and then reflecting those same divine attributes toward the rest of Allah''s creation. That is character: the heart internalized, developed, and trained in the light of these divine attributes, then made visible in our dealings with Allah''s creation.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'character then is nothing other than absorbing these divine attributes into the heart through revelation and then reflecting those same divine attributes toward the rest of allahs creation that is character the heart internalized developed and trained in the light of these divine attributes then made visible in our dealings with allahs creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 104, NULL, 'That is أخلاق, and that is Islam. Islam is about interactions. It is معاملات. There are three types of interactions in Islam:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'that is اخلاق and that is islam islam is about interactions it is معاملات there are three types of interactions in islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 105, NULL, 'Interaction with Allah: حُقُوقُ اللَّہِ Interaction with the self: حُقُوقُ النَّفْسِ Our interaction with the creation of Allah: حُقُوقُ الْعِبَادِ', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'interaction with allah حقوق الله interaction with the self حقوق النفس our interaction with the creation of allah حقوق العباد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 106, NULL, 'Huqooq Allah', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'huqooq allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 107, NULL, 'Allah''s right over us is that we recognize his attributes in the heavens and the earth, and that, through recognizing them, we come to love him for everything he has done for us. From that love, we willingly obey him and serve him as faithful slaves, as عبد. We worship him while knowing that only he deserves worship. That is the right of the Creator over his creation.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'allahs right over us is that we recognize his attributes in the heavens and the earth and that through recognizing them we come to love him for everything he has done for us from that love we willingly obey him and serve him as faithful slaves as عبد we worship him while knowing that only he deserves worship that is the right of the creator over his creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 108, NULL, 'What, then, is the right of the self?', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'what then is the right of the self', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 109, NULL, 'Huqooq Nafs', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'huqooq nafs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 110, NULL, 'The right of the self is that we reflect on the attributes of Allah in the عالم through the teachings of the Quran. We learn the attributes, qualities, and character of our master, then internalize and cultivate those qualities in our own hearts so that our character, our أخلاق, is formed.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the right of the self is that we reflect on the attributes of allah in the عالم through the teachings of the quran we learn the attributes qualities and character of our master then internalize and cultivate those qualities in our own hearts so that our character our اخلاق is formed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 111, NULL, 'We were created in the image of our master. We were created to represent our master on this earth. That means we must adopt the qualities and characteristics of our master. That is what a خلیفۃ is: a representative. Representation is not possible unless we become like the one we represent.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'we were created in the image of our master we were created to represent our master on this earth that means we must adopt the qualities and characteristics of our master that is what a خليفه is a representative representation is not possible unless we become like the one we represent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 112, NULL, 'For instance, Allah is کریم. He is generous. Therefore, my soul has a right over me: I must train it in generosity.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'for instance allah is كريم he is generous therefore my soul has a right over me i must train it in generosity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 113, NULL, 'The greatest generosity I can show my own soul is to protect it from sin and set it to work in good deeds. Allah is الحق. He is truthful. Therefore, my soul has a right over me: I must train it in truthfulness.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the greatest generosity i can show my own soul is to protect it from sin and set it to work in good deeds allah is الحق he is truthful therefore my soul has a right over me i must train it in truthfulness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 114, NULL, 'With whom must I be truthful? With myself.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'with whom must i be truthful with myself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 115, NULL, 'The greatest falsehood in which the self is trapped is the delusion of دنیا. I must therefore train myself to wake from my delusions about this world. I must wake to the reality that I am here only for a short time. Everything I labor for in a worldly sense will be left behind. When I die, I will be left with nothing in this world except the title of میت. My loved ones, the people for whom I labor day and night, will be the first to place me in the grave and throw dirt over my face. I must not sacrifice my afterlife for this temporary life. That is truthfulness to the self.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the greatest falsehood in which the self is trapped is the delusion of دنيا i must therefore train myself to wake from my delusions about this world i must wake to the reality that i am here only for a short time everything i labor for in a worldly sense will be left behind when i die i will be left with nothing in this world except the title of ميت my loved ones the people for whom i labor day and night will be the first to place me in the grave and throw dirt over my face i must not sacrifice my afterlife for this temporary life that is truthfulness to the self', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 116, NULL, 'The right of the self, then, is that I internalize the attributes of Allah and train myself in them, so that my character develops and I realize the potential with which I was created. I was created in the image of God, to act like God. And God is nothing but just.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the right of the self then is that i internalize the attributes of allah and train myself in them so that my character develops and i realize the potential with which i was created i was created in the image of god to act like god and god is nothing but just', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 117, NULL, 'This is why one of the divine names of Allah is المؤمن, which means, in essence, the giver of tranquility, the One who brings peace. It comes from the root امن, which means peace.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'this is why one of the divine names of allah is المومن which means in essence the giver of tranquility the one who brings peace it comes from the root امن which means peace', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 118, NULL, 'Huqooq Ibaad', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'huqooq ibaad', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 119, NULL, 'Finally, I come to the right of others, حُقُوقُ الْعِبَادِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'finally i come to the right of others حقوق العباد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 120, NULL, 'The right of Allah is to recognize his divine attributes in creation, and to submit to him willingly and lovingly in عبادۃ. The right of the self is to take those divine attributes into myself, so they shape my character and bring it into harmony with the character of Allah. I am to become like the Creator.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the right of allah is to recognize his divine attributes in creation and to submit to him willingly and lovingly in عباده the right of the self is to take those divine attributes into myself so they shape my character and bring it into harmony with the character of allah i am to become like the creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 121, NULL, 'Only after that character has been formed does the final right, حُقُوقُ الْعِبَادِ, come into force. It means reflecting the divine attributes of Allah in my dealings with his creation.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'only after that character has been formed does the final right حقوق العباد come into force it means reflecting the divine attributes of allah in my dealings with his creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 122, NULL, 'I trained myself to be generous with my own self. Now that generosity must appear in my dealings with others. I trained myself to be truthful and sincere with my own self. Now that truthfulness, that صدق, that sincerity, must appear in my dealings with others. I recognized how Allah forgives me and how patient he is with me. Now I must reflect those attributes by being patient and forgiving toward others.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i trained myself to be generous with my own self now that generosity must appear in my dealings with others i trained myself to be truthful and sincere with my own self now that truthfulness that صدق that sincerity must appear in my dealings with others i recognized how allah forgives me and how patient he is with me now i must reflect those attributes by being patient and forgiving toward others', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 123, NULL, 'This is not an easy task. That is why the first two rights must be fulfilled before the third right can truly be fulfilled. A man once came to the Messenger of Allah and said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'this is not an easy task that is why the first two rights must be fulfilled before the third right can truly be fulfilled a man once came to the messenger of allah and said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 124, NULL, 'Sayingیَا رَسُولَ اللہِ. اَصِلُ اَخِیہِ وَ یَقطَعُنِی وَ اُعطِیہِ وَ یَمنَعُنِی“Oh messenger of Allah, I give to him, but he withholds from me. I come to him, but he cuts me off. What should I do?” the Prophet replied, “That is صِلَۃُ الرَّحِمِ. What you are doing is right. Continue meeting him, even though he cuts you off.”', '', NULL, 'Saying', NULL, NULL, 'surah al fateha the horizons and the soul', 'sayingيا رسول الله اصل اخيه و يقطعني و اعطيه و يمنعني oh messenger of allah i give to him but he withholds from me i come to him but he cuts me off what should i do the prophet replied that is صله الرحم what you are doing is right continue meeting him even though he cuts you off', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 125, NULL, 'That is Islam. And Islam is hard work. I must not think of this religion as easy. I must become one who strives. I must honor myself, because Allah honored me when he said:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'that is islam and islam is hard work i must not think of this religion as easy i must become one who strives i must honor myself because allah honored me when he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 126, NULL, 'Al-Isra: 70وَلَقَدْ كَرَّمْنَا بَنِىٓ آدَمَ وَحَمَلْنَهُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ“We have ennobled the children of Adam. We have made you leaders over the land and the oceans. We gave you a heart. We gave you an intellect. We nourish both with our revelation. We give you the ability to overcome the worst part of yourself. And even when you fall from time to time, We have given you the means to renew and restore your soul through توبۃ, through repentance.”', '', NULL, 'Al-Isra: 70', NULL, NULL, 'surah al fateha the horizons and the soul', 'al isra 70ولقد كرمنا بني ادم وحملنهم في البر والبحر we have ennobled the children of adam we have made you leaders over the land and the oceans we gave you a heart we gave you an intellect we nourish both with our revelation we give you the ability to overcome the worst part of yourself and even when you fall from time to time we have given you the means to renew and restore your soul through توبه through repentance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 127, NULL, 'What a gift from Allah. I must do this with أخلاص, with sincerity, only for the sake of Allah. But it is not easy.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'what a gift from allah i must do this with اخلاص with sincerity only for the sake of allah but it is not easy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 128, NULL, 'Three Dimensions of Islam', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'three dimensions of islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 129, NULL, 'I understand these as the three dimensions of Islam: the rights of Allah, the rights of the self, and the rights of others. Recognizing the attributes of Allah in the heavens and the earth teaches the rights of Allah (حُقُوقُ اللَّہِ). Taking those divine attributes into myself, so that they shape my character, is the right of the soul (حُقُوقُ النَّفْسِ). Reflecting those divine attributes toward the creation of Allah is the right of others (حُقُوقُ الْعِبَاد).', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i understand these as the three dimensions of islam the rights of allah the rights of the self and the rights of others recognizing the attributes of allah in the heavens and the earth teaches the rights of allah حقوق الله taking those divine attributes into myself so that they shape my character is the right of the soul حقوق النفس reflecting those divine attributes toward the creation of allah is the right of others حقوق العباد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 130, NULL, 'The last of these is the hardest. It cannot be fulfilled unless the soul has first been lit by the character of Allah. This is why Rasul Allah ﷺ said in a hadees:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the last of these is the hardest it cannot be fulfilled unless the soul has first been lit by the character of allah this is why rasul allah ﷺ said in a hadees', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 131, NULL, 'Sayingأتخذو من أخلاق اللہ', '', 'أتخذو من أخلاق اللہ', 'Saying', NULL, NULL, 'surah al fateha the horizons and the soul', 'sayingاتخذو من اخلاق الله', 'اتخذو من اخلاق الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 132, NULL, 'Adopt the character and the qualities of Allah!', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'adopt the character and the qualities of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 133, NULL, 'I find a narration in which Rasul Allah once saw a man speaking to Maulana Ali with great disrespect. Maulana Ali answered him with kindness. The man still continued in his harsh and disrespectful manner, yet Maulana Ali kept answering him with kindness again and again.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i find a narration in which rasul allah once saw a man speaking to maulana ali with great disrespect maulana ali answered him with kindness the man still continued in his harsh and disrespectful manner yet maulana ali kept answering him with kindness again and again', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 134, NULL, 'When the man left, the prophet asked him, یا علی! I saw this man speak to you with such disrespect and treat you so badly again and again. Yet each time, you showed him kindness and respect in return. Why was that?', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'when the man left the prophet asked him يا علي i saw this man speak to you with such disrespect and treat you so badly again and again yet each time you showed him kindness and respect in return why was that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 135, NULL, 'Maulana Ali replied: یَا رَسُولَ اللہِ If this man is not willing to give up his wretched and evil nature in order to deal with me, then why should I give up my good character in order to deal with him?', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'maulana ali replied يا رسول الله if this man is not willing to give up his wretched and evil nature in order to deal with me then why should i give up my good character in order to deal with him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 136, NULL, 'SubhanAllah. What a beautiful statement. If this man is not willing to give up his wretched and evil nature in order to deal with me, then why should I give up my good character in order to deal with him? In other words, if this man insists on holding to something ugly, why should I let go of something beautiful that I possess? That is the beauty of أخلاق.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'subhanallah what a beautiful statement if this man is not willing to give up his wretched and evil nature in order to deal with me then why should i give up my good character in order to deal with him in other words if this man insists on holding to something ugly why should i let go of something beautiful that i possess that is the beauty of اخلاق', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 137, NULL, 'I therefore follow the example of Rasul Allah ﷺ, whom the Quran describes as reaching the pinnacle of اخلاق. Through his character, and through nothing but his character, he purified the most barbaric and vile people that had ever existed.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i therefore follow the example of rasul allah ﷺ whom the quran describes as reaching the pinnacle of اخلاق through his character and through nothing but his character he purified the most barbaric and vile people that had ever existed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 138, NULL, 'The history of Islam shows what kind of people he was sent to reform, and what mentality ruled them. They were worse than animals. Not a single virtue lived among them. They ate the flesh of elephants and crocodiles. When they ate a goat, they even boiled its hide and ate that too. They burned their enemies alive. They tore off their skin and wore it like a scarf. They cracked open a man''s skull and used it as a cup for wine. Their women dyed their clothes in the blood of their enemies.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'the history of islam shows what kind of people he was sent to reform and what mentality ruled them they were worse than animals not a single virtue lived among them they ate the flesh of elephants and crocodiles when they ate a goat they even boiled its hide and ate that too they burned their enemies alive they tore off their skin and wore it like a scarf they cracked open a mans skull and used it as a cup for wine their women dyed their clothes in the blood of their enemies', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 139, NULL, 'They did not merely kill the enemy. They tied his camel to his grave and left it there to starve to death. Sons married their mothers. Daughters were buried alive. They used the children of their enemies for target practice. Even their prayers were barbaric.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'they did not merely kill the enemy they tied his camel to his grave and left it there to starve to death sons married their mothers daughters were buried alive they used the children of their enemies for target practice even their prayers were barbaric', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 140, NULL, 'Sayingیا ربِّ فَلا تَجعَل حَیَاتی مَذِلَّۃُ ولا مَوتَتِی بَینَ النِّسآءِ نوائِحِ', '', 'یا ربِّ فَلا تَجعَل حَیَاتی مَذِلَّۃُ ولا مَوتَتِی بَینَ النِّسآءِ نوائِحِ', 'Saying', NULL, NULL, 'surah al fateha the horizons and the soul', 'sayingيا رب فلا تجعل حياتي مذله ولا موتتي بين النساء نوايح', 'يا رب فلا تجعل حياتي مذله ولا موتتي بين النساء نوايح');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 141, NULL, 'Sayingولاکن قَتیلاً تَمزَقُ الطَّیرِ حَولَہُ . و تَشرُبُ غِربانُ الدَّم من جوارح', '', 'ولاکن قَتیلاً تَمزَقُ الطَّیرِ حَولَہُ . و تَشرُبُ غِربانُ الدَّم من جوارح', 'Saying', NULL, NULL, 'surah al fateha the horizons and the soul', 'sayingولاكن قتيلا تمزق الطير حوله و تشرب غربان الدم من جوارح', 'ولاكن قتيلا تمزق الطير حوله و تشرب غربان الدم من جوارح');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 142, NULL, 'Oh Lord, do not disgrace me in my life by letting me die on a bed between grieving women. Give me a death where birds tear out my flesh and crows drink the fresh blood gushing from my limbs.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'oh lord do not disgrace me in my life by letting me die on a bed between grieving women give me a death where birds tear out my flesh and crows drink the fresh blood gushing from my limbs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 143, NULL, 'I see the state of the Arabs when Rasul Allah came among them. This was the people he was sent to reform. He changed them into رَحْمَۃُ اللّٰہِ عَلَیْہِ. Their names are not mentioned without saying رَحْمَۃُ اللّٰہِ عَلَیْہِ- May the mercy of Allah be with them.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'i see the state of the arabs when rasul allah came among them this was the people he was sent to reform he changed them into رحمه الله عليه their names are not mentioned without saying رحمه الله عليه may the mercy of allah be with them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 144, NULL, 'That is why, on the day of غدیر, Rasul Allah asked:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'that is why on the day of غدير rasul allah asked', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 145, NULL, 'Sayingاَلَسْتُ اَوْلَاکُمْ مِنْ اَنْفُسِکُمْ؟', '', 'اَلَسْتُ اَوْلَاکُمْ مِنْ اَنْفُسِکُمْ؟', 'Saying', NULL, NULL, 'surah al fateha the horizons and the soul', 'sayingالست اولاكم من انفسكم', 'الست اولاكم من انفسكم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 146, NULL, 'Am I not more beloved to you than your own souls?', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'am i not more beloved to you than your own souls', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 147, NULL, 'They replied:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'they replied', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 148, NULL, 'Sayingبلیٰ یَا رَسُولَ اللہِ', '', 'بلیٰ یَا رَسُولَ اللہِ', 'Saying', NULL, NULL, 'surah al fateha the horizons and the soul', 'sayingبلي يا رسول الله', 'بلي يا رسول الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 149, NULL, 'Indeed you are, O prophet of Allah.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'indeed you are o prophet of allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 150, NULL, 'Sayingكُنَّا الْحَيَوَانَاتِ! كُنتُ جعلنا البشر', '', 'كُنَّا الْحَيَوَانَاتِ! كُنتُ جعلنا البشر', 'Saying', NULL, NULL, 'surah al fateha the horizons and the soul', 'sayingكنا الحيوانات كنت جعلنا البشر', 'كنا الحيوانات كنت جعلنا البشر');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 151, NULL, 'We were animals! You made us human beings.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'we were animals you made us human beings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 152, NULL, 'How did he do this? Through his flawless اخلاق. He took the divine attributes of his creator into himself, formed through them a stainless character, and then reflected those same attributes back into creation with such force that the creator himself acknowledged:', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'how did he do this through his flawless اخلاق he took the divine attributes of his creator into himself formed through them a stainless character and then reflected those same attributes back into creation with such force that the creator himself acknowledged', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'the horizons and the soul', 'The Horizons And The Soul', 153, NULL, 'Al-Qalam: 4وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍۢ', '', 'وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍۢ', 'Al-Qalam: 4', 68, 4, 'surah al fateha the horizons and the soul', 'al qalam 4وانك لعلي خلق عظيم', 'وانك لعلي خلق عظيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the horizons and the soul', 'The Horizons And The Soul', 154, NULL, 'Indeed, beyond all doubt, You have reached the highest and most exalted level of character.', '', NULL, NULL, NULL, NULL, 'surah al fateha the horizons and the soul', 'indeed beyond all doubt you have reached the highest and most exalted level of character', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 0, NULL, 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ. ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ. رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي. السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.', '', 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ', NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي السلام عليكم ورحمه الله وبركاته', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي السلام عليكم ورحمه الله وبركاته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 1, NULL, 'Now that we understand these meanings of رَبِّ and الرَّحْمَٰن and رَحِيم, now that we understand these terms, I want to share with you a beautiful spiritual representation that اللهُ سُبْحَانَهُ وَتَعَالَى has created for us through the example of the womb, the رَحِيم. To quickly reiterate these terms, رَبِّ is a combination of six things in classical Arabic. The definition is a رَبُّهُ الْمَلِكُ وَالسَّيِّدُ الْمُرَبِّي الْمُرْشِدُ وَالْمُنْعِمُ الْقَيِّمُ. So a رَبِّ is an owner and he is the one with complete authority over its property. He is the one who nurtures his creation, guides it, benefits it by bestowing generous and undeserving gifts upon it, and he is the one who maintains it. So this is who اللَّه is, right? That''s His primary role with His creation, of رَبّ. And all His other attributes, they basically center around and they stem from His رَبُّ الْبَرِيَّةِ. So if someone asks, who is اللَّه? The answer to that question is اللَّه is رَبّ. Now, as for His nature, His nature is الرَّحْمَٰن and الرَّحِيم. So the manner in which He executes, or the way He carries out the functions of His رَبُّ الْبَيَّة, it is through intense and consistent love, compassion and mercy.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'now that we understand these meanings of رب and الرحمن and رحيم now that we understand these terms i want to share with you a beautiful spiritual representation that الله سبحانه وتعالي has created for us through the example of the womb the رحيم to quickly reiterate these terms رب is a combination of six things in classical arabic the definition is a ربه الملك والسيد المربي المرشد والمنعم القيم so a رب is an owner and he is the one with complete authority over its property he is the one who nurtures his creation guides it benefits it by bestowing generous and undeserving gifts upon it and he is the one who maintains it so this is who الله is right thats his primary role with his creation of رب and all his other attributes they basically center around and they stem from his رب البريه so if someone asks who is الله the answer to that question is الله is رب now as for his nature his nature is الرحمن and الرحيم so the manner in which he executes or the way he carries out the functions of his رب البيه it is through intense and consistent love compassion and mercy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 2, NULL, 'So now that we understand these concepts, I want to share this example that اللَّه has created for us through the womb. You know, by studying the womb, we can actually understand a lot about our master''s plan for us. Just by studying the relationship of the womb with its fetus. Because this womb, it is the first رُبَّ of the fetus. And it demonstrates the exact same principles of رَحْمَانِيَّة and رَحِيمِيَّة in its interaction with it. This is why there is a حَدِيثٌ in which رَسُولُ اللَّهِ, he said, this world is a womb for the afterlife. In other words, the story of our lives in this world, it tells a tale about the kind of life that we''re going to have in the afterlife, because this world, this دُنْيَا that we''re living in, is the womb, or acts as the womb, and we are the fetus in that womb. And just as the brief and temporary residence in a womb is actually preparation for this worldly life, our stay in this temporal world is nothing more than a short duration of preparation for the afterlife. Now, if you look at the رَحِيم, the womb, you''ll see all six principles of رُبِّيَ at work. It has ownership and it has authority over the embryo, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'so now that we understand these concepts i want to share this example that الله has created for us through the womb you know by studying the womb we can actually understand a lot about our masters plan for us just by studying the relationship of the womb with its fetus because this womb it is the first رب of the fetus and it demonstrates the exact same principles of رحمانيه and رحيميه in its interaction with it this is why there is a حديث in which رسول الله he said this world is a womb for the afterlife in other words the story of our lives in this world it tells a tale about the kind of life that were going to have in the afterlife because this world this دنيا that were living in is the womb or acts as the womb and we are the fetus in that womb and just as the brief and temporary residence in a womb is actually preparation for this worldly life our stay in this temporal world is nothing more than a short duration of preparation for the afterlife now if you look at the رحيم the womb youll see all six principles of ربي at work it has ownership and it has authority over the embryo right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 3, NULL, 'It nurtures the embryo, it helps the embryo grow and develop into a fetus. So the womb is مَٰلِكِ, it is سَيِّد and it is مُرَبِّي. Then we see that the womb, it bestows these priceless gifts upon the fetus, to the development of its eyes, its nose, its ears, hands, feet, the heart, the intellect and all of its internal and external organs. So we can see that the womb is also the مُنْعِم, the bestower of gifts. We also know that the womb, it manages the entire development process of the embryo from its conception all the way until it is fully developed. So the womb is also قَيِّم. So we can see that the womb, it actually acts as the very first physical رُبَّ that we come in contact with. And this very first act, it actually demonstrates the design of how اللَّه created this mechanism. It demonstrates the act of رُبُوبِيَّة by carrying out all six functions of the definition of the word رَبِّ, right? مَلِكٌ، سَيِّدٌ، مُرَبٍّ، مُرْشِدٌ، مُهَيْمِنٌ، قَيِّمٌ. Now, what happens once the baby is delivered into this world?', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'it nurtures the embryo it helps the embryo grow and develop into a fetus so the womb is ملك it is سيد and it is مربي then we see that the womb it bestows these priceless gifts upon the fetus to the development of its eyes its nose its ears hands feet the heart the intellect and all of its internal and external organs so we can see that the womb is also the منعم the bestower of gifts we also know that the womb it manages the entire development process of the embryo from its conception all the way until it is fully developed so the womb is also قيم so we can see that the womb it actually acts as the very first physical رب that we come in contact with and this very first act it actually demonstrates the design of how الله created this mechanism it demonstrates the act of ربوبيه by carrying out all six functions of the definition of the word رب right ملك سيد مرب مرشد مهيمن قيم now what happens once the baby is delivered into this world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 4, NULL, 'Who is the baby handed over to? It is handed over to its loving mother, who becomes the next immediate رَبّ of that baby. Not the father, the mother. It''s the mother that becomes the next رَبّ. Why? Because she feeds it. She takes care of it. There is this transference of رُبِّيَ that takes place. The mother now takes ownership of the baby. The mother now takes authority over it. The mother assumes the responsibility of nurturing it, helping it grow and develop, teaching it, guiding it, setting it to purpose, showering all these gifts and blessings upon it. She becomes the one who maintains that baby''s sustenance in all its various forms, physical, emotional, psychological.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'who is the baby handed over to it is handed over to its loving mother who becomes the next immediate رب of that baby not the father the mother its the mother that becomes the next رب why because she feeds it she takes care of it there is this transference of ربي that takes place the mother now takes ownership of the baby the mother now takes authority over it the mother assumes the responsibility of nurturing it helping it grow and develop teaching it guiding it setting it to purpose showering all these gifts and blessings upon it she becomes the one who maintains that babys sustenance in all its various forms physical emotional psychological', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 5, NULL, 'So we can see that our mothers become the next immediate رَبِّ. Right after the رُبُوبِيَّة of the womb, the رَحْمَٰن, it''s completed. Now father is also a رَبِّ, but his رُبُوبِيَّة gets executed through the mother. You see, the father always uses the mother as a means for her. He facilitates her functions of رُبُوبِيَّة. That''s the role of the father, but the primary caretaker of the child is always the mother.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'so we can see that our mothers become the next immediate رب right after the ربوبيه of the womb the رحمن its completed now father is also a رب but his ربوبيه gets executed through the mother you see the father always uses the mother as a means for her he facilitates her functions of ربوبيه thats the role of the father but the primary caretaker of the child is always the mother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 6, NULL, 'So now let''s study this حَدِيثٌ to better understand the underlying principles that are at work. So رَسُولُ اللَّهِ , he said, . This temporal world is the womb of the afterlife. So let''s examine the fetus and the womb of its mother. Is it the womb actually doing all the work? Or is it the mother doing all the work behind the scenes and letting this womb act as an intermediary between herself and her child?', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'so now lets study this حديث to better understand the underlying principles that are at work so رسول الله he said this temporal world is the womb of the afterlife so lets examine the fetus and the womb of its mother is it the womb actually doing all the work or is it the mother doing all the work behind the scenes and letting this womb act as an intermediary between herself and her child', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 7, NULL, 'Is it the womb or the mother? We know it''s always the mother, right? The mother is the one taking care of the baby''s needs. She is the one eating all the right things. She is making sure she doesn''t bump into things so that her baby doesn''t get hurt. She''s the one getting all the ultrasounds done, taking all those painful but necessary blood tests, all those injections. So she is the one actually suffering for the baby. Baby is living comfortably in the womb, but it''s the mother doing all the work, right? The mother is the one doing all the hard work all along. But from the perspective of the fetus, who is doing all the work? The womb, not the mother. You see, the fetus has absolutely no knowledge of its mother.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'is it the womb or the mother we know its always the mother right the mother is the one taking care of the babys needs she is the one eating all the right things she is making sure she doesnt bump into things so that her baby doesnt get hurt shes the one getting all the ultrasounds done taking all those painful but necessary blood tests all those injections so she is the one actually suffering for the baby baby is living comfortably in the womb but its the mother doing all the work right the mother is the one doing all the hard work all along but from the perspective of the fetus who is doing all the work the womb not the mother you see the fetus has absolutely no knowledge of its mother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 8, NULL, 'All it knows, all it recognizes, all it understands is the womb. If I ask the fetus, who do you think is feeding you? Who do you think is nurturing you, taking care of you, sustaining you? Who is doing all the work that is necessary for your health and development? What will the fetus reply? The womb. The fetus has absolutely no knowledge of the existence of its mother. You see? What mother? Where''s the mother? I don''t see a mother. All I see is the womb.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'all it knows all it recognizes all it understands is the womb if i ask the fetus who do you think is feeding you who do you think is nurturing you taking care of you sustaining you who is doing all the work that is necessary for your health and development what will the fetus reply the womb the fetus has absolutely no knowledge of the existence of its mother you see what mother wheres the mother i dont see a mother all i see is the womb', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 9, NULL, 'There is no mother. It''s just cause and effect. When I tell this fetus, no, no, it''s not the womb, it''s the mother. She is the one feeding you. She''s the one taking care of you. This womb is only an intermediary. It''s a means. And the fetus says, you know, what are you talking about? It''s the umbilical cord that''s feeding me. That''s what gets me this blood that is carrying all the nutrients. I get fed by that, the umbilical cord. The umbilical cord is responsible for my development.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'there is no mother its just cause and effect when i tell this fetus no no its not the womb its the mother she is the one feeding you shes the one taking care of you this womb is only an intermediary its a means and the fetus says you know what are you talking about its the umbilical cord thats feeding me thats what gets me this blood that is carrying all the nutrients i get fed by that the umbilical cord the umbilical cord is responsible for my development', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 10, NULL, 'There is no mother. And so I explain, no, no, there is a mother. She is all around you. You are within the love, the care, the concern, and the mercy of your mother. This womb wouldn''t exist if she didn''t exist. And this womb that you''re in, it''s actually temporary. This is not the world you were created for. Believe me, this world is filthy, it is dark, it is immensely constricted. There is an amazing and a beautiful world that exists outside this womb that has been created just for you. And that world is so magnificent that you cannot even imagine its glory right now within this womb. Trust me, this womb is filth compared to that world. So if you think this womb is kind and merciful to you, let me tell you, it doesn''t even compare to the love and the mercy of your mother.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'there is no mother and so i explain no no there is a mother she is all around you you are within the love the care the concern and the mercy of your mother this womb wouldnt exist if she didnt exist and this womb that youre in its actually temporary this is not the world you were created for believe me this world is filthy it is dark it is immensely constricted there is an amazing and a beautiful world that exists outside this womb that has been created just for you and that world is so magnificent that you cannot even imagine its glory right now within this womb trust me this womb is filth compared to that world so if you think this womb is kind and merciful to you let me tell you it doesnt even compare to the love and the mercy of your mother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 11, NULL, 'Because your mother is going to take care of you in the next world. She will shower you with so much love that you have absolutely no idea. You cannot even imagine that while you''re in this womb. But the fetus says, what are you talking about? I am really, really happy here. Everything I need is being taken care of for me right here. Why do I need to have another world? I don''t know why you keep talking to me about this mother and another world and an afterlife. There is no mother. There is no world outside this womb. You''re crazy. Okay, show me.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'because your mother is going to take care of you in the next world she will shower you with so much love that you have absolutely no idea you cannot even imagine that while youre in this womb but the fetus says what are you talking about i am really really happy here everything i need is being taken care of for me right here why do i need to have another world i dont know why you keep talking to me about this mother and another world and an afterlife there is no mother there is no world outside this womb youre crazy okay show me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 12, NULL, 'Show me this world that you keep talking about. Show it to me right now. I want to see it. Prove to me that there is another world. Prove to me that there is actually a mother. I''m not gonna believe you unless and until I see that world and until I see that mother. And I say, I can''t show it to you right now, but I promise when you transition out of this world, this womb, you''ll see both of them. Oh, so now I''m supposed to trust you. I''m supposed to trust your belief system, your intellect? What if you''re wrong? Now this is us with اللَّه in this world. There are so many of us denying the existence of the mother, living in the comforts of this womb, of this دُنْيَا.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'show me this world that you keep talking about show it to me right now i want to see it prove to me that there is another world prove to me that there is actually a mother im not gonna believe you unless and until i see that world and until i see that mother and i say i cant show it to you right now but i promise when you transition out of this world this womb youll see both of them oh so now im supposed to trust you im supposed to trust your belief system your intellect what if youre wrong now this is us with الله in this world there are so many of us denying the existence of the mother living in the comforts of this womb of this دنيا', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 13, NULL, 'So now, I begin this logical path of explanation and I say, look, you have been given these eyes, but there is so little to see here. You''ve been given these ears, but there''s so little to hear. You''ve been given taste buds, but there is so little to taste here. You have a nose with this magnificent ability to smell, but there''s not a single fragrance here. You have arms, you have feet, you have all these amazing gifts, but you cannot benefit from them within this womb. So think about it. These are of no use to you inside this womb, which means there must be another world that is out there, a world where you will be able to use and benefit from these gifts. Think about it. Your only purpose in this womb, in this world, is to draw your sustenance from your mother and develop these organs. In other words, you''re here so that you can prepare them for the next world where you will actually be using them, where you will actually benefit from them. But does the fetus understand that?', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'so now i begin this logical path of explanation and i say look you have been given these eyes but there is so little to see here youve been given these ears but theres so little to hear youve been given taste buds but there is so little to taste here you have a nose with this magnificent ability to smell but theres not a single fragrance here you have arms you have feet you have all these amazing gifts but you cannot benefit from them within this womb so think about it these are of no use to you inside this womb which means there must be another world that is out there a world where you will be able to use and benefit from these gifts think about it your only purpose in this womb in this world is to draw your sustenance from your mother and develop these organs in other words youre here so that you can prepare them for the next world where you will actually be using them where you will actually benefit from them but does the fetus understand that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 14, NULL, 'No. It doesn''t. To the fetus, the concept of another world and the existence of a mother is just ridiculous. Just as the concept of a God and an afterlife is absurd to so many of us. So now what happens? This fetus continues to live in its ignorance and its arrogance until the nine months complete. Now what happens? Contractions begin. The fetus starts panicking. What''s going on here? What''s happening? This is what was promised to you.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'no it doesnt to the fetus the concept of another world and the existence of a mother is just ridiculous just as the concept of a god and an afterlife is absurd to so many of us so now what happens this fetus continues to live in its ignorance and its arrogance until the nine months complete now what happens contractions begin the fetus starts panicking whats going on here whats happening this is what was promised to you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 15, NULL, 'I told you this day would come. I told you this world is temporary. So now with those contractions, this beautiful world of the fetus, this magnificent world it was living happily and comfortably in, it starts crumbling around it. It starts falling apart all around it. Now, isn''t that exactly the description of the Day of Judgment? When the earth is shaken up with its earthquakes. And the earth discharges its burden. And man says, what is wrong with this world? What is wrong with this earth? يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا. On this day, it will report the news of which your master has commanded it. ‏يَوْمَئِذٍۢ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًۭا لِّيُرَوْا۟ أَعْمَلَهُمْ ‎.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'i told you this day would come i told you this world is temporary so now with those contractions this beautiful world of the fetus this magnificent world it was living happily and comfortably in it starts crumbling around it it starts falling apart all around it now isnt that exactly the description of the day of judgment when the earth is shaken up with its earthquakes and the earth discharges its burden and man says what is wrong with this world what is wrong with this earth يوميذ تحدث اخبارها بان ربك اوحي لها on this day it will report the news of which your master has commanded it يوميذ يصدر الناس اشتاتا ليروا اعملهم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 16, NULL, 'On this day, people will separate out, and they will be shown the results of their deeds. ‏فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ ‎. So, whoever did an atom''s weight of good will see it. ‏وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍۢ شَرًّۭا يَرَهُۥ ‎. And whoever did an atom''s weight of evil will see it. So the world of the fetus now comes to an end, and it is forced out of it, it is pushed out of it against its will. You see, does the fetus have a choice in whether it wants to stay in the womb or not? No. Whether it wants to or not, whether it''s ready or not, once its time is up, that''s it. It is pushed out into the next world. It dies in the womb in order to be born again in the next world, you see. Its death in the womb results in its creation in this world. That''s what the word انْتَقَلَ means. It comes from نَقَلَ, which means a transference. It also means a copy or a replica. That''s what نَقَلَ means, a copy or a replica.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'on this day people will separate out and they will be shown the results of their deeds فمن يعمل مثقال ذره خيرا يره so whoever did an atoms weight of good will see it ومن يعمل مثقال ذره شرا يره and whoever did an atoms weight of evil will see it so the world of the fetus now comes to an end and it is forced out of it it is pushed out of it against its will you see does the fetus have a choice in whether it wants to stay in the womb or not no whether it wants to or not whether its ready or not once its time is up thats it it is pushed out into the next world it dies in the womb in order to be born again in the next world you see its death in the womb results in its creation in this world thats what the word انتقل means it comes from نقل which means a transference it also means a copy or a replica thats what نقل means a copy or a replica', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 17, NULL, 'Why? Because the next world is going to be a copy, it is going to be a replica of the first. If you did good in the world, in this world, you will find good in the next world. If you did evil in this world, you will find evil in the next world. It''s going to be a replica, it''s going to be a copy. If the fetus has not properly developed its eyes, its ears, its brain, its limbs in the womb of its mother, it is going to suffer the consequences of that in the afterlife of this دُنْيَا. سُبْحَانَ اللَّهِ. So now this temporal world of the fetus is destroyed and it comes into this huge world that he was informed about, this world that was promised to him in the womb. He is now forced into this world, this afterlife that he chose not to believe in. And then, as soon as it''s out of the womb, who is the baby handed to? The mother.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'why because the next world is going to be a copy it is going to be a replica of the first if you did good in the world in this world you will find good in the next world if you did evil in this world you will find evil in the next world its going to be a replica its going to be a copy if the fetus has not properly developed its eyes its ears its brain its limbs in the womb of its mother it is going to suffer the consequences of that in the afterlife of this دنيا سبحان الله so now this temporal world of the fetus is destroyed and it comes into this huge world that he was informed about this world that was promised to him in the womb he is now forced into this world this afterlife that he chose not to believe in and then as soon as its out of the womb who is the baby handed to the mother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 18, NULL, 'سُبْحَانَ اللَّهِ. The mother that he said did not exist, the mother he denied his entire life in the womb. So you can see that the fetus goes through the exact same confusion of the seen and the unseen while it''s in the womb of its mother. That''s so many of us go through in this life. The fetus that accepts the رُبُوبِيَّة of its mother through the womb comes out fully developed and is now capable of enjoying all the benefits that the afterlife has to offer, which is this physical world for the fetus. But the fetus that rejected the رُبُوبِيَّة of the womb, it comes out underdeveloped, blind, deaf, mute, physically challenged, mentally challenged, incapable of benefiting from the joys and pleasures that this world has to offer. We are all going through this exact same process in life. Why? Because الدُّنْيَا رَحِمُ الآخِرَةِ, this world is the womb for the afterlife. And here we have our رَبِّ telling us, look, follow the شَرِيعَة, keep yourself clean, keep yourself pure, do your صَلَاةٌ, complete your fast, pay your زَكَاة, fulfill your obligations of الْحَجّ. And what do we say?', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'سبحان الله the mother that he said did not exist the mother he denied his entire life in the womb so you can see that the fetus goes through the exact same confusion of the seen and the unseen while its in the womb of its mother thats so many of us go through in this life the fetus that accepts the ربوبيه of its mother through the womb comes out fully developed and is now capable of enjoying all the benefits that the afterlife has to offer which is this physical world for the fetus but the fetus that rejected the ربوبيه of the womb it comes out underdeveloped blind deaf mute physically challenged mentally challenged incapable of benefiting from the joys and pleasures that this world has to offer we are all going through this exact same process in life why because الدنيا رحم الاخره this world is the womb for the afterlife and here we have our رب telling us look follow the شريعه keep yourself clean keep yourself pure do your صلاه complete your fast pay your زكاه fulfill your obligations of الحج and what do we say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 19, NULL, 'Why? How is this going to help me? It''s not going to help you here. That''s not the purpose. The obligations of شَرِيعَة is not meant for this world. It''s the sustenance for the development of our spiritual limbs. That''s what شَرِيعَة is. It''s a means like the womb. It''s a tool. It''s a mechanism, a means, an intermediary for the development of our spiritual limbs, for the development of our spiritual organs that are going to help us live a good life. After this world is over, that is where we will benefit from these fully developed spiritual organs. In the afterlife, all we''re doing here in this دُنْيَا is developing them in order to use them in the next world, which is جَنَّة.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'why how is this going to help me its not going to help you here thats not the purpose the obligations of شريعه is not meant for this world its the sustenance for the development of our spiritual limbs thats what شريعه is its a means like the womb its a tool its a mechanism a means an intermediary for the development of our spiritual limbs for the development of our spiritual organs that are going to help us live a good life after this world is over that is where we will benefit from these fully developed spiritual organs in the afterlife all were doing here in this دنيا is developing them in order to use them in the next world which is جنه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 20, NULL, 'But how do you develop them? Through the شَرِيعَة. Because جَنَّة is described as a world that is incredibly beautiful, a world that is governed by a رَبِّ who is intensely merciful, who is constantly merciful. The شَرِيعَة is the umbilical cord providing the sustenance for the development of our spiritual existence, of our spiritual being. Now whether we believe in it or not, whether we want to or not, whether we execute it or not, that next world is inevitable. It''s coming. Right? الْجَنَّةُ حَقٌّ، وَالنَّارُ حَقٌّ، وَالْمَوْتُ حَقٌّ، وَالْبَرْزَخُ حَقٌّ، وَالْمِيزَانُ حَقٌّ، وَالصِّرَاطُ حَقٌّ. Paradise is a reality. Hellfire is a reality. Death is a reality.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'but how do you develop them through the شريعه because جنه is described as a world that is incredibly beautiful a world that is governed by a رب who is intensely merciful who is constantly merciful the شريعه is the umbilical cord providing the sustenance for the development of our spiritual existence of our spiritual being now whether we believe in it or not whether we want to or not whether we execute it or not that next world is inevitable its coming right الجنه حق والنار حق والموت حق والبرزخ حق والميزان حق والصراط حق paradise is a reality hellfire is a reality death is a reality', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 21, NULL, 'Rising from graves is a reality. The scales in which our actions will be weighed, that is a reality. The straight path is a reality. وَأَنَّ ٱلسَّاعَةَ آتِيَةٌۭ لَّا رَيْبَ فِيهَا. And that appointed moment, it is coming. There is absolutely no doubt about it. That is the world in which justice will be exacted. Every incident for which you said, where is justice? On that day we will see justice. The innocent people that suffered momentarily in this short span of life, this دُنْيَا, this world, their momentary suffering will be balanced out with never-ending gifts and pleasures in the afterlife. And the one who caused those sufferings for fleeting gains and pleasures, their pleasures will be counterbalanced with grievous pain and everlasting torment. But that day of judgment is coming. These are all descriptions of the day of judgment, when this universe will be destroyed, this world that we are so comfortable in, it''s going to end. That day is coming when souls will be paired together, when you will finally meet those loved ones', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'rising from graves is a reality the scales in which our actions will be weighed that is a reality the straight path is a reality وان الساعه اتيه لا ريب فيها and that appointed moment it is coming there is absolutely no doubt about it that is the world in which justice will be exacted every incident for which you said where is justice on that day we will see justice the innocent people that suffered momentarily in this short span of life this دنيا this world their momentary suffering will be balanced out with never ending gifts and pleasures in the afterlife and the one who caused those sufferings for fleeting gains and pleasures their pleasures will be counterbalanced with grievous pain and everlasting torment but that day of judgment is coming these are all descriptions of the day of judgment when this universe will be destroyed this world that we are so comfortable in its going to end that day is coming when souls will be paired together when you will finally meet those loved ones', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 22, NULL, 'Who left you behind in this world? And when that little girl who was buried alive will be asked, for what sin were you killed? This is the day where اللَّه will exact justice. This is the day of justice, not this world, not this دُنْيَا that we''re living in. That day all the deeds will open up. And when the book of deeds will be made public, وَإِذَا ٱلسَّمَآءُ كُشِطَتْ. And when the sky will be stripped away, وَإِذَا ٱلْجَحِيمُ سُعِّرَتْ. And when that hellfire is set ablaze, وَإِذَا ٱلْجَنَّةُ أُزْلِفَتْ. And when the paradise is brought near, ‏عَلِمَتْ نَفْسٌۭ مَّآ أَحْضَرَتْ ‎. Every soul will know what it has brought with it. All good will be rewarded on that day and all bad will be punished on that day. اللهُ أَكْبَرُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'who left you behind in this world and when that little girl who was buried alive will be asked for what sin were you killed this is the day where الله will exact justice this is the day of justice not this world not this دنيا that were living in that day all the deeds will open up and when the book of deeds will be made public واذا السماء كشطت and when the sky will be stripped away واذا الجحيم سعرت and when that hellfire is set ablaze واذا الجنه ازلفت and when the paradise is brought near علمت نفس ما احضرت every soul will know what it has brought with it all good will be rewarded on that day and all bad will be punished on that day الله اكبر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 23, NULL, 'And the fact of the matter is that we have such a benevolent, such a merciful, such a loving master who is just dying to reward us for the smallest good deed that we do in this world. You know, it has been narrated by the Prophet that there will be a man on the Day of Judgment and all this man ever did was lend money to others. He was a money lender. And usually such people are black hearted people because of interest, and they use that as a mechanism to gain worldly profit. But when this man sent out his servants to collect the money that people owed him, if the person was having a hard time returning back that money, if that''s what the servant would return and tell him, he would say, forget about it. So on the Day of Judgment, this man comes before اللَّه and he does not have any good deeds to his name, except that he used to do that.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'and the fact of the matter is that we have such a benevolent such a merciful such a loving master who is just dying to reward us for the smallest good deed that we do in this world you know it has been narrated by the prophet that there will be a man on the day of judgment and all this man ever did was lend money to others he was a money lender and usually such people are black hearted people because of interest and they use that as a mechanism to gain worldly profit but when this man sent out his servants to collect the money that people owed him if the person was having a hard time returning back that money if thats what the servant would return and tell him he would say forget about it so on the day of judgment this man comes before الله and he does not have any good deeds to his name except that he used to do that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 24, NULL, 'And اللهُ سُبْحَانَهُ وَتَعَالَى, He displays this man to everyone and He says, will I leave him to be more generous than me? Will I leave this man to be more generous than me? سُبْحَانَ اللَّهِ. He used to forgive people. Do you think I am not going to forgive him today? This is the master, the رَبّ that we fail in our أَبُو ضِيَاء towards. On this day, every single good deed will be balanced with a reward from an immensely beneficent, from an incredibly loving and compassionate master. All our delusions of grandeur in this world, they will be gone. On that day, the مُفْلِسٌ and the غَنِيٌّ, the destitute and the affluent, they will be separated.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'and الله سبحانه وتعالي he displays this man to everyone and he says will i leave him to be more generous than me will i leave this man to be more generous than me سبحان الله he used to forgive people do you think i am not going to forgive him today this is the master the رب that we fail in our ابو ضياء towards on this day every single good deed will be balanced with a reward from an immensely beneficent from an incredibly loving and compassionate master all our delusions of grandeur in this world they will be gone on that day the مفلس and the غني the destitute and the affluent they will be separated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 25, NULL, 'رَسُولُ اللَّهِ once asked his companions. He asked, you know, مَنِ الْمُفْلِسُ? Who is the مُفْلِسٌ? Who is the destitute? They said, المُفْلِسُ مَنْ لَا دِينَارَ وَلَا دِرْهَمَ عِنْدَنَا يَا رَسُولَ اللهِ. The destitute is the one who does not have any درهم or دِينَارٌ to his name. And the Prophet said, no. He said, the greatest destitute of my أُمَّة on the Day of Judgment, the greatest destitute of my أُمَّة on the Day of Judgment, will be the one who comes with all of his prayers and all of his fasting and all of his زَكَاة, وَيَأْتِي قَطْ شَتَمَ هَذَا وَقَذَفَ هَذَا وَأَكَلَ مَالَ هَذَا وَسَفَكَ دَمَ هَذَا وَضَرَبَ هَذَا, but in addition to all of these good deeds, he cheated this one, he lied to this one, he usurped the wealth of this one, he spilled the blood of this one, he struck this one. And so his good deeds will be taken from his account and put into the account of this one and this one and this one. And when his good deeds run out, before justice is fully served, the sins and faults of the remaining victims, they will be taken from their accounts and added to his accounts. And so despite living an entire life full of worship, full of prayers, full of fasting, paying زَكَاة, because of his injustices that he committed with other people, because of the hurt that he caused to other people in this world, this man will have to give up all his good deeds and he will have to take on all the horrible sins of his victims and he will finally be thrown into Hellfire.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'رسول الله once asked his companions he asked you know من المفلس who is the مفلس who is the destitute they said المفلس من لا دينار ولا درهم عندنا يا رسول الله the destitute is the one who does not have any درهم or دينار to his name and the prophet said no he said the greatest destitute of my امه on the day of judgment the greatest destitute of my امه on the day of judgment will be the one who comes with all of his prayers and all of his fasting and all of his زكاه وياتي قط شتم هذا وقذف هذا واكل مال هذا وسفك دم هذا وضرب هذا but in addition to all of these good deeds he cheated this one he lied to this one he usurped the wealth of this one he spilled the blood of this one he struck this one and so his good deeds will be taken from his account and put into the account of this one and this one and this one and when his good deeds run out before justice is fully served the sins and faults of the remaining victims they will be taken from their accounts and added to his accounts and so despite living an entire life full of worship full of prayers full of fasting paying زكاه because of his injustices that he committed with other people because of the hurt that he caused to other people in this world this man will have to give up all his good deeds and he will have to take on all the horrible sins of his victims and he will finally be thrown into hellfire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 26, NULL, 'This person, he said, will be the greatest destitute of my أُمَّة. May اللَّه protect us all from being among these destitutes on the Day of Judgment.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'this person he said will be the greatest destitute of my امه may الله protect us all from being among these destitutes on the day of judgment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the womb of afterlife', 'The Womb Of Afterlife', 27, NULL, 'آخِرُ دَعْوَاهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ he سَيِّدِنَا مُحَمَّدٍ خَاتِمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ وَعَلَى أَخِيهِ وَوَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِمَا الطَّيِّبِينَ الطَّاهِرِينَ وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ الْفَاتِحَة.', '', 'آخِرُ دَعْوَاهُمْ أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتِمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ وَعَلَى أَخِيهِ وَوَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِمَا الطَّيِّبِينَ الطَّاهِرِينَ وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ الْفَاتِحَة', NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'اخر دعواهم ان الحمد لله رب العالمين والصلاه والسلام علي رسوله he سيدنا محمد خاتم النبيين وسيد المرسلين وعلي اخيه ووصيه علي بن ابي طالب اشرف الوصيين وعلي الايمه من ذريتهما الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه', 'اخر دعواهم ان الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد خاتم النبيين وسيد المرسلين وعلي اخيه ووصيه علي بن ابي طالب اشرف الوصيين وعلي الايمه من ذريتهما الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 0, NULL, 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ', '', 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ', NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي السلام عليكم ورحمه الله وبركاته', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي السلام عليكم ورحمه الله وبركاته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 1, NULL, 'Now that we understand the linguistic meanings of the basic terms that I''ve explained so far in these sessions, now it''s time to start with the بَسْمَلَة, which is actually the first verse of سُورَةُ الْفَاتِحَةِ, ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎. So Arabs had this way of shortening these commonly repeated statements. So if they wanted to refer to ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, they would, instead of saying the statement completely, they would just shorten it down to بَسْمَلَة, right? And so, for example, لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ, they just simply would call it حَوْقَلَة. Similarly, they would use الْحَمْدُ لِلَّهِ for ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎, and so on. So the term ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, it actually refers to the first verse of سُورَةُ الْفَاتِحَةِ, which is ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'now that we understand the linguistic meanings of the basic terms that ive explained so far in these sessions now its time to start with the بسمله which is actually the first verse of سوره الفاتحه بسم الله الرحمن الرحيم so arabs had this way of shortening these commonly repeated statements so if they wanted to refer to بسم الله الرحمن الرحيم they would instead of saying the statement completely they would just shorten it down to بسمله right and so for example لا حول ولا قوه الا بالله they just simply would call it حوقله similarly they would use الحمد لله for الحمد لله رب العلمين and so on so the term بسم الله الرحمن الرحيم it actually refers to the first verse of سوره الفاتحه which is بسم الله الرحمن الرحيم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 2, NULL, 'Now, today what I want to focus on is this concept of being and attributes, because اللَّه is a being, He''s an entity, and then He has all these various attributes. And this is quite a complicated topic, so, you know, I tried to make it as simple as possible, but there are literally books written on this, so it''s very difficult to condense this huge topic. But if you look at the statement of ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ from a grammatical point of view, you''ll see that in the context of mentioning اللَّه, it uses a noun and it uses two adjectives, right? The word اللَّه in بِسْمِ اللَّهِ, the word اللَّه is a noun representing an entity, a being, and then you have two attributes of رَحْمَة, الرَّحْمَٰن, الرَّحِيمِ, right? These are the adjectives or the attributes describing the nature of اللَّه, that He is اللَّه and His nature is الرَّحْمَٰن and رَحِيم.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'now today what i want to focus on is this concept of being and attributes because الله is a being hes an entity and then he has all these various attributes and this is quite a complicated topic so you know i tried to make it as simple as possible but there are literally books written on this so its very difficult to condense this huge topic but if you look at the statement of بسم الله الرحمن الرحيم from a grammatical point of view youll see that in the context of mentioning الله it uses a noun and it uses two adjectives right the word الله in بسم الله the word الله is a noun representing an entity a being and then you have two attributes of رحمه الرحمن الرحيم right these are the adjectives or the attributes describing the nature of الله that he is الله and his nature is الرحمن and رحيم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 3, NULL, 'So let''s talk about this distinction between اللَّه''s name and His attributes, which is essentially the distinction between the concepts of a noun and adjectives if you look at it from a grammatical point of view. Attributes or adjectives are tools that have been provided to us by language in order for us to understand something. In other words, it is through the combination of these two things, noun and adjectives, or name and attributes, that we actually understand an entity, right? So if you want to gain a complete understanding of an entity, you need to understand its attributes. In the Arabic language, this is called ذَاتٌ وَصِفَاتٌ, being and attributes.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so lets talk about this distinction between اللهs name and his attributes which is essentially the distinction between the concepts of a noun and adjectives if you look at it from a grammatical point of view attributes or adjectives are tools that have been provided to us by language in order for us to understand something in other words it is through the combination of these two things noun and adjectives or name and attributes that we actually understand an entity right so if you want to gain a complete understanding of an entity you need to understand its attributes in the arabic language this is called ذات وصفات being and attributes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 4, NULL, 'So for instance, we have a soul and we have a body, which together constitute our ذَات, our being. But then soul has certain spiritual attributes, right? It can be kind, it can be brave, intelligent, generous, or it can be weak, it can be coward, it can be dumb, right? In the same way, the body has its own set of physical attributes: fat, thin, black, brown, white, tall, short. And once we understand these spiritual and physical attributes that are describing the entity, which is the soul or the body, we essentially come to recognize the nature of that being.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so for instance we have a soul and we have a body which together constitute our ذات our being but then soul has certain spiritual attributes right it can be kind it can be brave intelligent generous or it can be weak it can be coward it can be dumb right in the same way the body has its own set of physical attributes fat thin black brown white tall short and once we understand these spiritual and physical attributes that are describing the entity which is the soul or the body we essentially come to recognize the nature of that being', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 5, NULL, 'So the union of the two, they provide the identity and a complete description of that identity, which then enables our intellects to understand the nature of that being. But the thing is, attributes cannot exist without the being, right? It is the ذَات that gives existence to the صِفَاتْ. Attributes can only exist after the existence of the being itself. So if there is no اللَّه, there cannot be a الرَّحْمَٰن and رَحِيم. So that is why the name اللَّه is greater in its rank than a الرَّحْمَٰن or رَحِيم on the basis of its precedence.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so the union of the two they provide the identity and a complete description of that identity which then enables our intellects to understand the nature of that being but the thing is attributes cannot exist without the being right it is the ذات that gives existence to the صفات attributes can only exist after the existence of the being itself so if there is no الله there cannot be a الرحمن and رحيم so that is why the name الله is greater in its rank than a الرحمن or رحيم on the basis of its precedence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 6, NULL, 'So now if we start breaking down the statement of the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, the term اللَّه points to His ذَات, to His being. You know, He is a deity named اللَّه. اللَّه is the title of His essence. As He says in the Quran, ‏إِنَّنِىٓ أَنَا ٱللَّهُ لَآ إِلَهَ إِلَّآ أَنَا۠ فَٱعْبُدْنِى وَأَقِمِ ٱلصَّلَوٰةَ لِذِكْرِىٓ ‎, no doubt I am اللَّه, and there is no one worthy of worship and obedience except Me. Now this noun اللَّه has adjectives, which are His 99 صِفَةُ سُورَةِ الفَاتِحَةِ, His attributes describing the nature of اللَّه, right? These are His various manifestations in His interactions with creation.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so now if we start breaking down the statement of the بسم الله الرحمن الرحيم the term الله points to his ذات to his being you know he is a deity named الله الله is the title of his essence as he says in the quran انني انا الله لا اله الا انا فاعبدني واقم الصلوه لذكري no doubt i am الله and there is no one worthy of worship and obedience except me now this noun الله has adjectives which are his 99 صفه سوره الفاتحه his attributes describing the nature of الله right these are his various manifestations in his interactions with creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 7, NULL, 'So now you have الرَّحْمَٰن, الرَّحِيم, المَلِك, الْقُدُّوسُ, السَّلَام, الْمُؤْمِن, الْمُؤْمِن, الْعَزِيزُ, الْجَبَّار, الْمُتَكَبِّرُ, الْخَالِقُ, الْبَارِئ, الْمُصَوِّر, الْغَفَّار, الْقَهَّار, الْوَهَّابُ, الْفَاتِحَة, الْعَلِيمُ, الْكَابِدُ, الْبَاسِطُ, الْخَافِضُ, اَلْفَاتِحَة, الْمُعِزُّ, الْمُذِلُّ, السَّامِر, الْبَصِيرُ, الْحَكَمُ, الْحَكِيم, الْعَدْل, اَللَّطِيفُ, الْحَلِيم, الْكَبِيرُ, الْعَظِيم, الْغَفُورُ, ٱلْعَلِىُّ ٱلْكَبِيرُ, الْحَافِظ, الْحَسِيبُ, الْكَرِيم,', '', 'الرَّحْمَٰن الرَّحِيم المَلِك الْقُدُّوسُ السَّلَام الْمُؤْمِن الْمُؤْمِن الْعَزِيزُ الْجَبَّار الْمُتَكَبِّرُ الْخَالِقُ الْبَارِئ الْمُصَوِّر الْغَفَّار الْقَهَّار الْوَهَّابُ الْفَاتِحَة الْعَلِيمُ الْكَابِدُ الْبَاسِطُ الْخَافِضُ اَلْفَاتِحَة الْمُعِزُّ الْمُذِلُّ السَّامِر الْبَصِيرُ الْحَكَمُ الْحَكِيم الْعَدْل اَللَّطِيفُ الْحَلِيم الْكَبِيرُ الْعَظِيم الْغَفُورُ ٱلْعَلِىُّ ٱلْكَبِيرُ الْحَافِظ الْحَسِيبُ الْكَرِيم', NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so now you have الرحمن الرحيم الملك القدوس السلام المومن المومن العزيز الجبار المتكبر الخالق الباري المصور الغفار القهار الوهاب الفاتحه العليم الكابد الباسط الخافض الفاتحه المعز المذل السامر البصير الحكم الحكيم العدل اللطيف الحليم الكبير العظيم الغفور العلي الكبير الحافظ الحسيب الكريم', 'الرحمن الرحيم الملك القدوس السلام المومن المومن العزيز الجبار المتكبر الخالق الباري المصور الغفار القهار الوهاب الفاتحه العليم الكابد الباسط الخافض الفاتحه المعز المذل السامر البصير الحكم الحكيم العدل اللطيف الحليم الكبير العظيم الغفور العلي الكبير الحافظ الحسيب الكريم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 8, NULL, 'المُقِيم, الرَّقِيبُ, الْجَلِيلُ, الْمُجِيبُ, الْوَسِيرْ, الْوَدُود, الْمَجِيد, الْبَاعِثُ, الشَّهِيدُ, الْوَكِيل, اَلْكَاوِي, المَتِين, الْوَلِيُّ, الْحَمِيدُ, الْمُحْصِي, الْمُبْدِي, المُعِيدُ, الْمُحْيِي, الْمُمِيءُ, الْحَيُّ, الْقَيُّوم, الْوَاجِدُ, الْمَجِيد, الْوَاحِدُ, الصَّمَدُ, الْقَاضِيل, الْمُقْتَدِرُ, الْمُقَدِّم, الْمُؤَخِّر, الْأَوَّلُ, الآخِرُ, الظَّاهِرُ, الْبَاطِنُ, الْوَلِيُّ, الْمُتَعَالِي, الْبِرُّ, التَّوَّاب, الْمُنْتَقِمُ, الْعَفُوّ, الرَّؤُوفُ, المَلِك, الْمُلْك, ذُو الْجَلَالِ, وَلِيُّ كَرَمٍ, الْمُقْسِطُ, الْجَامِعَة, الْغَنِيُّ, الْمُكْنِي, المَنِيَّة, أَذْدَر, النَّفِير, النُّور, الْهَادِي, البَادِر, البَاقِي, الوَارِف, الرَّشِيدُ, الصَّبُورُ, الْحَنَّانُ, الْمَنَّانُ, الدَّيَّانُ, البُرْهَان.', '', 'المُقِيم الرَّقِيبُ الْجَلِيلُ الْمُجِيبُ الْوَسِيرْ الْوَدُود الْمَجِيد الْبَاعِثُ الشَّهِيدُ الْوَكِيل اَلْكَاوِي المَتِين الْوَلِيُّ الْحَمِيدُ الْمُحْصِي الْمُبْدِي المُعِيدُ الْمُحْيِي الْمُمِيءُ الْحَيُّ الْقَيُّوم الْوَاجِدُ الْمَجِيد الْوَاحِدُ الصَّمَدُ الْقَاضِيل الْمُقْتَدِرُ الْمُقَدِّم الْمُؤَخِّر الْأَوَّلُ الآخِرُ الظَّاهِرُ الْبَاطِنُ الْوَلِيُّ الْمُتَعَالِي الْبِرُّ التَّوَّاب الْمُنْتَقِمُ الْعَفُوّ الرَّؤُوفُ المَلِك الْمُلْك ذُو الْجَلَالِ وَلِيُّ كَرَمٍ الْمُقْسِطُ الْجَامِعَة الْغَنِيُّ الْمُكْنِي المَنِيَّة أَذْدَر النَّفِير النُّور الْهَادِي البَادِر البَاقِي الوَارِف الرَّشِيدُ الصَّبُورُ الْحَنَّانُ الْمَنَّانُ الدَّيَّانُ البُرْهَان', NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'المقيم الرقيب الجليل المجيب الوسير الودود المجيد الباعث الشهيد الوكيل الكاوي المتين الولي الحميد المحصي المبدي المعيد المحيي المميء الحي القيوم الواجد المجيد الواحد الصمد القاضيل المقتدر المقدم الموخر الاول الاخر الظاهر الباطن الولي المتعالي البر التواب المنتقم العفو الرووف الملك الملك ذو الجلال ولي كرم المقسط الجامعه الغني المكني المنيه اذدر النفير النور الهادي البادر الباقي الوارف الرشيد الصبور الحنان المنان الديان البرهان', 'المقيم الرقيب الجليل المجيب الوسير الودود المجيد الباعث الشهيد الوكيل الكاوي المتين الولي الحميد المحصي المبدي المعيد المحيي المميء الحي القيوم الواجد المجيد الواحد الصمد القاضيل المقتدر المقدم الموخر الاول الاخر الظاهر الباطن الولي المتعالي البر التواب المنتقم العفو الرووف الملك الملك ذو الجلال ولي كرم المقسط الجامعه الغني المكني المنيه اذدر النفير النور الهادي البادر الباقي الوارف الرشيد الصبور الحنان المنان الديان البرهان');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 9, NULL, 'So now, these are all these attributes that describe the nature of اللَّه. And to use the example of the prism and the light that I stated in one of the previous sessions, now you can think of اللَّه, as the term اللَّه, as one pure light, right? He is the light of the heavens and the earth. Now, when this pure light of the name اللَّه comes into the physical realm, His divine attributes refract within creation. The light of اللَّه splits into these 99 attributes within His creation.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so now these are all these attributes that describe the nature of الله and to use the example of the prism and the light that i stated in one of the previous sessions now you can think of الله as the term الله as one pure light right he is the light of the heavens and the earth now when this pure light of the name الله comes into the physical realm his divine attributes refract within creation the light of الله splits into these 99 attributes within his creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 10, NULL, 'So now we get all these different manifestations of اللَّه''s essence based on His interaction with His creation. So in one instance we see that اللَّه is كَرِيم, He is generous, but then in another instance we see He is جَبَّار, the compeller. In another instance we see He is أَحَرْ, the subduer. In another we see that He is الْعَزِيزُ, the powerful. In another we see He is مُسِيل, the one who humbles, but then He''s also اَلْمُعَوِّ...', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so now we get all these different manifestations of اللهs essence based on his interaction with his creation so in one instance we see that الله is كريم he is generous but then in another instance we see he is جبار the compeller in another instance we see he is احر the subduer in another we see that he is العزيز the powerful in another we see he is مسيل the one who humbles but then hes also المعو', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 11, NULL, 'الْفَاتِحَة, is the one who bestows honor. So His essence manifests through all these different attributes within creation.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'الفاتحه is the one who bestows honor so his essence manifests through all these different attributes within creation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 12, NULL, 'This world then becomes a theater for the divine manifestation of اللَّه''s attributes, enabling us to know who اللَّه is, not directly through His essence, but through the refraction of His attributes and His creations. This is why it is said, لَا تَفَكُّرَ فِي اللهِ، وَلَكِنْ تَفَكَّرْ فِي خَلْقِ اللهِ, do not reflect upon اللَّه, but rather reflect upon the creations of اللَّه. Why?', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'this world then becomes a theater for the divine manifestation of اللهs attributes enabling us to know who الله is not directly through his essence but through the refraction of his attributes and his creations this is why it is said لا تفكر في الله ولكن تفكر في خلق الله do not reflect upon الله but rather reflect upon the creations of الله why', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 13, NULL, 'Because it is creation, it is nature that manifests all of His attributes for us. So if you want to understand اللَّه, look outside yourself and look within yourself. We will keep showing them our signs within their own, within the horizons and within their own souls, until it becomes perfectly clear to them that all of this is from الْحَقّ.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'because it is creation it is nature that manifests all of his attributes for us so if you want to understand الله look outside yourself and look within yourself we will keep showing them our signs within their own within the horizons and within their own souls until it becomes perfectly clear to them that all of this is from الحق', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 14, NULL, 'But then اللَّه is infinite, and so are His attributes. This is why, when we attempt to understand اللَّه, we get bewildered by His attributes, because in a sense we cannot know what God is any more than we can know what God isn''t. You see, because when we speak about اللَّه, we are speaking about this infinite creator of the heavens and the earth. And the word infinite means without a limit. Now, the word in Arabic for definition is the same word that we use for a limitation or a boundary. A definition is what defines or gives finiteness to something, a concept. It limits it, it demarcates it, it puts it into perspective. So when we talk about اللَّهُ سُبْحَانَهُ وَتَعَالَى, we cannot define God. Because to define Him would mean to give Him a حُطّ, a boundary, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'but then الله is infinite and so are his attributes this is why when we attempt to understand الله we get bewildered by his attributes because in a sense we cannot know what god is any more than we can know what god isnt you see because when we speak about الله we are speaking about this infinite creator of the heavens and the earth and the word infinite means without a limit now the word in arabic for definition is the same word that we use for a limitation or a boundary a definition is what defines or gives finiteness to something a concept it limits it it demarcates it it puts it into perspective so when we talk about الله سبحانه وتعالي we cannot define god because to define him would mean to give him a حط a boundary right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 15, NULL, 'We would have to place Him in a limit, which is impossible, because, you know, He is without any limit. The way the intellect works, أَقَالَ means to create a boundary. Right? That''s the only way human intellect works. That''s the only way we know how to grasp or understand something, by creating a boundary, by creating a limit. And اللَّه cannot be limited. And this is why scholars say that all of عَقِيدَة, this concept of creed, it can be reduced into two statements. He is unlike anything. لَا يُشْبِهُ ذَاتَهُ الذَّوَاتُ وَلَا مُعَطَّلَةٌ تُوصَفُ الصِّفَاتُ. That His essence is not like any other essence, and His attributes are not in any way metaphorical. He is الْغَنِيُّ عَنِ الْجَمِيعِ وَالْجَمِيعُ مُفْتَقِرٌ إِلَيْهِ. He has no need of anyone, and everyone is in need of Him. So this statement actually negates need for اللَّه and it enforces need for the rest of creation. It negates independence for us.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'we would have to place him in a limit which is impossible because you know he is without any limit the way the intellect works اقال means to create a boundary right thats the only way human intellect works thats the only way we know how to grasp or understand something by creating a boundary by creating a limit and الله cannot be limited and this is why scholars say that all of عقيده this concept of creed it can be reduced into two statements he is unlike anything لا يشبه ذاته الذوات ولا معطله توصف الصفات that his essence is not like any other essence and his attributes are not in any way metaphorical he is الغني عن الجميع والجميع مفتقر اليه he has no need of anyone and everyone is in need of him so this statement actually negates need for الله and it enforces need for the rest of creation it negates independence for us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 16, NULL, 'Now, here is where we get into another central problem with religion, and that is the problem of transcendence and immanence. Transcendence is when we speak about God without anything, you know, any reference in this world that can guide us to Him. There is nothing in the world for which we can say, you know, that is God or this is like God, because اللَّه is above and beyond anything they ascribe to. So when we talk about transcendence, we''re talking about اللَّه being above and beyond everything that we know of, right? That''s why we say سُبْحَانَكَ, which is in Arabic the word, it means transcendence, and it comes from which means to purify, to get rid of filth, you know, to transcend something, to be above and beyond something. So اللَّه is transcendent.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'now here is where we get into another central problem with religion and that is the problem of transcendence and immanence transcendence is when we speak about god without anything you know any reference in this world that can guide us to him there is nothing in the world for which we can say you know that is god or this is like god because الله is above and beyond anything they ascribe to so when we talk about transcendence were talking about الله being above and beyond everything that we know of right thats why we say سبحانك which is in arabic the word it means transcendence and it comes from which means to purify to get rid of filth you know to transcend something to be above and beyond something so الله is transcendent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 17, NULL, 'But then pure transcendence has a lot of problems by itself. Because then now اللَّه becomes the God of the scientist. Like Einstein believed in a God, but he did not believe in a personal God, right? He believed in a transcendent God. The God he believed in was the God of the deist, who has nothing to do with his creation. And then that again creates a major problem. But then there is also this concept of immanence, the idea of God being close to us in the world. So for example, like in Hinduism, right, the Brahman class, they don''t really believe in idols. You know, we generally, when we think of a Hindu, we think they are idol worshipers, but this class of Brahmans, right, they don''t really believe in idols.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'but then pure transcendence has a lot of problems by itself because then now الله becomes the god of the scientist like einstein believed in a god but he did not believe in a personal god right he believed in a transcendent god the god he believed in was the god of the deist who has nothing to do with his creation and then that again creates a major problem but then there is also this concept of immanence the idea of god being close to us in the world so for example like in hinduism right the brahman class they dont really believe in idols you know we generally when we think of a hindu we think they are idol worshipers but this class of brahmans right they dont really believe in idols', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 18, NULL, 'It''s really a kind of trick to help all these stupid people of the lower class that they believe, who they feel that still need to evolve. So there''s this understanding in their tradition that the lower classes, or the caste system that they have, which they call the varna. So if you''re in a lesser varna, you cannot understand the Brahma. That''s what they believe, because he has gone through several lifetimes to get this ability to perceive. And it is something that only he can perceive, and only he can understand the Godhead, as they call it. Right, so Brahma understands the God that has no attribute, which they call the nirguna. But they have this idea that the lower class people actually need to see something in order to understand God, and so they gave them all these idols. It''s the Brahman class that gave idols, this concept of idols, to the lower classes, to the lower varna, who they actually knew were not gods. But they thought that it helps the common people understand God. And this is the problem of immanence in religion, which is creating likeness for God. You understand?', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'its really a kind of trick to help all these stupid people of the lower class that they believe who they feel that still need to evolve so theres this understanding in their tradition that the lower classes or the caste system that they have which they call the varna so if youre in a lesser varna you cannot understand the brahma thats what they believe because he has gone through several lifetimes to get this ability to perceive and it is something that only he can perceive and only he can understand the godhead as they call it right so brahma understands the god that has no attribute which they call the nirguna but they have this idea that the lower class people actually need to see something in order to understand god and so they gave them all these idols its the brahman class that gave idols this concept of idols to the lower classes to the lower varna who they actually knew were not gods but they thought that it helps the common people understand god and this is the problem of immanence in religion which is creating likeness for god you understand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 19, NULL, 'The way Christianity deals with this problem is obviously through Jesus, because Jesus becomes this incarnation of God, right? God enters into flesh. And in our tradition this is what is called حُلُول, where God enters the flesh, and some of the deviant Sufis, they actually claim the state. So this is not something specific to Christianity. You know, we know that there was a group called نُصِرَ that claimed divinity for مَوْلَانَا عَلِيّ.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'the way christianity deals with this problem is obviously through jesus because jesus becomes this incarnation of god right god enters into flesh and in our tradition this is what is called حلول where god enters the flesh and some of the deviant sufis they actually claim the state so this is not something specific to christianity you know we know that there was a group called نصر that claimed divinity for مولانا علي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 20, NULL, 'And it actually also happened for إِمَامٌ جَعْفَرٌ صَادِقٌ and other Imams as well. So now, how do we understand this concept of immanence in our religion? What is the relationship between transcendence and immanence? تَنْزِيهٌ and تَجْرِيد? Because you do need an access to your master, right? If you have a completely transcendent God, he becomes this cold, distant, uncaring, unloving God. On the other hand, if you give God the attributes of creation, you now have a whole new problem, and that''s what gives birth to these concepts of anthropomorphism, falling into this idea that God is petulant, that God has emotions, that God has anger, that he has pleasure in an anthropomorphic way. And this is something that, you know, penetrates the Muslim understanding as well. There are Muslims who think that when these words are used in the Hadith or the Quran, so for example when اللَّه says the one who faced the anger of اللَّه, they think that اللَّه''s anger is like our anger, that اللَّه becomes angry in an emotional sense. And that''s not true, because اللَّه is above and beyond anything that is ascribed to him. But we do believe that غَضَب has a meaning, and we believe that رِضًا has a meaning. You know, we believe that these words that اللَّه used in the Quran, like رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ, they were pleased with اللَّه and اللَّه was pleased with them. But don''t think your pleasure with اللَّه is the same as اللَّه''s pleasure with you. Don''t think those two words mean the same thing. In the context they are being used, each means a specific thing in relation to that thing that it is predicating. So when we talk about the attributes of اللَّهُ سُبْحَانَهُ وَتَعَالَى, we have to be extremely careful. When we try to create an understanding of these attributes, we have to be extremely careful, because we in a sense can only say about اللَّه what اللَّه has said about Himself. We cannot, you know, any description that اللَّه needed for our understanding, He described it Himself in the Quran. But then now here we enter into another problem, which is the problem of interpretation. Because even though اللَّه is telling us things about Himself in the Quran, even though He is self-disclosing to us, He is self-disclosing through language.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'and it actually also happened for امام جعفر صادق and other imams as well so now how do we understand this concept of immanence in our religion what is the relationship between transcendence and immanence تنزيه and تجريد because you do need an access to your master right if you have a completely transcendent god he becomes this cold distant uncaring unloving god on the other hand if you give god the attributes of creation you now have a whole new problem and thats what gives birth to these concepts of anthropomorphism falling into this idea that god is petulant that god has emotions that god has anger that he has pleasure in an anthropomorphic way and this is something that you know penetrates the muslim understanding as well there are muslims who think that when these words are used in the hadith or the quran so for example when الله says the one who faced the anger of الله they think that اللهs anger is like our anger that الله becomes angry in an emotional sense and thats not true because الله is above and beyond anything that is ascribed to him but we do believe that غضب has a meaning and we believe that رضا has a meaning you know we believe that these words that الله used in the quran like رضي الله عنهم ورضوا عنه they were pleased with الله and الله was pleased with them but dont think your pleasure with الله is the same as اللهs pleasure with you dont think those two words mean the same thing in the context they are being used each means a specific thing in relation to that thing that it is predicating so when we talk about the attributes of الله سبحانه وتعالي we have to be extremely careful when we try to create an understanding of these attributes we have to be extremely careful because we in a sense can only say about الله what الله has said about himself we cannot you know any description that الله needed for our understanding he described it himself in the quran but then now here we enter into another problem which is the problem of interpretation because even though الله is telling us things about himself in the quran even though he is self disclosing to us he is self disclosing through language', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 21, NULL, 'And language is filtered through the human mind. And the human mind has the capacity to interpret what is being said in so many different ways. So now we have a whole new set of problems. And this is why we stick to the Prophet and his واسع, right? Because they are the purest filter for us. And they''re still a filter, right? The Prophet صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ is also a filter, but he is the purest filter. And this is why the prophets have a capacity that other human beings do not have, and that is that, you know, اللَّهُ سُبْحَانَهُ وَتَعَالَى has chosen them to be these filters for revelation. And that is why the best understanding of اللَّهُ سُبْحَانَهُ وَتَعَالَى is the understanding that our Prophet صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ has articulated to us. And this is what he said, اللَّهُمَّ لَا نُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ. O اللَّه, we are unable to praise you. You are as you praised yourself. In other words, I cannot truly praise you. Because one of the reasons that we praise is based on our knowledge of the praiseworthy, right? If you don''t know the qualities of someone or something, you cannot really praise it. You cannot really praise them.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'and language is filtered through the human mind and the human mind has the capacity to interpret what is being said in so many different ways so now we have a whole new set of problems and this is why we stick to the prophet and his واسع right because they are the purest filter for us and theyre still a filter right the prophet صلي الله عليه وسلم is also a filter but he is the purest filter and this is why the prophets have a capacity that other human beings do not have and that is that you know الله سبحانه وتعالي has chosen them to be these filters for revelation and that is why the best understanding of الله سبحانه وتعالي is the understanding that our prophet صلي الله عليه وسلم has articulated to us and this is what he said اللهم لا نحصي ثناء عليك انت كما اثنيت علي نفسك o الله we are unable to praise you you are as you praised yourself in other words i cannot truly praise you because one of the reasons that we praise is based on our knowledge of the praiseworthy right if you dont know the qualities of someone or something you cannot really praise it you cannot really praise them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 22, NULL, 'And this is why in اللَّه''s self-disclosure to us, He is describing for us the reasons why He is praiseworthy, the reasons why He is a حَمِيدٌ. He has described to us, explained to us in the Quran the praiseworthy attributes that He has and why. This is how understanding the attributes of اللَّه enables us to come to know اللَّه. But these attributes are known to us through our human experience. And that''s where you get into the problem of immanence. You know, there has to be some correlation between what we understand about اللَّه and what we understand about ourselves, or what we see in the world, because otherwise we just simply cannot know اللَّه. It just wouldn''t be possible. And so in dealing with the attributes of اللَّه, you are still working with things in this world, you see.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'and this is why in اللهs self disclosure to us he is describing for us the reasons why he is praiseworthy the reasons why he is a حميد he has described to us explained to us in the quran the praiseworthy attributes that he has and why this is how understanding the attributes of الله enables us to come to know الله but these attributes are known to us through our human experience and thats where you get into the problem of immanence you know there has to be some correlation between what we understand about الله and what we understand about ourselves or what we see in the world because otherwise we just simply cannot know الله it just wouldnt be possible and so in dealing with the attributes of الله you are still working with things in this world you see', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 23, NULL, 'So when we say اللَّه سُبْحَانَهُ وَتَعَالَى is, for instance, قَدِيم, right? And قَدِيم becomes a problematic word because it''s a technical word. It is not found in the Quran. It is not actually an attribute of اللَّه. It''s more of a technical word. قِدَم is what they call a سُورَةُ الْفَاتِحَةِ attribute, because it negates حَدِيث.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so when we say الله سبحانه وتعالي is for instance قديم right and قديم becomes a problematic word because its a technical word it is not found in the quran it is not actually an attribute of الله its more of a technical word قدم is what they call a سوره الفاتحه attribute because it negates حديث', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 24, NULL, 'I know this is getting complicated, but basically it negates occurrence. That''s what قَدِيم means. It negates occurrence, it negates the fact that اللَّهُ سُبْحَانَهُ وَتَعَالَى is حَدَثَ, that He came into existence. No, اللَّه did not come into existence. The idea of قِدَمٌ is that اللَّهُ سُبْحَانَهُ وَتَعَالَى is as He always was and He will always continue to be the same way, without any change or any time factor. And this is where pre-eternity becomes the best word in English that we can use. When we say pre-eternity, I don''t even know what that means. I really don''t. But it''s a word that, I mean, how can you describe pre-eternity? You cannot even describe eternity, because eternity means forever. And so how do you use pre with eternity? How can there be something before that is eternal, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'i know this is getting complicated but basically it negates occurrence thats what قديم means it negates occurrence it negates the fact that الله سبحانه وتعالي is حدث that he came into existence no الله did not come into existence the idea of قدم is that الله سبحانه وتعالي is as he always was and he will always continue to be the same way without any change or any time factor and this is where pre eternity becomes the best word in english that we can use when we say pre eternity i dont even know what that means i really dont but its a word that i mean how can you describe pre eternity you cannot even describe eternity because eternity means forever and so how do you use pre with eternity how can there be something before that is eternal right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 25, NULL, 'So I really don''t know what that word means. I cannot. I have a sense of what that word means, but I cannot really describe it. But that''s the word that, that at best what we have come up with as a way of describing اللَّه''s existence. سُبْحَانَ اللَّهِ. So you can see that we run into all these problems when we try to understand اللَّهُ سُبْحَانَهُ وَتَعَالَى. And so مَوْلَانَا عَلِيٌّ عَلَيْهِ السَّلَامُ, he gave us this simple, simple formula for recognition of اللَّه, which is الْعَجْزُ عَنْ دَرَكِ الْإِدْرَاكِ إِدْرَاكٌ. Well, بَحْثُ أَنْزَتِهِ كُفْرٌ وَإِشْرَاقٌ. My inability to recognize اللَّه is recognizing اللَّه. My inability to recognize اللَّه, my inability of my intellectual powers to create a boundary, to create a definition around اللَّه, the meaning of اللَّه, the understanding of اللَّه, is recognizing Him. And any attempt to discuss His essence, it will inevitably result in assigning and attributing partners with Him, creating likeness for Him. So accepting our inability to know اللَّه is our true recognition of Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so i really dont know what that word means i cannot i have a sense of what that word means but i cannot really describe it but thats the word that that at best what we have come up with as a way of describing اللهs existence سبحان الله so you can see that we run into all these problems when we try to understand الله سبحانه وتعالي and so مولانا علي عليه السلام he gave us this simple simple formula for recognition of الله which is العجز عن درك الادراك ادراك well بحث انزته كفر واشراق my inability to recognize الله is recognizing الله my inability to recognize الله my inability of my intellectual powers to create a boundary to create a definition around الله the meaning of الله the understanding of الله is recognizing him and any attempt to discuss his essence it will inevitably result in assigning and attributing partners with him creating likeness for him so accepting our inability to know الله is our true recognition of him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 26, NULL, 'And this is why the most essential act in worship in Islam is the act of سِجْدَة, putting our intellects on the ground and surrendering its capacity to recognize اللَّه. Now, Quran gives us an incredibly concise statement to help us understand اللَّه. Because the way in which we understand this world around us is through things, right? The Arabic word for a thing is سُورَةُ الْفَاتِحَة, right? The word سُورَةُ الْفَاتِحَة, it means thing, and this word, it comes from شَاءَ, which means will, the will of اللَّه. Everything, every being, every ذَات that exists in this world has its own individual set of attributes, right? Every noun has its adjectives, all of which points to what they point to, the مَنْ شَاءَ, to the will and the purpose of their creator. So every سُورَةُ الْفَاتِحَة is a ذَات, it''s a being, it''s an entity which has its own set of attributes, or صِفَاتْ. And they are a sign, they are a means, they are a tool for us to understand the مَنْشَأ of the Creator, the will and the purpose of the Creator.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'and this is why the most essential act in worship in islam is the act of سجده putting our intellects on the ground and surrendering its capacity to recognize الله now quran gives us an incredibly concise statement to help us understand الله because the way in which we understand this world around us is through things right the arabic word for a thing is سوره الفاتحه right the word سوره الفاتحه it means thing and this word it comes from شاء which means will the will of الله everything every being every ذات that exists in this world has its own individual set of attributes right every noun has its adjectives all of which points to what they point to the من شاء to the will and the purpose of their creator so every سوره الفاتحه is a ذات its a being its an entity which has its own set of attributes or صفات and they are a sign they are a means they are a tool for us to understand the منشا of the creator the will and the purpose of the creator', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 27, NULL, 'But when it comes to اللَّه Himself, when it comes to the Creator Himself, there is no thing, there is no شَيْء that can be compared to Him in any way, shape or form. And so the Quran beautifully explains this concept to us through one single word in an آيَةٌ, كَمِثْلِهِ. No matter what you do, no matter how high your imaginations fly, no matter how deep your thoughts dive, there is absolutely no way for you to understand اللَّه, because there is no thing, no being, no attribute in existence, whether it''s physical or spiritual or metaphysical or conceptual or theoretical, there is nothing that is like اللَّه. There is absolutely nothing that you can use to compare it to اللَّه or to create a likeness for اللَّه. سُبْحَانَ اللَّهِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'but when it comes to الله himself when it comes to the creator himself there is no thing there is no شيء that can be compared to him in any way shape or form and so the quran beautifully explains this concept to us through one single word in an ايه كمثله no matter what you do no matter how high your imaginations fly no matter how deep your thoughts dive there is absolutely no way for you to understand الله because there is no thing no being no attribute in existence whether its physical or spiritual or metaphysical or conceptual or theoretical there is nothing that is like الله there is absolutely nothing that you can use to compare it to الله or to create a likeness for الله سبحان الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 28, NULL, 'Now I want you to take a moment to really let this paradox sink in. He created this magnificent universe all around us. Every single entity with its attributes is reflecting His divine existence. It''s reflecting His own attributes for us, so that we can gain a semblance of understanding of His powers, His glory, His majesty, His wrath, His love, His everything. And then once we do manage to get some feeble understanding of His attributes in creation, He says, لَيْسَ كَمِثْلِهِۦ شَىْءٌۭ. Look, whatever little now that you think you know about Me, understand that I''m not like that. I''m way beyond it. And what''s so incredible is that He does this linguistically through the use of one single word. This is not a word that is commonly used, and it was not even used in classical Arabic. The ancient Arabs actually never used this word. This is a word that is used in only in eloquence of the Quran.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'now i want you to take a moment to really let this paradox sink in he created this magnificent universe all around us every single entity with its attributes is reflecting his divine existence its reflecting his own attributes for us so that we can gain a semblance of understanding of his powers his glory his majesty his wrath his love his everything and then once we do manage to get some feeble understanding of his attributes in creation he says ليس كمثله شيء look whatever little now that you think you know about me understand that im not like that im way beyond it and whats so incredible is that he does this linguistically through the use of one single word this is not a word that is commonly used and it was not even used in classical arabic the ancient arabs actually never used this word this is a word that is used in only in eloquence of the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 29, NULL, 'So from a grammatical standpoint, the word is actually two words. There is the word كَ, and then there is the word مِثْلِهِ. These are both words that are used for comparison, but they are never fused together in this manner. They are always used individually. So let''s try to understand the subtlety in the usage of this word ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎. It''s really beautiful.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so from a grammatical standpoint the word is actually two words there is the word ك and then there is the word مثله these are both words that are used for comparison but they are never fused together in this manner they are always used individually so lets try to understand the subtlety in the usage of this word بسم الله الرحمن الرحيم its really beautiful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 30, NULL, 'So in Arabic, when you want to compare something in attributes — now you understand the difference between ذَات and صِفَاتْ, right? The noun and adjectives, being an attribute. So anytime you want to create a comparison in attributes, you add the letter كَ before it, oكَy? So for example, if I wanna compare the bravery of Zed to a lion, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so in arabic when you want to compare something in attributes now you understand the difference between ذات and صفات right the noun and adjectives being an attribute so anytime you want to create a comparison in attributes you add the letter ك before it oكy so for example if i wanna compare the bravery of zed to a lion right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 31, NULL, 'So if I wanna say that Zed is brave like a lion, I will have to use the letter كَ to do that. So I''ll say زَيْدٌ كَالْأَسَدِ. I''m saying Zaid is like a lion. Now what am I comparing here? I''m comparing the attribute of bravery of a lion with Zaid. So I''m using the letter كَ. زَيْدٌ كَالْأَسَدِ. But when I need to establish a comparison in essence, I cannot use the word كَ. You understand? Grammatically that would be wrong. I will now have to use the word مِثَالٌ.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so if i wanna say that zed is brave like a lion i will have to use the letter ك to do that so ill say زيد كالاسد im saying zaid is like a lion now what am i comparing here im comparing the attribute of bravery of a lion with zaid so im using the letter ك زيد كالاسد but when i need to establish a comparison in essence i cannot use the word ك you understand grammatically that would be wrong i will now have to use the word مثال', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 32, NULL, 'So for example, I will say . A cub is similar to a lion. The son of a lion is like the lion. Here I''m using the word مِثَالٌ, because I''m not comparing in attributes. I''m actually comparing the essence of these two entities, the lion and the cub. So this is a rule of the Arabic language, that when you know when you''re establishing comparisons, both words كَ and مِثَال, they are used in very precise ways. And we find this distinction all over Arabic poetry. So for example, there is this poet who is praising the generosity of a king and comparing it to an ocean, right? Now what is generosity? Is it being, or is it an attribute? It''s an attribute. So he''s comparing the generosity of this king to the ocean. So he has to use the letter كَ. So he says, كَالْبَحْرِ يَقْضِي فُؤُولَ الْكَرِيِّ بِلَا عَلِيَّةٍ جُودًا وَيَبَّأُ صُولَ الْبَعِيدِ سَحَائِبَا. He says, the king is generous like the ocean. When I move closer to him, he gives me pearls, and when I move away from him, he sends clouds filled with rain.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so for example i will say a cub is similar to a lion the son of a lion is like the lion here im using the word مثال because im not comparing in attributes im actually comparing the essence of these two entities the lion and the cub so this is a rule of the arabic language that when you know when youre establishing comparisons both words ك and مثال they are used in very precise ways and we find this distinction all over arabic poetry so for example there is this poet who is praising the generosity of a king and comparing it to an ocean right now what is generosity is it being or is it an attribute its an attribute so hes comparing the generosity of this king to the ocean so he has to use the letter ك so he says كالبحر يقضي فوول الكري بلا عليه جودا ويبا صول البعيد سحايبا he says the king is generous like the ocean when i move closer to him he gives me pearls and when i move away from him he sends clouds filled with rain', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 33, NULL, 'So here he uses the word كَ, because he is comparing the attributes of generosity. But when the being or the entity needs to be compared, the word مِثَالٌ has to be used. So the poet says, I am a lion and this is my son, indeed the son of a lion is like the lion. So now, because the comparison is being done in the ذَات, in the entity itself, the poet is using the word مِثْل. So I hope this gives you a much better understanding of this subtlety, because you know, that is what makes this آيَةٌ so beautiful.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so here he uses the word ك because he is comparing the attributes of generosity but when the being or the entity needs to be compared the word مثال has to be used so the poet says i am a lion and this is my son indeed the son of a lion is like the lion so now because the comparison is being done in the ذات in the entity itself the poet is using the word مثل so i hope this gives you a much better understanding of this subtlety because you know that is what makes this ايه so beautiful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 34, NULL, 'اللَّه says. To compare Himself, what اللَّه does in this verse is that He fuses both the سُورَةُ الْفَاتِحَةِ and the مِثْل together to create this one word, كَامِفْلِحْ. Why is that? Because we just learned that كَ is used for attributes and مِسِّيلْ is used for the entity itself. So what اللَّه is saying is that whether you try to compare me to attributes of creation, كَ, or if you try to compare me to the essence of creation, مِسِّيلْ, in both cases, you will fail, because لَيْسَ كَمِثْلِهِۦ شَىْءٌۭ. There is nothing that exists in attributes, and there is nothing that exists in essence that you can use to compare to me. سُبْحَانَ اللَّهِ. Can you appreciate the beauty of this word?', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'الله says to compare himself what الله does in this verse is that he fuses both the سوره الفاتحه and the مثل together to create this one word كامفلح why is that because we just learned that ك is used for attributes and مسيل is used for the entity itself so what الله is saying is that whether you try to compare me to attributes of creation ك or if you try to compare me to the essence of creation مسيل in both cases you will fail because ليس كمثله شيء there is nothing that exists in attributes and there is nothing that exists in essence that you can use to compare to me سبحان الله can you appreciate the beauty of this word', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 35, NULL, 'It''s incredible. This is eloquence at its best. I mean... There is nothing comparable to Me in attributes. مِثْل. There is nothing comparable to Me in beingness, in existence. كَمِثْلِهِ. There is nothing comparable to Me in attributes or in being. لَيْسَ كَمِثْلِهِۦ شَىْءٌۭ. There is no thing, whether physical, metaphysical, spiritual, conceptual, theoretical, practical, there is simply no شَيْء that you can use to create a comparison or a likeness for Me, not in attributes, not in essence. سُبْحَانَ اللَّهِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'its incredible this is eloquence at its best i mean there is nothing comparable to me in attributes مثل there is nothing comparable to me in beingness in existence كمثله there is nothing comparable to me in attributes or in being ليس كمثله شيء there is no thing whether physical metaphysical spiritual conceptual theoretical practical there is simply no شيء that you can use to create a comparison or a likeness for me not in attributes not in essence سبحان الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 36, NULL, 'So now that we understand this concept, what the بِسْمِ اللَّهِ does is that it condenses all the attributes of اللَّه سُبْحَانَهُ وَتَعَالَى into two primary attributes: الرَّحْمَٰن and الرَّحِيمِ. In other words, the two attributes that will always be present in each and every single interaction of اللَّهُ سُبْحَانَهُ وَتَعَالَى with His creation are the attributes of رَحْمَة: الرَّحْمَٰن and الرَّحِيم. Intense mercy, consistent mercy. So when we say ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, in essence we are remembering the essence of اللَّه. Right? Because it is اللَّه who is الرَّحْمَٰن and رَحِيم. So we''re remembering, reminding ourselves of the essence of اللَّه which is manifesting for us through these two primary attributes of رَحْمَة.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so now that we understand this concept what the بسم الله does is that it condenses all the attributes of الله سبحانه وتعالي into two primary attributes الرحمن and الرحيم in other words the two attributes that will always be present in each and every single interaction of الله سبحانه وتعالي with his creation are the attributes of رحمه الرحمن and الرحيم intense mercy consistent mercy so when we say بسم الله الرحمن الرحيم in essence we are remembering the essence of الله right because it is الله who is الرحمن and رحيم so were remembering reminding ourselves of the essence of الله which is manifesting for us through these two primary attributes of رحمه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 37, NULL, 'So what this does is that in a sense it implodes all of His remaining attributes. It sucks in all of His remaining attributes into this concept of رَحْمَة. You see, in other words, regardless of the way in which اللَّه is interacting with us right now, His رَحْمَة is present in that manifestation. Even if He is manifesting in my life right this moment as الْجَبَّار or الْقَهَّار, His رَحْمَانِيَّة, His رَحِيمِيَّة, His رَحْمَة, His love, His care, His compassion, His concern, His mercy, it''s always present in His interaction with me. There is a lot more to be, you know, explained about this. إِن شَآءَ ٱللَّهُ we''ll move this conversation forward in the next session.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'so what this does is that in a sense it implodes all of his remaining attributes it sucks in all of his remaining attributes into this concept of رحمه you see in other words regardless of the way in which الله is interacting with us right now his رحمه is present in that manifestation even if he is manifesting in my life right this moment as الجبار or القهار his رحمانيه his رحيميه his رحمه his love his care his compassion his concern his mercy its always present in his interaction with me there is a lot more to be you know explained about this ان شاء الله well move this conversation forward in the next session', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'allah - being vs attributes', 'Allah - Being vs Attributes', 38, NULL, 'وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتَمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ وَعَلَى أَخِيهِ وَوَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِمَا الطَّيِّبِينَ الطَّاهِرِينَ وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ، الْفَاتِحَة', '', 'وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتَمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ وَعَلَى أَخِيهِ وَوَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِمَا الطَّيِّبِينَ الطَّاهِرِينَ وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ، الْفَاتِحَة', NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'واخر دعوانا ان الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد خاتم النبيين وسيد المرسلين وعلي اخيه ووصيه علي بن ابي طالب اشرف الوصيين وعلي الايمه من ذريتهما الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه', 'واخر دعوانا ان الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد خاتم النبيين وسيد المرسلين وعلي اخيه ووصيه علي بن ابي طالب اشرف الوصيين وعلي الايمه من ذريتهما الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 0, NULL, 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ. ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎. اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ وَبَارِكْ وَسَلِّمْ. رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي. السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ.', '', 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ وَبَارِكْ وَسَلِّمْ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ', NULL, NULL, NULL, 'surah al fateha the ism of allah', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد وبارك وسلم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي السلام عليكم ورحمه الله وبركاته', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد وبارك وسلم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي السلام عليكم ورحمه الله وبركاته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 1, NULL, 'In the previous session, we talked about the concepts of tرَاnscendence and immanence of اللَّهُ سُبْحَانَهُ وَتَعَالَى. So we learnt that in one way, اللَّه is immensely distant out of His loftiness and because of His magnificence. But then at the same time, He is extremely close to our hearts and our consciousness, as the قُرْآن says that He''s closer to us than our jugular vein. And what that ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sically means is our consciousness, because when you cut the jugular vein, the first thing that you lose is your consciousness.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'in the previous session we talked about the concepts of tراnscendence and immanence of الله سبحانه وتعالي so we learnt that in one way الله is immensely distant out of his loftiness and because of his magnificence but then at the same time he is extremely close to our hearts and our consciousness as the قران says that hes closer to us than our jugular vein and what that بسم الله الرحمن الرحيم sically means is our consciousness because when you cut the jugular vein the first thing that you lose is your consciousness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 2, NULL, 'So in one instance He is extremely distant from us and in another He is extremely close. And there''s this beautiful verse in Urdu, which I really like, that I think that describes His immanence and His tرَاnscendence in a really beautiful way, in which the poet says, Ke duri ki yahad hai, ki tasavur bi khata hai. And what the poet is saying there is that اللَّه is so tرَاnscendent, He is so distant from us that even imagining anything about Him is a sin. But on the other hand, He is so close to us that He is closer to me than my jugular vein. And I think that is a really beautiful way in which the poet expresses this concept of tرَاnscendence and immanence.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'so in one instance he is extremely distant from us and in another he is extremely close and theres this beautiful verse in urdu which i really like that i think that describes his immanence and his tراnscendence in a really beautiful way in which the poet says ke duri ki yahad hai ki tasavur bi khata hai and what the poet is saying there is that الله is so tراnscendent he is so distant from us that even imagining anything about him is a sin but on the other hand he is so close to us that he is closer to me than my jugular vein and i think that is a really beautiful way in which the poet expresses this concept of tراnscendence and immanence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 3, NULL, 'We also looked at the distinction between اللَّه and His attributes, and we saw that how He is incompaرَاble by both of these. So لَيْسَ كَمِثْلِهِۦ شَىْءٌۭ, and the word ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, it''s actually a combination of كَـ and مِثْلِهِ, one used for attributes, the other used for essence. And the verse reveals to us that He is incompaرَاble through attributes as well as through essence.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'we also looked at the distinction between الله and his attributes and we saw that how he is incompaراble by both of these so ليس كمثله شيء and the word بسم الله الرحمن الرحيم its actually a combination of ك and مثله one used for attributes the other used for essence and the verse reveals to us that he is incompaراble through attributes as well as through essence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 4, NULL, 'So now that we''ve covered this noun اللَّه and His adjectives ٱلرَّحْمَنِ ٱلرَّحِيمِ, today I want to talk about عِصَام, right? Because it starts with ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎. The Alif is dropped because of a gرَاmmatical rule which I''ll talk about later, but that the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ is actually joined with the عِصَام. And the word عِصَام in Aرَاbic, it means two things. It means a noun, you know, as in the gرَاmmatical term noun, but and it also means name, because every noun has a name. So the classical Aرَاbs, they just used it interchangeably.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'so now that weve covered this noun الله and his adjectives الرحمن الرحيم today i want to talk about عصام right because it starts with بسم الله الرحمن الرحيم the alif is dropped because of a gراmmatical rule which ill talk about later but that the بسم الله الرحمن الرحيم is actually joined with the عصام and the word عصام in aراbic it means two things it means a noun you know as in the gراmmatical term noun but and it also means name because every noun has a name so the classical aراbs they just used it interchangeably', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 5, NULL, 'Now from a قُرْآنic perspective, this concept of name is extremely important, because it is the names, the أَسْمَاء, that elevated Adam over the angels and made him worthy of their prostرَاtion. Also because these names were something that were directly taught to Adam by none other than اللَّه Himself. So اللَّه taught Adam all the names. So the concept of name is actually extremely important in the human psyche, because we are بَنِي آدَمَ, we are the children of Adam.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'now from a قرانic perspective this concept of name is extremely important because it is the names the اسماء that elevated adam over the angels and made him worthy of their prostراtion also because these names were something that were directly taught to adam by none other than الله himself so الله taught adam all the names so the concept of name is actually extremely important in the human psyche because we are بني ادم we are the children of adam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 6, NULL, 'Now, what is the name? A name is ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sically the ability of symbolic thought. That is the essence of a name. So naming something is taking a symbol, which is linguistic in nature, and then applying that symbol to something which is either material or empirical, conceptual or even theoretical, right? Those are all entities that are actually named. We give a name to them. Or a name can be something that can be used as a means of abstرَاction in order to create sepaرَاtion in things.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'now what is the name a name is بسم الله الرحمن الرحيم sically the ability of symbolic thought that is the essence of a name so naming something is taking a symbol which is linguistic in nature and then applying that symbol to something which is either material or empirical conceptual or even theoretical right those are all entities that are actually named we give a name to them or a name can be something that can be used as a means of abstراction in order to create sepaراtion in things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 7, NULL, 'So you can have a broad category called cars, and then you can further break them down, further abstرَاct each one of them by giving them additional names, right? Mercedes, Toyota, BMW, Audi, all of these. So now this is something that only we can do. Animals cannot do this. Animals cannot use symbolic language. This is something that only human beings are capable of.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'so you can have a broad category called cars and then you can further break them down further abstراct each one of them by giving them additional names right mercedes toyota bmw audi all of these so now this is something that only we can do animals cannot do this animals cannot use symbolic language this is something that only human beings are capable of', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 8, NULL, 'It has been agreed by the Aرَاb scholars that human beings have ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sically three dominant modes of symbolic language. We have linguistics, which is the highest form, and then we have mathematics, which, believe it or not, actually comes under linguistics. This has always been the mindset of the ancient people. It''s only the 20th century and the Western civilization that elevated mathematics over language. Today, language has taken a secondary place, and that is because people don''t understand the power of language, especially the Aرَاbic language.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'it has been agreed by the aراb scholars that human beings have بسم الله الرحمن الرحيم sically three dominant modes of symbolic language we have linguistics which is the highest form and then we have mathematics which believe it or not actually comes under linguistics this has always been the mindset of the ancient people its only the 20th century and the western civilization that elevated mathematics over language today language has taken a secondary place and that is because people dont understand the power of language especially the aراbic language', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 9, NULL, 'And this is why even Muslims today, they try to place mathematics over the linguistics of قُرْآن when they want to try to prove it as a miرَاcle. And, you know, no doubt قُرْآن is mathematically perfect. I''m not, you know, discrediting that, and actually I''ve shown you a lot of examples of that in the sessions on is قُرْآن a miرَاcle. But the fact of the matter is that what makes قُرْآن a miرَاcle is not its mathematical perfection, but رَاther its linguistic perfection.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'and this is why even muslims today they try to place mathematics over the linguistics of قران when they want to try to prove it as a miراcle and you know no doubt قران is mathematically perfect im not you know discrediting that and actually ive shown you a lot of examples of that in the sessions on is قران a miراcle but the fact of the matter is that what makes قران a miراcle is not its mathematical perfection but راther its linguistic perfection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 10, NULL, 'And this is something that as Muslims we really need to understand and appreciate. And, you know, this need to prove قُرْآن mathematically, it actually comes from this feeling of inferiority before the god of modern science, which of course there is mathematics. You know, this comes from Newton and Einstein and all these other people who elevated mathematics and said that it is the only real way of understanding reality, right? And the reason they say that is because mathematics is precise and it is exact. But then these people did not study classical Aرَاbic, because Aرَاbic is precise and Aرَاbic is exact. In fact, it is precise and exact to a degree that mathematics cannot even come close to. And this is why the miرَاcle of قُرْآن, the إِعْجَاز of قُرْآن, is not in its mathematics, it is in its linguistic perfection and eloquence.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'and this is something that as muslims we really need to understand and appreciate and you know this need to prove قران mathematically it actually comes from this feeling of inferiority before the god of modern science which of course there is mathematics you know this comes from newton and einstein and all these other people who elevated mathematics and said that it is the only real way of understanding reality right and the reason they say that is because mathematics is precise and it is exact but then these people did not study classical aراbic because aراbic is precise and aراbic is exact in fact it is precise and exact to a degree that mathematics cannot even come close to and this is why the miراcle of قران the اعجاز of قران is not in its mathematics it is in its linguistic perfection and eloquence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 11, NULL, 'So قُرْآن is a linguistic miرَاcle. But the recognition of this, this concept of recognizing the fact that قُرْآن is a linguistic miرَاcle, it actually comes from our ability to recognize things through names. Because names have meanings, right? They help us identify, they help us recognize things. So the actual power of recognizing the قُرْآن as a linguistic miرَاcle, it comes through our ability of understanding names. And this is why اسْمٌ is so important, to understand this concept of اسْمٌ.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'so قران is a linguistic miراcle but the recognition of this this concept of recognizing the fact that قران is a linguistic miراcle it actually comes from our ability to recognize things through names because names have meanings right they help us identify they help us recognize things so the actual power of recognizing the قران as a linguistic miراcle it comes through our ability of understanding names and this is why اسم is so important to understand this concept of اسم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 12, NULL, 'And when it comes to classical Aرَاbic, even the letters become prominent, even the sounds become prominent. In fact, you know, if you take the Aرَاbic language, so when I say a tree, for example, in English, right, you see something that has a trunk, that has bرَاnches and leaves. You know, that''s what comes to your mind when I say the word tree, right? If it''s a palm tree, it has a trunk and then it has these palm fibers. Or, you know, if it''s a fir tree, then it''s got all these spikes instead of leaves. But ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sically there are three types of trees, right? You have the fir trees, you have the palm trees, and then you have these with leaves. So when we say شَجَرٌ in Aرَاbic, what is the difference between a شَجَرٌ and a tree? I mean, we could argue that they''re completely arbitرَاry, right? And this is a dominant opinion among most linguists in most languages, that names really have no connection to the thing that is named, other than the fact that they are ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sically signs that human beings have collectively agreed upon.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'and when it comes to classical aراbic even the letters become prominent even the sounds become prominent in fact you know if you take the aراbic language so when i say a tree for example in english right you see something that has a trunk that has bراnches and leaves you know thats what comes to your mind when i say the word tree right if its a palm tree it has a trunk and then it has these palm fibers or you know if its a fir tree then its got all these spikes instead of leaves but بسم الله الرحمن الرحيم sically there are three types of trees right you have the fir trees you have the palm trees and then you have these with leaves so when we say شجر in aراbic what is the difference between a شجر and a tree i mean we could argue that theyre completely arbitراry right and this is a dominant opinion among most linguists in most languages that names really have no connection to the thing that is named other than the fact that they are بسم الله الرحمن الرحيم sically signs that human beings have collectively agreed upon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 13, NULL, 'So their opinion is that the Aرَاbs saw the structure of a trunk with the bرَاnches and leaves and they decided to call it شَجَرٌ, whereas in English they decided to call it a tree. But the ancient Aرَاb would actually completely disagree with that. They would argue that there is a deep relationship between the word شَجَرٌ and this thing out there that we see. Because شَجَرٌ is made up of three letters. This word, this name, شَجَرٌ, is made up of three letters: سُورَةُ الْفَاتِحَةِ, جِيمْ, and رَا. Now, whenever you have the letter سُورَةُ الْفَاتِحَةِ, this is called حَرْفُ التَّفَشِّي in Aرَاbic. The letter سُورَةُ الْفَاتِحَةِ is always used for something that spreads out, that has رَاdiation, like شَمْسٌ, the sun. شَعْر, hair — hair has رَاdiation because it spreads out, it''s all spread all over the body. Shajar has رَاdiation because a tree has these bرَاnches that spread out. So سُورَةُ الْفَاتِحَةِ is a very specific word and it has a very specific meaning. Then there is the letter جِيمْ, which is حَرْفُ الشِّدَّةِ, right? It''s a strong letter.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'so their opinion is that the aراbs saw the structure of a trunk with the bراnches and leaves and they decided to call it شجر whereas in english they decided to call it a tree but the ancient aراb would actually completely disagree with that they would argue that there is a deep relationship between the word شجر and this thing out there that we see because شجر is made up of three letters this word this name شجر is made up of three letters سوره الفاتحه جيم and را now whenever you have the letter سوره الفاتحه this is called حرف التفشي in aراbic the letter سوره الفاتحه is always used for something that spreads out that has راdiation like شمس the sun شعر hair hair has راdiation because it spreads out its all spread all over the body shajar has راdiation because a tree has these bراnches that spread out so سوره الفاتحه is a very specific word and it has a very specific meaning then there is the letter جيم which is حرف الشده right its a strong letter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 14, NULL, 'It is used to represent things that are strong in their nature, because the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sis of a tree is strength. It is strong. It''s the trunk, right? That''s why it has the letter جِيمْ. جِسْم, the body, the main structure of the human being, strength. جَبَل, a mountain, starts with the letter جِيمْ because it''s powerful by its very nature, right? So جِيمْ is حَرْفُ الشِّدَّةِ. Then there is the letter رَا, which is the letter of repetition. Trees are constantly regeneرَاting themselves, they''re repeating themselves. So the ancient Aرَاb would argue that there''s a deep relationship between the letters and the thing that is named itself. And this is something — I mean, these are philosophical de‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎tes about the nature of language — but the Aرَاbs would definitely say that there is a secret in names. You know, in classical Aرَاbic names are not arbitرَاry. There is actually a very good reason why a شَجَرٌ is called a شَجَرٌ and a شَمْسٌ is called a شَمْسٌ, with those particular sounds in those particular order.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'it is used to represent things that are strong in their nature because the بسم الله الرحمن الرحيم sis of a tree is strength it is strong its the trunk right thats why it has the letter جيم جسم the body the main structure of the human being strength جبل a mountain starts with the letter جيم because its powerful by its very nature right so جيم is حرف الشده then there is the letter را which is the letter of repetition trees are constantly regeneراting themselves theyre repeating themselves so the ancient aراb would argue that theres a deep relationship between the letters and the thing that is named itself and this is something i mean these are philosophical de بسم الله الرحمن الرحيم tes about the nature of language but the aراbs would definitely say that there is a secret in names you know in classical aراbic names are not arbitراry there is actually a very good reason why a شجر is called a شجر and a شمس is called a شمس with those particular sounds in those particular order', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 15, NULL, 'And this is why we know that these sounds, they have an effect. The sounds of the Aرَاbic letters have an effect on the human consciousness. There is no denying that. The recitation of قُرْآن has a powerful effect on human consciousness, just by the very nature of its sounds. So even if you don''t understand a single word, just listening to a good recitation can deeply move your heart. And if you look up on the internet, you''ll find so many examples of people converting to Islam simply after hearing a recitation or hearing the adhan or something like that, because these sounds, they, you know, they''re not arbitرَاry. They have a very deep effect on the human consciousness. So Aرَاbic is an incredible, miرَاculous language in every way, shape, or form, and it''s very different from other languages of the world.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'and this is why we know that these sounds they have an effect the sounds of the aراbic letters have an effect on the human consciousness there is no denying that the recitation of قران has a powerful effect on human consciousness just by the very nature of its sounds so even if you dont understand a single word just listening to a good recitation can deeply move your heart and if you look up on the internet youll find so many examples of people converting to islam simply after hearing a recitation or hearing the adhan or something like that because these sounds they you know theyre not arbitراry they have a very deep effect on the human consciousness so aراbic is an incredible miراculous language in every way shape or form and its very different from other languages of the world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 16, NULL, 'But what I''m trying, the reason I''m explaining all this to you is because I want you to understand that all of its power, the power of this Aرَاbic language, it actually boils down to the human ability to understand names. You know, these أَسْمَاء that are provided for us within the fرَاmework of language. So it''s no coincidence that اللَّه started the statement with ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, and actually you''ll see, what I''ll explain as we go along, you''ll see the power of what that statement means. Now we understand the meaning of names, right? So let''s talk about the purpose of language. What is the purpose of language? The purpose of language geneرَاlly is communication, right? We want to be able to deliver communication, express ourselves. But if you actually analyze the purpose of language itself, it actually is unification. Language unifies.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'but what im trying the reason im explaining all this to you is because i want you to understand that all of its power the power of this aراbic language it actually boils down to the human ability to understand names you know these اسماء that are provided for us within the fراmework of language so its no coincidence that الله started the statement with بسم الله الرحمن الرحيم and actually youll see what ill explain as we go along youll see the power of what that statement means now we understand the meaning of names right so lets talk about the purpose of language what is the purpose of language the purpose of language geneراlly is communication right we want to be able to deliver communication express ourselves but if you actually analyze the purpose of language itself it actually is unification language unifies', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 17, NULL, 'This is the secret of the human being, that we have this ability to abstرَاct, differentiate, and identify things uniquely through names. We as human beings, we have this ability to see the one in the many. That''s the only way we can communicate. I mean, this is really profound. Think about it. The only way we can communicate is by seeing the one in the many. What am I talking about? So for example, if we talk about a lecture, let''s say, right? So for example, I tell you that there''s going to be a session next Sunday at 9:30 a.m. How do you know what the word session means in that context? How do you know what that statement means? The word session in that context, because the word session has many different meanings in different contexts.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'this is the secret of the human being that we have this ability to abstراct differentiate and identify things uniquely through names we as human beings we have this ability to see the one in the many thats the only way we can communicate i mean this is really profound think about it the only way we can communicate is by seeing the one in the many what am i talking about so for example if we talk about a lecture lets say right so for example i tell you that theres going to be a session next sunday at 9 30 a m how do you know what the word session means in that context how do you know what that statement means the word session in that context because the word session has many different meanings in different contexts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 18, NULL, 'So, I could say, you know, I''m recording a religious session, or the school is in session, right? The courtroom is in session. Yasmin had a great tennis coaching session. The Fedeرَاl Act was passed in the session of 1908. So the word session can have so many different meanings in different contexts. So but when I say there''s going to be a session tomorrow, how do you know which meaning of the word session I''m talking about? The only way you know that is because you are extرَاcting that one particular meaning of that word within that context out of so many other possibilities. And this is something we all do instinctively all the time. This is just an ability that we human beings have, because we have this inherent capability to extرَاct the one out of the many. And when we''re not able to do that, when we''re not able to zero in on one particular meaning, we are then forced to ask, wait a minute, I just want to make sure, did you mean this or did you mean that? Why do we do that? Because we''re trying to find that one particular meaning. You see that? So every sentence, every phرَاse, every word, it needs to boil down to one particular thought from a sea of possibilities.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'so i could say you know im recording a religious session or the school is in session right the courtroom is in session yasmin had a great tennis coaching session the fedeراl act was passed in the session of 1908 so the word session can have so many different meanings in different contexts so but when i say theres going to be a session tomorrow how do you know which meaning of the word session im talking about the only way you know that is because you are extراcting that one particular meaning of that word within that context out of so many other possibilities and this is something we all do instinctively all the time this is just an ability that we human beings have because we have this inherent capability to extراct the one out of the many and when were not able to do that when were not able to zero in on one particular meaning we are then forced to ask wait a minute i just want to make sure did you mean this or did you mean that why do we do that because were trying to find that one particular meaning you see that so every sentence every phراse every word it needs to boil down to one particular thought from a sea of possibilities', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 19, NULL, 'And so what language, and in particular names or these nouns, what they enable us to do is they enable us to speak intelligently about the oneness and the unified nature of words. Because that is who we are. We are all unifiers by our very inherent nature. This is what we as human beings were created to do. We are مُوَحِّدٌ by our natures. We were designed to make one out of many through language. This is why Adam was given the gift of names, this gift of language, because using names we can unify. Language is a sign of اللَّه within our existence, within the human existence, that that is what you have been created to do: to perform the ultimate unification, تَوْحِيد, because that''s what the word unification means in Aرَاbic, تَوْحِيد. We were created for تَوْحِيد, to single out the one إِلَهْ, the one true اللَّه, from all these possibilities and all these deities in our life posing as false gods. سُبْحَانَ اللَّهِ. So you can see how profound this concept of name or اِسْم becomes.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'and so what language and in particular names or these nouns what they enable us to do is they enable us to speak intelligently about the oneness and the unified nature of words because that is who we are we are all unifiers by our very inherent nature this is what we as human beings were created to do we are موحد by our natures we were designed to make one out of many through language this is why adam was given the gift of names this gift of language because using names we can unify language is a sign of الله within our existence within the human existence that that is what you have been created to do to perform the ultimate unification توحيد because thats what the word unification means in aراbic توحيد we were created for توحيد to single out the one اله the one true الله from all these possibilities and all these deities in our life posing as false gods سبحان الله so you can see how profound this concept of name or اسم becomes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 20, NULL, 'So now that you understand that, the next question is where does the process of this recognition of اللَّه begin? It begins with اِسْمُ اللهِ. It begins with the name of اللَّه.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'so now that you understand that the next question is where does the process of this recognition of الله begin it begins with اسم الله it begins with the name of الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 21, NULL, 'Now, the word اِسْم, linguistically, it comes from two root words. It comes from سُورَةُ الْفَاتِحَةِ and it comes from وَسَمَّى. Oكَـy, the word اِسْم, it actually comes from سُورَةُ الْفَاتِحَةِ or وَسَمَّى. The word سُورَةُ الْفَاتِحَةِ, it means lofty, something very high, like the sky in Aرَاbic is called a سَمَا, right? And the word وَسَمَّى, it actually means a sign or a symbol. Alright, so اِسْم is ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sically a combination of two things. It is سُورَةُ الْفَاتِحَةِ and وَسَمَّى. So it is ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sically a sign for those, it''s a lofty sign for those who can see. So if you break this word down, اِسْم linguistically, it actually means a lofty sign, coming from سُورَةُ الْفَاتِحَةِ and وَسَمَّى, a lofty sign. That''s what اِسْم is. It''s an أَلَمَ. It''s something you put onto something in order to signify it. So it''s essentially a signifier that indicates the signified, right? So اِسْم is a lofty sign.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'now the word اسم linguistically it comes from two root words it comes from سوره الفاتحه and it comes from وسمي oكy the word اسم it actually comes from سوره الفاتحه or وسمي the word سوره الفاتحه it means lofty something very high like the sky in aراbic is called a سما right and the word وسمي it actually means a sign or a symbol alright so اسم is بسم الله الرحمن الرحيم sically a combination of two things it is سوره الفاتحه and وسمي so it is بسم الله الرحمن الرحيم sically a sign for those its a lofty sign for those who can see so if you break this word down اسم linguistically it actually means a lofty sign coming from سوره الفاتحه and وسمي a lofty sign thats what اسم is its an الم its something you put onto something in order to signify it so its essentially a signifier that indicates the signified right so اسم is a lofty sign', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 22, NULL, 'In fact, in Suرَاh سُورَةُ الرُّومِ, اللَّه says, from His signs, the creations of the heavens and the earth.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'in fact in suراh سوره الروم الله says from his signs the creations of the heavens and the earth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 23, NULL, 'And in the variance, your tongues and your colors. So اللَّه relates the tongues to the heavens, right? Because you have the heavens first and then the earth, and He says, and then He says, you know, in the variance of your tongues and your skin color. So He relates tongues to the heavens and He relates the skin color to the earth. And this is called طَبَق in Aرَاbic, which is this concept, it''s a type of antithesis where you use opposites to explain something. So He talks about heaven and earth and then He relates them to tongues and colors, like, you know, our skin color and our speech.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'and in the variance your tongues and your colors so الله relates the tongues to the heavens right because you have the heavens first and then the earth and he says and then he says you know in the variance of your tongues and your skin color so he relates tongues to the heavens and he relates the skin color to the earth and this is called طبق in aراbic which is this concept its a type of antithesis where you use opposites to explain something so he talks about heaven and earth and then he relates them to tongues and colors like you know our skin color and our speech', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 24, NULL, 'So there is a relationship between tongues and heaven, and there is a relationship between skin color and the earth. Because speech comes from heaven. You see, speech, اللَّه taught human beings, or He taught Adam, or رَاther He imprinted within Adam language. عَلَّمَ means to imprint, right? The الرَّحْمَٰن imprinted within the human being the قُرْآن. That''s liteرَاlly what عَلَّمَ means, to imprint something. Language was imprinted within the human being. And this is why all human beings have this common ability to learn languages.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'so there is a relationship between tongues and heaven and there is a relationship between skin color and the earth because speech comes from heaven you see speech الله taught human beings or he taught adam or راther he imprinted within adam language علم means to imprint right the الرحمن imprinted within the human being the قران thats liteراlly what علم means to imprint something language was imprinted within the human being and this is why all human beings have this common ability to learn languages', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 25, NULL, 'Now, complexions is something that comes from the earth, because اللَّهُ سُبْحَانَهُ وَتَعَالَى said that Adam was created from all the topsoil of the earth, right? From the white, the black, the brown, the yellow, the red. So you get all these variances in human complexions because Adam was created from اُدْمَ.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'now complexions is something that comes from the earth because الله سبحانه وتعالي said that adam was created from all the topsoil of the earth right from the white the black the brown the yellow the red so you get all these variances in human complexions because adam was created from ادم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 26, NULL, 'You see, the word اُدْمَ in Aرَاbic, it means topsoil. And Adam means the one who was created from topsoil. So all human beings have these different complexions, just as there are all these colors of the soil. You have white soil and then you have pure white, right? You have red soil, yellow soil, black and then ebony black. So complexions are related to the earth, and language or speech is related to the heaven. Language is meaning, complexion is sensory. You see? Language is meaning, complexion is sensory. There''s a relationship between meaning and sensory. They''re both joined in the human being.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'you see the word ادم in aراbic it means topsoil and adam means the one who was created from topsoil so all human beings have these different complexions just as there are all these colors of the soil you have white soil and then you have pure white right you have red soil yellow soil black and then ebony black so complexions are related to the earth and language or speech is related to the heaven language is meaning complexion is sensory you see language is meaning complexion is sensory theres a relationship between meaning and sensory theyre both joined in the human being', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 27, NULL, 'So what is significant and what is palpable, what we understand and what we can see, touch and feel. So the sensory and the meaning are gathered in these two phenomena, the phenomena of language and the body. Because the essence of human being is language. We are defined as الْحَيَوَانُ النَّاطِقُ, the speaking or the articulating animal. Because what is the essence of language? It is رَاtionality, right? Language is meaningful. So the essence of the human being is language. And that''s why, you know, when we judge a person by their skin color, it is just so wrong, because you''re judging them by something that is just incidental to their nature, right? But when you judge somebody by what they believe in, by how they speak, by what they say, by whether they''re truthful or not, whether they''re virtuous or not, whether they stand for the truth or not.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'so what is significant and what is palpable what we understand and what we can see touch and feel so the sensory and the meaning are gathered in these two phenomena the phenomena of language and the body because the essence of human being is language we are defined as الحيوان الناطق the speaking or the articulating animal because what is the essence of language it is راtionality right language is meaningful so the essence of the human being is language and thats why you know when we judge a person by their skin color it is just so wrong because youre judging them by something that is just incidental to their nature right but when you judge somebody by what they believe in by how they speak by what they say by whether theyre truthful or not whether theyre virtuous or not whether they stand for the truth or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 28, NULL, 'I mean, that''s how human beings should be judged. That''s why Dr. King, he talked about being judged by the content of chaرَاcter. In one of his speeches, he said that we should judge people by the content of chaرَاcter. And how do you know the content of chaرَاcter? By the essence of that person. And what is the essence? Their belief, because that''s what''s going to manifest from them. So judging somebody by the skin color is just wrong at so many levels.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'i mean thats how human beings should be judged thats why dr king he talked about being judged by the content of chaراcter in one of his speeches he said that we should judge people by the content of chaراcter and how do you know the content of chaراcter by the essence of that person and what is the essence their belief because thats whats going to manifest from them so judging somebody by the skin color is just wrong at so many levels', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 29, NULL, 'Anyway, so اِسْم means a lofty or a heavenly sign. Now, the statement of بِسْمِ اللهِ begins with the اِسْم of اللَّه, the lofty signs pointing to اللَّه, because that is the only way we can know اللَّه, through the power of symbolic understanding, right? We cannot know اللَّه as we know things. We cannot know اللَّه the same way we know an MP3 player or a laptop or a computer because, you know, essences are hard to understand even with things, but when it comes to اللَّه, it''s absolutely impossible. So the only way we can know اللَّه is through symbolic language, which are these symbols within language and these symbols within existence, which he calls his آيَاتٌ, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'anyway so اسم means a lofty or a heavenly sign now the statement of بسم الله begins with the اسم of الله the lofty signs pointing to الله because that is the only way we can know الله through the power of symbolic understanding right we cannot know الله as we know things we cannot know الله the same way we know an mp3 player or a laptop or a computer because you know essences are hard to understand even with things but when it comes to الله its absolutely impossible so the only way we can know الله is through symbolic language which are these symbols within language and these symbols within existence which he calls his ايات right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 30, NULL, 'So he has his آيَاتٌ within language, which is in the form of قُرْآن, and then he has his آيَاتٌ, his lofty symbols within existence in the form of the heavens and the earth, and everything in between. So now I''m bringing this entire concept all together, right? So you understand this idea of unification accomplished through language, and these signs, because if you look at the signs, there are numerous signs. There is a whole ocean, this vast ocean of signs around us, but they all condense down to one particular, they''re all pointing to one particular entity, which is اللَّه. Right? So that''s what we find in the horizon. We will keep showing them our signs, our numerous signs within the horizons and within their soul, until it becomes absolutely clear to them that this is all coming from الْحَقُّ, from the one truth, one reality, which is اللَّهُ سُبْحَانَهُ وَتَعَالَى.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'so he has his ايات within language which is in the form of قران and then he has his ايات his lofty symbols within existence in the form of the heavens and the earth and everything in between so now im bringing this entire concept all together right so you understand this idea of unification accomplished through language and these signs because if you look at the signs there are numerous signs there is a whole ocean this vast ocean of signs around us but they all condense down to one particular theyre all pointing to one particular entity which is الله right so thats what we find in the horizon we will keep showing them our signs our numerous signs within the horizons and within their soul until it becomes absolutely clear to them that this is all coming from الحق from the one truth one reality which is الله سبحانه وتعالي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 31, NULL, 'But and if you look at the قُرْآن, it directs us to his 99 divine names, right, as familiar linguistic symbols so that we can gain some concept of who he is. That''s why he uses these familiar names. So for instance, اللَّه says he is مَلِكِ يَوْمِ ٱلدِّينِ, right? He is the owner or the king of the day of judgment. How are we able to understand that? How do we understand what that means? We only understand that because we understand the concept of مَالِكِ, right? We understand the concept of a king. And this enables us to relate to and appreciate the position that اللَّه will take on the day of judgment. He will assume the position of a king or the ultimate owner. But if you really think about it, we are only able to understand that because of the symbolic reference. But then we also learn that اللَّه is not limited to our concept of what a king means. He''s way more exalted than that. Right, so he''s — we get an idea that he''s a king, but then we also understand that it''s not like the kingship that we know of, but at least that concept of king, it gives us some understanding of his position and his relationship with us, right? It just, at the very least, it gets the point across.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'but and if you look at the قران it directs us to his 99 divine names right as familiar linguistic symbols so that we can gain some concept of who he is thats why he uses these familiar names so for instance الله says he is ملك يوم الدين right he is the owner or the king of the day of judgment how are we able to understand that how do we understand what that means we only understand that because we understand the concept of مالك right we understand the concept of a king and this enables us to relate to and appreciate the position that الله will take on the day of judgment he will assume the position of a king or the ultimate owner but if you really think about it we are only able to understand that because of the symbolic reference but then we also learn that الله is not limited to our concept of what a king means hes way more exalted than that right so hes we get an idea that hes a king but then we also understand that its not like the kingship that we know of but at least that concept of king it gives us some understanding of his position and his relationship with us right it just at the very least it gets the point across', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 32, NULL, 'So there is a distinction between اللَّه and the name of اللَّه. There''s a distinction between عِصَام and اللَّه. The عِصَام are all these lofty signs and symbols that He created for us in the horizons and within our souls in various numerous dimensions. They enable us to know Him. That''s an اسْم. That is what اِسْمُ اللهِ means. A lofty heavenly sign or a symbol that helps us recognize اللَّه. You see? Because I recognize you by your name, you recognize me by my name. So name is what helps us recognize.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'so there is a distinction between الله and the name of الله theres a distinction between عصام and الله the عصام are all these lofty signs and symbols that he created for us in the horizons and within our souls in various numerous dimensions they enable us to know him thats an اسم that is what اسم الله means a lofty heavenly sign or a symbol that helps us recognize الله you see because i recognize you by your name you recognize me by my name so name is what helps us recognize', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 33, NULL, 'So now that we understand the linguistic meaning of the word اِسْم as a lofty heavenly sign, what we can now appreciate about ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ is, you know, now I''m talking in the linguistic sense, that what we understand from it now is the lofty signs in the heavens and the earth and everywhere around us pointing to اللَّه and helping us recognize Him as الرَّحْمَٰن and رَحِيمٌ. ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, with the lofty heavenly signs that اللَّه has created for me in order for them to help me recognize that He is ٱلرَّحْمَنِ ٱلرَّحِيمِ, the intensely merciful and the consistently merciful.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'so now that we understand the linguistic meaning of the word اسم as a lofty heavenly sign what we can now appreciate about بسم الله الرحمن الرحيم is you know now im talking in the linguistic sense that what we understand from it now is the lofty signs in the heavens and the earth and everywhere around us pointing to الله and helping us recognize him as الرحمن and رحيم بسم الله الرحمن الرحيم with the lofty heavenly signs that الله has created for me in order for them to help me recognize that he is الرحمن الرحيم the intensely merciful and the consistently merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 34, NULL, 'إِن شَآءَ ٱللَّهُ, in the next session we will look at this preposition ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ that is joined with the إِيَّاكَ نَعْبُدُ, and we will explore the depth of this entire phرَاse, and we will see the power behind reciting ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, and you will see how perfectly this statement serves as the crown of سُورَةُ الْفَاتِحَةِ. Right, it''s sitting on top of سُورَةُ الْفَاتِحَةِ like a crown, because it really, it really deserves that مَقَامٌ.', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'ان شاء الله in the next session we will look at this preposition بسم الله الرحمن الرحيم that is joined with the اياك نعبد and we will explore the depth of this entire phراse and we will see the power behind reciting بسم الله الرحمن الرحيم and you will see how perfectly this statement serves as the crown of سوره الفاتحه right its sitting on top of سوره الفاتحه like a crown because it really it really deserves that مقام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'the ism of allah', 'The ISM Of Allah', 35, NULL, 'الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتَمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ وَآلِهِ وَوَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِمَا الطَّيِّبِينَ الطَّاهِرِينَ وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ، الْفَاتِحَة', '', 'الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتَمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ وَآلِهِ وَوَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِمَا الطَّيِّبِينَ الطَّاهِرِينَ وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ، الْفَاتِحَة', NULL, NULL, NULL, 'surah al fateha the ism of allah', 'الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد خاتم النبيين وسيد المرسلين واله ووصيه علي بن ابي طالب اشرف الوصيين وعلي الايمه من ذريتهما الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه', 'الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد خاتم النبيين وسيد المرسلين واله ووصيه علي بن ابي طالب اشرف الوصيين وعلي الايمه من ذريتهما الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 0, NULL, 'بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيمِ، اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ، وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ، كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ عَلَى إِبْرَاهِيمَ، وَعَلَى آلِ إِبْرَاهِيمَ، فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ، أَشْهَدُ أَنْ لَا إِلَٰهَ إِلَّا اللهُ، وَحْدَهُ لَا شَرِيكَ لَهُ، وَنَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، وَنَشْهَدُ أَنَّ مَوْلَانَا عَلِيًّا وَصِيُّهُ، وَالسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ. Now that we''ve completed most of the terminology from a linguistic perspective in ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, today I want to talk about the letter ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ itself, which is a preposition, and what it means is "with" or "in." So when you say بِسْمِ اللهِ, what you''re actually saying is, I am beginning in the name of اللَّهُ. But you''re omitting the "I am beginning." That''s just understood. It''s called محذوف مُقَدَّر, right, in grammar. But the بَا of بِسْمِ اللهِ is actually connected to an omitted verb. And this is something very important to understand, believe it or not. Because verb or an action is essentially the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sis of all existence. You know, there are two schools of thought.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد اشهد ان لا اله الا الله وحده لا شريك له ونشهد ان محمدا عبده ورسوله ونشهد ان مولانا عليا وصيه والسلام عليكم ورحمه الله وبركاته now that weve completed most of the terminology from a linguistic perspective in بسم الله الرحمن الرحيم today i want to talk about the letter بسم الله الرحمن الرحيم itself which is a preposition and what it means is with or in so when you say بسم الله what youre actually saying is i am beginning in the name of الله but youre omitting the i am beginning thats just understood its called محذوف مقدر right in grammar but the با of بسم الله is actually connected to an omitted verb and this is something very important to understand believe it or not because verb or an action is essentially the بسم الله الرحمن الرحيم sis of all existence you know there are two schools of thought', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 1, NULL, 'One believes that, you know, that the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sis of existence is a noun. And there''s another school of thought, which is the more dominant school of thought, which is also something that we subscribe to ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sed on أَلَمْ, is that the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sis of existence is not a noun, but rather a verb. Because if the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sis of existence is just a noun, then you''re simply talking about a state, right? Like, for example, if we look at our state of being, right, as a human being, we''re just simply here, like I''m being here, I''m existing here, and there''s no action involved in my being. But when you bring a verb into it, what you''re doing is you''re bringing the element of time into it, right? It''s either past, present, or future, because nouns do not have a past, present, future. A tree is a tree. But once a tree begins to blow in the wind, now there is a time associated with it, right? Did it blow in the past? Is it blowing in the present, or will it blow in the future when the wind comes? So the tree swaying is an action of the essence of the tree. Without that action, the tree is just a tree, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'one believes that you know that the بسم الله الرحمن الرحيم sis of existence is a noun and theres another school of thought which is the more dominant school of thought which is also something that we subscribe to بسم الله الرحمن الرحيم sed on الم is that the بسم الله الرحمن الرحيم sis of existence is not a noun but rather a verb because if the بسم الله الرحمن الرحيم sis of existence is just a noun then youre simply talking about a state right like for example if we look at our state of being right as a human being were just simply here like im being here im existing here and theres no action involved in my being but when you bring a verb into it what youre doing is youre bringing the element of time into it right its either past present or future because nouns do not have a past present future a tree is a tree but once a tree begins to blow in the wind now there is a time associated with it right did it blow in the past is it blowing in the present or will it blow in the future when the wind comes so the tree swaying is an action of the essence of the tree without that action the tree is just a tree right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 2, NULL, 'It would just be a being. So, and this is a very interesting de‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎te about existence itself. Is the root of existence movement and action, or is it being? Because if you think about it, this is also true about اللَّهِ relationship with this universe, with us, because اللَّهُ سُبْحَانَهُ وَتَعَالَى has action, right? But His action is created. His actual essence, His ذَاتْ, is passive. There''s no action in His essence when we talk about اللَّهُ. So اللَّهُ is essence and attributes, but both essence and attributes are nothing more than states of being. But action is a substantive that moves into time. And that''s why the understanding in theology is that اللَّهُ is beyond time and space. So His action is something that manifested within creation or bringing about creation, right? He brings things into existence through His action, through His فَاتِحَة.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'it would just be a being so and this is a very interesting de بسم الله الرحمن الرحيم te about existence itself is the root of existence movement and action or is it being because if you think about it this is also true about الله relationship with this universe with us because الله سبحانه وتعالي has action right but his action is created his actual essence his ذات is passive theres no action in his essence when we talk about الله so الله is essence and attributes but both essence and attributes are nothing more than states of being but action is a substantive that moves into time and thats why the understanding in theology is that الله is beyond time and space so his action is something that manifested within creation or bringing about creation right he brings things into existence through his action through his فاتحه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 3, NULL, 'But then that فَاتِحَة is مَا دَسَّ. So, like as the Quran says, you know, when He decides an affair, what does He do? He says to it "be" and it becomes, right? So اللَّهُ brings creation into existence through a command, which is actually a فَاتِحَة, it is an action. And so the preposition is actually connected to the omitted verb of اللَّهِ action of creation. So when we recite the بِسْمِ اللهِ, what we''re saying, you know, when we say بِسْمِ اللهِ, what we''re saying is that I am beginning with the recognition of the lofty signs within اللَّهِ creation. Because those signs are a witness and a proof of His intense and consistent love, compassion, care, and mercy, His رَحْمَة. This is the context referring to the primordial act of اللَّهُ, the original creation. So this is the interpretation of that statement in the transcendent realm: that it is an acknowledgement of the fact that I''m beginning with the recognition of these lofty signs that exist for me within creation that are pointing to and that are bearing witness and acting as proof and evidence of His intense and consistent love and mercy. His رَحْمَانِيَّة and His رَحِيمِيَّة. So that is the interpretation of this verse in the transcendent realm. But what about its meaning in the imminent or the personal realm? Because as we talked about these two concepts earlier, there is the transcendent God and then there is the imminent God. So in the transcendent realm, we understand it because there are all these signs around us and they are depicting and illustrating اللَّهِ love and mercy for us. But what about in my personal life?', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'but then that فاتحه is ما دس so like as the quran says you know when he decides an affair what does he do he says to it be and it becomes right so الله brings creation into existence through a command which is actually a فاتحه it is an action and so the preposition is actually connected to the omitted verb of الله action of creation so when we recite the بسم الله what were saying you know when we say بسم الله what were saying is that i am beginning with the recognition of the lofty signs within الله creation because those signs are a witness and a proof of his intense and consistent love compassion care and mercy his رحمه this is the context referring to the primordial act of الله the original creation so this is the interpretation of that statement in the transcendent realm that it is an acknowledgement of the fact that im beginning with the recognition of these lofty signs that exist for me within creation that are pointing to and that are bearing witness and acting as proof and evidence of his intense and consistent love and mercy his رحمانيه and his رحيميه so that is the interpretation of this verse in the transcendent realm but what about its meaning in the imminent or the personal realm because as we talked about these two concepts earlier there is the transcendent god and then there is the imminent god so in the transcendent realm we understand it because there are all these signs around us and they are depicting and illustrating الله love and mercy for us but what about in my personal life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 4, NULL, 'How does بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ apply to me personally? So in order to understand that, let''s break down the statement into its grammatical components. And this may seem unnecessary or too technical, but actually there''s a very deep connection here. So first of all, when do we recite بِسْمِ اللهِ? Let''s start there. When do we recite the بِسْمِ اللهِ? We recite it at the beginning of every action. So now let''s look at this statement from a grammatical point of view to understand this better. What are the various grammatical components of this statement? So it obviously begins with the letter ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, which I just explained as a preposition. Then we have the word اِسْم, which is a genitive masculine noun.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'how does بسم الله الرحمن apply to me personally so in order to understand that lets break down the statement into its grammatical components and this may seem unnecessary or too technical but actually theres a very deep connection here so first of all when do we recite بسم الله lets start there when do we recite the بسم الله we recite it at the beginning of every action so now lets look at this statement from a grammatical point of view to understand this better what are the various grammatical components of this statement so it obviously begins with the letter بسم الله الرحمن الرحيم which i just explained as a preposition then we have the word اسم which is a genitive masculine noun', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 5, NULL, 'This noun on its own, this noun would be written as اِسْم with the alif, and meaning, you know, name. But because it''s joined with that preposition, the alif is dropped and the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ fuses with the اِسْم and it becomes بِسْمِ, making it an indefinite noun. Then we have the proper noun اللَّهُ itself, right? بِسْمِ اللهِ. So بِسْمِ اللهِ. So then we have اللَّهُ, which is the proper noun. And finally, the statement ends with two adjectives of mercy, which is الرَّحْمَٰن and رَحِيم. So we have a preposition, we have an indefinite noun, we have a proper noun, and we have two adjectives in the statement. What''s missing? From a grammatical point of view, what''s missing here to complete this sentence? A verb, you see? Because we know that grammatically a statement is incomplete without a verb. So اللَّهُ left the phrase ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ as an incomplete grammatical sentence. He omitted the verb. You see that? Why did he do that?', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'this noun on its own this noun would be written as اسم with the alif and meaning you know name but because its joined with that preposition the alif is dropped and the بسم الله الرحمن الرحيم fuses with the اسم and it becomes بسم making it an indefinite noun then we have the proper noun الله itself right بسم الله so بسم الله so then we have الله which is the proper noun and finally the statement ends with two adjectives of mercy which is الرحمن and رحيم so we have a preposition we have an indefinite noun we have a proper noun and we have two adjectives in the statement whats missing from a grammatical point of view whats missing here to complete this sentence a verb you see because we know that grammatically a statement is incomplete without a verb so الله left the phrase بسم الله الرحمن الرحيم as an incomplete grammatical sentence he omitted the verb you see that why did he do that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 6, NULL, 'Because we conceptually complete the sentence by providing the verb through our action. You see, we complete the grammatical structure of the sentence by providing the verb through our action. This is why we recite the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ at the beginning of every action, every task, every فَاتِحَة, thus providing the verb to complete the structure of the statement. سُبْحَانَ اللَّهِ. I mean, this is just incredible, to design a statement like this, right? So now if I''m about to read the Quran and I say ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ as I''m about to begin, my action of reading the Quran, of reciting the Quran, is what is now completing the بِسْمِ اللهِ. So now what I''m saying essentially is, with the name of اللَّهُ, in the name of اللَّهُ who is intensely and consistently loving and merciful, I begin reading this book. And so now my action of reading the Quran, or regardless of what that action is, no matter what it is, right, it could be anything, but that action itself now gets empowered by the بِسْمِ اللهِ. But what''s even more amazing is that if we look at this linguistically, ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sed on everything that we''ve learned, what I''m really saying, let''s say, let''s take the example of reciting the Quran, when I say ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ before reciting the Quran, what I''m really saying is that my ability to read and this Quran that I intend to read is a lofty sign pointing to اللَّهِ incredible love and mercy, His رَحْمَانِيَّة and His رَحِيمِيَّة. So what this does is that it puts اللَّهِ love and His mercy right at the center of my focus as soon as I recite this phrase. That''s what triggers in my mind اللَّهِ love and mercy, because whatever I''m doing is now becoming a sign for me, a lofty heavenly sign pointing to the love of my Creator. You see that?', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'because we conceptually complete the sentence by providing the verb through our action you see we complete the grammatical structure of the sentence by providing the verb through our action this is why we recite the بسم الله الرحمن الرحيم at the beginning of every action every task every فاتحه thus providing the verb to complete the structure of the statement سبحان الله i mean this is just incredible to design a statement like this right so now if im about to read the quran and i say بسم الله الرحمن الرحيم as im about to begin my action of reading the quran of reciting the quran is what is now completing the بسم الله so now what im saying essentially is with the name of الله in the name of الله who is intensely and consistently loving and merciful i begin reading this book and so now my action of reading the quran or regardless of what that action is no matter what it is right it could be anything but that action itself now gets empowered by the بسم الله but whats even more amazing is that if we look at this linguistically بسم الله الرحمن الرحيم sed on everything that weve learned what im really saying lets say lets take the example of reciting the quran when i say بسم الله الرحمن الرحيم before reciting the quran what im really saying is that my ability to read and this quran that i intend to read is a lofty sign pointing to الله incredible love and mercy his رحمانيه and his رحيميه so what this does is that it puts الله love and his mercy right at the center of my focus as soon as i recite this phrase thats what triggers in my mind الله love and mercy because whatever im doing is now becoming a sign for me a lofty heavenly sign pointing to the love of my creator you see that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 7, NULL, 'My very act of reading, regardless, or not reading, whatever it is, it could be anything, any action, it becomes a lofty sign and a symbol. It becomes a witness and it bears testimony to رَحْمَةُ اللَّهِ. And it completely transforms my perspective on that action that I''m about to do. And this transformation is now happening even before I''ve actually started doing it. سُبْحَانَ اللَّهِ. So if I say ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ before I begin driving, that entire experience of driving, it becomes a reminder of اللَّهِ love and mercy for me: my ability to drive, the resources enabling me to own a car, my mental capacity to follow the signs, my brain power to remember what all these signs means, when to start, when to stop, my ability to assess traffic, my intuition, my instincts of when to stop, when to go fast, when to slow down, all the facilities that my car provides to me, the scenery outside the car. The wind coming in, the refreshing wind coming in through the windows of the car, every single thing that I can think of becomes a lofty reminder that points me directly to اللَّهِ intense and consistent love, care, concern, and mercy for me. It is because of His mercy this action is happening. It''s all reminding me of the one who gave me this ability, provided me with all these resources in order to experience and enjoy His mercy. This is the power of بِسْمِ اللَّهِ. مَا شَآءَ ٱللَّهُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'my very act of reading regardless or not reading whatever it is it could be anything any action it becomes a lofty sign and a symbol it becomes a witness and it bears testimony to رحمه الله and it completely transforms my perspective on that action that im about to do and this transformation is now happening even before ive actually started doing it سبحان الله so if i say بسم الله الرحمن الرحيم before i begin driving that entire experience of driving it becomes a reminder of الله love and mercy for me my ability to drive the resources enabling me to own a car my mental capacity to follow the signs my brain power to remember what all these signs means when to start when to stop my ability to assess traffic my intuition my instincts of when to stop when to go fast when to slow down all the facilities that my car provides to me the scenery outside the car the wind coming in the refreshing wind coming in through the windows of the car every single thing that i can think of becomes a lofty reminder that points me directly to الله intense and consistent love care concern and mercy for me it is because of his mercy this action is happening its all reminding me of the one who gave me this ability provided me with all these resources in order to experience and enjoy his mercy this is the power of بسم الله ما شاء الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 8, NULL, 'It is incredible. I mean, it always blows my mind every time I think about it. اللَّهِ first act was ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sed on His رَحْمَة, right? He gave us this ability to act. And then every action that we do now becomes a witness to His love and His mercy. All of that so eloquently, so precisely, so concisely captured within the phrase ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎. I begin this task, this action, which is a lofty heavenly sign reminding me of اللَّهِ intense and consistent love, care, concern and mercy. اللهُ أَكْبَرُ. Now, what is the purpose of reciting the بِسْمِ اللهِ before we begin any action? Why do we do it? From our perspective, like I said, it reminds us of اللَّهِ love and mercy and naturally makes us love Him ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ck. It''s our love manifesting in the form of worship and obedience.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'it is incredible i mean it always blows my mind every time i think about it الله first act was بسم الله الرحمن الرحيم sed on his رحمه right he gave us this ability to act and then every action that we do now becomes a witness to his love and his mercy all of that so eloquently so precisely so concisely captured within the phrase بسم الله الرحمن الرحيم i begin this task this action which is a lofty heavenly sign reminding me of الله intense and consistent love care concern and mercy الله اكبر now what is the purpose of reciting the بسم الله before we begin any action why do we do it from our perspective like i said it reminds us of الله love and mercy and naturally makes us love him بسم الله الرحمن الرحيم ck its our love manifesting in the form of worship and obedience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 9, NULL, 'That''s what the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, if you think about it in this way, the way I''ve explained to you, and if you actually become conscious of اللَّهِ love and mercy in our life, because this is what the statement does, it just puts that love right in front of us, and if we actually are able to experience it, it increases us in our love for Him. But what does it do from اللَّهِ perspective? It fills our action with what is called بَرَكَة. That''s what the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ does. It fills our action with بَرَكَة, as اللَّهُ said, إِذَا أَتَيْتُ رَضِيتُ وَإِذَا رَضِيتُ بَارَكْتُ وَلَيْسَ لِبَرَكَتِي نِهَايَةٌ. When you obey me, it pleases me. When I''m pleased, I bless you with بَرَكَة, and there is absolutely no limit to my بَرَكَة.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'thats what the بسم الله الرحمن الرحيم if you think about it in this way the way ive explained to you and if you actually become conscious of الله love and mercy in our life because this is what the statement does it just puts that love right in front of us and if we actually are able to experience it it increases us in our love for him but what does it do from الله perspective it fills our action with what is called بركه thats what the بسم الله الرحمن الرحيم does it fills our action with بركه as الله said اذا اتيت رضيت واذا رضيت باركت وليس لبركتي نهايه when you obey me it pleases me when im pleased i bless you with بركه and there is absolutely no limit to my بركه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 10, NULL, 'So now, what is بَرَكَة? It is generally translated as abundance. Right now, what has abundance got to do with the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎? What has it got to do with the اِسْم of اللَّهُ? So اللَّهُ says in سُورَةُ الرَّحْمَٰنِ, it is the last verse of سُورَةُ الرَّحْمَٰنِ in which He says, تَبَرَكَ ٱسْمُ رَبِّكَ ذِى ٱلْجَلَلِ وَٱلْإِكْرَامِ. تَبَارَكَ اسْمُ, so it''s تَبَرَكَ ٱسْمُ رَبِّكَ, again due to the grammatical rules, they can convert, they converge, they fuse together, so تَبَرَكَ ٱسْمُ رَبِّكَ ذِى ٱلْجَلَلِ وَٱلْإِكْرَامِ. The name of اللَّهُ, the name of your master, is glorious and benevolent. His name is full of بَرَكَة. But اللَّهُ does not mention in this verse which name of اللَّهُ is full of بَرَكَة, right? He just says the name of your master is blessed. But which name? So what did the Surah begin with? It began with الرَّحْمَٰن. And what is the first attribute of اللَّهُ that is mentioned in the بِسْمِ اللهِ? So اللَّهُ is telling us something about this attribute الرَّحْمَٰن, that it is full of بَرَكَة.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'so now what is بركه it is generally translated as abundance right now what has abundance got to do with the بسم الله الرحمن الرحيم what has it got to do with the اسم of الله so الله says in سوره الرحمن it is the last verse of سوره الرحمن in which he says تبرك اسم ربك ذي الجلل والاكرام تبارك اسم so its تبرك اسم ربك again due to the grammatical rules they can convert they converge they fuse together so تبرك اسم ربك ذي الجلل والاكرام the name of الله the name of your master is glorious and benevolent his name is full of بركه but الله does not mention in this verse which name of الله is full of بركه right he just says the name of your master is blessed but which name so what did the surah begin with it began with الرحمن and what is the first attribute of الله that is mentioned in the بسم الله so الله is telling us something about this attribute الرحمن that it is full of بركه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 11, NULL, 'But then we also know that اللَّهُ Himself is full of بَرَكَة. Right now we just talked about the name of اللَّهُ being full of بَرَكَة, but then اللَّهُ Himself is full of بَرَكَة, because He says in the Quran, your اللَّهُ who is the best of creators is full of بَرَكَة. So I want you to keep these two things in mind: the اِسْم of اللَّهُ is full of بَرَكَة, and the name اللَّهُ itself is full of بَرَكَة. So the first two words in the بِسْمِ اللهِ, the بِسْمِ اللهِ, the اِسْم and the اللَّهُ, they''re both loaded with بَرَكَة. Right?', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'but then we also know that الله himself is full of بركه right now we just talked about the name of الله being full of بركه but then الله himself is full of بركه because he says in the quran your الله who is the best of creators is full of بركه so i want you to keep these two things in mind the اسم of الله is full of بركه and the name الله itself is full of بركه so the first two words in the بسم الله the بسم الله the اسم and the الله theyre both loaded with بركه right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 12, NULL, 'Now what do you think will naturally happen to our action when we recite these two powerful words before beginning whatever it is that we''re doing? It will naturally, obviously fill it with بَرَكَة. In other words, by reciting ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ before performing an action, not only are we reminding ourselves of اللَّهِ intense and consistent love and mercy through the act itself, but we''re also asking اللَّهُ to fill that action with بَرَكَة.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'now what do you think will naturally happen to our action when we recite these two powerful words before beginning whatever it is that were doing it will naturally obviously fill it with بركه in other words by reciting بسم الله الرحمن الرحيم before performing an action not only are we reminding ourselves of الله intense and consistent love and mercy through the act itself but were also asking الله to fill that action with بركه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 13, NULL, 'Now let''s look at this word بَرَكَة and understand what it means linguistically. So there is no word in the English language that can fully capture the meaning of the word بَرَكَة. So we need to look at this like a composite word, like رَبِّ and all these other things that we''ve understood. So we''ll have to look at it through a combination of certain concepts. In classical Arabic, the word بَرَكَة is defined as البَرَكَةُ النَّمَاءُ وَزِيَادَةٌ. It is growth and abundance. بَرَكَة is defined as growth and abundance. Now the first word is أَنْعَمْتَ, which means growth.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'now lets look at this word بركه and understand what it means linguistically so there is no word in the english language that can fully capture the meaning of the word بركه so we need to look at this like a composite word like رب and all these other things that weve understood so well have to look at it through a combination of certain concepts in classical arabic the word بركه is defined as البركه النماء وزياده it is growth and abundance بركه is defined as growth and abundance now the first word is انعمت which means growth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 14, NULL, 'Something that rises, something that increases in size, makes something that progresses consistently, increasing in the results all the time, or something that goes further and further and increases. It increases beyond expectations. So if you plant a seed of one single fruit in the ground, how many fruits should you get in return? Just one. That would be fair because you planted the seeds of one fruit. But you take the seeds from that one fruit and after you plant it in the ground, you get this enormous number of fruits in return, each producing hundreds of thousands of seeds. That is بَرَكَة. That is the concept of بَرَكَة, an unprecedented growth. You planted one seed and eventually got thousands of seeds as a result. It''s a growth beyond expectations. That is what is called بَرَكَة. Because if you think about it, what is the comparison of a tree with a seed?', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'something that rises something that increases in size makes something that progresses consistently increasing in the results all the time or something that goes further and further and increases it increases beyond expectations so if you plant a seed of one single fruit in the ground how many fruits should you get in return just one that would be fair because you planted the seeds of one fruit but you take the seeds from that one fruit and after you plant it in the ground you get this enormous number of fruits in return each producing hundreds of thousands of seeds that is بركه that is the concept of بركه an unprecedented growth you planted one seed and eventually got thousands of seeds as a result its a growth beyond expectations that is what is called بركه because if you think about it what is the comparison of a tree with a seed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 15, NULL, 'The tree came from the seed, but those two things are completely beyond comparison. A seed is tiny, a tree is huge. A seed is delicate, a tree is firm. A seed has no value, but the tree bears hundreds upon hundreds of fruits, season after season, year after year. So if you really think about it, what we get from a seed, this tree that we get from a seed, when you compare it to what we actually invested there, there''s really no comparison. And that is the concept of بَرَكَة, a ridiculous growth, an unlimited increase.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'the tree came from the seed but those two things are completely beyond comparison a seed is tiny a tree is huge a seed is delicate a tree is firm a seed has no value but the tree bears hundreds upon hundreds of fruits season after season year after year so if you really think about it what we get from a seed this tree that we get from a seed when you compare it to what we actually invested there theres really no comparison and that is the concept of بركه a ridiculous growth an unlimited increase', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 16, NULL, 'Then the Arabs say that referring to the rain that keeps on coming and coming and coming. So continuity is another characteristic of the word بَرَكَة. So it is growth, it is increase, but then there is a continuity associated with it. It doesn''t stop. It is extensively abundant. That is included in the meaning of بَرَكَة.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'then the arabs say that referring to the rain that keeps on coming and coming and coming so continuity is another characteristic of the word بركه so it is growth it is increase but then there is a continuity associated with it it doesnt stop it is extensively abundant that is included in the meaning of بركه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 17, NULL, 'Then the word بَرَكَة also includes the meaning of stability in the Arabic language. So for example, the Arab would say, you know, when it''s like when a camel just digs itself into the ground and it doesn''t move and it just doesn''t budge, that is also a quality of بَرَكَة. And this is actually a really beautiful concept, because if you think about it, when you grow something, right, and you grow it too much, so for example,', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'then the word بركه also includes the meaning of stability in the arabic language so for example the arab would say you know when its like when a camel just digs itself into the ground and it doesnt move and it just doesnt budge that is also a quality of بركه and this is actually a really beautiful concept because if you think about it when you grow something right and you grow it too much so for example', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 18, NULL, 'you know, my kids, they play with Legos, right? My son, he builds this tower, just block upon block upon block. He just puts this one huge tower. Now, as the tower is getting tall, does it become more stable or does it become less stable? It becomes less stable, right? The taller the tower is, the less stable it becomes. It will easily fall and break, right? And there''s not going to be any tower end left anymore. That''s how it works. So when something increases rapidly and it increases at a very fast pace, right, it becomes unstable. But when something has بَرَكَة in it, that means it will increase in quantity, it will keep increasing in quantity beyond expectations, yet remain as stable as the camel sunk into the sand. سُبْحَانَ اللَّهِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'you know my kids they play with legos right my son he builds this tower just block upon block upon block he just puts this one huge tower now as the tower is getting tall does it become more stable or does it become less stable it becomes less stable right the taller the tower is the less stable it becomes it will easily fall and break right and theres not going to be any tower end left anymore thats how it works so when something increases rapidly and it increases at a very fast pace right it becomes unstable but when something has بركه in it that means it will increase in quantity it will keep increasing in quantity beyond expectations yet remain as stable as the camel sunk into the sand سبحان الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 19, NULL, 'In other words, that increase of بَرَكَة is not going away. It''s not going to be unstable. It''s not an unstable increase. It''s a very consistent and stable increase. The more it grows, the stronger it will get. Because we find unstable increase all around us in this world, right? Our economy, I mean, goes up, crashes. Governments, they take over really fast, they disappear really fast. Fashion industry, right, there are all these trends that pick up really fast, disappear just as fast, so, you know, something else takes its place. But اللَّهُ says بَرَكَة is something that increases and increases and increases, but then it remains stable, it doesn''t go away. So that''s the linguistic understanding, the concept of the word بَرَكَة.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'in other words that increase of بركه is not going away its not going to be unstable its not an unstable increase its a very consistent and stable increase the more it grows the stronger it will get because we find unstable increase all around us in this world right our economy i mean goes up crashes governments they take over really fast they disappear really fast fashion industry right there are all these trends that pick up really fast disappear just as fast so you know something else takes its place but الله says بركه is something that increases and increases and increases but then it remains stable it doesnt go away so thats the linguistic understanding the concept of the word بركه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 20, NULL, 'So the name of اللَّهُ, the اِسْمُ اللهِ, is filled with بَرَكَة. The name اللَّهُ itself is filled with بَرَكَة. His blessed name is being mentioned since the day creation came into existence.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'so the name of الله the اسم الله is filled with بركه the name الله itself is filled with بركه his blessed name is being mentioned since the day creation came into existence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 21, NULL, 'And it only keeps increasing and growing with every single passing moment. That is an example of the بَرَكَة of اللَّهِ name. It keeps increasing and growing with every single second, and it will continue to grow till the very end of time, until there is no time left, right? I mean, worshipers come and go, but the one who is worshiped, he remains forever. The concept of worship has بَرَكَة in it, because it remains forever. اللَّهُ has been worshiped from the beginning of time. People who glorify the names of اللَّهُ, they come and go. Many came before us, many will come after us, we will all be gone one day, but the glory of اللَّهُ will always remain forever, eternal. This is the بَرَكَة of اللَّهِ name.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'and it only keeps increasing and growing with every single passing moment that is an example of the بركه of الله name it keeps increasing and growing with every single second and it will continue to grow till the very end of time until there is no time left right i mean worshipers come and go but the one who is worshiped he remains forever the concept of worship has بركه in it because it remains forever الله has been worshiped from the beginning of time people who glorify the names of الله they come and go many came before us many will come after us we will all be gone one day but the glory of الله will always remain forever eternal this is the بركه of الله name', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 22, NULL, 'So now, to summarize, when I recite ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ before each and every action that I do, my action itself turns into a reminder, a heavenly lofty sign pointing to the loving care and mercy of a الرَّحْمَٰن and a رَحِيم in my life. And what that does is it creates بَرَكَة in the results of my action, you see. It creates an abundance in my action. There''s a حَدِيثُ سُورَةِ الْفَاتِحَةِ of رَسُولُ اللهِ in which he says, every single act is sterile or infertile without . Every act that is done without the remembrance of اللَّهُ will have no بَرَكَة and no abundance in it. Now what does that mean?', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'so now to summarize when i recite بسم الله الرحمن الرحيم before each and every action that i do my action itself turns into a reminder a heavenly lofty sign pointing to the loving care and mercy of a الرحمن and a رحيم in my life and what that does is it creates بركه in the results of my action you see it creates an abundance in my action theres a حديث سوره الفاتحه of رسول الله in which he says every single act is sterile or infertile without every act that is done without the remembrance of الله will have no بركه and no abundance in it now what does that mean', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 23, NULL, 'In practical terms, what does that mean? What does abundance have to do with this? So think about it. If you have an abundance of anything, let''s say money, easiest example, right? Let''s say you have an abundance of money. What does it free you of? If you have a never-ending supply of money, what does it liberate you from? It frees you from ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎. It liberates you from the shackles of anxiety and depression, the two biggest killers of our time. It frees you from ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'in practical terms what does that mean what does abundance have to do with this so think about it if you have an abundance of anything lets say money easiest example right lets say you have an abundance of money what does it free you of if you have a never ending supply of money what does it liberate you from it frees you from الحمد لله رب العلمين it liberates you from the shackles of anxiety and depression the two biggest killers of our time it frees you from الحمد لله رب العلمين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 24, NULL, 'Because you''re no longer concerned about that aspect of your life, of where''s the money gonna come from. So you''ll never feel anxious about it and you''ll never feel depressed. You get anxious about something ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sed on fear. Whether it''s going to happen or not. That makes you anxious. Loss creates depression. And if you have that abundant supply of money, at least as far as money is concerned, you will never be anxious and you will never be depressed. Right?', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'because youre no longer concerned about that aspect of your life of wheres the money gonna come from so youll never feel anxious about it and youll never feel depressed you get anxious about something بسم الله الرحمن الرحيم sed on fear whether its going to happen or not that makes you anxious loss creates depression and if you have that abundant supply of money at least as far as money is concerned you will never be anxious and you will never be depressed right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 25, NULL, 'Now imagine if you have the abundance, a never-ending supply of رَحْمَةُ اللَّهِniya and رَحِيمِيَّة in your life. If you have a never-ending supply of رَحْمَةُ اللَّهِ in your life, if you have this abundance of ذِكْرُ اللَّهِ, this close connection with اللَّهُ, will anything or any situation in life, no matter how ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎d it is, will it be able to affect you? Will it make you feel anxious or depressed? Impossible. Completely impossible. Because no matter the outcome, you''re experiencing the joy of closeness, and you''re experiencing اللَّهِ love simply by the act itself, being reminded by بِسْمِ اللهِ. It immediately puts that into focus for you, because this دُنْيَا, شَيْطَان, all of these things that are working against us, make us forget اللَّهُ. But this is why we say بِسْمِ اللهِ, because if you think about it, if this is executed properly, we would be saying بِسْمِ اللهِ like a thousand times a day.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'now imagine if you have the abundance a never ending supply of رحمه اللهniya and رحيميه in your life if you have a never ending supply of رحمه الله in your life if you have this abundance of ذكر الله this close connection with الله will anything or any situation in life no matter how بسم الله الرحمن الرحيم d it is will it be able to affect you will it make you feel anxious or depressed impossible completely impossible because no matter the outcome youre experiencing the joy of closeness and youre experiencing الله love simply by the act itself being reminded by بسم الله it immediately puts that into focus for you because this دنيا شيطان all of these things that are working against us make us forget الله but this is why we say بسم الله because if you think about it if this is executed properly we would be saying بسم الله like a thousand times a day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 26, NULL, 'And every time we would say it, we would be reminded of this. سُبْحَانَ اللَّهِ. And so what رَسُولُ اللَّهِ, what he meant by that statement, that every state, every act is sterile and infertile without بِسْمِ اللهِ. What he meant by that is, without the love of اللَّهُ, without a focus on اللَّهُ, without a proximity to اللَّهُ, without the remembrance of اللَّهُ, no amount of physical abundance will satisfy you in this world.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'and every time we would say it we would be reminded of this سبحان الله and so what رسول الله what he meant by that statement that every state every act is sterile and infertile without بسم الله what he meant by that is without the love of الله without a focus on الله without a proximity to الله without the remembrance of الله no amount of physical abundance will satisfy you in this world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 27, NULL, 'And we find the greatest proof of this حَدِيث when we look at this world around us. Millionaires, billionaires who are extremely anxious and constantly in a state of depression. Lottery winners committing suicides, actors, stars, rocks, these singers, all the money in the world, all the دُنْيَا in the world, the best clothing, the most fancy cars, houses where they get lost, they can''t find an exit. Right? So much abundance of physical material, constantly anxious, constantly depressed, and they end up committing suicide. So physical abundance means nothing if there is no connection with اللَّهُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'and we find the greatest proof of this حديث when we look at this world around us millionaires billionaires who are extremely anxious and constantly in a state of depression lottery winners committing suicides actors stars rocks these singers all the money in the world all the دنيا in the world the best clothing the most fancy cars houses where they get lost they cant find an exit right so much abundance of physical material constantly anxious constantly depressed and they end up committing suicide so physical abundance means nothing if there is no connection with الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 28, NULL, 'On the other hand, on the flip side, we find these Muslims, these true Muslims and believers, these مُؤْمِنِينَ, who despite the worst of situations, they seem the most content and happy. I mean, I''ve personally met people like that. Just blows my mind, right? They''ve just, you know, two sets of clothes in their closet, drinking brown water, they cannot, they cannot even get clean water, but they''re content and happy like you won''t believe. Why? Because they''re connected to اللَّهُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'on the other hand on the flip side we find these muslims these true muslims and believers these مومنين who despite the worst of situations they seem the most content and happy i mean ive personally met people like that just blows my mind right theyve just you know two sets of clothes in their closet drinking brown water they cannot they cannot even get clean water but theyre content and happy like you wont believe why because theyre connected to الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 29, NULL, 'And that connection, it creates بَرَكَة in whatever little they have, to such a degree, to such an extent, that they are actually sincerely happy. They are content and so satisfied with what they have. So much so that they don''t even desire more. Imagine that. That is بَرَكَة. How do you take that away from someone? But that is the بَرَكَة of بِسْمِ اللهِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'and that connection it creates بركه in whatever little they have to such a degree to such an extent that they are actually sincerely happy they are content and so satisfied with what they have so much so that they dont even desire more imagine that that is بركه how do you take that away from someone but that is the بركه of بسم الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'in the name of allah the merciful', 'In the Name Of Allah The Merciful', 30, NULL, 'May اللَّهُ fill all our hearts with His love and His mercy, and enable us that every time we perform an action we remember Him from this day forth, and every time may He make that experience of that action, whatever it is that we''re doing, turn it into an experience of joy and a remembrance of His love and mercy in our lives. وَغَرَضُ دَوَامٍ الْحَمْدُ لِلَّهِ عَبْدِ الْعَالَمِينَ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتِمِ النَّبِيِّينَ وَسَيِّدِ الْمُوسَى وَالْأَقِي وَوَصِيِّ آلِ النَّبِيِّ تَعَالَى...', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'may الله fill all our hearts with his love and his mercy and enable us that every time we perform an action we remember him from this day forth and every time may he make that experience of that action whatever it is that were doing turn it into an experience of joy and a remembrance of his love and mercy in our lives وغرض دوام الحمد لله عبد العالمين والصلاه والسلام علي رسوله سيدنا محمد خاتم النبيين وسيد الموسي والاقي ووصي ال النبي تعالي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 0, NULL, 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ اللَّهُمَّ صَلِّ يَا اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي', '', 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ اللَّهُمَّ صَلِّ يَا اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي', NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل يا الله علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل يا الله علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 1, NULL, 'السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ So in the previous session, we learned that اللَّهُ created us as nouns, right? And just speaking in grammatical terms, we are all nouns in our essence, but then from the moment we wake up until the moment we go back to sleep, in fact, even while we''re asleep, what we''re constantly doing through our actions is creating verbs. So the power of ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ is that it provides a context for our verbs. It provides a context for our actions by turning them into these reminders, right? By turning our actions into these heavenly, lofty signs, these اِسْم of اللَّهُ, reminding us of His intense and consistent love, care, kindness, concern and mercy, which is His رَحْمَانِيَّة and His رَحِيمِيَّة. And once we experience His رُبُوبِيَّة, right, once we experience His رُبُوبِيَّة through our interactions with this الم that He created for us, because all of our actions are only happening because His رُبُوبِيَّة enables and empowers us to do that. Right? So I''m able to drink water because He gave me this physical capacity to pour water into a glass. And then He made water subservient through His laws of nature so that it obediently falls into the glass when I pour it. It doesn''t refuse. It doesn''t change its direction, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'السلام عليكم ورحمه الله وبركاته so in the previous session we learned that الله created us as nouns right and just speaking in grammatical terms we are all nouns in our essence but then from the moment we wake up until the moment we go back to sleep in fact even while were asleep what were constantly doing through our actions is creating verbs so the power of بسم الله الرحمن الرحيم is that it provides a context for our verbs it provides a context for our actions by turning them into these reminders right by turning our actions into these heavenly lofty signs these اسم of الله reminding us of his intense and consistent love care kindness concern and mercy which is his رحمانيه and his رحيميه and once we experience his ربوبيه right once we experience his ربوبيه through our interactions with this الم that he created for us because all of our actions are only happening because his ربوبيه enables and empowers us to do that right so im able to drink water because he gave me this physical capacity to pour water into a glass and then he made water subservient through his laws of nature so that it obediently falls into the glass when i pour it it doesnt refuse it doesnt change its direction right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 2, NULL, 'It doesn''t just start rising upwards in mid-air. It follows and obeys these laws of gravity that اللَّهُ created, allowing me, enabling me to drink it. Now what is this if not a sign of the mercy and love of اللَّهُ, where He enabled me and water to interact in this manner? This is His action, His proof of رُبُوبِيَّة executed with intense and consistent love and mercy. So now once I recognize and, more importantly, once I experience this love, what should be my natural response to that love? It has to be ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎. All praise and all gratitude belongs to اللَّهُ سُبْحَانَهُ وَتَعَالَى, the رَبِّ, the master of الْعَالَمِين. This is why the بَسْمَلَة directly connects with the الْحَمْدُ لِلَّهِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'it doesnt just start rising upwards in mid air it follows and obeys these laws of gravity that الله created allowing me enabling me to drink it now what is this if not a sign of the mercy and love of الله where he enabled me and water to interact in this manner this is his action his proof of ربوبيه executed with intense and consistent love and mercy so now once i recognize and more importantly once i experience this love what should be my natural response to that love it has to be الحمد لله رب العلمين all praise and all gratitude belongs to الله سبحانه وتعالي the رب the master of العالمين this is why the بسمله directly connects with the الحمد لله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 3, NULL, 'Now in today''s session, I want to do a linguistic study of this word حَمْد, to demonstrate the perfection of the statement so that we can appreciate why اللَّهُ used this particular word and why He used it in this particular fashion in this verse. You know, why didn''t He choose a different style for saying the same thing? So let''s begin with the word حَمْد itself, because this form of His diction, it veils many, many valuable lessons for us to learn from. The word حَمْد is actually a composite word that means two things.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'now in todays session i want to do a linguistic study of this word حمد to demonstrate the perfection of the statement so that we can appreciate why الله used this particular word and why he used it in this particular fashion in this verse you know why didnt he choose a different style for saying the same thing so lets begin with the word حمد itself because this form of his diction it veils many many valuable lessons for us to learn from the word حمد is actually a composite word that means two things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 4, NULL, 'It means praise and it means gratitude. Right? It''s praise plus gratitude. Now there are two other distinct words in the Arabic language for praise and gratitude. The commonly used word for praise is مَدَحَ and the word used for gratitude is شُكْر. Now what''s the difference? Praise, as we all know, is a gesture of appreciation. When you are moved by something that is beautiful or colorful or scenic, you know, when something intrigues you in some way, when something impresses you, what do you do? You praise it. You verbalize your appreciation by praising it. That''s the very natural human response to something that our soul finds beautiful or impressive.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'it means praise and it means gratitude right its praise plus gratitude now there are two other distinct words in the arabic language for praise and gratitude the commonly used word for praise is مدح and the word used for gratitude is شكر now whats the difference praise as we all know is a gesture of appreciation when you are moved by something that is beautiful or colorful or scenic you know when something intrigues you in some way when something impresses you what do you do you praise it you verbalize your appreciation by praising it thats the very natural human response to something that our soul finds beautiful or impressive', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 5, NULL, 'Now gratitude is something entirely different. Gratitude is done in response to a beneficial act that was done for you. Right? If somebody lends you money or does something nice for you, you say شُكْرًا. So gratitude is always done as a response to a beneficial act. So you see the difference? Praise is done when something impresses you, or when you appreciate something about someone. Whereas gratitude is done in response to a favor or a kindness that was done for you. Now even though these two terms are used interchangeably in our lives, they''re actually both mutually exclusive. Someone you thank is not necessarily someone you praise. قُرْآن clearly distinguishes between these two concepts.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'now gratitude is something entirely different gratitude is done in response to a beneficial act that was done for you right if somebody lends you money or does something nice for you you say شكرا so gratitude is always done as a response to a beneficial act so you see the difference praise is done when something impresses you or when you appreciate something about someone whereas gratitude is done in response to a favor or a kindness that was done for you now even though these two terms are used interchangeably in our lives theyre actually both mutually exclusive someone you thank is not necessarily someone you praise قران clearly distinguishes between these two concepts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 6, NULL, 'So for instance, in the story of مُوسَى, we know that he was adopted and raised in the house of فِرْعَوْن, right? And then years later when مُوسَى returns to deliver اللَّهُs message to فِرْعَوْن, he says to him, "How dare you? How dare you talk to me this way? Did we not raise you as a newborn in this house? Did you not spend many years of your life growing up here? How dare you speak to me like that?" In other words, فِرْعَوْن is saying, aren''t you grateful? I raised you for so many years and now you''re going against everything that I taught you? To that, مُوسَى responds, yes, you did in fact show me that favor, and for that I am grateful. So even though فِرْعَوْن is someone who will never be praised, especially not by a Prophet, but even when he does a favor, he will be thanked. So gratitude can exist without praise. You see?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'so for instance in the story of موسي we know that he was adopted and raised in the house of فرعون right and then years later when موسي returns to deliver اللهs message to فرعون he says to him how dare you how dare you talk to me this way did we not raise you as a newborn in this house did you not spend many years of your life growing up here how dare you speak to me like that in other words فرعون is saying arent you grateful i raised you for so many years and now youre going against everything that i taught you to that موسي responds yes you did in fact show me that favor and for that i am grateful so even though فرعون is someone who will never be praised especially not by a prophet but even when he does a favor he will be thanked so gratitude can exist without praise you see', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 7, NULL, 'In the case of parents, اللَّهُ says in سُورَةُ لُقْمَان, ‏وَوَصَّيْنَا ٱلْإِنسَنَ بِوَلِدَيْهِ حَمَلَتْهُ أُمُّهُۥ وَهْنًا عَلَىٰ وَهْنٍۢ وَفِصَلُهُۥ فِى عَامَيْنِ أَنِ ٱشْكُرْ لِى وَلِوَلِدَيْكَ إِلَىَّ ٱلْمَصِيرُ ‎. And we have made it compulsory, we have enjoined upon human beings the care for their parents. His mother carried him increasing in weakness upon weakness, and then in his weaning, which is in two years, so be grateful to me and to your parents, because to me is the final destination. So be grateful to me and both of your parents. But then He says, but if your parents are working against you, in forcing you to disbelieve and commit شِرْك against me, then do not obey them. But you still have to be what? You still have to be grateful to them. In other words, if your parents are forcing you to disbelieve in اللَّهُ, you don''t have to praise them, but you still have to be grateful to them. إِبْرَاهِيم is a good example of this, right? He does not praise his father, who according to the قُرْآن was an idol worshipper, but he is still grateful to him. So, الْمَدَّاح and الشُّكْرُ, praise and gratitude, these are two completely separate things. They are mutually exclusive. You can praise without being grateful, and then you can be grateful without praising someone or something. But what''s interesting about the word حَمْد is that it necessarily means both things together. It''s mutually inclusive.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'in the case of parents الله says in سوره لقمان ووصينا الانسن بولديه حملته امه وهنا علي وهن وفصله في عامين ان اشكر لي ولولديك الي المصير and we have made it compulsory we have enjoined upon human beings the care for their parents his mother carried him increasing in weakness upon weakness and then in his weaning which is in two years so be grateful to me and to your parents because to me is the final destination so be grateful to me and both of your parents but then he says but if your parents are working against you in forcing you to disbelieve and commit شرك against me then do not obey them but you still have to be what you still have to be grateful to them in other words if your parents are forcing you to disbelieve in الله you dont have to praise them but you still have to be grateful to them ابراهيم is a good example of this right he does not praise his father who according to the قران was an idol worshipper but he is still grateful to him so المداح and الشكر praise and gratitude these are two completely separate things they are mutually exclusive you can praise without being grateful and then you can be grateful without praising someone or something but whats interesting about the word حمد is that it necessarily means both things together its mutually inclusive', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 8, NULL, 'When اللَّهُ says الْحَمْدُ لِلَّهِ, He is saying praise is for اللَّهُ and gratitude is also for اللَّهُ, both at the same time. You understand the difference? What the word حَمْد does is that it makes both these concepts of مَدَحَ and شُكْر mutually inclusive. One cannot exist without the other within حَمْد. It means praise and it means gratitude. So now let''s look at why اللَّهُ did not use the word مَدَحَ and شُكْر and instead used the word حَمْد. So let''s start with مَدَحَ. Why didn''t اللَّهُ say all praise is for اللَّهُ? The problem with the word مَدَحَ is that it is a praise that does not necessarily have to be genuine. You see? Because we all know that praise can be insincere. Right? A kid walks in the house with a really bad report card, and as soon as he enters the house, he goes, "Mom, oh my God, your food, it smells so delicious." And she hasn''t even started cooking yet. Right?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'when الله says الحمد لله he is saying praise is for الله and gratitude is also for الله both at the same time you understand the difference what the word حمد does is that it makes both these concepts of مدح and شكر mutually inclusive one cannot exist without the other within حمد it means praise and it means gratitude so now lets look at why الله did not use the word مدح and شكر and instead used the word حمد so lets start with مدح why didnt الله say all praise is for الله the problem with the word مدح is that it is a praise that does not necessarily have to be genuine you see because we all know that praise can be insincere right a kid walks in the house with a really bad report card and as soon as he enters the house he goes mom oh my god your food it smells so delicious and she hasnt even started cooking yet right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 9, NULL, 'So he''s praising her, but it''s not a genuine praise. You get it? Because praise can be fake. There is fake praise done for kings, for bosses, for people in all these high positions all the time. Isn''t it? People falsely praise appearances all the time, right? Wife asks the husband, you know, "Does this dress make me look fat?" "Oh no, you look beautiful." That''s مَدَحَ. This is why in classical Arabic, when you praise someone''s looks, you never say حَمِدَ. Because everybody knows that the person that is being praised did not make their own face. If they''re pretty, if they''re beautiful, if they''re handsome, اللَّهُ made them that way.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'so hes praising her but its not a genuine praise you get it because praise can be fake there is fake praise done for kings for bosses for people in all these high positions all the time isnt it people falsely praise appearances all the time right wife asks the husband you know does this dress make me look fat oh no you look beautiful thats مدح this is why in classical arabic when you praise someones looks you never say حمد because everybody knows that the person that is being praised did not make their own face if theyre pretty if theyre beautiful if theyre handsome الله made them that way', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 10, NULL, 'So saying you''re so beautiful would just naturally be considered مَدَحَ. Because it is understood in language itself that praising looks and all these external features, it is inherently a false praise. Now حَمْد, on the other hand, cannot be a false praise. It cannot be insincere praise. Why? Because حَمْد is generated in the heart by the awareness of the magnificence and the glory of the one that is being praised. I''ll say that again. حَمْد, the praise element of حَمْد, that occurs when the heart becomes aware of the magnificence and the glory of the one being praised. The heart and the intellect together recognize that اللَّهُ truly deserves that praise. So therefore حَمْد can never be a false praise. Because the حَمْد of اللَّهُ is not dependent on a personal need.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'so saying youre so beautiful would just naturally be considered مدح because it is understood in language itself that praising looks and all these external features it is inherently a false praise now حمد on the other hand cannot be a false praise it cannot be insincere praise why because حمد is generated in the heart by the awareness of the magnificence and the glory of the one that is being praised ill say that again حمد the praise element of حمد that occurs when the heart becomes aware of the magnificence and the glory of the one being praised the heart and the intellect together recognize that الله truly deserves that praise so therefore حمد can never be a false praise because the حمد of الله is not dependent on a personal need', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 11, NULL, 'It is never motivated by a personal agenda. You see, it stems simply from being impressed by who He is, not based on what He does for us. So I hope that makes it clear. Now let''s think about the word شُكْر. What if اللَّهُ had said, "All gratitude is for اللَّهُ"? What would be the problem with that? Gratitude, or thanks, it originates from the acknowledgement of a favor. Someone does something for you that you appreciate, you thank that person for that favor. You have a flat tire, someone comes along and helps you, you feel grateful. And you express that gratitude by saying thank you. So thanks can only happen when you have a reason to thank someone, right? It is a reaction to a favor.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'it is never motivated by a personal agenda you see it stems simply from being impressed by who he is not based on what he does for us so i hope that makes it clear now lets think about the word شكر what if الله had said all gratitude is for الله what would be the problem with that gratitude or thanks it originates from the acknowledgement of a favor someone does something for you that you appreciate you thank that person for that favor you have a flat tire someone comes along and helps you you feel grateful and you express that gratitude by saying thank you so thanks can only happen when you have a reason to thank someone right it is a reaction to a favor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 12, NULL, 'It''s never something you start with, right? You don''t just walk onto a street, see a stranger passing by and go, "Hey, you, thank you," right? You never do that. When اللَّهُ uses the word حَمْد, which is a combination of both praise and gratitude, there are certain rules that apply linguistically. First rule is that the praise aspect of حَمْد has to be genuine. It can never be fake. Second, the gratitude aspect of it is not reactionary. You see? So حَمْد is sincere praise and it is not a gratitude that is in response to what He does for us. Therefore, linguistically, saying الْحَمْدُ لِلَّهِ is far more powerful than saying اَلْحَمْدُ لِلَّٰهِ, and it is far more powerful than saying الشُّكْرُ لِلَّهِ, because it is a lot more comprehensive than both of them.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'its never something you start with right you dont just walk onto a street see a stranger passing by and go hey you thank you right you never do that when الله uses the word حمد which is a combination of both praise and gratitude there are certain rules that apply linguistically first rule is that the praise aspect of حمد has to be genuine it can never be fake second the gratitude aspect of it is not reactionary you see so حمد is sincere praise and it is not a gratitude that is in response to what he does for us therefore linguistically saying الحمد لله is far more powerful than saying الحمد لله and it is far more powerful than saying الشكر لله because it is a lot more comprehensive than both of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 13, NULL, 'Okay, so now what if اللَّهُ had said, الْمَدْحُ وَالشُّكْرُ لِلَّهِ رَبِّ الْعَالَمِينَ, "Praise and gratitude belongs to اللَّهُ"? What would be the problem with that? Even if we remove the shortcomings of both these words, مَدَحَ and شُكْر, the problem now is that when you put the word "and" in between the two things, which is the letter وَوْ, right? When you add that وَوْ, that "and" in the middle, the problem is that it separates both words even in meaning linguistically. So when I say linguistically, what I''m saying is that praise belongs to اللَّهُ for certain things and gratitude belongs to اللَّهُ for other things. They''re not always combined because the words aren''t combined. You see, this is a very cool feature of Arabic language: you never say what you don''t mean. So if we use the two words gratitude and praise and join them with an "and", in classical Arabic that means sometimes I''m in the mood to praise Him but not necessarily thank Him. And then there are other times when I''m in the mood to thank Him but not necessarily praise Him. But when اللَّهُ says الْحَمْدُ لِلَّهِ, that means for every act that He does or doesn''t do, for every blessing He gives or holds back, genuine praise and unconditional gratitude is due to Him, both at the same time. We do not get to pick and choose which one.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'okay so now what if الله had said المدح والشكر لله رب العالمين praise and gratitude belongs to الله what would be the problem with that even if we remove the shortcomings of both these words مدح and شكر the problem now is that when you put the word and in between the two things which is the letter وو right when you add that وو that and in the middle the problem is that it separates both words even in meaning linguistically so when i say linguistically what im saying is that praise belongs to الله for certain things and gratitude belongs to الله for other things theyre not always combined because the words arent combined you see this is a very cool feature of arabic language you never say what you dont mean so if we use the two words gratitude and praise and join them with an and in classical arabic that means sometimes im in the mood to praise him but not necessarily thank him and then there are other times when im in the mood to thank him but not necessarily praise him but when الله says الحمد لله that means for every act that he does or doesnt do for every blessing he gives or holds back genuine praise and unconditional gratitude is due to him both at the same time we do not get to pick and choose which one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 14, NULL, 'So now if you own a nice car and you say الْحَمْدُ لِلَّهِ, what have you just done? You''ve genuinely praised اللَّهُ for giving human beings this knowledge and this ability to create cars, to design and manufacture them, and you thank اللَّهُ for letting you own one. So now you''re praising and thanking اللَّهُ both at the same time, and all of that is eloquently captured in the beautiful word حَمْد. الْحَمْدُ لِلَّهِ. This is why حَمْد is the attitude of a true believer, because it is optimistic by its nature. You know, sometimes you''re going through a difficult time and somebody says, "How are you doing?" and you say, "Oh, you know, life sucks, but الْحَمْدُ لِلَّهِ." So you''re not really praising اللَّهُ or thanking Him when you say الْحَمْدُ لِلَّهِ that way, right? الْحَمْدُ لِلَّهِ is not a phrase that believers just throw around, because it is the reminder of an attitude.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'so now if you own a nice car and you say الحمد لله what have you just done youve genuinely praised الله for giving human beings this knowledge and this ability to create cars to design and manufacture them and you thank الله for letting you own one so now youre praising and thanking الله both at the same time and all of that is eloquently captured in the beautiful word حمد الحمد لله this is why حمد is the attitude of a true believer because it is optimistic by its nature you know sometimes youre going through a difficult time and somebody says how are you doing and you say oh you know life sucks but الحمد لله so youre not really praising الله or thanking him when you say الحمد لله that way right الحمد لله is not a phrase that believers just throw around because it is the reminder of an attitude', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 15, NULL, 'اللَّهُ is never interested in what comes out of our tongues. He''s more interested in what''s in our hearts that is connected with what comes out of our tongues. So when a believer says الْحَمْدُ لِلَّهِ, regardless of the situation or circumstances, the sentiment that resides in his heart is that indeed, without a doubt, all praise and all gratitude belongs to اللَّهُ regardless of my situation. If I''m going through a difficult time and I say الْحَمْدُ لِلَّهِ, what I mean is, indeed my praise and my gratitude is for اللَّهُ, because no matter what I''m going through, it could always be worse. Someone right now in this world is going through a much harsher version of what I''m going through right now, and he can then say the same for somebody else, and that person can say the same for somebody else, because no matter what problem we go through, it could always be worse. So I''m grateful to اللَّهُ that He is lenient with me. I''m grateful to اللَّهُ that He has provided me with the resources to fix my situation, because there might be someone who just doesn''t have the same resources that I do. And I praise Him for His majesty. And this acknowledgement of how the one who gives help can take it away and then restore it whenever He desires. Because my pain is supposed to remind me of all the times اللَّهُ had me living in comfort in which I forgot about Him. So الْحَمْدُ لِلَّهِ, sincere praises and unconditional gratitude belongs to the one who reminded me of His grace and His blessings by temporarily or even permanently taking it away. الْحَمْدُ لِلَّهِ, sincere praises and unconditional gratitude belongs to the one who filled my life with undeserved blessings, even in my state of pain, even in my state of difficulty. So an understanding of الْحَمْدُ لِلَّهِ can really empower us, and it can completely transform our attitudes towards life itself as believers.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'الله is never interested in what comes out of our tongues hes more interested in whats in our hearts that is connected with what comes out of our tongues so when a believer says الحمد لله regardless of the situation or circumstances the sentiment that resides in his heart is that indeed without a doubt all praise and all gratitude belongs to الله regardless of my situation if im going through a difficult time and i say الحمد لله what i mean is indeed my praise and my gratitude is for الله because no matter what im going through it could always be worse someone right now in this world is going through a much harsher version of what im going through right now and he can then say the same for somebody else and that person can say the same for somebody else because no matter what problem we go through it could always be worse so im grateful to الله that he is lenient with me im grateful to الله that he has provided me with the resources to fix my situation because there might be someone who just doesnt have the same resources that i do and i praise him for his majesty and this acknowledgement of how the one who gives help can take it away and then restore it whenever he desires because my pain is supposed to remind me of all the times الله had me living in comfort in which i forgot about him so الحمد لله sincere praises and unconditional gratitude belongs to the one who reminded me of his grace and his blessings by temporarily or even permanently taking it away الحمد لله sincere praises and unconditional gratitude belongs to the one who filled my life with undeserved blessings even in my state of pain even in my state of difficulty so an understanding of الحمد لله can really empower us and it can completely transform our attitudes towards life itself as believers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 16, NULL, 'Now let''s look at this term from a grammatical perspective. In language, we have nouns and we have verbs, right? We all know the difference. Verbs, they have tenses, whereas nouns, they don''t. There''s no past tense nouns or present tense nouns or, you know, future tense noun. So now when I say I praise اللَّهُ, I praise اللَّهُ, am I using a noun or a verb? I''m using a verb. It''s a present tense verb. But when اللَّهُ says praise belongs to اللَّهُ, is the word praise a noun or a verb? Here it''s a noun. You see, اللَّهُ could have used a verb.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'now lets look at this term from a grammatical perspective in language we have nouns and we have verbs right we all know the difference verbs they have tenses whereas nouns they dont theres no past tense nouns or present tense nouns or you know future tense noun so now when i say i praise الله i praise الله am i using a noun or a verb im using a verb its a present tense verb but when الله says praise belongs to الله is the word praise a noun or a verb here its a noun you see الله could have used a verb', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 17, NULL, 'He could have said الْحَمْدُ لِلَّهِ, I praise اللَّهُ. He could have said نَحْمَدُ اللهَ, we praise اللَّهُ. But اللَّهُ did not use a verb. He used a noun. Why? Because when I use a verb, there''s obviously going to be a tense associated with it. So when I use a present tense to say I praise اللَّهُ, then I''m only talking about the present. I''m not saying anything about the past or the future. You see? If I use the past tense, then I''m not guaranteeing anything about the future or the present. Because the verb limits and confines the action within time. It makes the action temporary.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'he could have said الحمد لله i praise الله he could have said نحمد الله we praise الله but الله did not use a verb he used a noun why because when i use a verb theres obviously going to be a tense associated with it so when i use a present tense to say i praise الله then im only talking about the present im not saying anything about the past or the future you see if i use the past tense then im not guaranteeing anything about the future or the present because the verb limits and confines the action within time it makes the action temporary', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 18, NULL, 'But اللَّهُ used a noun, which by its nature is permanent. Therefore, اللَّهُs genuine praise and unconditional gratitude, it has been described with permanence. And what that means is that I may be praising اللَّهُ right now, but the praise of اللَّهُ has always been there and will always be there. I''m not going to be here in this world forever, but the praise and the gratitude of اللَّهُ is always going to be here forever. His praise and His gratitude is not dependent on me. It''s not dependent on you. It''s not dependent on this world. This is a huge reality encapsulated within الْحَمْدُ لِلَّهِ, this concept of permanence in the praise and gratitude of اللَّهُ. It is a recognition of the fact that حَمْد is not dependent on my temporary existence. حَمْد is not because of me. See, when you use a verb, somebody always needs to do the verb, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'but الله used a noun which by its nature is permanent therefore اللهs genuine praise and unconditional gratitude it has been described with permanence and what that means is that i may be praising الله right now but the praise of الله has always been there and will always be there im not going to be here in this world forever but the praise and the gratitude of الله is always going to be here forever his praise and his gratitude is not dependent on me its not dependent on you its not dependent on this world this is a huge reality encapsulated within الحمد لله this concept of permanence in the praise and gratitude of الله it is a recognition of the fact that حمد is not dependent on my temporary existence حمد is not because of me see when you use a verb somebody always needs to do the verb right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 19, NULL, 'It''s called the subject, or the فَاتِحَة in Arabic. There has to be a doer for an action. You can''t just go into a conversation and say, failed the test. Who failed the test? Right? You can''t just say disappeared. What disappeared? Oh, your book disappeared. You understand? When you use a verb, you always need someone to do that work. But a noun doesn''t need a doer. A noun doesn''t need a subject. It is independent all by itself, right? An apple is an apple. It can exist all by itself, independent of any doer. So when اللَّهُ used the word الْحَمْدُ, He made it a noun. He made it independent, because He doesn''t need anyone to actually do the praising, and He doesn''t need anyone to be grateful. Had He used a verb instead, that would have meant that He needed someone to praise Him and He needed someone to be grateful to Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'its called the subject or the فاتحه in arabic there has to be a doer for an action you cant just go into a conversation and say failed the test who failed the test right you cant just say disappeared what disappeared oh your book disappeared you understand when you use a verb you always need someone to do that work but a noun doesnt need a doer a noun doesnt need a subject it is independent all by itself right an apple is an apple it can exist all by itself independent of any doer so when الله used the word الحمد he made it a noun he made it independent because he doesnt need anyone to actually do the praising and he doesnt need anyone to be grateful had he used a verb instead that would have meant that he needed someone to praise him and he needed someone to be grateful to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 20, NULL, 'So He removed the construction of time and space by using a noun. Now what this means is that even if there was not a single creation in the world, the حَمْد of اللَّهُ would still be there. It would still exist. Even after this world, this universe fades into non-existence, His praise and His gratitude will remain. Because it does not require a doer or a subject. سُبْحَانَ اللَّهِ. All of this is captured by one single word, used grammatically as a noun.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'so he removed the construction of time and space by using a noun now what this means is that even if there was not a single creation in the world the حمد of الله would still be there it would still exist even after this world this universe fades into non existence his praise and his gratitude will remain because it does not require a doer or a subject سبحان الله all of this is captured by one single word used grammatically as a noun', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 21, NULL, 'You know, sometimes we have these questions. Kids sometimes ask this question, like, why does He need to be praised? Why does He need our gratitude? So just the usage of this word, the grammatical way in which the word الْحَمْدُ is used, clearly answers that question, that He does not need our praise and He does not need our gratitude.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'you know sometimes we have these questions kids sometimes ask this question like why does he need to be praised why does he need our gratitude so just the usage of this word the grammatical way in which the word الحمد is used clearly answers that question that he does not need our praise and he does not need our gratitude', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 22, NULL, 'Okay, now let''s look at some other possible variations, because I wanna—I''m just going over this just to show you the perfection that اللَّهُ has used in just one single verse. Imagine the entire قُرْآن. Every single verse of the قُرْآن is perfect in this manner. And so just by appreciating one single verse, we can really appreciate the entire قُرْآن. حَضْرَة Ali Sahib used to give this beautiful example, that if you want to find out that, you know, if you''re cooking rice and you want to know that the rice has been properly cooked, you just check a couple of grains. You don''t check every single grain, right? So I love that analogy, because, you know, that''s exactly what we''re doing. We''re just looking at a couple of verses and studying its perfection, and that pretty much gives us an idea of the entire perfection of قُرْآن.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'okay now lets look at some other possible variations because i wanna im just going over this just to show you the perfection that الله has used in just one single verse imagine the entire قران every single verse of the قران is perfect in this manner and so just by appreciating one single verse we can really appreciate the entire قران حضره ali sahib used to give this beautiful example that if you want to find out that you know if youre cooking rice and you want to know that the rice has been properly cooked you just check a couple of grains you dont check every single grain right so i love that analogy because you know thats exactly what were doing were just looking at a couple of verses and studying its perfection and that pretty much gives us an idea of the entire perfection of قران', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 23, NULL, 'So let''s look at some other variations here. What if اللَّهُ had said, right, what if He used a command: praise اللَّهُ, the master of الْعَالَمِين. Now wouldn''t that have been better? Because after all, He is a master.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'so lets look at some other variations here what if الله had said right what if he used a command praise الله the master of العالمين now wouldnt that have been better because after all he is a master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 24, NULL, 'So a command would just naturally make sense. So why didn''t He make it a command? I''ll give you an example to help you understand. I tell my daughter to bring me a glass of water. Right? I say, "Hey Adam, bring me a glass of water." I give it a command. Now once she hears me, she has only two possible choices. She can either bring me the glass of water or she can bring me the glass of water, right? Those are the only two clear choices as far as I''m concerned. So now, if اللَّهُ commanded us to praise Him, you know, as a command, what are the two things that could have happened?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'so a command would just naturally make sense so why didnt he make it a command ill give you an example to help you understand i tell my daughter to bring me a glass of water right i say hey adam bring me a glass of water i give it a command now once she hears me she has only two possible choices she can either bring me the glass of water or she can bring me the glass of water right those are the only two clear choices as far as im concerned so now if الله commanded us to praise him you know as a command what are the two things that could have happened', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 25, NULL, 'Some would praise Him, some would obey His command, and then there would be others who would disobey Him. Because when you tell someone to do something, the ball is now in their court. Right? It depends on them to comply with your wishes, with your command. Maybe they''ll choose to do it, maybe they won''t. اللَّهُ did not talk about His praise and His gratitude in a way that is dependent on us. You see, He did not put the ball in our court. He said, whether you do it or not, whether you are grateful to me or not, whether you choose to praise me or not, my praise and my gratitude, my حَمْد, is always there. It has always been there, it will be there forever. Human beings will come and go, nations will come and go, generations after generations will come and go, this universe itself will come and go, but the حَمْد of اللَّهُ will always be there. It is simply a matter of fact.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'some would praise him some would obey his command and then there would be others who would disobey him because when you tell someone to do something the ball is now in their court right it depends on them to comply with your wishes with your command maybe theyll choose to do it maybe they wont الله did not talk about his praise and his gratitude in a way that is dependent on us you see he did not put the ball in our court he said whether you do it or not whether you are grateful to me or not whether you choose to praise me or not my praise and my gratitude my حمد is always there it has always been there it will be there forever human beings will come and go nations will come and go generations after generations will come and go this universe itself will come and go but the حمد of الله will always be there it is simply a matter of fact', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 26, NULL, 'So now, what if اللَّهُ had said, certainly, for sure, absolutely no doubt about it, حَمْد is for اللَّهُ? Wouldn''t that sound a lot more powerful than just saying all praise and all gratitude belongs to اللَّهُ? Right? It does sound more powerful, doesn''t it? So how come اللَّهُ didn''t say so? If you remember from our sessions on the miracles of قُرْآن, you know, when we had that topic of conversation, when we talked about conversation and communication itself, I told you there are two kinds of communications, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'so now what if الله had said certainly for sure absolutely no doubt about it حمد is for الله wouldnt that sound a lot more powerful than just saying all praise and all gratitude belongs to الله right it does sound more powerful doesnt it so how come الله didnt say so if you remember from our sessions on the miracles of قران you know when we had that topic of conversation when we talked about conversation and communication itself i told you there are two kinds of communications right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 27, NULL, 'A communication can either be informative or it can be emotional, right? It can be جُمْلَةٌ إِنْشَائِيَّةٌ or it can be جُمْلَةٌ خَبَرِيَّةٌ. Either you have speech that is expressing your feelings and emotions, or you have speech that is communicating information. Those are the two kinds of speech that human beings are capable of. That''s it. Right? So for example, right now, as I''m teaching you about الْحَمْدُ, am I delivering information or am I expressing my emotions? I am delivering information. This is informative speech. But when I''m talking to my friend and I''m telling my friend how I feel about someone or something, what kind of communication is that? That is an emotional conversation.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'a communication can either be informative or it can be emotional right it can be جمله انشاييه or it can be جمله خبريه either you have speech that is expressing your feelings and emotions or you have speech that is communicating information those are the two kinds of speech that human beings are capable of thats it right so for example right now as im teaching you about الحمد am i delivering information or am i expressing my emotions i am delivering information this is informative speech but when im talking to my friend and im telling my friend how i feel about someone or something what kind of communication is that that is an emotional conversation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 28, NULL, 'So those are the only two types of speech that we as human beings are capable of. The thing is that in Arabic linguistics, when you use إِنَّا, the statement can only be informative. You see, it can only be factual. It can never be emotional. That''s just a linguistic rule, that if you use إِنَّا before a statement, it just becomes informative. Indeed, we sent this قُرْآن in the night of power. It''s information. It''s factual. It''s not an emotional conversation. Because the word إِنَّ removes the emotion out of the statement. But if you don''t use the word إِنَّ, then that communication can be informative, but it can also be emotional. You understand?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'so those are the only two types of speech that we as human beings are capable of the thing is that in arabic linguistics when you use انا the statement can only be informative you see it can only be factual it can never be emotional thats just a linguistic rule that if you use انا before a statement it just becomes informative indeed we sent this قران in the night of power its information its factual its not an emotional conversation because the word ان removes the emotion out of the statement but if you dont use the word ان then that communication can be informative but it can also be emotional you understand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 29, NULL, 'So by not using إِنَّ, اللَّهُ made His حَمْد an open statement. We can now talk about اللَّهُs praise and gratitude with other people in order to teach them about it, to give them information about it, but we can also make it a statement to express our own emotions. سُبْحَانَ اللَّهِ. Can you appreciate the beauty of this? So using this style right now, by saying ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎, I am sharing with you, I am teaching you about اللَّهُs حَمْد. A few hours later, when I''m standing in صَلَاةٌ before اللَّهُ and I use the exact same phrase, ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎, I will be expressing my praise and my gratitude to my master. The same statement will now become an emotional conversation for me. سُبْحَانَ اللَّهِ. So you can see how perfect the usage of this word is in the context of الْفَاتِحَة.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'so by not using ان الله made his حمد an open statement we can now talk about اللهs praise and gratitude with other people in order to teach them about it to give them information about it but we can also make it a statement to express our own emotions سبحان الله can you appreciate the beauty of this so using this style right now by saying الحمد لله رب العلمين i am sharing with you i am teaching you about اللهs حمد a few hours later when im standing in صلاه before الله and i use the exact same phrase الحمد لله رب العلمين i will be expressing my praise and my gratitude to my master the same statement will now become an emotional conversation for me سبحان الله so you can see how perfect the usage of this word is in the context of الفاتحه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 30, NULL, 'So I hope this really gives you a deeper appreciation of the perfection of this language and how one thing flows into another, how ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎ connects with ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, and how perfect the usage of this word حَمْد is. So, to summarize this entire concept of praise and gratitude in grammatical terms, we are nouns and we create verbs through our actions.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'so i hope this really gives you a deeper appreciation of the perfection of this language and how one thing flows into another how الحمد لله رب العلمين connects with بسم الله الرحمن الرحيم and how perfect the usage of this word حمد is so to summarize this entire concept of praise and gratitude in grammatical terms we are nouns and we create verbs through our actions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 31, NULL, 'Right? We are nouns, اللَّهُ created us as nouns, as beings, as essence and we create verbs through our actions. Now اللَّهُ is also a noun and He created verbs through His action. This is اللَّهُ creating us in His own image. Right? Now on a daily basis we are interacting with اللَّهُ and He is interacting with us, right, through His رُبِّيَ, over His الم, He is interacting with us and we through our worship and obedience and praise, we are interacting with Him. Now, in this interaction, listen to this carefully, in this interaction between us and اللَّهُ سُبْحَانَهُ وَتَعَالَى, for the recognition of the noun that اللَّهُ is, He is worthy of our مَدَاح. He is worthy of our sincere and independent praise. And for all His actions influencing our existence, He is worthy of our شُكْر, our ultimate and unconditional gratitude. الْحَمْدُ لِلَّهِ covers both aspects of our existence and His existence. You see?', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'right we are nouns الله created us as nouns as beings as essence and we create verbs through our actions now الله is also a noun and he created verbs through his action this is الله creating us in his own image right now on a daily basis we are interacting with الله and he is interacting with us right through his ربي over his الم he is interacting with us and we through our worship and obedience and praise we are interacting with him now in this interaction listen to this carefully in this interaction between us and الله سبحانه وتعالي for the recognition of the noun that الله is he is worthy of our مداح he is worthy of our sincere and independent praise and for all his actions influencing our existence he is worthy of our شكر our ultimate and unconditional gratitude الحمد لله covers both aspects of our existence and his existence you see', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 32, NULL, 'For the recognition of the noun that اللَّهُ سُبْحَانَهُ وَتَعَالَى is, for the مَعْرِفَةٌ of His essence, which is impossible, but as much as we can learn about اللَّهُ سُبْحَانَهُ وَتَعَالَى, our natural response to learning about understanding who اللَّهُ سُبْحَانَهُ وَتَعَالَى is, He becomes worthy of our sincere praise. And then for what He does for us, how He influences our existence, He becomes worthy of our unconditional gratitude. Both these concepts are beautifully, perfectly, eloquently encapsulated in this one single phrase: all forms of sincere praise belongs to اللَّهُ for who He is. And all forms of unconditional gratitude, whether it''s on a personal level or a universal level, it belongs to اللَّهُ for what He did, for what He does and for what He will do. Because His actions are constantly manifesting on the stage that we call the الم. Therefore, ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'for the recognition of the noun that الله سبحانه وتعالي is for the معرفه of his essence which is impossible but as much as we can learn about الله سبحانه وتعالي our natural response to learning about understanding who الله سبحانه وتعالي is he becomes worthy of our sincere praise and then for what he does for us how he influences our existence he becomes worthy of our unconditional gratitude both these concepts are beautifully perfectly eloquently encapsulated in this one single phrase all forms of sincere praise belongs to الله for who he is and all forms of unconditional gratitude whether its on a personal level or a universal level it belongs to الله for what he did for what he does and for what he will do because his actions are constantly manifesting on the stage that we call the الم therefore الحمد لله رب العلمين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'linguistic perfection of hamd', 'Linguistic Perfection Of HAMD', 33, NULL, 'وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتَمِ الَّذِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ وَعَلَى أَخِيهِ وَوَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِمُ الطَّيِّبِينَ الطَّاهِرِينَ وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ، الْفَاتِحَة', '', 'وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتَمِ الَّذِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ وَعَلَى أَخِيهِ وَوَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِمُ الطَّيِّبِينَ الطَّاهِرِينَ وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ، الْفَاتِحَة', NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'واخر دعوانا ان الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد خاتم الذيين وسيد المرسلين وعلي اخيه ووصيه علي بن ابي طالب اشرف الوصيين وعلي الايمه من ذريتهم الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه', 'واخر دعوانا ان الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد خاتم الذيين وسيد المرسلين وعلي اخيه ووصيه علي بن ابي طالب اشرف الوصيين وعلي الايمه من ذريتهم الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 0, NULL, 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ', '', 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ', NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي السلام عليكم ورحمه الله وبركاته', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي السلام عليكم ورحمه الله وبركاته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 1, NULL, 'In the previous session, we did a linguistic study of this word الْحَمْدُ. We learned that it is a combination of sincere praise and unconditional gratitude that is owed to اللهُ سُبْحَانَهُ وَتَعَالَى for His constant, relentless, never-ending رُبُوِيَّة over His الْعَالَمِينَ that He created for us. And then it''s not just حَمْدٌ, but rather it is الْحَمْدُ, which means the ultimate praise, and it means the absolute gratitude belongs to Him by virtue of Him being our رَبٌّ.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'in the previous session we did a linguistic study of this word الحمد we learned that it is a combination of sincere praise and unconditional gratitude that is owed to الله سبحانه وتعالي for his constant relentless never ending ربويه over his العالمين that he created for us and then its not just حمد but rather it is الحمد which means the ultimate praise and it means the absolute gratitude belongs to him by virtue of him being our رب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 2, NULL, 'So now the سُورَةُ الْفَاتِحَة continues and He says, الرَّحْمَٰن, الرَّحِيم, the Abundantly Merciful and the Consistently Merciful. We''ve looked at this word in great detail in one of the previous sessions, so I''m not going to go into the meanings of it linguistically or otherwise so much, but rather today I want to explore some of the examples of His رَحْمَة. But just a quick word on رَحْمَة itself is, you know, generally we know that it means mercy. But it is actually a type of mercy that brings two things together. رَحْمَة is the type of love, the type of mercy that actually brings two things together in a way such that the principles of رُبُوبِيَّة can be applied to that thing. Right? And this is why the womb of a mother is called a رَحْم, because it brings the baby, the fetus, and the mother together, so the mother can nurture it, so that she can shower her love over this fetus, so that she can help sustain the fetus and then make it grow. So the word رَحْمَة is so powerful that, you know, our general understanding of these words like mercy, you know, they fall short in really capturing its essence.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'so now the سوره الفاتحه continues and he says الرحمن الرحيم the abundantly merciful and the consistently merciful weve looked at this word in great detail in one of the previous sessions so im not going to go into the meanings of it linguistically or otherwise so much but rather today i want to explore some of the examples of his رحمه but just a quick word on رحمه itself is you know generally we know that it means mercy but it is actually a type of mercy that brings two things together رحمه is the type of love the type of mercy that actually brings two things together in a way such that the principles of ربوبيه can be applied to that thing right and this is why the womb of a mother is called a رحم because it brings the baby the fetus and the mother together so the mother can nurture it so that she can shower her love over this fetus so that she can help sustain the fetus and then make it grow so the word رحمه is so powerful that you know our general understanding of these words like mercy you know they fall short in really capturing its essence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 3, NULL, 'So now in this next verse, اللهُ سُبْحَانَهُ وَتَعَالَى, He highlights His رَحْمَة by dedicating an entire verse just to mention the quality of His رُبُوبِيَّة. So what according to Him is the essence or the defining attribute of His رُبُوبِيَّة? It is His رَحْمَة. It is His رَحْمٰن, His mercy, His love, His care, His concern that manifests through His abundance in His رَحْمَانِيَّة and His consistency through His رَحِيمِيَّة. And this is why when we look around us, when we study this أَلَمْ, we find this one thread of رَحْمَة flowing through the entire fabric of His آلم. It is this glue that lovingly holds this آلم together. It''s that magical magnetic force that just naturally pulls us towards اللهُ سُبْحَانَهُ وَتَعَالَى and it keeps us connected with our Master. And so just to put this concept in visual terms, you can imagine رَحْمَة as this gravitational field, this force of love that pulls us towards Him. And what we experience from that pull is our حَمْدٌ, our ultimate praise and our absolute gratitude that is owed to this magnificent, this abundantly and consistently merciful رَبٌّ of this الْعَالَمِينَ, the الرَّحْمَٰن and the الرَّحِيمِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'so now in this next verse الله سبحانه وتعالي he highlights his رحمه by dedicating an entire verse just to mention the quality of his ربوبيه so what according to him is the essence or the defining attribute of his ربوبيه it is his رحمه it is his رحمن his mercy his love his care his concern that manifests through his abundance in his رحمانيه and his consistency through his رحيميه and this is why when we look around us when we study this الم we find this one thread of رحمه flowing through the entire fabric of his الم it is this glue that lovingly holds this الم together its that magical magnetic force that just naturally pulls us towards الله سبحانه وتعالي and it keeps us connected with our master and so just to put this concept in visual terms you can imagine رحمه as this gravitational field this force of love that pulls us towards him and what we experience from that pull is our حمد our ultimate praise and our absolute gratitude that is owed to this magnificent this abundantly and consistently merciful رب of this العالمين the الرحمن and the الرحيم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 4, NULL, 'Now, if you look at the gratitude aspect or the gratitude component of الْحَمْدُ, if we just focus on this one aspect of شُكْر, what is the reality of شُكْر? What is the manifestation of sincere gratitude? It''s تَقْوَى, right? It is this constant awareness of اللَّهُs presence. It is the constant recognition and awareness of His blessings. And this is a very high station. This type of شُكْر, it holds a very lofty مَقَام, and not everyone is truly capable of achieving these high ranks of شُكْر. And this is why اللَّهُ says in the Quran, وَقَلِيلٌۭ مِّنْ عِبَادِىَ ٱلشَّكُورُ. Very, very few of My servants are truly شَكُورٌ. The شَكُور is very different from the شَاكِرٌ. The شَاكِرٌ, the grateful, is the one who is grateful for اللَّهُs blessings. But the شَكُور, he''s the one who''s grateful for calamities and tribulations also, not just blessings. He actually feels gratitude when horrible things happen to him.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'now if you look at the gratitude aspect or the gratitude component of الحمد if we just focus on this one aspect of شكر what is the reality of شكر what is the manifestation of sincere gratitude its تقوي right it is this constant awareness of اللهs presence it is the constant recognition and awareness of his blessings and this is a very high station this type of شكر it holds a very lofty مقام and not everyone is truly capable of achieving these high ranks of شكر and this is why الله says in the quran وقليل من عبادي الشكور very very few of my servants are truly شكور the شكور is very different from the شاكر the شاكر the grateful is the one who is grateful for اللهs blessings but the شكور hes the one whos grateful for calamities and tribulations also not just blessings he actually feels gratitude when horrible things happen to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 5, NULL, 'Because most people at best, they''ll become patient or resigned, but the شَكُور, they actually say الْحَمْدُ لِلَّهِ as they are experiencing these calamities, because the شَكُور, they know that اللَّهُ only does good for the believers, right? There''s a حَدِيثٌ in which رَسُولُ اللهِ said, عَجَبًا لِأَمْرِ الْمُؤْمِنِ فَإِنَّهُ أَمْرُهُ لَهُ كُلُّهُ خَيْرٌ. How wondrous is the affair of the believer! His affair, all of it is good. So if you''re a true believer, then it''s all good. And that''s why if you really do believe, you enter into the state of constant gratitude, even for the tribulations. It''s always الْحَمْدُ لِلَّهِ. And always a good thing to remember is what Ibn Abbas رَضِيَ اللهُ said, that no matter how bad it is, it could always be worse. And there are people like that. There are even in the non-Muslim community, you''ll find people like that, you know, they always look at the good side. Well, it could be worse. Think about this, you know, count your blessings. So there are people that just naturally, instinctively have this understanding. Now, in this verse, اللَّهُ says He is a رَبٌّ that is الرَّحْمَٰن and الرَّحِيمِ. How does His رَحْمَة manifest in our lives? Today I just want to focus on how His love presents itself in our lives. How does اللَّهُ demonstrate His love for us? Through His blessings, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'because most people at best theyll become patient or resigned but the شكور they actually say الحمد لله as they are experiencing these calamities because the شكور they know that الله only does good for the believers right theres a حديث in which رسول الله said عجبا لامر المومن فانه امره له كله خير how wondrous is the affair of the believer his affair all of it is good so if youre a true believer then its all good and thats why if you really do believe you enter into the state of constant gratitude even for the tribulations its always الحمد لله and always a good thing to remember is what ibn abbas رضي الله said that no matter how bad it is it could always be worse and there are people like that there are even in the non muslim community youll find people like that you know they always look at the good side well it could be worse think about this you know count your blessings so there are people that just naturally instinctively have this understanding now in this verse الله says he is a رب that is الرحمن and الرحيم how does his رحمه manifest in our lives today i just want to focus on how his love presents itself in our lives how does الله demonstrate his love for us through his blessings right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 6, NULL, 'Through His gifts, His نِرْمَا. When I as a parent, when I want to demonstrate my love for my children, how do I do that? By bestowing gifts upon them, right? Valuable, desirable, beneficial gifts. Gifts that the child understands that he or she could not attain by their own efforts. Now think about the blessings, the gifts that اللَّهُ has bestowed upon all of us. Incredible gifts, infinite gifts. If you attempt to enumerate the blessings of اللَّهُ, you will never be able to enumerate them. Gifts that are not only impossible to count, their value is just impossible to measure. Just look at one single نِعَمَ. Look at the نِعَمَ, for instance, of the eye. That is just one نِعَمَ, sight.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'through his gifts his نرما when i as a parent when i want to demonstrate my love for my children how do i do that by bestowing gifts upon them right valuable desirable beneficial gifts gifts that the child understands that he or she could not attain by their own efforts now think about the blessings the gifts that الله has bestowed upon all of us incredible gifts infinite gifts if you attempt to enumerate the blessings of الله you will never be able to enumerate them gifts that are not only impossible to count their value is just impossible to measure just look at one single نعم look at the نعم for instance of the eye that is just one نعم sight', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 7, NULL, 'First of all, think about this, blinking. Just think about blinking. You don''t even notice that you blink. Now, if you didn''t blink, have you ever seen pictures of Aristotle Onassis? You know, when he got really old, the richest man, one of the richest men in the world, he owned his own private fleet of ships, he had to use band-aids to hold up his eyelids because he lost the function of the muscle that returns the eyelid and his eyelids just dropped all the time. So he used band-aids to hold them up, but then he had to put drops in his eyes all the time. Because if your eyelids don''t close, they get dry and you start getting dust in them. Because one of the things that blinking does is it brings the dust back down. You see, they''re like windshield wipers, right? They bring the dust down and then what happens is that the dust, it just moves to the side and accumulates in the corners of the eye. So when you wipe your eyes, you''ll get some of that dust out of the eye. And you don''t even think about that. That''s just one part of the eye.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'first of all think about this blinking just think about blinking you dont even notice that you blink now if you didnt blink have you ever seen pictures of aristotle onassis you know when he got really old the richest man one of the richest men in the world he owned his own private fleet of ships he had to use band aids to hold up his eyelids because he lost the function of the muscle that returns the eyelid and his eyelids just dropped all the time so he used band aids to hold them up but then he had to put drops in his eyes all the time because if your eyelids dont close they get dry and you start getting dust in them because one of the things that blinking does is it brings the dust back down you see theyre like windshield wipers right they bring the dust down and then what happens is that the dust it just moves to the side and accumulates in the corners of the eye so when you wipe your eyes youll get some of that dust out of the eye and you dont even think about that thats just one part of the eye', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 8, NULL, 'But then if you think about the intricate network of these nerves behind the eye and the myelination of that sheath, the fact that there''s this constant synaptic responses, the fact that there''s neural transmission, because that breaks down for some people, right? They go blind, they lose the function of the sight. I mean, we don''t think about all of this. Think about the electric work that goes in the function of an eye. Colors, just think about colors. اللَّهُ could have made everything black and white, right? Look at all the subtle colors that He put in this world that we can experience. Our eyes can experience an incredible variety of colors. I mean, that''s نِرْمَا. Then look how, you know, how some of these colors, they just give you pleasure in just seeing them. You don''t even think about it.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'but then if you think about the intricate network of these nerves behind the eye and the myelination of that sheath the fact that theres this constant synaptic responses the fact that theres neural transmission because that breaks down for some people right they go blind they lose the function of the sight i mean we dont think about all of this think about the electric work that goes in the function of an eye colors just think about colors الله could have made everything black and white right look at all the subtle colors that he put in this world that we can experience our eyes can experience an incredible variety of colors i mean thats نرما then look how you know how some of these colors they just give you pleasure in just seeing them you dont even think about it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 9, NULL, 'Today we know that there''s vibration. If you look at color, there are seven colors. All colors go down to seven primary colors. I think in color theory they go down to three, but basically everybody agrees that there are seven colors in a spectrum. If you look at visible light, each one of these colors has an effect upon the soul, right? Red has a certain vibrational resonance. It''s a lower resonance than violet. Violet is at the high spectrum, red is at the low spectrum. Red, when you see the color red, it stimulates you. You don''t even know that. They know that now in color theory because, you know, all the study that''s been done on people, that if you put them in red rooms, it has a different effect on them than if you put them in blue rooms. It''ll actually change their moods because these colors have a resonance.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'today we know that theres vibration if you look at color there are seven colors all colors go down to seven primary colors i think in color theory they go down to three but basically everybody agrees that there are seven colors in a spectrum if you look at visible light each one of these colors has an effect upon the soul right red has a certain vibrational resonance its a lower resonance than violet violet is at the high spectrum red is at the low spectrum red when you see the color red it stimulates you you dont even know that they know that now in color theory because you know all the study thats been done on people that if you put them in red rooms it has a different effect on them than if you put them in blue rooms itll actually change their moods because these colors have a resonance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 10, NULL, 'there''s an electromagnetic radiation and it''s all having a psychological effect on us and we don''t even know it. Now, the thing about the world: if you go out and look at green, green will make you feel good, right? That''s why people love to look at grass, they love to visit these gardens, they love to look at trees. You know, it has a يُنَعِّش, as the Arabs would say. Yeah, it''s called رَابِعَةٌ, spring. This is why we say in our prayers that اللَّهُ make the recital of Quran the spring of my heart: اللَّهُمَّ اجْعَلِ الْقُرْآنَ رَبِيعَ قَلْبِي. What does that mean? Because رَابِعَةٌ is that thing which brings your heart back to life, because spring brings your whole being back to life. People start feeling good. People get this thing, they call it SAD, Seasonal Affective Disorder, SAD. There are people who get depressed in the wintertime. It''s an actual psychological state. But then spring comes around and they forget how depressed they were in the winter. They start feeling wonderful. Why are they feeling wonderful now? Green. You see, the color starts changing.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'theres an electromagnetic radiation and its all having a psychological effect on us and we dont even know it now the thing about the world if you go out and look at green green will make you feel good right thats why people love to look at grass they love to visit these gardens they love to look at trees you know it has a ينعش as the arabs would say yeah its called رابعه spring this is why we say in our prayers that الله make the recital of quran the spring of my heart اللهم اجعل القران ربيع قلبي what does that mean because رابعه is that thing which brings your heart back to life because spring brings your whole being back to life people start feeling good people get this thing they call it sad seasonal affective disorder sad there are people who get depressed in the wintertime its an actual psychological state but then spring comes around and they forget how depressed they were in the winter they start feeling wonderful why are they feeling wonderful now green you see the color starts changing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 11, NULL, 'There''s photosynthesis that''s happening. All this chlorophyll is starting to come back to life. Flowers start blooming again. Flowers. Look at the flowers. I mean, what is that? A flower? Why do people like smelling a flower? That''s another name of scent. Just the sight of a beautiful flower. Just the sight, right? Beauty.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'theres photosynthesis thats happening all this chlorophyll is starting to come back to life flowers start blooming again flowers look at the flowers i mean what is that a flower why do people like smelling a flower thats another name of scent just the sight of a beautiful flower just the sight right beauty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 12, NULL, 'When the eye looks at something beautiful, why do we all respond the same way? When you see something beautiful, and most people, we all share a common taste in beauty, when we see something beautiful, we''re attracted to it, right? There''s an attraction. Why? It''s because beauty is an attribute of God, and what you''re seeing in the الٓمٓ is a reflection of that divine attribute of your رَبٌّ. So you''re essentially attracted to the divine, but you think you''re being attracted to the flower. No, it''s the beauty of the divine manifesting through the flower. That is real attraction. Real attraction is not in this ephemeral beauty that fades away. It''s the manifestation of the divine in creation that''s the real attraction. But we don''t realize that. So there are all these things about the eye that we just don''t think about. I mean, look at the eyelashes, the eyebrows. They''re serving a purpose, right? Eyelashes serve a purpose.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'when the eye looks at something beautiful why do we all respond the same way when you see something beautiful and most people we all share a common taste in beauty when we see something beautiful were attracted to it right theres an attraction why its because beauty is an attribute of god and what youre seeing in the الم is a reflection of that divine attribute of your رب so youre essentially attracted to the divine but you think youre being attracted to the flower no its the beauty of the divine manifesting through the flower that is real attraction real attraction is not in this ephemeral beauty that fades away its the manifestation of the divine in creation thats the real attraction but we dont realize that so there are all these things about the eye that we just dont think about i mean look at the eyelashes the eyebrows theyre serving a purpose right eyelashes serve a purpose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 13, NULL, 'I mean, when anything comes near our eye, we instinctively close our eyelids to protect the eye. I mean, that''s just amazing. So there are all these things about just the eye that if we really start thinking about it, I mean, look at the abundance in just the eye, the abundance in the نِعْمَةٌ of the eye. Just look at the رَحْمَانِيَّة of this رَبِّ, with one single gift. And that''s based on what we just know so far. There must be so many blessings that we don''t even know about yet. سُبْحَانَ اللَّهِ. What about light? Right? The external factor that makes sight possible, that makes the eye useful, that makes the eye functional, which in turn makes people happy or depressed.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'i mean when anything comes near our eye we instinctively close our eyelids to protect the eye i mean thats just amazing so there are all these things about just the eye that if we really start thinking about it i mean look at the abundance in just the eye the abundance in the نعمه of the eye just look at the رحمانيه of this رب with one single gift and thats based on what we just know so far there must be so many blessings that we dont even know about yet سبحان الله what about light right the external factor that makes sight possible that makes the eye useful that makes the eye functional which in turn makes people happy or depressed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 14, NULL, 'Why do people get depressed? You know, one of the reasons they think is because the serotonin level, as they drop, which is the key hormone in making us feel happy. That''s what they call serotonin. They call it the happy hormone, right? And one of its factors of release is based on light. So you''re taking in light during the day and you''re feeling good and happy and cheerful and you don''t even think about it. There are all these hormones that are related to melatonin. That''s based on light, right? Melatonin is what makes us sleepy. That''s why people that are constantly in artificial light, they have difficulty sleeping. But the eye is what''s doing all of that, right? The eye is dictating.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'why do people get depressed you know one of the reasons they think is because the serotonin level as they drop which is the key hormone in making us feel happy thats what they call serotonin they call it the happy hormone right and one of its factors of release is based on light so youre taking in light during the day and youre feeling good and happy and cheerful and you dont even think about it there are all these hormones that are related to melatonin thats based on light right melatonin is what makes us sleepy thats why people that are constantly in artificial light they have difficulty sleeping but the eye is whats doing all of that right the eye is dictating', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 15, NULL, 'That''s why we get tired. It''s all based on the eye. So even our sleep patterns are being affected by the human eye. And we don''t even realize that. When we feel awake, when we feel drowsy, it''s all the result of the eye. And this is just the eye alone. We cannot even enumerate all the blessings of the eye, which is one نِعْمَةٌ. This is just نِعْمَةُ الْعَيْنِ that we''re talking about here. We cannot even enumerate the blessings of this one organ. There are untold, infinite blessings in it. And it''s just one نِرْمَا. اللهُ أَكْبَرُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'thats why we get tired its all based on the eye so even our sleep patterns are being affected by the human eye and we dont even realize that when we feel awake when we feel drowsy its all the result of the eye and this is just the eye alone we cannot even enumerate all the blessings of the eye which is one نعمه this is just نعمه العين that were talking about here we cannot even enumerate the blessings of this one organ there are untold infinite blessings in it and its just one نرما الله اكبر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 16, NULL, 'So the شَكُور is the one who is constantly experiencing the state of gratitude, its presence and the lack of it. But this comes from this absolute certainty and this is a مَقَام, this is a station that is related to رِضًا, which is complete contentment with اللهُ سُبْحَانَهُ وَتَعَالَى. It''s a state of مَحَبَّة. It''s a state of this intense love because once you fall in love, you just cannot see anything else. I mean, there''s this incredible beauty of love. You know, when you''re in love, you can''t see faults, right? Even when they do exist, you just can''t see them. If you love Laila and anybody tells you, you know, Laila did this or she did that, you get angry. Why? What? Laila would never do that. No, no, no.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'so the شكور is the one who is constantly experiencing the state of gratitude its presence and the lack of it but this comes from this absolute certainty and this is a مقام this is a station that is related to رضا which is complete contentment with الله سبحانه وتعالي its a state of محبه its a state of this intense love because once you fall in love you just cannot see anything else i mean theres this incredible beauty of love you know when youre in love you cant see faults right even when they do exist you just cant see them if you love laila and anybody tells you you know laila did this or she did that you get angry why what laila would never do that no no no', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 17, NULL, 'I saw Laila did this. You''re lying. You''re a liar. Laila would never do that. Why? Because he''s in love with Laila. No matter what you say about Laila, he''s not going to believe you. You know, that''s real love. People don''t even know that type of love anymore. So if you''re in love with اللَّهُ, He just cannot do anything that would harm you or hurt you. Impossible, nothing, because you''ll say it''s me. You see, I did it to myself. اللَّهُ didn''t do that. اللَّهُ would never do that. I did that to myself, or that اللَّهُ is doing it because, you know, like the father that punishes the child. You see, I mean, you see a father punishing the child. The father loves the child. Why is he punishing it? Because he knows that in that punishment is benefit for the child. He''s disciplining the child, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'i saw laila did this youre lying youre a liar laila would never do that why because hes in love with laila no matter what you say about laila hes not going to believe you you know thats real love people dont even know that type of love anymore so if youre in love with الله he just cannot do anything that would harm you or hurt you impossible nothing because youll say its me you see i did it to myself الله didnt do that الله would never do that i did that to myself or that الله is doing it because you know like the father that punishes the child you see i mean you see a father punishing the child the father loves the child why is he punishing it because he knows that in that punishment is benefit for the child hes disciplining the child right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 18, NULL, 'He''s bringing the child back on the right track. Through that punishment, he''s reminding the child of something worse. You know, if I see my son putting his hand in the fire, I''ll slap his hand. Why am I doing that? Because I want him to taste a light pain in order to avoid a much greater pain, you see? Because I know that the pain of this slap is nothing compared to the pain of the flame. And when اللهُ سُبْحَانَهُ وَتَعَالَى gives us a tribulation, those are nothing compared to Hellfire. Nothing. So if اللَّهُ is purifying us to prevent us from doing something that He doesn''t want us to do, then the شَكُور realizes that, that this tribulation is the love of His Creator for him.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'hes bringing the child back on the right track through that punishment hes reminding the child of something worse you know if i see my son putting his hand in the fire ill slap his hand why am i doing that because i want him to taste a light pain in order to avoid a much greater pain you see because i know that the pain of this slap is nothing compared to the pain of the flame and when الله سبحانه وتعالي gives us a tribulation those are nothing compared to hellfire nothing so if الله is purifying us to prevent us from doing something that he doesnt want us to do then the شكور realizes that that this tribulation is the love of his creator for him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 19, NULL, 'You know, the Prophet صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ, he once saw a mother nursing her child. You know, and this is a man, as they say, you know, the man of اللَّهُ takes discernment from everything, right? He takes عِبْرَة, a discernment, a lesson from everything. His glance is discernment and his speech is wisdom. So, there''s always a reason why he speaks. So, the Prophet صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ, he once saw a woman nursing her child, and he said to his صَحَابَة, Do you think that this woman would throw her child into the Hellfire? And they said, لَا وَاللَّهِ يَا رَسُولَ اللَّهِ. She would never do that. He said, اللَّهُ has more mercy for His servants than this woman has for her child. اللَّهُ أَرْحَمُ بِعِبَادِهِ مِنْ هَذِهِ الْأُمِّ لِوَلَدِهَا. اللَّهُ has more mercy for His servants than this woman has for her child.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'you know the prophet صلي الله عليه وسلم he once saw a mother nursing her child you know and this is a man as they say you know the man of الله takes discernment from everything right he takes عبره a discernment a lesson from everything his glance is discernment and his speech is wisdom so theres always a reason why he speaks so the prophet صلي الله عليه وسلم he once saw a woman nursing her child and he said to his صحابه do you think that this woman would throw her child into the hellfire and they said لا والله يا رسول الله she would never do that he said الله has more mercy for his servants than this woman has for her child الله ارحم بعباده من هذه الام لولدها الله has more mercy for his servants than this woman has for her child', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 20, NULL, 'اللهُ سُبْحَانَهُ وَتَعَالَى, you know, in سُورَةُ الْإِسْرَاءِ, when He talked about His Prophet نُوحٌ عَلَيْهِ السَّلَامُ, He said, إِنَّهُۥ كَانَ عَبْدًۭا شَكُورًۭا. Indeed, he was a grateful slave, because of the amount of دَعْوَة that he did. You know, people today they get fed up after a week of دَعْوَة, they say, you know, they give advice two times, three times and that''s it. Oh, you know, I give up, these people never listen. I mean, this is 950 years of doing what اللَّهُ asked him to do. That''s a شَكُور. And one of the things mentioned in السِّيرَةُ is that نُوحٌ عَلَيْهِ السَّلَامُ, he never once went to relieve himself, except that he came back saying, الْحَمْدُ لِلَّهِ الَّذِي أَذْهَبَ عَنِّي الْأَذَى. Praise and gratitude be to the one who removed this harm from me. Even just having شُكْر for something like relieving himself.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'الله سبحانه وتعالي you know in سوره الاسراء when he talked about his prophet نوح عليه السلام he said انه كان عبدا شكورا indeed he was a grateful slave because of the amount of دعوه that he did you know people today they get fed up after a week of دعوه they say you know they give advice two times three times and thats it oh you know i give up these people never listen i mean this is 950 years of doing what الله asked him to do thats a شكور and one of the things mentioned in السيره is that نوح عليه السلام he never once went to relieve himself except that he came back saying الحمد لله الذي اذهب عني الاذي praise and gratitude be to the one who removed this harm from me even just having شكر for something like relieving himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 21, NULL, 'Because what a blessing that is, right? I mean, think about — you know, I don''t know if you''ve ever read these stories of Bahlol. As kids, we used to read them. And there''s this one story of Bahlol in which he went to visit Harun Rashid, the palace of Harun Rashid, who was a king at that time. And he asked Harun Rashid, you know, would you like anything? And Harun said, bring me back a glass of water. So they brought him water. As he was about to drink it, Bahlol asked, if you will refuse this water, right, you were dying of thirst, but you were refused this water, what would you give for this water? And he said, I would give half of my kingdom for it if I couldn''t have it. And then Bahlol said, if you drank this water and then you couldn''t release it, what would you give to release it? He said, I''d give the rest of my kingdom. So Bahlol asked, then what is the worth of your kingdom that is not worth a cup of water or the release of it as urine? In other words, what do you really possess? You know, if it, all this kingdom that you possess, it doesn''t even equal a cup of water or the release of it.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'because what a blessing that is right i mean think about you know i dont know if youve ever read these stories of bahlol as kids we used to read them and theres this one story of bahlol in which he went to visit harun rashid the palace of harun rashid who was a king at that time and he asked harun rashid you know would you like anything and harun said bring me back a glass of water so they brought him water as he was about to drink it bahlol asked if you will refuse this water right you were dying of thirst but you were refused this water what would you give for this water and he said i would give half of my kingdom for it if i couldnt have it and then bahlol said if you drank this water and then you couldnt release it what would you give to release it he said id give the rest of my kingdom so bahlol asked then what is the worth of your kingdom that is not worth a cup of water or the release of it as urine in other words what do you really possess you know if it all this kingdom that you possess it doesnt even equal a cup of water or the release of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 22, NULL, 'So think of that, the blessing of just eating, drinking, and digesting it. I mean, you don''t have to tell your hydrochloric acid to be released. You don''t have to push any buttons here, right? You eat something and if it''s protein, then it just breaks down into amino acids and your body then reassembles them as muscle tissue. If it''s fat, it breaks down into fatty acids, then your body reassembles them. If it''s carbs, it breaks them down, takes them to the brain, produces energy, right? If you have extra, then insulin is released, takes it to the liver, stores it as glycogen, so that when later on you''re out of energy, the liver can release that glycogen, break it down for you, and produce energy. You don''t have to do any of this. You don''t have to tell the body to do any of this, and yet it''s all doing that for us. اللهُ أَكْبَرُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'so think of that the blessing of just eating drinking and digesting it i mean you dont have to tell your hydrochloric acid to be released you dont have to push any buttons here right you eat something and if its protein then it just breaks down into amino acids and your body then reassembles them as muscle tissue if its fat it breaks down into fatty acids then your body reassembles them if its carbs it breaks them down takes them to the brain produces energy right if you have extra then insulin is released takes it to the liver stores it as glycogen so that when later on youre out of energy the liver can release that glycogen break it down for you and produce energy you dont have to do any of this you dont have to tell the body to do any of this and yet its all doing that for us الله اكبر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 23, NULL, 'I mean, that''s what — how to be grateful for the blessings of اللَّهُ. Islam is all about being grateful to اللَّهُ. That''s what Islam is. We just, just the simplest of things. Right now, we''re all at 98.6 degrees.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'i mean thats what how to be grateful for the blessings of الله islam is all about being grateful to الله thats what islam is we just just the simplest of things right now were all at 98 6 degrees', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 24, NULL, 'Who do you think is maintaining our bodies at 98.6 right now? Seriously, who''s maintaining that? You know, right now, I could have a fever and I could be shivering. If I was sick right now, right? But if I was sick right now, even though it''s a moderate temperature in the room, I could be shivering, I could be feeling cold, and it wouldn''t even be cold. If I had a fever, I would be boiling up right now in a moderate climate. You''d all be fine, but if I had a fever, I would, you know, want to take off all my clothes and I''d be all hot and sweaty. Think about that. اللَّهُ is keeping us all at 98.6. Even if it''s 100 degrees outside, our bodies are releasing fluid as sweat in order to maintain this 98.6 on average. Even if it''s 100 degrees outside, why don''t we boil up to 100 degrees? What created that inner thermostat that keeps us all at this balance? If it''s cold out, why don''t we all drop down and freeze? Because we would if, you know, if we go out in ice cold temperatures long enough, we''ll freeze. But for a period of time, we won''t.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'who do you think is maintaining our bodies at 98 6 right now seriously whos maintaining that you know right now i could have a fever and i could be shivering if i was sick right now right but if i was sick right now even though its a moderate temperature in the room i could be shivering i could be feeling cold and it wouldnt even be cold if i had a fever i would be boiling up right now in a moderate climate youd all be fine but if i had a fever i would you know want to take off all my clothes and id be all hot and sweaty think about that الله is keeping us all at 98 6 even if its 100 degrees outside our bodies are releasing fluid as sweat in order to maintain this 98 6 on average even if its 100 degrees outside why dont we boil up to 100 degrees what created that inner thermostat that keeps us all at this balance if its cold out why dont we all drop down and freeze because we would if you know if we go out in ice cold temperatures long enough well freeze but for a period of time we wont', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 25, NULL, 'We''ll all stay at 98.6. Why? اللهُ أَكْبَرُ. We go swimming in cold water and our temperature maintains itself. This is all from اللهُ سُبْحَانَهُ وَتَعَالَى. All manifestation of the رَحْمَانِيَّة and the رَحِيمِيَة of our رَبِّ.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'well all stay at 98 6 why الله اكبر we go swimming in cold water and our temperature maintains itself this is all from الله سبحانه وتعالي all manifestation of the رحمانيه and the رحيميه of our رب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 26, NULL, 'And the شَكُور is constantly aware of the abundance of these blessings of الرَّحْمَٰن, but then they also look at those that are less fortunate than them in their worldly affairs. They use that as a resource to draw even more gratitude, right? There''s a حَدِيثُ سُورَةِ الْفَاتِحَةِ of رَسُولُ اللهِ in which he said about this دُنْيَا that you should always look at people who are less fortunate than you are in دُنْيَا, because you''ll always feel grateful. There''s always people who are less fortunate than you are today. I guarantee you, no matter how miserable you think you are, you''ll always find people in much more misery than you are right now. So you say الْحَمْدُ لِلَّهِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'and the شكور is constantly aware of the abundance of these blessings of الرحمن but then they also look at those that are less fortunate than them in their worldly affairs they use that as a resource to draw even more gratitude right theres a حديث سوره الفاتحه of رسول الله in which he said about this دنيا that you should always look at people who are less fortunate than you are in دنيا because youll always feel grateful theres always people who are less fortunate than you are today i guarantee you no matter how miserable you think you are youll always find people in much more misery than you are right now so you say الحمد لله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 27, NULL, 'I mean, if you don''t have a lot of money, you know, in this country, the United States, or even most of us living in Pakistan and India, we''re considered well off, we''re considered, you know, decently rich. In biblical times, to put a jar of honey on your table was considered a sign of immense wealth. Think about that. A jar of honey on your table was a sign of great wealth. Really. The majority of people living in America today would be considered royalty in previous times. The houses that we live in, they would be considered palaces.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'i mean if you dont have a lot of money you know in this country the united states or even most of us living in pakistan and india were considered well off were considered you know decently rich in biblical times to put a jar of honey on your table was considered a sign of immense wealth think about that a jar of honey on your table was a sign of great wealth really the majority of people living in america today would be considered royalty in previous times the houses that we live in they would be considered palaces', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 28, NULL, 'The facilities that we have, this idea of having running water, just running water. The fact that you can take a hot shower just by turning a knob, people don''t even think about this. There are places today in this world, وَاللهِ, there are women who have the sole job of bringing water every day. It takes them about two hours to go get the water. It takes about an hour to fill up, you know, these قِرْبَة, what they call. Loaded on the back of donkeys in these villages and then two hours to come back home. Five hours, five hours every day just to bring drinking water to their village, and that''s their entire life. Can you imagine what they must feel when they drink water? What do you think they would say after all that, five hours of hard work, when they take that first sip? What do you think they say? ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'the facilities that we have this idea of having running water just running water the fact that you can take a hot shower just by turning a knob people dont even think about this there are places today in this world والله there are women who have the sole job of bringing water every day it takes them about two hours to go get the water it takes about an hour to fill up you know these قربه what they call loaded on the back of donkeys in these villages and then two hours to come back home five hours five hours every day just to bring drinking water to their village and thats their entire life can you imagine what they must feel when they drink water what do you think they would say after all that five hours of hard work when they take that first sip what do you think they say الحمد لله رب العلمين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 29, NULL, 'That water, it''s brown. Most of them have kidney problems. Most of them have urinary problems because of the sediment in that water. People have forgotten this. We could have been born in that village. You and I could have been born in that village, drinking that brown water, having those kidney problems. I mean, we never think about these things, do we? Just think about the blessings, the نِعَمَ of this house that we live in. Think about the نِعَمَ of water, the نِعَمَ of food on our table, the نِعَمَ of clothes to cover up our nakedness, to keep us warm. The نِعْمَةٌ of a bed. The نِعْمَةٌ of just being healthy. I mean نِعْمَةُ الْعَافِيَةِ, that you got up in the morning and you weren''t sick.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'that water its brown most of them have kidney problems most of them have urinary problems because of the sediment in that water people have forgotten this we could have been born in that village you and i could have been born in that village drinking that brown water having those kidney problems i mean we never think about these things do we just think about the blessings the نعم of this house that we live in think about the نعم of water the نعم of food on our table the نعم of clothes to cover up our nakedness to keep us warm the نعمه of a bed the نعمه of just being healthy i mean نعمه العافيه that you got up in the morning and you werent sick', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 30, NULL, 'Think of how many people got up this morning and they had to empty out a bag that had their urine in it. A bag that they have to change every hour. Think of how many people that got up this morning that couldn''t go to the toilet or they bled blood. Think how many people there are with asthma. They couldn''t breathe this morning. They woke up gasping for air. Really? Think about how many people spend their last night coughing. They couldn''t sleep because of this cough. Really? That''s why, I mean شُكْر, showing gratitude to اللهُ سُبْحَانَهُ وَتَعَالَى, you really have to wonder about our lives, right? Just the blessings that the الرَّحْمَٰن has bestowed upon us and our complaints, my God! Our constant never-ending complaints against God.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'think of how many people got up this morning and they had to empty out a bag that had their urine in it a bag that they have to change every hour think of how many people that got up this morning that couldnt go to the toilet or they bled blood think how many people there are with asthma they couldnt breathe this morning they woke up gasping for air really think about how many people spend their last night coughing they couldnt sleep because of this cough really thats why i mean شكر showing gratitude to الله سبحانه وتعالي you really have to wonder about our lives right just the blessings that the الرحمن has bestowed upon us and our complaints my god our constant never ending complaints against god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 31, NULL, 'What did I do to deserve this? What have I done to this? You exist. That''s enough as a crime, really. If you really think about this, that''s enough as a crime, to think that you exist beside اللَّهُ. To think that we share existence with اللَّهُ. We are criminals. Just for having that thought, because لَآ إِلَهَ إِلَّا ٱللَّهُ. There is nothing worthy of إِلَهِيَّة except اللَّهُ. And yet here we are, right, walking around, just thinking, you know, these little contingent creatures living on this insignificant planet, in this insignificant galaxy, that are totally dependent for every breath, at every instant, on اللهُ سُبْحَانَهُ وَتَعَالَى, and we think we are independent. We think we are self-sufficient.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'what did i do to deserve this what have i done to this you exist thats enough as a crime really if you really think about this thats enough as a crime to think that you exist beside الله to think that we share existence with الله we are criminals just for having that thought because لا اله الا الله there is nothing worthy of الهيه except الله and yet here we are right walking around just thinking you know these little contingent creatures living on this insignificant planet in this insignificant galaxy that are totally dependent for every breath at every instant on الله سبحانه وتعالي and we think we are independent we think we are self sufficient', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 32, NULL, 'We think we are in control. If I''m in such a state of heedlessness with اللهُ سُبْحَانَهُ وَتَعَالَى, I''m a criminal. If I forget اللَّهُ for one instant, I am a criminal and I stand condemned. And then anything that happens to me, I deserve it. Because I''ve forgotten who اللَّهُ is and who I am in relation to that. Oh man! What has deluded you about your master? What has deluded you about your Lord? Why are you in the state of غُرُور? Total delusion. Thinking that you don''t need me at every instant of your life. Just to draw your next breath. Just to have your next heartbeat.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'we think we are in control if im in such a state of heedlessness with الله سبحانه وتعالي im a criminal if i forget الله for one instant i am a criminal and i stand condemned and then anything that happens to me i deserve it because ive forgotten who الله is and who i am in relation to that oh man what has deluded you about your master what has deluded you about your lord why are you in the state of غرور total delusion thinking that you dont need me at every instant of your life just to draw your next breath just to have your next heartbeat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 33, NULL, 'I mean heartbeat. What is a heartbeat? An electric impulse. Who''s activating it? It''s اللهُ سُبْحَانَهُ وَتَعَالَى. You think it''s your brain. It''s not your brain. Your brain is not doing that. They don''t even know what''s doing it. I mean, you can cut all your nerves to the brain and the heart will still beat, right? What makes the heart beat? And yet, here we are, these insignificant creatures complaining about اللَّهُ, judging Him for His faults.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'i mean heartbeat what is a heartbeat an electric impulse whos activating it its الله سبحانه وتعالي you think its your brain its not your brain your brain is not doing that they dont even know whats doing it i mean you can cut all your nerves to the brain and the heart will still beat right what makes the heart beat and yet here we are these insignificant creatures complaining about الله judging him for his faults', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 34, NULL, 'That''s a crime. Or we sit on our high horses, you know, right next to Him judging others. Our عُلَمَاء, I mean just looking down upon others based on their knowledge that اللَّهُ has bestowed them with. That''s not why اللَّهُ gave you that knowledge, to look down on others. He created us all as brothers to embrace each other. See, there''s two ways to embracing, right? There''s the embrace of an equal. And then there is the embrace of the superior. Did you ever think about that? What''s the embrace of an equal? You embrace somebody who''s the same as you. If I embrace you, you''re my brother.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'thats a crime or we sit on our high horses you know right next to him judging others our علماء i mean just looking down upon others based on their knowledge that الله has bestowed them with thats not why الله gave you that knowledge to look down on others he created us all as brothers to embrace each other see theres two ways to embracing right theres the embrace of an equal and then there is the embrace of the superior did you ever think about that whats the embrace of an equal you embrace somebody whos the same as you if i embrace you youre my brother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 35, NULL, 'We have an equal embrace. We''re the same height. I put my arms around you. You put your arms around me and we have an embrace. That''s the embrace of an equal. What''s the embrace of a superior to an inferior? How do you embrace a child? The child can put his arms around you. You pick them up, right? You lift them and you embrace them and you hold them. See, that''s Islam. That massage, that temperament, the temperament of Islam is to take all these other sects and religions and those who are inferior in knowledge and then just embrace them.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'we have an equal embrace were the same height i put my arms around you you put your arms around me and we have an embrace thats the embrace of an equal whats the embrace of a superior to an inferior how do you embrace a child the child can put his arms around you you pick them up right you lift them and you embrace them and you hold them see thats islam that massage that temperament the temperament of islam is to take all these other sects and religions and those who are inferior in knowledge and then just embrace them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 36, NULL, 'That''s the embrace of اللَّهُ. He is so great that He will even allow somebody that denies Him to exist. I mean, if you want to think about greatness, that is greatness. That is رَحْمَة. He''ll feed them, He''ll nurture them, give them rain, keep their bodies healthy, give them a wife, children that love Him. اللَّهُ does all of that, even though that person denies His very existence. But all that does is show the greatness of اللهُ سُبْحَانَهُ وَتَعَالَى.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'thats the embrace of الله he is so great that he will even allow somebody that denies him to exist i mean if you want to think about greatness that is greatness that is رحمه hell feed them hell nurture them give them rain keep their bodies healthy give them a wife children that love him الله does all of that even though that person denies his very existence but all that does is show the greatness of الله سبحانه وتعالي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 37, NULL, 'You know, there''s a story of Ibrahim عَلَيْهِ سَلَامٌ that one night, it was famous about him that he never ate alone, right, Ibrahim عَلَيْهِ سَلَامٌ? He always found somebody to eat with. But one night he couldn''t find anybody, so he went out looking for someone and then he finally found this man and he brought him home. And this man was a مُشْرِك. So before this man ate his food he blessed it in the name of his idols, and when Ibrahim heard that he said, you know, you can''t eat any of my food, you''re an idol worshiper, get out of here. So the man left. But then اللَّهُ revealed to Ibrahim, He said, Ibrahim, I have been feeding him for 40 years. And I''ve been patient with his idolatry for 40 years. You couldn''t be patient with him for just one meal. And so, Ibrahim, he went and he found that man, he apologized to him, invited him back to his table. And the man asked why? What suddenly changed? And he told him. And this man became a Muslim. That is Islam. You know. This ability to embrace everyone. I mean that''s دَعْوَة.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'you know theres a story of ibrahim عليه سلام that one night it was famous about him that he never ate alone right ibrahim عليه سلام he always found somebody to eat with but one night he couldnt find anybody so he went out looking for someone and then he finally found this man and he brought him home and this man was a مشرك so before this man ate his food he blessed it in the name of his idols and when ibrahim heard that he said you know you cant eat any of my food youre an idol worshiper get out of here so the man left but then الله revealed to ibrahim he said ibrahim i have been feeding him for 40 years and ive been patient with his idolatry for 40 years you couldnt be patient with him for just one meal and so ibrahim he went and he found that man he apologized to him invited him back to his table and the man asked why what suddenly changed and he told him and this man became a muslim that is islam you know this ability to embrace everyone i mean thats دعوه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 38, NULL, 'What is دَعْوَة? In Arabic, even in Urdu, you say, you know, what is دَعْوَة? What does that word mean? It''s an invitation, isn''t it? Now if I put a gun to your head and I say you''re coming to dinner tonight at my house, is that an invitation? Seriously, is that an invitation? It''s not. You''re not inviting someone, you''re forcing them to come. And you know, there''s no compulsion in religion. An invitation is only valid if you allow the person the possibility of refusing that invitation. Now, who would allow the person that possibility? A generous host, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'what is دعوه in arabic even in urdu you say you know what is دعوه what does that word mean its an invitation isnt it now if i put a gun to your head and i say youre coming to dinner tonight at my house is that an invitation seriously is that an invitation its not youre not inviting someone youre forcing them to come and you know theres no compulsion in religion an invitation is only valid if you allow the person the possibility of refusing that invitation now who would allow the person that possibility a generous host right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 39, NULL, 'اللَّهُ has made a house, He called it دَارُ السَّلَامِ, He invited all of His creation to it and He gave them the option to refuse to come to that house. So if people refuse it, why are we so fearful of them? Why are we so afraid of them? Right? See, the thing about people, you know, that when they are ignorant, they fear. That''s what a fundamentalist is, that''s what an extremist is. It is somebody who''s afraid of the other. He''s afraid of having his إِيمَان challenged. He''s so afraid that he won''t even allow for the other to exist because he can''t. He''s not going to allow that possibility. He wants them eliminated, my way or the highway. And we have this in our own community at our own levels, right? If you''re not going to follow what I''m saying, that''s it. And that''s really a disease. That''s not Islam. Islam is the only religion that''s ever allowed other religions, other ideologies to exist side by side with it, because it creates this environment of invitation. It allows the other people to experience something different and then be attracted to it.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'الله has made a house he called it دار السلام he invited all of his creation to it and he gave them the option to refuse to come to that house so if people refuse it why are we so fearful of them why are we so afraid of them right see the thing about people you know that when they are ignorant they fear thats what a fundamentalist is thats what an extremist is it is somebody whos afraid of the other hes afraid of having his ايمان challenged hes so afraid that he wont even allow for the other to exist because he cant hes not going to allow that possibility he wants them eliminated my way or the highway and we have this in our own community at our own levels right if youre not going to follow what im saying thats it and thats really a disease thats not islam islam is the only religion thats ever allowed other religions other ideologies to exist side by side with it because it creates this environment of invitation it allows the other people to experience something different and then be attracted to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 40, NULL, 'But because we present this harshness in our behaviors and then call it Islam, no wonder people are getting turned off from Islam in multitudes. Because we have no care about a fellow human being. We don''t look at the other person as a human being. We look at them as either Muslim, non-Muslim, Christian, Jew, believer, non-believer, in agreement with me, in disagreement with me, my enemy, right? There''s no... One of the great scholars of Islam, he said that the door that he came to his Lord through was تَعْظِيمُ الْمَخْلُوقَاتِ, exalting the creation of اللهُ سُبْحَانَهُ وَتَعَالَى. He said, ... I never saw a scholar except I exalted him because of the knowledge that he was carrying. But then it got to a point where مَا رَأَيْتُمْ مُؤْمِنًا أَوْ مُسْلِمًا مَهْمَا كَانَ حَالُهُ إِلَّا عَظَّمْتَهُ لِانْتِسَابِهِ الْعُبُودِيَّةَ لِلَّهِ. I never saw a believer or a Muslim man, no matter what his state was, but I exalted him just for being a servant of اللَّهُ. Just for attempting to submit to اللَّهُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'but because we present this harshness in our behaviors and then call it islam no wonder people are getting turned off from islam in multitudes because we have no care about a fellow human being we dont look at the other person as a human being we look at them as either muslim non muslim christian jew believer non believer in agreement with me in disagreement with me my enemy right theres no one of the great scholars of islam he said that the door that he came to his lord through was تعظيم المخلوقات exalting the creation of الله سبحانه وتعالي he said i never saw a scholar except i exalted him because of the knowledge that he was carrying but then it got to a point where ما رايتم مومنا او مسلما مهما كان حاله الا عظمته لانتسابه العبوديه لله i never saw a believer or a muslim man no matter what his state was but i exalted him just for being a servant of الله just for attempting to submit to الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 41, NULL, 'But then he said that I didn''t see anyone, even the non-Muslims, إِلَّا أَعْظَمَ طَاعَتِهِ لِأَنَّهُ مَحَلُّ الْإِرَادَةِ اللَّهِ سُبْحَانَهُ وَتَعَالَى حَيْثُ أَوْجَدَهُ بِقَوْلِهِ كُنْ فَيَكُونُ. Except that I never saw anyone, anything in this universe except that I exalted it because through his existence, I saw the will of the divine manifesting before my eyes. So he said I never saw a rock or a tree or anything or anyone except that I saw it as a manifestation of the divine will. It was God that put that thing there. That''s what he was acknowledging. And then he said the one who exalts the sanctified things of اللَّهُ, he is the one who is most loved by اللَّهُ. And what is more sanctified in this الٓمٓ than the creation of اللهُ سُبْحَانَهُ وَتَعَالَى? These things that اللَّهُ has created as His تَجَلِّي, right? His divine manifestations that invite us all to marvel over it, praise it. They draw out from us the praise component of this حَمْدٌ. I mean, if you look at people, right? When you see people who can do something slightly amazing, you see this beautiful singer singing a song in his or her beautiful voice or playing an instrument in a concert. What do people do? They just clap, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'but then he said that i didnt see anyone even the non muslims الا اعظم طاعته لانه محل الاراده الله سبحانه وتعالي حيث اوجده بقوله كن فيكون except that i never saw anyone anything in this universe except that i exalted it because through his existence i saw the will of the divine manifesting before my eyes so he said i never saw a rock or a tree or anything or anyone except that i saw it as a manifestation of the divine will it was god that put that thing there thats what he was acknowledging and then he said the one who exalts the sanctified things of الله he is the one who is most loved by الله and what is more sanctified in this الم than the creation of الله سبحانه وتعالي these things that الله has created as his تجلي right his divine manifestations that invite us all to marvel over it praise it they draw out from us the praise component of this حمد i mean if you look at people right when you see people who can do something slightly amazing you see this beautiful singer singing a song in his or her beautiful voice or playing an instrument in a concert what do people do they just clap right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 42, NULL, 'They just stand up, whistle and clap. They do all these things. They give this artist a standing ovation, to praise him or her because of what''s happening in their hearts. They just see something extraordinary and they want to praise it. They cannot help themselves because they just saw something that affected their soul. So when they see somebody who mastered the piano, for instance, you know, who got up and played some extraordinary piece of Beethoven, they just stand up and they clap and they clap and they clap. And the point is to say what an extraordinary thing you''ve just done before my eyes, right? It was truly incredible. That''s what they feel like doing because they find it so amazing. And yet we''re here in this incredible existence, this theater of amazing creations, stars in the heavens, galaxies of them. You know, we''ve got Hubble telescopes that look into the furthest corners of the universe, into this massive expansiveness. We have flowers that bloom before our eyes that demonstrate these beautiful colors, this incredible scent. We watch flowers that move across as the sun moves in the sky, you know, flowers that follow the sun.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'they just stand up whistle and clap they do all these things they give this artist a standing ovation to praise him or her because of whats happening in their hearts they just see something extraordinary and they want to praise it they cannot help themselves because they just saw something that affected their soul so when they see somebody who mastered the piano for instance you know who got up and played some extraordinary piece of beethoven they just stand up and they clap and they clap and they clap and the point is to say what an extraordinary thing youve just done before my eyes right it was truly incredible thats what they feel like doing because they find it so amazing and yet were here in this incredible existence this theater of amazing creations stars in the heavens galaxies of them you know weve got hubble telescopes that look into the furthest corners of the universe into this massive expansiveness we have flowers that bloom before our eyes that demonstrate these beautiful colors this incredible scent we watch flowers that move across as the sun moves in the sky you know flowers that follow the sun', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 43, NULL, 'There are, the Arabs call them عَبْدُ شَمْسٍ, you know, slaves of the sun. We have animals that do the most extraordinary things. Elephants that can carry these extraordinary weight on their backs. But then ants, little tiny ants, the most extraordinary in their creation, that they can carry many times their own weight. All of these things are happening right before our eyes. We have women with the fetus developing in their wombs. You know, mitotic cell division happening at these rapid rates. All of these things happening everywhere, constantly within us, outside of us. And we don''t feel compelled to give اللَّهُ a standing ovation. To stand before اللهُ سُبْحَانَهُ وَتَعَالَى at least five times a day and say اللهُ أَكْبَرُ، اللهُ أَكْبَرُ، اللهُ أَكْبَرُ. Really to stand in ovation before our master, like people stand before some poor soul who has perfected some little trick on a musical instrument, can just pipe out a tune, and we''re so compelled to jump up out of our seats and clap and, you know, Bravo, Bravo. And we can just get up to praise the master of this world, the الرَّحْمَٰن and the رَحِيم, and just say اللهُ أَكْبَرُ. I mean, really, what is wrong with us?', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'there are the arabs call them عبد شمس you know slaves of the sun we have animals that do the most extraordinary things elephants that can carry these extraordinary weight on their backs but then ants little tiny ants the most extraordinary in their creation that they can carry many times their own weight all of these things are happening right before our eyes we have women with the fetus developing in their wombs you know mitotic cell division happening at these rapid rates all of these things happening everywhere constantly within us outside of us and we dont feel compelled to give الله a standing ovation to stand before الله سبحانه وتعالي at least five times a day and say الله اكبر الله اكبر الله اكبر really to stand in ovation before our master like people stand before some poor soul who has perfected some little trick on a musical instrument can just pipe out a tune and were so compelled to jump up out of our seats and clap and you know bravo bravo and we can just get up to praise the master of this world the الرحمن and the رحيم and just say الله اكبر i mean really what is wrong with us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 44, NULL, 'الْحَمْدُ لِلَّهِ.', '', 'الْحَمْدُ لِلَّهِ', NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'الحمد لله', 'الحمد لله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 45, NULL, 'What has deluded us? What has taken us away from the praise and the gratitude of our master? I just am so guilty of all of this. It''s so hard to even admit and acknowledge this, but we''re all in the same boat of ingratitude. And our Prophet constantly went into سَجْدَة out of gratitude and praise for every little thing. He saw an eclipse. He went and gave God an ovation. He prayed. He stood up and, you know, he prayed, went into سَجْدَة as a testimony that he was witnessing something incredible. He was witnessing a reminder of the رَحْمَانِيَّة and the رَحِيمِيَّة of his رَبٌّ. Everything, every instant was a reminder for him. And yet here we are, blessed beyond measures.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'what has deluded us what has taken us away from the praise and the gratitude of our master i just am so guilty of all of this its so hard to even admit and acknowledge this but were all in the same boat of ingratitude and our prophet constantly went into سجده out of gratitude and praise for every little thing he saw an eclipse he went and gave god an ovation he prayed he stood up and you know he prayed went into سجده as a testimony that he was witnessing something incredible he was witnessing a reminder of the رحمانيه and the رحيميه of his رب everything every instant was a reminder for him and yet here we are blessed beyond measures', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'abundant and consistent mercy', 'Abundant and Consistent Mercy', 46, NULL, 'May اللَّهُ strengthen our hearts to witness and to experience, and give us this ability to just marvel over the blessings of His رَحْمَانِيَّة and His رَحِيمِيَّة. Because may He help us experience the joy of true and sincere praise and unconditional gratitude for not only everything that He has done for us, but also for what He has withheld from us. For not only the joy in our lives, but also for the grief and the sorrows that humble us, that remind us, that break our intoxication of this world, that sober us, that pull us off our high horses and just throw us down on the floor. الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِ الْمُحَمَّدِينَ خَاتِمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ وَعَلَى آلِهِ وَصَحْبِهِ عَلِيٍّ النَّبِيِّ طَالِبٍ أَشْرَفِ الْوَصِيِّينَ.', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'may الله strengthen our hearts to witness and to experience and give us this ability to just marvel over the blessings of his رحمانيه and his رحيميه because may he help us experience the joy of true and sincere praise and unconditional gratitude for not only everything that he has done for us but also for what he has withheld from us for not only the joy in our lives but also for the grief and the sorrows that humble us that remind us that break our intoxication of this world that sober us that pull us off our high horses and just throw us down on the floor الحمد لله رب العالمين والصلاه والسلام علي رسوله سيد المحمدين خاتم النبيين وسيد المرسلين وعلي اله وصحبه علي النبي طالب اشرف الوصيين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 0, NULL, 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ وَبَارِكْ وَسَلِّمْ كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي', '', 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ وَبَارِكْ وَسَلِّمْ كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي', NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد وبارك وسلم كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد وبارك وسلم كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 1, NULL, 'السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ In the last few sessions, we completed our discussion on these first three verses of سُورَةُ الْفَاتِحَةِ: ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎, ٱلرَّحْمَنِ ٱلرَّحِيمِ, all of which are a testimony to Allah''s abundant and consistent love and grace. He is the master of everything that exists in creation, and for that He is owed اَلْحَمْدُ, which is sincere praise and unconditional gratitude.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'السلام عليكم ورحمه الله وبركاته in the last few sessions we completed our discussion on these first three verses of سوره الفاتحه بسم الله الرحمن الرحيم الحمد لله رب العلمين الرحمن الرحيم all of which are a testimony to allahs abundant and consistent love and grace he is the master of everything that exists in creation and for that he is owed الحمد which is sincere praise and unconditional gratitude', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 2, NULL, 'Today we''re going to look at the next verse, which is مَلِكِ يَوْمِ ٱلدِّينِ. We''ll begin with a linguistic analysis of these three words to get a better understanding of exactly what this means. So this verse, مَلِكِ يَوْمِ ٱلدِّينِ, there are two forms of recitation for this verse. There is the Kufi style of recitation, which is what we recite generally, مَلِكِ يَوْمِ ٱلدِّينِ, but there''s another school of thought which recites this as مَلِكِ يَوْمِ ٱلدِّينِ, and actually both forms are valid. So we''ll look at both variations.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'today were going to look at the next verse which is ملك يوم الدين well begin with a linguistic analysis of these three words to get a better understanding of exactly what this means so this verse ملك يوم الدين there are two forms of recitation for this verse there is the kufi style of recitation which is what we recite generally ملك يوم الدين but theres another school of thought which recites this as ملك يوم الدين and actually both forms are valid so well look at both variations', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 3, NULL, 'The word مَالِكِ, as we know by now, it means an owner, right? Even in Urdu the word مَالِكِ means owner. And it comes from these three root letters, mem, lam and kaf, which is مَلِكِ, and the word مَلِكِ actually means property. So the one who owns property is called the مَالِكِ of that property, right? Now there''s another word in Arabic that shares the same three root letters, and that is مُلْك, which means kingdom, and the one who rules over a kingdom is called مَالِكِ, king.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'the word مالك as we know by now it means an owner right even in urdu the word مالك means owner and it comes from these three root letters mem lam and kaf which is ملك and the word ملك actually means property so the one who owns property is called the مالك of that property right now theres another word in arabic that shares the same three root letters and that is ملك which means kingdom and the one who rules over a kingdom is called مالك king', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 4, NULL, 'So Allah talks about both in the Quran. There is this concept of مِلْقِيَةٌ and there is مُلْقِيَة. The word مِلْقِيَةٌ means ownership and مُلْقِيَة means kingship. And Allah ascribes both these attributes to Himself. So He is not only the owner, He is also the king. Because He is the one who judges, the one who decrees, who legislates, who has the ultimate authority over everything in His kingdom.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'so allah talks about both in the quran there is this concept of ملقيه and there is ملقيه the word ملقيه means ownership and ملقيه means kingship and allah ascribes both these attributes to himself so he is not only the owner he is also the king because he is the one who judges the one who decrees who legislates who has the ultimate authority over everything in his kingdom', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 5, NULL, 'There is no one above the king that a plaintiff can plead his case with. So, Allah says in سُورَةُ الزُّمَرِ, He says, ‏وَمَا قَدَرُوا۟ ٱللَّهَ حَقَّ قَدْرِهِۦ وَٱلْأَرْضُ جَمِيعًۭا قَبْضَتُهُۥ يَوْمَ ٱلْقِيَمَةِ وَٱلسَّمَوَتُ مَطْوِيَّتٌۢ بِيَمِينِهِۦ ۚ سُبْحَنَهُۥ وَتَعَلَىٰ عَمَّا يُشْرِكُونَ ‎ They did not give Allah a just estimation that was due to Him. And on the day of the resurrection, the entire earth will be grasped by His hand and heavens will be rolled up in His right hand. Now, what does He mean by having it all in His right hand? It basically means, it''s an ancient Arabic expression that actually means under His complete control, right? This is مِلْقِيَةٌ, complete ownership.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'there is no one above the king that a plaintiff can plead his case with so allah says in سوره الزمر he says وما قدروا الله حق قدره والارض جميعا قبضته يوم القيمه والسموت مطويت بيمينه سبحنه وتعلي عما يشركون they did not give allah a just estimation that was due to him and on the day of the resurrection the entire earth will be grasped by his hand and heavens will be rolled up in his right hand now what does he mean by having it all in his right hand it basically means its an ancient arabic expression that actually means under his complete control right this is ملقيه complete ownership', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 6, NULL, 'In another verse, He says, ‏قُلِ ٱللَّهُمَّ مَلِكَ ٱلْمُلْكِ تُؤْتِى ٱلْمُلْكَ مَن تَشَآءُ وَتَنزِعُ ٱلْمُلْكَ مِمَّن تَشَآءُ وَتُعِزُّ مَن تَشَآءُ وَتُذِلُّ مَن تَشَآءُ ۖ بِيَدِكَ ٱلْخَيْرُ ۖ إِنَّكَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌۭ ‎ So, this verse begins by saying that قُلِ ٱللَّهُمَّ مَلِكَ ٱلْمُلْكِ, declare that Allah is the king of all kingdoms. Right? Here He talks about Himself as being the king, مَالِكِ. So you can see that both forms are used in the Quran. He is مَالِكِ and He is مَالِكِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'in another verse he says قل اللهم ملك الملك توتي الملك من تشاء وتنزع الملك ممن تشاء وتعز من تشاء وتذل من تشاء بيدك الخير انك علي كل شيء قدير so this verse begins by saying that قل اللهم ملك الملك declare that allah is the king of all kingdoms right here he talks about himself as being the king مالك so you can see that both forms are used in the quran he is مالك and he is مالك', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 7, NULL, 'He is the owner of the day of judgment and He is also the king of the day of judgment. And both these terms have this implication that nobody will be able to question Him about any of His decisions, and He alone will pass all judgment and make all the final decisions. So that is مَالِكِ or مَالِكِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'he is the owner of the day of judgment and he is also the king of the day of judgment and both these terms have this implication that nobody will be able to question him about any of his decisions and he alone will pass all judgment and make all the final decisions so that is مالك or مالك', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 8, NULL, 'The next word is يَوْم, which is actually quite an interesting word in Arabic, like مَلِكِ يَوْمِ ٱلدِّينِ. Now generally this statement is translated as a day, right? يَوْم is translated as day, owner of the day of judgment. But linguistically, يَوْم does not actually mean a 24-hour day. What it means is a time interval. It can mean any period of time. So يَوْم could be used for a moment. It could be used for an hour. It could mean a day, it could mean a month, a year. It could also mean several thousand years.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'the next word is يوم which is actually quite an interesting word in arabic like ملك يوم الدين now generally this statement is translated as a day right يوم is translated as day owner of the day of judgment but linguistically يوم does not actually mean a 24 hour day what it means is a time interval it can mean any period of time so يوم could be used for a moment it could be used for an hour it could mean a day it could mean a month a year it could also mean several thousand years', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 9, NULL, 'So, it is simply a duration of time allocated for, you know, a specific purpose. That''s what a يَوْمِ is. So, for instance, in the Quran, Allah says, ... The angels and the spirit ascend to Him during a يَوْمِ, the extent of which is 50,000 years. So, here Allah سُبْحَانَهُ وَتَعَالَى specifies يَوْمِ as being equal to 50,000 years. In سُورَةُ الْمُزَّمِّلِ, He says, ‏يَوْمَ تَرْجُفُ ٱلْأَرْضُ وَٱلْجِبَالُ وَكَانَتِ ٱلْجِبَالُ كَثِيبًۭا مَّهِيلًا ‎. That moment when the earth and the mountains will convulse and you will see that mountains will turn into a heap of sand that is being poured down. Here, He uses the same word يَوْم, مَلِكِ يَوْمِ ٱلدِّينِ, for a moment. So the word يَوْم can be used for various periods of time, including time itself. So, in سُورَةُ الْفَاتِحَةِ, He says, مَلِكِ يَوْمِ ٱلدِّينِ. Owner of the time period of دِين. Right?', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'so it is simply a duration of time allocated for you know a specific purpose thats what a يوم is so for instance in the quran allah says the angels and the spirit ascend to him during a يوم the extent of which is 50 000 years so here allah سبحانه وتعالي specifies يوم as being equal to 50 000 years in سوره المزمل he says يوم ترجف الارض والجبال وكانت الجبال كثيبا مهيلا that moment when the earth and the mountains will convulse and you will see that mountains will turn into a heap of sand that is being poured down here he uses the same word يوم ملك يوم الدين for a moment so the word يوم can be used for various periods of time including time itself so in سوره الفاتحه he says ملك يوم الدين owner of the time period of دين right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 10, NULL, 'So, now let''s look at دِين. The word دِين in the Arabic language comes from the root letters دَيْنٍ, which has several meanings. One of the meanings of دَيْنٍ is, you know, it is a type of rain that falls over and over again until it brings the dead earth back to life. Another meaning of دَيْنٍ is to discipline something. مَنْ دَنَا نَفْسُهُ, whoever disciplines his soul. It also means a way of life. ‏لَكُمْ دِينُكُمْ وَلِىَ دِينِ ‎, you have your way of life and we have ours. Right? But the root meaning of the word دَيْنٍ actually means debt. Our religion is called دِينُ الإِسْلَامِ, the Deen of Islam, and literally this can be translated as the debt of submission. In other words, the idea is that we have been endowed with innumerable and invaluable blessings by our Master.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'so now lets look at دين the word دين in the arabic language comes from the root letters دين which has several meanings one of the meanings of دين is you know it is a type of rain that falls over and over again until it brings the dead earth back to life another meaning of دين is to discipline something من دنا نفسه whoever disciplines his soul it also means a way of life لكم دينكم ولي دين you have your way of life and we have ours right but the root meaning of the word دين actually means debt our religion is called دين الاسلام the deen of islam and literally this can be translated as the debt of submission in other words the idea is that we have been endowed with innumerable and invaluable blessings by our master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 11, NULL, 'And so for all those blessings, we owe our Creator a debt of submission. Allah says, أَفَغَيْرَ دِينِ ٱللَّهِ يَبْغُونَ (Do they seek other than the دِين of Allah?) وَلَهُۥٓ أَسْلَمَ مَن فِى ٱلسَّمَوَتِ وَٱلْأَرْضِ طَوْعًۭا وَكَرْهًۭا, while all creatures in the heaven and the earth have bowed down to Him in submission, willingly or unwillingly. So what Allah is asking here is that do they seek other than repaying this debt when in reality everyone and everything in existence is paying its debt to its Creator? They''re all in a state of submission, willingly or unwillingly.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'and so for all those blessings we owe our creator a debt of submission allah says افغير دين الله يبغون do they seek other than the دين of allah وله اسلم من في السموت والارض طوعا وكرها while all creatures in the heaven and the earth have bowed down to him in submission willingly or unwillingly so what allah is asking here is that do they seek other than repaying this debt when in reality everyone and everything in existence is paying its debt to its creator theyre all in a state of submission willingly or unwillingly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 12, NULL, 'Now, there are areas of submission that the human being recognizes. One of them is our call to nature. We have to do certain things that we just cannot avoid. And one of them is, for instance, to eat. That is part of our nature. When we get hungry we must eat or we die. We need to drink water when we are thirsty. If we don''t drink, we die. We have to relieve ourselves once we have eaten or taken drink. We don''t really have a choice in these matters, do we? We have to do them whether we want to or not. We have to sleep. When sleep comes upon us, we can fight it for a while, but eventually we have to submit or we go into acute psychosis.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'now there are areas of submission that the human being recognizes one of them is our call to nature we have to do certain things that we just cannot avoid and one of them is for instance to eat that is part of our nature when we get hungry we must eat or we die we need to drink water when we are thirsty if we dont drink we die we have to relieve ourselves once we have eaten or taken drink we dont really have a choice in these matters do we we have to do them whether we want to or not we have to sleep when sleep comes upon us we can fight it for a while but eventually we have to submit or we go into acute psychosis', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 13, NULL, 'So there is this idea of willing or unwilling submission to nature itself. But then there is also submission to our own beings, to our own physical bodies. We have limitations. We can eat, but there is only so much that we can eat. We can only drink so much. We can only do so much physical work before we get exhausted. Right? We have limitations in our movements because of the structure of our bodies. So there is a type of submission of the self, given that we are temporal creatures that are limited by our physical aspects.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'so there is this idea of willing or unwilling submission to nature itself but then there is also submission to our own beings to our own physical bodies we have limitations we can eat but there is only so much that we can eat we can only drink so much we can only do so much physical work before we get exhausted right we have limitations in our movements because of the structure of our bodies so there is a type of submission of the self given that we are temporal creatures that are limited by our physical aspects', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 14, NULL, 'Now the Arabic word for a boundary or a limit is سُورَةُ الْفَاتِحَةِ. So all of creation have حُدُودٌ, right? We are all confined within our limits, within our boundaries. We cannot go outside those boundaries. Water cannot flow upwards. A rock cannot fly. A bird cannot bark. A dog cannot sing. Honey will always stay sweet. Citrus will always stay sour.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'now the arabic word for a boundary or a limit is سوره الفاتحه so all of creation have حدود right we are all confined within our limits within our boundaries we cannot go outside those boundaries water cannot flow upwards a rock cannot fly a bird cannot bark a dog cannot sing honey will always stay sweet citrus will always stay sour', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 15, NULL, 'So in the Quran, there is this idea of limitations, that everything is in a state of submission to its limitations. Every creature is confined within its boundaries, its حُدُود, and they are confined within it willingly or unwillingly. So in other words, they are all in a state of submission. And then Allah follows the statement with a reminder that they will all be returned back to their owner. And to Him is their return. Now if you deeply reflect upon creation itself, you''ll see that there are things that are emerging and then they are returning back into non-existence. Everything that has life comes into existence and then returns back into non-existence. Plants, vegetables, the animal kingdom, and ultimately even the mineral kingdom, they''re all returning to non-existence after they came into existence.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'so in the quran there is this idea of limitations that everything is in a state of submission to its limitations every creature is confined within its boundaries its حدود and they are confined within it willingly or unwillingly so in other words they are all in a state of submission and then allah follows the statement with a reminder that they will all be returned back to their owner and to him is their return now if you deeply reflect upon creation itself youll see that there are things that are emerging and then they are returning back into non existence everything that has life comes into existence and then returns back into non existence plants vegetables the animal kingdom and ultimately even the mineral kingdom theyre all returning to non existence after they came into existence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 16, NULL, 'So in other words, everything that is in existence is paying back its debt to its creator, except the human beings, you see. It is only human beings who are not actively paying back their debt of submission, their دِينُ الإِسْلَامِ. But the difference here is that we are also not being asked about our debts right now. So when will we be asked? And who will ask us about these debts? مَلِكِ يَوْمِ ٱلدِّينِ, the owner and the king of that time period when the debt of submission falls due. So يَوْمِ الدِّينِ is that time period when the debt of submission falls due. It''s payback time. كَيْفَمَا تُدِينُ تُدَانُ. How you transact with others is the way you will be transacted with. This is why this time period is also called يَوْمُ الْحِسَابِ, the time of accountability. رَسُولُ اللَّهِ said in one of his Hadiths, he said, take yourself to account before you are taken to account.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'so in other words everything that is in existence is paying back its debt to its creator except the human beings you see it is only human beings who are not actively paying back their debt of submission their دين الاسلام but the difference here is that we are also not being asked about our debts right now so when will we be asked and who will ask us about these debts ملك يوم الدين the owner and the king of that time period when the debt of submission falls due so يوم الدين is that time period when the debt of submission falls due its payback time كيفما تدين تدان how you transact with others is the way you will be transacted with this is why this time period is also called يوم الحساب the time of accountability رسول الله said in one of his hadiths he said take yourself to account before you are taken to account', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 17, NULL, 'So there is a debt of submission that we owe Allah. But then there is also a debt that Allah will owe us on that day. You see? When a master issues a command to his slave, the fulfillment of that command is a debt that the slave owes to his master, because there are only two possibilities: he either obeys the command or he disobeys it. In both cases, a return or a recompense falls due upon the master. You see, if the slave obeyed his master and executed his command properly, then his master owes him a reward. But if he disobeyed his master''s command, the master now owes him punishment. That''s يَوْمِ الدِّينِ, that''s يَوْمُ الْحِسَابِ, the day when that debt falls due. This is why Allah calls upon people to actually owe him a debt. He says in the Quran, who will indebt Allah with a beautiful debt? So Allah is asking us for a loan. Who will indebt Allah with a beautiful debt?', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'so there is a debt of submission that we owe allah but then there is also a debt that allah will owe us on that day you see when a master issues a command to his slave the fulfillment of that command is a debt that the slave owes to his master because there are only two possibilities he either obeys the command or he disobeys it in both cases a return or a recompense falls due upon the master you see if the slave obeyed his master and executed his command properly then his master owes him a reward but if he disobeyed his masters command the master now owes him punishment thats يوم الدين thats يوم الحساب the day when that debt falls due this is why allah calls upon people to actually owe him a debt he says in the quran who will indebt allah with a beautiful debt so allah is asking us for a loan who will indebt allah with a beautiful debt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 18, NULL, 'Why is Allah asking us for a loan? So that Allah multiplies its rewards many, many times over and returns it back to his life. So in this verse, Allah is actually asking His slaves, who among you will give me a loan? Right? Who among you will indebt me with His willing submission of عُبُودِيَّة, so that I can multiply its rewards many, many times over and pay it back to you. For He has the most noble rewards. سُبْحَانَ اللَّهِ. Even on that day of حِسَاب, this مَالِكِ is full of love and mercy. So that is what مَلِكِ يَوْمِ ٱلدِّينِ linguistically means. The king or the owner of the time period when the debt of submission falls due. Now let''s look at some of the implications of this verse. The most important aspect of this verse is that it addresses this notion of an unjust world.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'why is allah asking us for a loan so that allah multiplies its rewards many many times over and returns it back to his life so in this verse allah is actually asking his slaves who among you will give me a loan right who among you will indebt me with his willing submission of عبوديه so that i can multiply its rewards many many times over and pay it back to you for he has the most noble rewards سبحان الله even on that day of حساب this مالك is full of love and mercy so that is what ملك يوم الدين linguistically means the king or the owner of the time period when the debt of submission falls due now lets look at some of the implications of this verse the most important aspect of this verse is that it addresses this notion of an unjust world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 19, NULL, 'We know so many people today have given up faith and this belief in the existence of a creator based on the injustices that they see in this world, right? They look at all of this injustice that goes on around in this world and they use that as proof against God. Now this can be based on an injustice that happened to them personally or injustices that happens to another. And their argument is that if there is a God that is so loving and caring, then how come He let all of this happen? Now, what''s interesting about that, especially to us as a Muslim, is that nowhere in the Quran, Allah claims or promises to give us a good life in this world. Nowhere. In fact, what He promises every human being is quite the opposite. He says, in سُورَةُ الْبَقَرَةِ, He says, ‏وَلَنَبْلُوَنَّكُم بِشَىْءٍۢ مِّنَ ٱلْخَوْفِ وَٱلْجُوعِ وَنَقْصٍۢ مِّنَ ٱلْأَمْوَلِ وَٱلْأَنفُسِ وَٱلثَّمَرَتِ ۗ وَبَشِّرِ ٱلصَّبِرِينَ ‎. And no doubt about it, indeed, surely we shall test you with fear, with hunger, with loss of wealth, with loss of life, children, with loss of crops. But then he says, وَبَشِّرِ الصَّابِرِينَ, and for the patient ones there are glad tidings. In سُورَةُ الْمُلْكِ, he says, ‏تَبَرَكَ ٱلَّذِى بِيَدِهِ ٱلْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَىْءٍۢ قَدِيرٌ ‎. Blessed is the one whose hand has the ultimate dominion and is able to do everything.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'we know so many people today have given up faith and this belief in the existence of a creator based on the injustices that they see in this world right they look at all of this injustice that goes on around in this world and they use that as proof against god now this can be based on an injustice that happened to them personally or injustices that happens to another and their argument is that if there is a god that is so loving and caring then how come he let all of this happen now whats interesting about that especially to us as a muslim is that nowhere in the quran allah claims or promises to give us a good life in this world nowhere in fact what he promises every human being is quite the opposite he says in سوره البقره he says ولنبلونكم بشيء من الخوف والجوع ونقص من الامول والانفس والثمرت وبشر الصبرين and no doubt about it indeed surely we shall test you with fear with hunger with loss of wealth with loss of life children with loss of crops but then he says وبشر الصابرين and for the patient ones there are glad tidings in سوره الملك he says تبرك الذي بيده الملك وهو علي كل شيء قدير blessed is the one whose hand has the ultimate dominion and is able to do everything', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 20, NULL, '‏ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًۭا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ ‎. Who created death and life to test you and see which of you is the best in action. According to the Quran, this world was never meant for justice. According to the Quran, this life is a test, and this world that we live in is an examination hall, and everyone is being tested. Some with poverty, some with wealth, some with sickness, some with health. In fact, the healthy and the rich are going through a much more difficult test than the sick and the poor. Because they will be held accountable for these gifts. You know, I gave you all this, show me what you did with it. And this is why it''s no surprise that the greatest man to walk the face of this earth, رَسُولُ اللهِ ﷺ, he chose poverty over riches. But the point is that this world is imperfect and it is unjust by its very design. So now let''s take a moment to think about this perfect world. If I asked you to describe your perfect world to me, if I asked you to design a perfect world, what kind of world would you design? Think about it. What components would your perfect world comprise of?', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'الذي خلق الموت والحيوه ليبلوكم ايكم احسن عملا وهو العزيز الغفور who created death and life to test you and see which of you is the best in action according to the quran this world was never meant for justice according to the quran this life is a test and this world that we live in is an examination hall and everyone is being tested some with poverty some with wealth some with sickness some with health in fact the healthy and the rich are going through a much more difficult test than the sick and the poor because they will be held accountable for these gifts you know i gave you all this show me what you did with it and this is why its no surprise that the greatest man to walk the face of this earth رسول الله ﷺ he chose poverty over riches but the point is that this world is imperfect and it is unjust by its very design so now lets take a moment to think about this perfect world if i asked you to describe your perfect world to me if i asked you to design a perfect world what kind of world would you design think about it what components would your perfect world comprise of', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 21, NULL, 'We will all agree unanimously that in our perfect world there would be complete justice, there would be perfect harmony. No one in the world would sleep hungry. There would be no disease, there would be no pain, there would be no suffering. It would be a world where everybody is treated equally, justly. Love and peace will prevail. There will be absolutely no ugliness in that world. There will only be beauty. People would love and help each other. The proverbial lion and the deer would drink peacefully from the same river. Isn''t that the perfect world that we all dream of? Now if you think about it, what did I just describe to you? I just described جَنَّة.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'we will all agree unanimously that in our perfect world there would be complete justice there would be perfect harmony no one in the world would sleep hungry there would be no disease there would be no pain there would be no suffering it would be a world where everybody is treated equally justly love and peace will prevail there will be absolutely no ugliness in that world there will only be beauty people would love and help each other the proverbial lion and the deer would drink peacefully from the same river isnt that the perfect world that we all dream of now if you think about it what did i just describe to you i just described جنه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 22, NULL, 'Isn''t it? Isn''t all of this exactly the description of paradise? So you can see that this world is simply one side of the equation. The problem with someone who is only seeing this world is that he is looking at just one side of the equation, and there are a bunch of imbalances on this side. If you do not believe in a Day of Judgment, in a day of accountability, then you are simply left with a world that is completely unfair. But if you believe in a Day of Judgment, all the injustices on this side of the equation will get balanced with perfect justice on the other side of the equation. So in fact, the injustices of this world is proof and testimony to the existence of a perfect world. Logically, just speaking logically, rationally as human beings, what we see in this world, we have to believe because it is our innate desire to have this perfect world. Where do we get this concept of a perfect world? How come even the atheist, the one who does not believe in God, does believe in the dream of a perfect world? Because that is the other side of the equation. So just this, the inferior version of this دُنْيَا, is proof of the existence of a perfect world. So in this verse Allah talks about this transition that will take place from this world into the next.', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'isnt it isnt all of this exactly the description of paradise so you can see that this world is simply one side of the equation the problem with someone who is only seeing this world is that he is looking at just one side of the equation and there are a bunch of imbalances on this side if you do not believe in a day of judgment in a day of accountability then you are simply left with a world that is completely unfair but if you believe in a day of judgment all the injustices on this side of the equation will get balanced with perfect justice on the other side of the equation so in fact the injustices of this world is proof and testimony to the existence of a perfect world logically just speaking logically rationally as human beings what we see in this world we have to believe because it is our innate desire to have this perfect world where do we get this concept of a perfect world how come even the atheist the one who does not believe in god does believe in the dream of a perfect world because that is the other side of the equation so just this the inferior version of this دنيا is proof of the existence of a perfect world so in this verse allah talks about this transition that will take place from this world into the next', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'day of judgment - linguistics', 'Day Of Judgment - Linguistics', 23, NULL, 'There is a transition from رُبُوبِيَّة to مَالِكِيَّة. From lordship to ownership or kingship. From the love, care, concern and mercy of Allah in this world to the one in which He takes on a different role. The role of the owner and the king of the day when the debt of submission falls due. So this verse actually makes the transition from دُنْيَا to the أُخْرَى. إِن شَآءَ ٱللَّهُ, in the next session we''ll look at some more implications of this verse and how it affects our lives. وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ الْخَاتِمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ، وَعَلَى أَخِيهِ وَوَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ، وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِ الطَّيِّبِينَ الطَّاهِرِينَ، وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ، الْفَاتِحَة', '', NULL, NULL, NULL, NULL, 'surah al fateha day of judgment linguistics', 'there is a transition from ربوبيه to مالكيه from lordship to ownership or kingship from the love care concern and mercy of allah in this world to the one in which he takes on a different role the role of the owner and the king of the day when the debt of submission falls due so this verse actually makes the transition from دنيا to the اخري ان شاء الله in the next session well look at some more implications of this verse and how it affects our lives واخر دعوانا ان الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد الخاتم النبيين وسيد المرسلين وعلي اخيه ووصيه علي بن ابي طالب اشرف الوصيين وعلي الايمه من ذريته الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 0, NULL, 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ, ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, اللَّهُمَّ صَلِّ يَا اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ، وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ، كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ، وَعَلَى آلِ إِبْرَاهِيمَ، فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ, رَبِّ اشْرَحْ لِي صَدْرِي، وَيَسِّرْ لِي أَمْرِي، وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي، يَفْقَهُوا قَوْلِي. سَلَامٌ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ.', '', 'أَعُوذُ بِاللهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ اللَّهُمَّ صَلِّ يَا اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ، وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ، كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ، وَعَلَى آلِ إِبْرَاهِيمَ، فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ رَبِّ اشْرَحْ لِي صَدْرِي، وَيَسِّرْ لِي أَمْرِي، وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي، يَفْقَهُوا قَوْلِي سَلَامٌ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ', NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل يا الله علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي سلام عليكم ورحمه الله وبركاته', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل يا الله علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي سلام عليكم ورحمه الله وبركاته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 1, NULL, 'So in the previous session, we learned that مَلِكِ يَوْمِ ٱلدِّينِ, linguistically what it means is the owner, مَالِكِ or مَالِكِ, which is king. So the owner or the king of the time period when the debt of submission falls due. And we talked about the imperfections of this world which necessitate this idea of a perfect world which is the hereafter.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'so in the previous session we learned that ملك يوم الدين linguistically what it means is the owner مالك or مالك which is king so the owner or the king of the time period when the debt of submission falls due and we talked about the imperfections of this world which necessitate this idea of a perfect world which is the hereafter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 2, NULL, 'Today we look at this verse in some more detail and I want to help us understand its purpose and its relevance in the surah, especially from the point of view of this transition that we see taking place here. So if you look at the theme of the surah so far, we saw that from the beginning, اللَّهُs love and His mercy was being highlighted, right? I begin with the lofty symbols of اللَّهُ that are pointing to His immense love and mercy. All sincere praise and all unconditional gratitude is due to اللَّهُ for His mastery, His lordship over this أَلَمْ, which is everything that can be known in existence. So, ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎, the abundantly merciful, the consistently merciful.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'today we look at this verse in some more detail and i want to help us understand its purpose and its relevance in the surah especially from the point of view of this transition that we see taking place here so if you look at the theme of the surah so far we saw that from the beginning اللهs love and his mercy was being highlighted right i begin with the lofty symbols of الله that are pointing to his immense love and mercy all sincere praise and all unconditional gratitude is due to الله for his mastery his lordship over this الم which is everything that can be known in existence so الحمد لله رب العلمين the abundantly merciful the consistently merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 3, NULL, 'So, if you look at this, right, اللَّهُs love is being highlighted in the surah, and now suddenly there is this switch that we see in tone, and اللَّهُ changes His tone to say, مَلِكِ يَوْمِ ٱلدِّينِ, owner of the time when the debt of submission falls due. Right? Why this sudden change in tone? So scholars explain that this transition is extremely profound, and its purpose is to engender this desire for تَقْوَى in our hearts. So it is what the Arabs called الْبَاعِث, which is what basically stimulates you to do something, something that motivates you. It''s the motivating factor about something.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'so if you look at this right اللهs love is being highlighted in the surah and now suddenly there is this switch that we see in tone and الله changes his tone to say ملك يوم الدين owner of the time when the debt of submission falls due right why this sudden change in tone so scholars explain that this transition is extremely profound and its purpose is to engender this desire for تقوي in our hearts so it is what the arabs called الباعث which is what basically stimulates you to do something something that motivates you its the motivating factor about something', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 4, NULL, 'Because if you think about it, if love is not balanced with some system of accountability, it is human tendency to start taking advantage of that kindness. We see this all the time in our life. If you know anyone in your life who is just love, love, love all the time, someone who will let people get away with murder, what you''ll see is that as much as this person might be loved, they will never be taken seriously. In fact, they will be taken advantage of. Isn''t that the case? So understanding this weakness in human nature, اللَّهُ changes His tone to remind us that look, even though I am a very merciful and a very loving God, but you have to take Me seriously.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'because if you think about it if love is not balanced with some system of accountability it is human tendency to start taking advantage of that kindness we see this all the time in our life if you know anyone in your life who is just love love love all the time someone who will let people get away with murder what youll see is that as much as this person might be loved they will never be taken seriously in fact they will be taken advantage of isnt that the case so understanding this weakness in human nature الله changes his tone to remind us that look even though i am a very merciful and a very loving god but you have to take me seriously', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 5, NULL, 'Don''t think you can take undue advantage of My love, because I am also your creator, I am also your owner, I am also your king, and I have set a time period where I will take you to account for your debt of submission. Because nothing is happening right now to you in this world. You are free to do whatever you want, right? If you commit a sin right now in this world, lightning is not going to strike you down. So what that freedom allows human nature to do is that it allows us to become heedless, and this verse is basically reminding us not to be heedless. It creates a sense of accountability and it also creates a sense of urgency to make the most of whatever time we have remaining.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'dont think you can take undue advantage of my love because i am also your creator i am also your owner i am also your king and i have set a time period where i will take you to account for your debt of submission because nothing is happening right now to you in this world you are free to do whatever you want right if you commit a sin right now in this world lightning is not going to strike you down so what that freedom allows human nature to do is that it allows us to become heedless and this verse is basically reminding us not to be heedless it creates a sense of accountability and it also creates a sense of urgency to make the most of whatever time we have remaining', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 6, NULL, 'Because no one knows when and where he''s going to die, right? Except that we all know that we are going to inevitably die someday. وَمَا تَدْرِى نَفْسٌۭ مَّاذَا تَكْسِبُ غَدًۭا وَمَا تَدْرِى نَفْسٌۢ بِأَىِّ أَرْضٍۢ تَمُوتُ. No soul knows what he will earn tomorrow, and no soul knows in which land it will die. So this concept of an inevitable death and this idea of returning back to the creator for accountability, what it does is that it creates this awareness of اللَّهُ in our hearts, which is called تَقْوَى. This word تَقْوَى, it comes from وِقَايَة, which means a strong sense of fearful awareness.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'because no one knows when and where hes going to die right except that we all know that we are going to inevitably die someday وما تدري نفس ماذا تكسب غدا وما تدري نفس باي ارض تموت no soul knows what he will earn tomorrow and no soul knows in which land it will die so this concept of an inevitable death and this idea of returning back to the creator for accountability what it does is that it creates this awareness of الله in our hearts which is called تقوي this word تقوي it comes from وقايه which means a strong sense of fearful awareness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 7, NULL, 'So, تَقْوَى is the awareness of اللَّهُs constant presence in our lives. So, scholars have stated that what this verse مَلِكِ يَوْمِ ٱلدِّينِ does is that it motivates us towards تَقْوَى in a number of ways. So, today I want to go over some of those motivating factors that have been outlined by scholars.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'so تقوي is the awareness of اللهs constant presence in our lives so scholars have stated that what this verse ملك يوم الدين does is that it motivates us towards تقوي in a number of ways so today i want to go over some of those motivating factors that have been outlined by scholars', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 8, NULL, 'The first, they say, is the fear of punishment in this world. This is a worldly type of retribution which is called عِقَاب. So human nature is such that we just naturally tend to fear pain. In fact, fear of pain is probably a greater immediate concern than the desire for pleasure. There were these studies done that when given two choices and the possibility of one over the other were equal, people chose to avoid pain rather than acquiring pleasure. So the avoidance of pain, the fear of pain, actually supersedes the desire for pleasure. And so what this fear allows us to do is that it enables us to delay our gratification.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'the first they say is the fear of punishment in this world this is a worldly type of retribution which is called عقاب so human nature is such that we just naturally tend to fear pain in fact fear of pain is probably a greater immediate concern than the desire for pleasure there were these studies done that when given two choices and the possibility of one over the other were equal people chose to avoid pain rather than acquiring pleasure so the avoidance of pain the fear of pain actually supersedes the desire for pleasure and so what this fear allows us to do is that it enables us to delay our gratification', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 9, NULL, 'They did a study in the US which was, I think, a 30-year study. It was very interesting. What they did is that they took these five-year-old kids and they offered them a cookie. And they said that you can have this cookie right now, or if you wait 10 minutes you can have two cookies. And so the children were very different in their choices. And what these people did is that they monitored these kids over a 30-year period. And what they found almost consistently was that the children that delayed their gratification for a greater reward, the children that took one cookie and waited, that left that one cookie and waited 10 minutes to get the two cookies, basically delaying their gratification, they found that these kids were far more successful in their lives than the ones who wanted it and took it immediately. It was a very interesting study.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'they did a study in the us which was i think a 30 year study it was very interesting what they did is that they took these five year old kids and they offered them a cookie and they said that you can have this cookie right now or if you wait 10 minutes you can have two cookies and so the children were very different in their choices and what these people did is that they monitored these kids over a 30 year period and what they found almost consistently was that the children that delayed their gratification for a greater reward the children that took one cookie and waited that left that one cookie and waited 10 minutes to get the two cookies basically delaying their gratification they found that these kids were far more successful in their lives than the ones who wanted it and took it immediately it was a very interesting study', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 10, NULL, 'So the delay of gratification, right, this temporary deprivation for the hope of something greater, is very important. And this delay is the basis of a lot of what is going on in the Quran. This idea of delaying gratification, because the people of this دُنْيَا, they desire instant gratification. Right? No, you love this, the instant gratification, the present life of this world, and you keep delaying, you keep leaving the Hereafter. So basically you put off what''s coming and you just want this immediate pleasure.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'so the delay of gratification right this temporary deprivation for the hope of something greater is very important and this delay is the basis of a lot of what is going on in the quran this idea of delaying gratification because the people of this دنيا they desire instant gratification right no you love this the instant gratification the present life of this world and you keep delaying you keep leaving the hereafter so basically you put off whats coming and you just want this immediate pleasure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 11, NULL, 'And this is something we all are guilty of. We all fall into lust. It''s an immediate pleasure. It''s instant gratification. It''s an immediate satisfaction. And we often end up sacrificing doing the right thing to gain this immediate pleasure. And we don''t think of repercussions. But that''s the way we are, that''s just human nature.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'and this is something we all are guilty of we all fall into lust its an immediate pleasure its instant gratification its an immediate satisfaction and we often end up sacrificing doing the right thing to gain this immediate pleasure and we dont think of repercussions but thats the way we are thats just human nature', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 12, NULL, 'So مَلِكِ يَوْمِ ٱلدِّينِ is essentially what the scholars say, you know, it is the fear of punishment in the next world. One of the things about the Islamic and essentially all Abrahamic faiths is that there''s an idea that just as you have physics, you also have metaphysics. So physics are laws that we can discern from this palpable world, right? This world, this sensory world that we can touch and feel, it has certain laws.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'so ملك يوم الدين is essentially what the scholars say you know it is the fear of punishment in the next world one of the things about the islamic and essentially all abrahamic faiths is that theres an idea that just as you have physics you also have metaphysics so physics are laws that we can discern from this palpable world right this world this sensory world that we can touch and feel it has certain laws', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 13, NULL, 'And these are the laws of cause and effect. If you do something in this world, so every action has to have a reaction. So for instance, if I hit this table, there''s going to be the sound, right? If there was no sound, then there''s a suspension of a physical law and we''d have to look into it. Like, why did that happen? Why was there no sound? Because according to the laws of physics, my striking this table should produce a sound. So there are these laws of, if you jump off a building, there''s going to be an effect from that cause. Right? So just as there are physical laws, there are also metaphysical laws. There are laws of cause and effect that transcend the physical world. And they move into the spiritual world or the psychic world.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'and these are the laws of cause and effect if you do something in this world so every action has to have a reaction so for instance if i hit this table theres going to be the sound right if there was no sound then theres a suspension of a physical law and wed have to look into it like why did that happen why was there no sound because according to the laws of physics my striking this table should produce a sound so there are these laws of if you jump off a building theres going to be an effect from that cause right so just as there are physical laws there are also metaphysical laws there are laws of cause and effect that transcend the physical world and they move into the spiritual world or the psychic world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 14, NULL, 'So for instance, if I shout at you, if I scream at you, there is going to be a psychic effect. It''s going to have an emotional effect. Where are emotions? We don''t truly understand where emotions lie, except that we just know that they''re part of our consciousness. But if I shout at you, you will feel something inside. You will either feel depressed or you will become angry. And that''s coming from another realm, right? It''s not from the physical realm. That''s from the realm of emotions. So just as there are physical effects, there are also spiritual effects, there are also psychic effects. So for instance, the Arabs, they have this term, what they call which literally means water of the face. But the idea is that it''s a kind of purity or a kind of impurity that people have on their face.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'so for instance if i shout at you if i scream at you there is going to be a psychic effect its going to have an emotional effect where are emotions we dont truly understand where emotions lie except that we just know that theyre part of our consciousness but if i shout at you you will feel something inside you will either feel depressed or you will become angry and thats coming from another realm right its not from the physical realm thats from the realm of emotions so just as there are physical effects there are also spiritual effects there are also psychic effects so for instance the arabs they have this term what they call which literally means water of the face but the idea is that its a kind of purity or a kind of impurity that people have on their face', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 15, NULL, 'You''ll see this, people who have sinned a lot in their lives, their evil begins to show up on their faces and you get a type of metaphysical darkness in their face. In the same way, people that do a lot of good deeds, you''ll see that their faces are affected by that. They have a kind face. You see this luminance or this brightness radiating from their face. And this is why the Arabs used to call a face, they would call it الصَّحِيفَة, which means the register, because it registers everything. Somebody once said that by 50, everybody has the face that they deserve. So if you''re 50 years old, you have the face that you deserve. If you''ve had a good life, it''s going to show up on your face. So that fear of another worldly punishment is one of the things that will compel a person to do good and stay within boundaries within this world by delaying gratifications. The next motivating factor for تَقْوَى is desiring a benefit. That''s the next one.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'youll see this people who have sinned a lot in their lives their evil begins to show up on their faces and you get a type of metaphysical darkness in their face in the same way people that do a lot of good deeds youll see that their faces are affected by that they have a kind face you see this luminance or this brightness radiating from their face and this is why the arabs used to call a face they would call it الصحيفه which means the register because it registers everything somebody once said that by 50 everybody has the face that they deserve so if youre 50 years old you have the face that you deserve if youve had a good life its going to show up on your face so that fear of another worldly punishment is one of the things that will compel a person to do good and stay within boundaries within this world by delaying gratifications the next motivating factor for تقوي is desiring a benefit thats the next one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 16, NULL, 'So just as people fear punishment, they also desire benefit. This is at the most basic human foundation, right? Stick and carrot. This is how children are disciplined, stick and carrot. It''s how societies work, stick and carrot. So really much of society is based on these principles. And that''s why the highest people, the elite, the most intelligent people are the ones that actually transcend these stick and carrot factors and they move into another realm. People like Maulana Ali, who often said in his prayers, يَا إِلَهِي، مَا عَبَدْتُكَ بِشَوْقِ جَنَّتِكَ، وَلَا مِنْ خَوْفِ نَارِكَ، بَلْ وَجَدْتُكَ مُسْتَحِقًّا لِلْعِبَادَةِ فَعَبَدْتُكَ. My master, I do not worship you out of a desire for your paradise, nor do I worship you out of fear of your hellfire. Instead, I truly found you worthy of my worship, and for that reason alone I worship you. And this is a very high station of worship that completely transcends this carrot and stick philosophy. It''s the ideal form of worship. But the majority of people are at this base level, and because the Quran speaks to all of humanity, it talks in this general manner. There''s a Hadith in which the Prophet said, move according to the level of the least amongst you. Move according to the level of the least amongst you.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'so just as people fear punishment they also desire benefit this is at the most basic human foundation right stick and carrot this is how children are disciplined stick and carrot its how societies work stick and carrot so really much of society is based on these principles and thats why the highest people the elite the most intelligent people are the ones that actually transcend these stick and carrot factors and they move into another realm people like maulana ali who often said in his prayers يا الهي ما عبدتك بشوق جنتك ولا من خوف نارك بل وجدتك مستحقا للعباده فعبدتك my master i do not worship you out of a desire for your paradise nor do i worship you out of fear of your hellfire instead i truly found you worthy of my worship and for that reason alone i worship you and this is a very high station of worship that completely transcends this carrot and stick philosophy its the ideal form of worship but the majority of people are at this base level and because the quran speaks to all of humanity it talks in this general manner theres a hadith in which the prophet said move according to the level of the least amongst you move according to the level of the least amongst you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 17, NULL, 'سُبْحَانَ اللَّهِ. So you have to move with the least amongst you. You don''t speed up and leave people behind. Right? No, that''s not the way of Islam. And this is why if you carefully study this religion, you''ll see that most of it is designed to protect the weakest people. Right? Because there are people who can stand on their own and they don''t have a problem with that, but then there are also people that cannot do that and they have their human weaknesses. And so the شَرِيعَة, it protects those people by preventing them from certain things. And this is why the Quran speaks against things like gambling, for instance, right? The Quran says that there is good in gambling, actually, it does say that.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'سبحان الله so you have to move with the least amongst you you dont speed up and leave people behind right no thats not the way of islam and this is why if you carefully study this religion youll see that most of it is designed to protect the weakest people right because there are people who can stand on their own and they dont have a problem with that but then there are also people that cannot do that and they have their human weaknesses and so the شريعه it protects those people by preventing them from certain things and this is why the quran speaks against things like gambling for instance right the quran says that there is good in gambling actually it does say that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 18, NULL, 'يَسْـَٔلُونَكَ عَنِ ٱلْخَمْرِ وَٱلْمَيْسِرِ قُلْ فِيهِمَآ إِثْمٌۭ كَبِيرٌۭ وَمَنَفِعُ لِلنَّاسِ وَإِثْمُهُمَآ أَكْبَرُ مِن نَّفْعِهِمَا. They ask you concerning alcohol and gambling. Tell them in them is a great sin and also a benefit for mankind, but the sin is far greater than their benefit. So Quran actually says that there is some good in gambling. I mean, there are lessons to be learned in gambling, right? Risk is an interesting phenomenon in commerce. There''s a strong relationship between gambling and commerce. But the harms of gambling are far greater than its benefits. And it is a known social science, this fact that around 3% of people that go into gambling casinos, they become addicted and it destroys their lives. And this is why if you''ve ever been to a gambling casino, I mean, I''ve been inside this casino at Atlantic City many years ago, and it was one of the most frightening things I ever saw. It was like a circle out of Dante''s Inferno. And you just see all of these people in this zombie-like state, just sitting on their seats, putting in quarters into the machine one after the other and pulling this lever. I mean, it''s a scary sight. And then there was this pawn shop in the middle of that casino with this big sign outside that said, We take wedding rings. That is just so sinister.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'يسلونك عن الخمر والميسر قل فيهما اثم كبير ومنفع للناس واثمهما اكبر من نفعهما they ask you concerning alcohol and gambling tell them in them is a great sin and also a benefit for mankind but the sin is far greater than their benefit so quran actually says that there is some good in gambling i mean there are lessons to be learned in gambling right risk is an interesting phenomenon in commerce theres a strong relationship between gambling and commerce but the harms of gambling are far greater than its benefits and it is a known social science this fact that around 3 of people that go into gambling casinos they become addicted and it destroys their lives and this is why if youve ever been to a gambling casino i mean ive been inside this casino at atlantic city many years ago and it was one of the most frightening things i ever saw it was like a circle out of dantes inferno and you just see all of these people in this zombie like state just sitting on their seats putting in quarters into the machine one after the other and pulling this lever i mean its a scary sight and then there was this pawn shop in the middle of that casino with this big sign outside that said we take wedding rings that is just so sinister', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 19, NULL, 'What kind of people are these? How do you justify a job like this, just depriving people in this manner, just taking advantage of human weakness? But that''s the reality of our world, right? And gambling is based on the carrot phenomenon. It''s a carrot phenomenon. You know, gamblers think that if I put in money and I pull the lever, and it''s all designed so that winning will happen enough times to keep you there, right? That''s part of the design. So when people leave, they say, oh, you know, I made such and such. They never actually think about how much they lost. They''ll always tell you how much they won. So that''s the phenomenon of the carrot, you know, and it''s used a lot, and that''s one of the worst things about it.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'what kind of people are these how do you justify a job like this just depriving people in this manner just taking advantage of human weakness but thats the reality of our world right and gambling is based on the carrot phenomenon its a carrot phenomenon you know gamblers think that if i put in money and i pull the lever and its all designed so that winning will happen enough times to keep you there right thats part of the design so when people leave they say oh you know i made such and such they never actually think about how much they lost theyll always tell you how much they won so thats the phenomenon of the carrot you know and its used a lot and thats one of the worst things about it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 20, NULL, 'But then obviously from the worldly things, you know, these things that are pleasurable that we find in the slide, that give you instant pleasure, they''re always followed by a far greater pain, because that''s just the design of it, isn''t it? I mean, in our case, we all can give examples of that. And this is why the Prophet, he said, Paradise was surrounded by distasteful things and fire was surrounded by delightful things, pleasurable things. So if you''re walking towards paradise, you will inevitably encounter distasteful things. It''s just part of the design. And so now it''s up to the عَقِيل, this person of intellect, to recognize this, and that''s why the Quran frequently talks about تَدَبُّر, which means to reflect deeply upon something. You know, Quran frequently asks us ... Why don''t you reflect deeply? It actually uses the word تَدَبُّر a lot, which is deep reflection. The word تَدَبُّر comes from a root which means to take something to its end. دُبُر is the behind of something.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'but then obviously from the worldly things you know these things that are pleasurable that we find in the slide that give you instant pleasure theyre always followed by a far greater pain because thats just the design of it isnt it i mean in our case we all can give examples of that and this is why the prophet he said paradise was surrounded by distasteful things and fire was surrounded by delightful things pleasurable things so if youre walking towards paradise you will inevitably encounter distasteful things its just part of the design and so now its up to the عقيل this person of intellect to recognize this and thats why the quran frequently talks about تدبر which means to reflect deeply upon something you know quran frequently asks us why dont you reflect deeply it actually uses the word تدبر a lot which is deep reflection the word تدبر comes from a root which means to take something to its end دبر is the behind of something', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 21, NULL, 'It''s the end of something. أَدْبَار is what''s behind you. So تَدَبُّر is going through something until you get to its very end. So that''s why when you have تَدَبُّر as a quality, you just look down the road, right? You think about the consequences. You think about where this action will end up. Whereas this person who''s just stuck in this أَجَلَ, this haste of instant gratification, doesn''t really just go beyond the present, and they''re just stuck right there and they don''t think about the future. And there''s this interesting theory in theology about this divine experience versus a demonic experience. And the way you differentiate between a true divine experience and a true demonic experience is that a demonic experience is always accompanied with an expansion of the self. In other words, it is very exciting and it''s a very joyful experience, the demonic experience. But then it is always followed with despair.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'its the end of something ادبار is whats behind you so تدبر is going through something until you get to its very end so thats why when you have تدبر as a quality you just look down the road right you think about the consequences you think about where this action will end up whereas this person whos just stuck in this اجل this haste of instant gratification doesnt really just go beyond the present and theyre just stuck right there and they dont think about the future and theres this interesting theory in theology about this divine experience versus a demonic experience and the way you differentiate between a true divine experience and a true demonic experience is that a demonic experience is always accompanied with an expansion of the self in other words it is very exciting and its a very joyful experience the demonic experience but then it is always followed with despair', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 22, NULL, 'On the contrary, a true spiritual experience, a true divine experience is exactly the opposite. The initial experience is incredible constriction and it''s incredible fear and dread, but then it is followed by a sense of expansion and joy. So, you know, anyway, so the benefit, acquiring a benefit is the second motivating factor for تَقْوَى. The next motivating factor, scholars say, and benefits of this verse, مَلِكِ يَوْمِ ٱلدِّينِ, the other benefit that it provides is that it gives us the grounds for the fear of a reckoning. That you''re going to be reckoned on the Day of Judgment. And so this fear of reckoning, it should instill in our hearts this desire to do good. You see, anyone who has a business, they have what they call internal audits. If you have a business and you live in a country like the US or England, for instance, where they have these revenue services, these are external agencies that will come in and they will examine your books, they will examine your business. And if you''ve been fudging the books, then you''ll get penalties. It''s not just that you will pay what you owe in back taxes and things like that. They will actually add penalties and they will add interest and they will do all these kinds of things.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'on the contrary a true spiritual experience a true divine experience is exactly the opposite the initial experience is incredible constriction and its incredible fear and dread but then it is followed by a sense of expansion and joy so you know anyway so the benefit acquiring a benefit is the second motivating factor for تقوي the next motivating factor scholars say and benefits of this verse ملك يوم الدين the other benefit that it provides is that it gives us the grounds for the fear of a reckoning that youre going to be reckoned on the day of judgment and so this fear of reckoning it should instill in our hearts this desire to do good you see anyone who has a business they have what they call internal audits if you have a business and you live in a country like the us or england for instance where they have these revenue services these are external agencies that will come in and they will examine your books they will examine your business and if youve been fudging the books then youll get penalties its not just that you will pay what you owe in back taxes and things like that they will actually add penalties and they will add interest and they will do all these kinds of things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 23, NULL, 'So companies that are worried about that external reckoning or that external auditing by the revenue services, what they do is that they conduct an internal audit, and so if there''s anything that needs correcting, they will correct it internally. And that''s what''s called in our terms, it''s called مُحَاسَبَة, and it''s part of تَقْوَى, where you actually take your own self to account. The hadith says: Take yourself to account before you are taken to account. And this is why it has been said that when a true believer, when he lies down to sleep at night, he reflects on his actions for the day. And the things that he found that he did wrong, he asks اللَّهُ for forgiveness and he makes a determination to correct those things in the next day. So this is why this concept of مُحَاسَبَة is an extremely important concept within Islam.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'so companies that are worried about that external reckoning or that external auditing by the revenue services what they do is that they conduct an internal audit and so if theres anything that needs correcting they will correct it internally and thats whats called in our terms its called محاسبه and its part of تقوي where you actually take your own self to account the hadith says take yourself to account before you are taken to account and this is why it has been said that when a true believer when he lies down to sleep at night he reflects on his actions for the day and the things that he found that he did wrong he asks الله for forgiveness and he makes a determination to correct those things in the next day so this is why this concept of محاسبه is an extremely important concept within islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 24, NULL, 'The next benefit of this verse is that it creates this concept of shame or modesty from the awareness of God. That اللَّهُ is aware of our actions, that اللَّهُ is watching us. So we should have this shame or this modesty before اللَّهُ. حَيَّا. The word الْحَيَا in Arabic is probably better translated as modesty, which is related to shame. There''s a sense that you don''t want to do something in front of a person or in front of your Lord out of love and respect. There are certain things that children won''t do in front of their parents out of respect. The Prophet, he said: Every religion has a peculiar characteristic, and the characteristic of my religion is modesty. Anthropologists, they divide cultures into two types of cultures.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'the next benefit of this verse is that it creates this concept of shame or modesty from the awareness of god that الله is aware of our actions that الله is watching us so we should have this shame or this modesty before الله حيا the word الحيا in arabic is probably better translated as modesty which is related to shame theres a sense that you dont want to do something in front of a person or in front of your lord out of love and respect there are certain things that children wont do in front of their parents out of respect the prophet he said every religion has a peculiar characteristic and the characteristic of my religion is modesty anthropologists they divide cultures into two types of cultures', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 25, NULL, 'They divide it as shame based cultures and then guilt based cultures. So Western cultures generally tend to fall into the guilt culture. And a guilt culture, it cultivates within people moral components inside of themselves where If they do something wrong, they feel bad about it on the inside. And so one of the things a lot of people know about people in the West is that they will often find it very difficult to do wrong things without actually feeling bad. In fact, there''s a whole industry in America to help people overcome this feeling of guilt, self-help books, self-improvement courses. There''s a whole industry that capitalizes on this idea of helping people overcome guilt. So in guilt cultures, there''s an internal mechanism. In shame-based cultures, the mechanisms are external. And so people, they don''t do wrong things out of fear of others. They don''t do wrong things out of fear of others.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'they divide it as shame based cultures and then guilt based cultures so western cultures generally tend to fall into the guilt culture and a guilt culture it cultivates within people moral components inside of themselves where if they do something wrong they feel bad about it on the inside and so one of the things a lot of people know about people in the west is that they will often find it very difficult to do wrong things without actually feeling bad in fact theres a whole industry in america to help people overcome this feeling of guilt self help books self improvement courses theres a whole industry that capitalizes on this idea of helping people overcome guilt so in guilt cultures theres an internal mechanism in shame based cultures the mechanisms are external and so people they dont do wrong things out of fear of others they dont do wrong things out of fear of others', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 26, NULL, 'which generally creates hypocrisy in cultures. And India and Pakistan and many Asian countries are very much rooted in the shame based culture where people don''t have an internal component and they''re only controlled from external factors. So when such a person is in his own country, in his own community, he finds it shameful to do certain things, but when he goes to another country, where nobody knows him it''s no longer shameful to do those same things right they start doing them and and they don''t really feel any guilt inside or any shame inside and this is why you know a lot of kids from India and Pakistan when they come to the US for studies or things like that or you know any other Western country they go completely crazy they start drinking they start partying they do drugs and even though they never did those things when they were back home It just becomes completely acceptable overnight because they''re no longer in the culture where to do those things was shameful. And also, a different country or a different city, it provides anonymity, right? When people move into different countries, into different environments, because back home, everybody knows you, right? They know your parents. So if you do anything, the entire community is going to hear about it. The entire جَمَاعَة is going to hear about it. In a different city or a different country, there is this anonymity. So it''s difficult to sense that shame, which is why guilt cultures are very important in advanced societies and shame, it works very well at the tribal level, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'which generally creates hypocrisy in cultures and india and pakistan and many asian countries are very much rooted in the shame based culture where people dont have an internal component and theyre only controlled from external factors so when such a person is in his own country in his own community he finds it shameful to do certain things but when he goes to another country where nobody knows him its no longer shameful to do those same things right they start doing them and and they dont really feel any guilt inside or any shame inside and this is why you know a lot of kids from india and pakistan when they come to the us for studies or things like that or you know any other western country they go completely crazy they start drinking they start partying they do drugs and even though they never did those things when they were back home it just becomes completely acceptable overnight because theyre no longer in the culture where to do those things was shameful and also a different country or a different city it provides anonymity right when people move into different countries into different environments because back home everybody knows you right they know your parents so if you do anything the entire community is going to hear about it the entire جماعه is going to hear about it in a different city or a different country there is this anonymity so its difficult to sense that shame which is why guilt cultures are very important in advanced societies and shame it works very well at the tribal level right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 27, NULL, 'It works quite well in small cultures, but when you move to advanced cultures like the West, it breaks down. now Islam is rooted in a shame based culture but what it does is that it transcends the shame that is rooted in people and it grounds it in shame before God so it''s not so much of an internal factor it is still an external factor right meaning it''s more shame based but it has to do with this modesty, this حَيَّا before God, before the prophet, before the angels, right? Because you have these two angels on each side recording everything that we do. So the idea is that you become aware of the spiritual presence that then prevents you from doing wrong things and this is called which is a very high station it is a station of vigilance or this constant awareness of اللَّهُs presence based on his word in the Quran indeed اللَّهُ sees everything and is aware of everything The use of this term is so beautiful. رَقِيب. رَقِيب is the jealous lover. You know, like if you''re in love with someone and that person is in love with another person, so that other person becomes your رَقِيب, right? And it is the nature of a رَقِيب that you''re constantly gonna spy on them, constantly be aware of every move they make, right? That''s a رَقِيب.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'it works quite well in small cultures but when you move to advanced cultures like the west it breaks down now islam is rooted in a shame based culture but what it does is that it transcends the shame that is rooted in people and it grounds it in shame before god so its not so much of an internal factor it is still an external factor right meaning its more shame based but it has to do with this modesty this حيا before god before the prophet before the angels right because you have these two angels on each side recording everything that we do so the idea is that you become aware of the spiritual presence that then prevents you from doing wrong things and this is called which is a very high station it is a station of vigilance or this constant awareness of اللهs presence based on his word in the quran indeed الله sees everything and is aware of everything the use of this term is so beautiful رقيب رقيب is the jealous lover you know like if youre in love with someone and that person is in love with another person so that other person becomes your رقيب right and it is the nature of a رقيب that youre constantly gonna spy on them constantly be aware of every move they make right thats a رقيب', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 28, NULL, 'the jealous lovers. اللَّهُ says that اللَّهُ is watching you like a jealous lover. He''s watching every single move of it. The metaphors, the analogies are so beautiful in the Quran. So there is this idea of shame. There''s this very interesting story over a hundred years ago when British ruled India, they say they lived a pickpocket, right? He was a Muslim, but his job was just picking pockets of people. He was a thief. In fact, he was a member of a gang who did this. There was an entire gang dedicated to just, they would go out and then they would pick pockets all day and then bring all the earnings in the night. So one day, this man, he picked the pocket of an Englishman, of a Britisher, and that wallet had a lot of money in it. So he was quite happy initially.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'the jealous lovers الله says that الله is watching you like a jealous lover hes watching every single move of it the metaphors the analogies are so beautiful in the quran so there is this idea of shame theres this very interesting story over a hundred years ago when british ruled india they say they lived a pickpocket right he was a muslim but his job was just picking pockets of people he was a thief in fact he was a member of a gang who did this there was an entire gang dedicated to just they would go out and then they would pick pockets all day and then bring all the earnings in the night so one day this man he picked the pocket of an englishman of a britisher and that wallet had a lot of money in it so he was quite happy initially', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 29, NULL, 'But then he thought of something, and then he went and returned that wallet back to that Englishman. And that night when he returned back to his gang, the leader would ask everyone how much did they earn that day. And so when his turn came, he said, "You know, I did pick the pocket of this rich Englishman, this Christian, but then I decided to return it back." And when asked why, he said, "You know, I thought that on the Day of Judgment, if Christ came to رَسُولُ اللَّهِ and said, A man of your nation picked the pocket of a man from my nation, my Prophet would have to feel shame before him on my account. And I just cannot be the reason to put my Prophet to shame before Christ. And so I returned his wallet to him."', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'but then he thought of something and then he went and returned that wallet back to that englishman and that night when he returned back to his gang the leader would ask everyone how much did they earn that day and so when his turn came he said you know i did pick the pocket of this rich englishman this christian but then i decided to return it back and when asked why he said you know i thought that on the day of judgment if christ came to رسول الله and said a man of your nation picked the pocket of a man from my nation my prophet would have to feel shame before him on my account and i just cannot be the reason to put my prophet to shame before christ and so i returned his wallet to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 30, NULL, 'Right? And I mean, this was the level of awareness of just people a hundred years ago, because they were concerned about putting our Prophet to shame. And in his last sermon to his nation, رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ, in his last خُطْبَة, one of the things he said was ............................................. put me to shame on the Day of Judgment. You know, when a classroom produces a bad result, the teacher feels shame, right? Isn''t he asked, "What''s the matter? Why did so many children fail in your class today?"', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'right and i mean this was the level of awareness of just people a hundred years ago because they were concerned about putting our prophet to shame and in his last sermon to his nation رسول الله صلي الله عليه وسلم in his last خطبه one of the things he said was put me to shame on the day of judgment you know when a classroom produces a bad result the teacher feels shame right isnt he asked whats the matter why did so many children fail in your class today', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 31, NULL, 'And our Prophet, his last request to us was, "My people, do not shame me before اللَّهُ on the Day of Judgment." There is this verse in Urdu poetry, which I love so much. It''s wojo geet tum neso na nahi, mere umre bhar kari astha. Mere dard ki tivo das tanjis at tum haseema ragai.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'and our prophet his last request to us was my people do not shame me before الله on the day of judgment there is this verse in urdu poetry which i love so much its wojo geet tum neso na nahi mere umre bhar kari astha mere dard ki tivo das tanjis at tum haseema ragai', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 32, NULL, 'So there''s the story about — I don''t know if this story is true or not, but nevertheless it demonstrates this beautiful love that this man had for his Prophet, and it was grounded in shame, because he felt ashamed at the idea of being the reason for the Prophet''s shame. So it was still an external factor, but it transcended the realm of people and it was rooted in a higher dimension. And may اللَّهُ give us all this awareness of understanding that, just having this awareness of not just being ashamed before the Prophet, but also putting the Prophet to shame before اللَّهُ, based on our — you know, this man who strived twenty-three years of his life for us, and we cannot even produce the most basic result for him.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'so theres the story about i dont know if this story is true or not but nevertheless it demonstrates this beautiful love that this man had for his prophet and it was grounded in shame because he felt ashamed at the idea of being the reason for the prophets shame so it was still an external factor but it transcended the realm of people and it was rooted in a higher dimension and may الله give us all this awareness of understanding that just having this awareness of not just being ashamed before the prophet but also putting the prophet to shame before الله based on our you know this man who strived twenty three years of his life for us and we cannot even produce the most basic result for him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 33, NULL, 'The next motivating factor for تَقْوَى is gratitude over the blessing of اللَّهُ, for all the blessings of اللَّهُ, by being obedient. So the next thing that مَلِكِ يَوْمِ ٱلدِّينِ, this verse, helps us with is obtaining تَقْوَى through the recognition of اللَّهُs blessings and demonstrating the gratitude for those blessings through obedience. So it''s this awareness that every blessing that you have, اللَّهُ gave it to you. If God gave you sight, the gratitude for that sight is to use it for the sake of اللَّهُ. If He gave you hearing, the gratitude for hearing is to use it for the sake of اللَّهُ. If He gave you physical strength, everything should be used for what it was made for.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'the next motivating factor for تقوي is gratitude over the blessing of الله for all the blessings of الله by being obedient so the next thing that ملك يوم الدين this verse helps us with is obtaining تقوي through the recognition of اللهs blessings and demonstrating the gratitude for those blessings through obedience so its this awareness that every blessing that you have الله gave it to you if god gave you sight the gratitude for that sight is to use it for the sake of الله if he gave you hearing the gratitude for hearing is to use it for the sake of الله if he gave you physical strength everything should be used for what it was made for', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 34, NULL, 'So اللهُ سُبْحَانَهُ وَتَعَالَى, He did not create His creation and desire disobedience from them. He enables disobedience, which is called خِذْلَان. So اللَّهُ is the enabler. He allows disobedience to happen, but He''s not content with it. He does not want His servants to be in a state of ingratitude, even though He allows it. So it''s very important to have gratitude for the blessings by using those blessings in obedience. That is the definition of شُكْر: to use the gifts that اللَّهُ has given you to perform things that are pleasing to اللَّهُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'so الله سبحانه وتعالي he did not create his creation and desire disobedience from them he enables disobedience which is called خذلان so الله is the enabler he allows disobedience to happen but hes not content with it he does not want his servants to be in a state of ingratitude even though he allows it so its very important to have gratitude for the blessings by using those blessings in obedience that is the definition of شكر to use the gifts that الله has given you to perform things that are pleasing to الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 35, NULL, 'The next motivating factor is knowledge. So knowledge actually provides a reason to have تَقْلَا. Now, if you notice, there is this ascension that is taking place in the motivations here.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'the next motivating factor is knowledge so knowledge actually provides a reason to have تقلا now if you notice there is this ascension that is taking place in the motivations here', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 36, NULL, 'We started off with the base levels, which is the fear of punishment and the desire for a reward. Then it transcended, it went higher into this idea of a reckoning, and then just gratitude through obedience, and now a higher realm of knowledge, which is the next motivating factor for تَقْلَا, which is based on سُورَةُ الْفَاتِحَةِ, right? Because اللَّهُ says, "Indeed the ones who are truly fearful of اللَّهُ, who have خُشُوعٌ, they are the scholars." The word خُشُوعٌ is a type of تَقْوَى that comes from a fearful awareness of God through knowledge. It comes from awe before God that is based on knowledge of who اللَّهُ is. And it is amongst His creation, amongst His servants, it is the عُلَمَاء that have this knowledge.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'we started off with the base levels which is the fear of punishment and the desire for a reward then it transcended it went higher into this idea of a reckoning and then just gratitude through obedience and now a higher realm of knowledge which is the next motivating factor for تقلا which is based on سوره الفاتحه right because الله says indeed the ones who are truly fearful of الله who have خشوع they are the scholars the word خشوع is a type of تقوي that comes from a fearful awareness of god through knowledge it comes from awe before god that is based on knowledge of who الله is and it is amongst his creation amongst his servants it is the علماء that have this knowledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 37, NULL, 'And then the magnification of اللَّهُs majesty, right? And this is called مَقَامُ الْهَيْبَةِ, which is the station of awe, and which is a higher station than, you know, just even just basic gratitude. Because it comes from this awe that is produced by the knowledge of who اللَّهُ is, right? It''s called مَقَامُ الْهَيْبَةِ. The مُحِبٌّ is someone who has this awe for a greater, like for the Sultan, right? There''s an awe that goes with it.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'and then the magnification of اللهs majesty right and this is called مقام الهيبه which is the station of awe and which is a higher station than you know just even just basic gratitude because it comes from this awe that is produced by the knowledge of who الله is right its called مقام الهيبه the محب is someone who has this awe for a greater like for the sultan right theres an awe that goes with it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 38, NULL, 'so you know when you go visit a Sultan, there''s a whole way that they have made things in order to instill this awe in your hearts for him. So for instance, if you go to the White House to meet the President, you''ll see these Marine guards with guns standing outside that have these big bayonets. I mean, there''s a reason why the bayonets are there. I mean, they could have just had the guns, right? Why do you need those bayonets? But the bayonet is there to instill this سُورَةُ الْفَاتِحَةِ, right? Bayonet is this little sword-like thing, this knife-like thing that is attached to the gun, to the barrel of the gun. Why do they need that? In case of an event, they''ll probably shoot rather than stab, but why is there that knife? Because it''s meant to instill this سُورَةُ الْفَاتِحَةِ in our hearts. It''s the same with just swords outside the palace of a king in Arabia. It creates سُورَةُ الْفَاتِحَةِ. And then you go in and then there are all these long corridors made of marble and this expensive stuff, and they make you walk through all of these magnificent corridors with all of these elegant decorations. Why? The purpose is to humble you, because you''re about to meet the Sultan, you''re about to meet the President, the Prime Minister, the King. And so this whole experience that they make you go through is to produce this kind of humility within your heart, to put you in your place, you see?', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'so you know when you go visit a sultan theres a whole way that they have made things in order to instill this awe in your hearts for him so for instance if you go to the white house to meet the president youll see these marine guards with guns standing outside that have these big bayonets i mean theres a reason why the bayonets are there i mean they could have just had the guns right why do you need those bayonets but the bayonet is there to instill this سوره الفاتحه right bayonet is this little sword like thing this knife like thing that is attached to the gun to the barrel of the gun why do they need that in case of an event theyll probably shoot rather than stab but why is there that knife because its meant to instill this سوره الفاتحه in our hearts its the same with just swords outside the palace of a king in arabia it creates سوره الفاتحه and then you go in and then there are all these long corridors made of marble and this expensive stuff and they make you walk through all of these magnificent corridors with all of these elegant decorations why the purpose is to humble you because youre about to meet the sultan youre about to meet the president the prime minister the king and so this whole experience that they make you go through is to produce this kind of humility within your heart to put you in your place you see', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 39, NULL, 'And no matter where you go, they all have the same type of rituals. Whether you go to the Queen''s palace or you go to the White House or to go to the Sultan''s palace, they''re all designed to create this awe in your heart for the Sultan, which is important. Because if the Sultan does not generate this awe, then why should people obey him in the first place? And this is also why traditionally عُلَمَاء dressed a certain way. This is why رَسُولُ اللَّهِ encouraged عُلَمَاء to dress in this certain particular way so that it instills this awe, this respect in the hearts of the audience. Otherwise, why is anybody going to listen to them? This is why we find the كِسْوَة on the الْكَعْبَة, that black cloth, because it''s a sanctified place, right? That كِسْوَة, it illustrates the magnificence of the الْكَعْبَة. It creates this awe within our hearts. So it''s a very important aspect of تَعْظِيم. And then the final stage, you know, is صِدْقُ الْمَحَبَّةِ, the sincerity in one''s love for God, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'and no matter where you go they all have the same type of rituals whether you go to the queens palace or you go to the white house or to go to the sultans palace theyre all designed to create this awe in your heart for the sultan which is important because if the sultan does not generate this awe then why should people obey him in the first place and this is also why traditionally علماء dressed a certain way this is why رسول الله encouraged علماء to dress in this certain particular way so that it instills this awe this respect in the hearts of the audience otherwise why is anybody going to listen to them this is why we find the كسوه on the الكعبه that black cloth because its a sanctified place right that كسوه it illustrates the magnificence of the الكعبه it creates this awe within our hearts so its a very important aspect of تعظيم and then the final stage you know is صدق المحبه the sincerity in ones love for god right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 40, NULL, 'It gives this ultimate form of تَقْوَى, which is the highest motivating factor for تَقْوَى. And this is, you know, one of the poets, محْمُودٌ الوَرَّاقُ, he said, "You disobey اللَّهُ but then you claim that you love Him? This is impossible and a very strange type of logic that I don''t understand. Had your love been sincere, you would have been obedient." Because a lover always obeys his or her beloved. So the nature of love is that you want to obey the one that you love. Then he says, a woman asked about the state of the one who was in this burning passion for her, right? The عَاشِقٌ is the one who is in this burning passion for the beloved. So she''s asking this man about her lover, and she says, "So for the sake of God, tell me about his state. And don''t stint in your description and don''t exaggerate." In other words, I want to hear the truth. So she asks this man, tell me about his love. Tell me what kind of love does he have for me. And so this man says, if this man knew that he would die from thirst, and if you said don''t touch that water, he wouldn''t touch it.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'it gives this ultimate form of تقوي which is the highest motivating factor for تقوي and this is you know one of the poets محمود الوراق he said you disobey الله but then you claim that you love him this is impossible and a very strange type of logic that i dont understand had your love been sincere you would have been obedient because a lover always obeys his or her beloved so the nature of love is that you want to obey the one that you love then he says a woman asked about the state of the one who was in this burning passion for her right the عاشق is the one who is in this burning passion for the beloved so shes asking this man about her lover and she says so for the sake of god tell me about his state and dont stint in your description and dont exaggerate in other words i want to hear the truth so she asks this man tell me about his love tell me what kind of love does he have for me and so this man says if this man knew that he would die from thirst and if you said dont touch that water he wouldnt touch it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 41, NULL, 'So if your lover is gonna die of thirst and you said don''t touch that drink of water, he won''t touch it. He''d rather die than disobey you. So the point of that, what the poet is emphasizing, is that it is the nature, obedience is the nature of love. The very nature of love is to be obedient. So the more you love God, the more you will obey God. And that''s the idea. And so the عُلَمَاء have stated these, think of it like a staircase, right? And think of all of these motivating factors as rungs. So it begins with the fear of punishment, then the next step is desiring the rewards, then it is having this concept of reckoning, this accountability before God, right? And then shame, the next level is having shame before God, His prophet and His angels. Then the next level is gratitude, then the next is knowledge, and finally you reach the final stage of love, which is sincere love manifested through obedience.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'so if your lover is gonna die of thirst and you said dont touch that drink of water he wont touch it hed rather die than disobey you so the point of that what the poet is emphasizing is that it is the nature obedience is the nature of love the very nature of love is to be obedient so the more you love god the more you will obey god and thats the idea and so the علماء have stated these think of it like a staircase right and think of all of these motivating factors as rungs so it begins with the fear of punishment then the next step is desiring the rewards then it is having this concept of reckoning this accountability before god right and then shame the next level is having shame before god his prophet and his angels then the next level is gratitude then the next is knowledge and finally you reach the final stage of love which is sincere love manifested through obedience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 42, NULL, 'So it''s a very, you know, it''s a very beautiful and a very powerful verse, مَلِكِ يَوْمِ ٱلدِّينِ, and its purpose is to motivate us towards تَقْوَى. And so you have, you know, with ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎, ٱلرَّحْمَنِ ٱلرَّحِيمِ, مَلِكِ يَوْمِ ٱلدِّينِ, from these three verses, we get a complete picture of who اللَّهُ is. Right? So it provides a complete description, a very concise description of who اللَّهُ is.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'so its a very you know its a very beautiful and a very powerful verse ملك يوم الدين and its purpose is to motivate us towards تقوي and so you have you know with الحمد لله رب العلمين الرحمن الرحيم ملك يوم الدين from these three verses we get a complete picture of who الله is right so it provides a complete description a very concise description of who الله is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 43, NULL, 'The next, the following verses that we will study in future sessions, so these next verses, they give us an understanding of what اللَّهُ wants from us and what we want from اللَّهُ. And so this is how the سُورَةُ الْفَاتِحَةِ is split into these two parts. You have the first, these beginning three verses, which tells us in third person who اللَّهُ is. And then, from there, it begins this transition of what we are asking اللَّهُ for. So, إِن شَآءَ ٱللَّهُ, we''ll explore those verses in the following sessions, إِن شَآءَ ٱللَّهُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'the next the following verses that we will study in future sessions so these next verses they give us an understanding of what الله wants from us and what we want from الله and so this is how the سوره الفاتحه is split into these two parts you have the first these beginning three verses which tells us in third person who الله is and then from there it begins this transition of what we are asking الله for so ان شاء الله well explore those verses in the following sessions ان شاء الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'motivating factors for piety', 'Motivating Factors For Piety', 44, NULL, 'وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتِمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ، وَعَلَى أَخِيهِ وَوَصِيِّهِ عَلِيٍّ النَّبِيِّ طَالِبٍ شَرَفِ الْوَصِيِّينَ، وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِمَا الطَّيِّبِينَ الطَّاهِرِينَ، وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ. الْفَاتِحَة', '', 'وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتِمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ، وَعَلَى أَخِيهِ وَوَصِيِّهِ عَلِيٍّ النَّبِيِّ طَالِبٍ شَرَفِ الْوَصِيِّينَ، وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِمَا الطَّيِّبِينَ الطَّاهِرِينَ، وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ الْفَاتِحَة', NULL, NULL, NULL, 'surah al fateha motivating factors for piety', 'واخر دعوانا ان الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد خاتم النبيين وسيد المرسلين وعلي اخيه ووصيه علي النبي طالب شرف الوصيين وعلي الايمه من ذريتهما الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه', 'واخر دعوانا ان الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد خاتم النبيين وسيد المرسلين وعلي اخيه ووصيه علي النبي طالب شرف الوصيين وعلي الايمه من ذريتهما الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 0, NULL, 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ. رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي. السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ.', '', 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ', NULL, NULL, NULL, 'surah al fateha worship and assistance', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي السلام عليكم ورحمه الله وبركاته', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي السلام عليكم ورحمه الله وبركاته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 1, NULL, 'We completed the linguistic study of the first four verses of سُورَةُ الْفَاتِحَةِ. So now we have, after giving us an introduction of who اللَّهُ is through the first, or rather the beginning verses, then he says, ‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‎. It is only you that we worship or willingly enslave ourselves to. And it is only you that we seek help from. Now here, there''s something really interesting in this verse. If you notice, there is a complete change of tone over here. So the previous verses, they were all in the third person, right? They were informational. So ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, begin with the name of اللَّهُ, extremely merciful, intensely merciful. All praise and glory belongs to اللَّهُ, who is the master of all universes or everything that is known, the abundant, the abundantly merciful, the consistently merciful, owner of a time when the debt of submission falls due. So these are all statements. If you notice, they''re all in the third person, in which اللَّهُ is just basically informing us about who He is.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'we completed the linguistic study of the first four verses of سوره الفاتحه so now we have after giving us an introduction of who الله is through the first or rather the beginning verses then he says اياك نعبد واياك نستعين it is only you that we worship or willingly enslave ourselves to and it is only you that we seek help from now here theres something really interesting in this verse if you notice there is a complete change of tone over here so the previous verses they were all in the third person right they were informational so بسم الله الرحمن الرحيم begin with the name of الله extremely merciful intensely merciful all praise and glory belongs to الله who is the master of all universes or everything that is known the abundant the abundantly merciful the consistently merciful owner of a time when the debt of submission falls due so these are all statements if you notice theyre all in the third person in which الله is just basically informing us about who he is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 2, NULL, 'But then, He suddenly changes the tone and He turns it into a second person conversation. He turns it into a دُعَاء, as if we are now speaking directly with Him. It is only you we worship and it is only you we turn to for help. The tone of this verse is not that اللَّهُ is the one that we worship and اللَّهُ is the one that we turn to for help. It''s not in the third person. It''s as if we are in direct conversation with اللَّهُ at this point. And this is a beautiful linguistic tool in the Arabic language that is called الِٱلْتِفَاتُ, which is a sudden change in the pronoun of the speaker, or the one that is being spoken to. So اللَّهُ constantly changes the conversation in the Quran from third person to first person, then to second person, and then back to third person, right? And you can see this in almost every single سُورَةُ الْفَاتِحَةِ. He sometimes refers to Himself using I, sometimes He uses we, right? Sometimes he uses him. These are all linguistic tools to not only keep the reader alert and awake, but also a mechanism to highlight what اللَّهُ wants from us. So in the case of سُورَةُ الْفَاتِحَةِ, you can see that the tone now suddenly changes to a دُعَاء, it changes to a supplication. It is only you we worship and it is only you we turn to for help.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'but then he suddenly changes the tone and he turns it into a second person conversation he turns it into a دعاء as if we are now speaking directly with him it is only you we worship and it is only you we turn to for help the tone of this verse is not that الله is the one that we worship and الله is the one that we turn to for help its not in the third person its as if we are in direct conversation with الله at this point and this is a beautiful linguistic tool in the arabic language that is called الالتفات which is a sudden change in the pronoun of the speaker or the one that is being spoken to so الله constantly changes the conversation in the quran from third person to first person then to second person and then back to third person right and you can see this in almost every single سوره الفاتحه he sometimes refers to himself using i sometimes he uses we right sometimes he uses him these are all linguistic tools to not only keep the reader alert and awake but also a mechanism to highlight what الله wants from us so in the case of سوره الفاتحه you can see that the tone now suddenly changes to a دعاء it changes to a supplication it is only you we worship and it is only you we turn to for help', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 3, NULL, 'And who is the one saying that? It is you and I that are saying that. So we are now in direct conversation with اللَّهُ. And this style of switching suddenly from third person to second person is a means of letting us know that this is in fact what اللَّهُ wants from us. You understand? When we say ... because this is all revelation coming from اللَّهُ, right? We are not the authors of Quran. So this is all revelation coming from اللَّهُ. So now imagine a book like Quran, something so meaningful. How is اللَّهُ to have this conversation with us where suddenly now He wants us, while He''s describing Himself, He wants us to know what He wants from us. So by changing his tone to ‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‎, اللَّهُ is expressing His intention of wanting us to say that we willingly worship you and we freely give up our freedom and desires to become your slaves.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'and who is the one saying that it is you and i that are saying that so we are now in direct conversation with الله and this style of switching suddenly from third person to second person is a means of letting us know that this is in fact what الله wants from us you understand when we say because this is all revelation coming from الله right we are not the authors of quran so this is all revelation coming from الله so now imagine a book like quran something so meaningful how is الله to have this conversation with us where suddenly now he wants us while hes describing himself he wants us to know what he wants from us so by changing his tone to اياك نعبد واياك نستعين الله is expressing his intention of wanting us to say that we willingly worship you and we freely give up our freedom and desires to become your slaves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 4, NULL, 'In other words, اللَّهُ is not commanding us into slavery by saying اِسْتَعْبَدُوا أَنْفُسَكُمْ لِ, enslave yourselves to Me. Instead, He wants us to say إِيَّاكَ نَعْبُدُ, it is only you that we want to worship. In other words, اللَّهُ is asking us to reach this conclusion of our وُضِيءَ on our own, through the study of the previous three verses. The idea is that when we truly understand the meaning of ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎, when we truly understand the meaning of ٱلرَّحْمَنِ ٱلرَّحِيمِ, and when we truly understand the meaning of مَلِكِ يَوْمِ ٱلدِّينِ, and when we recognize what an incredibly loving, merciful, and powerful رَبِّ اللَّهُ is, our natural and logical conclusion to that understanding has to be . You see? Our natural response has to be a willing desire of submission. So the idea here is that if you haven''t reached that conclusion all by yourself, then don''t say it. So اللَّهُ is not forcing us to say it. This is us saying it to اللَّهُ out of our own free will. So I wanted to start the explanation of this verse by making that distinction.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'in other words الله is not commanding us into slavery by saying استعبدوا انفسكم ل enslave yourselves to me instead he wants us to say اياك نعبد it is only you that we want to worship in other words الله is asking us to reach this conclusion of our وضيء on our own through the study of the previous three verses the idea is that when we truly understand the meaning of الحمد لله رب العلمين when we truly understand the meaning of الرحمن الرحيم and when we truly understand the meaning of ملك يوم الدين and when we recognize what an incredibly loving merciful and powerful رب الله is our natural and logical conclusion to that understanding has to be you see our natural response has to be a willing desire of submission so the idea here is that if you havent reached that conclusion all by yourself then dont say it so الله is not forcing us to say it this is us saying it to الله out of our own free will so i wanted to start the explanation of this verse by making that distinction', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 5, NULL, 'Now let''s look at this verse linguistically. The first word is إِيَّاكَ, which means only you. So, linguistically, إِيَّاكَ excludes everything and everyone except the object of the conversation. So, think of it like a clause of exclusivity. So, what we''re saying is you, only you, and no one else but you, إِيَّاكَ.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'now lets look at this verse linguistically the first word is اياك which means only you so linguistically اياك excludes everything and everyone except the object of the conversation so think of it like a clause of exclusivity so what were saying is you only you and no one else but you اياك', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 6, NULL, 'The next word is نَعْبُدُ, which means we worship. And نَعْبُدُ comes from the word عِبَادَة, which we all know means worship, which in turn comes from the root word سُورَةُ الْفَاتِحَةِ, which means slave. Now, what is the connection between worship and slavery? What''s the relationship there? The relationship is that worship is a demonstration of one''s slavery. Worship or عِبَادَة is a demonstration of one''s acceptance of slavery. It is a proof of one''s slavery. It is an act of devotion and dedication that establishes one''s slavery.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'the next word is نعبد which means we worship and نعبد comes from the word عباده which we all know means worship which in turn comes from the root word سوره الفاتحه which means slave now what is the connection between worship and slavery whats the relationship there the relationship is that worship is a demonstration of ones slavery worship or عباده is a demonstration of ones acceptance of slavery it is a proof of ones slavery it is an act of devotion and dedication that establishes ones slavery', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 7, NULL, 'So I''ll give you a very basic example. If I stood on the top of a building and I screamed at the top of my lungs for two hours that, you know, I''m a slave of اللَّهُ, I''m a slave of اللَّهُ, I''m a slave of اللَّهُ, but then when it''s time for prayer, if I do not pray, I can say that I''m a slave of اللَّهُ all day long, but did I back it up? Did I prove that statement? No.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'so ill give you a very basic example if i stood on the top of a building and i screamed at the top of my lungs for two hours that you know im a slave of الله im a slave of الله im a slave of الله but then when its time for prayer if i do not pray i can say that im a slave of الله all day long but did i back it up did i prove that statement no', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 8, NULL, 'So our worship, our عِبَادَة, is actually proof and evidence of the fact that we are in fact the slaves of اللَّهُ. Otherwise it''s just an empty claim. That''s how these two words are connected together. So it means it is only you and no one else but you that we worship or willingly enslave ourselves to.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'so our worship our عباده is actually proof and evidence of the fact that we are in fact the slaves of الله otherwise its just an empty claim thats how these two words are connected together so it means it is only you and no one else but you that we worship or willingly enslave ourselves to', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 9, NULL, 'Now, what''s really powerful about this concept is that by desiring this enslavement of اللَّهُ, we are essentially desiring freedom from everything else. Becoming the slaves of اللَّهُ provides freedom from every other slavery of this world. So essentially what we''re recognizing through إِيَّاكَ نَعْبُدُ is that we do not want to become the slave of this دُنْيَا. We want to become the slave of اللَّهُ and in the process of that slavery, through the process of that slavery, we want to free ourselves from everything else. So by recognizing our أُمُّ الْقُرْآنِ to اللَّهُ, what we get is the حُرِّيَة, which is true freedom. In completing the أُمُّ الْقُرْآنِ to اللَّهُ, we are no longer slaves to ourselves and that''s a truly free person. If I can control myself, then I''m a slave to myself. Somebody can say, I''m free, I''m free.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'now whats really powerful about this concept is that by desiring this enslavement of الله we are essentially desiring freedom from everything else becoming the slaves of الله provides freedom from every other slavery of this world so essentially what were recognizing through اياك نعبد is that we do not want to become the slave of this دنيا we want to become the slave of الله and in the process of that slavery through the process of that slavery we want to free ourselves from everything else so by recognizing our ام القران to الله what we get is the حريه which is true freedom in completing the ام القران to الله we are no longer slaves to ourselves and thats a truly free person if i can control myself then im a slave to myself somebody can say im free im free', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 10, NULL, 'But then when the food shows up, they just cannot stop themselves. And that''s not freedom as far as the Muslim is concerned, right? He''s not عَبْدُ اللهِ at that point. He''s عَبْدُ الْهَوَى. He''s a slave of his own passions. So عَبْدُ اللهِ, the slave of اللَّهُ, is that when the situation arises, he has تَقْوَى of اللَّهُ. He has that mindfulness of the presence of اللَّهُ. It''s not that the temptation goes away, right? The desire is still there because we''re all humans, so the شَهْوَة might still be there, but the slave of اللَّهُ, the عَبْدُ اللهِ, can control it because he''s not the slave of his passion, he is the سَيِّد of it, right? He''s not the عَبْدُ of his passion, he is the سَيِّد of his passion, he is the master of it. That is someone who is really free, you know, that''s الدَّهْرُ. But this level of mastery can only be attained through the slavery of اللَّهُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'but then when the food shows up they just cannot stop themselves and thats not freedom as far as the muslim is concerned right hes not عبد الله at that point hes عبد الهوي hes a slave of his own passions so عبد الله the slave of الله is that when the situation arises he has تقوي of الله he has that mindfulness of the presence of الله its not that the temptation goes away right the desire is still there because were all humans so the شهوه might still be there but the slave of الله the عبد الله can control it because hes not the slave of his passion he is the سيد of it right hes not the عبد of his passion he is the سيد of his passion he is the master of it that is someone who is really free you know thats الدهر but this level of mastery can only be attained through the slavery of الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 11, NULL, 'So, you know, there are many kinds of slaveries in that respect, right? The tongue is the same, right? There are so many people who just can''t stop backbiting. They just can''t stop gossiping. I mean, you can tell them, you can point it out to them a million times, but they just can''t stop. I mean, it''s just amazing. And in most cases, they''re not even aware of it. I mean, I''m sure I do things like that all the time, but because this just exists within us, this inability to control our tongues, to speak badly about others, to say things that we really shouldn''t be saying. And I''m just guilty as the next person. But this is the human weakness that people find it hard to control. We find it hard to control these things. So learning to control the tongue is also a major thing in Islam.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'so you know there are many kinds of slaveries in that respect right the tongue is the same right there are so many people who just cant stop backbiting they just cant stop gossiping i mean you can tell them you can point it out to them a million times but they just cant stop i mean its just amazing and in most cases theyre not even aware of it i mean im sure i do things like that all the time but because this just exists within us this inability to control our tongues to speak badly about others to say things that we really shouldnt be saying and im just guilty as the next person but this is the human weakness that people find it hard to control we find it hard to control these things so learning to control the tongue is also a major thing in islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 12, NULL, 'So when we say "إِيَّاكَ نَعْبُدُ," it is only you we desire to enslave ourselves to, what''s implicit in that دُعَاء is that we are essentially desiring freedom from the enslavement of everything else. Everything that is دُنْيَا: money, houses, cars, children, food, these branded clothes, friends, relatives. I mean, there are millions and millions of shackles that we wear around ourselves, and you know, and we don''t even realize it. And what the slavery of اللَّهُ does is that it frees us from all those shackles.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'so when we say اياك نعبد it is only you we desire to enslave ourselves to whats implicit in that دعاء is that we are essentially desiring freedom from the enslavement of everything else everything that is دنيا money houses cars children food these branded clothes friends relatives i mean there are millions and millions of shackles that we wear around ourselves and you know and we dont even realize it and what the slavery of الله does is that it frees us from all those shackles', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 13, NULL, 'The next thing that I want to point out about this verse is the fact that اللَّهُ سُبْحَانَهُ وَتَعَالَى, he uses the plural form here. He says, "إِيَّاكَ نَعْبُدُ," it is only you we worship. Now, let me ask you a question. The majority of the time when we pray, are we praying by ourselves or in a group? Generally, we''re praying by ourselves, right? So then, can I say when I''m praying by myself, can I just say, "إِيَّاكَ أَعْبُدُ," it is only you that I worship? I mean, wouldn''t that be more logical?', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'the next thing that i want to point out about this verse is the fact that الله سبحانه وتعالي he uses the plural form here he says اياك نعبد it is only you we worship now let me ask you a question the majority of the time when we pray are we praying by ourselves or in a group generally were praying by ourselves right so then can i say when im praying by myself can i just say اياك اعبد it is only you that i worship i mean wouldnt that be more logical', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 14, NULL, 'So then can I change it to the singular form when I''m just praying by myself? No, I cannot. It''s not permissible. It''s not allowed. I cannot change it. I have to use the plural form. So that''s very interesting, right? Why did اللَّهُ fix the statement in the plural form? Scholars explain that by fixing the statement in the plural form, what اللَّهُ is emphasizing is this importance of unity. اللَّهُ is emphasizing this concept of unity, that even when I pray by myself, I do not speak just for myself. I speak on behalf of the whole أُمَّة, on behalf of my entire community.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'so then can i change it to the singular form when im just praying by myself no i cannot its not permissible its not allowed i cannot change it i have to use the plural form so thats very interesting right why did الله fix the statement in the plural form scholars explain that by fixing the statement in the plural form what الله is emphasizing is this importance of unity الله is emphasizing this concept of unity that even when i pray by myself i do not speak just for myself i speak on behalf of the whole امه on behalf of my entire community', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 15, NULL, 'I say, ... because the ultimate way to establish unity is through the worship of اللَّهُ. That''s why they say that a family that prays together stays together, a community that prays together sticks together. So the message in this verse and the following verses is to be united, to stay united as one unit, as one family, one community, one nation. So اللَّهُ has forced this idea of this togetherness, you know. So when I''m doing my prayers, I am just naturally praying for you. When you''re doing your prayer, you''re praying for me, even when you''re praying alone. So this plural form, this unity, this, the sense of brotherhood, the sense of مِلَّة, أُمَّة, right, all of this is just present in this plural form of نَعْبُدُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'i say because the ultimate way to establish unity is through the worship of الله thats why they say that a family that prays together stays together a community that prays together sticks together so the message in this verse and the following verses is to be united to stay united as one unit as one family one community one nation so الله has forced this idea of this togetherness you know so when im doing my prayers i am just naturally praying for you when youre doing your prayer youre praying for me even when youre praying alone so this plural form this unity this the sense of brotherhood the sense of مله امه right all of this is just present in this plural form of نعبد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 16, NULL, 'So we say "إِيَّاكَ نَعْبُدُ," it is you that we worship. And the next thing we say is "إِيَّاكَ نَسْتَعِينُ," it is only you that we seek assistance from. Now the word نَسْتَعِينُ, it comes from اِسْتِعَانَة, which in turn then comes from the root word عَوْن, and it means assistance. Now, there are many other words in Arabic for help, right? There is one common word is نَصْر. There is also مُسَاعَدَة, there is نَجْدَة. There are all these different kinds of help. But these are all different kinds of help.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'so we say اياك نعبد it is you that we worship and the next thing we say is اياك نستعين it is only you that we seek assistance from now the word نستعين it comes from استعانه which in turn then comes from the root word عون and it means assistance now there are many other words in arabic for help right there is one common word is نصر there is also مساعده there is نجده there are all these different kinds of help but these are all different kinds of help', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 17, NULL, 'So نَصْر is a type of help that has a greater sense of urgency to it. نَصْر is the kind of help that we ask for. It''s the kind of help that we seek in emergency situations. Major, major things, right? When the help of اللَّهُ arrives at the most difficult of times, understand that victory will be near. When the help of اللَّهُ arrives and you are victorious in battles, right? Again, major help. Keep us steadfast and help us over the nation of disbelievers. Major emergency situation, major challenge. So when I''m in a situation where I cannot do anything to get myself out of that, then I need somebody else to do it for me. And in those kind of emergency situations, the word نَصْر would be used. The word عَوْن is used for small matters. It''s the help that I need in little, little things, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'so نصر is a type of help that has a greater sense of urgency to it نصر is the kind of help that we ask for its the kind of help that we seek in emergency situations major major things right when the help of الله arrives at the most difficult of times understand that victory will be near when the help of الله arrives and you are victorious in battles right again major help keep us steadfast and help us over the nation of disbelievers major emergency situation major challenge so when im in a situation where i cannot do anything to get myself out of that then i need somebody else to do it for me and in those kind of emergency situations the word نصر would be used the word عون is used for small matters its the help that i need in little little things right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 18, NULL, 'So, I need a glass of water. I can get up and get it myself, but if you''re just right next to the cooler, I can say, "Hey, can you get me a glass of water?" And if you bring me that glass of water, what you did is you assisted me, right? That''s عَوْن. It''s seeking assistance in daily tasks, little, little things. So why is this distinction made in سُورَةُ الْفَاتِحَةِ where the word عَوْن is used instead of نَصْر? It''s because a true believer is someone who turns to اللَّهُ سُبْحَانَهُ وَتَعَالَى all the time. That''s the quality of a true believer. He turns to اللَّهُ for everything, for all the little, little things in his life, you understand. He doesn''t just think of اللَّهُ in major situations. He remembers اللَّهُ in the little, little things all throughout his day, you know, like a lover that remembers the beloved all the time.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'so i need a glass of water i can get up and get it myself but if youre just right next to the cooler i can say hey can you get me a glass of water and if you bring me that glass of water what you did is you assisted me right thats عون its seeking assistance in daily tasks little little things so why is this distinction made in سوره الفاتحه where the word عون is used instead of نصر its because a true believer is someone who turns to الله سبحانه وتعالي all the time thats the quality of a true believer he turns to الله for everything for all the little little things in his life you understand he doesnt just think of الله in major situations he remembers الله in the little little things all throughout his day you know like a lover that remembers the beloved all the time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 19, NULL, 'And this is exactly what we find in the daily routine of our Prophet. He woke up in the morning. What was the first thing he did? The second he woke up, he praised اللَّهُ. "الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَ مَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ" He went to the restroom to relieve himself. "أَعُوذُ بِاللَّهِ مِنَ الْخُبْثِ وَالْخَبَائِثِ" he sought the protection of اللَّهُ from شَيْطَان. Right? He got on his horse.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'and this is exactly what we find in the daily routine of our prophet he woke up in the morning what was the first thing he did the second he woke up he praised الله الحمد لله الذي احيانا بعد ما اماتنا واليه النشور he went to the restroom to relieve himself اعوذ بالله من الخبث والخبايث he sought the protection of الله from شيطان right he got on his horse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 20, NULL, 'سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ Before he would start eating his food, ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ As soon as he finished eating his food, ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎ He stepped out of his house to leave somewhere. بِسْمِ اللَّهِ تَوَكَّلْتُ عَلَى اللَّهِ وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ It is used for seeking assistance of اللَّهُ constantly, in even in the most tiny matters. So the first reason for using our own is this idea of constant remembrance.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'سبحان الذي سخر لنا هذا وما كنا له مقرنين وانا الي ربنا لمنقلبون before he would start eating his food بسم الله الرحمن الرحيم as soon as he finished eating his food الحمد لله رب العلمين he stepped out of his house to leave somewhere بسم الله توكلت علي الله ولا حول ولا قوه الا بالله العلي العظيم it is used for seeking assistance of الله constantly in even in the most tiny matters so the first reason for using our own is this idea of constant remembrance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 21, NULL, 'The second reason we constantly seek His assistance is because we recognize that we are not the ideal slaves, right? We understand that we are weak human beings who desperately require assistance every step of the way, in every little thing that we do. Because we are dominated by our desires of this world. We are challenged by innumerable distractions every single waking moment of our lives. So we are constantly walking this slippery slope. So we know that it''s not going to be easy to maintain our عَبْدِيَّة, because we are surrounded by the worst four enemies that are constantly working against us.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'the second reason we constantly seek his assistance is because we recognize that we are not the ideal slaves right we understand that we are weak human beings who desperately require assistance every step of the way in every little thing that we do because we are dominated by our desires of this world we are challenged by innumerable distractions every single waking moment of our lives so we are constantly walking this slippery slope so we know that its not going to be easy to maintain our عبديه because we are surrounded by the worst four enemies that are constantly working against us', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 22, NULL, 'First is our نَفْس, our soul that is weak to begin with. Then we have this دُنْيَا, the temptations of this world. Then we have هَوَىٰ, which is our overwhelming desires and passions. And then there is شَيْطَان himself. So we are surrounded on all sides by these powerful enemies. And we recognize that, and so we admit that our أَبُو ضِيَاء and our servitude is not going to be worthy of رَبُّ الْعَالَمِينَ. But we''re willing to try, right? We''re still willing to try. And in that trying, we''re going to need our master''s assistance in every little thing that we do. So when we fail over and over again, we will still constantly need اللَّهُ to pick us up, because only He can protect and assist us. So, ‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‎. It is only You that we worship, but then it is only You that we seek assistance from in every little thing that we do. So the statement is made up of these two parts.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'first is our نفس our soul that is weak to begin with then we have this دنيا the temptations of this world then we have هوي which is our overwhelming desires and passions and then there is شيطان himself so we are surrounded on all sides by these powerful enemies and we recognize that and so we admit that our ابو ضياء and our servitude is not going to be worthy of رب العالمين but were willing to try right were still willing to try and in that trying were going to need our masters assistance in every little thing that we do so when we fail over and over again we will still constantly need الله to pick us up because only he can protect and assist us so اياك نعبد واياك نستعين it is only you that we worship but then it is only you that we seek assistance from in every little thing that we do so the statement is made up of these two parts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 23, NULL, 'إِيَّاكَ نَعْبُدُ is making that willing commitment to اللَّهُ. That yes, I do want to become your slave so that I can be free from everything else. I desire freedom. The reason I am making this commitment to you is because I desire freedom. That''s إِيَّاكَ نَعْبُدُ. And إِيَّاكَ نَسْتَعِينُ is asking Him for assistance in getting that job done. So that''s the second reason. And the third reason is that we seek the closeness of اللَّهُ. We desire the قُرْب of اللَّهُ. This is also the reason why this conversation switched from third person to second person, right? Because when we say we are now directly speaking with اللَّهُ. So it''s a more intimate conversation.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'اياك نعبد is making that willing commitment to الله that yes i do want to become your slave so that i can be free from everything else i desire freedom the reason i am making this commitment to you is because i desire freedom thats اياك نعبد and اياك نستعين is asking him for assistance in getting that job done so thats the second reason and the third reason is that we seek the closeness of الله we desire the قرب of الله this is also the reason why this conversation switched from third person to second person right because when we say we are now directly speaking with الله so its a more intimate conversation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 24, NULL, 'And we''re using that intimate conversation for two things, for worship and for assistance. So, what scholars tell us is that what this verse teaches us is that we all want to be near and we all want to be dear to اللَّهُ. We all want to be loved by اللَّهُ. We want to be His beloved. Right? But the ultimate way to establish that nearness, that love of اللَّهُ, is by worshiping Him and by calling out to Him for assistance. That''s why in a حَدِيثٌ قُدْسِيٌّ اللَّهُ very explicitly says: my slave does not get closer to me more so than by doing what I have told him to do, and that is the five times daily prayer. So if you want to be close to اللَّهُ, pray five times a day and keep calling Him for assistance, because there is no better time to call Him for assistance than with prayer.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'and were using that intimate conversation for two things for worship and for assistance so what scholars tell us is that what this verse teaches us is that we all want to be near and we all want to be dear to الله we all want to be loved by الله we want to be his beloved right but the ultimate way to establish that nearness that love of الله is by worshiping him and by calling out to him for assistance thats why in a حديث قدسي الله very explicitly says my slave does not get closer to me more so than by doing what i have told him to do and that is the five times daily prayer so if you want to be close to الله pray five times a day and keep calling him for assistance because there is no better time to call him for assistance than with prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 25, NULL, 'The next topic that I want to talk about is the sequence, the sequence in which these two things are used, these two words are used, right? So if you look at it, the first thing that is mentioned is عِبَادَة. Worship is mentioned first, and that is followed by أَعُوذُ, which is the assistance of اللَّهُ. Now why is that important? Because the sequence that you find in the Quran between things, that is never coincidental, right? It always has a very specific purpose. It''s always very precise, because this is divine, this is divine revelation. So like nothing is just arbitrary in the Quran. So why is worship mentioned before seeking assistance? Because the best way to seek the help and the assistance from اللَّهُ, the best way to ask اللَّهُ for anything and everything that we may need or want, is to ask after worshipping Him.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'the next topic that i want to talk about is the sequence the sequence in which these two things are used these two words are used right so if you look at it the first thing that is mentioned is عباده worship is mentioned first and that is followed by اعوذ which is the assistance of الله now why is that important because the sequence that you find in the quran between things that is never coincidental right it always has a very specific purpose its always very precise because this is divine this is divine revelation so like nothing is just arbitrary in the quran so why is worship mentioned before seeking assistance because the best way to seek the help and the assistance from الله the best way to ask الله for anything and everything that we may need or want is to ask after worshipping him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 26, NULL, 'عَبْدُ اللهِ ibn Masood, he would tell his students, "Save your needs and your necessities for the obligatory prayers." So whenever you need something or whenever you''re dealing with something difficult, a difficult situation, a challenge in life, don''t worry. There is going to be an obligatory prayer right around the corner. Use that as an opportunity to ask اللَّهُ to help you solve your problems. Not to say that you cannot remember اللَّهُ during the entire day, which obviously we should, that''s the idea of أَعُوذُ, right? But the proper sequence, the proper protocol would be to worship اللَّهُ and then seek His assistance.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'عبد الله ibn masood he would tell his students save your needs and your necessities for the obligatory prayers so whenever you need something or whenever youre dealing with something difficult a difficult situation a challenge in life dont worry there is going to be an obligatory prayer right around the corner use that as an opportunity to ask الله to help you solve your problems not to say that you cannot remember الله during the entire day which obviously we should thats the idea of اعوذ right but the proper sequence the proper protocol would be to worship الله and then seek his assistance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 27, NULL, 'The last thing I want to point out is the حِكْمَةٌ, the wisdom in the repetition of this word إِيَّاكَ. So you can see that the word إِيَّاكَ is used twice here, right? إِيَّاكَ نَعْبُدُ and then إِيَّاكَ نَسْتَعِينُ. So the word إِيَّاكَ is repeated twice. Now grammatically speaking, if اللَّهُ omitted the second إِيَّاكَ, and if اللَّهُ had just said ‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‎, it is only you we worship and seek assistance from.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'the last thing i want to point out is the حكمه the wisdom in the repetition of this word اياك so you can see that the word اياك is used twice here right اياك نعبد and then اياك نستعين so the word اياك is repeated twice now grammatically speaking if الله omitted the second اياك and if الله had just said اياك نعبد واياك نستعين it is only you we worship and seek assistance from', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 28, NULL, 'Right? Just eliminate the second إِيَّاكَ. That would have been grammatically correct. So then why did اللَّهُ repeat Himself when it''s not grammatically necessary? Does this mean that the second إِيَّاكَ is not absolutely necessary to the meaning? No. And let''s look at that. So there''s a wisdom behind that. So when we say ‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‎, when we remove the second إِيَّاكَ, both words نَعْبُدُ and نَسْتَعِينُ, they connect back with the same إِيَّاكَ. Which means they become associated with that إِيَّاكَ. But when I say ‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‎, they both now have their own إِيَّاكَ.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'right just eliminate the second اياك that would have been grammatically correct so then why did الله repeat himself when its not grammatically necessary does this mean that the second اياك is not absolutely necessary to the meaning no and lets look at that so theres a wisdom behind that so when we say اياك نعبد واياك نستعين when we remove the second اياك both words نعبد and نستعين they connect back with the same اياك which means they become associated with that اياك but when i say اياك نعبد واياك نستعين they both now have their own اياك', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 29, NULL, 'So what that does grammatically is that it makes both independent of one another. It makes worship and assistance independent of one another. Why is that important? Why did اللَّهُ do it this way? Because اللَّهُ said worship and then seek assistance, right? That''s the optimal method. That''s the right protocol. That would be ideal. That''s how we''re supposed to do it. But then there might be some of us who might have lost our way. There might be some people who are not praying to اللَّهُ. They''re not worshipping اللَّهُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'so what that does grammatically is that it makes both independent of one another it makes worship and assistance independent of one another why is that important why did الله do it this way because الله said worship and then seek assistance right thats the optimal method thats the right protocol that would be ideal thats how were supposed to do it but then there might be some of us who might have lost our way there might be some people who are not praying to الله theyre not worshipping الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 30, NULL, 'And yet, because of life, they just run into some difficulties or some tragedies. And in that difficult moment, they need اللَّهُs assistance. They need اللَّهُs help. So اللَّهُ very subtly, He separates the two, just a little bit. He makes them independent for the sake of the people to let them know that even if you aren''t worshipping Me, even if you aren''t praying to Me, don''t worry, you can still seek My help and My assistance. My door is still open to you. سُبْحَانَ اللهِ. So worshipping Me and then seeking assistance would be the ideal way, in submitting yourselves to Me, willingly, freely enslaving yourselves to Me and then seeking My assistance, that would be the more logical way of doing things. But even if you''re not doing that, even if you''re not worshipping Me or enslaving yourselves to Me or submitting to Me, I will not deny My assistance to you. You can still always turn to Me. You can still always come to Me, talk to Me.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'and yet because of life they just run into some difficulties or some tragedies and in that difficult moment they need اللهs assistance they need اللهs help so الله very subtly he separates the two just a little bit he makes them independent for the sake of the people to let them know that even if you arent worshipping me even if you arent praying to me dont worry you can still seek my help and my assistance my door is still open to you سبحان الله so worshipping me and then seeking assistance would be the ideal way in submitting yourselves to me willingly freely enslaving yourselves to me and then seeking my assistance that would be the more logical way of doing things but even if youre not doing that even if youre not worshipping me or enslaving yourselves to me or submitting to me i will not deny my assistance to you you can still always turn to me you can still always come to me talk to me', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 31, NULL, 'I will still be there for you. That''s the beauty of ‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‎. Now, considering the relationship between a master and a slave, what is the slave constantly in need of from his master? Commands, instructions, right? If there are no instructions from a master, if there are no commands coming from a master, then technically that means you''re free. So as the عَبْدُ, we need some instructions from اللَّهُ, right? Now the Arabic word for instructions is هِدَايَة, which comes from the root word هُدًى. So the next logical progression in this line of thought is that يَا اللَّهُ, now that I have enslaved myself to You, now that I''m committed to You, now that I''m depending on Your assistance to fulfill my commitment, what is it that You want me to do? How can I pay off this debt of submission that I owe You? How can I move towards You? How can I get closer to You? Give me some instructions, give me some هُدًى. And so, the سُورَةُ الْفَاتِحَةِ progresses into . Guide us, instruct us towards the straight path.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'i will still be there for you thats the beauty of اياك نعبد واياك نستعين now considering the relationship between a master and a slave what is the slave constantly in need of from his master commands instructions right if there are no instructions from a master if there are no commands coming from a master then technically that means youre free so as the عبد we need some instructions from الله right now the arabic word for instructions is هدايه which comes from the root word هدي so the next logical progression in this line of thought is that يا الله now that i have enslaved myself to you now that im committed to you now that im depending on your assistance to fulfill my commitment what is it that you want me to do how can i pay off this debt of submission that i owe you how can i move towards you how can i get closer to you give me some instructions give me some هدي and so the سوره الفاتحه progresses into guide us instruct us towards the straight path', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 32, NULL, 'Scholars point out something very important here in this sequence of declarations. So we just learned that is a commitment, right? It''s a declaration, it''s a promise, it''s our sincere as we call it. Right? That is followed by a call for assistance, which is then followed by asking for instructions. So if you think about the sequence here, we''re not saying give me the instructions first, if I think I''ll be able to do them, if they make sense to me, if I feel like, you know, I''m able to find the time to do them, then I will do them. No. All of that has already been covered in the earlier verses. Right? Starting from we are just making the commitment.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'scholars point out something very important here in this sequence of declarations so we just learned that is a commitment right its a declaration its a promise its our sincere as we call it right that is followed by a call for assistance which is then followed by asking for instructions so if you think about the sequence here were not saying give me the instructions first if i think ill be able to do them if they make sense to me if i feel like you know im able to find the time to do them then i will do them no all of that has already been covered in the earlier verses right starting from we are just making the commitment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 33, NULL, 'We''re making that promise of that we will do whatever you tell us to do, because that''s all part of being a slave. Right? You don''t become a slave and then say, you know, I''ll do it when it makes sense to me. The making sense of it was all done in the previous three verses. Those were the verses that make us realize that اللَّهُ is worthy of our . Those are the verses where we get convinced of اللَّهُs mastery over us. Right? Those were the verses where we completed our homework, where we did all our research, they complete the theory portion of this whole message. Starting from now, it''s practical time, it''s all action.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'were making that promise of that we will do whatever you tell us to do because thats all part of being a slave right you dont become a slave and then say you know ill do it when it makes sense to me the making sense of it was all done in the previous three verses those were the verses that make us realize that الله is worthy of our those are the verses where we get convinced of اللهs mastery over us right those were the verses where we completed our homework where we did all our research they complete the theory portion of this whole message starting from now its practical time its all action', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 34, NULL, 'And the reason this is important is because people ask this question, you know, why do we have to take ahead when السُّلَيْمَان is, when we take, when we make this commitment, people say that, we know, why do I have to make this promise, why is this so important? Because that is the action of commitment. You can think and ponder and plan all you want, but until you actually commit to something, you cannot produce a change. I mean, isn''t that true in every aspect of our lives? Weight loss, the biggest problem of our times.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'and the reason this is important is because people ask this question you know why do we have to take ahead when السليمان is when we take when we make this commitment people say that we know why do i have to make this promise why is this so important because that is the action of commitment you can think and ponder and plan all you want but until you actually commit to something you cannot produce a change i mean isnt that true in every aspect of our lives weight loss the biggest problem of our times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 35, NULL, 'We can read all about weight loss. In fact, according to a study, obese people are usually the ones who know the most about losing weight, how they need to lose the weight, because they''ve read up so much about it, they''ve watched so many videos on this. But until they commit to a lifestyle of good diet and a lifestyle of exercise, they cannot actually lose the weight, right? So you have to make a commitment to produce change.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'we can read all about weight loss in fact according to a study obese people are usually the ones who know the most about losing weight how they need to lose the weight because theyve read up so much about it theyve watched so many videos on this but until they commit to a lifestyle of good diet and a lifestyle of exercise they cannot actually lose the weight right so you have to make a commitment to produce change', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'worship and assistance', 'Worship and Assistance', 36, NULL, 'And this is why we have I commit only to you and I seek only your assistance, and then we have guide us, give us instructions. So the more sincere we are in our commitment, the more we can expect اللَّهُ to help us on our journey towards him. So إِن شَآءَ ٱللَّهُ, in the next session we will look at the remaining verses. وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتِمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ وَعَلَى أَخِيهِ وَوَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِ الطَّاهِرِينَ وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ، الْفَاتِحَة.', '', NULL, NULL, NULL, NULL, 'surah al fateha worship and assistance', 'and this is why we have i commit only to you and i seek only your assistance and then we have guide us give us instructions so the more sincere we are in our commitment the more we can expect الله to help us on our journey towards him so ان شاء الله in the next session we will look at the remaining verses واخر دعوانا ان الحمد لله رب العالمين والصلاه والسلام علي رسوله سيدنا محمد خاتم النبيين وسيد المرسلين وعلي اخيه ووصيه علي بن ابي طالب اشرف الوصيين وعلي الايمه من ذريته الطاهرين والسلام عليهم اجمعين الفاتحه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 0, NULL, 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ اللَّهُمَّ صَلِّ يَا اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ وَبَارِكْ وَسَلِّمْ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ', '', 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ اللَّهُمَّ صَلِّ يَا اللَّهُ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ وَبَارِكْ وَسَلِّمْ رَبِّ اشْرَحْ لِي صَدْرِي وَيَسِّرْ لِي أَمْرِي وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي يَفْقَهُوا قَوْلِي السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ', NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل يا الله علي سيدنا محمد وعلي ال سيدنا محمد وبارك وسلم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي السلام عليكم ورحمه الله وبركاته', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل يا الله علي سيدنا محمد وعلي ال سيدنا محمد وبارك وسلم رب اشرح لي صدري ويسر لي امري واحلل عقده من لساني يفقهوا قولي السلام عليكم ورحمه الله وبركاته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 1, NULL, 'We''re studying سُورَةُ الْفَاتِحَةِ, and we''ve completed the first four verses: ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, ‏ٱلْحَمْدُ لِلَّهِ رَبِّ ٱلْعَلَمِينَ ‎, ٱلرَّحْمَنِ ٱلرَّحِيمِ, مَلِكِ يَوْمِ ٱلدِّينِ. So now in this session we''re going to look at ٱهْدِنَا ٱلصِّرَطَ ٱلْمُسْتَقِيمَ. This verse is commonly translated as "guide us to the straight path," right? ٱهْدِنَا ٱلصِّرَطَ ٱلْمُسْتَقِيمَ, guide us to the straight path.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'were studying سوره الفاتحه and weve completed the first four verses بسم الله الرحمن الرحيم الحمد لله رب العلمين الرحمن الرحيم ملك يوم الدين so now in this session were going to look at اهدنا الصرط المستقيم this verse is commonly translated as guide us to the straight path right اهدنا الصرط المستقيم guide us to the straight path', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 2, NULL, 'Now let''s look at what does that mean. Normally we think about it like, you know, so when I say to you, "guide me to your house," what am I asking for? I''m asking for instructions, right? Directions. That''s what guidance essentially means. It means instructions or directions. Now, how are you going to give me these instructions? What are the different ways in which you can give me instructions or directions? So for instance, you can say, take this particular road and go three miles on it and then turn left, right? That is how typically you will give instructions for a particular destination. You''ll just list it out for the person. Another way you can do that, you can tell me, you can guide me by saying, you know what, just stand at this bus stop, and take this particular bus and then get off at this particular stop. So that''s another way you can guide me. This is guidance through the bus, right? It is guidance through a medium or through an intermediary.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'now lets look at what does that mean normally we think about it like you know so when i say to you guide me to your house what am i asking for im asking for instructions right directions thats what guidance essentially means it means instructions or directions now how are you going to give me these instructions what are the different ways in which you can give me instructions or directions so for instance you can say take this particular road and go three miles on it and then turn left right that is how typically you will give instructions for a particular destination youll just list it out for the person another way you can do that you can tell me you can guide me by saying you know what just stand at this bus stop and take this particular bus and then get off at this particular stop so thats another way you can guide me this is guidance through the bus right it is guidance through a medium or through an intermediary', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 3, NULL, 'So what you''re saying in the second mode of instructions is that you don''t have to do anything. The bus will do all the work for you. You''re telling me that all you have to do is make sure that you''re at the right bus stop at the right time and you catch the right bus, and then just let the bus get you to your destination. That''s the second way of giving instructions, through an intermediary or through a medium. The third way is that you can say, look, I''m headed home right now, why don''t you just jump in the car with me and I''ll take you all the way, right? Those are the three ways by which you can guide me or direct me to your house. First is through a set of instructions. Second is through a medium or an intermediary. And the third is by literally taking me to that destination yourself. It''s very important that you understand these three, the differences between these three modes of instructions.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'so what youre saying in the second mode of instructions is that you dont have to do anything the bus will do all the work for you youre telling me that all you have to do is make sure that youre at the right bus stop at the right time and you catch the right bus and then just let the bus get you to your destination thats the second way of giving instructions through an intermediary or through a medium the third way is that you can say look im headed home right now why dont you just jump in the car with me and ill take you all the way right those are the three ways by which you can guide me or direct me to your house first is through a set of instructions second is through a medium or an intermediary and the third is by literally taking me to that destination yourself its very important that you understand these three the differences between these three modes of instructions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 4, NULL, 'Now, what is so cool about this verse, and listen to this carefully, is that asking for guidance through a set of instructions or through a set of directions in Arabic, it is called اِهْدِنَا إِلَى صِرَاطِ الْمُسْتَقِيمِ. اِهْدِنَا إِلَى صِرَاطِ الْمُسْتَقِيمِ. Guide me through a set of instructions. Asking for guidance using a medium would be اِهْدِنَا بِالصِّرَاطِ الْمُسْتَقِيمِ. The letter ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ would be included with صِرَاط. اِهْدِنَا بِالصِّرَاطِ الْمُسْتَقِيمِ. Asking for completely assisted guidance, which is the third form, in which you are literally holding my hand and taking me to the destination, that would be اِهْدِنَا عَلَى صِرَاطِ الْمُسْتَقِيمِ. You see?', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'now what is so cool about this verse and listen to this carefully is that asking for guidance through a set of instructions or through a set of directions in arabic it is called اهدنا الي صراط المستقيم اهدنا الي صراط المستقيم guide me through a set of instructions asking for guidance using a medium would be اهدنا بالصراط المستقيم the letter بسم الله الرحمن الرحيم would be included with صراط اهدنا بالصراط المستقيم asking for completely assisted guidance which is the third form in which you are literally holding my hand and taking me to the destination that would be اهدنا علي صراط المستقيم you see', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 5, NULL, 'Now, what''s interesting about the فَاتِحَة is that we are not asking اللَّه for instructions by saying, اِهْدِنَا إِلَى صِرَاطِ الْمُسْتَقِيمِ. We''re not asking Him for instructions by saying, ٱهْدِنَا ٱلصِّرَطَ ٱلْمُسْتَقِيمَ. And we''re not saying, اِهْدِنَا عَلَى صِرَاطِ الْمُسْتَقِيمِ. We are not using any of those words. We are just simply saying .', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'now whats interesting about the فاتحه is that we are not asking الله for instructions by saying اهدنا الي صراط المستقيم were not asking him for instructions by saying اهدنا الصرط المستقيم and were not saying اهدنا علي صراط المستقيم we are not using any of those words we are just simply saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 6, NULL, 'You see that? We''re omitting the إِلَى, we''re omitting the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, and we''re omitting the أَلَا in our request for our instructions. Now why is that relevant? Because according to the rules of Arabic linguistics, when you don''t use any of these words, what you actually mean is all of them at the same time. You see, the principle of Arabic is that if you are using none of these words, you''re linguistically using all of them, otherwise you would have to use these separate sentences.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'you see that were omitting the الي were omitting the بسم الله الرحمن الرحيم and were omitting the الا in our request for our instructions now why is that relevant because according to the rules of arabic linguistics when you dont use any of these words what you actually mean is all of them at the same time you see the principle of arabic is that if you are using none of these words youre linguistically using all of them otherwise you would have to use these separate sentences', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 7, NULL, 'So now when we say , what we''re really saying is, direct me to the straight path through your instructions, which is the قُرْآن. We''re saying, guide me to the straight path through your intermediaries, through the mediums, through the example of people like رَسُولُ اللَّهِ , مَالِنَا عَلِي , the أَإِيمَا, the دُعَاء, and then finally, hold my hand and walk me along this path until I reach my destination. Grant me your constant companionship as I walk along this path. سُبْحَانَ اللَّهِ. It''s amazing.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'so now when we say what were really saying is direct me to the straight path through your instructions which is the قران were saying guide me to the straight path through your intermediaries through the mediums through the example of people like رسول الله مالنا علي the اايما the دعاء and then finally hold my hand and walk me along this path until i reach my destination grant me your constant companionship as i walk along this path سبحان الله its amazing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 8, NULL, 'See, a school counselor gives us guidance, guides the students, right? That''s the job of a school counselor. His guidance is ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sically information, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'see a school counselor gives us guidance guides the students right thats the job of a school counselor his guidance is بسم الله الرحمن الرحيم sically information right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 9, NULL, 'A traffic officer''s guidance is information. The GPS guiding you in your car is information, but اللَّه''s guidance is more than just information. Because اللَّه''s guidance has to do with the personal choices that we have to make every single moment. So we''re not just asking for directions, we''re also asking Him for the strength and His assistance in helping us make those right decisions. These are two very different things. Because sometimes we can have all the right information and we can still make the wrong decisions.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'a traffic officers guidance is information the gps guiding you in your car is information but اللهs guidance is more than just information because اللهs guidance has to do with the personal choices that we have to make every single moment so were not just asking for directions were also asking him for the strength and his assistance in helping us make those right decisions these are two very different things because sometimes we can have all the right information and we can still make the wrong decisions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 10, NULL, 'Also, if you think about it, you know, guidance, what did we say guidance is? It''s just a set of instructions, right? How many times do we need information? One time. You know, if I''ve been given the right information, I don''t have to ask for it again. Once I know the direction to your house, that''s it. I''m not going to keep asking you again and again. But how many times do we ask اللَّه for guidance? Over and over again, as a standard, right? It''s like drinking water. You cannot say I drank water yesterday, so I''m never going to need it again. It doesn''t work that way. If you want to survive, you have to drink again and again, every single day.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'also if you think about it you know guidance what did we say guidance is its just a set of instructions right how many times do we need information one time you know if ive been given the right information i dont have to ask for it again once i know the direction to your house thats it im not going to keep asking you again and again but how many times do we ask الله for guidance over and over again as a standard right its like drinking water you cannot say i drank water yesterday so im never going to need it again it doesnt work that way if you want to survive you have to drink again and again every single day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 11, NULL, '![](images/167/7500cce9-7ea7-43ad-a8ea-d087e3‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎3830.jpg)', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'images 167 7500cce9 7ea7 43ad a8ea d087e3 بسم الله الرحمن الرحيم 3830 jpg', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 12, NULL, 'So just as our bodies become thirsty for water and food, our heart keeps starving for guidance. This is why we keep coming ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ck to اللَّه in every single prayer with this request of ٱهْدِنَا ٱلصِّرَطَ ٱلْمُسْتَقِيمَ.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'so just as our bodies become thirsty for water and food our heart keeps starving for guidance this is why we keep coming بسم الله الرحمن الرحيم ck to الله in every single prayer with this request of اهدنا الصرط المستقيم', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 13, NULL, 'Now let''s look at this word اِهْدِنَا. So guidance we already talked about. But what''s really interesting is that if you look at the root word for اِهْدِنَا, it comes from هُدًى. So in this context, the derivative is هُدًى, which means guidance, which I just explained to you. But what''s interesting is that هُدًى is also the root word for هَدِيَّة. Now what does هَدِيَّة mean? It''s also used in Urdu. The word هَدِيَّة, it means a gift. Now for an Arab living in the desert when he''s lost, right? Think about an Arab who lives in the desert and he got lost in the desert.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'now lets look at this word اهدنا so guidance we already talked about but whats really interesting is that if you look at the root word for اهدنا it comes from هدي so in this context the derivative is هدي which means guidance which i just explained to you but whats interesting is that هدي is also the root word for هديه now what does هديه mean its also used in urdu the word هديه it means a gift now for an arab living in the desert when hes lost right think about an arab who lives in the desert and he got lost in the desert', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 14, NULL, 'What is the greatest gift that you can give him? Even more than water. Because water is not going to be good enough. It will last him maybe one more day. Food is maybe going to last him a couple more days. So from an Arab''s perspective, especially an Arab who is lost in the desert, what is the greatest of all gift for him? Guidance, directions ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ck to his home, ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ck to his family. That''s the ultimate gift. So we''re asking اللَّه not just for any gift, we''re asking اللَّه for the ultimate gift. Because اللَّه''s guidance is the ultimate gift for a believer. So it becomes so much more than just instructions or informations, you see? It completely changes the perspective of a believer from just simply a set of rules.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'what is the greatest gift that you can give him even more than water because water is not going to be good enough it will last him maybe one more day food is maybe going to last him a couple more days so from an arabs perspective especially an arab who is lost in the desert what is the greatest of all gift for him guidance directions بسم الله الرحمن الرحيم ck to his home بسم الله الرحمن الرحيم ck to his family thats the ultimate gift so were asking الله not just for any gift were asking الله for the ultimate gift because اللهs guidance is the ultimate gift for a believer so it becomes so much more than just instructions or informations you see it completely changes the perspective of a believer from just simply a set of rules', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 15, NULL, 'It creates the sense of gratitude because instructions and directions are now perceived as a gift, a gesture of love, a gesture of care. That''s when you give a gift to somebody, right? You don''t give a gift to somebody you hate. You always give a gift to somebody you love. So now these instructions and this set of information of how to live our life, it no longer feels like this burden that we have to bear, but rather it feels like a gift. That is the perspective that changes when you understand the linguistics of the word هُدًى or هُدًى.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'it creates the sense of gratitude because instructions and directions are now perceived as a gift a gesture of love a gesture of care thats when you give a gift to somebody right you dont give a gift to somebody you hate you always give a gift to somebody you love so now these instructions and this set of information of how to live our life it no longer feels like this burden that we have to bear but rather it feels like a gift that is the perspective that changes when you understand the linguistics of the word هدي or هدي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 16, NULL, 'Now let''s look at صِرَاطَ. What is صِرَاطَ? So it is generally translated as a path, right? But in the Arabic language, there are certain rules that go with the word صِرَاطَ. The first rule is that it can only be used for a straight path. Okay? صِرَاطَ, the word سُورَةُ الفَاتِحَةِ, it can only be used for a straight path. If a road is bumpy, or if it curves, or if the road is wavy, it cannot be سُورَةُ الفَاتِحَةِ.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'now lets look at صراط what is صراط so it is generally translated as a path right but in the arabic language there are certain rules that go with the word صراط the first rule is that it can only be used for a straight path okay صراط the word سوره الفاتحه it can only be used for a straight path if a road is bumpy or if it curves or if the road is wavy it cannot be سوره الفاتحه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 17, NULL, 'Right? So by definition, the word سُورَةُ الفَاتِحَةِ, it means that the path has to be straight. So the word سُورَةُ الفَاتِحَةِ, right, just with the ضُمَّ at the top, سُورَة, it is actually used for a perfectly straight sword. That''s a سُورَة. If the sword is curved, it is called سَيْف. You know some of these swords that we see in old movies? So, مَالِنَا عَلِي''s sword ذُو الْفِقَار is a good example of that, right? It''s, we know that it''s curved, right? The shape of ذُو الْفِقَار was curved. So what, what is that, what did رَسُولُ اللَّهِ say? لَا فَتَى إِلَّا عَلِيٌّ، لَا سَيْفَ إِلَّا ذُو الْفَقَارِ. Not لَا سُورَةَ إِلَّا ذُو الْفَقَار, right? He said لَا سَيْفَ إِلَّا ذُو الْفَقَارِ, because سُورَةُ الْفَاتِحَة by definition is a curved sword, right? So صِرَاط means a perfectly straight path. That''s the first thing. The second rule is that صِرَاطَ can only be used for a wide path. By definition, صِرَاطَ cannot be used for a narrow path.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'right so by definition the word سوره الفاتحه it means that the path has to be straight so the word سوره الفاتحه right just with the ضم at the top سوره it is actually used for a perfectly straight sword thats a سوره if the sword is curved it is called سيف you know some of these swords that we see in old movies so مالنا عليs sword ذو الفقار is a good example of that right its we know that its curved right the shape of ذو الفقار was curved so what what is that what did رسول الله say لا فتي الا علي لا سيف الا ذو الفقار not لا سوره الا ذو الفقار right he said لا سيف الا ذو الفقار because سوره الفاتحه by definition is a curved sword right so صراط means a perfectly straight path thats the first thing the second rule is that صراط can only be used for a wide path by definition صراط cannot be used for a narrow path', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 18, NULL, 'It has to be a wide path. A path that allows multiple people to travel on it simultaneously. So in our world, just think of it like a major highway with multiple lanes, except that it''s just a perfectly straight highway. You understand? Now, this is something very cool. There are other words in Arabic that can be used for a path. There are various different ways. So, for example, there is سَبِيل, which means a path. There is فَاتِحَة, which means a path. There is طَارِق, which means a path. Now, what''s really interesting about these words is that there are plurals avaإِلَىble for all these words.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'it has to be a wide path a path that allows multiple people to travel on it simultaneously so in our world just think of it like a major highway with multiple lanes except that its just a perfectly straight highway you understand now this is something very cool there are other words in arabic that can be used for a path there are various different ways so for example there is سبيل which means a path there is فاتحه which means a path there is طارق which means a path now whats really interesting about these words is that there are plurals avaاليble for all these words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 19, NULL, 'So, for instance, for سَبِيل, there is سُبُل. Right? The plural of سَبِيل is سُبُل. For طَارِق, the plural is طَوَارِق. For فَاتِحَة, the plural is فِجَاج. What was really interesting is that there is no plural for the word صِرَاطَ. It is a singular word. And this is why صِرَاط also means the only avaإِلَىble path. So imagine, just imagine these two islands that are connected by a single bridge, right? There is water under the bridge and the water between these two islands, it''s very turbulent. Think about it that way, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'so for instance for سبيل there is سبل right the plural of سبيل is سبل for طارق the plural is طوارق for فاتحه the plural is فجاج what was really interesting is that there is no plural for the word صراط it is a singular word and this is why صراط also means the only avaاليble path so imagine just imagine these two islands that are connected by a single bridge right there is water under the bridge and the water between these two islands its very turbulent think about it that way right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 20, NULL, 'You cannot take a boat to go from one side to the other or one island to the other. The only way for you to get from point A to point B in this case is this one single wide bridge. There is absolutely no other path for you to take except this bridge. You understand? So in this case where there is no alternate route avaإِلَىble, then that bridge, that one singular wide path would be called صِرَاطَ. So صِرَاطَ linguistically has these peculiar characteristics. It has to have, it has to be a wide path, it has to be a straight path, and it has to be the only path to that destination.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'you cannot take a boat to go from one side to the other or one island to the other the only way for you to get from point a to point b in this case is this one single wide bridge there is absolutely no other path for you to take except this bridge you understand so in this case where there is no alternate route avaاليble then that bridge that one singular wide path would be called صراط so صراط linguistically has these peculiar characteristics it has to have it has to be a wide path it has to be a straight path and it has to be the only path to that destination', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 21, NULL, 'So now what does all of this mean for us? It means that there can be many, many paths avaإِلَىble to us in terms of how we choose to live our lives. There can be many religions, there can be many belief systems, all of which can be correct. But the path that directly leads to اللهُ سُبْحَانَهُ وَتَعَالَى, it can only be one. It means that even though there are many different religions, many different philosophies, all explaining how to reach God, all explaining how to live your life, the word سُورَةُ الفَاتِحَةِ indicates that there can only be one true religion, the perfect religion.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'so now what does all of this mean for us it means that there can be many many paths avaاليble to us in terms of how we choose to live our lives there can be many religions there can be many belief systems all of which can be correct but the path that directly leads to الله سبحانه وتعالي it can only be one it means that even though there are many different religions many different philosophies all explaining how to reach god all explaining how to live your life the word سوره الفاتحه indicates that there can only be one true religion the perfect religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 22, NULL, 'Think about it like that. The perfect religion. So there is good, there is better, that is best, that is perfect. If you start breaking it down in that way, صِرَاطَ indicates the perfect religion. Right? It''s a religion, a path that will be the shortest distance between point A and point B, connecting the slave to his master.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'think about it like that the perfect religion so there is good there is better that is best that is perfect if you start breaking it down in that way صراط indicates the perfect religion right its a religion a path that will be the shortest distance between point a and point b connecting the slave to his master', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 23, NULL, 'Now, if this was not interesting enough, which obviously it is, what really blows my mind is that اللَّه did not just say صِرَاطَ in this verse, he said الصِّرَاطَ, right? He used the definite article, the. This, the path, the particular path. Now صِرَاطَ already meant one single path by its definition, then why say الصِّرَاطَ? Because even though الْإِسْلَام is the one true religion, there are many, many sects within الْإِسْلَام, and by making this word a definite, by adding the definite article to سُورَةُ الفَاتِحَةِ, making it الصِّرَاط, what is being taught here, that there can only be one perfectly true sect within الْإِسْلَام itself. Isn''t that incredible? So just by understanding the linguistics of the word, it can answer all of our questions, you know, because people ask this all the time. I used to ask this question all the time, you know, why does there only have to be one true religion?', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'now if this was not interesting enough which obviously it is what really blows my mind is that الله did not just say صراط in this verse he said الصراط right he used the definite article the this the path the particular path now صراط already meant one single path by its definition then why say الصراط because even though الاسلام is the one true religion there are many many sects within الاسلام and by making this word a definite by adding the definite article to سوره الفاتحه making it الصراط what is being taught here that there can only be one perfectly true sect within الاسلام itself isnt that incredible so just by understanding the linguistics of the word it can answer all of our questions you know because people ask this all the time i used to ask this question all the time you know why does there only have to be one true religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 24, NULL, 'Why can''t every religion be a true religion? It can''t because the word سُورَةُ الْفَاتِحَةِ does not have a plural. So it can only be singular. It must be straight, which means it must take the shortest route to connect us with اللَّه. Right, because the shortest distance between two points is a straight line. Also, it must be a wide path, which means there has to be acceptance for others along the way. That''s صِرَاطَ, but then الصِّرَاطَ means that there is only one sect, one lane that will, the fastest lane, right? Think about it on a highway, you have the slow lane, you have the fast lane, so this is the fast lane that will directly lead to اللَّه using the shortest distance. It''s the most direct path to اللَّه, سُبْحَانَ اللهِ. All of these meanings are encapsulated in the single word السَّبْعُ...', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'why cant every religion be a true religion it cant because the word سوره الفاتحه does not have a plural so it can only be singular it must be straight which means it must take the shortest route to connect us with الله right because the shortest distance between two points is a straight line also it must be a wide path which means there has to be acceptance for others along the way thats صراط but then الصراط means that there is only one sect one lane that will the fastest lane right think about it on a highway you have the slow lane you have the fast lane so this is the fast lane that will directly lead to الله using the shortest distance its the most direct path to الله سبحان الله all of these meanings are encapsulated in the single word السبع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 25, NULL, 'الصِّرَاطَ.', '', 'الصِّرَاطَ', NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'الصراط', 'الصراط');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 26, NULL, 'And this is not to say that the rest of الْإِسْلَام and all the other sects are all gar‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ge. No, of course not. All it means is that it''s going to take them longer to get there, but they will eventually get there. Everybody is going to eventually get there. And this is why all Muslims of all sects, regardless, right, they pray for this knowledge of this direct path to اللَّه, because all Muslims are praying and saying, including us, I mean, we just, you know, knowing the straight, we, so even if I say that is the, is the, is the fastest path, is knowing that path and actually walking the path are two different things. So that is why we''re also saying, we''re also constantly praying for, for, because if you think about it, if we, if we strongly believe, we truly believe in our hearts that we are on the right path, on the right, we are the right sect within the world of الْإِسْلَام, then why do we have to constantly keep asking for this guidance? Why do we have to keep every prayer, why do we have to keep saying, we already are on the right path? But being on the right path and walking the path are two completely different things.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'and this is not to say that the rest of الاسلام and all the other sects are all gar بسم الله الرحمن الرحيم ge no of course not all it means is that its going to take them longer to get there but they will eventually get there everybody is going to eventually get there and this is why all muslims of all sects regardless right they pray for this knowledge of this direct path to الله because all muslims are praying and saying including us i mean we just you know knowing the straight we so even if i say that is the is the is the fastest path is knowing that path and actually walking the path are two different things so that is why were also saying were also constantly praying for for because if you think about it if we if we strongly believe we truly believe in our hearts that we are on the right path on the right we are the right sect within the world of الاسلام then why do we have to constantly keep asking for this guidance why do we have to keep every prayer why do we have to keep saying we already are on the right path but being on the right path and walking the path are two completely different things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 27, NULL, 'Just by standing on the path, I do not get to my destination. I have to walk the path, right? So there''s so many other nuances within this which I''m skipping over, but I''ve given you the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sics, and if you really think about it and if you really reflect on it, it''ll open up so many more, it''ll open up a world of understanding for you. Anyway, so that is السَّرَاةُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'just by standing on the path i do not get to my destination i have to walk the path right so theres so many other nuances within this which im skipping over but ive given you the بسم الله الرحمن الرحيم sics and if you really think about it and if you really reflect on it itll open up so many more itll open up a world of understanding for you anyway so that is السراه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 28, NULL, 'Now the word مُسْتَقِيمَ, it is ٱهْدِنَا ٱلصِّرَطَ ٱلْمُسْتَقِيمَ, right? How is مُسْتَقِيمَ translated generally? ٱهْدِنَا ٱلصِّرَطَ ٱلْمُسْتَقِيمَ, guide us to the straight path. But we already established that صِرَاطَ, it already implies straight, right? Because if it wasn''t straight, it wouldn''t be صِرَاطَ. So now why is اللَّه repeating Himself? He''s not. Because مُسْتَقِيمَ does not just mean straight, it actually means upright.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'now the word مستقيم it is اهدنا الصرط المستقيم right how is مستقيم translated generally اهدنا الصرط المستقيم guide us to the straight path but we already established that صراط it already implies straight right because if it wasnt straight it wouldnt be صراط so now why is الله repeating himself hes not because مستقيم does not just mean straight it actually means upright', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 29, NULL, 'The word مُسْتَقِيمَ, it comes from قَامَ or اِسْتَقَامَ, which means to stand up. Not so much to go forward, but to go upward, right? It''s from قِيَامٌ, which means to stand upright. So in صَلَاةٌ, in our prayers, you know, we have ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎, we have رُكُوْر, we have سُجُود, right? So what does ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ mean? Means to stand up straight. That''s what ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ is. So when we say we are asking اللَّه for guidance on a path, which heads which way? Straight up it is. We''re asking guidance for a path of spiritual elevation.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'the word مستقيم it comes from قام or استقام which means to stand up not so much to go forward but to go upward right its from قيام which means to stand upright so in صلاه in our prayers you know we have بسم الله الرحمن الرحيم we have ركور we have سجود right so what does بسم الله الرحمن الرحيم mean means to stand up straight thats what بسم الله الرحمن الرحيم is so when we say we are asking الله for guidance on a path which heads which way straight up it is were asking guidance for a path of spiritual elevation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 30, NULL, 'Now think about this. What happens when I travel on a path that puts me on an elevation? The more I travel on it, the higher I will rise. Isn''t that true? Imagine this: a path that is just a physical path. Think of it as a ladder, like this ladder that is going from the ground all the way up to the sky.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'now think about this what happens when i travel on a path that puts me on an elevation the more i travel on it the higher i will rise isnt that true imagine this a path that is just a physical path think of it as a ladder like this ladder that is going from the ground all the way up to the sky', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 31, NULL, 'As I''m climbing this ladder, what am I rising above? I''m rising above this دُنْيَا, isn''t it? And as I rise higher, who am I getting close to? I''m getting closer to اللَّه. Now, what happens to the view as you rise higher? It becomes better, it becomes broader, right? You start getting a better perspective on things. We already established that walking this path is all about gaining knowledge. So the more we learn, the more knowledge we acquire, the more aware we become of the realities of this world and of the afterlife. This path of spiritual elevation helps mold and form our perspective.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'as im climbing this ladder what am i rising above im rising above this دنيا isnt it and as i rise higher who am i getting close to im getting closer to الله now what happens to the view as you rise higher it becomes better it becomes broader right you start getting a better perspective on things we already established that walking this path is all about gaining knowledge so the more we learn the more knowledge we acquire the more aware we become of the realities of this world and of the afterlife this path of spiritual elevation helps mold and form our perspective', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 32, NULL, 'But then there''s a negative side to this as well, because the higher you climb, the more danger there is of falling. So if you are, you know, one foot high and you fall off from a stool, you''ll be okay, right? If you''re 20 feet high and you fall, you''re not going to be so okay. If you''re 100 feet high and you fall, right? So in other words, the person who is traveling on this path for a long time, is he in less danger or is he in more danger?', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'but then theres a negative side to this as well because the higher you climb the more danger there is of falling so if you are you know one foot high and you fall off from a stool youll be okay right if youre 20 feet high and you fall youre not going to be so okay if youre 100 feet high and you fall right so in other words the person who is traveling on this path for a long time is he in less danger or is he in more danger', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 33, NULL, 'He''s in more danger. And this is why you''ll see that the higher the rank of the person, the more خُشُوعٌ this person shows in his صَلَاةٌ, it just manifests, the more, because he has so much more fear in his heart, the, you know, the more خُشُوع he has, the more he cries on his prayer mat during صَلَاةٌ. And this is why we find the صَحَابَة exercising extreme caution at every single step of their way. Not because they love to be miserable, which is the impression we get sometimes reading these books of سُورَة الْفَاتِحَة. I mean, at least I used to think that way. I''m like, what is wrong with these people? Like, why? اللَّه has not asked us to be miserable in life. He has asked us to enjoy life and have, lead a good life and all of that. Then why are these people suffering or putting themselves through these hardships of constant prayer, constant fasting? Just, right? Because اللَّه never demanded that. Yet we find, if we read the books of سُورَةُ الْفَاتِحَةِ, we find these people just striving to the nth degree, and it never made sense to me until I understood the linguistics of this. Why did they do that?', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'hes in more danger and this is why youll see that the higher the rank of the person the more خشوع this person shows in his صلاه it just manifests the more because he has so much more fear in his heart the you know the more خشوع he has the more he cries on his prayer mat during صلاه and this is why we find the صحابه exercising extreme caution at every single step of their way not because they love to be miserable which is the impression we get sometimes reading these books of سوره الفاتحه i mean at least i used to think that way im like what is wrong with these people like why الله has not asked us to be miserable in life he has asked us to enjoy life and have lead a good life and all of that then why are these people suffering or putting themselves through these hardships of constant prayer constant fasting just right because الله never demanded that yet we find if we read the books of سوره الفاتحه we find these people just striving to the nth degree and it never made sense to me until i understood the linguistics of this why did they do that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 34, NULL, 'They did that because of this caution and this superior perspective. You know, we look at them and we think that they are suffering. But if we had a chance to ask them, they would say that they were enjoying it, they were loving it, because they were excited about their destination. And so the work to get there no longer felt like work, you understand? So if you have a goal, if there is something that you want to achieve and you''re really crazy about achieving it, you''re really motivated about getting there, the effort to get there is actually enjoyable. You don''t really care about it. Think about a rocket. A rocket that is headed towards space.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'they did that because of this caution and this superior perspective you know we look at them and we think that they are suffering but if we had a chance to ask them they would say that they were enjoying it they were loving it because they were excited about their destination and so the work to get there no longer felt like work you understand so if you have a goal if there is something that you want to achieve and youre really crazy about achieving it youre really motivated about getting there the effort to get there is actually enjoyable you dont really care about it think about a rocket a rocket that is headed towards space', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 35, NULL, 'That''s literally... it is on a path that is directed upward. Now, we know that this rocket, it needs a lot of fuel, it needs a lot of force, it needs a lot of energy to overcome the gravity of this Earth. But once it breaks through the gravitational field and it enters space, there is no effort required for any kind of movement. All it needs is a bit of thrust here and there, and it''ll just glide to wherever it wants to go. So that''s what the صَحَابَة were aiming for. That''s why they put so much work, because then once they perfected it, once they rose above the perspective of this inferior دُنْيَا, once they became aware of the unlimited and infinite space, the infinite possibilities of the solar system, gأَلَاxies, this universe, then this insignificant دُنْيَا became worthless to them.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'thats literally it is on a path that is directed upward now we know that this rocket it needs a lot of fuel it needs a lot of force it needs a lot of energy to overcome the gravity of this earth but once it breaks through the gravitational field and it enters space there is no effort required for any kind of movement all it needs is a bit of thrust here and there and itll just glide to wherever it wants to go so thats what the صحابه were aiming for thats why they put so much work because then once they perfected it once they rose above the perspective of this inferior دنيا once they became aware of the unlimited and infinite space the infinite possibilities of the solar system gالاxies this universe then this insignificant دنيا became worthless to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 36, NULL, 'So if you really grasp this concept, and if you start looking at it from this perspective, you know, you can really reconcile a lot of their behavior in this world. So we say... when we say it in سُورَةُ الْفَاتِحَةِ, when we pray, what we''re actually saying is: grant us the gift, the gift of guidance. Grant us the gift of true knowledge through your book, through the practical examples of your beloved and chosen people. And then, as we begin our spiritual journey towards you, following the footsteps of your chosen ones, accompany us every single step of the way.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'so if you really grasp this concept and if you start looking at it from this perspective you know you can really reconcile a lot of their behavior in this world so we say when we say it in سوره الفاتحه when we pray what were actually saying is grant us the gift the gift of guidance grant us the gift of true knowledge through your book through the practical examples of your beloved and chosen people and then as we begin our spiritual journey towards you following the footsteps of your chosen ones accompany us every single step of the way', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'verse', 'guidance to the straight path', 'Guidance To The Straight Path', 37, NULL, '![](images/167/e1618e1c-a163-4415-9af3-b9d008a48‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎0.jpg)', '', 'بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ', NULL, 1, 1, 'surah al fateha guidance to the straight path', 'images 167 e1618e1c a163 4415 9af3 b9d008a48 بسم الله الرحمن الرحيم 0 jpg', 'بسم الله الرحمن الرحيم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 38, NULL, 'Support us, assist us as we walk through this path that is straight, that is wide, and that is the only path that elevates us towards You. Bring us into this fast lane. Help us move along this fast lane. Help us see things clearly as we rise above this دُنْيَا and move towards You, and then protect us from falling ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ck into this دُنْيَا. This is the أُنْ, the assistance that we beg for daily in our five daily prayers.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'support us assist us as we walk through this path that is straight that is wide and that is the only path that elevates us towards you bring us into this fast lane help us move along this fast lane help us see things clearly as we rise above this دنيا and move towards you and then protect us from falling بسم الله الرحمن الرحيم ck into this دنيا this is the ان the assistance that we beg for daily in our five daily prayers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 39, NULL, 'Then we say, صِرَطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ, the path of those whom You bestowed Your favors upon. Now, what''s interesting is that this verse, it actually uses the past tense. Right? On the path of those on whom you bestowed your favours. So why the past tense? The reason is because all these role models, they exist in the past.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'then we say صرط الذين انعمت عليهم the path of those whom you bestowed your favors upon now whats interesting is that this verse it actually uses the past tense right on the path of those on whom you bestowed your favours so why the past tense the reason is because all these role models they exist in the past', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 40, NULL, 'So you know, if you''re a student and you want to get some good career advice, who do you seek that advice from? Do you seek it from your fellow students or do you seek that advice from graduates? Obviously the graduates, right? You''re not going to ask your friend who is studying with you in the same school, in the same class, about career advice. So if you want to become a doctor, you''ll take advice from graduate doctors, you know. What course did you take? How did you get into this program? What are the things that I need to focus on?', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'so you know if youre a student and you want to get some good career advice who do you seek that advice from do you seek it from your fellow students or do you seek that advice from graduates obviously the graduates right youre not going to ask your friend who is studying with you in the same school in the same class about career advice so if you want to become a doctor youll take advice from graduate doctors you know what course did you take how did you get into this program what are the things that i need to focus on', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 41, NULL, 'So the verse says, the path of those on whom you showered your blessings, the path of the prophets, the path of the messengers, the path of the martyrs, all these righteous people, right? The word أَنْعَمْتَ actually comes from the root word نِعَمْ, which means something that is smooth and soft, right? There''s this word in Arabic for cattle, you know, cows and sheep. In Arabic they''re called أَنْعَمْتَ because they walk very slowly, they walk in a gentle manner. So this verse is identifying and specifying the path that was requested in the previous verse. You know, when we said, oh اللَّه, guide us on this path, towards this path of spiritual elevation, what is that path? It is the path of those who were successful in reaching you, those who got through the trials of this world in a soft and smooth manner and achieved spiritual elevation.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'so the verse says the path of those on whom you showered your blessings the path of the prophets the path of the messengers the path of the martyrs all these righteous people right the word انعمت actually comes from the root word نعم which means something that is smooth and soft right theres this word in arabic for cattle you know cows and sheep in arabic theyre called انعمت because they walk very slowly they walk in a gentle manner so this verse is identifying and specifying the path that was requested in the previous verse you know when we said oh الله guide us on this path towards this path of spiritual elevation what is that path it is the path of those who were successful in reaching you those who got through the trials of this world in a soft and smooth manner and achieved spiritual elevation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 42, NULL, 'That is... then we say... not on the path of those who received your wrath, your غَضَبٌ, who became the recipients of your anger, and not on the path of those who are lost. Now this is really interesting, because when the verse talked about blessings, right, when it talked about نِعْمَةٌ, أَنْعَمْتَ عَلَيْهِمْ, the verse reads, صِرَطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ, the path on whom you showered your blessings, right? But when it came to غَضَبٌ, اللَّه says, ٱلْمَغْضُوبِ عَلَيْهِمْ, the ones who receive the غَضَبٌ. You see that? It leaves out the subject. It just says those who received your anger. Not those that you were angry upon, but those who received your anger. See, when I say he got beaten, the question that comes up is who did the beating? It could be one, it could be many, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'that is then we say not on the path of those who received your wrath your غضب who became the recipients of your anger and not on the path of those who are lost now this is really interesting because when the verse talked about blessings right when it talked about نعمه انعمت عليهم the verse reads صرط الذين انعمت عليهم the path on whom you showered your blessings right but when it came to غضب الله says المغضوب عليهم the ones who receive the غضب you see that it leaves out the subject it just says those who received your anger not those that you were angry upon but those who received your anger see when i say he got beaten the question that comes up is who did the beating it could be one it could be many right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 43, NULL, 'So what this is telling us is that those who receive اللَّه''s anger, they''re not just receiving اللَّه''s anger, they''re receiving the anger of messengers, the anger of angels, the anger of other believers, the anger of the heavens, the earth, right? They''re receiving the wrath and the anger from all directions. And so this verse, it does not mention اللَّه when it talks about غَضَب, but it specifically mentions اللَّه when it talks about blessings, the ones you showered blessings upon. But it is not those who you became angry with, because anger and غَضَبٌ was never the intention of اللَّه to begin with, because He is a الرَّحْمَٰن. So whatever they did, they did it to themselves. You see, they earned it for themselves. But the ones who received blessings, اللَّه helped them along the way towards the right path, you know, with the help of instructions, with the help of guidance, through messengers, through all of these intermediaries, and then also by helping them along the way with His هُدًى, with His knowledge.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'so what this is telling us is that those who receive اللهs anger theyre not just receiving اللهs anger theyre receiving the anger of messengers the anger of angels the anger of other believers the anger of the heavens the earth right theyre receiving the wrath and the anger from all directions and so this verse it does not mention الله when it talks about غضب but it specifically mentions الله when it talks about blessings the ones you showered blessings upon but it is not those who you became angry with because anger and غضب was never the intention of الله to begin with because he is a الرحمن so whatever they did they did it to themselves you see they earned it for themselves but the ones who received blessings الله helped them along the way towards the right path you know with the help of instructions with the help of guidance through messengers through all of these intermediaries and then also by helping them along the way with his هدي with his knowledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 44, NULL, 'So in other words, it means on the path of those who you granted blessings. And what is that blessing? We talked about this earlier, that''s knowledge. So essentially this is saying on the path of those that whom you granted knowledge, the knowledge of realities, and then the ones whom you granted the examples of how to put that knowledge into action through role models like رَسُولُ اللَّهِ, through مَوْلَانَا عَلِي, through the الْإِمَامُ, through the الدُّعَاءُ, and then that personal divine companionship along the way. All of that is encapsulated in صِرَطَ ٱلَّذِينَ أَنْعَمْتَ عَلَيْهِمْ. Not on the path of those whom you gave knowledge but they chose not to act upon it, and not on the path of those who act but they have no knowledge of what they''re doing. ضَالِّينَ means the one who is lost, who does not know any better. And notice that the word سِرَاطَ is not used with ٱلْمَغْضُوبِ عَلَيْهِمْ and it is not used with ضَالِّينَ. You see, it''s only used with أَنْعَمْتَ عَلَيْهِمْ, because that is the صِرَاطَ الْمُسْتَقِيمَ, the one that has the blessings of اللَّه.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'so in other words it means on the path of those who you granted blessings and what is that blessing we talked about this earlier thats knowledge so essentially this is saying on the path of those that whom you granted knowledge the knowledge of realities and then the ones whom you granted the examples of how to put that knowledge into action through role models like رسول الله through مولانا علي through the الامام through the الدعاء and then that personal divine companionship along the way all of that is encapsulated in صرط الذين انعمت عليهم not on the path of those whom you gave knowledge but they chose not to act upon it and not on the path of those who act but they have no knowledge of what theyre doing ضالين means the one who is lost who does not know any better and notice that the word سراط is not used with المغضوب عليهم and it is not used with ضالين you see its only used with انعمت عليهم because that is the صراط المستقيم the one that has the blessings of الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 45, NULL, 'Now, let me try to explain this difference between ٱلْمَغْضُوبِ عَلَيْهِمْ and ضَالِّينَ with a simple example. So I have two children, right? I have Eram and Amir. Eram is 13, Amir is 7. So, you know, they both love chocolate chip cookies, right? So I buy a fresh box from the store and, you know, I give that box to Eram and I say, both of them, I put that box in front of both of them and I say, look guys, I know this is your favorite cookie and, you know, can you see how nice this is and how fresh it looks? Right here, smell it, smell it, right? So I put that in front of them and then I tell them, look, all of this stuff is so cool, but you cannot have them. I''m going to place this right here on the table right in front of you. And then I''m going to go downstairs in my ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sement to record this session on فَاتِحَة. And when I come ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ck, we will eat these together because I brought it for all of us to share together. But until I return, don''t touch these cookies. I''m telling Eram this, right, because she''s the older one.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'now let me try to explain this difference between المغضوب عليهم and ضالين with a simple example so i have two children right i have eram and amir eram is 13 amir is 7 so you know they both love chocolate chip cookies right so i buy a fresh box from the store and you know i give that box to eram and i say both of them i put that box in front of both of them and i say look guys i know this is your favorite cookie and you know can you see how nice this is and how fresh it looks right here smell it smell it right so i put that in front of them and then i tell them look all of this stuff is so cool but you cannot have them im going to place this right here on the table right in front of you and then im going to go downstairs in my بسم الله الرحمن الرحيم sement to record this session on فاتحه and when i come بسم الله الرحمن الرحيم ck we will eat these together because i brought it for all of us to share together but until i return dont touch these cookies im telling eram this right because shes the older one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 46, NULL, 'And I''m also telling her, make sure Amir does not eat them as well, because he''s still a kid. Right? So I explain all of this to Eram and then I go in the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎sement, I do my session, right? And then I come ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎ck upstairs and what do I find? I find these two cookie monsters sitting on the couch, right? They''re both just wolfing all of these cookies down. Now, who am I going to get mad at? Eram or Amir? Obviously Eram. Why? Because I explicitly, very clearly told her not to eat those cookies. I did not tell Amir.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'and im also telling her make sure amir does not eat them as well because hes still a kid right so i explain all of this to eram and then i go in the بسم الله الرحمن الرحيم sement i do my session right and then i come بسم الله الرحمن الرحيم ck upstairs and what do i find i find these two cookie monsters sitting on the couch right theyre both just wolfing all of these cookies down now who am i going to get mad at eram or amir obviously eram why because i explicitly very clearly told her not to eat those cookies i did not tell amir', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 47, NULL, 'He doesn''t know what''s going on, right? But I specifically told Eram not to eat the cookies. So obviously, I''m going to be a lot more angry with her because, you know, she knew better. I''ll tell her that, I''ll say, I clearly told you not to eat these cookies and you still disobeyed me. Right? And while I''m shouting at her and scolding her, Amir is looking at me innocently and he''s still like eating these cookies. But you understand the difference, right? The difference between ٱلْمَغْضُوبِ عَلَيْهِمْ and ضَالِّينَ is that the مَغْضُوب are the ones who were given the نِعْمَة of knowledge. They were shown the right path and they still chose to disobey اللَّه. They still chose to do the wrong thing. But ضَالِّينَ are the ones who had no clue that they were doing the wrong thing. It doesn''t mean that they''re innocent.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'he doesnt know whats going on right but i specifically told eram not to eat the cookies so obviously im going to be a lot more angry with her because you know she knew better ill tell her that ill say i clearly told you not to eat these cookies and you still disobeyed me right and while im shouting at her and scolding her amir is looking at me innocently and hes still like eating these cookies but you understand the difference right the difference between المغضوب عليهم and ضالين is that the مغضوب are the ones who were given the نعمه of knowledge they were shown the right path and they still chose to disobey الله they still chose to do the wrong thing but ضالين are the ones who had no clue that they were doing the wrong thing it doesnt mean that theyre innocent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 48, NULL, 'It doesn''t mean that they will not be taken to account, because اللَّه gave all of us intellects, right? Which is a proof and a حُجَّة for and against each and every one of us. Right? It is a proof that we need to seek knowledge. So, "Oh, I just didn''t know" is not a good enough excuse, because that''s what the intellect was given to you for, so that you would gain knowledge. So the are the people who should have strived to gain the necessary knowledge of اللَّه and then do the right thing. They should have made that effort to know better. So they''re not off the hook by any sense, but they''re still better than . which are the people who absolutely knew what the right thing to do was and they still chose not to do it. So that''s the difference between these two terms. So this is the real message of فَاتِحَة, this bأَلَاnce between knowledge and action.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'it doesnt mean that they will not be taken to account because الله gave all of us intellects right which is a proof and a حجه for and against each and every one of us right it is a proof that we need to seek knowledge so oh i just didnt know is not a good enough excuse because thats what the intellect was given to you for so that you would gain knowledge so the are the people who should have strived to gain the necessary knowledge of الله and then do the right thing they should have made that effort to know better so theyre not off the hook by any sense but theyre still better than which are the people who absolutely knew what the right thing to do was and they still chose not to do it so thats the difference between these two terms so this is the real message of فاتحه this bالاnce between knowledge and action', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 49, NULL, 'Right? So, بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ الرَّحْمَٰنِ الرَّحِيمِ مَالِكِ يَوْمِ الدِّينِ. These verses are all about knowledge. These are all about seeking knowledge of our Master, getting to know Him, getting to understand Him, understand what He wants, why He created us, what does He want from us? What''s this concept of mastery? What''s this concept of slavery? And what are the advantage of عُبُودِيَّة? And how can we achieve freedom through this? And this idea that we are the ones in need of Him, because He has something that He can give to us that we want, rather than Him wanting us to do something. So that is all encapsulated in these verses. And then we have . This is our recognition and our acceptance of this knowledge being the one true knowledge.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'right so بسم الله الرحمن الرحيم الحمد لله رب العالمين الرحمن الرحيم مالك يوم الدين these verses are all about knowledge these are all about seeking knowledge of our master getting to know him getting to understand him understand what he wants why he created us what does he want from us whats this concept of mastery whats this concept of slavery and what are the advantage of عبوديه and how can we achieve freedom through this and this idea that we are the ones in need of him because he has something that he can give to us that we want rather than him wanting us to do something so that is all encapsulated in these verses and then we have this is our recognition and our acceptance of this knowledge being the one true knowledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 50, NULL, 'You know, and us making a commitment to اللَّه, and after that we have: guide us to the only straight and wide path of knowledge that elevates us and brings us closer towards You. Right? Guide us to the path of إِيمَان, give us the ultimate gift of إِيمَان through the path of الْإِسْلَام, which is Your ultimate blessing. This path that is this religion that is the perfect bأَلَاnce between knowledge and action. So guide us along this path through the examples of role models of the people of the past that You have favored, the ones who were wise, who had wisdom. You remember the definition of wisdom: to have correct knowledge and then to act upon it. That''s a wise person, who has the knowledge and then acts upon it. So make us among those people, of these role models of the past, that when they were provided knowledge they acted upon it. Do not make us among those who gain knowledge but then do not act upon that knowledge, because those are the people who will receive Your wrath from all directions on the Day of Judgment, because of the ‏بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِ ‎d decisions that they made. And do not make us from among those who act without knowledge, because they are the ones who are lost. So the essence of سُورَةُ الْفَاتِحَةِ is this bأَلَاnce between these two things. It is bأَلَاncing الْحَمْد with أَمَلٌ, knowledge with action. It is, you know, bأَلَاncing, it is the bأَلَاnce between gaining the knowledge of اللَّه, right, striving to acquire the knowledge of His تَوْحِيد, making a commitment, this promise, this أَهْدِ, which has to come before the action, and only after that comes the instructions, right, the هِدَايَةٌ.', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'you know and us making a commitment to الله and after that we have guide us to the only straight and wide path of knowledge that elevates us and brings us closer towards you right guide us to the path of ايمان give us the ultimate gift of ايمان through the path of الاسلام which is your ultimate blessing this path that is this religion that is the perfect bالاnce between knowledge and action so guide us along this path through the examples of role models of the people of the past that you have favored the ones who were wise who had wisdom you remember the definition of wisdom to have correct knowledge and then to act upon it thats a wise person who has the knowledge and then acts upon it so make us among those people of these role models of the past that when they were provided knowledge they acted upon it do not make us among those who gain knowledge but then do not act upon that knowledge because those are the people who will receive your wrath from all directions on the day of judgment because of the بسم الله الرحمن الرحيم d decisions that they made and do not make us from among those who act without knowledge because they are the ones who are lost so the essence of سوره الفاتحه is this bالاnce between these two things it is bالاncing الحمد with امل knowledge with action it is you know bالاncing it is the bالاnce between gaining the knowledge of الله right striving to acquire the knowledge of his توحيد making a commitment this promise this اهد which has to come before the action and only after that comes the instructions right the هدايه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'guidance to the straight path', 'Guidance To The Straight Path', 51, NULL, 'And then we ask اللَّه to make us among those who created this bأَلَاnce between knowledge and action. And this is why Maulana Ali says knowledge without action is a cأَلَاmity on the soul, and action without knowledge is pure ignorance, it''s perversion. So success, it lies in the middle. It lies at the center of this bأَلَاnce between knowledge and action. That is the true manifestation of أَبْهُدِيَّة. A slave who obeys through knowledge, who strives to understand the wisdom of his master''s commands and then practically acts upon it, realizing that this is for his own benefit. And that is the entire essence of سُورَةُ الْفَاتِحَةِ. وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ سَيِّدِنَا مُحَمَّدٍ خَاتِمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ، وَالْآلِ وَالْوَصِيِّ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ، وَإِلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِ الطَّيِّبِينَ الطَّاهِرِينَ، وَالسَّلَامُ عَلَيْهِمْ أَجْمَعِينَ، الْفَاتِحَة', '', NULL, NULL, NULL, NULL, 'surah al fateha guidance to the straight path', 'and then we ask الله to make us among those who created this bالاnce between knowledge and action and this is why maulana ali says knowledge without action is a cالاmity on the soul and action without knowledge is pure ignorance its perversion so success it lies in the middle it lies at the center of this bالاnce between knowledge and action that is the true manifestation of ابهديه a slave who obeys through knowledge who strives to understand the wisdom of his masters commands and then practically acts upon it realizing that this is for his own benefit and that is the entire essence of سوره الفاتحه واخر دعوانا ان الحمد لله رب العالمين والصلاه والسلام علي رسول سيدنا محمد خاتم النبيين وسيد المرسلين والال والوصي علي بن ابي طالب اشرف الوصيين والي الايمه من ذريته الطيبين الطاهرين والسلام عليهم اجمعين الفاتحه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 0, NULL, 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ اللَّهُمَّ صَلِّ عَلَى سَيِّدِنَا مُحَمَّدٍ وَعَلَى آلِ سَيِّدِنَا مُحَمَّدٍ كَمَا صَلَّيْتَ وَسَلَّمْتَ وَبَارَكْتَ وَرَحِمْتَ وَتَرَحَّمْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ So now that we''ve completed سُورَةُ الْفَاتِحَةِ I wanted to do a session on this idea of اِسْتِقَامَة which is remaining steadfast on the straight path and this is one of the major challenges of walking the path and it is something that we all probably can relate to we all as Muslims we want to do the right thing we want the straight path but we''re not always able to for various different reasons and then we end up getting frustrated with ourselves and sometimes with religion itself. Now this is something that I have personally struggled with extensively in my life. But then الْحَمْدُ لِلَّهِ I came across some material and some perspectives that has helped me a lot. And so I thought I would like to share that with you hoping and praying that it will do the same for you. In سُورَةُ الْفَاتِحَةِ we request اللَّهُ سُبْحَانَهُ وَتَعَالَى for guidance we say guide us towards the straight path now this verse is the essence of the Surah the initial verses they are basically building up to this one right giving us an understanding of who اللَّهُ is الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ الرَّحْمَٰنِ الرَّحِيمِ مَالِكِ يَوْمِ الدِّينِ but this is it is called the prayer of all prayers. Guide us, guidance. Guide us through instructions, role models and then through your divine companionship. Now the question is what exactly is صِرَاطَ الْمُسْتَقِيمَ? اللَّهُ actually defines it for us in سُورَةُ يَاسِين.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم اللهم صل علي سيدنا محمد وعلي ال سيدنا محمد كما صليت وسلمت وباركت ورحمت وترحمت علي ابراهيم وعلي ال ابراهيم في العالمين انك حميد مجيد السلام عليكم ورحمه الله وبركاته so now that weve completed سوره الفاتحه i wanted to do a session on this idea of استقامه which is remaining steadfast on the straight path and this is one of the major challenges of walking the path and it is something that we all probably can relate to we all as muslims we want to do the right thing we want the straight path but were not always able to for various different reasons and then we end up getting frustrated with ourselves and sometimes with religion itself now this is something that i have personally struggled with extensively in my life but then الحمد لله i came across some material and some perspectives that has helped me a lot and so i thought i would like to share that with you hoping and praying that it will do the same for you in سوره الفاتحه we request الله سبحانه وتعالي for guidance we say guide us towards the straight path now this verse is the essence of the surah the initial verses they are basically building up to this one right giving us an understanding of who الله is الحمد لله رب العالمين الرحمن الرحيم مالك يوم الدين but this is it is called the prayer of all prayers guide us guidance guide us through instructions role models and then through your divine companionship now the question is what exactly is صراط المستقيم الله actually defines it for us in سوره ياسين', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 1, NULL, 'where he says and no doubt about it you should worship me for that is the straight path so عِبَادَة or عُبُودِيَّة the willing submission is how اللَّهُ defines the straight path The person who willingly submits himself or herself to اللَّهُ is the one who has found the straight path, which الْحَمْدُ لِلَّهِ we all have. But now the big question is how do we walk the path? Because we never get to our destination by just finding the correct path. We get to it by actually walking it, right? So how do we walk this path? And what is the term? Is there a term for walking this path? There is. And that term is called تَقْوَى, which is a strong mindfulness for the presence of اللَّهُ in our lives. تَقْوَى, commonly translated as piety, is essential for أَبُو دِيَّة, for attaining the ranks of servitude. And that is exactly what we asked for when we said, ‏إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ ‎ It is only you we worship Again, worship being the straight path.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'where he says and no doubt about it you should worship me for that is the straight path so عباده or عبوديه the willing submission is how الله defines the straight path the person who willingly submits himself or herself to الله is the one who has found the straight path which الحمد لله we all have but now the big question is how do we walk the path because we never get to our destination by just finding the correct path we get to it by actually walking it right so how do we walk this path and what is the term is there a term for walking this path there is and that term is called تقوي which is a strong mindfulness for the presence of الله in our lives تقوي commonly translated as piety is essential for ابو ديه for attaining the ranks of servitude and that is exactly what we asked for when we said اياك نعبد واياك نستعين it is only you we worship again worship being the straight path', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 2, NULL, 'And it is only you we seek help from. اسْتَعَانَ, right? What is this method of اسْتَعَانَ? Seeking اللَّهُs help? اللَّهُ explains that in سُورَةُ الْبَقَرَةِ. He says, وَأَسْتَعِينُ بِالصَّبْرِ وَالصَّلَاةِ and seek my help through patience and prayer and the same word is used أَسْتَعِينُ so we have now just solved this equation right we all desire صِرَاطَ الْمُسْتَقِيمَ the straight path مُسْتَقِيم as I explained earlier a path that has اِسْتَقَامَ built into it right a path of spiritual elevation How is that achieved? Through عُبُودِيَّة, willing servitude to the will of اللَّهُ. How do we walk this path? By developing piety, by developing تَقْوَى, an acute awareness of who اللَّهُ is, by establishing a connection with Him. And how do we connect with Him?', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'and it is only you we seek help from استعان right what is this method of استعان seeking اللهs help الله explains that in سوره البقره he says واستعين بالصبر والصلاه and seek my help through patience and prayer and the same word is used استعين so we have now just solved this equation right we all desire صراط المستقيم the straight path مستقيم as i explained earlier a path that has استقام built into it right a path of spiritual elevation how is that achieved through عبوديه willing servitude to the will of الله how do we walk this path by developing piety by developing تقوي an acute awareness of who الله is by establishing a connection with him and how do we connect with him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 3, NULL, 'بِالصَّبْرِ وَالصَّلَاةِ, through patience and through prayer. Now we all know about the daily prayers. But what does صَبْر mean here in this context? It means to be steadfast and consistent with our prayers. And then the آيَاتٌ continues to say, And no doubt about it, for sure, this is truly an extremely difficult task for most people. إِلَّا, except, those who possess the knowledge and who possess the knowledge and the awareness of the majesty of their master. People who have تَقْوَى. So it all ultimately boils down to consistency and being steadfast, اِسْتَقَامَة. Now what is اِسْتَقَامَة? It comes from the same root word أَمَا That was used for مُسْتَقِيم, صِرَاطُ الْمُسْتَقِيمِ, the same root word, قَامَ.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'بالصبر والصلاه through patience and through prayer now we all know about the daily prayers but what does صبر mean here in this context it means to be steadfast and consistent with our prayers and then the ايات continues to say and no doubt about it for sure this is truly an extremely difficult task for most people الا except those who possess the knowledge and who possess the knowledge and the awareness of the majesty of their master people who have تقوي so it all ultimately boils down to consistency and being steadfast استقامه now what is استقامه it comes from the same root word اما that was used for مستقيم صراط المستقيم the same root word قام', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 4, NULL, 'So اِسْتَقِمْ means to stay firm on something. And how do we stay firm? اللَّهُ answers that in the قُرْآن when He says, . He says, establish the prayer, be firm, stay firm on your prayer, stay firm on your صَلَاةٌ. So اِسْتِقَامَة is to establish something firmly or to be solid in something, to be firm in it. Right? So resilience is one of the words that is used. Grit, some people use the word grit. But اِسْتِقَامَة is essentially the ability to stand firm and be consistent in our إِيمَان, in our worship and our belief. To give you sort of a visual representation from the physical world of the اِسْتِقَامَة, think about a solid tree. A solid tree, it stands firm even when the wind blows, right? Even if a storm hits it, it stays its ground.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'so استقم means to stay firm on something and how do we stay firm الله answers that in the قران when he says he says establish the prayer be firm stay firm on your prayer stay firm on your صلاه so استقامه is to establish something firmly or to be solid in something to be firm in it right so resilience is one of the words that is used grit some people use the word grit but استقامه is essentially the ability to stand firm and be consistent in our ايمان in our worship and our belief to give you sort of a visual representation from the physical world of the استقامه think about a solid tree a solid tree it stands firm even when the wind blows right even if a storm hits it it stays its ground', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 5, NULL, 'Now, the question we''re trying to address is, how can we be like that? How do we develop the ability to stay strong on this path despite the storms of our situations, of our challenges, of our environments? So you must have noticed if you read the قُرْآن that in many verses اللَّهُ سُبْحَانَهُ وَتَعَالَى, He always mentions two things when He talks about faith. He always couples إِيمَان with أَمَلْ. He couples faith with action. So we understand that there are two parts to what we are supposed to do. There is the inner part and then there''s the outer part. What''s the inner part? It''s the belief, the إِيمَان, the faith. Another way we can think about this in terms of عِبَادَة is that there is a worship for the heart and then there is a worship for the limbs. The body, the tongue, the ears, the eyes. You understand?', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'now the question were trying to address is how can we be like that how do we develop the ability to stay strong on this path despite the storms of our situations of our challenges of our environments so you must have noticed if you read the قران that in many verses الله سبحانه وتعالي he always mentions two things when he talks about faith he always couples ايمان with امل he couples faith with action so we understand that there are two parts to what we are supposed to do there is the inner part and then theres the outer part whats the inner part its the belief the ايمان the faith another way we can think about this in terms of عباده is that there is a worship for the heart and then there is a worship for the limbs the body the tongue the ears the eyes you understand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 6, NULL, 'There are the internal عِبَادَات and then there are the external عِبَادَات. The internal has to do with our belief system, with our إِيمَان. How do we think of اللَّهُ? How do we view Him? How do we respond internally with the things that He has asked us to do? And why He has asked us to do those. That''s all internal. It has to do with our certainty or with our doubt, right? So certainty is يَقِين, doubt is شَقَّ. So we are either certain about it or we have doubts about it. But that all has to do with our internal mechanism, our internal worship system. What are the external عِبَادَات?', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'there are the internal عبادات and then there are the external عبادات the internal has to do with our belief system with our ايمان how do we think of الله how do we view him how do we respond internally with the things that he has asked us to do and why he has asked us to do those thats all internal it has to do with our certainty or with our doubt right so certainty is يقين doubt is شق so we are either certain about it or we have doubts about it but that all has to do with our internal mechanism our internal worship system what are the external عبادات', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 7, NULL, 'Those are the obvious ones, the five time prayers, reading قُرْآن, you know, guarding our ears, eyes, all of that, you know, these are all external type of عِبَادَات. Now, if I asked you, what do you think is essential for اِسْتِقَامَة? Is it the internal or the external? What would you say is essential for اِسْتِقَامَة? Our Prophet صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ in a حَدِيثٌ, he stated, إِنَّ فِي الْجَسَدِ مُضْغَةً، إِذَا صَلُحَتْ صَلُحَ الْجَسَدُ كُلُّهُ، وَإِذَا فَسَدَتْ فَسَدَ الْجَسَدُ كُلُّهُ، أَلَا وَهِيَ الْقَلْبُ Indeed, within the body, there is a lump of flesh. إِذَا صَلُحَتْ صَلَحَ الْجَسَدُ كُلُّهُ If it is set right, if it is set straight, then the entire body will be set right.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'those are the obvious ones the five time prayers reading قران you know guarding our ears eyes all of that you know these are all external type of عبادات now if i asked you what do you think is essential for استقامه is it the internal or the external what would you say is essential for استقامه our prophet صلي الله عليه وسلم in a حديث he stated ان في الجسد مضغه اذا صلحت صلح الجسد كله واذا فسدت فسد الجسد كله الا وهي القلب indeed within the body there is a lump of flesh اذا صلحت صلح الجسد كله if it is set right if it is set straight then the entire body will be set right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 8, NULL, 'But if it is corrupted, then the entire body will be corrupted. Indeed, beware it is the heart. So what we''re learning from this حَدِيثٌ is that the master of the body isn''t actually the mind. Which sounds a bit strange because many people believe that the mind is what is in control. Well, news flash. It''s actually your heart that is in control. It''s your heart that controls your mind. Now what do I mean by that? The type of heart that you have will control your thoughts. It''ll control your mind and eventually it''ll control your actions. So whatever your heart truly desires, your mind will think of ways to fulfill those desires. And then the limbs will actually make it happen.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'but if it is corrupted then the entire body will be corrupted indeed beware it is the heart so what were learning from this حديث is that the master of the body isnt actually the mind which sounds a bit strange because many people believe that the mind is what is in control well news flash its actually your heart that is in control its your heart that controls your mind now what do i mean by that the type of heart that you have will control your thoughts itll control your mind and eventually itll control your actions so whatever your heart truly desires your mind will think of ways to fulfill those desires and then the limbs will actually make it happen', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 9, NULL, 'They will execute it. You see? So the heart is the king. What the king wants needs to happen. Who helps the king figure out how to make it happen? That''s the وَزِير, that''s the mind, right? That''s the brain. And then there is the army, which is the limbs that actually carry out and execute what the وَزِير comes up with for the king. So the mind actually becomes a tool, an instrument to execute whatever is in the heart. And this is why our Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, he said if you take care of this lump of flesh, which is the heart. Now everyone be clear that when I say the heart, I''m not talking about the physical heart, right? I''m talking about the spiritual heart, the قَلْب. So if this heart is purified, when you take care of that heart, when you feed the heart, when you rectify the heart, then all your actions will automatically become pure. But when the heart is corrupted, when it is starved, when it''s not taken care of, when it is deprived of its spiritual sustenance, then the rest of the actions will just naturally get corrupted. And what''s really interesting, that if you look at, like, if you want to see this theory in its practical form, let''s look at the chronological theme of revelation. Just think about how the قُرْآن was revealed.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'they will execute it you see so the heart is the king what the king wants needs to happen who helps the king figure out how to make it happen thats the وزير thats the mind right thats the brain and then there is the army which is the limbs that actually carry out and execute what the وزير comes up with for the king so the mind actually becomes a tool an instrument to execute whatever is in the heart and this is why our prophet صلي الله عليه وسلم he said if you take care of this lump of flesh which is the heart now everyone be clear that when i say the heart im not talking about the physical heart right im talking about the spiritual heart the قلب so if this heart is purified when you take care of that heart when you feed the heart when you rectify the heart then all your actions will automatically become pure but when the heart is corrupted when it is starved when its not taken care of when it is deprived of its spiritual sustenance then the rest of the actions will just naturally get corrupted and whats really interesting that if you look at like if you want to see this theory in its practical form lets look at the chronological theme of revelation just think about how the قران was revealed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 10, NULL, 'What were the first verses to be revealed? They were not about drinking alcohol and they were not about preventing people from committing fornication. They were not about the rules of حَلَالٌ and حَرَامٌ. The first verses to be revealed were all about building تَقْوَى of اللَّهُ سُبْحَانَهُ وَتَعَالَى. They were all about building an attachment with اللَّهُ سُبْحَانَهُ وَتَعَالَى, about understanding the Day of Judgment, realizing and learning that we will be taken to account for our actions, that we''re not just living in this life without a purpose like animals, that there is a purpose to اللَّهُs تَوْحِيدٌ, there is a purpose to اللَّهُs oneness. So the initial verses of revelation were about, you know, the Day of Judgment, they were about retribution, they were about loving اللَّهُ, they were about understanding what اللَّهُ has done for us, it was about understanding what اللَّهُ wants from us, about life and death, about, you know, basically who He is and what He wants. Why? Because all those initial verses of revelation, they were building a foundation for us, they were setting the foundation of اِسْتِقَامَة.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'what were the first verses to be revealed they were not about drinking alcohol and they were not about preventing people from committing fornication they were not about the rules of حلال and حرام the first verses to be revealed were all about building تقوي of الله سبحانه وتعالي they were all about building an attachment with الله سبحانه وتعالي about understanding the day of judgment realizing and learning that we will be taken to account for our actions that were not just living in this life without a purpose like animals that there is a purpose to اللهs توحيد there is a purpose to اللهs oneness so the initial verses of revelation were about you know the day of judgment they were about retribution they were about loving الله they were about understanding what الله has done for us it was about understanding what الله wants from us about life and death about you know basically who he is and what he wants why because all those initial verses of revelation they were building a foundation for us they were setting the foundation of استقامه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 11, NULL, 'So now if we go back to the example of the صَلَاة tree, اللَّهُ سُبْحَانَهُ وَتَعَالَى says in سُورَةُ إِبْرَاهِيمَ, when He gives the example of a good word, He says that a good word is like a good tree. ‏أَلَمْ تَرَ كَيْفَ ضَرَبَ ٱللَّهُ مَثَلًۭا كَلِمَةًۭ طَيِّبَةًۭ كَشَجَرَةٍۢ طَيِّبَةٍ أَصْلُهَا ثَابِتٌۭ وَفَرْعُهَا فِى ٱلسَّمَآءِ ‎. Do you not see how اللَّهُ sets forth the example of a good word, which is like a fruitful tree? Its roots are firmly fixed into the earth and its branches rise up to the sky. So in other words, its foundation is solid. That''s what the word اللَّهُ uses. And then its branches rise up towards the sky. See, you can become elevated. Right, you can grow, you can get higher, you can force yourself into a path of spiritual elevation, but if you don''t have solid roots, it''s not gonna last long, and this is what happens with so many people.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'so now if we go back to the example of the صلاه tree الله سبحانه وتعالي says in سوره ابراهيم when he gives the example of a good word he says that a good word is like a good tree الم تر كيف ضرب الله مثلا كلمه طيبه كشجره طيبه اصلها ثابت وفرعها في السماء do you not see how الله sets forth the example of a good word which is like a fruitful tree its roots are firmly fixed into the earth and its branches rise up to the sky so in other words its foundation is solid thats what the word الله uses and then its branches rise up towards the sky see you can become elevated right you can grow you can get higher you can force yourself into a path of spiritual elevation but if you dont have solid roots its not gonna last long and this is what happens with so many people', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 12, NULL, 'And this is something that I have struggled with myself, so I can actually speak from experience, that I can, I have forced myself into the prayers, fasting and this and that, and I do it for a while and I push myself and I push myself and I just grit my teeth and I do it, but doesn''t last. Something happens and suddenly everything goes out the window. And this was happening for a while until I finally understood these things, because what I realized is that the taller a tree gets, the deeper its roots have to go. So if you study the way اللَّهُ has designed a tree, you''ll see that the taller it is, the more deep and wide its roots are spread within the earth. In fact, even mountains we know have foundations, and the taller it is, the more it is grounded within the earth. Everything, anything in existence, in order for it to be solid and firm and to have اِسْتِقَامَة, it must have a solid foundation.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'and this is something that i have struggled with myself so i can actually speak from experience that i can i have forced myself into the prayers fasting and this and that and i do it for a while and i push myself and i push myself and i just grit my teeth and i do it but doesnt last something happens and suddenly everything goes out the window and this was happening for a while until i finally understood these things because what i realized is that the taller a tree gets the deeper its roots have to go so if you study the way الله has designed a tree youll see that the taller it is the more deep and wide its roots are spread within the earth in fact even mountains we know have foundations and the taller it is the more it is grounded within the earth everything anything in existence in order for it to be solid and firm and to have استقامه it must have a solid foundation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 13, NULL, 'And so اللَّهُ is telling us, and even in the training that He gives us, He did not start out with the rules, He started out with building our foundation. And this is why سُورَةُ الْفَاتِحَةِ, which is essentially the summary of the entire قُرْآن, right? It''s a description of what you are about to find in the remaining 113 سُورَةُ الْفَاتِحَةِ. It begins, look how سُورَةُ الْفَاتِحَةِ begins, by creating an understanding of who اللَّهُ is. الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ، الرَّحْمَٰنِ الرَّحِيمِ، مَالِكِ يَوْمِ الدِّينِ. These are all verses about knowing اللَّهُ, about setting this foundation. And once this foundation is built, which will naturally engender تَقْوَى and تَوَكُّل, which is, you know, our reliance and trust in اللَّهُ, only then we are taught to ask for the rules and guidance. But look at the order of these verses, right? The beginning verses are designed to build a solid foundation.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'and so الله is telling us and even in the training that he gives us he did not start out with the rules he started out with building our foundation and this is why سوره الفاتحه which is essentially the summary of the entire قران right its a description of what you are about to find in the remaining 113 سوره الفاتحه it begins look how سوره الفاتحه begins by creating an understanding of who الله is الحمد لله رب العالمين الرحمن الرحيم مالك يوم الدين these are all verses about knowing الله about setting this foundation and once this foundation is built which will naturally engender تقوي and توكل which is you know our reliance and trust in الله only then we are taught to ask for the rules and guidance but look at the order of these verses right the beginning verses are designed to build a solid foundation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 14, NULL, 'So that when the rules are revealed, we can just have اِسْتِقَامَة. You understand? If we look at the example of the tree again, when a wind blows, if the roots of the tree are deep and they are firm within the ground, what happens to the tree? Well, its leaves might move, the branches might shake and break, but the tree stays standing. Right? It''s solid. But what happens to a tree that does not have deep roots? It easily gets knocked over. And I believe that the problem with الإِسْلَامic training these days is that we are raised in such a way that we just don''t have solid roots. Our training method is the rule shaming method. It''s this rule oriented or rule shaming method. This is the method where you grow up as a kid and the only thing you are really taught about is حَرَامٌ and hellfire.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'so that when the rules are revealed we can just have استقامه you understand if we look at the example of the tree again when a wind blows if the roots of the tree are deep and they are firm within the ground what happens to the tree well its leaves might move the branches might shake and break but the tree stays standing right its solid but what happens to a tree that does not have deep roots it easily gets knocked over and i believe that the problem with الاسلامic training these days is that we are raised in such a way that we just dont have solid roots our training method is the rule shaming method its this rule oriented or rule shaming method this is the method where you grow up as a kid and the only thing you are really taught about is حرام and hellfire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 15, NULL, 'And the emphasis is on if you do حَرَامٌ, you will go to hellfire. And that''s how many of us were raised and that''s how many of us are raising our children. Well, it is true that there are things that are حَرَامٌ. It is true that there is hellfire. It is true that اللَّهُ has anger and wrath. This is all true. But why are children being taught that above His mercy? Why are we not teaching our children that اللَّهُ is the most merciful? And that even if you make a mistake, if you make a mistake and you repent, you can always try again. Why is this not the message that is being taught? And the answer, unfortunately, is because this is to control the behavior of the child. So many of us use fear as this control mechanism.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'and the emphasis is on if you do حرام you will go to hellfire and thats how many of us were raised and thats how many of us are raising our children well it is true that there are things that are حرام it is true that there is hellfire it is true that الله has anger and wrath this is all true but why are children being taught that above his mercy why are we not teaching our children that الله is the most merciful and that even if you make a mistake if you make a mistake and you repent you can always try again why is this not the message that is being taught and the answer unfortunately is because this is to control the behavior of the child so many of us use fear as this control mechanism', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 16, NULL, 'The only problem is that this might have worked maybe somewhat in my generation, more so in the previous generation, but in the new generation, it just backfires. When we''re using false fear or false shame, unhealthy shame to control someone''s behavior, we''re not building solid roots. What we''re building is avoidance. Imagine that you grew up in a household where you''re always being told, let''s take police as an example, right? You''re always being told that you better watch out for the police. They''re going to throw you in jail. Don''t make a mistake. You better not do this. You better not do that because, you know, the police is going to catch you and they''re going to throw you in jail. They''re going to punish you. So you are basically taught to be afraid of the police.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'the only problem is that this might have worked maybe somewhat in my generation more so in the previous generation but in the new generation it just backfires when were using false fear or false shame unhealthy shame to control someones behavior were not building solid roots what were building is avoidance imagine that you grew up in a household where youre always being told lets take police as an example right youre always being told that you better watch out for the police theyre going to throw you in jail dont make a mistake you better not do this you better not do that because you know the police is going to catch you and theyre going to throw you in jail theyre going to punish you so you are basically taught to be afraid of the police', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 17, NULL, 'Why? Because police is made out to be this very wrathful and scary entity. Now, if you grow up with this kind of training, years and years of this kind of material being fed to you, best case scenario, you will learn to avoid the police. That''s the best case scenario. But will you want to be close to the police? Will you want to be best friends with the police? Will you confide your problems to the police? Will you turn to the police for help when you''re in trouble? No, because you don''t trust the police and you''ve been told that they''re just there to punish you. You see? And so what''s happening is that this type of training is not building اِسْتَقَامَ. It''s not building any form of stability in our youth and in our own selves.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'why because police is made out to be this very wrathful and scary entity now if you grow up with this kind of training years and years of this kind of material being fed to you best case scenario you will learn to avoid the police thats the best case scenario but will you want to be close to the police will you want to be best friends with the police will you confide your problems to the police will you turn to the police for help when youre in trouble no because you dont trust the police and youve been told that theyre just there to punish you you see and so whats happening is that this type of training is not building استقام its not building any form of stability in our youth and in our own selves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 18, NULL, 'It''s building avoidance. So many people, when they are raised this way, when they grow up, they don''t want to have anything to do with اللَّهُ. They actually want to avoid اللَّهُ and religion completely. Because they say, you know what, everything is حَرَامٌ, no matter what I do, I''m going to end up going to hell anyway. Everything I do is wrong, so what''s the point in trying? You know, and to make it worse in our teachings and these, you know, there are some, I''ve heard someone say that, you know, if you don''t do نَمَاز this way and if you don''t do رُكوع this way and such that your نَمَاز will be thrown in your face. I mean, this is, you know, a child making an effort to actually stand up for نَمَاز. And then you tell him that, okay, so everything I do is حَرَامٌ and I''m going to get punished for it, but the good things that I do are not good enough. You tell me, why should anyone come to a religion like that?', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'its building avoidance so many people when they are raised this way when they grow up they dont want to have anything to do with الله they actually want to avoid الله and religion completely because they say you know what everything is حرام no matter what i do im going to end up going to hell anyway everything i do is wrong so whats the point in trying you know and to make it worse in our teachings and these you know there are some ive heard someone say that you know if you dont do نماز this way and if you dont do ركوع this way and such that your نماز will be thrown in your face i mean this is you know a child making an effort to actually stand up for نماز and then you tell him that okay so everything i do is حرام and im going to get punished for it but the good things that i do are not good enough you tell me why should anyone come to a religion like that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 19, NULL, 'So what happens is that everybody starts avoiding religion and اللَّهُ together, all together, because it''s backfiring. And the reason it''s backfiring is because we are trying to grow this tree of الإِسْلَام within ourselves and our children without creating any solid foundation. So even miraculously if this tree sustains long enough to grow, it then is not able to survive the smallest earthquake, you see? It cannot stand the smallest storm. So we need to focus on building a solid foundation so that when life hits us, because we are going to be shaken in life, there''s no doubt about that, I mean, look at the times we live in with all these temptations around us, these desires going crazy, right, the tree, this tree of الإِسْلَام within our hearts, it will be shaken from time to time. We will be tested through trials.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'so what happens is that everybody starts avoiding religion and الله together all together because its backfiring and the reason its backfiring is because we are trying to grow this tree of الاسلام within ourselves and our children without creating any solid foundation so even miraculously if this tree sustains long enough to grow it then is not able to survive the smallest earthquake you see it cannot stand the smallest storm so we need to focus on building a solid foundation so that when life hits us because we are going to be shaken in life theres no doubt about that i mean look at the times we live in with all these temptations around us these desires going crazy right the tree this tree of الاسلام within our hearts it will be shaken from time to time we will be tested through trials', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 20, NULL, 'That''s not something that should come as a surprise to anyone, right? That is something that اللَّهُ clearly says in the قُرْآن. Do you really think that you will enter paradise without going through that which those who came before you went through? They were struck with calamity, they were struck with adversity, they struggled, and then they were shaken. The word زُلْزِلُوا in Arabic, it actually comes from the same root as زِلْزَال, which means an earthquake. So they were shaken like an earthquake, and they were tried so much and they were shaken so much that even the messengers and those with the messengers, they started asking, when will the help of اللَّهُ arrive? Indeed, the help of اللَّهُ is near. The help of اللَّهُ isn''t just there. It doesn''t just exist as a concept. It''s there right now with you as you''re going through the test. اللَّهُ says that we are closer to you than your jugular vein. And what''s interesting about that, you know, a lot of people don''t understand what that means. That''s the verse.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'thats not something that should come as a surprise to anyone right that is something that الله clearly says in the قران do you really think that you will enter paradise without going through that which those who came before you went through they were struck with calamity they were struck with adversity they struggled and then they were shaken the word زلزلوا in arabic it actually comes from the same root as زلزال which means an earthquake so they were shaken like an earthquake and they were tried so much and they were shaken so much that even the messengers and those with the messengers they started asking when will the help of الله arrive indeed the help of الله is near the help of الله isnt just there it doesnt just exist as a concept its there right now with you as youre going through the test الله says that we are closer to you than your jugular vein and whats interesting about that you know a lot of people dont understand what that means thats the verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 21, NULL, 'What does that mean? It means that we are closer to you than your own consciousness. See, jugular vein, you cut the jugular vein, what''s the first thing that the person loses? Consciousness, right? So what that means is that we know what you are about to think before you think it. It''s that kind of proximity. So we are going to be shaken from time to time. Now, how does a building withstand an earthquake? Again, the answer all goes back to the type of foundation it has. That is what will determine its اِسْتِقَامَة. So the question we have to ask ourselves is what type of foundation do we have with اللَّهُ سُبْحَانَهُ وَتَعَالَى?', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'what does that mean it means that we are closer to you than your own consciousness see jugular vein you cut the jugular vein whats the first thing that the person loses consciousness right so what that means is that we know what you are about to think before you think it its that kind of proximity so we are going to be shaken from time to time now how does a building withstand an earthquake again the answer all goes back to the type of foundation it has that is what will determine its استقامه so the question we have to ask ourselves is what type of foundation do we have with الله سبحانه وتعالي', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 22, NULL, 'When I am tested through pain or through pleasure, will I be able to withstand it? Will I be able to be firm on the straight path? And if the honest answer to that is no, that means I need to work on my relationship with اللَّهُ, not work on the rules. Not try to increase my صَلَاةٌ or my fasting, and I need to first work on my relationship. The rules, the actions will just follow. And this is why scholars have said that the first verses that were revealed, they did not say give up alcohol and give up fornication, because people would have said, you know, we''ll never give up those things, and they would never have if it started with that, because they had not yet built a foundation with اللَّهُ. They had not yet built the roots. So if you come to a person from the very start and you give them rules, they''re just not going to follow it, because it goes against what they want. And that is the very mistake that many of us make with ourselves and with our children. I made that with myself. So we''re not building a foundation, we''re constantly throwing rules at them. We''re not talking about building an attachment with اللَّهُ, we''re not teaching them to love اللَّهُ, we''re not teaching them what it really means to put our reliance on اللَّهُ. Where is that being taught? The only thing being taught to our children is that, you know, this is حَرَامٌ, that is حَرَامٌ, it''s حَرَامٌ to eat this, it''s حَرَامٌ to drink that, it''s حَرَامٌ to dress like that, it''s حَرَامٌ to say this. I mean, that''s it, right?', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'when i am tested through pain or through pleasure will i be able to withstand it will i be able to be firm on the straight path and if the honest answer to that is no that means i need to work on my relationship with الله not work on the rules not try to increase my صلاه or my fasting and i need to first work on my relationship the rules the actions will just follow and this is why scholars have said that the first verses that were revealed they did not say give up alcohol and give up fornication because people would have said you know well never give up those things and they would never have if it started with that because they had not yet built a foundation with الله they had not yet built the roots so if you come to a person from the very start and you give them rules theyre just not going to follow it because it goes against what they want and that is the very mistake that many of us make with ourselves and with our children i made that with myself so were not building a foundation were constantly throwing rules at them were not talking about building an attachment with الله were not teaching them to love الله were not teaching them what it really means to put our reliance on الله where is that being taught the only thing being taught to our children is that you know this is حرام that is حرام its حرام to eat this its حرام to drink that its حرام to dress like that its حرام to say this i mean thats it right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 23, NULL, 'And the problem with that method is that everything about الإِسْلَام is being rejected. And that is exactly what the scholars said, right? That if you start off with the rules, if اللَّهُ had started off with the rules, even with the companions, these were the best people that existed, but even they would have rejected the rules. And this is why اللَّهُ did not start with the rules. I mean, look at جُزْءُ عَمَّ, right, the 30th chapter of قُرْآن, it''s basically Meccan, majority of the verses in that جُزْء were revealed in the initial stages of الإِسْلَام, in the first 10 years of الإِسْلَام. Where do you find rules in that? Do you find any rules? Not really. It talks about اللَّهُ, it talks about His love, His mercy, it talks about the Day of Judgment, it talks about human beings, it talks about their relationships with themselves, among themselves, with اللَّهُ, it talks about, you know, human psychology, it talks about تَقْوَى, it talks about تَوَكُّل, it talks about retribution, it teaches about جَنَّة, it teaches about جَهَنَّم, right, it focuses, you know, on all these things that are relationship building, it''s all foundation building stuff in جُزْءُ عَمَّ. Because if you want اِسْتِقَامَة, you have to build a foundation in the love of اللَّهُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'and the problem with that method is that everything about الاسلام is being rejected and that is exactly what the scholars said right that if you start off with the rules if الله had started off with the rules even with the companions these were the best people that existed but even they would have rejected the rules and this is why الله did not start with the rules i mean look at جزء عم right the 30th chapter of قران its basically meccan majority of the verses in that جزء were revealed in the initial stages of الاسلام in the first 10 years of الاسلام where do you find rules in that do you find any rules not really it talks about الله it talks about his love his mercy it talks about the day of judgment it talks about human beings it talks about their relationships with themselves among themselves with الله it talks about you know human psychology it talks about تقوي it talks about توكل it talks about retribution it teaches about جنه it teaches about جهنم right it focuses you know on all these things that are relationship building its all foundation building stuff in جزء عم because if you want استقامه you have to build a foundation in the love of الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 24, NULL, 'See, this brings me to an interesting point about تَقْوَى, that when we generally talk about تَقْوَى, we think in terms of shame and fear. Right? And you might say, well, that is a good thing, isn''t it? I mean, what''s wrong with fear? Well, interestingly, today, psychologists, they are telling us that there is healthy fear and then there is unhealthy fear.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'see this brings me to an interesting point about تقوي that when we generally talk about تقوي we think in terms of shame and fear right and you might say well that is a good thing isnt it i mean whats wrong with fear well interestingly today psychologists they are telling us that there is healthy fear and then there is unhealthy fear', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 25, NULL, 'Okay, there is healthy fear and then there is unhealthy fear. Let me give you an example. You know when you do something really bad and you''re really scared of your parents or your loved ones finding out? Sometimes what do we do? Do you run to the parent or your loved one or do you run away from them? You run away from them and you hide, right? So there''s basically two ways to respond when you hurt someone or when you make a mistake. So imagine that you just hurt your closest friend or you hurt your spouse. There are some people who feel so bad about it, so ashamed about it, what they do is that they hide. They try to avoid the person. They try to hide from the issue. They try to avoid the conversation.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'okay there is healthy fear and then there is unhealthy fear let me give you an example you know when you do something really bad and youre really scared of your parents or your loved ones finding out sometimes what do we do do you run to the parent or your loved one or do you run away from them you run away from them and you hide right so theres basically two ways to respond when you hurt someone or when you make a mistake so imagine that you just hurt your closest friend or you hurt your spouse there are some people who feel so bad about it so ashamed about it what they do is that they hide they try to avoid the person they try to hide from the issue they try to avoid the conversation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 26, NULL, 'They distance themselves from the person, right? Now is that a healthy way to deal with it? Does that actually solve the problem or does it make it worse? It makes it worse. And this is exactly what we do with اللَّهُ. When many of us feel like we''ve made a mistake and we''re so ashamed, instead of going towards اللَّهُ, we run away from Him. We try to hide. So we don''t want to pray anymore because, you know, we feel so ashamed. And we don''t want to talk about اللَّهُ, we don''t want to talk about religion, because it makes us feel ashamed. But then what''s a healthier way to deal with this? When you''ve hurt someone, what''s the healthiest way to fix it? To go to the person and what? Apologize. To go to the person and say, I''m sorry, I regret it. I admit it. I made a mistake. I''m going to try to do better.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'they distance themselves from the person right now is that a healthy way to deal with it does that actually solve the problem or does it make it worse it makes it worse and this is exactly what we do with الله when many of us feel like weve made a mistake and were so ashamed instead of going towards الله we run away from him we try to hide so we dont want to pray anymore because you know we feel so ashamed and we dont want to talk about الله we dont want to talk about religion because it makes us feel ashamed but then whats a healthier way to deal with this when youve hurt someone whats the healthiest way to fix it to go to the person and what apologize to go to the person and say im sorry i regret it i admit it i made a mistake im going to try to do better', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 27, NULL, 'Give me another chance. I will try to do better. And if I fail, I will try again. And I will try again. And I will try again. That is أَسْتَغْفِرْ. That is تَوْبَة. That is what we''re supposed to do. Because that is healthy fear. That is the healthy response when you make a mistake. That instead of trying to hide from اللَّهُ, instead of saying, you know, I just don''t want to do anything with religion, I want nothing to do with God, I''m not even gonna try, I''m not gonna pray because, you know, I''ve committed so many sins, you know, I just feel so ashamed to face اللَّهُ. That''s an unhealthy type of shame. But تَقْوَى is not unhealthy fear. It is not unhealthy shame.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'give me another chance i will try to do better and if i fail i will try again and i will try again and i will try again that is استغفر that is توبه that is what were supposed to do because that is healthy fear that is the healthy response when you make a mistake that instead of trying to hide from الله instead of saying you know i just dont want to do anything with religion i want nothing to do with god im not even gonna try im not gonna pray because you know ive committed so many sins you know i just feel so ashamed to face الله thats an unhealthy type of shame but تقوي is not unhealthy fear it is not unhealthy shame', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 28, NULL, 'It is healthy fear. It is the kind of healthy shame that will help you try to stay away from what displeases or what angers اللَّهُ. And when you do what angers اللَّهُ, you will rush to apologize and you will rush to repent. You will try to make things better.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'it is healthy fear it is the kind of healthy shame that will help you try to stay away from what displeases or what angers الله and when you do what angers الله you will rush to apologize and you will rush to repent you will try to make things better', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 29, NULL, 'And the reason I''m mentioning all of this is because I feel what''s happening is that we are just feeding the wrong kind of fear and shame. Because, you know, when you talk about اللَّهُ or you think about اللَّهُ like a scary policeman, I mean, you''re encouraging yourself, you''re encouraging your children and the people around you to actually avoid اللَّهُ. You''re subconsciously teaching them to run away from اللَّهُ, not to run towards Him, not to apologize, to fix it. So healthy fear will motivate us to get closer to اللَّهُ and repent. Unhealthy shame will make us run away from اللَّهُ and it''ll make us avoid Him out of shame. So in order for us to have this ability to stay firm on our إِيمَان, to have اِسْتَقَامَ on the صِرَاطَ الْمُسْتَقِيمَ, we all need to learn to develop this healthy fear of اللَّهُ, which is called تَقْوَى. Now how do we do that? How do we build healthy fear?', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'and the reason im mentioning all of this is because i feel whats happening is that we are just feeding the wrong kind of fear and shame because you know when you talk about الله or you think about الله like a scary policeman i mean youre encouraging yourself youre encouraging your children and the people around you to actually avoid الله youre subconsciously teaching them to run away from الله not to run towards him not to apologize to fix it so healthy fear will motivate us to get closer to الله and repent unhealthy shame will make us run away from الله and itll make us avoid him out of shame so in order for us to have this ability to stay firm on our ايمان to have استقام on the صراط المستقيم we all need to learn to develop this healthy fear of الله which is called تقوي now how do we do that how do we build healthy fear', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 30, NULL, 'You know what the seed of healthy fear is? What the seed of تَقْوَى is? This is interesting. Actually, let me put it this way. Let''s back up. What''s the seed to unhealthy shame? We know that a seed is the essence, right? It''s the seed that grows into a tree. But it all starts at the seed level. So if you want to address something, we should always look at the root cause, right? The seed. Now, if you look at the seed of unhealthy shame, you know what it is?', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'you know what the seed of healthy fear is what the seed of تقوي is this is interesting actually let me put it this way lets back up whats the seed to unhealthy shame we know that a seed is the essence right its the seed that grows into a tree but it all starts at the seed level so if you want to address something we should always look at the root cause right the seed now if you look at the seed of unhealthy shame you know what it is', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 31, NULL, 'It''s thinking that you are supposed to be perfect. It''s this myth of perfection that lies at the root of our problems. It is when you''re taught and you start believing that you''re actually supposed to be perfect. And if you believe that, then you will react with unhealthy shame when you make a mistake. Why? Because you feel like I was supposed to be perfect. And I''m not perfect and I''m so ashamed of myself, I''m not even going to try anymore because this is too hard. So what that does is it leads us to despair. But what was the root cause? What was the seed? That you thought that you were supposed to be perfect. Because that''s what you were taught by your family, your teachers, your culture, whatever.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'its thinking that you are supposed to be perfect its this myth of perfection that lies at the root of our problems it is when youre taught and you start believing that youre actually supposed to be perfect and if you believe that then you will react with unhealthy shame when you make a mistake why because you feel like i was supposed to be perfect and im not perfect and im so ashamed of myself im not even going to try anymore because this is too hard so what that does is it leads us to despair but what was the root cause what was the seed that you thought that you were supposed to be perfect because thats what you were taught by your family your teachers your culture whatever', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 32, NULL, 'Now let''s go to the root or the seed of healthy تَقْوَى and healthy أَسْتَغْفِرُ and healthy تَوْبَة, you know, going back to اللَّهُ. Do you know what the root is? Knowing, understanding that all human beings will make mistakes. It''s actually the opposite. It is realizing that the human being is imperfect. Understanding that we have been created as imperfect human beings. When you know that, when you understand that, then you can easily respond with repentance, because you know that you''re human and so you messed up. Okay, I messed up. I screwed up. I screwed up big time. But I''m gonna fix it. I''m gonna try and repent. I''ll try again. I''ll try harder. Even if I make the same mistake over and over and over again and I keep repenting over and over and over again, I will not give up trying to do better. That is the essence of تَوْبَة. Imperfect human beings trying to take one tiny step towards perfection. That''s what we are trying. Trying to make tomorrow better than yesterday.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'now lets go to the root or the seed of healthy تقوي and healthy استغفر and healthy توبه you know going back to الله do you know what the root is knowing understanding that all human beings will make mistakes its actually the opposite it is realizing that the human being is imperfect understanding that we have been created as imperfect human beings when you know that when you understand that then you can easily respond with repentance because you know that youre human and so you messed up okay i messed up i screwed up i screwed up big time but im gonna fix it im gonna try and repent ill try again ill try harder even if i make the same mistake over and over and over again and i keep repenting over and over and over again i will not give up trying to do better that is the essence of توبه imperfect human beings trying to take one tiny step towards perfection thats what we are trying trying to make tomorrow better than yesterday', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 33, NULL, 'That''s what we are supposed to do. The Prophet صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ, he said, all children of Adam will make mistakes, but the best of them are the ones who repent. So we have to let go of this crazy myth of perfection, because it''s the root cause of so many of our problems. It is the reason why we keep, you know, falling into despair. Because if you''re told you''re supposed to be perfect and you end up realizing that you''re not perfect, or you cannot be perfect, or it''s just too difficult to be perfect, that is frustrating, that is irritating. But when you understand that we are created with this, you know, this design of being imperfect. How can you go against the divine design? Tell me that. Just tell me that. How can you go against the divine design? How can anyone do that? اللَّهُ says that He created us imperfect. Look at the descriptions of human beings in the قُرْآن.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'thats what we are supposed to do the prophet صلي الله عليه وسلم he said all children of adam will make mistakes but the best of them are the ones who repent so we have to let go of this crazy myth of perfection because its the root cause of so many of our problems it is the reason why we keep you know falling into despair because if youre told youre supposed to be perfect and you end up realizing that youre not perfect or you cannot be perfect or its just too difficult to be perfect that is frustrating that is irritating but when you understand that we are created with this you know this design of being imperfect how can you go against the divine design tell me that just tell me that how can you go against the divine design how can anyone do that الله says that he created us imperfect look at the descriptions of human beings in the قران', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 34, NULL, 'I mean, seriously. This, like, you know, clay, pottery clay. We created man weak. We made him impatient. Indeed, man has been created anxious. Look at, I mean, these are some descriptions of human being in the قُرْآن. Weak, built from filthy liquid, hasty, impatient, anxious. So how can we go against that? It''s impossible. And when you try to go against that, you will end up hitting with despair. But then اللَّهُ, he balances out our weakness by telling us, oh my servants, my servants, my beloved servants. What type of servants? Who have transgressed completely against their soul by their constant sins?', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'i mean seriously this like you know clay pottery clay we created man weak we made him impatient indeed man has been created anxious look at i mean these are some descriptions of human being in the قران weak built from filthy liquid hasty impatient anxious so how can we go against that its impossible and when you try to go against that you will end up hitting with despair but then الله he balances out our weakness by telling us oh my servants my servants my beloved servants what type of servants who have transgressed completely against their soul by their constant sins', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 35, NULL, 'Do not despair of the mercy of اللَّهُ. You know, when we commit sins, okay, everybody get this straight, when we commit sins, when we do something that has been forbidden, we are not hurting اللَّهُ. Just be very clear about that. When we do something good, we''re not doing any favors to اللَّهُ. When we do something bad, we''re not hurting اللَّهُ. We''re only hurting ourselves, because we cannot wrong اللَّهُ, right? We cannot hurt اللَّهُ. We cannot take anything away from اللَّهُ. His kingdom is infinite. Everybody be very clear about that. And by doing anything good, we''re not doing him any kind of favors. So, you know, by doing, when اللَّهُ forbids us from something, it''s for our own benefit. It''s for the benefit of our spirituality. It''s for us to move along the صُرَاطُ الْمُسْتَقِيمِ. So by doing wrong, by committing what is forbidden, we are only hurting our own souls. So be very clear about that. You know, it''s like if you drink poison, are you hurting yourself or the doctor? The doctor is telling you don''t drink poison because the doctor understands that what you''re drinking is poison. You''re drinking it because it tastes good. It feels good. It makes you high. But if you drink that poison, are you essentially hurting yourself or the doctor? If you refuse then to take the medicine, the antidote for that poison, are you hurting yourself or are you hurting the doctor? You''re hurting yourself.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'do not despair of the mercy of الله you know when we commit sins okay everybody get this straight when we commit sins when we do something that has been forbidden we are not hurting الله just be very clear about that when we do something good were not doing any favors to الله when we do something bad were not hurting الله were only hurting ourselves because we cannot wrong الله right we cannot hurt الله we cannot take anything away from الله his kingdom is infinite everybody be very clear about that and by doing anything good were not doing him any kind of favors so you know by doing when الله forbids us from something its for our own benefit its for the benefit of our spirituality its for us to move along the صراط المستقيم so by doing wrong by committing what is forbidden we are only hurting our own souls so be very clear about that you know its like if you drink poison are you hurting yourself or the doctor the doctor is telling you dont drink poison because the doctor understands that what youre drinking is poison youre drinking it because it tastes good it feels good it makes you high but if you drink that poison are you essentially hurting yourself or the doctor if you refuse then to take the medicine the antidote for that poison are you hurting yourself or are you hurting the doctor youre hurting yourself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 36, NULL, 'So just realize that اللَّهُ is not the one that we are wronging by committing a sin. We are hurting none other than our own souls. So اللَّهُ says, tell my slaves, my beloved slaves, the ones that I have created with love and compassion, and these people who are hurting themselves by doing wrong, who are transgressing against their own selves, who are transgressing against their own souls, do not despair in the mercy of اللَّهُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'so just realize that الله is not the one that we are wronging by committing a sin we are hurting none other than our own souls so الله says tell my slaves my beloved slaves the ones that i have created with love and compassion and these people who are hurting themselves by doing wrong who are transgressing against their own selves who are transgressing against their own souls do not despair in the mercy of الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 37, NULL, 'اللَّهُ is telling us not to despair, but many of us, we despair, because we have this wrong concept about ourselves and this wrong concept about اللَّهُ. Our egos just cannot bear the fact that we are not perfect. So we think of ourselves as, you know, that I''m supposed to be perfect, I better be perfect, and if I''m not perfect, then I''m worthless. So we all have this, you know, this all or none mindset. I mean, I either have to be an angel, otherwise I am going to be the devil.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'الله is telling us not to despair but many of us we despair because we have this wrong concept about ourselves and this wrong concept about الله our egos just cannot bear the fact that we are not perfect so we think of ourselves as you know that im supposed to be perfect i better be perfect and if im not perfect then im worthless so we all have this you know this all or none mindset i mean i either have to be an angel otherwise i am going to be the devil', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 38, NULL, 'This is something I thought only I used to struggle with, but I found out that this is very common, because I used to always think like that. There''s no way I can be good, there''s no way I can be an angel, but yeah, I can be a devil, that comes easier to me, so I''m just going to go that way. In my head it was all black or white. But we have to stop that. It changed my life when I stopped thinking like that. You know, بَنِي آدَمَ is not one or the other. The children of Adam, بَنِي آدَمَ, were not angels and were not a devil.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'this is something i thought only i used to struggle with but i found out that this is very common because i used to always think like that theres no way i can be good theres no way i can be an angel but yeah i can be a devil that comes easier to me so im just going to go that way in my head it was all black or white but we have to stop that it changed my life when i stopped thinking like that you know بني ادم is not one or the other the children of adam بني ادم were not angels and were not a devil', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 39, NULL, 'A believer is actually someone who is flawed, contrary to everything that we''ve been taught so far. A believer is actually someone who is flawed but who continually strives to repent, and who tries really hard to get it right, who doesn''t give up, who constantly strives to get back up after he falls, who never gives up. That is a believer, that is a مُؤْمِن, not somebody who is flawless. This is why the Prophet said that all children of Adam will make mistakes, but the best are those who repent.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'a believer is actually someone who is flawed contrary to everything that weve been taught so far a believer is actually someone who is flawed but who continually strives to repent and who tries really hard to get it right who doesnt give up who constantly strives to get back up after he falls who never gives up that is a believer that is a مومن not somebody who is flawless this is why the prophet said that all children of adam will make mistakes but the best are those who repent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 40, NULL, 'Letting go of this false sense of perfection will allow us this ability to get back up when we fall. And you want to hear something else that''s really counterintuitive? شَيْطَان feeds off this false sense of perfection. I mean, شَيْطَان really does a number with it. He uses it as a weapon against us. You know how? When you make a mistake or when I make a mistake, he''ll come to us and he''ll say, look at you. How shameful is you? You''re gonna pray now after you did this? What kind of a terrible person are you? Do you not have any shame? Look what a hypocrite you are.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'letting go of this false sense of perfection will allow us this ability to get back up when we fall and you want to hear something else thats really counterintuitive شيطان feeds off this false sense of perfection i mean شيطان really does a number with it he uses it as a weapon against us you know how when you make a mistake or when i make a mistake hell come to us and hell say look at you how shameful is you youre gonna pray now after you did this what kind of a terrible person are you do you not have any shame look what a hypocrite you are', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 41, NULL, 'Just look at you. Now you''re gonna stand before اللَّهُ after doing this. He''s not even gonna look at you. Who would look at you? Would you look at somebody else who did that to you? Would you be merciful on somebody who did something like that to you? Of course not. So then if you wouldn''t be merciful towards somebody like that, then why do you expect اللَّهُ to be merciful to you? You don''t deserve His mercy. You don''t deserve His love. Does that sound familiar? These kind of thoughts?', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'just look at you now youre gonna stand before الله after doing this hes not even gonna look at you who would look at you would you look at somebody else who did that to you would you be merciful on somebody who did something like that to you of course not so then if you wouldnt be merciful towards somebody like that then why do you expect الله to be merciful to you you dont deserve his mercy you dont deserve his love does that sound familiar these kind of thoughts', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 42, NULL, 'This is how شَيْطَان uses this tool of false perfection against us. He''ll put us through this unhealthy shame. He''ll drag our face through this unhealthy fear and shame, and then when we''re done shaming ourselves and bashing ourselves up, then he''ll come to us from a different angle and he''ll say, do you really want to believe in a God who puts you through this mental torture? I mean, think about it. اللَّهُ created you as imperfect human being and He''s now demanding perfection of you. What kind of a horrible master is this? I mean, what kind of ridiculous religion is this? Look at the contradiction in it. Just leave it, right? Look how شَيْطَان works, right? He''s the one who put us through this unhealthy shame, then he comes at us from a different angle. How could اللَّهُ do this to you?', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'this is how شيطان uses this tool of false perfection against us hell put us through this unhealthy shame hell drag our face through this unhealthy fear and shame and then when were done shaming ourselves and bashing ourselves up then hell come to us from a different angle and hell say do you really want to believe in a god who puts you through this mental torture i mean think about it الله created you as imperfect human being and hes now demanding perfection of you what kind of a horrible master is this i mean what kind of ridiculous religion is this look at the contradiction in it just leave it right look how شيطان works right hes the one who put us through this unhealthy shame then he comes at us from a different angle how could الله do this to you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 43, NULL, 'How could He put that alcohol in your presence? Didn''t He know that you''re weak in the قُرْآن? He says that He knows everything. He says He''s closer than your jugular vein. He knew that you would drink that alcohol. Why did He put it in your presence? Whose fault is it? Why would He do that to you? It''s not your fault you drank that alcohol. It''s اللَّهُs fault, clearly. Look at that. It''s just logic. I mean, look at this religion. How stupid is that, you see? And you know what we do? We say, you know what, that makes perfect logical sense. If really اللَّهُ, you know, He should have known better, so you know what, screw religion. But if we realize that we are not perfect and that we were never created to be perfect, then when شَيْطَان comes to us in these ways, and he gives us all these brilliant ideas, we say, you know what? Thank you for that. Yes, I know I made a mistake, but my اللَّهُ is Most Merciful.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'how could he put that alcohol in your presence didnt he know that youre weak in the قران he says that he knows everything he says hes closer than your jugular vein he knew that you would drink that alcohol why did he put it in your presence whose fault is it why would he do that to you its not your fault you drank that alcohol its اللهs fault clearly look at that its just logic i mean look at this religion how stupid is that you see and you know what we do we say you know what that makes perfect logical sense if really الله you know he should have known better so you know what screw religion but if we realize that we are not perfect and that we were never created to be perfect then when شيطان comes to us in these ways and he gives us all these brilliant ideas we say you know what thank you for that yes i know i made a mistake but my الله is most merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 44, NULL, 'My اللَّهُ is not like me. My اللَّهُ, I may not forgive another person if he does something wrong to me. I may not forgive this other person if he does it again. I will definitely not forgive him if he does it again and again and again, the same thing. But I am not اللَّهُ. But my اللَّهُ is not like me. My اللَّهُ is way more merciful than I can ever be, than all of humanity combined can ever be. Because my اللَّهُ is, He is the Most Forgiving. He will forgive me if I try again, and even if I fail after that, and if I repent again, He will forgive me again. But I will keep on trying until I get it right. That''s what اللَّهُ wants, us to have hope in His mercy.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'my الله is not like me my الله i may not forgive another person if he does something wrong to me i may not forgive this other person if he does it again i will definitely not forgive him if he does it again and again and again the same thing but i am not الله but my الله is not like me my الله is way more merciful than i can ever be than all of humanity combined can ever be because my الله is he is the most forgiving he will forgive me if i try again and even if i fail after that and if i repent again he will forgive me again but i will keep on trying until i get it right thats what الله wants us to have hope in his mercy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 45, NULL, 'There''s this beautiful حَدِيثٌ of رَسُولُ اللهِ in which, it''s a حَدِيثٌ of قُدْسِيّ, in which اللَّهُ is talking to us through the Prophet, and He said, اللَّهُ says, يَا ابْنَ آدَمَ. اللَّهُ says, O son of Adam, as long as you call upon Me and ask of Me, I shall forgive you for what you have done and I will not even care about it. I won''t even care what you did. That''s how easily I will forgive you. يَا ابْنَ آدَمَ، لَوْ بَلَغَتْ ذُنُوبُكَ عَنَانَ السَّمَاءِ ثُمَّ اسْتَغْفَرْتَنِي غَفَرْتُ لَكَ. O son of Adam, were your sins so big, so many, to reach the clouds of the sky, and were you to then ask forgiveness of Me, غَفَرْتُ لَك, I would instantly forgive you.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'theres this beautiful حديث of رسول الله in which its a حديث of قدسي in which الله is talking to us through the prophet and he said الله says يا ابن ادم الله says o son of adam as long as you call upon me and ask of me i shall forgive you for what you have done and i will not even care about it i wont even care what you did thats how easily i will forgive you يا ابن ادم لو بلغت ذنوبك عنان السماء ثم استغفرتني غفرت لك o son of adam were your sins so big so many to reach the clouds of the sky and were you to then ask forgiveness of me غفرت لك i would instantly forgive you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 46, NULL, 'I don''t have time to get into the linguistics of this, but it''s so beautiful. Instantly forgive you. يَا ابْنَ آدَمَ، إِنَّكَ لَوْ أَتَيْتَنِي بِقُرَابِ الْأَرْضِ خَطَايَا ثُمَّ لَقِيتَنِي لَا تُشْرِكُ بِي شَيْئًا لَأَتَيْتُكَ بِقُرَابِهَا مَغْفِرَةً. O son of Adam, were you to come to Me with sins as great as this earth, and were you then to face Me, ascribing no partnership with Me, I would bring you forgiveness as great as your sin is. That''s who اللَّهُ is. I mean, according to this حَدِيثٌ, اللَّهُ says that if someone goes to اللَّهُ with sins that fills the area between the heavens and the earth, I mean, do you know how much that area is? I mean, think about it, the area between the earth and the sky filled with sins. Who has that many sins?', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'i dont have time to get into the linguistics of this but its so beautiful instantly forgive you يا ابن ادم انك لو اتيتني بقراب الارض خطايا ثم لقيتني لا تشرك بي شييا لاتيتك بقرابها مغفره o son of adam were you to come to me with sins as great as this earth and were you then to face me ascribing no partnership with me i would bring you forgiveness as great as your sin is thats who الله is i mean according to this حديث الله says that if someone goes to الله with sins that fills the area between the heavens and the earth i mean do you know how much that area is i mean think about it the area between the earth and the sky filled with sins who has that many sins', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 47, NULL, 'That''s a lot of sins, right? That''s a lot. And what اللَّهُ is saying, that if anyone comes to Him with sins filling the area between the heaven and the earth, and then they sincerely repent to Him, اللَّهُ will give them forgiveness which is as big or more. So that is who اللَّهُ is. He is not a policeman who is waiting to throw us in jail. He is the Most Merciful. But the problem is that we are not teaching His mercy. We''re just teaching His wrath. We''re not teaching any attachment to اللَّهُ. We''re just teaching rules. We''re not talking about the roots, we''re talking about the leaves and the branches. You have to eat like this, you have to dress like this, you have to walk like this, you have to eat, sleep and spit like this.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'thats a lot of sins right thats a lot and what الله is saying that if anyone comes to him with sins filling the area between the heaven and the earth and then they sincerely repent to him الله will give them forgiveness which is as big or more so that is who الله is he is not a policeman who is waiting to throw us in jail he is the most merciful but the problem is that we are not teaching his mercy were just teaching his wrath were not teaching any attachment to الله were just teaching rules were not talking about the roots were talking about the leaves and the branches you have to eat like this you have to dress like this you have to walk like this you have to eat sleep and spit like this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 48, NULL, 'I mean this is allowed, this is not, you know, these micronutrients, this micro-ingredient is not حَلَالٌ within the pizza. I mean, it''s kind of حَلَالٌ, but it''s not 100. I''ve actually seen a bottle of water that says حَلَالٌ certified on it. A bottle of water that says حَلَالٌ certified on it. It''s water. * ** it. I mean, this is missing the fruit, what do we call it, the forest for the trees, right? This is it. This is missing the forest for a leaf on a tree. We''re not focusing on the roots. So what ends up happening is we end up creating either this aversion and this hatred for religion, you know, completely abandoning it, or then there is this external shell, this lifeless shell of عِبَادَة that just crumbles to the ground with the first trial. I mean, don''t get me wrong, I do not belittle the importance of the outer worship.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'i mean this is allowed this is not you know these micronutrients this micro ingredient is not حلال within the pizza i mean its kind of حلال but its not 100 ive actually seen a bottle of water that says حلال certified on it a bottle of water that says حلال certified on it its water it i mean this is missing the fruit what do we call it the forest for the trees right this is it this is missing the forest for a leaf on a tree were not focusing on the roots so what ends up happening is we end up creating either this aversion and this hatred for religion you know completely abandoning it or then there is this external shell this lifeless shell of عباده that just crumbles to the ground with the first trial i mean dont get me wrong i do not belittle the importance of the outer worship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 49, NULL, 'Of course, it''s a combination of both things. That''s how I started by saying that دِين is the outer worship coupled with the inner worship. That''s why I began with that, right? It''s both آمَنُوا and عَمِلَ صَالِحَاتٍ. But what I''m saying is that you cannot do one and not the other. The problem, what I''m saying is that many of us are focusing only on the outer aspects, and if you just focus on the outer, it''s like growing a tree without roots. So when the wind comes, it''ll just knock it down. We all need to have solid roots, which is the relationship with اللَّهُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'of course its a combination of both things thats how i started by saying that دين is the outer worship coupled with the inner worship thats why i began with that right its both امنوا and عمل صالحات but what im saying is that you cannot do one and not the other the problem what im saying is that many of us are focusing only on the outer aspects and if you just focus on the outer its like growing a tree without roots so when the wind comes itll just knock it down we all need to have solid roots which is the relationship with الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 50, NULL, 'So, how do we build these roots practically? First, I told you, we remove this myth of human perfection from our minds. We have to set a different understanding, that we as human beings, we are not perfect, we were not created to be perfect, and a true believer is somebody who acknowledges that imperfection and then takes the step to better himself. So we are created as human beings to keep repenting and keep trying again and take small tiny steps every day towards that perfection, which we may or we may never achieve, which is fine.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'so how do we build these roots practically first i told you we remove this myth of human perfection from our minds we have to set a different understanding that we as human beings we are not perfect we were not created to be perfect and a true believer is somebody who acknowledges that imperfection and then takes the step to better himself so we are created as human beings to keep repenting and keep trying again and take small tiny steps every day towards that perfection which we may or we may never achieve which is fine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 51, NULL, 'But at least we''re walking in the right direction. We''re not walking in the opposite direction. I mean, can you imagine a child that is learning to walk for the first time, this child, right? He''s learning to walk and he falls down and he says, you know what? I''m just going to stop trying. This is too hard. I''m just going to sit here and that''s it. I''m never going to walk. That child will never learn how to walk. Can you imagine a person driving and the moment he makes a wrong turn, they just switch off their car. You know, they put it in park and they just say, you know what, forget it. I''m not going to drive.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'but at least were walking in the right direction were not walking in the opposite direction i mean can you imagine a child that is learning to walk for the first time this child right hes learning to walk and he falls down and he says you know what im just going to stop trying this is too hard im just going to sit here and thats it im never going to walk that child will never learn how to walk can you imagine a person driving and the moment he makes a wrong turn they just switch off their car you know they put it in park and they just say you know what forget it im not going to drive', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 52, NULL, 'This whole car is stupid. This whole route is stupid. I''m done. That''s it. I made a wrong turn. Imagine, okay, imagine your GPS saying you made a wrong turn. Sorry, right? You turn left instead of right and your GPS goes, you know what? You made a wrong turn. Just stop trying. I''m not giving you any directions. Turn off the car.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'this whole car is stupid this whole route is stupid im done thats it i made a wrong turn imagine okay imagine your gps saying you made a wrong turn sorry right you turn left instead of right and your gps goes you know what you made a wrong turn just stop trying im not giving you any directions turn off the car', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 53, NULL, 'Your trip is over. Does the GPS do that? No. What does it do? It does something completely different. What does it say? Recalculating, rerouting. What is that in Arabic? That''s تَوْبَة. That''s actually literally تَوْبَة because تَوْبَة means to return, return. تَوْبَة is our internal mechanism rerouting us back to اللَّهُ. That''s the process of أَسْتَغْفِرُ.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'your trip is over does the gps do that no what does it do it does something completely different what does it say recalculating rerouting what is that in arabic thats توبه thats actually literally توبه because توبه means to return return توبه is our internal mechanism rerouting us back to الله thats the process of استغفر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 54, NULL, 'The word تَوْبَة in Arabic literally means to turn around and return. How many times does the GPS of your car reroute you? Just once? If you take several wrong turns, what does the GPS say? You know what? You''re an idiot. It''s pointless trying to give you directions. You just keep making the same wrong turns. I''m not going to guide you anymore. You know, does the GPS do that? No, it keeps rerouting you. How many times?', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'the word توبه in arabic literally means to turn around and return how many times does the gps of your car reroute you just once if you take several wrong turns what does the gps say you know what youre an idiot its pointless trying to give you directions you just keep making the same wrong turns im not going to guide you anymore you know does the gps do that no it keeps rerouting you how many times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 55, NULL, 'Millions, billions of times if it has to. Infinite number of times. Tell me I''m wrong. A GPS, a man-made machine, is capable of doing that. You think اللَّهُ cannot do that? سُبْحَانَ اللَّهِ. So we have to change the way we think. We have to be able to get back up after we fall. We have to learn to repent and we have to learn to keep going and keep trying. That is the first thing for اِسْتَقَامَ. Now what we can do to develop this foundation', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'millions billions of times if it has to infinite number of times tell me im wrong a gps a man made machine is capable of doing that you think الله cannot do that سبحان الله so we have to change the way we think we have to be able to get back up after we fall we have to learn to repent and we have to learn to keep going and keep trying that is the first thing for استقام now what we can do to develop this foundation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 56, NULL, 'is actually very simple. It''s a simple three-ingredient recipe. The first is صَلَاةٌ. That''s like the oxygen of the heart. That is where we connect with اللَّهُ. That''s where we have that communication with اللَّهُ. That''s where we go to the person we''ve wronged and we say sorry. It''s what keeps us spiritually, psychologically and mentally connected with اللَّهُ. So no matter what you do, even if you''re doing the worst things possible, don''t ignore your prayers. Keep getting there, keep connecting. If you can do five, do three. If you can do three, do two, do one. At least try to pray once a day, and then rejoice in that prayer. Be really happy and proud of that prayer. I mean, no matter how distracted or imperfect you think it was, you know what, if you did a fast and furious kind of prayer.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'is actually very simple its a simple three ingredient recipe the first is صلاه thats like the oxygen of the heart that is where we connect with الله thats where we have that communication with الله thats where we go to the person weve wronged and we say sorry its what keeps us spiritually psychologically and mentally connected with الله so no matter what you do even if youre doing the worst things possible dont ignore your prayers keep getting there keep connecting if you can do five do three if you can do three do two do one at least try to pray once a day and then rejoice in that prayer be really happy and proud of that prayer i mean no matter how distracted or imperfect you think it was you know what if you did a fast and furious kind of prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 57, NULL, 'This is another problem we face, that again stems from this myth of perfection. If I asked you to list out for me all your sins and all your mistakes that you committed today, you''ll probably be able to give me a long list. But if I asked you to list out for me all your good deeds of the day, I bet you''re going to struggle with that.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'this is another problem we face that again stems from this myth of perfection if i asked you to list out for me all your sins and all your mistakes that you committed today youll probably be able to give me a long list but if i asked you to list out for me all your good deeds of the day i bet youre going to struggle with that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 58, NULL, 'Can I write this down? Is it good enough? Does that count? First of all, you won''t even remember half the things you did. Because we don''t appreciate the good that we do as much as we beat ourselves over the wrong that we do. You see? So from now on, every good deed that you do, from tasting that salt before, if you remember to taste that salt before your food, to wearing your سُورَةُ الْفَاتِحَة, to, I don''t know, to smiling at someone, every little thing. I want you to be grateful for that. I want you to acknowledge it. I want you to be happy about it. I want you to remember اللَّهُ when you do that. I want you to, you know, make the angels write that in your book by saying الْحَمْدُ لِلَّهِ. Keep reminding yourself of اللَّهُ after every good deed, and then feel really happy about it and really proud about it. Just for remembering to say بِسْمِ اللَّهِ before something, you know, from saying بِسْمِ اللَّهِ to saving somebody''s life and everything in between, I want you to be happy and rejoice in every good deed that you do. You did a صَلَاةٌ, you did one صَلَاةٌ, just the first, and you were Amazon shopping while you were doing that. You know what, you did نَمَاز, you did صَلَاةٌ, you stood up to remember اللَّهُ, you dropped whatever you were doing and you connected with اللَّهُ. Be happy about that. Try to do better next time, but be happy. Don''t crap on what you did. Don''t discredit the effort that you made.', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'can i write this down is it good enough does that count first of all you wont even remember half the things you did because we dont appreciate the good that we do as much as we beat ourselves over the wrong that we do you see so from now on every good deed that you do from tasting that salt before if you remember to taste that salt before your food to wearing your سوره الفاتحه to i dont know to smiling at someone every little thing i want you to be grateful for that i want you to acknowledge it i want you to be happy about it i want you to remember الله when you do that i want you to you know make the angels write that in your book by saying الحمد لله keep reminding yourself of الله after every good deed and then feel really happy about it and really proud about it just for remembering to say بسم الله before something you know from saying بسم الله to saving somebodys life and everything in between i want you to be happy and rejoice in every good deed that you do you did a صلاه you did one صلاه just the first and you were amazon shopping while you were doing that you know what you did نماز you did صلاه you stood up to remember الله you dropped whatever you were doing and you connected with الله be happy about that try to do better next time but be happy dont crap on what you did dont discredit the effort that you made', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'chapter', 'staying steadfast on the path', 'Staying Steadfast On The Path', 59, NULL, 'This is how you build relationship with اللَّهُ, slowly, small chunks, by thinking about Him, by remembering Him, consciously realizing that this is something you''re actually doing to please Him every time you do it. So be easy on yourselves. Enjoy what you''re doing. Enjoy the good that you are doing to make اللَّهُ happy. That''s the first. Second is دُعَاء, the daily, the remembrance of اللَّهُ through supplications. That''s the GPS rerouting us. And the third is the recitation and understanding of قُرْآن. I mean, you have to stay connected to it daily, even if one verse a day, I don''t care. If you do this daily and you understand it and you''re consistent with it, you will build اِسْتِقَامَة. You will build this resilience on the straight path, this الصِّرَاطَ الْمُسْتَقِيمَ. I mean, these are things that have really, really helped me in life, and I really hope it''ll do the same for you. وَآخِرُ دَعْوَانَا أَنِ الْحَمْدُ لِلَّهِ وَبِالْعَالَمِينَ، وَالصَّلَاةُ وَالسَّلَامُ وَعَلَى رَسُولِهِ سَيِّدِنَا مُحَمَّدٍ خَاتِمِ النَّبِيِّينَ وَسَيِّدِ الْمُرْسَلِينَ، وَعَلَى أَخِيهِ وَوَصِيِّهِ عَلِيِّ بْنِ أَبِي طَالِبٍ أَشْرَفِ الْوَصِيِّينَ، وَعَلَى الْأَئِمَّةِ مِنْ ذُرِّيَّتِهِمَا الطَّيِّبِينَ الطَّاهِرِينَ، وَسَلِّمْ عَلَيْهِمْ أَجْمَعِينَ، الْفَاتِحَةُ', '', NULL, NULL, NULL, NULL, 'surah al fateha staying steadfast on the path', 'this is how you build relationship with الله slowly small chunks by thinking about him by remembering him consciously realizing that this is something youre actually doing to please him every time you do it so be easy on yourselves enjoy what youre doing enjoy the good that you are doing to make الله happy thats the first second is دعاء the daily the remembrance of الله through supplications thats the gps rerouting us and the third is the recitation and understanding of قران i mean you have to stay connected to it daily even if one verse a day i dont care if you do this daily and you understand it and youre consistent with it you will build استقامه you will build this resilience on the straight path this الصراط المستقيم i mean these are things that have really really helped me in life and i really hope itll do the same for you واخر دعوانا ان الحمد لله وبالعالمين والصلاه والسلام وعلي رسوله سيدنا محمد خاتم النبيين وسيد المرسلين وعلي اخيه ووصيه علي بن ابي طالب اشرف الوصيين وعلي الايمه من ذريتهما الطيبين الطاهرين وسلم عليهم اجمعين الفاتحه', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'episode', NULL, 'What is Worship?', 0, 1, 'What is Worship? we look at the linguistic meaning of ''worship''.', '', NULL, NULL, NULL, NULL, 'surah al fateha what is worship', 'what is worship we look at the linguistic meaning of worship', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'episode', NULL, 'The Womb Of Afterlife', 0, 2, 'The Womb Of Afterlife we study the HADEES of Rasul Allah(Salallahu alayhi wa aalihee wa sallam) in which he compares the life of this world to the womb.', '', NULL, NULL, NULL, NULL, 'surah al fateha the womb of afterlife', 'the womb of afterlife we study the hadees of rasul allah salallahu alayhi wa aalihee wa sallam in which he compares the life of this world to the womb', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'episode', NULL, 'Allah - Being vs Attributes', 0, 3, 'Allah - Being vs Attributes we study the distinction of ''being'' vs ''attributes'', leading to the conversation about transcendence vs immanence. Finally, we look at the powerful word Allah uses to explain how we can understand him.', '', NULL, NULL, NULL, NULL, 'surah al fateha allah being vs attributes', 'allah being vs attributes we study the distinction of being vs attributes leading to the conversation about transcendence vs immanence finally we look at the powerful word allah uses to explain how we can understand him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'episode', NULL, 'The ISM Of Allah', 0, 4, 'The ISM Of Allah we explore the linguistic meaning of ISM', '', NULL, NULL, NULL, NULL, 'surah al fateha the ism of allah', 'the ism of allah we explore the linguistic meaning of ism', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'episode', NULL, 'In the Name Of Allah The Merciful', 0, 5, 'In the Name Of Allah The Merciful we study the phrase in its linguistic context to understand its purpose.', '', NULL, NULL, NULL, NULL, 'surah al fateha in the name of allah the merciful', 'in the name of allah the merciful we study the phrase in its linguistic context to understand its purpose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'episode', NULL, 'Linguistic Perfection Of HAMD', 0, 6, 'Linguistic Perfection Of HAMD we closely examine the perfection in the use of the word HAMD in this verse.', '', NULL, NULL, NULL, NULL, 'surah al fateha linguistic perfection of hamd', 'linguistic perfection of hamd we closely examine the perfection in the use of the word hamd in this verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('surah-al-fateha', 'episode', NULL, 'Abundant and Consistent Mercy', 0, 7, 'Abundant and Consistent Mercy we reflect on the infinite blessings of Allah(Subhanahu wa Ta''ala)', '', NULL, NULL, NULL, NULL, 'surah al fateha abundant and consistent mercy', 'abundant and consistent mercy we reflect on the infinite blessings of allah subhanahu wa taala', '');
